CREATE OR REPLACE FUNCTION public.app_apply_event_command(p_command text, p_event_id uuid, p_record jsonb, p_actor text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_command text:=nullif(btrim(coalesce(p_command,'')),''); v_record jsonb:=coalesce(p_record,'{}'::jsonb);
  v_row public.events_app_events%rowtype; v_previous jsonb; v_manager public.ops_manager_managers%rowtype;
  v_actor_manager_id uuid; v_actor text; v_reason text:=left(coalesce(nullif(btrim(p_reason),''),'Event updated from Event Input Console.'),1000);
  v_now timestamptz:=statement_timestamp();
begin
  if jsonb_typeof(v_record)<>'object' then raise exception using errcode='22023',message='event command record must be an object'; end if;
  begin v_actor_manager_id:=nullif(lower(btrim(coalesce(v_record->>'actor_manager_id',''))),'')::uuid;
  exception when others then raise exception using errcode='22023',message='authenticated manager UUID is required for event mutation'; end;
  select * into v_manager from public.ops_manager_managers m
  where m.manager_id=v_actor_manager_id and m.active=true and m.revoked_at is null and m.is_system_principal=false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
  if v_manager.manager_id is null or nullif(btrim(v_manager.display_name),'') is null then
    raise exception using errcode='42501',message='an authorized active named manager principal is required for event mutation';
  end if;
  v_actor:=left(btrim(v_manager.display_name),200);
  if v_command='create' then
    if nullif(v_record->>'start_instant_utc','') is null or nullif(v_record->>'end_instant_utc','') is null then
      raise exception using errcode='22023',message='New event requires explicit Chicago start and end instants';
    end if;
    insert into public.events_app_events(
      event_name,location_group_id,event_scope,primary_venue_id,venue_ids,display_location,coverage_location_ids,staffing_area_ids,
      source_location_text,parser_confidence,needs_review,parse_reason,source_text,source_format,manually_overridden,overridden_by,
      overridden_at,event_timezone,operation_id,event_date,end_date,start_time,end_time,start_instant_utc,end_instant_utc,attendee_count,notes,custodial_note_codes,custodial_public_notes,created_by,
      created_by_manager_id,updated_by_manager_id,updated_at
    ) values(
      v_record->>'event_name',(v_record->>'location_group_id')::uuid,v_record->>'event_scope',nullif(v_record->>'primary_venue_id','')::uuid,
      coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'venue_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),v_record->>'display_location',
      coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'coverage_location_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'staffing_area_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      nullif(v_record->>'source_location_text',''),nullif(v_record->>'parser_confidence',''),coalesce((v_record->>'needs_review')::boolean,false),
      nullif(v_record->>'parse_reason',''),nullif(v_record->>'source_text',''),nullif(v_record->>'source_format',''),
      coalesce((v_record->>'manually_overridden')::boolean,false),case when coalesce((v_record->>'manually_overridden')::boolean,false) then v_actor end,
      case when coalesce((v_record->>'manually_overridden')::boolean,false) then v_now end,
      coalesce(nullif(v_record->>'event_timezone',''),'America/Chicago'),nullif(v_record->>'operation_id','')::uuid,(v_record->>'event_date')::date,
      (v_record->>'end_date')::date,(v_record->>'start_time')::time,(v_record->>'end_time')::time,(v_record->>'start_instant_utc')::timestamptz,(v_record->>'end_instant_utc')::timestamptz,nullif(v_record->>'attendee_count','')::integer,
      nullif(v_record->>'notes',''),coalesce(array(select distinct code from jsonb_array_elements_text(coalesce(v_record->'custodial_note_codes','[]'::jsonb)) code),'{}'::text[]),coalesce(v_record->>'custodial_public_notes',''),v_actor,v_actor_manager_id,
      case when coalesce((v_record->>'manually_overridden')::boolean,false) then v_actor_manager_id end,v_now
    ) on conflict(operation_id) where operation_id is not null do update set updated_at=public.events_app_events.updated_at
    returning * into v_row;
    return to_jsonb(v_row);
  elsif v_command='update' then
    select to_jsonb(e.*) into v_previous from public.events_app_events e where e.id=p_event_id for update;
    if v_previous is null then raise exception using errcode='P0002',message='event not found'; end if;
    if (nullif(v_record->>'start_instant_utc','') is null) <> (nullif(v_record->>'end_instant_utc','') is null) then
      raise exception using errcode='22023',message='Event start and end instants must be supplied together';
    end if;
    if nullif(v_record->>'start_instant_utc','') is null and (
      nullif(v_previous->>'start_instant_utc','') is not null
      or nullif(v_previous->>'end_instant_utc','') is not null
      or (v_previous->>'event_date')::date is distinct from (v_record->>'event_date')::date
      or (v_previous->>'end_date')::date is distinct from (v_record->>'end_date')::date
      or (v_previous->>'start_time')::time is distinct from (v_record->>'start_time')::time
      or (v_previous->>'end_time')::time is distinct from (v_record->>'end_time')::time
    ) then
      raise exception using errcode='22023',message='Changed event time requires explicit Chicago start and end instants';
    end if;
    update public.events_app_events set
      event_name=v_record->>'event_name',location_group_id=(v_record->>'location_group_id')::uuid,event_scope=v_record->>'event_scope',
      primary_venue_id=nullif(v_record->>'primary_venue_id','')::uuid,
      venue_ids=coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'venue_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      display_location=v_record->>'display_location',
      coverage_location_ids=coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'coverage_location_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      staffing_area_ids=coalesce(array(select jsonb_array_elements_text(coalesce(v_record->'staffing_area_ids','[]'::jsonb)))::uuid[],'{}'::uuid[]),
      source_location_text=nullif(v_record->>'source_location_text',''),parser_confidence=nullif(v_record->>'parser_confidence',''),
      needs_review=coalesce((v_record->>'needs_review')::boolean,false),parse_reason=nullif(v_record->>'parse_reason',''),
      source_text=nullif(v_record->>'source_text',''),source_format=nullif(v_record->>'source_format',''),manually_overridden=true,
      overridden_by=v_actor,overridden_at=v_now,updated_by_manager_id=v_actor_manager_id,
      event_timezone=coalesce(nullif(v_record->>'event_timezone',''),'America/Chicago'),event_date=(v_record->>'event_date')::date,
      end_date=(v_record->>'end_date')::date,start_time=(v_record->>'start_time')::time,end_time=(v_record->>'end_time')::time,start_instant_utc=(v_record->>'start_instant_utc')::timestamptz,end_instant_utc=(v_record->>'end_instant_utc')::timestamptz,
      attendee_count=nullif(v_record->>'attendee_count','')::integer,notes=nullif(v_record->>'notes',''),custodial_note_codes=coalesce(array(select distinct code from jsonb_array_elements_text(coalesce(v_record->'custodial_note_codes','[]'::jsonb)) code),'{}'::text[]),custodial_public_notes=coalesce(v_record->>'custodial_public_notes',''),revision=coalesce(revision,1)+1,updated_at=v_now
    where id=p_event_id returning * into v_row;
    insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_row.id,'update',v_actor,v_actor_manager_id,v_reason,v_previous,to_jsonb(v_row),v_now);
    return to_jsonb(v_row);
  elsif v_command='cancel' then
    raise exception using errcode='22023',message='event cancellation requires expected revision and operation id';
    select to_jsonb(e.*) into v_previous from public.events_app_events e where e.id=p_event_id for update;
    if v_previous is null then raise exception using errcode='P0002',message='event not found'; end if;
    update public.events_app_events set status='CANCELLED',cancelled_at=coalesce(cancelled_at,v_now),cancelled_by=v_actor,
      cancelled_by_manager_id=v_actor_manager_id,cancellation_reason=v_reason,overridden_by=v_actor,overridden_at=v_now,
      updated_by_manager_id=v_actor_manager_id,revision=coalesce(revision,1)+1,updated_at=v_now
    where id=p_event_id returning * into v_row;
    insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_row.id,'cancel',v_actor,v_actor_manager_id,v_reason,v_previous,to_jsonb(v_row),v_now);
    return to_jsonb(v_row);
  end if;
  raise exception using errcode='22023',message='unsupported bounded event command';
end
$function$

CREATE OR REPLACE FUNCTION public.app_event_manager_digest_candidate(p_event_id uuid, p_at timestamp with time zone)
 RETURNS TABLE(event_revision integer, occurrence_starts_at timestamp with time zone, event_name text, event_date date, display_location text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_event public.events_app_events%rowtype;v_place jsonb;
begin
  if p_event_id is null or p_at is null or not isfinite(p_at) then return; end if;
  select * into v_event from public.events_app_events where id=p_event_id;
  if v_event.id is null or v_event.status<>'SCHEDULED'
    or coalesce(v_event.needs_review,false) or v_event.event_scope='UNKNOWN'
    or v_event.cancelled_at is not null or v_event.archived_at is not null
    or v_event.start_instant_utc is null or v_event.end_instant_utc is null
    or v_event.start_instant_utc<=p_at then return;end if;
  v_place:=public.app_event_place_authority(to_jsonb(v_event),p_at);
  if (v_place->>'admissible')::boolean is not true then return;end if;
  return query select v_event.revision,v_event.start_instant_utc,v_event.event_name,
    v_event.event_date,coalesce(nullif(v_place->>'primary_display_name',''),v_event.display_location);
end $function$

CREATE OR REPLACE FUNCTION public.app_event_manager_digest_is_current(p_payload jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_id uuid;v_revision integer;v_start timestamptz;
begin
  if p_payload is null or jsonb_typeof(p_payload)<>'object' or p_at is null then return false;end if;
  if coalesce(p_payload->>'next_event_id','') !~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or coalesce(p_payload->>'next_event_revision','') !~ '^[1-9][0-9]{0,8}$'
    or coalesce(p_payload->>'next_event_starts_at','')=''
    or not (p_payload ? 'next_event_display_location') then return false;end if;
  begin
    v_id:=(p_payload->>'next_event_id')::uuid;
    v_revision:=(p_payload->>'next_event_revision')::integer;
    v_start:=(p_payload->>'next_event_starts_at')::timestamptz;
  exception when others then return false;end;
  return exists(select 1 from public.app_event_manager_digest_candidate(v_id,p_at) candidate
    where candidate.event_revision=v_revision and candidate.occurrence_starts_at=v_start
      and candidate.display_location is not distinct from
        nullif(p_payload->>'next_event_display_location',''));
end $function$

CREATE OR REPLACE FUNCTION public.app_event_place_admission_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_authority jsonb;
begin
  if new.status='SCHEDULED' and coalesce(new.needs_review,false)=false then
    v_authority:=public.app_event_place_authority(to_jsonb(new),clock_timestamp());
    if (v_authority->>'admissible')::boolean is not true then
      raise exception using errcode='40901',message='Event venue mapping is inactive or requires manager review; refresh the venue before scheduling.',
        detail=v_authority::text;
    end if;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.app_event_place_authority(p_record jsonb, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_overlay jsonb;
  v_row jsonb;
  v_id text;
  v_primary text:=nullif(p_record->>'primary_venue_id','');
  v_count integer:=0;
  v_primary_display text;
  v_primary_status text;
begin
  if p_record is null or jsonb_typeof(p_record)<>'object' or p_at is null or not isfinite(p_at) then
    raise exception using errcode='22023',message='Event record and finite overlay clock required';
  end if;
  v_overlay:=public.custodial_place_event_venue_overlay(p_at);
  if jsonb_typeof(v_overlay->'venues')<>'array' then
    raise exception using errcode='55000',message='Event venue overlay unavailable';
  end if;
  for v_id in
    select distinct selected.id from (
      select v_primary as id
      union all
      select jsonb_array_elements_text(case when jsonb_typeof(p_record->'venue_ids')='array'
        then p_record->'venue_ids' else '[]'::jsonb end)
    ) selected where selected.id is not null and selected.id<>''
  loop
    v_count:=v_count+1;
    if v_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      return jsonb_build_object('admissible',false,'review_reason','invalid_legacy_venue_id','venue_id',v_id);
    end if;
    select item.value into v_row from jsonb_array_elements(v_overlay->'venues') item(value)
      where item.value->>'venue_id'=v_id;
    if v_row is null then
      return jsonb_build_object('admissible',false,'review_reason','legacy_venue_missing','venue_id',v_id);
    end if;
    if v_row->>'mapping_status' not in ('MAPPED','UNMAPPED')
      or coalesce((v_row->>'event_eligible')::boolean,false) is not true then
      return jsonb_build_object('admissible',false,'review_reason',coalesce(v_row->>'review_reason','legacy_venue_ineligible'),
        'mapping_status',v_row->>'mapping_status','venue_id',v_id,'source_drift',v_row->'source_drift');
    end if;
    if v_id=v_primary then
      v_primary_status:=v_row->>'mapping_status';
      if v_primary_status='MAPPED' then v_primary_display:=v_row->>'display_name'; end if;
    end if;
    v_row:=null;
  end loop;
  -- Older scheduled rows can be group-only. No bridge assignment is invented.
  if v_count=0 and coalesce(p_record->>'event_scope','UNKNOWN') not in ('ZOO_WIDE','OFFSITE','SINGLE_VENUE','MULTI_VENUE') then
    return jsonb_build_object('admissible',false,'review_reason','unresolved_event_scope');
  end if;
  return jsonb_build_object('admissible',true,'mapping_status',coalesce(v_primary_status,'LEGACY_UNMAPPED'),
    'primary_display_name',v_primary_display,'venue_count',v_count,
    'capability_authority',case when v_primary_status='MAPPED' then 'CANONICAL_EVENT_ONLY' else 'LEGACY_UNMAPPED' end);
end $function$

CREATE OR REPLACE FUNCTION public.app_event_supersession_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op='INSERT' then
    if new.status='SUPERSEDED' then raise exception using errcode='42501',message='new event cannot be born superseded'; end if;
    return new;
  end if;
  if tg_op='DELETE' then
    if old.status='SUPERSEDED' then raise exception using errcode='42501',message='superseded event history cannot be deleted'; end if;
    return old;
  end if;
  if old.status='SUPERSEDED' and new is distinct from old then
    raise exception using errcode='42501',message='superseded event history is immutable';
  end if;
  if old.status<>'SUPERSEDED' and new.status='SUPERSEDED'
    and current_setting('app.event_supersession_command',true) is distinct from 'on' then
    raise exception using errcode='42501',message='named manager supersession command is required';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.app_replace_event_authoritative(p_event_id uuid, p_expected_revision integer, p_record jsonb, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_old public.events_app_events%rowtype;
  v_new public.events_app_events%rowtype;
  v_previous jsonb;
  v_operation_id uuid;
  v_created jsonb;
  v_request_digest text;
  v_now timestamptz:=statement_timestamp();
begin
  select * into v_manager from public.ops_manager_managers m where m.manager_id=p_manager_id
    and m.active=true and m.revoked_at is null and m.is_system_principal=false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
  if v_manager.manager_id is null or nullif(btrim(v_manager.display_name),'') is null then
    raise exception using errcode='42501',message='active named manager authority is required for event replacement';
  end if;
  if p_event_id is null or p_expected_revision is null or p_expected_revision<1
    or jsonb_typeof(p_record) is distinct from 'object' then
    raise exception using errcode='22023',message='event id, expected revision and normalized replacement are required';
  end if;
  begin v_operation_id:=(p_record->>'operation_id')::uuid;
  exception when others then raise exception using errcode='22023',message='replacement operation id must be a UUID'; end;
  if v_operation_id is null or p_record->>'status'<>'SCHEDULED'
    or coalesce((p_record->>'needs_review')::boolean,true)
    or nullif(p_record->>'start_instant_utc','') is null
    or nullif(p_record->>'end_instant_utc','') is null then
    raise exception using errcode='22023',message='resolved scheduled replacement and explicit Chicago instants are required';
  end if;
  v_request_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
    'source_event_id',p_event_id,'expected_revision',p_expected_revision,
    'manager_id',p_manager_id,'record',p_record));
  select * into v_old from public.events_app_events e where e.id=p_event_id for update;
  if not found then raise exception using errcode='P0002',message='source event not found'; end if;
  if v_old.status='SUPERSEDED' then
    select * into v_new from public.events_app_events e where e.id=v_old.superseded_by_event_id;
    if v_new.operation_id=v_operation_id and v_old.supersession_request_digest=v_request_digest then
      return jsonb_build_object('old_event',to_jsonb(v_old),'replacement_event',to_jsonb(v_new),'replayed',true);
    end if;
    raise exception using errcode='40901',message='Event was already superseded by another replacement. Refresh before saving.';
  end if;
  if v_old.status<>'SCHEDULED' or coalesce(v_old.needs_review,false) then
    raise exception using errcode='40901',message='Only an active resolved event can be replaced. Refresh before saving.';
  end if;
  if v_old.revision is distinct from p_expected_revision then
    raise exception using errcode='40901',message='Event changed since this preview. Refresh and review before saving.';
  end if;
  if exists(select 1 from public.events_app_events e where e.operation_id=v_operation_id) then
    raise exception using errcode='40901',message='Replacement operation already belongs to another event.';
  end if;
  v_previous:=to_jsonb(v_old);
  v_created:=public.app_apply_event_command('create',null,
    p_record||jsonb_build_object('actor_manager_id',p_manager_id,'manually_overridden',true),null,
    'Manager-confirmed replacement event.');
  select * into v_new from public.events_app_events e where e.id=(v_created->>'id')::uuid;
  if v_new.id is null or v_new.status<>'SCHEDULED' or v_new.operation_id<>v_operation_id then
    raise exception using errcode='22023',message='replacement event did not persist as scheduled';
  end if;
  perform set_config('app.event_supersession_command','on',true);
  update public.events_app_events e set status='SUPERSEDED',superseded_by_event_id=v_new.id,
    superseded_at=v_now,superseded_by_manager_id=p_manager_id,supersession_request_digest=v_request_digest,
    revision=e.revision+1,updated_at=v_now
    where e.id=v_old.id returning * into v_old;
  insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_old.id,'supersede',v_manager.display_name,p_manager_id,
      'Manager-confirmed replacement; original event retained.',v_previous,to_jsonb(v_old),v_now);
  insert into public.events_app_event_history(event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(v_new.id,'create_replacement',v_manager.display_name,p_manager_id,
      'Replacement for event '||v_old.id::text,null,to_jsonb(v_new),v_now);
  return jsonb_build_object('old_event',to_jsonb(v_old),'replacement_event',to_jsonb(v_new),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.app_transition_event_cancellation(p_event_id uuid, p_action text, p_expected_revision integer, p_operation_id uuid, p_manager_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_old public.events_app_events%rowtype;
  v_new public.events_app_events%rowtype;
  v_receipt public.events_app_transition_receipts%rowtype;
  v_previous jsonb;
  v_history_id uuid;
  v_reason text:=left(coalesce(nullif(btrim(p_reason),''),
    case when p_action='restore' then 'Manager-confirmed ordinary cancellation recovery.'
      else 'Manager-confirmed event cancellation.' end),1000);
  v_digest text;
  v_now timestamptz;
begin
  if p_event_id is null or p_action not in ('cancel','restore') or p_action is null
    or p_expected_revision is null or p_expected_revision<1
    or p_operation_id is null or p_manager_id is null then
    raise exception using errcode='22023',message='event, action, revision, operation and named manager are required';
  end if;
  select * into v_manager from public.ops_manager_managers m
    where m.manager_id=p_manager_id and m.active=true and m.revoked_at is null
      and m.is_system_principal=false
      and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]
    for share;
  if v_manager.manager_id is null or nullif(btrim(v_manager.display_name),'') is null then
    raise exception using errcode='42501',message='active named manager authority is required for event transition';
  end if;
  v_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
    'event_id',p_event_id,'action',p_action,'expected_revision',p_expected_revision,
    'manager_id',p_manager_id,'reason',v_reason));
  select * into v_old from public.events_app_events e where e.id=p_event_id for update;
  if v_old.id is null then raise exception using errcode='P0002',message='event not found'; end if;
  v_now:=clock_timestamp();
  select * into v_receipt from public.events_app_transition_receipts r
    where r.operation_id=p_operation_id;
  if v_receipt.operation_id is not null then
    if v_receipt.event_id=p_event_id and v_receipt.action=p_action
      and v_receipt.expected_revision=p_expected_revision
      and v_receipt.actor_manager_id=p_manager_id and v_receipt.request_digest=v_digest then
      return jsonb_build_object('event',v_receipt.result_record,'history_id',v_receipt.history_id,
        'operation_id',p_operation_id,'action',p_action,'replayed',true,
        'reminders','current eligibility revalidation pending');
    end if;
    raise exception using errcode='40901',message='Event operation id belongs to a different request.';
  end if;
  if v_old.revision is distinct from p_expected_revision then
    raise exception using errcode='40901',message='Event changed since this preview. Refresh and review before saving.';
  end if;
  if p_action='cancel' then
    if v_old.status not in ('SCHEDULED','NEEDS_REVIEW') or v_old.superseded_by_event_id is not null then
      raise exception using errcode='40901',message='Only a current scheduled or review event can be cancelled.';
    end if;
  else
    if v_old.status<>'CANCELLED' or v_old.cancelled_from_status is distinct from 'SCHEDULED'
      or v_old.superseded_by_event_id is not null or v_old.archived_at is not null
      or coalesce(v_old.needs_review,false) or v_old.event_scope='UNKNOWN' then
      raise exception using errcode='40901',message='Only a resolved ordinary cancellation can be restored.';
    end if;
    if v_old.end_instant_utc is null or v_old.end_instant_utc<=v_now then
      raise exception using errcode='40901',message='Event occurrence is past or lacks a confirmed Chicago instant; correct it before restoring.';
    end if;
    if v_old.event_scope='ZOO_WIDE' then
      if not exists(select 1 from public.event_venues ev
          where ev.id=v_old.primary_venue_id and ev.active and ev.event_scope='ZOO_WIDE') then
        raise exception using errcode='40901',message='Zoo-wide venue is no longer eligible.';
      end if;
    elsif v_old.event_scope in ('SINGLE_VENUE','MULTI_VENUE') then
      if v_old.primary_venue_id is null or not(v_old.primary_venue_id=any(v_old.venue_ids))
        or (v_old.event_scope='MULTI_VENUE' and cardinality(v_old.venue_ids)<2)
        or exists(select 1 from unnest(v_old.venue_ids) selected(id)
          left join public.event_venues ev on ev.id=selected.id
          where ev.id is null or not ev.active or not ev.eligible_event_venue
            or ev.event_scope='ZOO_WIDE') then
        raise exception using errcode='40901',message='Event venue is no longer eligible; manager correction is required.';
      end if;
    elsif v_old.event_scope<>'OFFSITE' then
      raise exception using errcode='40901',message='Event scope is not restorable.';
    end if;
  end if;
  v_previous:=to_jsonb(v_old);
  perform set_config('app.event_cancellation_transition','on',true);
  if p_action='cancel' then
    update public.events_app_events e set status='CANCELLED',cancelled_from_status=v_old.status,
      cancelled_at=v_now,cancelled_by=v_manager.display_name,cancelled_by_manager_id=p_manager_id,
      cancellation_reason=v_reason,overridden_by=v_manager.display_name,overridden_at=v_now,
      updated_by_manager_id=p_manager_id,revision=e.revision+1,updated_at=v_now
      where e.id=p_event_id returning * into v_new;
  else
    update public.events_app_events e set status='SCHEDULED',cancelled_from_status=null,
      cancelled_at=null,cancelled_by=null,cancelled_by_manager_id=null,cancellation_reason=null,
      overridden_by=v_manager.display_name,overridden_at=v_now,
      updated_by_manager_id=p_manager_id,revision=e.revision+1,updated_at=v_now
      where e.id=p_event_id returning * into v_new;
  end if;
  insert into public.events_app_event_history
    (event_id,action,actor,actor_manager_id,reason,previous_record,new_record,created_at)
    values(p_event_id,p_action,v_manager.display_name,p_manager_id,v_reason,v_previous,to_jsonb(v_new),v_now)
    returning id into v_history_id;
  insert into public.events_app_transition_receipts
    (operation_id,event_id,action,expected_revision,actor_manager_id,request_digest,history_id,result_record,created_at)
    values(p_operation_id,p_event_id,p_action,p_expected_revision,p_manager_id,v_digest,v_history_id,to_jsonb(v_new),v_now);
  return jsonb_build_object('event',to_jsonb(v_new),'history_id',v_history_id,
    'operation_id',p_operation_id,'action',p_action,'replayed',false,
    'reminders','current eligibility revalidation pending');
end $function$

CREATE OR REPLACE FUNCTION public.claim_event_notification(p_event_id uuid, p_employee_id uuid, p_msg_user_id uuid, p_notification_kind text, p_scheduled_for_local text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_kind text := nullif(btrim(coalesce(p_notification_kind, '')), '');
  v_scheduled timestamp;
  v_existing public.events_app_notification_log%rowtype;
begin
  if p_event_id is null or p_employee_id is null or p_msg_user_id is null then
    raise exception 'event_id, employee_id, and msg_user_id are required';
  end if;
  if v_kind is null or length(v_kind) > 120 then
    raise exception 'notification_kind is required and must be at most 120 characters';
  end if;
  begin
    v_scheduled := p_scheduled_for_local::timestamp;
  exception when others then
    raise exception 'scheduled_for_local is invalid';
  end;

  perform pg_advisory_xact_lock(hashtextextended('event-reminder:' || p_event_id::text || ':' || p_employee_id::text, 0));

  select log.* into v_existing
  from public.events_app_notification_log log
  where log.event_id = p_event_id
    and log.employee_id = p_employee_id
    and log.status in ('sent', 'sending')
    and (log.status = 'sent' or log.updated_at > now() - interval '10 minutes')
  order by case when log.status = 'sent' then 0 else 1 end, log.updated_at desc
  limit 1;

  if found then
    return jsonb_build_object(
      'claimed', false,
      'reason', case when v_existing.status = 'sent' then 'event_already_notified' else 'event_notification_in_flight' end,
      'notification_kind', v_existing.notification_kind,
      'response_message_id', v_existing.response_message_id,
      'status', v_existing.status
    );
  end if;

  insert into public.events_app_notification_log(
    event_id, employee_id, msg_user_id, notification_kind, scheduled_for_local,
    sent_at, status, notes, created_at, updated_at
  ) values (
    p_event_id, p_employee_id, p_msg_user_id, v_kind, v_scheduled,
    now(), 'sending', 'Claimed before message delivery', now(), now()
  )
  on conflict (event_id, employee_id, notification_kind) do update set
    msg_user_id = excluded.msg_user_id,
    scheduled_for_local = excluded.scheduled_for_local,
    sent_at = now(),
    status = 'sending',
    response_message_id = null,
    notes = 'Retry claimed before message delivery',
    updated_at = now()
  where public.events_app_notification_log.status = 'error'
     or (public.events_app_notification_log.status = 'sending'
         and public.events_app_notification_log.updated_at <= now() - interval '10 minutes')
  returning * into v_existing;

  if not found then
    select log.* into v_existing
    from public.events_app_notification_log log
    where log.event_id = p_event_id
      and log.employee_id = p_employee_id
      and log.notification_kind = v_kind
    limit 1;
    return jsonb_build_object(
      'claimed', false,
      'reason', 'notification_already_claimed',
      'response_message_id', v_existing.response_message_id,
      'status', v_existing.status
    );
  end if;

  return jsonb_build_object(
    'claimed', true,
    'reason', 'claim_created',
    'notification_kind', v_kind,
    'log_id', v_existing.id,
    'status', v_existing.status
  );
end
$function$

CREATE OR REPLACE FUNCTION public.cleaning_inspections_set_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_session record;
  v_completion_at timestamptz;
  v_inspector_name text;
begin
  if tg_op = 'UPDATE' then
    if row(new.operation_id,new.session_id,new.request_fingerprint,new.inspector_manager_id,
           new.inspected_at,new.created_at,new.location_id,new.employee_id,new.inspector_name_snapshot,
           new.employee_name_snapshot,new.location_code_snapshot,new.location_name_snapshot,
           new.session_started_at,new.session_ended_at,new.session_duration_minutes)
       is distinct from
       row(old.operation_id,old.session_id,old.request_fingerprint,old.inspector_manager_id,
           old.inspected_at,old.created_at,old.location_id,old.employee_id,old.inspector_name_snapshot,
           old.employee_name_snapshot,old.location_code_snapshot,old.location_name_snapshot,
           old.session_started_at,old.session_ended_at,old.session_duration_minutes) then
      raise exception using errcode='23514', message='Inspection actor, cleaning identity, and snapshots are immutable';
    end if;
    new.updated_at := clock_timestamp();
    return new;
  end if;

  new.inspected_at := statement_timestamp();
  new.created_at := new.inspected_at;
  select
    s.location_id,s.employee_id,s.started_at,s.ended_at,s.duration_minutes,s.status,
    (select max(cr.submitted_at) from public.completion_responses cr where cr.session_id=s.id) completion_submitted_at,
    s.location_code_snapshot,s.location_name_snapshot,s.employee_name_snapshot
  into v_session
  from public.sessions s
  where s.id = new.session_id;
  if not found then
    raise exception using errcode='P0002', message='Cleaning session was not found';
  end if;
  if v_session.status not in ('pending_submit','closed') then
    raise exception using errcode='23514', message='Only a finished cleaning session can be inspected';
  end if;
  v_completion_at := coalesce(v_session.ended_at,v_session.completion_submitted_at);
  if v_completion_at is null then
    raise exception using errcode='23514', message='Finished cleaning session has no completion timestamp';
  end if;
  if new.inspected_at < v_completion_at or new.inspected_at > v_completion_at + interval '24 hours' then
    raise exception using errcode='23514', message='Inspection must be recorded within 24 hours after cleaning completion';
  end if;

  new.location_id := v_session.location_id;
  new.employee_id := v_session.employee_id;
  new.employee_name_snapshot := v_session.employee_name_snapshot;
  new.location_code_snapshot := v_session.location_code_snapshot;
  new.location_name_snapshot := v_session.location_name_snapshot;
  new.session_started_at := v_session.started_at;
  new.session_ended_at := v_completion_at;
  new.session_duration_minutes := coalesce(v_session.duration_minutes,
    greatest(0,ceil(extract(epoch from (v_completion_at-v_session.started_at))/60.0)::integer));

  if new.inspector_manager_id is not null then
    select m.display_name into v_inspector_name
    from public.ops_manager_managers m
    where m.manager_id=new.inspector_manager_id
      and m.active=true and m.revoked_at is null and m.is_system_principal=false;
    if not found then
      raise exception using errcode='23503', message='Active inspector manager was not found';
    end if;
    new.inspector_name_snapshot := v_inspector_name;
  else
    new.inspector_name_snapshot := coalesce(nullif(btrim(new.inspector_name_snapshot),''),'Custodial Manager');
  end if;
  new.updated_at := clock_timestamp();
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.create_maintenance_tickets_from_response(p_completion_response_id uuid, p_session_id uuid, p_location_id uuid, p_reported_by_employee_id uuid, p_device_id uuid, p_reported_at timestamp with time zone, p_response_json jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_issue_array jsonb;
  v_item jsonb;
  v_issue_summary text;
  v_issue_category text;
  v_fixture_type text;
  v_fixture_identifier text;
  v_out_of_order boolean;
  v_location_code text;
  v_location_name text;
  v_reporter_name text;
  v_count integer := 0;
  v_top_level_out_of_order boolean := (
    lower(coalesce(
      p_response_json->>'out_of_order',
      p_response_json->>'outOfOrder',
      p_response_json->>'place_out_of_order',
      p_response_json->>'placeOutOfOrder',
      p_response_json->>'out_of_order_signed',
      p_response_json->>'outOfOrderSigned',
      'false'
    )) in ('true','t','1','yes','y','on')
  );
  v_top_level_fixture_identifier text := coalesce(
    p_response_json->>'fixture_identifier',
    p_response_json->>'fixtureIdentifier',
    p_response_json->>'out_of_order_details',
    p_response_json->>'outOfOrderDetails',
    p_response_json->>'stall',
    p_response_json->>'stall_number',
    p_response_json->>'stallNumber',
    p_response_json->>'urinal',
    p_response_json->>'urinal_number',
    p_response_json->>'urinalNumber'
  );
  v_explicit_issue_notes text := coalesce(
    p_response_json->>'maintenance_notes',
    p_response_json->>'maintenanceNotes',
    p_response_json->>'issue_notes',
    p_response_json->>'issueNotes'
  );
  v_top_level_notes text := coalesce(
    v_explicit_issue_notes,
    p_response_json->>'notes',
    p_response_json->>'note'
  );
  v_has_explicit_issue boolean := (
    lower(coalesce(
      p_response_json->>'has_maintenance_issue',
      p_response_json->>'hasMaintenanceIssue',
      p_response_json->>'maintenance_issue',
      p_response_json->>'maintenanceIssue',
      'false'
    )) in ('true','t','1','yes','y','on')
  );
begin
  select l.location_code, l.location_name
    into v_location_code, v_location_name
  from public.locations l
  where l.id = p_location_id
  limit 1;

  select e.display_name
    into v_reporter_name
  from public.employees e
  where e.id = p_reported_by_employee_id
  limit 1;

  delete from public.maintenance_tickets mt
  where mt.completion_response_id = p_completion_response_id
    and mt.issue_source = 'completion_form'
    and mt.status = 'open';

  v_issue_array := case
    when jsonb_typeof(p_response_json->'maintenance_issues') = 'array' then p_response_json->'maintenance_issues'
    when jsonb_typeof(p_response_json->'maintenanceIssues') = 'array' then p_response_json->'maintenanceIssues'
    when jsonb_typeof(p_response_json->'maintenance_issue_checks') = 'array' then p_response_json->'maintenance_issue_checks'
    when jsonb_typeof(p_response_json->'maintenanceIssueChecks') = 'array' then p_response_json->'maintenanceIssueChecks'
    when jsonb_typeof(p_response_json->'checked_maintenance_issues') = 'array' then p_response_json->'checked_maintenance_issues'
    when jsonb_typeof(p_response_json->'checkedMaintenanceIssues') = 'array' then p_response_json->'checkedMaintenanceIssues'
    when jsonb_typeof(p_response_json->'maintenance_issues_found') = 'array' then p_response_json->'maintenance_issues_found'
    when jsonb_typeof(p_response_json->'maintenanceIssuesFound') = 'array' then p_response_json->'maintenanceIssuesFound'
    when jsonb_typeof(p_response_json->'maintenance_issue_found') = 'array' then p_response_json->'maintenance_issue_found'
    when jsonb_typeof(p_response_json->'issues') = 'array' then p_response_json->'issues'
    when jsonb_typeof(p_response_json->'maintenance') = 'array' then p_response_json->'maintenance'
    else null
  end;

  if v_issue_array is null
     and (v_has_explicit_issue or v_explicit_issue_notes is not null or v_top_level_out_of_order) then
    v_issue_array := jsonb_build_array(
      jsonb_build_object(
        'label', coalesce(v_explicit_issue_notes, v_top_level_notes, 'Maintenance issue reported'),
        'fixture_identifier', v_top_level_fixture_identifier,
        'out_of_order', v_top_level_out_of_order,
        'raw_response', p_response_json
      )
    );
  end if;

  if v_issue_array is null or jsonb_array_length(v_issue_array) = 0 then
    return 0;
  end if;

  for v_item in select value from jsonb_array_elements(v_issue_array)
  loop
    if jsonb_typeof(v_item) = 'string' then
      v_issue_summary := trim(both '"' from v_item::text);
      if lower(v_issue_summary) in ('other maintenance issue found', 'other') and v_top_level_notes is not null then
        v_issue_summary := 'Other maintenance issue: ' || v_top_level_notes;
      end if;
      v_issue_category := trim(both '"' from v_item::text);
      v_fixture_type := case
        when lower(v_issue_summary) like '%toilet%' then 'toilet'
        when lower(v_issue_summary) like '%urinal%' then 'urinal'
        else null
      end;
      v_fixture_identifier := v_top_level_fixture_identifier;
      v_out_of_order := v_top_level_out_of_order;
    else
      v_issue_summary := coalesce(
        v_item->>'label', v_item->>'issue', v_item->>'issue_label',
        v_item->>'issueLabel', v_item->>'name', v_item->>'value',
        v_item->>'description', v_item->>'maintenance_issue',
        v_item->>'maintenanceIssue', 'Maintenance issue reported'
      );
      if lower(v_issue_summary) in ('other maintenance issue found', 'other') and v_top_level_notes is not null then
        v_issue_summary := 'Other maintenance issue: ' || v_top_level_notes;
      end if;
      v_issue_category := coalesce(
        v_item->>'category', v_item->>'issue_category',
        v_item->>'issueCategory', v_issue_summary
      );
      v_fixture_type := coalesce(
        v_item->>'fixture_type', v_item->>'fixtureType',
        case
          when lower(v_issue_summary) like '%toilet%' then 'toilet'
          when lower(v_issue_summary) like '%urinal%' then 'urinal'
          else null
        end
      );
      v_fixture_identifier := coalesce(
        v_item->>'fixture_identifier', v_item->>'fixtureIdentifier',
        v_item->>'stall', v_item->>'stall_number', v_item->>'stallNumber',
        v_item->>'urinal', v_item->>'urinal_number', v_item->>'urinalNumber',
        v_top_level_fixture_identifier
      );
      v_out_of_order := (
        lower(coalesce(
          v_item->>'out_of_order', v_item->>'outOfOrder',
          v_item->>'place_out_of_order', v_item->>'placeOutOfOrder',
          v_item->>'out_of_order_signed', v_item->>'outOfOrderSigned',
          case when v_top_level_out_of_order then 'true' else 'false' end
        )) in ('true','t','1','yes','y','on')
      );
    end if;

    insert into public.maintenance_tickets (
      completion_response_id, session_id, location_id,
      reported_by_employee_id, device_id, issue_source, status,
      issue_summary, issue_category, fixture_type, fixture_identifier,
      out_of_order, issue_payload, location_code_snapshot,
      location_name_snapshot, reporter_name_snapshot, reported_at
    ) values (
      p_completion_response_id, p_session_id, p_location_id,
      p_reported_by_employee_id, p_device_id, 'completion_form', 'open',
      left(coalesce(v_issue_summary, 'Maintenance issue reported'), 500),
      left(v_issue_category, 200), left(v_fixture_type, 100),
      left(v_fixture_identifier, 100), coalesce(v_out_of_order, false),
      jsonb_build_object(
        'raw_item', v_item,
        'top_level_note', v_top_level_notes,
        'top_level_fixture_identifier', v_top_level_fixture_identifier,
        'top_level_out_of_order', v_top_level_out_of_order
      ),
      v_location_code, v_location_name, v_reporter_name,
      coalesce(p_reported_at, now())
    );

    v_count := v_count + 1;
  end loop;

  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_activation_assert_consume(p_operation uuid, p_device uuid, p_code_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype; d public.devices%rowtype; c public.device_auth_enrollment_codes%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 select * into strict d from public.devices where id=p_device for update;
 select * into a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if a.operation_id is null then raise exception 'assigned activation operation not found'; end if;
 if a.device_id is distinct from p_device or a.canonical_device_id is distinct from d.device_id or d.active is not true
  or a.expected_employee_id is distinct from d.assigned_employee_id or a.expected_assignment_epoch is distinct from d.assignment_epoch
  or a.state not in ('prepared','delivered','delivery_unknown') or a.expires_at<=now() or a.claimant_credential_id is null
  then raise exception 'assigned activation recipient is stale or unavailable'; end if;
 perform public.custodial_activation_assert_manager(a.requester_manager_id,a.claimant_credential_id,a.claimant_device_id);
 select * into strict c from public.device_auth_enrollment_codes where enrollment_id=a.enrollment_id for update;
 if c.device_id is distinct from p_device or c.code_hash is distinct from p_code_hash or c.revoked_at is not null or c.expires_at<=now()
  or c.failed_attempts>=10 or c.metadata_json->>'purpose' is distinct from 'assigned_device_activation'
  or c.metadata_json->>'operation_id' is distinct from p_operation::text
  or c.metadata_json->>'device_id' is distinct from p_device::text
  or c.metadata_json->>'canonical_device_id' is distinct from d.device_id
  or c.metadata_json->>'employee_id' is distinct from a.expected_employee_id::text
  or c.metadata_json->>'assignment_epoch' is distinct from a.expected_assignment_epoch::text
  or c.metadata_json->>'claimant_credential_id' is distinct from a.claimant_credential_id::text
  or (c.consumed_at is not null and not exists(select 1 from public.device_auth_enrollment_operations e
   where e.operation_id=p_operation and e.device_id=p_device and e.enrollment_id=c.enrollment_id))
  then raise exception 'assigned activation code binding invalid'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_claim(p_operation uuid, p_manager uuid, p_claimant uuid, p_workstation text, p_serial_sha256 text, p_client_version text, p_code_hash text, p_token_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype; d public.devices%rowtype; code jsonb;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_claimant,p_workstation);
 if p_workstation is null or p_operation is null then raise exception 'exact workstation claim required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation::text,0));
 select d0.* into strict d from public.devices d0 join public.custodial_assigned_activation_operations a0 on a0.device_id=d0.id
  where a0.operation_id=p_operation for update of d0;
 perform public.custodial_activation_expire_device(d.id);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if a.requester_manager_id is distinct from p_manager or a.requester_credential_id=p_claimant
  or a.approved_serial_sha256 is distinct from p_serial_sha256 then raise exception using errcode='42501',message='activation claimant or physical recipient mismatch'; end if;
 if a.terminal_at is not null then return jsonb_build_object('status',public.custodial_activation_public_status(a)); end if;
 -- Reserve the bounded attempt BEFORE returning the dispatch secret. Counting
 -- only the later delivery report permits endless retries after client loss.
 if a.attempts>=5 then raise exception using errcode='40001',message='activation dispatch attempt limit reached'; end if;
 if d.active is not true or d.assigned_employee_id is distinct from a.expected_employee_id
  or d.assignment_epoch is distinct from a.expected_assignment_epoch then raise exception 'activation assignment changed'; end if;
 if a.claimant_credential_id is not null then
  if (a.claimant_credential_id,a.claimant_device_id,a.client_version) is distinct from (p_claimant,p_workstation,p_client_version)
   then raise exception using errcode='42501',message='activation already claimed by another workstation'; end if;
  update public.custodial_assigned_activation_operations set state='prepared',state_version=state_version+1,
   attempts=attempts+1 where operation_id=p_operation returning * into a;
 else
  if coalesce(p_code_hash,'') !~ '^[0-9a-f]{64}$' or coalesce(p_client_version,'') !~ '^[a-z0-9][a-z0-9._-]{0,79}$'
   or p_token_envelope is null or jsonb_typeof(p_token_envelope)<>'object' or pg_column_size(p_token_envelope)>2048
   or p_token_envelope->>'version' is distinct from 'assigned-activation.aes-256-gcm.v1'
   or coalesce(p_token_envelope->>'ciphertext','') !~ '^[A-Za-z0-9_-]{58}$'
   or coalesce(p_token_envelope->>'iv','') !~ '^[A-Za-z0-9_-]{16}$'
   or coalesce(p_token_envelope->>'tag','') !~ '^[A-Za-z0-9_-]{22}$'
   or (select count(*) from jsonb_object_keys(p_token_envelope))<>4
   then raise exception 'bounded authenticated activation envelope required'; end if;
  select to_jsonb(issued) into strict code from public.device_auth_issue_enrollment_code(d.id,p_code_hash,p_manager::text,a.expires_at,
   jsonb_build_object('purpose','assigned_device_activation','operation_id',p_operation,'device_id',d.id,
    'canonical_device_id',d.device_id,'employee_id',a.expected_employee_id,'assignment_epoch',a.expected_assignment_epoch,
    'claimant_credential_id',p_claimant)) issued;
  update public.custodial_assigned_activation_operations set claimant_credential_id=p_claimant,claimant_device_id=p_workstation,
   client_version=p_client_version,enrollment_id=(code->>'enrollment_id')::uuid,token_envelope=p_token_envelope,
   state='prepared',state_version=state_version+1,attempts=1,prepared_at=now() where operation_id=p_operation returning * into a;
 end if;
 return jsonb_build_object('status',public.custodial_activation_public_status(a),'token_envelope',a.token_envelope);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_delivery(p_operation uuid, p_manager uuid, p_claimant uuid, p_workstation text, p_expected_version integer, p_outcome text, p_error_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_claimant,p_workstation);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation;
 perform 1 from public.devices where id=a.device_id for update;
 perform public.custodial_activation_expire_device(a.device_id);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if (a.requester_manager_id,a.claimant_credential_id,a.claimant_device_id) is distinct from (p_manager,p_claimant,p_workstation)
  then raise exception using errcode='42501',message='exact activation claimant required'; end if;
 if a.terminal_at is not null then return public.custodial_activation_public_status(a); end if;
 if a.state_version is distinct from p_expected_version or a.state<>'prepared'
  or a.attempts<1 or coalesce(p_outcome,'') not in ('delivered','delivery_unknown')
  then raise exception using errcode='40001',message='stale or invalid activation delivery report'; end if;
 update public.custodial_assigned_activation_operations set state=p_outcome,state_version=state_version+1,
  delivered_at=case when p_outcome='delivered' then coalesce(delivered_at,now()) else delivered_at end,
  last_error_code=p_error_code where operation_id=p_operation returning * into a;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_guard_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if tg_op='DELETE' then raise exception 'activation operation history is retained'; end if;
 if old.terminal_at is not null then raise exception 'terminal activation receipt is immutable'; end if;
 if (new.operation_id,new.device_id,new.canonical_device_id,new.expected_employee_id,new.expected_assignment_epoch,
  new.requested_action,new.requester_manager_id,new.requester_credential_id,new.approved_serial_sha256,new.requested_at,new.expires_at)
 is distinct from (old.operation_id,old.device_id,old.canonical_device_id,old.expected_employee_id,old.expected_assignment_epoch,
  old.requested_action,old.requester_manager_id,old.requester_credential_id,old.approved_serial_sha256,old.requested_at,old.expires_at)
 then raise exception 'activation frozen recipient changed'; end if;
 if old.claimant_credential_id is not null and
  (new.claimant_credential_id,new.claimant_device_id,new.client_version,new.enrollment_id,new.prepared_at)
  is distinct from (old.claimant_credential_id,old.claimant_device_id,old.client_version,old.enrollment_id,old.prepared_at)
  then raise exception 'activation claimant changed'; end if;
 if new.state_version<>old.state_version+1 or new.attempts<old.attempts or new.attempts>old.attempts+1
  or not ((old.state='requested' and new.state in ('prepared','error','expired','cancelled'))
   or (old.state in ('prepared','delivered','delivery_unknown') and new.state in
    ('prepared','delivered','delivery_unknown','native_active','not_required','error','expired','cancelled')))
  then raise exception 'activation state transition invalid'; end if;
 if new.terminal_at is null and old.token_envelope is not null and new.token_envelope is distinct from old.token_envelope
  then raise exception 'activation same-operation token cannot rotate'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_list(p_manager uuid, p_requester uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d record; result jsonb;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_requester);
 for d in select dev.id from public.devices dev where exists(select 1 from public.custodial_assigned_activation_operations a
  where a.device_id=dev.id and a.requester_manager_id=p_manager and a.terminal_at is null)
  order by dev.id limit 50 for update of dev
 loop perform public.custodial_activation_expire_device(d.id);end loop;
 select coalesce(jsonb_agg(public.custodial_activation_public_status(a) order by a.requested_at),'[]'::jsonb)
 into result from (select * from public.custodial_assigned_activation_operations
  where requester_manager_id=p_manager and terminal_at is null order by requested_at limit 50) a;
 return jsonb_build_object('operations',result);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_native_result(p_operation uuid, p_device uuid, p_credential uuid, p_token_hash text, p_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype; d public.devices%rowtype;
 c public.device_auth_credentials%rowtype; e public.device_auth_enrollment_operations%rowtype;
outcome text; lineage uuid;
begin
 perform public.custodial_begin_application_mutation();
 if p_operation is null or p_device is null or p_credential is null then raise exception 'exact native result identity required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation::text,0));
 select * into strict d from public.devices where id=p_device for update;
 perform public.custodial_activation_expire_device(p_device);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 select * into c from public.device_auth_credentials where credential_id=p_credential and device_id=p_device
  and token_hash=p_token_hash and confirmed_at is not null and revoked_at is null and expires_at>now();
 if c.credential_id is null or a.device_id is distinct from p_device or d.active is not true
  or a.expected_employee_id is distinct from d.assigned_employee_id or a.expected_assignment_epoch is distinct from d.assignment_epoch
  then raise exception using errcode='42501',message='current exact assigned device credential required'; end if;
 if p_receipt is null or jsonb_typeof(p_receipt)<>'object' or pg_column_size(p_receipt)>2048
  or (select count(*) from jsonb_object_keys(p_receipt))<>9
  or p_receipt->>'operation_id' is distinct from p_operation::text
  or p_receipt->>'device_id' is distinct from d.device_id
  or p_receipt->>'credential_id' is distinct from p_credential::text
  or coalesce(p_receipt->>'flow','') not in ('enrollment','recovery')
  or p_receipt->>'journal_schema' is distinct from 'native-assigned-activation.v1'
  or coalesce(p_receipt->>'journal_binding_sha256','') !~ '^[0-9a-f]{64}$'
  or coalesce(p_receipt->>'lineage_operation_id','') !~ '^[0-9a-f-]{36}$'
  then raise exception 'exact bounded protected native receipt required'; end if;
 lineage:=(p_receipt->>'lineage_operation_id')::uuid;
 if not exists(select 1 from public.device_auth_enrollment_operations original
  where original.operation_id=lineage and original.device_id=p_device and original.status='confirmed'
   and public.custodial_credential_may_transmit_frozen_work(original.credential_id,p_credential,p_device,now()))
  then raise exception 'native lineage is not an authenticated predecessor'; end if;
 if a.state in ('native_active','not_required') then
  if a.native_receipt is distinct from p_receipt then raise exception 'native terminal receipt conflict'; end if;
  return public.custodial_activation_public_status(a);
 end if;
 if a.state not in ('prepared','delivered','delivery_unknown') or a.claimant_credential_id is null
  then raise exception 'native activation is not pending'; end if;
 select * into e from public.device_auth_enrollment_operations where operation_id=p_operation;
 if p_receipt->>'outcome'='active' and p_receipt->'changed'='true'::jsonb then
  if e.operation_id is null or e.device_id is distinct from p_device or e.credential_id is distinct from p_credential
   or e.flow is distinct from p_receipt->>'flow' or e.status<>'confirmed' or e.enrollment_id is distinct from a.enrollment_id
   then raise exception 'native active requires exact confirmed enrollment'; end if;
  outcome:='native_active';
 elsif p_receipt->>'outcome'='not_required' and p_receipt->'changed'='false'::jsonb then
  if e.operation_id is not null or c.created_at>=a.requested_at or not exists(
   select 1 from public.device_auth_enrollment_codes where enrollment_id=a.enrollment_id and consumed_at is null)
   then raise exception 'not required must preserve an existing healthy credential'; end if;
  outcome:='not_required';
 else raise exception 'invalid native activation outcome'; end if;
 update public.device_auth_enrollment_codes set revoked_at=coalesce(revoked_at,now())
  where enrollment_id=a.enrollment_id and consumed_at is null;
 update public.custodial_assigned_activation_operations set state=outcome,state_version=state_version+1,
  native_receipt=p_receipt,terminal_at=now(),token_envelope=null,last_error_code=null
  where operation_id=p_operation returning * into a;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_read(p_operation uuid, p_manager uuid, p_requester uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.custodial_assigned_activation_operations%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_requester);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation;
 if a.requester_manager_id is distinct from p_manager then raise exception using errcode='42501',message='activation belongs to another manager'; end if;
 perform 1 from public.devices where id=a.device_id for update;
 perform public.custodial_activation_expire_device(a.device_id);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_activation_request(p_operation uuid, p_device text, p_employee uuid, p_epoch bigint, p_manager uuid, p_requester uuid, p_serial_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype; a public.custodial_assigned_activation_operations%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 perform public.custodial_activation_assert_manager(p_manager,p_requester);
 if p_operation is null or p_employee is null or p_epoch is null or p_serial_sha256 is null then raise exception 'exact activation request required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation::text,0));
 select * into strict d from public.devices where device_id=p_device for update;
 perform public.custodial_activation_expire_device(d.id);
 select * into a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 if found then
  if (a.device_id,a.expected_employee_id,a.expected_assignment_epoch,a.requester_manager_id,a.requester_credential_id,a.approved_serial_sha256)
   is distinct from (d.id,p_employee,p_epoch,p_manager,p_requester,p_serial_sha256)
   then raise exception using errcode='40001',message='activation operation conflict'; end if;
  return public.custodial_activation_public_status(a);
 end if;
 if d.active is not true or d.assigned_employee_id is distinct from p_employee or d.assignment_epoch is distinct from p_epoch
  or not exists(select 1 from public.employees where id=p_employee and active and employee_code ~ '^EMP[0-9]+$')
 then raise exception using errcode='40001',message='phone assignment changed or unavailable'; end if;
 insert into public.custodial_assigned_activation_operations(operation_id,device_id,canonical_device_id,
  expected_employee_id,expected_assignment_epoch,requested_action,requester_manager_id,requester_credential_id,approved_serial_sha256)
 values(p_operation,d.id,d.device_id,p_employee,p_epoch,'activate_or_recover',p_manager,p_requester,p_serial_sha256) returning * into a;
 return public.custodial_activation_public_status(a);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_append_session_correction(p_operation_id uuid, p_session_id uuid, p_manager_id uuid, p_reason text, p_backend_execution_secret text, p_corrected_employee_id uuid DEFAULT NULL::uuid, p_corrected_location_id uuid DEFAULT NULL::uuid, p_corrected_device_id uuid DEFAULT NULL::uuid, p_corrected_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_corrected_ended_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_fingerprint text;
  v_existing public.custodial_session_corrections%rowtype;
  v_current record;
  v_manager_name text;
  v_employee record;
  v_location record;
  v_device record;
  v_employee_id uuid;
  v_location_id uuid;
  v_device_id uuid;
  v_started_at timestamptz;
  v_ended_at timestamptz;
  v_changed_fields text[];
  v_inserted public.custodial_session_corrections%rowtype;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if p_operation_id is null or p_session_id is null or p_manager_id is null
     or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 then
    raise exception using errcode='22023', message='Correction operation, session, named manager, and reason are required';
  end if;

  v_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'operation_id',p_operation_id,'session_id',p_session_id,'manager_id',p_manager_id,
    'reason',btrim(p_reason),'employee_id',p_corrected_employee_id,'location_id',p_corrected_location_id,
    'device_id',p_corrected_device_id,'started_at',p_corrected_started_at,'ended_at',p_corrected_ended_at
  )::text,'UTF8'),'sha256'),'hex');

  select * into v_existing
  from public.custodial_session_corrections c
  where c.operation_id = p_operation_id;
  if found then
    if v_existing.request_fingerprint is distinct from v_fingerprint then
      raise exception using errcode='23505', message='Correction operation was already used for a different request';
    end if;
    return jsonb_build_object('correction_id',v_existing.correction_id,'session_id',v_existing.session_id,
      'operation_id',v_existing.operation_id,'replayed',true,'changed_fields',v_existing.changed_fields,
      'created_at',v_existing.created_at);
  end if;

  select m.display_name into v_manager_name
  from public.ops_manager_managers m
  where m.manager_id = p_manager_id
    and m.active = true and m.revoked_at is null and m.is_system_principal = false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[];
  if not found then
    raise exception using errcode='42501', message='An active named manager is required to correct a cleaning record';
  end if;

  select
    coalesce(c.effective_employee_id,s.employee_id) employee_id,
    coalesce(c.effective_location_id,s.location_id) location_id,
    coalesce(c.effective_device_id,s.device_id) device_id,
    coalesce(c.effective_started_at,s.started_at) started_at,
    coalesce(c.effective_ended_at,s.ended_at) ended_at
  into v_current
  from public.sessions s
  left join lateral (
    select c.* from public.custodial_session_corrections c
    where c.session_id = s.id
    order by c.created_at desc,c.correction_id desc
    limit 1
  ) c on true
  where s.id = p_session_id
  for update of s;
  if not found then
    raise exception using errcode='P0002', message='Cleaning session was not found';
  end if;

  v_employee_id := coalesce(p_corrected_employee_id,v_current.employee_id);
  v_location_id := coalesce(p_corrected_location_id,v_current.location_id);
  v_device_id := coalesce(p_corrected_device_id,v_current.device_id);
  v_started_at := coalesce(p_corrected_started_at,v_current.started_at);
  v_ended_at := coalesce(p_corrected_ended_at,v_current.ended_at);

  v_changed_fields := array_remove(array[
    case when v_employee_id is distinct from v_current.employee_id then 'employee' end,
    case when v_location_id is distinct from v_current.location_id then 'location' end,
    case when v_device_id is distinct from v_current.device_id then 'device' end,
    case when v_started_at is distinct from v_current.started_at then 'started_at' end,
    case when v_ended_at is distinct from v_current.ended_at then 'ended_at' end
  ],null);
  if cardinality(v_changed_fields) = 0 then
    raise exception using errcode='22023', message='Correction must change at least one manager-visible fact';
  end if;
  if v_ended_at is not null and v_ended_at < v_started_at then
    raise exception using errcode='22023', message='Corrected cleaning end time cannot precede its start time';
  end if;

  select e.id,e.display_name into v_employee from public.employees e where e.id = v_employee_id;
  select l.id,l.location_code,l.location_name into v_location from public.locations l where l.id = v_location_id;
  select d.id,d.device_id,d.device_name,d.assignment_epoch into v_device from public.devices d where d.id = v_device_id;
  if v_employee.id is null or v_location.id is null or v_device.id is null then
    raise exception using errcode='23503', message='Corrected employee, location, and phone must exist';
  end if;

  insert into public.custodial_session_corrections(
    operation_id,request_fingerprint,session_id,corrected_by_manager_id,corrected_by_manager_name_snapshot,
    reason,changed_fields,effective_employee_id,effective_employee_name_snapshot,effective_location_id,
    effective_location_code_snapshot,effective_location_name_snapshot,effective_device_id,
    effective_device_identifier_snapshot,effective_device_name_snapshot,effective_assignment_epoch_snapshot,
    effective_started_at,effective_ended_at
  ) values (
    p_operation_id,v_fingerprint,p_session_id,p_manager_id,v_manager_name,btrim(p_reason),v_changed_fields,
    v_employee.id,v_employee.display_name,v_location.id,v_location.location_code,v_location.location_name,
    v_device.id,v_device.device_id,v_device.device_name,v_device.assignment_epoch,v_started_at,v_ended_at
  ) returning * into v_inserted;

  return jsonb_build_object('correction_id',v_inserted.correction_id,'session_id',v_inserted.session_id,
    'operation_id',v_inserted.operation_id,'replayed',false,'changed_fields',v_inserted.changed_fields,
    'created_at',v_inserted.created_at);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_assert_manager(p_manager_id uuid)
 RETURNS ops_manager_managers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
begin
  if p_manager_id is null then
    raise exception using errcode = '22023', message = 'Custodial Manager identity is required.';
  end if;
  select * into v_manager
  from public.ops_manager_managers
  where manager_id = p_manager_id
    and active is true
    and revoked_at is null
    and is_system_principal is false
  limit 1;
  if v_manager.manager_id is null or not ('CUSTODIAL_MANAGER' = any(coalesce(v_manager.roles, '{}'::text[]))) then
    raise exception using errcode = '42501', message = 'Custodial Manager access is required.';
  end if;
  return v_manager;
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_assign_employee_device(p_device_identifier text, p_employee_id uuid DEFAULT NULL::uuid, p_changed_by_manager_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_move_existing boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_identifier text := upper(regexp_replace(btrim(coalesce(p_device_identifier, '')), '^KIOSK[-_ ]?', 'KIOSK_', 'i'));
  v_device public.devices%rowtype;
  v_old_employee public.employees%rowtype;
  v_new_employee public.employees%rowtype;
  v_new_user public.msg_users%rowtype;
  v_other_device public.devices%rowtype;
  v_alias text;
  v_changed boolean := false;
  v_reason text := left(nullif(btrim(coalesce(p_reason, '')), ''), 500);
begin
  v_manager := public.custodial_assert_manager(p_changed_by_manager_id);
  if v_identifier ~ '^KIOSK_[2-9]$' then
    v_identifier := 'KIOSK_0' || substring(v_identifier from 7);
  end if;
  if v_identifier !~ '^KIOSK_(0[2-9]|10)$' then
    raise exception using errcode = '22023', message = 'Choose an employee kiosk from KIOSK_02 through KIOSK_10.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('custodial-device-assignment:' || v_identifier, 0));
  select * into v_device
  from public.devices
  where upper(device_id) = v_identifier and active is true
  for update;
  if v_device.id is null then
    raise exception using errcode = 'P0002', message = 'Active employee kiosk not found.';
  end if;

  if v_device.assigned_employee_id is not null then
    select * into v_old_employee from public.employees where id = v_device.assigned_employee_id;
  end if;

  if p_employee_id is not null then
    select * into v_new_employee
    from public.employees
    where id = p_employee_id
    for update;
    if v_new_employee.id is null then
      raise exception using errcode = 'P0002', message = 'Employee not found.';
    end if;
    if v_new_employee.active is not true or v_new_employee.role <> 'staff' or v_new_employee.employee_code !~ '^EMP[0-9]+$' then
      raise exception using errcode = '22023', message = 'Only an active Memphis Zoo custodial employee can be assigned to a phone.';
    end if;

    select * into v_new_user
    from public.msg_users
    where employee_id = v_new_employee.id
    for update;
    if v_new_user.id is null then
      if exists (select 1 from public.msg_users where lower(btrim(display_name)) = lower(v_new_employee.display_name)) then
        raise exception using errcode = '23505', message = 'Messenger already contains a different user with this employee name.';
      end if;
      insert into public.msg_users(employee_id, display_name, role, is_active)
      values (v_new_employee.id, v_new_employee.display_name, 'employee', true)
      returning * into v_new_user;
    else
      update public.msg_users
      set display_name = v_new_employee.display_name,
          role = 'employee',
          is_active = true,
          updated_at = now()
      where id = v_new_user.id
      returning * into v_new_user;
    end if;

    select * into v_other_device
    from public.devices
    where assigned_employee_id = v_new_employee.id
      and id <> v_device.id
      and active is true
    order by device_id
    limit 1
    for update;

    if v_other_device.id is not null and not p_move_existing then
      raise exception using errcode = '23505', message = format('%s is already assigned to %s. Confirm moving the employee to this phone.', v_new_employee.display_name, v_other_device.device_id);
    end if;

    if v_other_device.id is not null then
      update public.devices
      set assigned_employee_id = null,
          device_name = 'Unassigned ' || v_other_device.device_id,
          updated_at = now()
      where id = v_other_device.id;

      update public.msg_device_assignments
      set is_active = false,
          notes = 'Phone unassigned by Operations app',
          updated_at = now()
      where upper(device_identifier) = upper(v_other_device.device_id)
         or upper(device_identifier) in (
           select upper(alias_identifier) from public.device_aliases
           where canonical_device_id = v_other_device.id and active is true
         );

      insert into public.custodial_employee_device_assignment_history(
        device_id, device_identifier, previous_employee_id, previous_employee_name,
        new_employee_id, new_employee_name, changed_by_manager_id,
        change_reason, source, metadata_json
      ) values (
        v_other_device.id, v_other_device.device_id, v_new_employee.id, v_new_employee.display_name,
        null, null, v_manager.manager_id,
        coalesce(v_reason, 'moved_to_' || v_device.device_id), 'operations_app',
        jsonb_build_object('moved_to_device', v_device.device_id)
      );
    end if;
  end if;

  v_changed := v_device.assigned_employee_id is distinct from p_employee_id;

  update public.devices
  set assigned_employee_id = p_employee_id,
      device_name = case when p_employee_id is null then 'Unassigned ' || v_device.device_id else v_new_employee.display_name end,
      updated_at = now()
  where id = v_device.id
  returning * into v_device;

  if p_employee_id is null then
    update public.msg_device_assignments
    set is_active = false,
        notes = 'Phone unassigned by Operations app',
        updated_at = now()
    where upper(device_identifier) = upper(v_device.device_id)
       or upper(device_identifier) in (
         select upper(alias_identifier) from public.device_aliases
         where canonical_device_id = v_device.id and active is true
       );
  else
    insert into public.msg_device_assignments(device_identifier, msg_user_id, is_active, notes)
    values (v_device.device_id, v_new_user.id, true, 'Managed by Operations app')
    on conflict (device_identifier) do update
    set msg_user_id = excluded.msg_user_id,
        is_active = true,
        notes = excluded.notes,
        updated_at = now();

    for v_alias in
      select alias_identifier from public.device_aliases
      where canonical_device_id = v_device.id and active is true
    loop
      insert into public.msg_device_assignments(device_identifier, msg_user_id, is_active, notes)
      values (v_alias, v_new_user.id, true, 'Managed alias for ' || v_device.device_id)
      on conflict (device_identifier) do update
      set msg_user_id = excluded.msg_user_id,
          is_active = true,
          notes = excluded.notes,
          updated_at = now();
    end loop;
  end if;

  if v_changed or v_other_device.id is not null then
    insert into public.custodial_employee_device_assignment_history(
      device_id, device_identifier, previous_employee_id, previous_employee_name,
      new_employee_id, new_employee_name, changed_by_manager_id,
      change_reason, source, metadata_json
    ) values (
      v_device.id, v_device.device_id, v_old_employee.id, v_old_employee.display_name,
      v_new_employee.id, v_new_employee.display_name, v_manager.manager_id,
      coalesce(v_reason, case when p_employee_id is null then 'phone_unassigned' else 'phone_reassigned' end),
      'operations_app',
      jsonb_build_object('move_existing', p_move_existing, 'messenger_user_id', v_new_user.id)
    );
  end if;

  return jsonb_build_object(
    'changed', v_changed,
    'device', jsonb_build_object(
      'device_pk', v_device.id,
      'device_id', v_device.device_id,
      'device_name', v_device.device_name,
      'assigned_employee_id', v_device.assigned_employee_id,
      'assigned_employee_name', v_new_employee.display_name
    ),
    'previous_employee', case when v_old_employee.id is null then null else jsonb_build_object('id', v_old_employee.id, 'display_name', v_old_employee.display_name, 'employee_code', v_old_employee.employee_code) end,
    'new_employee', case when v_new_employee.id is null then null else jsonb_build_object('id', v_new_employee.id, 'display_name', v_new_employee.display_name, 'employee_code', v_new_employee.employee_code, 'msg_user_id', v_new_user.id) end,
    'moved_from_device', v_other_device.device_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_assign_employee_device(p_device_identifier text, p_employee_id uuid, p_changed_by_manager_id uuid, p_reason text, p_move_existing boolean, p_expected_owner_provided boolean, p_expected_current_employee_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_identifier text:=upper(regexp_replace(btrim(coalesce(p_device_identifier,'')),'^KIOSK[-_ ]?','KIOSK_','i'));
  v_current_employee_id uuid;
begin
  perform public.custodial_assert_manager(p_changed_by_manager_id);
  if v_identifier ~ '^KIOSK_[2-9]$' then v_identifier:='KIOSK_0'||substring(v_identifier from 7); end if;
  if p_expected_owner_provided is null then raise exception using errcode='22023',message='expected-owner presence must be explicit'; end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-device-assignment:'||v_identifier,0));
  select d.assigned_employee_id into v_current_employee_id from public.devices d
  where upper(d.device_id)=v_identifier and d.active=true for update;
  if not found then raise exception using errcode='P0002',message='Active employee kiosk not found.'; end if;
  if p_expected_owner_provided and v_current_employee_id is distinct from p_expected_current_employee_id then
    raise exception using errcode='40001',message='This phone assignment changed. Refresh and try again.';
  end if;
  return public.custodial_assign_employee_device(
    v_identifier,p_employee_id,p_changed_by_manager_id,p_reason,p_move_existing
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_bootstrap_restore_release_authority(p_manager_id uuid, p_request_id uuid, p_device_identifier text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_definition public.custodial_release_authority_bootstrap_definitions%rowtype; v_device text:=upper(btrim(coalesce(p_device_identifier,''))); v_secret_digest text;
begin
  select execution_secret_digest into v_secret_digest from public.custodial_backend_execution_config where config_key=true and enabled=true;
  if v_secret_digest is null or length(coalesce(p_backend_execution_secret,''))<32 or encode(extensions.digest(convert_to(p_backend_execution_secret,'UTF8'),'sha256'),'hex')<>v_secret_digest then raise exception using errcode='42501',message='backend execution secret is not authorized'; end if;
  if p_request_id is null or v_device !~ '^KIOSK_(0[2-9]|10)$' or not coalesce((select paused from public.custodial_release_canary_controls where device_identifier=v_device),false) then raise exception using errcode='55000',message='the exact release canary must be paused before bootstrap restoration'; end if;
  if not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id and m.active and m.revoked_at is null and m.roles && array['DIRECTOR','SECURITY_ADMIN']::text[]) then raise exception using errcode='42501',message='named release manager authority is required'; end if;
  select * into v_definition from public.custodial_release_authority_bootstrap_definitions where bootstrap_key=true;
  if v_definition.function_identity is null or encode(extensions.digest(convert_to(v_definition.function_definition,'UTF8'),'sha256'),'hex')<>v_definition.definition_sha256 then raise exception using errcode='23514',message='bootstrap controller definition failed its digest'; end if;
  execute v_definition.function_definition;
  execute 'revoke all on function public.custodial_control_release_canary(uuid,uuid,text,text,text,jsonb,text) from public,anon,authenticated,service_role';
  execute 'grant execute on function public.custodial_control_release_canary(uuid,uuid,text,text,text,jsonb,text) to postgres,service_role';
  return jsonb_build_object('restored_controller',v_definition.function_identity,'canary_paused',true,'request_id',p_request_id);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_claim_offline_reconciliation_notification_recipients(p_outbox_id uuid, p_worker_id text, p_outbox_lease_token uuid, p_recipients jsonb, p_backend_execution_secret text)
 RETURNS TABLE(delivery_recipient_id uuid, manager_id uuid, recipient_user_id uuid, client_message_id text, notification_instance_key text, attempts integer, lease_token uuid, lease_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_outbox public.custodial_offline_reconciliation_outbox%rowtype;
  v_worker_id text := nullif(btrim(coalesce(p_worker_id,'')), '');
  v_expected integer;
  v_inserted integer;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if v_worker_id is null or length(v_worker_id)>200 or p_outbox_id is null then raise exception using errcode='22023',message='a bounded worker and notification identity are required'; end if;
  select * into v_outbox from public.custodial_offline_reconciliation_outbox where outbox_id=p_outbox_id for update;
  if v_outbox.outbox_id is null then raise exception using errcode='P0002',message='offline reconciliation notification was not found'; end if;
  if v_outbox.state<>'claimed' or v_outbox.claimed_by<>v_worker_id or v_outbox.lease_token is distinct from p_outbox_lease_token or v_outbox.lease_expires_at<=now() then
    raise exception using errcode='40901',message='notification claim is no longer owned by this worker';
  end if;
  if not exists(select 1 from public.custodial_offline_reconciliation_delivery_recipients where outbox_id=p_outbox_id) then
    if jsonb_typeof(coalesce(p_recipients,'null'::jsonb))<>'array' or jsonb_array_length(p_recipients) not between 1 and 100 then
      raise exception using errcode='22023',message='one to one hundred authoritative named-manager recipients are required';
    end if;
    select count(*) into v_expected from (
      select distinct input.manager_id,input.user_id from jsonb_to_recordset(p_recipients) as input(manager_id uuid,user_id uuid)
    ) candidates;
    insert into public.custodial_offline_reconciliation_delivery_recipients(
      outbox_id,manager_id,recipient_user_id,client_message_id,notification_instance_key
    )
    select p_outbox_id,c.manager_id,c.user_id,
      'offline-reconciliation:'||p_outbox_id::text||':'||c.user_id::text,
      'offline-reconciliation:'||p_outbox_id::text||':'||c.user_id::text
    from (select distinct input.manager_id,input.user_id from jsonb_to_recordset(p_recipients) as input(manager_id uuid,user_id uuid)) c
    join public.ops_manager_managers m on m.manager_id=c.manager_id and m.active=true and m.revoked_at is null and m.is_system_principal=false
    join public.msg_users u on u.id=c.user_id and u.ops_manager_id=m.manager_id and coalesce(u.is_active,true)=true;
    get diagnostics v_inserted=row_count;
    if v_inserted<>v_expected then raise exception using errcode='42501',message='notification recipients must be active named-manager Messenger identities'; end if;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,evidence_json)
      select p_outbox_id,r.delivery_recipient_id,'recipient_declared',jsonb_build_object('manager_id',r.manager_id,'recipient_user_id',r.recipient_user_id,'client_message_id',r.client_message_id)
      from public.custodial_offline_reconciliation_delivery_recipients r where r.outbox_id=p_outbox_id;
  end if;
  with exhausted as (
    update public.custodial_offline_reconciliation_delivery_recipients r
    set state='failed',failed_at=now(),claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,
      last_error='recipient delivery lease expired after maximum attempts'
    where r.outbox_id=p_outbox_id and r.state='claimed' and r.lease_expires_at<=now() and r.attempts>=5
    returning r.delivery_recipient_id,r.attempts
  ) insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,error_text,evidence_json)
    select p_outbox_id,e.delivery_recipient_id,'recipient_lease_exhausted',e.attempts,'recipient delivery lease expired after maximum attempts',jsonb_build_object('terminal',true) from exhausted e;
  with reclaimed as (
    update public.custodial_offline_reconciliation_delivery_recipients r
    set state='retry',claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,next_attempt_at=now(),
      last_error=coalesce(nullif(r.last_error,''),'recipient delivery lease expired')
    where r.outbox_id=p_outbox_id and r.state='claimed' and r.lease_expires_at<=now() and r.attempts<5
    returning r.delivery_recipient_id,r.attempts
  ) insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,error_text,evidence_json)
    select p_outbox_id,r.delivery_recipient_id,'recipient_lease_reclaimed',r.attempts,'recipient delivery lease expired',jsonb_build_object('requeued',true) from reclaimed r;
  return query
  with candidates as (
    select r.delivery_recipient_id from public.custodial_offline_reconciliation_delivery_recipients r
    where r.outbox_id=p_outbox_id and r.state in ('pending','retry') and r.next_attempt_at<=now() and r.attempts<5
    order by r.created_at,r.delivery_recipient_id for update skip locked
  ), claimed as (
    update public.custodial_offline_reconciliation_delivery_recipients r
    set state='claimed',claimed_by=v_worker_id,lease_token=gen_random_uuid(),claimed_at=now(),lease_expires_at=least(v_outbox.lease_expires_at,now()+interval '120 seconds'),attempts=r.attempts+1
    from candidates c where r.delivery_recipient_id=c.delivery_recipient_id returning r.*
  ), evidence as (
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,worker_id,evidence_json)
    select p_outbox_id,c.delivery_recipient_id,'recipient_claimed',c.attempts,v_worker_id,jsonb_build_object('lease_token',c.lease_token,'lease_expires_at',c.lease_expires_at) from claimed c
  )
  select c.delivery_recipient_id,c.manager_id,c.recipient_user_id,c.client_message_id,c.notification_instance_key,c.attempts,c.lease_token,c.lease_expires_at from claimed c;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_close_maintenance_ticket_authoritative(p_ticket_id uuid, p_closed_by text, p_close_notes text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_closed_by text := nullif(left(btrim(coalesce(p_closed_by,'')),200),'');
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if p_ticket_id is null or v_closed_by is null then raise exception using errcode='22023',message='ticket identity and named closer are required'; end if;
  return public.close_maintenance_ticket(p_ticket_id,v_closed_by,nullif(left(btrim(coalesce(p_close_notes,'')),1000),''));
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_commit_offline_occurrence(p_client_session_id text, p_client_completion_id text, p_device_id text, p_location_code text, p_client_started_at text, p_client_ended_at text, p_response_json jsonb, p_scan_evidence jsonb, p_correlation_id text, p_context_id text, p_submission_proof text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_client_session_id text := nullif(btrim(coalesce(p_client_session_id,'')), '');
  v_client_completion_id text := nullif(btrim(coalesce(p_client_completion_id,'')), '');
  v_context_id uuid;
  v_credential_id uuid;
  v_started_at timestamptz;
  v_ended_at timestamptz;
  v_context public.custodial_offline_actor_contexts%rowtype;
  v_proof public.custodial_offline_submission_proofs%rowtype;
  v_existing public.custodial_offline_reconciliation_records%rowtype;
  v_device public.devices%rowtype;
  v_employee public.employees%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_location record;
  v_session public.sessions%rowtype;
  v_completion_response_id uuid;
  v_submitted_at timestamptz;
  v_ticket_count integer := 0;
  v_payload_fingerprint text;
  v_result jsonb;
  v_item jsonb;
  v_event_type text;
  v_event_id text;
  v_event_time timestamptz;
  v_event_fingerprint text;
  v_event_ids text[] := array[]::text[];
  v_reconciliation_id uuid;
  v_failure_detail text;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select session.* into v_session
  from public.sessions session
  where session.client_session_id=v_client_session_id and session.status='cancelled'
  limit 1;
  if v_session.id is not null then
    if not exists(
      select 1
      from public.custodial_offline_actor_contexts context
      join public.locations location on location.id=context.location_id
      join public.devices device on device.id=context.device_id
      where context.context_id::text=lower(btrim(coalesce(p_context_id,'')))
        and context.client_session_id=v_client_session_id
        and context.status='cancelled'
        and context.location_id=v_session.location_id
        and context.employee_id=v_session.employee_id
        and context.device_id=v_session.device_id
        and location.location_code=public.resolve_scan_location_code(p_location_code)
        and (
          upper(btrim(device.device_id))=upper(btrim(coalesce(p_device_id,'')))
          or exists(
            select 1 from public.device_aliases alias
            where alias.canonical_device_id=device.id and alias.active=true
              and upper(btrim(alias.alias_identifier))=upper(btrim(coalesce(p_device_id,'')))
          )
        )
    ) then
      raise exception using errcode='23514',message='Cancelled session does not match the frozen offline occurrence';
    end if;
    return jsonb_build_object(
      'status','cancelled','terminal',true,'discard_local_workflow',true,
      'reason','offline_context_expired','session_uuid',v_session.session_uuid,
      'client_session_id',v_session.client_session_id,
      'client_completion_id',v_client_completion_id,
      'started_at',v_session.started_at,'ended_at',v_session.ended_at,
      'duration_minutes',v_session.duration_minutes,
      'duration_display',v_session.duration_display,'replayed',true
    );
  end if;
  if v_client_session_id is null or length(v_client_session_id)>200 or v_client_completion_id is null or length(v_client_completion_id)>200 then
    return public.custodial_quarantine_offline_submission(p_client_session_id,p_client_completion_id,null,null,
      jsonb_build_object('response_json',coalesce(p_response_json,'null'::jsonb),'scan_evidence',coalesce(p_scan_evidence,'null'::jsonb)),
      'invalid_stable_submission_identity','{}'::jsonb,p_backend_execution_secret);
  end if;
  if jsonb_typeof(p_response_json) is distinct from 'object' or pg_column_size(coalesce(p_response_json,'null'::jsonb))>1048576
     or jsonb_typeof(p_scan_evidence) is distinct from 'array' or coalesce(jsonb_array_length(p_scan_evidence),0)>100
     or pg_column_size(coalesce(p_scan_evidence,'null'::jsonb))>1048576 then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,null,null,
      jsonb_build_object('response_json',coalesce(p_response_json,'null'::jsonb),'scan_evidence',coalesce(p_scan_evidence,'null'::jsonb)),
      'invalid_payload_shape_or_bounds','{}'::jsonb,p_backend_execution_secret);
  end if;
  begin
    v_context_id := nullif(lower(btrim(coalesce(p_context_id,''))), '')::uuid;
    v_credential_id := nullif(lower(btrim(coalesce(p_authenticated_credential_id,''))), '')::uuid;
    v_started_at := nullif(btrim(coalesce(p_client_started_at,'')), '')::timestamptz;
    v_ended_at := nullif(btrim(coalesce(p_client_ended_at,'')), '')::timestamptz;
  exception when others then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,null,null,
      jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'malformed_authority_or_timestamp',jsonb_build_object('context_id',p_context_id,'credential_id',p_authenticated_credential_id),p_backend_execution_secret);
  end;
  if not isfinite(v_started_at) or not isfinite(v_ended_at) or v_ended_at<=v_started_at or v_ended_at>now()+interval '10 minutes'
     or v_started_at<now()-interval '7 days' or v_ended_at-v_started_at>interval '24 hours' then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context_id,null,
      jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'invalid_occurrence_timestamps','{}'::jsonb,p_backend_execution_secret);
  end if;
  perform public.custodial_lock_offline_reconciliation_keys(v_client_session_id,v_client_completion_id);
  select * into v_context from public.custodial_offline_actor_contexts where context_id=v_context_id for update;
  if v_context.context_id is null then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,null,null,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'offline_actor_context_not_found','{}'::jsonb,p_backend_execution_secret);
  end if;
  if not public.custodial_credential_may_transmit_frozen_work(v_context.credential_id,v_credential_id,v_context.device_id) then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,null,
      jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'context_binding_mismatch','{}'::jsonb,p_backend_execution_secret);
  end if;
  v_payload_fingerprint := public.custodial_offline_payload_fingerprint(v_context,v_client_completion_id,v_started_at,v_ended_at,p_response_json,p_scan_evidence,p_correlation_id);
  select * into v_existing from public.custodial_offline_reconciliation_records where client_completion_id=v_client_completion_id or client_session_id=v_client_session_id order by case when client_completion_id=v_client_completion_id then 0 else 1 end limit 1 for update;
  if v_existing.reconciliation_id is not null then
    if v_existing.client_session_id=v_client_session_id and v_existing.client_completion_id=v_client_completion_id and v_existing.payload_fingerprint=v_payload_fingerprint then
      insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,evidence_json) values(v_existing.reconciliation_id,'replayed',jsonb_build_object('exact_payload_replay',true));
      return v_existing.result_json || jsonb_build_object('reconciliation_id',v_existing.reconciliation_id,'replayed',true);
    end if;
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'payload_fingerprint_conflict','{}'::jsonb,p_backend_execution_secret);
  end if;
  if v_context.client_session_id<>v_client_session_id or v_context.status<>'activated' or v_context.expires_at<=now()
     or upper(btrim(coalesce(p_device_id,'')))<>upper((select device_id from public.devices where id=v_context.device_id))
     or public.resolve_scan_location_code(p_location_code)<>v_context.canonical_location_code or v_context.started_at<>v_started_at then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'context_binding_mismatch','{}'::jsonb,p_backend_execution_secret);
  end if;
  select * into v_proof from public.custodial_offline_submission_proofs where context_id=v_context.context_id for update;
  if v_proof.state<>'issued' or coalesce(p_submission_proof,'') !~ '^[0-9a-f]{64}$' or encode(extensions.digest(convert_to(lower(p_submission_proof),'UTF8'),'sha256'),'hex')<>v_proof.proof_digest then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'submission_proof_invalid','{}'::jsonb,p_backend_execution_secret);
  end if;
  select * into v_device from public.devices where id=v_context.device_id for update;
  select * into v_employee from public.employees where id=v_context.employee_id;
  select * into v_credential from public.device_auth_credentials where credential_id=v_context.credential_id;
  select l.id,l.location_code,l.location_name,l.location_type,l.form_type into v_location from public.locations l where l.id=v_context.location_id;
  if v_device.id is null or v_employee.id is null or v_credential.credential_id is null
     or v_credential.device_id<>v_context.device_id or v_credential.confirmed_at is null
     or v_location.id is null
     or (v_context.snapshot_id is null and (
       v_device.active is not true or v_employee.active is not true
       or v_credential.revoked_at is not null or v_credential.expires_at<=now()
       or not exists(select 1 from public.custodial_employee_device_assignment_history h
         where h.assignment_change_id=v_context.assignment_change_id and h.device_id=v_context.device_id
           and h.new_employee_id=v_context.employee_id)
     ))
     or (v_context.snapshot_id is not null and (
       v_credential.confirmed_at>v_started_at or v_started_at>=v_credential.expires_at
       or v_ended_at>=v_credential.expires_at
       or (v_credential.revoked_at is not null and v_ended_at>=v_credential.revoked_at)
       or not exists(select 1 from public.custodial_employee_device_assignment_history h
         where h.assignment_change_id=v_context.assignment_change_id and h.device_id=v_context.device_id
           and h.new_employee_id=v_context.employee_id and h.changed_at<=v_started_at)
       or exists(select 1 from public.custodial_employee_device_assignment_history h
         where h.device_id=v_context.device_id and h.assignment_change_id<>v_context.assignment_change_id
           and h.changed_at>v_started_at and h.changed_at<=v_ended_at)
     )) then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'permanent_actor_or_credential_proof_loss','{}'::jsonb,p_backend_execution_secret);
  end if;
  begin
    for v_item in select value from jsonb_array_elements(p_scan_evidence) loop
      if jsonb_typeof(v_item)<>'object' or pg_column_size(v_item)>65536
         or not (v_item ?& array['client_event_id','event_type','result','notes','scanned_at','payload_json'])
         or exists(select 1 from jsonb_object_keys(v_item) k where k not in ('client_event_id','event_type','result','notes','scanned_at','payload_json'))
         or jsonb_typeof(v_item->'event_type')<>'string' or jsonb_typeof(v_item->'client_event_id')<>'string' or jsonb_typeof(v_item->'scanned_at')<>'string'
         or coalesce(jsonb_typeof(v_item->'result'),'null') not in ('string','null') or coalesce(jsonb_typeof(v_item->'notes'),'null') not in ('string','null')
         or jsonb_typeof(v_item->'payload_json')<>'object' or not ((v_item->'payload_json') ? 'entry_source')
         or exists(select 1 from jsonb_object_keys(v_item->'payload_json') k where k<>'entry_source')
         or (v_item->'payload_json'->>'entry_source') not in ('native-nfc','manual-qr-fallback')
      then raise exception using errcode='22023',message='scan event shape or provenance is invalid'; end if;
      v_event_type := nullif(btrim(v_item->>'event_type'),''); v_event_id := nullif(btrim(v_item->>'client_event_id'),'');
      if v_event_type not in ('scan_received','scan_blocked','scan_start','scan_finish','scan_resume_pending','scan_invalid_location','scan_unauthorized_device','scan_error') or v_event_id is null or length(v_event_id)>200 or length(coalesce(v_item->>'result',''))>200 or length(coalesce(v_item->>'notes',''))>4000 or jsonb_typeof(coalesce(v_item->'payload_json','{}'::jsonb))<>'object' or pg_column_size(coalesce(v_item->'payload_json','{}'::jsonb))>32768 then raise exception using errcode='22023',message='scan event fields are invalid'; end if;
      v_event_time := (v_item->>'scanned_at')::timestamptz;
      if not isfinite(v_event_time) or v_event_time<v_started_at-interval '10 minutes' or v_event_time>v_ended_at+interval '10 minutes' then raise exception using errcode='22023',message='scan event timestamp is outside the occurrence window'; end if;
      if array_position(v_event_ids,v_event_id) is not null then raise exception using errcode='23505',message='duplicate scan event identity in one payload'; end if;
      v_event_ids := array_append(v_event_ids,v_event_id);
    end loop;
  exception when others then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'malformed_scan_evidence',jsonb_build_object('detail',sqlerrm),p_backend_execution_secret);
  end;
  for v_event_id in select unnest(v_event_ids) order by 1 loop
    perform pg_advisory_xact_lock(hashtextextended('custodial-offline-event:'||v_event_id,0));
    if exists(select 1 from public.custodial_offline_scan_event_evidence where client_event_id=v_event_id) or exists(select 1 from public.scan_events where client_event_id=v_event_id) then
      return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'scan_event_identity_already_bound',jsonb_build_object('client_event_id',v_event_id),p_backend_execution_secret);
    end if;
  end loop;
  begin
    insert into public.custodial_offline_time_reservations(occurrence_id,employee_id,device_id,started_at,ended_at) values(v_context.occurrence_id,v_context.employee_id,v_context.device_id,v_started_at,v_ended_at);
    select * into v_session from public.sessions where client_session_id=v_client_session_id for update;
    if v_session.id is null then
      insert into public.sessions(session_uuid,client_session_id,location_id,employee_id,device_id,status,started_at,ended_at,duration_minutes,duration_display,completion_source)
      values(v_client_session_id,v_client_session_id,v_context.location_id,v_context.employee_id,v_context.device_id,'pending_submit',v_started_at,v_ended_at,greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer),greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer)::text||' min','kiosk_form') returning * into v_session;
    elsif v_session.device_id<>v_context.device_id or v_session.employee_id<>v_context.employee_id or v_session.location_id<>v_context.location_id or v_session.status not in ('active','pending_submit') then raise exception using errcode='23514',message='server session is not bound to the activated occurrence';
    else
      update public.sessions set status='pending_submit',ended_at=v_ended_at,duration_minutes=greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer),duration_display=greatest(0,round(extract(epoch from(v_ended_at-v_started_at))/60.0)::integer)::text||' min' where id=v_session.id and status='active';
      select * into v_session from public.sessions where id=v_session.id;
    end if;
    insert into public.completion_responses(session_id,location_id,submitted_by_employee_id,device_id,response_json,submitted_at,client_completion_id) values(v_session.id,v_context.location_id,v_context.employee_id,v_context.device_id,p_response_json,now(),v_client_completion_id) returning id,submitted_at into v_completion_response_id,v_submitted_at;
    v_ticket_count := public.create_maintenance_tickets_from_response(v_completion_response_id,v_session.id,v_context.location_id,v_context.employee_id,v_context.device_id,v_submitted_at,p_response_json);
    update public.sessions set status='closed',completion_source='kiosk_form',updated_at=now() where id=v_session.id and status='pending_submit';
    if not found then raise exception using errcode='40001',message='session did not reach the canonical pending_submit state'; end if;
    v_result := jsonb_build_object('status','closed','terminal',true,'client_session_id',v_client_session_id,'client_completion_id',v_client_completion_id,'session_uuid',v_session.session_uuid,'completion_response_id',v_completion_response_id,'occurrence_id',v_context.occurrence_id,'original_employee_id',v_context.employee_id,'started_at',v_started_at,'ended_at',v_ended_at,'correlation_id',nullif(btrim(coalesce(p_correlation_id,'')),''),'maintenance_ticket_count',v_ticket_count,'replayed',false);
    insert into public.custodial_offline_reconciliation_records(context_id,occurrence_id,occurrence_fingerprint,original_employee_id,device_id,credential_id,location_id,client_session_id,client_completion_id,payload_fingerprint,payload_json,state,result_json,session_id,completion_response_id)
    values(v_context.context_id,v_context.occurrence_id,v_context.occurrence_fingerprint,v_context.employee_id,v_context.device_id,v_context.credential_id,v_context.location_id,v_client_session_id,v_client_completion_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'committed',v_result,v_session.id,v_completion_response_id) returning reconciliation_id into v_reconciliation_id;
    for v_item in select value from jsonb_array_elements(p_scan_evidence) loop
      v_event_type := v_item->>'event_type'; v_event_id := btrim(v_item->>'client_event_id'); v_event_time := (v_item->>'scanned_at')::timestamptz;
      v_event_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object('client_event_id',v_event_id,'context_id',v_context.context_id::text,'device_id',v_context.device_id::text,'event_type',v_event_type,'location_id',v_context.location_id::text,'payload_json',coalesce(v_item->'payload_json','{}'::jsonb),'result',nullif(v_item->>'result',''),'scanned_at',v_event_time,'session_id',v_session.id::text,'notes',nullif(v_item->>'notes',''))::text,'UTF8'),'sha256'),'hex');
      insert into public.custodial_offline_scan_event_evidence(client_event_id,context_id,reconciliation_id,session_id,event_fingerprint,event_payload) values(v_event_id,v_context.context_id,v_reconciliation_id,v_session.id,v_event_fingerprint,v_item);
      insert into public.scan_events(scanned_at,location_id,location_code,device_id,device_identifier,session_id,event_type,result,notes,payload_json,client_event_id) values(v_event_time,v_context.location_id,v_context.canonical_location_code,v_context.device_id,v_device.device_id,v_session.id,v_event_type,nullif(v_item->>'result',''),nullif(v_item->>'notes',''),coalesce(v_item->'payload_json','{}'::jsonb)||jsonb_build_object('offline_occurrence_id',v_context.occurrence_id),v_event_id);
    end loop;
    update public.custodial_offline_actor_contexts set status='committed' where context_id=v_context.context_id and status='activated';
    update public.custodial_offline_submission_proofs set state='consumed',consumed_at=now() where context_id=v_context.context_id and state='issued';
    insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,evidence_json) values(v_reconciliation_id,'accepted',jsonb_build_object('occurrence_fingerprint',v_context.occurrence_fingerprint,'payload_fingerprint',v_payload_fingerprint));
  exception when exclusion_violation then
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'overlapping_employee_or_device_occurrence','{}'::jsonb,p_backend_execution_secret);
  when others then
    v_failure_detail := sqlerrm;
    return public.custodial_quarantine_offline_submission(v_client_session_id,v_client_completion_id,v_context.context_id,v_payload_fingerprint,jsonb_build_object('response_json',p_response_json,'scan_evidence',p_scan_evidence),'operational_commit_exception',jsonb_build_object('detail',v_failure_detail),p_backend_execution_secret);
  end;
  return v_result || jsonb_build_object('reconciliation_id',v_reconciliation_id);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_completion_assert_taxonomy(p_response jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t jsonb; v_catalog jsonb; v_digest text; v_area text;
 v_raw jsonb; v_selections jsonb; v_item jsonb; v_label text; v_id text; i integer; v_kind text;
begin
 if not (p_response ? 'taxonomy') then return; end if;
 t:=p_response->'taxonomy';
 if jsonb_typeof(t) is distinct from 'object'
   or jsonb_typeof(t->'version') is distinct from 'string'
   or jsonb_typeof(t->'digest') is distinct from 'string' then
  raise exception using errcode='22023',message='completion taxonomy metadata is malformed';
 end if;
 select c.catalog_json,c.catalog_sha256 into v_catalog,v_digest
 from public.custodial_completion_taxonomy_versions c where c.version=t->>'version';
 if not found or t->>'digest' is distinct from v_digest then
  raise exception using errcode='22023',message='completion taxonomy version or digest is unavailable';
 end if;
 v_area:=p_response->>'form_type';
 if v_area not in ('restroom','exhibit') or v_catalog->'areas'->v_area is null then
  raise exception using errcode='22023',message='completion taxonomy area is invalid';
 end if;
 for v_kind in select unnest(array['services','issues']::text[]) loop
  v_raw:=p_response->(case when v_kind='services' then 'services_performed' else 'maintenance_issues_found' end);
  v_selections:=t->v_kind;
  if jsonb_typeof(v_raw) is distinct from 'array' or jsonb_typeof(v_selections) is distinct from 'array'
    or jsonb_array_length(v_raw)<>jsonb_array_length(v_selections) then
   raise exception using errcode='22023',message='completion taxonomy selections do not match raw answers';
  end if;
  for i in 0..jsonb_array_length(v_raw)-1 loop
   v_item:=v_selections->i;
   if jsonb_typeof(v_raw->i) is distinct from 'string' or jsonb_typeof(v_item) is distinct from 'object'
    or jsonb_typeof(v_item->'id') is distinct from 'string'
    or jsonb_typeof(v_item->'label') is distinct from 'string' then
    raise exception using errcode='22023',message='completion taxonomy selection is malformed';
   end if;
   v_label:=v_raw->>i; v_id:=v_item->>'id';
   if v_item->>'label' is distinct from v_label or btrim(v_label)='' then
    raise exception using errcode='22023',message='completion taxonomy selection changed the original answer';
   end if;
   if v_kind='services' and v_id='OTHER' then
    if exists(select 1 from jsonb_array_elements(v_catalog->'areas'->v_area->v_kind) known
      where known->>'label'=v_label) then
     raise exception using errcode='22023',message='known completion service cannot be classified OTHER';
    end if;
   elsif not exists(select 1 from jsonb_array_elements(v_catalog->'areas'->v_area->v_kind) known
      where known->>'id'=v_id and known->>'label'=v_label) then
    raise exception using errcode='22023',message='completion taxonomy selection is not in this version';
   end if;
  end loop;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_control_release_canary(p_manager_id uuid, p_request_id uuid, p_device_identifier text, p_action text, p_reason text, p_authoritative_health jsonb, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_device text:=upper(btrim(coalesce(p_device_identifier,''))); v_existing public.custodial_release_canary_rollback_audits%rowtype;
  v_entry public.custodial_release_authority_restore_inventory%rowtype; v_entries public.custodial_release_authority_restore_inventory[]; v_result jsonb; v_restored integer:=0;
  v_secret_digest text; v_health jsonb; v_transport jsonb;
begin
  select execution_secret_digest into v_secret_digest from public.custodial_backend_execution_config where config_key=true and enabled=true;
  if v_secret_digest is null or length(coalesce(p_backend_execution_secret,''))<32 or encode(extensions.digest(convert_to(p_backend_execution_secret,'UTF8'),'sha256'),'hex')<>v_secret_digest then raise exception using errcode='42501',message='backend execution secret is not authorized'; end if;
  if not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id and m.active and m.revoked_at is null and m.roles && array['DIRECTOR','SECURITY_ADMIN']::text[]) then raise exception using errcode='42501',message='named release manager authority is required'; end if;
  if p_request_id is null or v_device !~ '^KIOSK_(0[2-9]|10)$' or p_action not in ('pause_canary','resume_canary','restore_authority') or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 or jsonb_typeof(p_authoritative_health)<>'object' then raise exception using errcode='22023',message='stable request, exact canary, supported action, reason, and authority health are required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-release-canary:'||v_device,0));
  select * into v_existing from public.custodial_release_canary_rollback_audits where requested_by_manager_id=p_manager_id and request_id=p_request_id for update;
  if found then
    if v_existing.device_identifier<>v_device or v_existing.action<>p_action or v_existing.reason<>btrim(p_reason) or v_existing.authoritative_health<>p_authoritative_health then raise exception using errcode='23505',message='release control request identity is already bound to different inputs'; end if;
    return v_existing.result_json||jsonb_build_object('audit_id',v_existing.audit_id,'replayed',true);
  end if;
  if p_action='pause_canary' then
    insert into public.custodial_release_canary_controls(device_identifier,paused,updated_by_manager_id,reason,last_transport_probe_id) values(v_device,true,p_manager_id,btrim(p_reason),null) on conflict(device_identifier) do update set paused=true,updated_at=statement_timestamp(),updated_by_manager_id=excluded.updated_by_manager_id,reason=excluded.reason,last_transport_probe_id=null;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',true,'restored_objects',0);
  elsif p_action='restore_authority' then
    if not coalesce((select paused from public.custodial_release_canary_controls where device_identifier=v_device),false) then raise exception using errcode='55000',message='the exact release canary must be paused before authority restoration'; end if;
    select array_agg(i order by i.restore_order,i.object_identity) into v_entries from public.custodial_release_authority_restore_inventory i;
    foreach v_entry in array v_entries loop
      if encode(extensions.digest(convert_to(v_entry.definition_sql,'UTF8'),'sha256'),'hex')<>v_entry.definition_sha256 then raise exception using errcode='23514',message='a captured authority restoration definition failed its digest'; end if;
      execute v_entry.definition_sql; v_restored:=v_restored+1;
    end loop;
    update public.custodial_release_canary_controls set updated_at=statement_timestamp(),updated_by_manager_id=p_manager_id,reason=btrim(p_reason),last_transport_probe_id=null where device_identifier=v_device;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',true,'restored_objects',v_restored);
  else
    v_health:=public.custodial_run_release_canary_recovery_probe(v_device,p_backend_execution_secret);
    if coalesce((v_health->>'passed')::boolean,false) is not true then raise exception using errcode='55000',message='fresh persisted database recovery probe is green before canary resume'; end if;
    v_transport:=public.custodial_get_release_canary_transport_probe_health(v_device,p_authoritative_health#>>'{scan_rpc_transport,backend_commit_sha}',p_authoritative_health#>>'{scan_rpc_transport,release_id}',p_backend_execution_secret);
    if coalesce((v_transport->>'ready')::boolean,false) is not true then raise exception using errcode='55000',message='fresh native phone transport proof is required before canary resume'; end if;
    update public.custodial_release_canary_controls set paused=false,updated_at=statement_timestamp(),updated_by_manager_id=p_manager_id,reason=btrim(p_reason),last_transport_probe_id=(v_transport->>'probe_id')::uuid where device_identifier=v_device and paused=true;
    if not found then raise exception using errcode='55000',message='the exact release canary must be paused before resume'; end if;
    v_result:=jsonb_build_object('device_identifier',v_device,'canary_paused',false,'restored_objects',0,'verified_authoritative_health',v_health,'verified_transport_health',v_transport);
  end if;
  insert into public.custodial_release_canary_rollback_audits(requested_by_manager_id,request_id,device_identifier,action,reason,authoritative_health,result_json) values(p_manager_id,p_request_id,v_device,p_action,btrim(p_reason),p_authoritative_health,v_result) returning audit_id into v_existing.audit_id;
  return v_result||jsonb_build_object('audit_id',v_existing.audit_id,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_create_employee(p_display_name text, p_employee_code text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_changed_by_manager_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_name text := regexp_replace(btrim(coalesce(p_display_name, '')), '\s+', ' ', 'g');
  v_code text := upper(btrim(coalesce(p_employee_code, '')));
  v_employee public.employees%rowtype;
  v_user public.msg_users%rowtype;
begin
  v_manager := public.custodial_assert_manager(p_changed_by_manager_id);
  if length(v_name) < 2 or length(v_name) > 160 then
    raise exception using errcode = '22023', message = 'Employee name must be between 2 and 160 characters.';
  end if;
  if exists (select 1 from public.employees where lower(btrim(display_name)) = lower(v_name)) then
    raise exception using errcode = '23505', message = 'An employee record with that name already exists. Reactivate the existing record instead.';
  end if;
  if v_code = '' then v_code := public.custodial_next_employee_code(); end if;
  if v_code is null or v_code !~ '^EMP[0-9]{3,6}$' then
    raise exception using errcode = '22023', message = 'Employee code must use the EMP number format, such as EMP010.';
  end if;
  if exists (select 1 from public.employees where upper(coalesce(employee_code, '')) = v_code) then
    raise exception using errcode = '23505', message = 'That employee code is already in use.';
  end if;

  insert into public.employees(employee_code, display_name, active, role, notes)
  values (v_code, v_name, true, 'staff', nullif(btrim(coalesce(p_notes, '')), ''))
  returning * into v_employee;

  insert into public.msg_users(employee_id, display_name, role, is_active)
  values (v_employee.id, v_employee.display_name, 'employee', true)
  returning * into v_user;

  insert into public.custodial_employee_status_history(
    employee_id, employee_name, previous_active, new_active,
    changed_by_manager_id, change_reason, source, metadata_json
  ) values (
    v_employee.id, v_employee.display_name, null, true,
    v_manager.manager_id, 'employee_created', 'operations_app',
    jsonb_build_object('employee_code', v_employee.employee_code, 'msg_user_id', v_user.id)
  );

  return jsonb_build_object(
    'created', true,
    'employee', to_jsonb(v_employee),
    'messenger_user_id', v_user.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION custodial_dr.guard_release_selection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'custodial_dr'
AS $function$
declare paused boolean;
begin
  -- The shared control-row lock prevents a paused writer from committing a
  -- staging row after a concurrent resume has already checked its population.
  select mutations_paused into paused from custodial_dr.restore_control
    where singleton=true for share;
  if not found then raise exception 'release selection requires restore control'; end if;
  new.recovery_staged:=paused;
  return new;
end $function$

CREATE OR REPLACE FUNCTION custodial_dr.require_single_release_on_resume()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'custodial_dr'
AS $function$
declare deployed_count integer;
begin
  if new.mutations_paused=false then
    select count(*) into deployed_count from public.release_deployment_manifest where status='deployed';
    if deployed_count<>1 then
      raise exception 'release reconciliation requires exactly one deployed identity, found %',deployed_count;
    end if;
    -- The updated control row is visible here. Each release guard therefore
    -- clears its staging marker; the unique index independently enforces it.
    update public.release_deployment_manifest set recovery_staged=false where recovery_staged;
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_evaluate_location_proximity_measurement(p_location_code text, p_device_identifier text, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_session_uuid text DEFAULT NULL::text, p_client_event_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_presented_device text := nullif(btrim(coalesce(p_device_identifier, '')), '');
  v_resolved_location_code text := public.resolve_scan_location_code(p_location_code);
  v_device_pk uuid;
  v_device_id text;
  v_location_id uuid;
  v_location_name text;
  v_session_id uuid;
  v_target_lat numeric;
  v_target_lon numeric;
  v_coordinate_source text;
  v_radius numeric := greatest(25, public.get_setting_int('gps_proximity_radius_m', 175));
  v_max_accuracy numeric := greatest(25, public.get_setting_int('gps_max_accuracy_m', 100));
  v_distance numeric;
  v_effective_radius numeric;
  v_result text;
  v_badge_color text;
  v_event_id uuid;
  v_session_key text := coalesce(nullif(btrim(p_session_uuid), ''), '');
begin
  if v_presented_device is null then raise exception 'device identifier is required'; end if;
  if v_resolved_location_code is null then raise exception 'Active location not found for code: %', p_location_code; end if;
  if p_latitude is null or p_latitude < -90 or p_latitude > 90 then raise exception 'latitude is invalid'; end if;
  if p_longitude is null or p_longitude < -180 or p_longitude > 180 then raise exception 'longitude is invalid'; end if;
  if p_accuracy_m is not null and p_accuracy_m < 0 then raise exception 'accuracy_m cannot be negative'; end if;

  select d.id, d.device_id
    into v_device_pk, v_device_id
  from public.devices d
  where d.active = true and upper(btrim(d.device_id)) = upper(v_presented_device)
  union all
  select d.id, d.device_id
  from public.device_aliases da
  join public.devices d on d.id = da.canonical_device_id and d.active = true
  where da.active = true and upper(btrim(da.alias_identifier)) = upper(v_presented_device)
  limit 1;
  if v_device_pk is null then raise exception 'Active device not found: %', v_presented_device; end if;

  select l.id, l.location_name
    into v_location_id, v_location_name
  from public.locations l
  where l.active = true and l.location_code = v_resolved_location_code
  limit 1;

  if v_session_key <> '' then
    select s.id into v_session_id
    from public.sessions s
    where s.session_uuid = v_session_key
      and s.device_id = v_device_pk
      and s.location_id = v_location_id
    limit 1;
    if v_session_id is null and public.custodial_gps_session_state(
      v_resolved_location_code,v_presented_device,v_session_key
    ) is null then
      raise exception 'Session does not belong to this device and location';
    end if;
  end if;

  select lp.latitude, lp.longitude,
         coalesce(nullif(lp.coordinate_source, ''), 'location_proximity_settings')
    into v_target_lat, v_target_lon, v_coordinate_source
  from public.location_proximity_settings lp
  where lp.location_id = v_location_id
    and lp.active = true
    and lp.latitude is not null
    and lp.longitude is not null
  order by lp.updated_at desc
  limit 1;

  if v_target_lat is null or v_target_lon is null then
    select gp.latitude, gp.longitude,
           coalesce(nullif(gp.coordinate_source, ''), 'location_group_proximity_settings')
      into v_target_lat, v_target_lon, v_coordinate_source
    from public.location_group_memberships gm
    join public.location_groups lg on lg.id = gm.location_group_id and lg.active = true
    join public.location_group_proximity_settings gp
      on gp.location_group_id = lg.id
     and gp.active = true
     and gp.latitude is not null
     and gp.longitude is not null
    where gm.location_id = v_location_id and gm.active = true
    order by gp.updated_at desc, lg.group_name
    limit 1;
  end if;

  if v_target_lat is null or v_target_lon is null then
    v_result := 'not_configured';
    v_badge_color := 'amber';
    v_effective_radius := v_radius;
  else
    v_distance := 6371000 * 2 * asin(sqrt(
      power(sin(radians((p_latitude - v_target_lat)::double precision) / 2), 2)
      + cos(radians(v_target_lat::double precision))
      * cos(radians(p_latitude::double precision))
      * power(sin(radians((p_longitude - v_target_lon)::double precision) / 2), 2)
    ));
    v_effective_radius := v_radius + least(greatest(coalesce(p_accuracy_m, 0), 0), 25);
    if p_accuracy_m is not null and p_accuracy_m > v_max_accuracy then
      v_result := 'low_accuracy';
      v_badge_color := 'amber';
    elsif v_distance <= v_effective_radius then
      v_result := 'near';
      v_badge_color := 'green';
    else
      v_result := 'away';
      v_badge_color := 'red';
    end if;
  end if;

  insert into public.device_location_proximity_status(
    device_id, location_id, session_uuid, presented_identifier, result, badge_color,
    distance_m, allowed_radius_m, accuracy_m, client_latitude, client_longitude,
    target_latitude, target_longitude, coordinate_source, evaluated_at,
    correlation_id, metadata_json
  ) values (
    v_device_pk, v_location_id, v_session_key, v_presented_device, v_result, v_badge_color,
    v_distance, v_effective_radius, p_accuracy_m, p_latitude, p_longitude,
    v_target_lat, v_target_lon, v_coordinate_source, now(),
    nullif(btrim(coalesce(p_correlation_id, '')), ''),
    jsonb_build_object('location_code', v_resolved_location_code, 'location_name', v_location_name)
  )
  on conflict (device_id, location_id, session_uuid) do update set
    presented_identifier = excluded.presented_identifier,
    result = excluded.result,
    badge_color = excluded.badge_color,
    distance_m = excluded.distance_m,
    allowed_radius_m = excluded.allowed_radius_m,
    accuracy_m = excluded.accuracy_m,
    client_latitude = excluded.client_latitude,
    client_longitude = excluded.client_longitude,
    target_latitude = excluded.target_latitude,
    target_longitude = excluded.target_longitude,
    coordinate_source = excluded.coordinate_source,
    evaluated_at = now(),
    correlation_id = excluded.correlation_id,
    metadata_json = excluded.metadata_json;

  if p_client_event_id is not null then
    select se.id into v_event_id
    from public.scan_events se
    where se.client_event_id = p_client_event_id
    limit 1;
  end if;

  if v_event_id is null then
    insert into public.scan_events(
      scanned_at, location_id, location_code, device_id, device_identifier,
      session_id, event_type, result, notes, payload_json, client_event_id
    ) values (
      now(), v_location_id, v_resolved_location_code, v_device_pk, v_device_id,
      v_session_id, 'work_position_check', v_result,
      case
        when v_result = 'away' then format('Phone is %s meters from the authoritative location coordinate.', round(v_distance))
        when v_result = 'near' then 'Phone is within the authoritative location radius.'
        when v_result = 'low_accuracy' then 'GPS accuracy is too low for a green proximity result.'
        else 'No authoritative GPS coordinate is configured for this location.'
      end,
      jsonb_build_object(
        'session_uuid', nullif(v_session_key, ''),
        'client_session_id', nullif(v_session_key, ''),
        'distance_m', v_distance,
        'allowed_radius_m', v_effective_radius,
        'accuracy_m', p_accuracy_m,
        'client_latitude', p_latitude,
        'client_longitude', p_longitude,
        'target_latitude', v_target_lat,
        'target_longitude', v_target_lon,
        'coordinate_source', v_coordinate_source,
        'badge_color', v_badge_color,
        'correlation_id', p_correlation_id
      ),
      nullif(btrim(coalesce(p_client_event_id, '')), '')
    ) returning id into v_event_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'result', v_result,
    'badge_color', v_badge_color,
    'device_id', v_device_id,
    'presented_device_id', v_presented_device,
    'location_code', v_resolved_location_code,
    'location_name', v_location_name,
    'session_uuid', nullif(v_session_key, ''),
    'distance_m', case when v_distance is null then null else round(v_distance, 1) end,
    'allowed_radius_m', round(v_effective_radius, 1),
    'accuracy_m', p_accuracy_m,
    'target_latitude', v_target_lat,
    'target_longitude', v_target_lon,
    'coordinate_source', v_coordinate_source,
    'evaluated_at', now(),
    'scan_event_id', v_event_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_evaluate_location_proximity_v2_measurement(p_location_code text, p_device_identifier text, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_session_uuid text DEFAULT NULL::text, p_client_event_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_observed_at timestamptz := coalesce(p_observed_at, clock_timestamp());
  v_presented_device text := nullif(btrim(coalesce(p_device_identifier, '')), '');
  v_resolved_location_code text := public.resolve_scan_location_code(p_location_code);
  v_device_pk uuid;
  v_device_id text;
  v_location_id uuid;
  v_location_name text;
  v_session_id uuid;
  v_target_lat numeric;
  v_target_lon numeric;
  v_coordinate_source text;
  v_radius numeric := greatest(25, public.get_setting_int('gps_proximity_radius_m', 175));
  v_max_accuracy numeric := greatest(25, public.get_setting_int('gps_max_accuracy_m', 100));
  v_max_age_seconds numeric := greatest(30, public.get_setting_int('gps_max_observation_age_seconds', 120));
  v_future_tolerance_seconds numeric := greatest(0, public.get_setting_int('gps_future_tolerance_seconds', 30));
  v_boundary_hysteresis numeric := greatest(5, public.get_setting_int('gps_boundary_hysteresis_m', 15));
  v_max_human_speed numeric := greatest(2, public.get_setting_int('gps_max_human_speed_mps', 12));
  v_distance numeric;
  v_uncertainty numeric;
  v_observation_age_seconds numeric;
  v_previous_lat numeric;
  v_previous_lon numeric;
  v_previous_accuracy_m numeric;
  v_previous_observed_at timestamptz;
  v_motion_distance_m numeric;
  v_motion_effective_distance_m numeric;
  v_motion_elapsed_seconds numeric;
  v_motion_speed_mps numeric;
  v_status_observed_at timestamptz;
  v_result text;
  v_badge_color text;
  v_event_id uuid;
  v_session_key text := coalesce(nullif(btrim(p_session_uuid), ''), '');
  v_authoritative boolean := false;
begin
  if v_presented_device is null then raise exception 'device identifier is required'; end if;
  if v_resolved_location_code is null then raise exception 'Active location not found for code: %', p_location_code; end if;
  if p_latitude is null or p_latitude < -90 or p_latitude > 90 then raise exception 'latitude is invalid'; end if;
  if p_longitude is null or p_longitude < -180 or p_longitude > 180 then raise exception 'longitude is invalid'; end if;
  if p_accuracy_m is not null and p_accuracy_m < 0 then raise exception 'accuracy_m cannot be negative'; end if;

  select d.id, d.device_id into v_device_pk, v_device_id
  from public.devices d
  where d.active = true and upper(btrim(d.device_id)) = upper(v_presented_device)
  union all
  select d.id, d.device_id
  from public.device_aliases da
  join public.devices d on d.id = da.canonical_device_id and d.active = true
  where da.active = true and upper(btrim(da.alias_identifier)) = upper(v_presented_device)
  limit 1;
  if v_device_pk is null then raise exception 'Active device not found: %', v_presented_device; end if;

  select l.id, l.location_name into v_location_id, v_location_name
  from public.locations l
  where l.active = true and l.location_code = v_resolved_location_code
  limit 1;

  if v_session_key <> '' then
    select s.id into v_session_id
    from public.sessions s
    where s.session_uuid = v_session_key
      and s.device_id = v_device_pk
      and s.location_id = v_location_id
    limit 1;
    if v_session_id is null and public.custodial_gps_session_state(
      v_resolved_location_code,v_presented_device,v_session_key
    ) is null then
      raise exception 'Session does not belong to this device and location';
    end if;
  end if;

  select lp.latitude, lp.longitude, coalesce(nullif(lp.coordinate_source, ''), 'location_proximity_settings')
  into v_target_lat, v_target_lon, v_coordinate_source
  from public.location_proximity_settings lp
  where lp.location_id = v_location_id
    and lp.active = true
    and lp.latitude is not null
    and lp.longitude is not null
  order by lp.updated_at desc
  limit 1;

  if v_target_lat is null or v_target_lon is null then
    select gp.latitude, gp.longitude, coalesce(nullif(gp.coordinate_source, ''), 'location_group_proximity_settings')
    into v_target_lat, v_target_lon, v_coordinate_source
    from public.location_group_memberships gm
    join public.location_groups lg on lg.id = gm.location_group_id and lg.active = true
    join public.location_group_proximity_settings gp
      on gp.location_group_id = lg.id
     and gp.active = true
     and gp.latitude is not null
     and gp.longitude is not null
    where gm.location_id = v_location_id and gm.active = true
    order by gp.updated_at desc, lg.group_name
    limit 1;
  end if;

  select s.client_latitude, s.client_longitude, s.accuracy_m, coalesce(s.observed_at, s.evaluated_at)
  into v_previous_lat, v_previous_lon, v_previous_accuracy_m, v_previous_observed_at
  from public.device_location_proximity_status s
  where s.device_id = v_device_pk
    and s.location_id = v_location_id
    and s.session_uuid = v_session_key
    and s.result in ('near', 'away', 'boundary_uncertain')
  limit 1;

  v_observation_age_seconds := extract(epoch from (v_now - v_observed_at));
  -- A client clock that is ahead must not pin the current-status row into the
  -- future and suppress later legitimate observations. The unmodified client
  -- timestamp remains in the scan event and metadata for audit evidence.
  v_status_observed_at := least(v_observed_at, v_now);
  v_uncertainty := greatest(v_boundary_hysteresis, least(greatest(coalesce(p_accuracy_m, 0), 0), v_max_accuracy));

  if v_target_lat is not null and v_target_lon is not null then
    v_distance := 6371000 * 2 * asin(sqrt(
      power(sin(radians((p_latitude - v_target_lat)::double precision) / 2), 2)
      + cos(radians(v_target_lat::double precision)) * cos(radians(p_latitude::double precision))
      * power(sin(radians((p_longitude - v_target_lon)::double precision) / 2), 2)
    ));
  end if;

  if v_previous_lat is not null
     and v_previous_lon is not null
     and v_previous_observed_at is not null
     and v_observed_at > v_previous_observed_at then
    v_motion_elapsed_seconds := extract(epoch from (v_observed_at - v_previous_observed_at));
    v_motion_distance_m := 6371000 * 2 * asin(sqrt(
      power(sin(radians((p_latitude - v_previous_lat)::double precision) / 2), 2)
      + cos(radians(v_previous_lat::double precision)) * cos(radians(p_latitude::double precision))
      * power(sin(radians((p_longitude - v_previous_lon)::double precision) / 2), 2)
    ));
    v_motion_effective_distance_m := greatest(
      0,
      v_motion_distance_m - greatest(coalesce(p_accuracy_m, 0), 0) - greatest(coalesce(v_previous_accuracy_m, 0), 0)
    );
    v_motion_speed_mps := v_motion_effective_distance_m / greatest(v_motion_elapsed_seconds, 0.001);
  end if;

  if v_observation_age_seconds < -v_future_tolerance_seconds then
    v_result := 'future_clock'; v_badge_color := 'amber';
  elsif v_observation_age_seconds > v_max_age_seconds then
    v_result := 'stale'; v_badge_color := 'amber';
  elsif p_accuracy_m is null or p_accuracy_m > v_max_accuracy then
    v_result := 'low_accuracy'; v_badge_color := 'amber';
  elsif v_target_lat is null or v_target_lon is null then
    v_result := 'not_configured'; v_badge_color := 'amber';
  elsif v_motion_speed_mps is not null and v_motion_speed_mps > v_max_human_speed then
    v_result := 'implausible_jump'; v_badge_color := 'amber';
  elsif abs(v_distance - v_radius) <= v_uncertainty then
    v_result := 'boundary_uncertain'; v_badge_color := 'amber';
  elsif v_distance < v_radius then
    v_result := 'near'; v_badge_color := 'green'; v_authoritative := true;
  else
    v_result := 'away'; v_badge_color := 'red'; v_authoritative := true;
  end if;

  insert into public.device_location_proximity_status(
    device_id, location_id, session_uuid, presented_identifier, result, badge_color,
    distance_m, allowed_radius_m, accuracy_m, client_latitude, client_longitude,
    target_latitude, target_longitude, coordinate_source, observed_at,
    observation_age_seconds, motion_speed_mps, evaluated_at, correlation_id, metadata_json
  ) values (
    v_device_pk, v_location_id, v_session_key, v_presented_device, v_result, v_badge_color,
    v_distance, v_radius, p_accuracy_m, p_latitude, p_longitude,
    v_target_lat, v_target_lon, v_coordinate_source, v_status_observed_at,
    v_observation_age_seconds, v_motion_speed_mps, v_now,
    nullif(btrim(coalesce(p_correlation_id, '')), ''),
    jsonb_build_object(
      'location_code', v_resolved_location_code,
      'location_name', v_location_name,
      'authoritative', v_authoritative,
      'reported_observed_at', v_observed_at,
      'boundary_uncertainty_m', v_uncertainty,
      'motion_distance_m', v_motion_distance_m,
      'motion_effective_distance_m', v_motion_effective_distance_m
    )
  )
  on conflict(device_id, location_id, session_uuid) do update set
    presented_identifier = excluded.presented_identifier,
    result = excluded.result,
    badge_color = excluded.badge_color,
    distance_m = excluded.distance_m,
    allowed_radius_m = excluded.allowed_radius_m,
    accuracy_m = excluded.accuracy_m,
    client_latitude = excluded.client_latitude,
    client_longitude = excluded.client_longitude,
    target_latitude = excluded.target_latitude,
    target_longitude = excluded.target_longitude,
    coordinate_source = excluded.coordinate_source,
    observed_at = excluded.observed_at,
    observation_age_seconds = excluded.observation_age_seconds,
    motion_speed_mps = excluded.motion_speed_mps,
    evaluated_at = excluded.evaluated_at,
    correlation_id = excluded.correlation_id,
    metadata_json = excluded.metadata_json
  where excluded.observed_at >= coalesce(device_location_proximity_status.observed_at, device_location_proximity_status.evaluated_at);

  insert into public.scan_events(
      scanned_at, location_id, location_code, device_id, device_identifier,
      session_id, event_type, result, notes, payload_json, client_event_id
    ) values (
      v_now, v_location_id, v_resolved_location_code, v_device_pk, v_device_id,
      v_session_id, 'work_position_check', v_result,
      case
        when v_result = 'away' then format('Phone is %s meters from the authoritative location coordinate.', round(v_distance))
        when v_result = 'near' then 'Phone is within the authoritative location radius.'
        when v_result = 'boundary_uncertain' then 'Phone is near the GPS boundary; location remains advisory until a clearer reading arrives.'
        when v_result = 'low_accuracy' then 'GPS accuracy is too low for an authoritative proximity result.'
        when v_result = 'stale' then 'GPS observation is stale and was not accepted as current position.'
        when v_result = 'future_clock' then 'GPS observation timestamp is ahead of server time.'
        when v_result = 'implausible_jump' then 'GPS movement is implausibly fast and requires a fresh reading.'
        else 'No authoritative GPS coordinate is configured for this location.'
      end,
      jsonb_build_object(
        'session_uuid', nullif(v_session_key, ''),
        'client_session_id', nullif(v_session_key, ''),
        'distance_m', v_distance,
        'allowed_radius_m', v_radius,
        'accuracy_m', p_accuracy_m,
        'client_latitude', p_latitude,
        'client_longitude', p_longitude,
        'target_latitude', v_target_lat,
        'target_longitude', v_target_lon,
        'coordinate_source', v_coordinate_source,
        'badge_color', v_badge_color,
        'authoritative', v_authoritative,
        'observed_at', v_observed_at,
        'observation_age_seconds', v_observation_age_seconds,
        'motion_speed_mps', v_motion_speed_mps,
        'motion_distance_m', v_motion_distance_m,
        'motion_effective_distance_m', v_motion_effective_distance_m,
        'correlation_id', p_correlation_id
      ),
      nullif(btrim(coalesce(p_client_event_id, '')), '')
    )
    on conflict(client_event_id) where client_event_id is not null do nothing
    returning id into v_event_id;

  if v_event_id is null and nullif(btrim(coalesce(p_client_event_id, '')), '') is not null then
    select se.id into v_event_id
    from public.scan_events se
    where se.client_event_id = nullif(btrim(p_client_event_id), '')
    limit 1;
  end if;

  return jsonb_build_object(
    'ok', true,
    'result', v_result,
    'authoritative', v_authoritative,
    'badge_color', v_badge_color,
    'device_id', v_device_id,
    'presented_device_id', v_presented_device,
    'location_code', v_resolved_location_code,
    'location_name', v_location_name,
    'session_uuid', nullif(v_session_key, ''),
    'distance_m', case when v_distance is null then null else round(v_distance, 1) end,
    'allowed_radius_m', round(v_radius, 1),
    'accuracy_m', p_accuracy_m,
    'target_latitude', v_target_lat,
    'target_longitude', v_target_lon,
    'coordinate_source', v_coordinate_source,
    'observed_at', v_observed_at,
    'observation_age_seconds', round(v_observation_age_seconds, 1),
    'motion_speed_mps', case when v_motion_speed_mps is null then null else round(v_motion_speed_mps, 2) end,
    'evaluated_at', v_now,
    'scan_event_id', v_event_id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_feedback_relay_attachment_internal(p_principal text, p_action text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  cfg public.system_feedback_email_relay_config%rowtype;
  item public.system_feedback_email_intents%rowtype;
  image jsonb;
  expected_sha text;
  canonical_match text[];
  observed jsonb;
  ticket uuid;
  disposition text;
  allowed text[];
begin
  if p_principal !~ '^relay:[0-9a-f]{64}$' or p_args is null or jsonb_typeof(p_args)<>'object'
    or octet_length(p_args::text)>16384 or p_args->>'adapter_schema_sha256' !~ '^[0-9a-f]{64}$'
    or p_args->>'intent_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_args->>'claim_token' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_args->>'claim_generation' !~ '^[1-9][0-9]{0,8}$'
    or p_args->>'envelope_sha256' !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='Exact private attachment admission fence required';end if;
  allowed:=case p_action when 'prepare' then array['intent_id','claim_token','claim_generation','envelope_sha256','adapter_schema_sha256']
    when 'complete' then array['intent_id','claim_token','claim_generation','envelope_sha256','adapter_schema_sha256','ticket','observed']
    when 'reject' then array['intent_id','claim_token','claim_generation','envelope_sha256','adapter_schema_sha256','ticket','disposition'] end;
  if allowed is null or exists(select 1 from jsonb_object_keys(p_args) k where not k=any(allowed))
    or exists(select 1 from unnest(allowed) k where not p_args ? k or p_args->k='null'::jsonb) then
    raise exception using errcode='22023',message='Unknown or missing private attachment admission argument';end if;
  select * into strict cfg from public.system_feedback_email_relay_config where singleton for update;
  select * into strict item from public.system_feedback_email_intents where id=(p_args->>'intent_id')::uuid for update;
  if item.claim_principal is distinct from p_principal or item.claim_token::text is distinct from p_args->>'claim_token'
    or item.claim_generation<>(p_args->>'claim_generation')::integer
    or item.envelope_sha256 is distinct from p_args->>'envelope_sha256' then
    raise exception using errcode='42501',message='Stale or foreign attachment claim';end if;
  if p_action='prepare' and item.attempt_id is not null then return '{"status":"already_attempted"}'::jsonb;end if;
  if cfg.paused or cfg.transport_principal is distinct from p_principal or cfg.transport_verified_at is null
    or cfg.transport_verified_at<now()-interval '15 minutes'
    or cfg.transport_schema_sha256 is distinct from p_args->>'adapter_schema_sha256'
    or item.state<>'claimed' or item.claim_until<=now() or item.attempt_id is not null then
    raise exception using errcode='55000',message='Private attachment preparation is paused or expired';end if;
  image:=item.feedback_snapshot->'image_attachment';
  if image is null or image='null'::jsonb then
    if p_action='prepare' then return '{"status":"no_attachment"}'::jsonb;end if;
    raise exception using errcode='22023',message='No protected attachment to attest';
  end if;
  if not public.feedback_email_attachment_source_matches(item.id) then
    update public.system_feedback_email_intents set state='needs_attention',attention_reason='attachment_source_changed',
      claim_token=null,claim_until=null,attachment_verification_state='blocked' where id=item.id;
    return '{"status":"needs_attention"}'::jsonb;
  end if;
  if p_action='prepare' then
    ticket:=gen_random_uuid();
    update public.system_feedback_email_intents set attachment_verification_ticket=ticket,
      attachment_verification_state='pending',attachment_verification_claim_token=item.claim_token,
      attachment_verification_generation=item.claim_generation,
      attachment_verification_source_digest=public.static_weekly_digest_jsonb(image),
      attachment_verification_sha256=null,attachment_verification_size=null,
      attachment_verification_type=null,attachment_verified_at=null where id=item.id;
    return jsonb_build_object('status','ready','ticket',ticket,'operation_id',item.operation_id,'image',image);
  end if;
  if p_args->>'ticket' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or item.attachment_verification_ticket::text is distinct from p_args->>'ticket'
    or item.attachment_verification_state<>'pending'
    or item.attachment_verification_claim_token is distinct from item.claim_token
    or item.attachment_verification_generation is distinct from item.claim_generation
    or item.attachment_verification_source_digest is distinct from public.static_weekly_digest_jsonb(image) then
    raise exception using errcode='42501',message='Stale private attachment verification ticket';end if;
  if p_action='reject' then
    disposition:=p_args->>'disposition';
    if disposition not in ('missing','corrupt','configuration_unavailable') or disposition is null then
      raise exception using errcode='22023',message='Typed private attachment disposition required';end if;
    if disposition='configuration_unavailable' then
      update public.system_feedback_email_relay_config set paused=true,pause_reason='attachment_storage_unavailable',updated_at=now() where singleton;
      update public.system_feedback_email_intents set state='queued',claim_token=null,claim_until=null,
        attachment_verification_state='unverified',attachment_verification_ticket=null where id=item.id;
      return '{"status":"paused"}'::jsonb;
    end if;
    update public.system_feedback_email_intents set state='needs_attention',claim_token=null,claim_until=null,
      attention_reason=case when disposition='missing' then 'protected_attachment_missing' else 'protected_attachment_corrupt' end,
      attachment_verification_state='blocked' where id=item.id;
    return '{"status":"needs_attention"}'::jsonb;
  end if;
  observed:=p_args->'observed';
  if jsonb_typeof(observed)<>'object' or
    (select count(*) from jsonb_object_keys(observed))<>3 or not(observed ?& array['sha256','size','type'])
    or observed->>'sha256' !~ '^[0-9a-f]{64}$'
    or observed->>'size' !~ '^[1-9][0-9]{0,6}$'
    or (observed->>'size')::integer>5*1024*1024
    or observed->>'type' not in ('image/png','image/jpeg','image/webp','image/gif')
    or nullif(image->>'size','')::integer is distinct from (observed->>'size')::integer
    or replace(image->>'type','image/jpg','image/jpeg') is distinct from observed->>'type' then
    raise exception using errcode='22023',message='Actual attachment size and type proof required';end if;
  canonical_match:=regexp_match(coalesce(image->>'storage_path',''),
    '^feedback/'||item.operation_id::text||'/([0-9a-f]{64})\.(png|jpg|webp|gif)$');
  expected_sha:=coalesce(nullif(image->>'sha256',''),canonical_match[1]);
  if expected_sha is not null and expected_sha is distinct from observed->>'sha256' then
    raise exception using errcode='22023',message='Actual attachment digest mismatch';end if;
  if expected_sha is null and nullif(image->>'data_url','') is null and nullif(image->>'dataUrl','') is null then
    raise exception using errcode='22023',message='No immutable attachment digest source';end if;
  update public.system_feedback_email_intents set attachment_verification_state='verified',
    attachment_verification_sha256=observed->>'sha256',attachment_verification_size=(observed->>'size')::integer,
    attachment_verification_type=observed->>'type',attachment_verified_at=now() where id=item.id;
  return '{"status":"verified"}'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_feedback_triage(p_request uuid, p_manager uuid, p_credential uuid, p_feedback uuid, p_action text, p_expected_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
 old_receipt public.system_feedback_triage_receipts%rowtype;
 item public.system_feedback_items%rowtype;
 manager public.ops_manager_managers%rowtype;
 accepted timestamptz; result jsonb;
begin
 if p_request is null or p_manager is null or p_credential is null or p_feedback is null
  or p_action is null or p_action not in ('acknowledged','resolved','closed')
  or p_expected_version is null or p_expected_version!~'^[a-f0-9]{64}$' then
  raise exception using errcode='22023',message='Exact Feedback command and version required'; end if;
 select * into manager from public.ops_manager_managers m where m.manager_id=p_manager
  and m.active and m.revoked_at is null and not m.is_system_principal
  and m.roles&&array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
 if not found then raise exception using errcode='42501',message='Current named manager required'; end if;
 perform 1 from public.ops_manager_trusted_devices d where d.credential_id=p_credential
  and d.manager_id=p_manager and d.revoked_at is null and d.expires_at>clock_timestamp()
  and d.max_access_level='full_access' for share;
 if not found then raise exception using errcode='42501',message='Current full-access manager credential required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('feedback-triage:'||p_request::text,0));
 select * into old_receipt from public.system_feedback_triage_receipts where request_id=p_request;
 if found then
  if old_receipt.feedback_id<>p_feedback or old_receipt.manager_id<>p_manager
   or old_receipt.credential_id<>p_credential or old_receipt.action<>p_action
   or old_receipt.expected_version<>p_expected_version then
   raise exception using errcode='40001',message='Feedback request identity conflict'; end if;
  return jsonb_build_object('ok',true,'replayed',true,'receipt',old_receipt.receipt);
 end if;
 select * into item from public.system_feedback_items where id=p_feedback for update;
 if not found then raise exception using errcode='P0002',message='Feedback item unavailable'; end if;
 if public.custodial_feedback_triage_version(item.status,item.updated_at)<>p_expected_version
  or item.status='closed' or item.status=p_action
  or (item.status='resolved' and p_action<>'closed') then
  raise exception using errcode='40001',message='Feedback changed; refresh before a new action'; end if;
 accepted:=clock_timestamp();
 update public.system_feedback_items set status=p_action,updated_at=accepted,
  acknowledged_at=case when p_action='acknowledged' then accepted else acknowledged_at end,
  acknowledged_by=case when p_action='acknowledged' then manager.display_name else acknowledged_by end,
  metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object(
   'status_changed_via','manager_feedback_inbox','status_changed_by',manager.display_name,
   'status_changed_manager_id',p_manager,'status_changed_credential_id',p_credential)
  where id=p_feedback returning * into item;
 result:=jsonb_build_object('request_id',p_request,'feedback_id',p_feedback,'status',p_action,
  'triage_version',public.custodial_feedback_triage_version(item.status,item.updated_at),
  'actor_manager_id',p_manager,'actor_credential_id',p_credential,'accepted_at',accepted);
 insert into public.system_feedback_triage_receipts
  (request_id,feedback_id,manager_id,credential_id,action,expected_version,receipt,accepted_at)
 values(p_request,p_feedback,p_manager,p_credential,p_action,p_expected_version,result,accepted);
 return jsonb_build_object('ok',true,'replayed',false,'receipt',result);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_finish_historical_session_authoritative(p_session_identifier text, p_device_id text, p_finish_operation_id uuid, p_client_ended_at timestamp with time zone, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  return public.tool_finish_session_exact(
    p_session_identifier,p_device_id,p_finish_operation_id,p_client_ended_at
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_finish_offline_reconciliation_notification_recipient(p_delivery_recipient_id uuid, p_worker_id text, p_lease_token uuid, p_succeeded boolean, p_message_id uuid, p_error text, p_retry_seconds integer, p_terminal boolean, p_delivery_evidence jsonb, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_recipient public.custodial_offline_reconciliation_delivery_recipients%rowtype;
  v_outbox public.custodial_offline_reconciliation_outbox%rowtype;
  v_worker_id text := nullif(btrim(coalesce(p_worker_id,'')), '');
  v_error text := nullif(left(btrim(coalesce(p_error,'')),500),'');
  v_retry_seconds integer := greatest(15,least(coalesce(p_retry_seconds,60),3600));
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select * into v_recipient from public.custodial_offline_reconciliation_delivery_recipients where delivery_recipient_id=p_delivery_recipient_id for update;
  if v_recipient.delivery_recipient_id is null then raise exception using errcode='P0002',message='offline reconciliation notification recipient was not found'; end if;
  select * into v_outbox from public.custodial_offline_reconciliation_outbox where outbox_id=v_recipient.outbox_id for key share;
  if v_worker_id is null or v_recipient.state<>'claimed' or v_recipient.claimed_by<>v_worker_id or v_recipient.lease_token is distinct from p_lease_token or v_recipient.lease_expires_at<=now()
     or v_outbox.state<>'claimed' or v_outbox.claimed_by<>v_worker_id or v_outbox.lease_expires_at<=now() then
    raise exception using errcode='40901',message='recipient delivery claim is no longer owned by this worker';
  end if;
  if p_succeeded is true then
    if p_message_id is null or not exists(
      select 1 from public.msg_messages m join public.msg_thread_participants tp on tp.thread_id=m.thread_id and tp.user_id=v_recipient.recipient_user_id and tp.left_at is null
      where m.id=p_message_id and m.client_message_id=v_recipient.client_message_id and m.metadata_json->>'notification_instance_key'=v_recipient.notification_instance_key
    ) then raise exception using errcode='23514',message='recipient delivery evidence must bind the stable Messenger notification identity'; end if;
    update public.custodial_offline_reconciliation_delivery_recipients
    set state='delivered',delivered_at=now(),failed_at=null,claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,last_error=null,message_id=p_message_id,
      delivery_evidence=coalesce(p_delivery_evidence,'{}'::jsonb)||jsonb_build_object('message_id',p_message_id,'client_message_id',v_recipient.client_message_id,'notification_instance_key',v_recipient.notification_instance_key)
    where delivery_recipient_id=v_recipient.delivery_recipient_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,worker_id,evidence_json)
    values(v_recipient.outbox_id,v_recipient.delivery_recipient_id,'recipient_delivered',v_recipient.attempts,v_worker_id,jsonb_build_object('message_id',p_message_id,'client_message_id',v_recipient.client_message_id));
  elsif p_terminal is true or v_recipient.attempts>=5 then
    update public.custodial_offline_reconciliation_delivery_recipients
    set state='failed',failed_at=now(),claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,last_error=coalesce(v_error,'recipient delivery reached terminal failure'),
      delivery_evidence=coalesce(p_delivery_evidence,'{}'::jsonb)
    where delivery_recipient_id=v_recipient.delivery_recipient_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,worker_id,error_text,evidence_json)
    values(v_recipient.outbox_id,v_recipient.delivery_recipient_id,'recipient_failed',v_recipient.attempts,v_worker_id,coalesce(v_error,'recipient delivery reached terminal failure'),coalesce(p_delivery_evidence,'{}'::jsonb));
  else
    update public.custodial_offline_reconciliation_delivery_recipients
    set state='retry',claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,next_attempt_at=now()+make_interval(secs=>v_retry_seconds),last_error=coalesce(v_error,'recipient delivery failed'),
      delivery_evidence=coalesce(p_delivery_evidence,'{}'::jsonb)
    where delivery_recipient_id=v_recipient.delivery_recipient_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,delivery_recipient_id,event_type,attempt,worker_id,error_text,evidence_json)
    values(v_recipient.outbox_id,v_recipient.delivery_recipient_id,'recipient_retry_scheduled',v_recipient.attempts,v_worker_id,coalesce(v_error,'recipient delivery failed'),coalesce(p_delivery_evidence,'{}'::jsonb));
  end if;
  select * into v_recipient from public.custodial_offline_reconciliation_delivery_recipients where delivery_recipient_id=v_recipient.delivery_recipient_id;
  return jsonb_build_object('delivery_recipient_id',v_recipient.delivery_recipient_id,'state',v_recipient.state,'attempts',v_recipient.attempts,'terminal',v_recipient.state in ('delivered','failed'),'message_id',v_recipient.message_id);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_finish_offline_reconciliation_notification(p_outbox_id uuid, p_worker_id text, p_lease_token uuid, p_succeeded boolean, p_error text, p_retry_seconds integer, p_terminal boolean, p_delivery_json jsonb, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_outbox public.custodial_offline_reconciliation_outbox%rowtype;
  v_worker_id text := nullif(btrim(coalesce(p_worker_id,'')), '');
  v_error text := nullif(left(btrim(coalesce(p_error,'')),500),'');
  v_retry_seconds integer := greatest(15,least(coalesce(p_retry_seconds,60),3600));
  v_recipients integer := 0;
  v_delivered integer := 0;
  v_failed integer := 0;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select * into v_outbox from public.custodial_offline_reconciliation_outbox where outbox_id=p_outbox_id for update;
  if v_outbox.outbox_id is null then raise exception using errcode='P0002',message='offline reconciliation notification was not found'; end if;
  if v_worker_id is null or v_outbox.state<>'claimed' or v_outbox.claimed_by<>v_worker_id or v_outbox.lease_token is distinct from p_lease_token or v_outbox.lease_expires_at<=now() then raise exception using errcode='40901',message='notification claim is no longer owned by this worker'; end if;
  select count(*),count(*) filter(where state='delivered'),count(*) filter(where state='failed') into v_recipients,v_delivered,v_failed
    from public.custodial_offline_reconciliation_delivery_recipients where outbox_id=v_outbox.outbox_id;
  if v_failed>0 or p_terminal is true then
    update public.custodial_offline_reconciliation_outbox
    set state='failed',failed_at=now(),claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,
      last_error=coalesce(v_error,case when v_failed>0 then 'one or more named-manager recipients are unavailable' else 'notification delivery reached terminal failure' end),delivery_json=coalesce(p_delivery_json,'{}'::jsonb)
    where outbox_id=v_outbox.outbox_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,event_type,attempt,worker_id,error_text,evidence_json)
    values(v_outbox.outbox_id,'outbox_failed',v_outbox.attempts,v_worker_id,coalesce(v_error,'notification delivery reached terminal failure'),coalesce(p_delivery_json,'{}'::jsonb));
  elsif v_recipients>0 and v_delivered=v_recipients then
    update public.custodial_offline_reconciliation_outbox
    set state='delivered',delivered_at=now(),failed_at=null,claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,last_error=null,delivery_json=coalesce(p_delivery_json,'{}'::jsonb)
    where outbox_id=v_outbox.outbox_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,event_type,attempt,worker_id,evidence_json)
    values(v_outbox.outbox_id,'outbox_delivered',v_outbox.attempts,v_worker_id,coalesce(p_delivery_json,'{}'::jsonb));
  elsif v_recipients=0 and p_succeeded is true then
    update public.custodial_offline_reconciliation_outbox
    set state='delivered',delivered_at=now(),failed_at=null,claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,last_error=null,delivery_json=coalesce(p_delivery_json,'{}'::jsonb)
    where outbox_id=v_outbox.outbox_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,event_type,attempt,worker_id,evidence_json)
    values(v_outbox.outbox_id,'outbox_delivered',v_outbox.attempts,v_worker_id,coalesce(p_delivery_json,'{}'::jsonb));
  elsif v_outbox.attempts>=5 then
    update public.custodial_offline_reconciliation_outbox
    set state='failed',failed_at=now(),claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,last_error=coalesce(v_error,'notification delivery reached maximum attempts'),delivery_json=coalesce(p_delivery_json,'{}'::jsonb)
    where outbox_id=v_outbox.outbox_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,event_type,attempt,worker_id,error_text,evidence_json)
    values(v_outbox.outbox_id,'outbox_failed',v_outbox.attempts,v_worker_id,coalesce(v_error,'notification delivery reached maximum attempts'),coalesce(p_delivery_json,'{}'::jsonb));
  else
    update public.custodial_offline_reconciliation_outbox
    set state='retry',claimed_by=null,lease_token=null,claimed_at=null,lease_expires_at=null,next_attempt_at=now()+make_interval(secs=>v_retry_seconds),last_error=coalesce(v_error,'notification delivery incomplete'),delivery_json=coalesce(p_delivery_json,'{}'::jsonb)
    where outbox_id=v_outbox.outbox_id;
    insert into public.custodial_offline_reconciliation_delivery_events(outbox_id,event_type,attempt,worker_id,error_text,evidence_json)
    values(v_outbox.outbox_id,'outbox_retry_scheduled',v_outbox.attempts,v_worker_id,coalesce(v_error,'notification delivery incomplete'),coalesce(p_delivery_json,'{}'::jsonb));
  end if;
  select * into v_outbox from public.custodial_offline_reconciliation_outbox where outbox_id=v_outbox.outbox_id;
  return jsonb_build_object('outbox_id',v_outbox.outbox_id,'state',v_outbox.state,'attempts',v_outbox.attempts,'terminal',v_outbox.state in ('delivered','failed'),'next_attempt_at',v_outbox.next_attempt_at,'failed_at',v_outbox.failed_at);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_get_device_rollback_readiness(p_device_identifier text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_device public.devices%rowtype; v_sync public.device_sync_status%rowtype; v_open_sessions integer;
begin
  select device.* into v_device
  from public.device_aliases alias
  join public.devices device on device.id=alias.canonical_device_id
  where alias.alias_identifier=btrim(p_device_identifier) and alias.active=true and device.active=true
  limit 1;
  if v_device.id is null then
    select device.* into v_device from public.devices device
    where device.device_id=btrim(p_device_identifier) and device.active=true limit 1;
  end if;
  if v_device.id is null then
    raise exception using errcode='P0002',message='Active device not found';
  end if;
  select * into v_sync from public.device_sync_status where device_id=v_device.id;
  select count(*)::integer into v_open_sessions
  from public.custodial_open_work() where device_id=v_device.id;
  return jsonb_build_object(
    'contract_version','custodial-rollback-readiness.v2','device_id',v_device.device_id,
    'backend_queue_count',coalesce(v_sync.queue_count,-1),'backend_open_session_count',v_open_sessions,
    'backend_sync_reported_at',v_sync.updated_at,
    'eligible',v_sync.device_id is not null and v_sync.updated_at>=now()-interval '5 minutes'
      and v_sync.queue_count=0 and v_open_sessions=0
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_get_release_canary_transport_probe_health(p_device_identifier text, p_backend_commit_sha text, p_release_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_device text:=upper(btrim(coalesce(p_device_identifier,'')));
  v_control public.custodial_release_canary_controls%rowtype;
  v_probe public.custodial_release_canary_transport_probes%rowtype;
  v_ready boolean:=false;
  v_reason text:='phone_transport_probe_missing';
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if v_device !~ '^KIOSK_(0[2-9]|10)$'
     or lower(btrim(coalesce(p_backend_commit_sha,''))) !~ '^[0-9a-f]{40}$'
     or length(btrim(coalesce(p_release_id,''))) not between 1 and 200 then
    raise exception using errcode='22023',message='exact canary and deployed release identity are required';
  end if;
  select * into v_control from public.custodial_release_canary_controls where device_identifier=v_device;
  if v_control.device_identifier is null then
    return jsonb_build_object('ready',false,'configured',false,'device_identifier',v_device,'reason','canary_control_not_initialized');
  end if;
  if v_control.paused then
    select p.* into v_probe from public.custodial_release_canary_transport_probes p
    join public.device_auth_credentials c on c.credential_id=p.credential_id
    join public.devices d on d.id=c.device_id
    where p.device_identifier=v_device and p.control_updated_at=v_control.updated_at
      and p.backend_commit_sha=lower(btrim(p_backend_commit_sha)) and p.release_id=btrim(p_release_id)
      and p.passed and p.expires_at>statement_timestamp() and p.observed_at>=v_control.updated_at
      and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>statement_timestamp()
      and d.active=true and upper(btrim(d.device_id))=v_device
    order by p.observed_at desc,p.probe_id desc limit 1;
    if v_probe.probe_id is not null then v_ready:=true; v_reason:='fresh_paused_phone_probe'; end if;
  elsif v_control.last_transport_probe_id is not null then
    select p.* into v_probe from public.custodial_release_canary_transport_probes p
    join public.device_auth_credentials c on c.credential_id=p.credential_id
    join public.devices d on d.id=c.device_id
    where p.probe_id=v_control.last_transport_probe_id and p.device_identifier=v_device
      and p.backend_commit_sha=lower(btrim(p_backend_commit_sha)) and p.release_id=btrim(p_release_id)
      and p.passed and c.confirmed_at is not null and c.revoked_at is null
      and c.expires_at>statement_timestamp() and d.active=true and upper(btrim(d.device_id))=v_device;
    if v_probe.probe_id is not null then v_ready:=true; v_reason:='resume_bound_phone_probe'; end if;
  end if;
  return jsonb_build_object(
    'ready',v_ready,'configured',true,'device_identifier',v_device,'canary_paused',v_control.paused,
    'reason',v_reason,'probe_id',v_probe.probe_id,'credential_id',v_probe.credential_id,
    'observed_at',v_probe.observed_at,'expires_at',v_probe.expires_at,
    'backend_commit_sha',v_probe.backend_commit_sha,'release_id',v_probe.release_id,
    'route_path',v_probe.route_path,'probe_function',v_probe.probe_function
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_legacy_activation_bind(p_operation uuid, p_device uuid, p_credential uuid, p_token_hash text, p_installation_digest text, p_native_request uuid, p_attestation_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare authority jsonb; b public.custodial_activation_legacy_lineage_bindings%rowtype;
begin
 authority:=public.custodial_legacy_activation_context(p_operation,p_device,p_credential,p_token_hash);
 if p_installation_digest is null or p_installation_digest !~ '^[0-9a-f]{64}$' or p_native_request is null
  or p_attestation_digest is null or p_attestation_digest !~ '^[0-9a-f]{64}$'
  then raise exception 'exact native installation attestation required'; end if;
 select * into b from public.custodial_activation_legacy_lineage_bindings where activation_operation_id=p_operation;
 if b.binding_id is not null then
  if (b.device_id,b.authenticated_credential_id,b.installation_binding_sha256,b.binding_kind,b.source_enrollment_operation_id,
    b.current_recovery_operation_id,b.expected_employee_id,b.expected_assignment_epoch)
   is distinct from (p_device,p_credential,p_installation_digest,authority->>'binding_kind',
    (authority->>'source_enrollment_operation_id')::uuid,(authority->>'current_recovery_operation_id')::uuid,
    (authority->>'employee_id')::uuid,(authority->>'assignment_epoch')::bigint)
   then raise exception 'legacy installation binding conflict'; end if;
  return public.custodial_legacy_activation_binding_json(b);
 end if;
 if authority->>'state' not in ('prepared','delivered','delivery_unknown')
  then raise exception 'cannot create legacy binding for terminal operation'; end if;
 insert into public.custodial_activation_legacy_lineage_bindings(activation_operation_id,binding_kind,device_id,
  authenticated_credential_id,installation_binding_sha256,source_enrollment_operation_id,current_recovery_operation_id,
  expected_employee_id,expected_assignment_epoch,native_request_id,native_request_attestation_sha256)
 values(p_operation,authority->>'binding_kind',p_device,p_credential,p_installation_digest,
  (authority->>'source_enrollment_operation_id')::uuid,(authority->>'current_recovery_operation_id')::uuid,
  (authority->>'employee_id')::uuid,(authority->>'assignment_epoch')::bigint,p_native_request,p_attestation_digest)
 returning * into b;
 return public.custodial_legacy_activation_binding_json(b);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_legacy_activation_context(p_operation uuid, p_device uuid, p_credential uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype; a public.custodial_assigned_activation_operations%rowtype;
 c public.device_auth_credentials%rowtype; e public.device_auth_enrollment_operations%rowtype;
 original uuid; recovery uuid; kind text:='authenticated_legacy_installation_observation';
begin
 perform public.custodial_begin_application_mutation();
 if p_operation is null or p_device is null or p_credential is null then raise exception 'exact legacy activation identity required'; end if;
 perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation::text,0));
 select * into strict d from public.devices where id=p_device for update;
 perform public.custodial_activation_expire_device(p_device);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation for update;
 select * into c from public.device_auth_credentials where credential_id=p_credential and device_id=p_device
  and token_hash=p_token_hash and confirmed_at is not null and revoked_at is null and expires_at>now() for update;
 if c.credential_id is null or a.device_id is distinct from p_device or d.active is not true
  or a.expected_employee_id is distinct from d.assigned_employee_id or a.expected_assignment_epoch is distinct from d.assignment_epoch
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$')
  then raise exception using errcode='42501',message='current exact assigned legacy credential required'; end if;
 if a.state not in ('prepared','delivered','delivery_unknown','native_active','not_required') or a.claimant_credential_id is null
  then raise exception 'legacy activation is not pending or accepted'; end if;
 select * into e from public.device_auth_enrollment_operations where operation_id=p_operation;
 if e.operation_id is not null then
  if e.device_id is distinct from p_device or e.credential_id is distinct from p_credential
   or e.flow<>'recovery' or e.status<>'confirmed' or e.enrollment_id is distinct from a.enrollment_id
   then raise exception 'legacy recovery requires exact confirmed replacement'; end if;
  recovery:=p_operation;
 else
  if c.created_at>=a.requested_at or not exists(select 1 from public.device_auth_enrollment_codes
    where enrollment_id=a.enrollment_id and consumed_at is null)
   then raise exception 'legacy healthy activation must retain an existing credential'; end if;
  -- Only the exact current credential metadata may point to original proof.
  -- Merely finding a nearby enrollment for the device is not authority.
  select operation_id into original from public.device_auth_enrollment_operations
   where operation_id::text=c.metadata_json->>'enrollment_operation_id'
    and device_id=p_device and credential_id=p_credential and flow='enrollment' and status='confirmed';
  if original is not null then kind:='confirmed_enrollment_operation'; end if;
 end if;
 return jsonb_build_object('binding_kind',kind,'activation_operation_id',p_operation,'device_id',d.device_id,
  'credential_id',p_credential,'source_enrollment_operation_id',original,'current_recovery_operation_id',recovery,
  'employee_id',a.expected_employee_id,'assignment_epoch',a.expected_assignment_epoch,'state',a.state);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_legacy_activation_result(p_operation uuid, p_device uuid, p_credential uuid, p_token_hash text, p_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare authority jsonb; a public.custodial_assigned_activation_operations%rowtype;
 b public.custodial_activation_legacy_lineage_bindings%rowtype; outcome text; recovery boolean;
begin
 authority:=public.custodial_legacy_activation_context(p_operation,p_device,p_credential,p_token_hash);
 select * into strict a from public.custodial_assigned_activation_operations where operation_id=p_operation;
 select * into strict b from public.custodial_activation_legacy_lineage_bindings where activation_operation_id=p_operation;
 if (b.device_id,b.authenticated_credential_id,b.binding_kind,b.source_enrollment_operation_id,b.current_recovery_operation_id,
    b.expected_employee_id,b.expected_assignment_epoch) is distinct from
   (p_device,p_credential,authority->>'binding_kind',(authority->>'source_enrollment_operation_id')::uuid,
    (authority->>'current_recovery_operation_id')::uuid,(authority->>'employee_id')::uuid,(authority->>'assignment_epoch')::bigint)
  then raise exception 'current legacy binding authority conflict'; end if;
 recovery:=b.current_recovery_operation_id is not null;
 outcome:=case when recovery then 'native_active' else 'not_required' end;
 if p_receipt is null or jsonb_typeof(p_receipt)<>'object' or pg_column_size(p_receipt)>2048
  or (select count(*) from jsonb_object_keys(p_receipt))<>11
  or p_receipt->>'operation_id' is distinct from p_operation::text
  or p_receipt->>'device_id' is distinct from authority->>'device_id'
  or p_receipt->>'credential_id' is distinct from p_credential::text
  or p_receipt->>'outcome' is distinct from (case when recovery then 'active' else 'not_required' end)
  or p_receipt->'changed' is distinct from to_jsonb(recovery)
  or p_receipt->>'transition' is distinct from (case when recovery then 'confirmed_recovery' else 'healthy_no_change' end)
  or p_receipt->>'journal_schema' is distinct from 'native-assigned-activation-legacy.v1'
  or coalesce(p_receipt->>'journal_binding_sha256','') !~ '^[0-9a-f]{64}$'
  or p_receipt->>'legacy_binding_id' is distinct from b.binding_id::text
  or p_receipt->>'legacy_binding_kind' is distinct from b.binding_kind
  or p_receipt->>'installation_binding_sha256' is distinct from b.installation_binding_sha256
  then raise exception 'exact bounded legacy native receipt required'; end if;
 if a.state in ('native_active','not_required') then
  if a.native_receipt is distinct from p_receipt or a.state<>outcome then raise exception 'legacy terminal receipt conflict'; end if;
 else
  update public.device_auth_enrollment_codes set revoked_at=coalesce(revoked_at,now())
   where enrollment_id=a.enrollment_id and consumed_at is null;
  update public.custodial_assigned_activation_operations set state=outcome,state_version=state_version+1,
   native_receipt=p_receipt,terminal_at=now(),token_envelope=null,last_error_code=null
   where operation_id=p_operation returning * into a;
 end if;
 -- SHA of exact stored jsonb receipt is server-owned terminal identity, not
 -- native journal digest. The HTTPS response includes the exact receipt too.
 return jsonb_build_object('status',public.custodial_activation_public_status(a),
  'binding',public.custodial_legacy_activation_binding_json(b),
  'activation_receipt_sha256',public.static_weekly_digest_text(a.native_receipt::text));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_lock_offline_reconciliation_keys(p_client_session_id text, p_client_completion_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_first text := 'custodial-offline-key:session:' || coalesce(p_client_session_id,'');
  v_second text := 'custodial-offline-key:completion:' || coalesce(p_client_completion_id,'');
begin
  if v_first <= v_second then
    perform pg_advisory_xact_lock(hashtextextended(v_first, 0));
    perform pg_advisory_xact_lock(hashtextextended(v_second, 0));
  else
    perform pg_advisory_xact_lock(hashtextextended(v_second, 0));
    perform pg_advisory_xact_lock(hashtextextended(v_first, 0));
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_manager_completion_evidence(p_manager_id uuid, p_session_uuid text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.sessions%rowtype; r public.completion_responses%rowtype;
 v_catalog jsonb; v_digest text; v_native boolean:=false;
 v_issue boolean; v_issue_known boolean:=false; v_work text; v_class text; v_raw_issue_count integer:=0;
 v_open integer:=0; v_work_order integer:=0; v_fixed integer:=0; v_legacy_closed integer:=0; v_total integer:=0;
 v_tickets jsonb:='[]'::jsonb; v_follow_up text;
begin
 perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
 if p_manager_id is null or p_session_uuid is null or length(p_session_uuid)=0 or length(p_session_uuid)>128
   or not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id
    and m.active=true and m.revoked_at is null and m.is_system_principal=false
    and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]) then
  raise exception using errcode='42501',message='active named manager authority is required';
 end if;
 select * into s from public.sessions where session_uuid=p_session_uuid;
 if not found then raise exception using errcode='P0002',message='cleaning session was not found'; end if;
 select * into r from public.completion_responses where session_id=s.id;
 if not found then
  return jsonb_build_object('session_id',s.id,'session_uuid',s.session_uuid,
   'location_id',s.location_id,'employee_id',s.employee_id,'device_id',s.device_id,
   'started_at',s.started_at,'ended_at',s.ended_at,
   'session_status',s.status,'completion_recorded',false,'classification','no_completion_record',
   'inspection_evaluation','not_performed_by_this_reader');
 end if;
 select c.catalog_json,c.catalog_sha256 into v_catalog,v_digest from public.custodial_completion_taxonomy_versions c
  where c.version=r.response_json#>>'{taxonomy,version}';
 select exists(
  select 1 from public.custodial_offline_reconciliation_records receipt
  join public.custodial_offline_actor_contexts context on context.context_id=receipt.context_id
  where receipt.completion_response_id=r.id and receipt.session_id=s.id
   and receipt.state='committed' and context.status='committed' and s.status='closed'
   and receipt.occurrence_id=context.occurrence_id and receipt.occurrence_fingerprint=context.occurrence_fingerprint
   and receipt.credential_id=context.credential_id and receipt.location_id=s.location_id
   and context.location_id=s.location_id and r.location_id=s.location_id
   and context.client_session_id=s.client_session_id and receipt.client_session_id=s.client_session_id
   and receipt.client_completion_id=r.client_completion_id and receipt.original_employee_id=s.employee_id
   and context.employee_id=s.employee_id and receipt.device_id=s.device_id and context.device_id=s.device_id
   and r.device_id=s.device_id and r.submitted_by_employee_id=s.employee_id
   and receipt.payload_json->'response_json'=r.response_json
   and context.native_start_attestation_version='custodial-native-start.v1'
   and context.native_scan_entry_id is not null
   and context.native_completion_attestation_version='custodial-native-completion.v2'
   and context.native_completion_attestation_sha256 ~ '^[0-9a-f]{64}$'
   and context.native_finish_scan_entry_id is not null
   and context.native_finish_scan_entry_id<>context.native_scan_entry_id
   and context.started_at=s.started_at and context.native_completed_at=s.ended_at
   and context.native_completed_at>context.started_at and context.native_completed_at<=statement_timestamp()
   and exists(select 1 from public.custodial_offline_scan_event_evidence evidence
    where evidence.context_id=context.context_id and evidence.reconciliation_id=receipt.reconciliation_id
      and evidence.session_id=s.id and lower(evidence.client_event_id)=context.native_finish_scan_entry_id::text
      and evidence.event_payload->>'event_type'='scan_finish'
      and evidence.event_payload->>'result'='ok'
      and evidence.event_payload#>>'{payload_json,entry_source}'='native-nfc'
      and evidence.event_payload->>'scanned_at'=public.custodial_canonical_utc_millis(context.native_completed_at))
 ) into v_native;
 select count(*),count(*) filter(where t.status='open'),
  count(*) filter(where t.resolution_outcome='work_order_sent'),
  count(*) filter(where t.resolution_outcome='mark_fixed'),
  count(*) filter(where t.status='closed' and t.resolution_outcome is null),
  coalesce(jsonb_agg(jsonb_build_object('ticket_id',t.id,'status',t.status,
   'resolution_outcome',t.resolution_outcome,'external_work_order_reference',t.external_work_order_reference,
   'resolution_actor_manager_id',t.resolution_actor_manager_id,'closed_at',t.closed_at,
   'issue_summary',t.issue_summary) order by t.reported_at,t.id) filter(where t.id is not null),'[]'::jsonb)
 into v_total,v_open,v_work_order,v_fixed,v_legacy_closed,v_tickets
 from public.maintenance_tickets t where t.completion_response_id=r.id and t.issue_source='completion_form';
 if jsonb_typeof(r.response_json->'attention_needed')='boolean' then
  v_issue_known:=true; v_issue:=(r.response_json->>'attention_needed')::boolean;
 end if;
 if jsonb_typeof(r.response_json->'maintenance_issues_found')='array' then
  v_raw_issue_count:=jsonb_array_length(r.response_json->'maintenance_issues_found');
 end if;
 if v_raw_issue_count=0 and (lower(coalesce(r.response_json->>'out_of_order_signed','')) in ('yes','true')
    or nullif(btrim(coalesce(r.response_json->>'out_of_order_details','')),'') is not null) then
  v_raw_issue_count:=1;
 end if;
 if v_total>0 or v_raw_issue_count>0
    or lower(coalesce(r.response_json->>'out_of_order_signed','')) in ('yes','true')
    or nullif(btrim(coalesce(r.response_json->>'out_of_order_details','')),'') is not null then
  v_issue_known:=true; v_issue:=true;
 end if;
 v_work:=r.response_json->>'work_result';
 if not v_issue_known then v_follow_up:='unknown';
 elsif not v_issue then v_follow_up:='none_reported';
 elsif v_total>0 and v_fixed=v_total and v_raw_issue_count>0 and v_total>=v_raw_issue_count
  then v_follow_up:='linked_tickets_marked_fixed_coverage_unverified';
 else v_follow_up:='required_or_unresolved';
 end if;
 if not v_native then v_class:='historical_or_unverified_completion';
 elsif v_work='checked_no_cleaning_needed' then v_class:='checked_only';
 elsif v_work not in ('full','details') or v_work is null then v_class:='unknown';
 elsif v_follow_up='none_reported' then v_class:='cleaned_no_issues_reported';
 elsif v_follow_up='linked_tickets_marked_fixed_coverage_unverified'
  then v_class:='cleaned_linked_tickets_marked_fixed_coverage_unverified';
 elsif v_follow_up='required_or_unresolved' then v_class:='cleaned_follow_up_required';
 else v_class:='cleaned_issue_state_unknown';
 end if;
 return jsonb_build_object('session_id',s.id,'session_uuid',s.session_uuid,'session_status',s.status,
  'location_id',s.location_id,'employee_id',s.employee_id,'device_id',s.device_id,
  'started_at',s.started_at,'ended_at',s.ended_at,
  'completion_recorded',true,'completion_response_id',r.id,'client_completion_id',r.client_completion_id,
  'submitted_at',r.submitted_at,'original_response',r.response_json,
  'taxonomy_version',r.response_json#>>'{taxonomy,version}',
  'taxonomy_digest',r.response_json#>>'{taxonomy,digest}',
  'taxonomy_status',case when not (r.response_json ? 'taxonomy') then 'unversioned_historical_or_protected_draft'
   when v_catalog is null or v_digest is distinct from r.response_json#>>'{taxonomy,digest}' then 'metadata_unverified_legacy'
   else 'versioned_current_catalog' end,
  'catalog_digest',v_digest,'catalog',v_catalog,
  'native_exact_receipt_admitted',v_native,'work_result',v_work,'issue_reported',case when v_issue_known then to_jsonb(v_issue) else 'null'::jsonb end,
  'linked_completion_tickets',v_tickets,'linked_ticket_count',v_total,'linked_open_count',v_open,
  'linked_work_order_sent_count',v_work_order,'linked_mark_fixed_count',v_fixed,
  'linked_legacy_closed_unknown_count',v_legacy_closed,'raw_reported_issue_count',v_raw_issue_count,
  'linked_issue_count_shortfall',greatest(v_raw_issue_count-v_total,0),'follow_up',v_follow_up,
  'classification',v_class,'inspection_evaluation','not_performed_by_this_reader');
end $function$

CREATE OR REPLACE FUNCTION public.custodial_manager_dispose_offline_reconciliation(p_manager_id uuid, p_reconciliation_id uuid, p_disposition text, p_reason text, p_request_id uuid, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_fingerprint text; v_request_fingerprint text; v_existing public.custodial_offline_reconciliation_dispositions%rowtype; v_disposition_id uuid;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id and m.active=true and m.revoked_at is null and m.roles && array['DIRECTOR','SECURITY_ADMIN']::text[]) then raise exception using errcode='42501',message='named recovery manager authority is required'; end if;
  if p_request_id is null or p_disposition not in ('reviewed','retained_for_recovery','superseded_by_new_occurrence') or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 then raise exception using errcode='22023',message='stable disposition request identity, disposition, and reason are required'; end if;
  perform pg_advisory_xact_lock(hashtextextended('custodial-offline-disposition:'||p_manager_id::text||':'||p_request_id::text,0));
  v_request_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object('reconciliation_id',p_reconciliation_id,'disposition',p_disposition,'reason',btrim(p_reason))::text,'UTF8'),'sha256'),'hex');
  select * into v_existing from public.custodial_offline_reconciliation_dispositions where manager_id=p_manager_id and request_id=p_request_id for update;
  if v_existing.disposition_id is not null then
    if v_existing.request_fingerprint<>v_request_fingerprint then raise exception using errcode='23505',message='disposition request identity is already bound to a different recovery outcome'; end if;
    return jsonb_build_object('disposition_id',v_existing.disposition_id,'reconciliation_id',v_existing.reconciliation_id,'immutable_original_evidence_fingerprint',v_existing.original_evidence_fingerprint,'replayed',true);
  end if;
  select encode(extensions.digest(convert_to(to_jsonb(r)::text,'UTF8'),'sha256'),'hex') into v_fingerprint from public.custodial_offline_reconciliation_records r where r.reconciliation_id=p_reconciliation_id;
  if v_fingerprint is null then raise exception using errcode='P0002',message='offline reconciliation not found'; end if;
  insert into public.custodial_offline_reconciliation_dispositions(reconciliation_id,manager_id,disposition,reason,original_evidence_fingerprint,request_id,request_fingerprint) values(p_reconciliation_id,p_manager_id,p_disposition,btrim(p_reason),v_fingerprint,p_request_id,v_request_fingerprint) returning disposition_id into v_disposition_id;
  insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,actor_manager_id,reason,evidence_json) values(p_reconciliation_id,'disposition_recorded',p_manager_id,btrim(p_reason),jsonb_build_object('disposition_id',v_disposition_id,'disposition',p_disposition,'request_id',p_request_id));
  perform public.custodial_enqueue_offline_reconciliation_disposition_notice(v_disposition_id);
  return jsonb_build_object('disposition_id',v_disposition_id,'reconciliation_id',p_reconciliation_id,'immutable_original_evidence_fingerprint',v_fingerprint,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_manager_get_offline_reconciliation(p_manager_id uuid, p_reconciliation_id uuid, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_record public.custodial_offline_reconciliation_records%rowtype;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if not exists(select 1 from public.ops_manager_managers m where m.manager_id=p_manager_id and m.active=true and m.revoked_at is null) then raise exception using errcode='42501',message='active named manager authority is required'; end if;
  select * into v_record from public.custodial_offline_reconciliation_records where reconciliation_id=p_reconciliation_id;
  if v_record.reconciliation_id is null then raise exception using errcode='P0002',message='offline reconciliation not found'; end if;
  return jsonb_build_object('record',to_jsonb(v_record),'audits',(select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at),'[]'::jsonb) from public.custodial_offline_reconciliation_audits a where a.reconciliation_id=v_record.reconciliation_id),'dispositions',(select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at),'[]'::jsonb) from public.custodial_offline_reconciliation_dispositions d where d.reconciliation_id=v_record.reconciliation_id),'notifications',coalesce((select jsonb_agg(jsonb_build_object(
    'outbox_id',o.outbox_id,'notification_key',o.notification_key,'notification_kind',o.notification_kind,'disposition_id',o.disposition_id,'state',o.state,
    'status_label',case o.state when 'pending' then 'Pending delivery' when 'claimed' then 'Delivery in progress' when 'retry' then 'Retry scheduled' when 'delivered' then 'Delivered' else 'Delivery unavailable' end,
    'attempts',o.attempts,'claimed_at',o.claimed_at,'lease_expires_at',o.lease_expires_at,'next_attempt_at',o.next_attempt_at,'delivered_at',o.delivered_at,'failed_at',o.failed_at,'last_error',nullif(left(coalesce(o.last_error,''),500),''),'delivery_evidence',o.delivery_json,
    'recipients',coalesce((select jsonb_agg(jsonb_build_object('delivery_recipient_id',dr.delivery_recipient_id,'manager_id',dr.manager_id,'recipient_user_id',dr.recipient_user_id,'state',dr.state,'attempts',dr.attempts,'claimed_at',dr.claimed_at,'lease_expires_at',dr.lease_expires_at,'next_attempt_at',dr.next_attempt_at,'delivered_at',dr.delivered_at,'failed_at',dr.failed_at,'last_error',nullif(left(coalesce(dr.last_error,''),500),''),'message_id',dr.message_id,'client_message_id',dr.client_message_id,'notification_instance_key',dr.notification_instance_key,'delivery_evidence',dr.delivery_evidence,
      'events',coalesce((select jsonb_agg(jsonb_build_object('event_type',de.event_type,'attempt',de.attempt,'worker_id',de.worker_id,'error',de.error_text,'evidence',de.evidence_json,'created_at',de.created_at) order by de.created_at,de.delivery_event_id) from public.custodial_offline_reconciliation_delivery_events de where de.delivery_recipient_id=dr.delivery_recipient_id),'[]'::jsonb)) order by dr.created_at,dr.delivery_recipient_id) from public.custodial_offline_reconciliation_delivery_recipients dr where dr.outbox_id=o.outbox_id),'[]'::jsonb),
    'events',coalesce((select jsonb_agg(jsonb_build_object('event_type',de.event_type,'attempt',de.attempt,'worker_id',de.worker_id,'error',de.error_text,'evidence',de.evidence_json,'created_at',de.created_at) order by de.created_at,de.delivery_event_id) from public.custodial_offline_reconciliation_delivery_events de where de.outbox_id=o.outbox_id and de.delivery_recipient_id is null),'[]'::jsonb)
  ) order by o.created_at,o.outbox_id) from public.custodial_offline_reconciliation_outbox o where o.reconciliation_id=v_record.reconciliation_id),'[]'::jsonb));
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_manager_get_session_truth(p_manager_id uuid, p_session_id uuid, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_result jsonb;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if not exists(
    select 1 from public.ops_manager_managers m
    where m.manager_id=p_manager_id and m.active=true and m.revoked_at is null
      and m.is_system_principal=false
      and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]
  ) then
    raise exception using errcode='42501', message='An active named manager is required to view cleaning truth';
  end if;
  select to_jsonb(v) into v_result
  from public.v_custodial_cleaning_session_truth v
  where v.session_id=p_session_id;
  if v_result is null then
    raise exception using errcode='P0002', message='Cleaning session was not found';
  end if;
  return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_native_alert_dispatch_status(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.employee_native_alert_finalizations%rowtype;o public.employee_native_alert_outcomes%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null then raise exception 'exact alert job required' using errcode='22023';end if;
 perform 1 from public.operational_notification_jobs where job_id=p_job for update;
 select * into a from public.employee_native_alert_finalizations where job_id=p_job for update;
 if a.job_id is null then return jsonb_build_object('schema','custodial.native-alert-dispatch-status.v1',
  'reserved',false,'dispatch_authorized',false);end if;
 select * into o from public.employee_native_alert_outcomes where job_id=p_job;
 return jsonb_build_object('schema','custodial.native-alert-dispatch-status.v1','reserved',true,
  'dispatch_authorized',false,'job_id',a.job_id,'attempt_id',a.attempt_id,
  'outcome_operation_id',a.outcome_operation_id,'content_sha256',a.content_sha256,
  'provider_outcome',coalesce(o.provider_outcome,'prepared'),
  'provider_message_id',o.provider_message_id,'error_code',o.error_code);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_alert_finalize_at(p_job uuid, p_lease uuid, p_prepared uuid, p_expected jsonb, p_candidate jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare target jsonb;prep public.employee_native_alert_preparations%rowtype;
 prior public.employee_native_alert_finalizations%rowtype;j public.operational_notification_jobs%rowtype;
 c public.device_auth_credentials%rowtype;i public.event_push_instances%rowtype;
 projection jsonb;at_time timestamptz;until_time timestamptz;data jsonb;
 required_keys text[];ttl integer;row_out public.employee_native_alert_finalizations%rowtype;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_lease is null or p_prepared is null
  or jsonb_typeof(p_expected) is distinct from 'object'
  or jsonb_typeof(p_candidate) is distinct from 'object' then
  raise exception 'exact native alert finalize request required' using errcode='22023';end if;
 target:=public.custodial_native_alert_target_at(p_job,p_lease,p_test_at);
 if target->'current' is distinct from 'true'::jsonb or target->'expected' is distinct from p_expected then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_alert_target_superseded');end if;
 select * into j from public.operational_notification_jobs where job_id=p_job for update;
 select * into prep from public.employee_native_alert_preparations where job_id=p_job for update;
 at_time:=coalesce(p_test_at,clock_timestamp());
 if prep.job_id is null or prep.preparation_id<>p_prepared or prep.lease_token<>p_lease
  or prep.expected is distinct from p_expected or prep.alert_kind is distinct from target->>'kind'
  or prep.prepared_until<=at_time or j.leased_until<=at_time then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_alert_preparation_superseded');end if;
 select * into prior from public.employee_native_alert_finalizations where job_id=p_job for update;
 if prior.job_id is not null then
  return jsonb_build_object('current',true,'dispatch_authorized',false,
   'delivery_outcome_unknown',true,'reason','native_alert_original_finalization_no_resend');end if;
 select * into c from public.device_auth_credentials where credential_id=(p_expected->>'credential_id')::uuid for update;
 until_time:=least(prep.prepared_until,j.leased_until,c.expires_at);
 if c.credential_id is null or c.revoked_at is not null or c.expires_at<=at_time then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_alert_credential_superseded');end if;
 if prep.alert_kind='EVENT' then
  select * into i from public.event_push_instances where instance_id=j.source_id for update;
  projection:=public.mz_employee_event_push_current_projection(p_job,p_lease,i.instance_id,c.credential_id,i.assignment_epoch);
  if projection->'current' is distinct from 'true'::jsonb then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_event_source_superseded');end if;
  projection:=projection||jsonb_build_object('notification_kind',i.notification_kind,'service_date',i.service_date::text);
  until_time:=least(until_time,(projection->>'start_instant_utc')::timestamptz);
  required_keys:=array['body','channel_id','event_id','event_revision','instance_id','kind',
   'notification_key','notification_kind','notification_type','recipient_device_uuid','route',
   'schema','service_date','source_revision','title'];
 else
  if not public.custodial_native_alert_message_current(p_job,prep.source_projection,at_time) then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_message_source_superseded');end if;
  projection:=prep.source_projection;
  required_keys:=array['body','channel_id','kind','message_id','notification_key','notification_type',
   'recipient_user_id','route','schema','source_revision','thread_id','title'];
 end if;
 if projection is distinct from prep.source_projection
  or (prep.alert_kind='EVENT' and public.static_weekly_digest_jsonb(projection) is distinct from prep.source_revision)
  or (prep.alert_kind='MESSAGE' and projection->>'source_revision' is distinct from prep.source_revision)
  or until_time<=at_time+interval '1 second' then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_alert_source_or_window_superseded');end if;
 if (select array_agg(key order by key collate "C") from jsonb_object_keys(p_candidate) key) is distinct from required_keys
  or exists(select 1 from jsonb_each(p_candidate) e where jsonb_typeof(e.value)<>'string')
  or octet_length(p_candidate->>'title') not between 1 and 180
  or octet_length(p_candidate->>'body') not between 1 and 1000
  or p_candidate->>'source_revision' is distinct from prep.source_revision
  or p_candidate->>'kind' is distinct from (case prep.alert_kind when 'EVENT' then 'employee_event' else 'employee_message' end)
  or p_candidate->>'notification_type' is distinct from lower(prep.alert_kind)
  or p_candidate->>'channel_id' is distinct from (case prep.alert_kind when 'EVENT' then 'employee-events' else 'employee-messages' end)
  or p_candidate->>'schema' is distinct from (case prep.alert_kind when 'EVENT' then 'custodial.native-event-payload.v1'
   else 'custodial.native-message-payload.v1' end) then
  raise exception 'native alert content candidate invalid' using errcode='22023';end if;
 if prep.alert_kind='EVENT' then
  if coalesce(projection->>'employee_name','')=''
   or coalesce(projection->>'event_name','')=''
   or coalesce(projection->>'display_location','')=''
   or p_candidate->>'event_id' is distinct from projection->>'event_id'
   or p_candidate->>'instance_id' is distinct from projection->>'instance_id'
   or p_candidate->>'event_revision' is distinct from projection->>'event_revision'
   or p_candidate->>'recipient_device_uuid' is distinct from p_expected->>'device_uuid'
   or p_candidate->>'notification_kind' is distinct from projection->>'notification_kind'
   or p_candidate->>'service_date' is distinct from projection->>'service_date'
   or p_candidate->>'notification_key' is distinct from projection->>'notification_key'
   or p_candidate->>'route' is distinct from 'events.html?hub=employee&event_id='||(projection->>'event_id')
   or p_candidate->>'title' is distinct from 'Memphis Zoo event reminder'
   or position(projection->>'event_name' in p_candidate->>'body')=0
   or position(projection->>'display_location' in p_candidate->>'body')=0 then
   raise exception 'native Event content not bound to current source' using errcode='42501';end if;
 else
  if p_candidate->>'message_id' is distinct from projection->>'message_id'
   or p_candidate->>'thread_id' is distinct from projection->>'thread_id'
   or p_candidate->>'recipient_user_id' is distinct from projection->>'recipient_user_id'
   or p_candidate->>'notification_key' is distinct from 'message:'||j.source_id::text
   or p_candidate->>'route' is distinct from 'messages.html?hub=employee&thread_id='||(projection->>'thread_id')
   or p_candidate->>'title' is distinct from projection#>>'{payload,title}'
   or p_candidate->>'body' is distinct from projection#>>'{payload,body}' then
   raise exception 'native Message content not bound to current source' using errcode='42501';end if;
 end if;
 if exists(select 1 from jsonb_each_text(p_candidate) e where e.value~'[[:cntrl:]]') then
  raise exception 'native alert content contains controls' using errcode='22023';end if;
 data:=p_candidate||jsonb_build_object('generation_id',p_expected->>'generation_id',
  'principal_digest',p_expected->>'principal_digest','token_digest',p_expected->>'token_digest',
  'receipt_job_id',p_job::text,'receipt_credential_id',p_expected->>'credential_id',
  'receipt_employee_id',p_expected->>'employee_id','receipt_device_id',p_expected->>'device_id',
  'receipt_assignment_epoch',p_expected->>'assignment_epoch',
  'reservation_at',public.custodial_native_location_utc(at_time),
  'valid_until',public.custodial_native_location_utc(until_time));
 if prep.alert_kind='MESSAGE' then
  data:=data||jsonb_build_object('service_date',public.sch_service_date(at_time)::text);end if;
 data:=data||jsonb_build_object('content_sha256',
  public.static_weekly_digest_text(public.custodial_native_location_canonical(data)));
 if octet_length(public.custodial_native_location_canonical(data))>3500 then
  raise exception 'native alert closed wire too large' using errcode='22023';end if;
 insert into public.employee_native_alert_finalizations(job_id,preparation_id,alert_kind,source_revision,
  payload,content_sha256,finalized_at,valid_until)
 values(p_job,p_prepared,prep.alert_kind,prep.source_revision,data,data->>'content_sha256',at_time,until_time)
 returning * into row_out;
 ttl:=least(2419200,floor(extract(epoch from until_time-at_time))::integer);
 return jsonb_build_object('schema','custodial.native-alert-dispatch.v1','dispatch_authorized',true,
  'reservation',jsonb_build_object('current',true,'replayed',false,'delivery_outcome_unknown',false,
   'dispatch_authorized',true,'payload',data,'wire',public.custodial_native_location_canonical(data)),
  'attempt_id',row_out.attempt_id,'outcome_operation_id',row_out.outcome_operation_id,'ttl_seconds',ttl);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_alert_message_current(p_job uuid, p_projection jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare j public.operational_notification_jobs%rowtype;m public.msg_messages%rowtype;
 t public.msg_threads%rowtype;u public.msg_users%rowtype;r public.msg_receipts%rowtype;
 legacy public.employee_native_push_delivery_receipts%rowtype;
 recipient uuid;target_thread_id uuid;revision text;
begin
 if p_job is null or p_at is null or not isfinite(p_at)
  or jsonb_typeof(p_projection) is distinct from 'object'
  or p_projection->>'schema' is distinct from 'custodial.employee-message-admission.v1' then return false;end if;
 select * into j from public.operational_notification_jobs where job_id=p_job for update;
 if j.job_id is null or j.job_type<>'employee_native_push' or j.status<>'leased'
  or j.leased_until<=p_at or j.source_id::text is distinct from p_projection->>'message_id'
  or j.job_key is distinct from p_projection->>'job_key'
  or j.lease_token::text is distinct from p_projection->>'lease_token'
  or j.payload_json is distinct from p_projection->'payload' then return false;end if;
 select * into legacy from public.employee_native_push_delivery_receipts where job_id=p_job for update;
 if legacy.job_id is null or legacy.delivery_state<>'prepared'
  or legacy.lease_token is distinct from j.lease_token
  or legacy.credential_id::text is distinct from p_projection->>'credential_id'
  or legacy.registration_id::text is distinct from p_projection->>'registration_id'
  or legacy.assignment_epoch::text is distinct from p_projection->>'assignment_epoch'
  or legacy.token_hash is distinct from p_projection->>'token_hash' then return false;end if;
 recipient:=(p_projection->>'recipient_user_id')::uuid;
 target_thread_id:=(p_projection->>'thread_id')::uuid;
 select * into t from public.msg_threads where id=target_thread_id for update;
 select * into m from public.msg_messages where id=j.source_id for share;
 select * into u from public.msg_users where id=recipient and is_active=true for share;
 if t.id is null or t.is_active is not true or t.system_key='ops_manager_shared_chat_v1'
  or m.id is null or m.thread_id is distinct from t.id or m.is_deleted is not false
  or m.sender_user_id=u.id or m.sent_at is null or m.sent_at>p_at
  or u.id is null or u.employee_id::text is distinct from p_projection->>'employee_id' then return false;end if;
 perform 1 from public.msg_thread_participants where thread_id=t.id and user_id=u.id
  and left_at is null for share;
 if not found then return false;end if;
 select * into r from public.msg_receipts where message_id=m.id and user_id=u.id for share;
 if r.message_id is null or r.acknowledged_at is not null
  or exists(select 1 from public.msg_message_deletions where message_id=m.id and user_id=u.id)
  or exists(select 1 from public.msg_thread_visibility v where v.thread_id=t.id and v.user_id=u.id
   and (v.device_identifier is null or upper(btrim(v.device_identifier))=upper(btrim(p_projection->>'device_identifier')))
   and coalesce(m.sent_at,m.created_at)<=v.hidden_before) then return false;end if;
 revision:=public.static_weekly_digest_jsonb(jsonb_build_object('message_id',m.id,'thread_id',m.thread_id,
  'sender_user_id',m.sender_user_id,'sent_at',m.sent_at,'body',m.body,
  'metadata_json',m.metadata_json,'recipient_user_id',u.id));
 if revision is distinct from p_projection->>'source_revision'
  or p_projection#>>'{payload,body}' is distinct from
   left(coalesce(nullif(regexp_replace(m.body,'[[:space:]]+',' ','g'),''),'New message'),1000)
  or p_projection#>>'{payload,title}' is distinct from p_projection#>>'{payload,data_json,sender_name}'
  or p_projection#>>'{payload,data_json,notification_key}' is distinct from 'message:'||m.id::text
  or p_projection#>>'{payload,data_json,route}' is distinct from
   'messages.html?hub=employee&thread_id='||t.id::text then return false;end if;
 return true;
exception when data_exception or invalid_text_representation then return false;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_alert_prepare_at(p_job uuid, p_lease uuid, p_expected jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare target jsonb;j public.operational_notification_jobs%rowtype;i public.event_push_instances%rowtype;
 prep public.employee_native_alert_preparations%rowtype;claim jsonb;projection jsonb;
 at_time timestamptz;until_time timestamptz;revision text;kind text;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_lease is null or jsonb_typeof(p_expected) is distinct from 'object' then
  raise exception 'exact alert preparation required' using errcode='22023';end if;
 target:=public.custodial_native_alert_target_at(p_job,p_lease,p_test_at);
 if target->'current' is distinct from 'true'::jsonb or target->'expected' is distinct from p_expected then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_alert_target_superseded');end if;
 select * into j from public.operational_notification_jobs where job_id=p_job for update;
 at_time:=coalesce(p_test_at,clock_timestamp());kind:=target->>'kind';
 until_time:=least(j.leased_until,(select expires_at from public.device_auth_credentials
  where credential_id=(p_expected->>'credential_id')::uuid));
 select * into prep from public.employee_native_alert_preparations where job_id=p_job for update;
 if prep.job_id is not null then
  if prep.lease_token is distinct from p_lease or prep.expected is distinct from p_expected
   or prep.alert_kind is distinct from kind or prep.prepared_until<=at_time then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_alert_preparation_superseded');end if;
  return jsonb_build_object('schema','custodial.native-alert-preparation.v1','current',true,
   'dispatch_authorized',false,'prepared_id',prep.preparation_id,'job_id',p_job,'lease_token',p_lease,
   'kind',kind,'expected',prep.expected,'source_revision',prep.source_revision,
   'source_projection',prep.source_projection,
   'prepared_until',public.custodial_native_location_utc(prep.prepared_until));
 end if;
 if kind='EVENT' then
  select * into i from public.event_push_instances where instance_id=j.source_id for update;
  claim:=public.mz_claim_employee_event_push_delivery(p_job,p_lease,i.instance_id,
   (p_expected->>'credential_id')::uuid,i.assignment_epoch,(p_expected->>'registration_id')::uuid,
   p_expected->>'token_digest',at_time);
  if claim->'dispatch_authorized' is distinct from 'true'::jsonb then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_event_claim_unavailable');end if;
  projection:=public.mz_employee_event_push_current_projection(p_job,p_lease,i.instance_id,
   (p_expected->>'credential_id')::uuid,i.assignment_epoch);
  if projection->'current' is distinct from 'true'::jsonb then
   raise exception 'native Event projection unavailable after claim' using errcode='42501';end if;
  until_time:=least(until_time,(projection->>'start_instant_utc')::timestamptz);
  projection:=projection||jsonb_build_object('notification_kind',i.notification_kind,'service_date',i.service_date::text);
  revision:=public.static_weekly_digest_jsonb(projection);
 elsif kind='MESSAGE' then
  claim:=public.mz_prepare_employee_native_push_delivery(p_job,p_lease,
   (p_expected->>'credential_id')::uuid,(p_expected->>'assignment_epoch')::bigint,
   (p_expected->>'registration_id')::uuid,p_expected->>'token_digest',at_time);
  if claim->'dispatch_authorized' is distinct from 'true'::jsonb
   or jsonb_typeof(claim->'message_projection') is distinct from 'object' then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_message_source_unavailable');end if;
  projection:=claim->'message_projection';revision:=projection->>'source_revision';
 else raise exception 'native alert kind unavailable' using errcode='22023';end if;
 if not isfinite(at_time) or until_time<=at_time+interval '1 second'
  or revision !~ '^[0-9a-f]{64}$' then
  raise exception 'native alert preparation window or source unavailable' using errcode='42501';end if;
 insert into public.employee_native_alert_preparations(job_id,lease_token,alert_kind,expected,
  source_projection,source_revision,prepared_at,prepared_until)
 values(p_job,p_lease,kind,p_expected,projection,revision,at_time,until_time) returning * into prep;
 return jsonb_build_object('schema','custodial.native-alert-preparation.v1','current',true,
  'dispatch_authorized',false,'prepared_id',prep.preparation_id,'job_id',p_job,'lease_token',p_lease,
  'kind',kind,'expected',prep.expected,'source_revision',prep.source_revision,
  'source_projection',prep.source_projection,
  'prepared_until',public.custodial_native_location_utc(prep.prepared_until));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_alert_record_outcome(p_job uuid, p_operation uuid, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.employee_native_alert_finalizations%rowtype;o public.employee_native_alert_outcomes%rowtype;
 received timestamptz;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_operation is null or jsonb_typeof(p_evidence) is distinct from 'object'
  or (select array_agg(key order by key collate "C") from jsonb_object_keys(p_evidence) key) is distinct from
   array['error_code','operation_id','outcome','provider_message_id']
  or p_evidence->>'operation_id' is distinct from p_operation::text
  or p_evidence->>'outcome' not in ('provider_accepted','known_nonacceptance','delivery_outcome_unknown') then
  raise exception 'exact native alert outcome required' using errcode='22023';end if;
 if p_evidence->>'outcome'='provider_accepted' then
  if jsonb_typeof(p_evidence->'provider_message_id') is distinct from 'string'
   or length(p_evidence->>'provider_message_id') not between 1 and 1000
   or p_evidence->>'provider_message_id'~'[[:cntrl:]]'
   or p_evidence->'error_code'<>'null'::jsonb then
   raise exception 'provider acceptance evidence invalid' using errcode='22023';end if;
 elsif p_evidence->'provider_message_id'<>'null'::jsonb
  or coalesce(p_evidence->>'error_code','') !~ '^[a-z][a-z0-9_]{0,99}$' then
  raise exception 'provider uncertainty evidence invalid' using errcode='22023';end if;
 perform 1 from public.operational_notification_jobs where job_id=p_job for update;
 select * into a from public.employee_native_alert_finalizations where job_id=p_job for update;
 if a.job_id is null or a.outcome_operation_id<>p_operation then
  raise exception 'original native alert finalization required' using errcode='42501';end if;
 select * into o from public.employee_native_alert_outcomes where job_id=p_job;
 if o.job_id is not null then
  if o.operation_id<>p_operation or o.provider_outcome<>p_evidence->>'outcome'
   or o.provider_message_id is distinct from p_evidence->>'provider_message_id'
   or o.error_code is distinct from p_evidence->>'error_code' then
   raise exception 'native alert outcome conflict' using errcode='23505';end if;
  return jsonb_build_object('schema','custodial.native-alert-outcome.v1','recorded',true,'replayed',true,
   'provider_outcome',o.provider_outcome,'provider_message_id',o.provider_message_id,'error_code',o.error_code);
 end if;
 received:=clock_timestamp();
 insert into public.employee_native_alert_outcomes(job_id,operation_id,provider_outcome,provider_message_id,error_code,recorded_at)
 values(p_job,p_operation,p_evidence->>'outcome',p_evidence->>'provider_message_id',p_evidence->>'error_code',received);
 return jsonb_build_object('schema','custodial.native-alert-outcome.v1','recorded',true,'replayed',false,
  'provider_outcome',p_evidence->>'outcome','provider_message_id',p_evidence->>'provider_message_id',
  'error_code',p_evidence->>'error_code');
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_alert_source_live(p_job uuid, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.employee_native_alert_finalizations%rowtype;
 prep public.employee_native_alert_preparations%rowtype;
 j public.operational_notification_jobs%rowtype;
 i public.event_push_instances%rowtype;e public.events_app_events%rowtype;
 employee public.employees%rowtype;place jsonb;source jsonb;
 m public.msg_messages%rowtype;t public.msg_threads%rowtype;
 u public.msg_users%rowtype;r public.msg_receipts%rowtype;
 recipient uuid;revision text;
begin
 if p_job is null or p_at is null or not isfinite(p_at) then return false;end if;
 select * into a from public.employee_native_alert_finalizations where job_id=p_job;
 select * into prep from public.employee_native_alert_preparations where job_id=p_job;
 select * into j from public.operational_notification_jobs where job_id=p_job;
 if a.job_id is null or prep.job_id is null or j.job_id is null
  or a.preparation_id<>prep.preparation_id or a.alert_kind<>prep.alert_kind
  or a.source_revision<>prep.source_revision or a.payload->>'source_revision'<>prep.source_revision
  or a.finalized_at>p_at or a.valid_until<=p_at
  or a.payload->>'valid_until'<>public.custodial_native_location_utc(a.valid_until) then return false;end if;
 if prep.alert_kind='EVENT' then
  select * into i from public.event_push_instances where instance_id=j.source_id;
  select * into e from public.events_app_events where id=i.event_id;
  select * into employee from public.employees where id=i.employee_id and active=true;
  if j.job_type<>'employee_event_push' or i.instance_id is null
   or i.state not in ('leased','sent','opened') or i.cancelled_at is not null
   or i.dispatch_job_id is distinct from p_job or i.dispatch_lease_token is distinct from prep.lease_token
   or e.id is null or e.revision<>i.event_revision or e.status<>'SCHEDULED'
   or coalesce(e.needs_review,false) or e.event_scope='UNKNOWN'
   or e.cancelled_at is not null or e.archived_at is not null
   or e.start_instant_utc<=p_at or e.end_instant_utc is null
   or employee.id is null or i.employee_id::text<>a.payload->>'receipt_employee_id'
   or i.credential_id::text<>a.payload->>'receipt_credential_id'
   or i.device_id::text<>a.payload->>'recipient_device_uuid'
   or i.assignment_epoch::text<>a.payload->>'receipt_assignment_epoch'
   or not exists(select 1 from public.mz_event_reminder_schedule(e.id,e.revision,i.employee_id,i.notification_kind) s
     where s.scheduled_for=i.scheduled_for) then return false;end if;
  place:=public.app_event_place_authority(to_jsonb(e),p_at);
  if place->>'admissible' is distinct from 'true' then return false;end if;
  source:=jsonb_build_object('current',true,'event_id',e.id,'event_revision',e.revision,
   'instance_id',i.instance_id,'notification_key',i.notification_key,
   'employee_id',employee.id,'employee_name',employee.display_name,
   'event_name',e.event_name,
   'display_location',coalesce(nullif(place->>'primary_display_name',''),e.display_location),
   'event_date',e.event_date,'start_time',e.start_time,'end_time',e.end_time,
   'start_instant_utc',e.start_instant_utc,'end_instant_utc',e.end_instant_utc,
   'attendee_count',e.attendee_count,'custodial_note_codes',e.custodial_note_codes,
   'custodial_public_notes',e.custodial_public_notes,
   'place_authority',place->>'capability_authority',
   'notification_kind',i.notification_kind,'service_date',i.service_date::text);
  return source=prep.source_projection
   and public.static_weekly_digest_jsonb(source)=a.source_revision
   and a.payload->>'event_id'=e.id::text
   and a.payload->>'event_revision'=e.revision::text
   and a.payload->>'notification_key'=i.notification_key;
 end if;
 if prep.alert_kind<>'MESSAGE' or j.job_type<>'employee_native_push'
  or j.source_id::text is distinct from prep.source_projection->>'message_id'
  or j.job_key is distinct from prep.source_projection->>'job_key' then return false;end if;
 recipient:=(prep.source_projection->>'recipient_user_id')::uuid;
 select * into m from public.msg_messages where id=j.source_id;
 select * into t from public.msg_threads where id=m.thread_id;
 select * into u from public.msg_users where id=recipient and is_active=true;
 select * into r from public.msg_receipts where message_id=m.id and user_id=u.id;
 if m.id is null or m.is_deleted is not false or m.sent_at is null or m.sent_at>p_at
  or t.id is null or t.is_active is not true or t.system_key='ops_manager_shared_chat_v1'
  or u.id is null or u.employee_id::text is distinct from a.payload->>'receipt_employee_id'
  or m.sender_user_id=u.id or r.message_id is null or r.acknowledged_at is not null
  or not exists(select 1 from public.msg_thread_participants x
    where x.thread_id=t.id and x.user_id=u.id and x.left_at is null)
  or exists(select 1 from public.msg_message_deletions x where x.message_id=m.id and x.user_id=u.id)
  or exists(select 1 from public.msg_thread_visibility v where v.thread_id=t.id and v.user_id=u.id
    and (v.device_identifier is null or upper(btrim(v.device_identifier))=upper(btrim(a.payload->>'receipt_device_id')))
    and coalesce(m.sent_at,m.created_at)<=v.hidden_before) then return false;end if;
 revision:=public.static_weekly_digest_jsonb(jsonb_build_object('message_id',m.id,
  'thread_id',m.thread_id,'sender_user_id',m.sender_user_id,'sent_at',m.sent_at,
  'body',m.body,'metadata_json',m.metadata_json,'recipient_user_id',u.id));
 return revision=a.source_revision and prep.source_projection->>'source_revision'=revision
  and prep.source_projection#>>'{payload,body}'=left(coalesce(nullif(regexp_replace(m.body,'[[:space:]]+',' ','g'),''),'New message'),1000)
  and a.payload->>'message_id'=m.id::text and a.payload->>'thread_id'=t.id::text
  and a.payload->>'recipient_user_id'=u.id::text;
exception when data_exception or invalid_text_representation then return false;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_alert_target_at(p_job uuid, p_lease uuid, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare j public.operational_notification_jobs%rowtype;i public.event_push_instances%rowtype;
 d public.devices%rowtype;c public.device_auth_credentials%rowtype;r public.employee_push_registrations%rowtype;
 g public.employee_native_push_generations%rowtype;at_time timestamptz;recipient uuid;epoch bigint;
 kind text;active_count integer;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_lease is null then raise exception 'exact alert job lease required' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into j from public.operational_notification_jobs where job_id=p_job;
 if j.job_id is null or j.status<>'leased' or j.lease_token is distinct from p_lease
  or j.job_type not in ('employee_event_push','employee_native_push') then
  return jsonb_build_object('current',false,'reason','native_alert_job_superseded');end if;
 if j.job_type='employee_event_push' then
  kind:='EVENT';
  select * into i from public.event_push_instances where instance_id=j.source_id;
  recipient:=i.credential_id;epoch:=i.assignment_epoch;
 elsif j.payload_json#>>'{data_json,kind}'='employee_message'
  and (j.payload_json#>'{data_json,test_delivery}') is null
  and j.job_key='employee-message-push:'||j.source_id::text||':'||(j.payload_json->>'credential_id') then
  kind:='MESSAGE';recipient:=(j.payload_json->>'credential_id')::uuid;
  epoch:=(j.payload_json->>'assignment_epoch')::bigint;
 else return jsonb_build_object('current',false,'reason','native_alert_kind_unavailable');end if;
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id
  where c0.credential_id=recipient for update of d0;
 select * into c from public.device_auth_credentials where credential_id=recipient for update;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 select * into r from public.employee_push_registrations
  where credential_id=recipient and device_id=d.id and employee_id=d.assigned_employee_id
   and assignment_epoch=d.assignment_epoch and active is true and revoked_at is null
  order by last_seen_at desc,registration_id desc limit 1;
 select count(*) into active_count from public.employee_native_push_generations
  where credential_id=recipient and registration_id=r.registration_id
   and revoked_at is null and dispatch_retired_at is null;
 if active_count=1 then
  select * into g from public.employee_native_push_generations
   where credential_id=recipient and registration_id=r.registration_id
    and revoked_at is null and dispatch_retired_at is null for update;
 end if;
 -- Match the existing native target's device -> credential -> registration
 -- -> generation -> job lock order. Re-read the job after acquiring its lock;
 -- the preliminary recipient lookup is never itself authority.
 select * into j from public.operational_notification_jobs where job_id=p_job for update;
 at_time:=coalesce(p_test_at,clock_timestamp());
 if not isfinite(at_time) or j.job_id is null or j.status<>'leased'
  or j.lease_token is distinct from p_lease or j.leased_until<=at_time
  or j.job_type is distinct from (case kind when 'EVENT' then 'employee_event_push' else 'employee_native_push' end)
  or (kind='EVENT' and j.source_id is distinct from i.instance_id)
  or (kind='MESSAGE' and (j.payload_json->>'credential_id' is distinct from recipient::text
   or j.payload_json->>'assignment_epoch' is distinct from epoch::text))
  or d.id is null or d.active is not true
  or d.device_id !~ '^KIOSK_(0[2-9]|10)$'
  or d.assignment_epoch is distinct from epoch or c.device_id is distinct from d.id
  or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=at_time
  or r.registration_id is null or r.platform is distinct from 'android'
  or r.token_hash is distinct from public.static_weekly_digest_text(r.fcm_token)
  or g.generation_id is null or g.registration_id is distinct from r.registration_id
  or g.device_id is distinct from d.id or g.device_identifier is distinct from d.device_id
  or g.employee_id is distinct from d.assigned_employee_id or g.assignment_epoch is distinct from d.assignment_epoch
  or g.principal_digest !~ '^[0-9a-f]{64}$' or g.token_digest is distinct from r.token_hash
  or g.activated_at>at_time or not exists(select 1 from public.employees e
   where e.id=d.assigned_employee_id and e.active and e.employee_code~'^EMP[0-9]+$')
  or (kind='EVENT' and (i.instance_id is null or i.credential_id is distinct from c.credential_id
    or i.device_id is distinct from d.id or i.employee_id is distinct from d.assigned_employee_id))
  or (kind='MESSAGE' and (j.payload_json->>'credential_id' is distinct from c.credential_id::text
    or j.payload_json->>'employee_id' is distinct from d.assigned_employee_id::text
    or j.payload_json->>'device_id' is distinct from d.id::text
    or j.payload_json->>'device_identifier' is distinct from d.device_id
    or j.payload_json->>'assignment_epoch' is distinct from d.assignment_epoch::text)) then
  return jsonb_build_object('current',false,'reason','native_alert_recipient_superseded');end if;
 return jsonb_build_object('current',true,'kind',kind,'token',r.fcm_token,
  'expected',jsonb_build_object('generation_id',g.generation_id::text,'principal_digest',g.principal_digest,
   'token_digest',g.token_digest,'credential_id',c.credential_id::text,'employee_id',d.assigned_employee_id::text,
   'device_id',d.device_id,'device_uuid',d.id::text,'assignment_epoch',d.assignment_epoch::text,
   'registration_id',r.registration_id::text));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_canonical(p_data jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare result text;
begin
 if jsonb_typeof(p_data) is distinct from 'object' or exists(
  select 1 from jsonb_each(p_data) e where jsonb_typeof(e.value)<>'string' or e.key !~ '^[a-z][a-z0-9_]*$')
 then raise exception 'native location flat string object required';end if;
 select '{'||coalesce(string_agg(to_json(key)::text||':'||to_json(value)::text,',' order by key collate "C"),'')||'}'
 into result from jsonb_each_text(p_data);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_dispatch_prepare_at(p_job uuid, p_lease uuid, p_expected jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare reserved jsonb;a public.employee_native_location_dispatch_attempts%rowtype;ttl integer;
begin
 perform public.custodial_begin_application_mutation();
 -- reserve_at owns final original recipient + exact publication/projection
 -- admission and its full ordered lock fence. Sample clock only inside it.
 reserved:=public.custodial_native_location_reserve_at(p_job,p_lease,p_expected,p_test_at);
 if reserved->'dispatch_authorized' is distinct from 'true'::jsonb then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_dispatch_not_fresh');end if;
 insert into public.employee_native_location_dispatch_attempts(job_id) values(p_job) returning * into a;
 ttl:=least(2419200,floor(extract(epoch from (reserved#>>'{payload,valid_until}')::timestamptz-(reserved#>>'{payload,reservation_at}')::timestamptz))::integer);
 if ttl<0 then raise exception 'native LOCATION validity unavailable';end if;
 return jsonb_build_object('schema','custodial.native-location-dispatch.v1','dispatch_authorized',true,'reservation',reserved,
  'attempt_id',a.attempt_id,'outcome_operation_id',a.outcome_operation_id,'ttl_seconds',ttl);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_dispatch_status(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.employee_native_push_delivery_receipts%rowtype;a public.employee_native_location_dispatch_attempts%rowtype;b jsonb;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null then raise exception 'exact original job required' using errcode='22023';end if;
 -- Same final job->receipt read fence as original outcome status, no later
 -- device/generation locks. This read grants neither token nor dispatch rights.
 perform 1 from public.operational_notification_jobs where job_id=p_job for update;
 select * into r from public.employee_native_push_delivery_receipts where job_id=p_job for update;
 if r.job_id is null then return jsonb_build_object('schema','custodial.native-location-dispatch-status.v1','reserved',false,'dispatch_authorized',false);end if;
 if r.native_generation_id is null or r.native_payload->>'schema' is distinct from 'custodial.native-location-payload.v2' then
  raise exception 'original LOCATION native reservation required' using errcode='42501';end if;
 select * into a from public.employee_native_location_dispatch_attempts where job_id=p_job;
 b:=jsonb_build_object('receipt_job_id',r.job_id::text,'lease_token',r.lease_token::text,'registration_id',r.registration_id::text,
  'generation_id',r.native_generation_id::text,'reservation_at',public.custodial_native_location_utc(r.prepared_at),
  'content_sha256',r.native_payload_sha256,'token_digest',r.token_hash,'principal_digest',r.native_payload->>'principal_digest',
  'receipt_credential_id',r.credential_id::text,'receipt_assignment_epoch',r.assignment_epoch::text,
  'receipt_employee_id',r.native_payload->>'receipt_employee_id','receipt_device_id',r.native_payload->>'receipt_device_id');
 return jsonb_build_object('schema','custodial.native-location-dispatch-status.v1','reserved',true,'dispatch_authorized',false,
  'binding',b,'attempt_id',a.attempt_id,'outcome_operation_id',a.outcome_operation_id);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_inventory_at(p_credential uuid, p_credential_hash text, p_native_request uuid, p_attestation_digest text, p_body jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;g public.employee_native_push_generations%rowtype;
 scan public.employee_native_location_inventory_scans%rowtype;at_time timestamptz;sid uuid;ids uuid[];field text;
 bound jsonb;cursor_value jsonb;rows_value jsonb:='[]'::jsonb;entry record;count_rows integer:=0;has_more boolean:=false;result jsonb;
begin
 perform public.custodial_begin_application_mutation();
 if p_credential is null or p_native_request is null or coalesce(p_credential_hash,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_attestation_digest,'') !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_body) is distinct from 'object' or octet_length(p_body::text)>65536
  or (select array_agg(key order by key) from jsonb_object_keys(p_body) key) is distinct from
   array['assignment_epoch','ceiling','credential_id','cursor','device_id','employee_id','generation_ids','limit','principal_digest','scan_id','schema','server_now']
  or p_body->>'schema' is distinct from 'custodial.native-provider-inventory-request.v1'
  or p_body->>'credential_id' is distinct from p_credential::text or p_body->'limit' is distinct from '32'::jsonb
  or jsonb_typeof(p_body->'assignment_epoch') is distinct from 'number' or coalesce(p_body->>'assignment_epoch','') !~ '^[1-9][0-9]{0,15}$'
  or (p_body->>'assignment_epoch')::numeric>9007199254740991
  or coalesce(p_body->>'principal_digest','') !~ '^[0-9a-f]{64}$' or coalesce(p_body->>'scan_id','') !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or jsonb_typeof(p_body->'generation_ids') is distinct from 'array' or jsonb_array_length(p_body->'generation_ids') not between 1 and 32
  or public.custodial_native_location_tuple(p_body->'cursor') is not true or public.custodial_native_location_tuple(p_body->'ceiling') is not true
 then raise exception 'exact bounded native inventory request required' using errcode='22023';end if;
 foreach field in array array['schema','credential_id','device_id','employee_id','principal_digest','scan_id'] loop
  if jsonb_typeof(p_body->field) is distinct from 'string' then raise exception 'inventory string required' using errcode='22023';end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_body->'generation_ids') x where jsonb_typeof(x)<>'string' or x#>>'{}' !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$')
  or (select count(distinct x) from jsonb_array_elements(p_body->'generation_ids') x)<>jsonb_array_length(p_body->'generation_ids')
 then raise exception 'exact unique native generations required' using errcode='22023';end if;
 sid:=(p_body->>'scan_id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id where c0.credential_id=p_credential for update of d0;
 select * into c from public.device_auth_credentials where credential_id=p_credential for update;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 perform 1 from public.employee_native_push_generations where generation_id in(select x::uuid from jsonb_array_elements_text(p_body->'generation_ids') x) order by generation_id for update;
 at_time:=coalesce(p_test_at,clock_timestamp());
 if not isfinite(at_time) or d.id is null or d.active is not true or d.device_id !~ '^KIOSK_(0[2-9]|10)$'
  or c.token_hash is distinct from p_credential_hash or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=at_time
  or d.device_id is distinct from p_body->>'device_id' or d.assigned_employee_id::text is distinct from p_body->>'employee_id'
  or d.assignment_epoch::text is distinct from p_body->>'assignment_epoch'
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$') then
  raise exception 'current inventory credential required' using errcode='42501';end if;
 for field in select jsonb_array_elements_text(p_body->'generation_ids') loop
  select * into g from public.employee_native_push_generations where generation_id=field::uuid;
  if g.generation_id is null or g.credential_id is distinct from c.credential_id or g.device_id is distinct from d.id
   or g.device_identifier is distinct from d.device_id or g.employee_id is distinct from d.assigned_employee_id
   or g.assignment_epoch is distinct from d.assignment_epoch or g.principal_digest is distinct from p_body->>'principal_digest'
   or g.revoked_at is not null or g.activated_at>at_time then raise exception 'current exact inventory generations required' using errcode='42501';end if;
 end loop;
 select * into scan from public.employee_native_location_inventory_scans where scan_id=sid;
 if scan.scan_id is null then
  if p_body->'cursor'<>'null'::jsonb or p_body->'ceiling'<>'null'::jsonb or p_body->'server_now'<>'null'::jsonb then
   return jsonb_build_object('ok',false,'error','custodial_native_provider_cursor_invalid','schema','custodial.native-provider-inventory-restart.v1',
    'scan_id',sid::text,'principal_digest',p_body->>'principal_digest','cursor',p_body->'cursor','ceiling',p_body->'ceiling',
    'server_now',p_body->'server_now','generation_ids',p_body->'generation_ids');end if;
  select coalesce(array_agg(x.job_id order by x.reservation_at,x.job_id),'{}'::uuid[]) into ids from (
   select * from public.custodial_native_location_inventory_rows(p_credential,p_body->>'principal_digest',p_body->'generation_ids',at_time)
    where reservation_at<=at_time order by reservation_at,job_id limit 4097) x;
  if cardinality(ids)>4096 then raise exception 'inventory bounded snapshot capacity pending';end if;
  bound:='null'::jsonb;
  if cardinality(ids)>0 then select public.custodial_native_provider_original_tuple(ids[cardinality(ids)]) into bound;
   if bound is null then raise exception 'original bounded native ceiling unavailable' using errcode='42501';end if;end if;
  insert into public.employee_native_location_inventory_scans(scan_id,credential_id,employee_id,device_identifier,assignment_epoch,principal_digest,
   generation_ids,server_now,ceiling,candidate_jobs,first_native_request_id,first_attestation_digest)
   values(sid,p_credential,d.assigned_employee_id,d.device_id,d.assignment_epoch,p_body->>'principal_digest',p_body->'generation_ids',at_time,bound,ids,p_native_request,p_attestation_digest)
   returning * into scan;
 else
  if scan.credential_id<>p_credential or scan.employee_id<>d.assigned_employee_id or scan.device_identifier<>d.device_id
   or scan.assignment_epoch<>d.assignment_epoch or scan.principal_digest<>p_body->>'principal_digest' or scan.generation_ids<>p_body->'generation_ids'
   then raise exception 'inventory scan original principal conflict' using errcode='23505';end if;
 end if;
 -- Initial response-loss retry may carry all NULL bounds for this same scan.
 if not(p_body->'cursor'='null'::jsonb and p_body->'ceiling'='null'::jsonb and p_body->'server_now'='null'::jsonb) then
  if p_body->'ceiling' is distinct from scan.ceiling
   or p_body->'server_now' is distinct from to_jsonb(public.custodial_native_location_utc(scan.server_now))
   or (p_body->'cursor'<>'null'::jsonb and not exists(select 1 from unnest(scan.candidate_jobs) job(job_id)
    where job.job_id::text=p_body#>>'{cursor,job_id}'
     and public.custodial_native_provider_original_tuple(job.job_id)=p_body->'cursor')) then
   return jsonb_build_object('ok',false,'error','custodial_native_provider_cursor_invalid','schema','custodial.native-provider-inventory-restart.v1',
    'scan_id',sid::text,'principal_digest',p_body->>'principal_digest','cursor',p_body->'cursor','ceiling',p_body->'ceiling',
    'server_now',p_body->'server_now','generation_ids',p_body->'generation_ids');end if;
 end if;
 cursor_value:=p_body->'cursor';
 for entry in select x.* from public.custodial_native_location_inventory_rows(p_credential,scan.principal_digest,scan.generation_ids,at_time) x
  where x.job_id=any(scan.candidate_jobs)
   and (p_body->'cursor'='null'::jsonb or (x.reservation_at,x.job_id)>((p_body#>>'{cursor,reservation_at}')::timestamptz,(p_body#>>'{cursor,job_id}')::uuid))
  order by x.reservation_at,x.job_id limit 33 loop
  if count_rows=32 then has_more:=true;exit;end if;
  count_rows:=count_rows+1;rows_value:=rows_value||jsonb_build_array(jsonb_build_object('payload',entry.payload,'provider_outcome',entry.provider_outcome));
  cursor_value:=jsonb_build_object('reservation_at',public.custodial_native_location_utc(entry.reservation_at),'job_id',entry.job_id::text);
 end loop;
 result:=jsonb_build_object('ok',true,'data',jsonb_build_object('schema','custodial.native-provider-inventory.v1','scan_id',sid::text,
  'principal_digest',scan.principal_digest,'device_id',scan.device_identifier,'credential_id',scan.credential_id::text,'employee_id',scan.employee_id::text,
  'assignment_epoch',scan.assignment_epoch,'generation_ids',scan.generation_ids,'cursor',cursor_value,'ceiling',scan.ceiling,
  'server_now',public.custodial_native_location_utc(scan.server_now),'has_more',has_more,'rows',rows_value));
 if octet_length(result::text)>262144 then raise exception 'inventory bounded response pending';end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_outcome_at(p_binding jsonb, p_evidence jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare receipt public.employee_native_push_delivery_receipts%rowtype;g public.employee_native_push_generations%rowtype;
 prior public.employee_native_location_outcomes%rowtype;terminal public.employee_native_location_outcomes%rowtype;
 expected jsonb;operation uuid;state text;at_time timestamptz;replayed boolean:=false;
begin
 perform public.custodial_begin_application_mutation();
 if jsonb_typeof(p_binding) is distinct from 'object' or jsonb_typeof(p_evidence) is distinct from 'object'
  or octet_length(p_binding::text)>4096 or octet_length(p_evidence::text)>4096
  or (select array_agg(key order by key) from jsonb_object_keys(p_evidence) key) is distinct from array['error_code','operation_id','outcome','provider_message_id']
  or jsonb_typeof(p_evidence->'operation_id') is distinct from 'string' or p_evidence->>'operation_id' !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or jsonb_typeof(p_evidence->'outcome') is distinct from 'string' or p_evidence->>'outcome' not in ('delivery_outcome_unknown','provider_accepted','known_nonacceptance')
  or jsonb_typeof(p_binding->'receipt_job_id') is distinct from 'string' or p_binding->>'receipt_job_id' !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
 then raise exception 'exact native outcome binding/evidence required' using errcode='22023';end if;
 state:=p_evidence->>'outcome';operation:=(p_evidence->>'operation_id')::uuid;
 if state='provider_accepted' then
  if jsonb_typeof(p_evidence->'provider_message_id') is distinct from 'string' or length(p_evidence->>'provider_message_id') not between 1 and 1000
   or p_evidence->>'provider_message_id'<>btrim(p_evidence->>'provider_message_id') or p_evidence->>'provider_message_id' ~ '[[:cntrl:]]'
   or p_evidence->'error_code' is distinct from 'null'::jsonb then raise exception 'exact provider acceptance required' using errcode='22023';end if;
 else
  if p_evidence->'provider_message_id' is distinct from 'null'::jsonb or jsonb_typeof(p_evidence->'error_code') is distinct from 'string'
   or p_evidence->>'error_code' !~ '^[a-z][a-z0-9_]{0,99}$' then raise exception 'bounded outcome diagnostic required' using errcode='22023';end if;
 end if;
 select * into receipt from public.employee_native_push_delivery_receipts where job_id=(p_binding->>'receipt_job_id')::uuid;
 if receipt.native_generation_id is null then raise exception 'original native reservation required' using errcode='42501';end if;
 if exists(select 1 from public.employee_native_location_dispatch_attempts where job_id=receipt.job_id and outcome_operation_id<>operation) then
  raise exception 'original dispatch outcome operation required' using errcode='23505';end if;
 if receipt.native_payload->>'schema'='custodial.native-provider-payload.v1'
  and (receipt.native_payload->>'kind' is distinct from 'employee_lunch_coverage'
   or not exists(select 1 from public.employee_native_lunch_dispatch_attempts
    where job_id=receipt.job_id and outcome_operation_id=operation)) then
  raise exception 'original LUNCH dispatch outcome operation required' using errcode='23505';end if;
 select * into g from public.employee_native_push_generations where generation_id=receipt.native_generation_id;
 -- Original ledger settlement remains legal after rotation/removal/lease expiry;
 -- it neither dispatches nor updates a successor registration's health.
 perform 1 from public.devices where id=g.device_id for update;
 perform 1 from public.device_auth_credentials where credential_id=receipt.credential_id for update;
 perform 1 from public.employee_push_registrations where device_id=g.device_id order by registration_id for update;
 perform 1 from public.employee_native_push_generations where generation_id=g.generation_id for update;
 perform 1 from public.operational_notification_jobs where job_id=receipt.job_id for update;
 select r0.* into receipt from public.employee_native_push_delivery_receipts r0 where r0.job_id=receipt.job_id for update;
 expected:=jsonb_build_object('receipt_job_id',receipt.job_id::text,'lease_token',receipt.lease_token::text,
  'registration_id',receipt.registration_id::text,'generation_id',receipt.native_generation_id::text,
  'reservation_at',public.custodial_native_location_utc(receipt.prepared_at),'content_sha256',receipt.native_payload_sha256,
  'token_digest',receipt.token_hash,'principal_digest',receipt.native_payload->>'principal_digest',
  'receipt_credential_id',receipt.credential_id::text,'receipt_assignment_epoch',receipt.assignment_epoch::text,
  'receipt_employee_id',receipt.native_payload->>'receipt_employee_id','receipt_device_id',receipt.native_payload->>'receipt_device_id');
 if p_binding is distinct from expected then raise exception 'original reservation identity mismatch' using errcode='23505';end if;
 select * into prior from public.employee_native_location_outcomes where operation_id=operation;
 if prior.operation_id is not null then
  if prior.binding is distinct from expected or prior.evidence is distinct from p_evidence then raise exception 'outcome operation identity conflict' using errcode='23505';end if;
  replayed:=true;
 else
  select * into terminal from public.employee_native_location_outcomes where job_id=receipt.job_id and outcome<>'delivery_outcome_unknown';
  if terminal.operation_id is not null then raise exception 'original reservation already has exact final outcome' using errcode='23505';end if;
  at_time:=coalesce(p_test_at,clock_timestamp());
  if not isfinite(at_time) or at_time<receipt.prepared_at then raise exception 'outcome server time unavailable';end if;
  insert into public.employee_native_location_outcomes(operation_id,job_id,generation_id,binding,evidence,outcome,server_received_at)
   values(operation,receipt.job_id,receipt.native_generation_id,expected,p_evidence,state,at_time) returning * into prior;
 end if;
 return jsonb_build_object('schema','custodial.native-location-outcome-receipt.v1','binding',prior.binding,'evidence',prior.evidence,
  'server_received_at',public.custodial_native_location_utc(prior.server_received_at),'replayed',replayed,'dispatch_authorized',false);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_outcome_status(p_binding jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.employee_native_push_delivery_receipts%rowtype;o public.employee_native_location_outcomes%rowtype;expected jsonb;
begin
 perform public.custodial_begin_application_mutation();
 if jsonb_typeof(p_binding) is distinct from 'object' or octet_length(p_binding::text)>4096
  or jsonb_typeof(p_binding->'receipt_job_id') is distinct from 'string' or p_binding->>'receipt_job_id' !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
 then raise exception 'exact original outcome status binding required' using errcode='22023';end if;
 -- This read serializes with settlement at its final job->receipt fence. It
 -- acquires no device/generation lock afterward and cannot reverse that order.
 perform 1 from public.operational_notification_jobs where job_id=(p_binding->>'receipt_job_id')::uuid for update;
 select * into r from public.employee_native_push_delivery_receipts where job_id=(p_binding->>'receipt_job_id')::uuid for update;
 if r.native_generation_id is null then raise exception 'original native reservation required' using errcode='42501';end if;
 expected:=jsonb_build_object('receipt_job_id',r.job_id::text,'lease_token',r.lease_token::text,'registration_id',r.registration_id::text,
  'generation_id',r.native_generation_id::text,'reservation_at',public.custodial_native_location_utc(r.prepared_at),
  'content_sha256',r.native_payload_sha256,'token_digest',r.token_hash,'principal_digest',r.native_payload->>'principal_digest',
  'receipt_credential_id',r.credential_id::text,'receipt_assignment_epoch',r.assignment_epoch::text,
  'receipt_employee_id',r.native_payload->>'receipt_employee_id','receipt_device_id',r.native_payload->>'receipt_device_id');
 if p_binding is distinct from expected then raise exception 'original outcome status identity mismatch' using errcode='23505';end if;
 select * into o from public.employee_native_location_outcomes where job_id=r.job_id
  order by (outcome<>'delivery_outcome_unknown') desc,server_received_at desc,operation_id desc limit 1;
 return jsonb_build_object('schema','custodial.native-location-outcome-status.v1','binding',expected,'dispatch_authorized',false,
  'provider_outcome',coalesce(o.outcome,'prepared'),'evidence',o.evidence,'server_received_at',public.custodial_native_location_utc(o.server_received_at));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_project_ack(p_event uuid, p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare e public.employee_native_provider_events%rowtype;r public.employee_native_push_delivery_receipts%rowtype;
 g public.employee_native_push_generations%rowtype;d public.devices%rowtype;c public.device_auth_credentials%rowtype;
 a public.device_notification_acknowledgements%rowtype;prior public.employee_native_location_ack_projections%rowtype;field text;
begin
 perform public.custodial_begin_application_mutation();
 select * into e from public.employee_native_provider_events where event_id=p_event;
 if e.event_id is null or e.action<>'acknowledged' then raise exception 'exact admitted native ACK required' using errcode='42501';end if;
 select * into g from public.employee_native_push_generations where generation_id=e.generation_id;
 -- Reentrant when called by the receipt owner; no new reverse-order lock.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into d from public.devices where id=g.device_id for update;
 select * into c from public.device_auth_credentials where credential_id=e.credential_id for update;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 select * into g from public.employee_native_push_generations where generation_id=e.generation_id for update;
 perform 1 from public.operational_notification_jobs where job_id=e.job_id for update;
 select * into r from public.employee_native_push_delivery_receipts where job_id=e.job_id for update;
 if p_at is null or not isfinite(p_at) or p_at<e.server_received_at or d.active is not true or c.revoked_at is not null or c.confirmed_at is null or c.expires_at<=p_at
  or c.device_id is distinct from d.id or g.device_id is distinct from d.id or g.credential_id is distinct from c.credential_id
  or g.employee_id is distinct from d.assigned_employee_id or g.assignment_epoch is distinct from d.assignment_epoch or g.revoked_at is not null
  or r.native_generation_id is distinct from g.generation_id or r.registration_id is distinct from g.registration_id
  or r.credential_id is distinct from c.credential_id or r.assignment_epoch is distinct from d.assignment_epoch
  or r.native_payload->>'schema' is distinct from 'custodial.native-location-payload.v2'
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$') then
  raise exception 'current original ACK identity required' using errcode='42501';end if;
 foreach field in array array['generation_id','receipt_job_id','notification_key','receipt_credential_id','receipt_employee_id','receipt_device_id',
  'receipt_assignment_epoch','principal_digest','token_digest','content_sha256'] loop
  if e.original_event->>field is distinct from r.native_payload->>field then raise exception 'ACK original reservation mismatch' using errcode='42501';end if;
 end loop;
 select * into prior from public.employee_native_location_ack_projections where event_id=p_event;
 if prior.event_id is not null then return;end if;
 insert into public.device_notification_acknowledgements as old(device_identifier,notification_key,notification_type,
  credential_id,assignment_epoch,employee_id,notification_job_id,acknowledged_at,metadata_json)
 values(d.device_id,r.native_payload->>'notification_key','location_status',c.credential_id,d.assignment_epoch,d.assigned_employee_id,r.job_id,e.server_received_at,
  jsonb_build_object('schema','custodial.native-location-ack-projection.v1','native_event_id',e.event_id))
 on conflict(device_identifier,notification_key,credential_id,assignment_epoch) do update
  set acknowledged_at=coalesce(old.acknowledged_at,excluded.acknowledged_at),
   updated_at=case when old.acknowledged_at is null then p_at else old.updated_at end
  where old.employee_id=excluded.employee_id and old.notification_job_id=excluded.notification_job_id and old.notification_type=excluded.notification_type
 returning * into a;
 if a.id is null then raise exception 'legacy ACK original actor/job conflict' using errcode='23505';end if;
 insert into public.employee_native_location_ack_projections values(e.event_id,r.job_id,a.id,p_at,a.acknowledged_at);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_receipt_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if old.native_generation_id is not null and (tg_op='DELETE' or to_jsonb(new) is distinct from to_jsonb(old)) then
  raise exception 'native location reservation immutable; exact outcome owner required' using errcode='23514';
 end if;
 if tg_op='DELETE' then return old;end if;
 if old.native_generation_id is null and new.native_generation_id is not null then
  raise exception 'historical receipt cannot acquire fabricated native lineage' using errcode='23514';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_reserve_at(p_job uuid, p_lease uuid, p_expected jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;r public.employee_push_registrations%rowtype;
 g public.employee_native_push_generations%rowtype;j public.operational_notification_jobs%rowtype;
 prior public.employee_native_push_delivery_receipts%rowtype;a record;v record;
 at_time timestamptz;until_time timestamptz;coverage_end timestamptz;day_end timestamptz;
 service_date date;data jsonb;wire text;digest text;field text;authority_count integer;employee_name text;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_lease is null or jsonb_typeof(p_expected) is distinct from 'object'
  or (select array_agg(key order by key) from jsonb_object_keys(p_expected) key) is distinct from
   array['assignment_epoch','credential_id','device_id','employee_id','generation_id','principal_digest','registration_id','token_digest']
  or exists(select 1 from jsonb_each(p_expected) e where jsonb_typeof(e.value)<>'string')
 then raise exception 'exact native location recipient required' using errcode='22023';end if;
 foreach field in array array['credential_id','employee_id','generation_id','registration_id'] loop
  if p_expected->>field !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then raise exception 'invalid native location UUID';end if;
 end loop;
 if p_expected->>'assignment_epoch' !~ '^[1-9][0-9]{0,15}$'
  or (p_expected->>'assignment_epoch')::numeric>9007199254740991
  or p_expected->>'principal_digest' !~ '^[0-9a-f]{64}$' or p_expected->>'token_digest' !~ '^[0-9a-f]{64}$'
  or p_expected->>'device_id' !~ '^KIOSK_(0[2-9]|10)$' then raise exception 'invalid native location principal';end if;
 -- Same schedule fence as publication, then native registration lock order.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id
  where c0.credential_id=(p_expected->>'credential_id')::uuid for update of d0;
 select * into c from public.device_auth_credentials where credential_id=(p_expected->>'credential_id')::uuid for update;
 select display_name into employee_name from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 select * into r from public.employee_push_registrations where registration_id=(p_expected->>'registration_id')::uuid;
 select * into g from public.employee_native_push_generations where generation_id=(p_expected->>'generation_id')::uuid for update;
 select * into j from public.operational_notification_jobs where job_id=p_job for update;
 at_time:=coalesce(p_test_at,clock_timestamp());service_date:=public.sch_service_date(at_time);
 if not isfinite(at_time) or d.id is null or d.active is not true or d.device_id is distinct from p_expected->>'device_id'
  or d.assigned_employee_id::text is distinct from p_expected->>'employee_id' or d.assignment_epoch::text is distinct from p_expected->>'assignment_epoch'
  or c.device_id is distinct from d.id or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=at_time
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$')
  or r.registration_id is null or r.device_id is distinct from d.id or r.credential_id is distinct from c.credential_id
  or r.employee_id is distinct from d.assigned_employee_id or r.assignment_epoch is distinct from d.assignment_epoch
  or r.platform is distinct from 'android' or r.active is not true or r.revoked_at is not null
  or r.token_hash is distinct from p_expected->>'token_digest'
  or public.static_weekly_digest_text(r.fcm_token) is distinct from r.token_hash
  or g.generation_id is null or g.registration_id is distinct from r.registration_id or g.device_id is distinct from d.id
  or g.device_identifier is distinct from d.device_id or g.credential_id is distinct from c.credential_id
  or g.employee_id is distinct from d.assigned_employee_id or g.assignment_epoch is distinct from d.assignment_epoch
  or g.principal_digest is distinct from p_expected->>'principal_digest' or g.token_digest is distinct from r.token_hash
  or g.revoked_at is not null or g.dispatch_retired_at is not null or g.activated_at>at_time then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_recipient_superseded');end if;
 if j.job_id is null or j.job_type is distinct from 'employee_native_push' or j.status is distinct from 'leased'
  or j.lease_token is distinct from p_lease or j.leased_until is null or j.leased_until<=at_time
  or j.payload_json->>'credential_id' is distinct from c.credential_id::text
  or j.payload_json->>'employee_id' is distinct from d.assigned_employee_id::text
  or j.payload_json->>'device_id' is distinct from d.id::text
  or j.payload_json->>'device_identifier' is distinct from d.device_id
  or j.payload_json->>'assignment_epoch' is distinct from d.assignment_epoch::text
  or j.payload_json#>>'{data_json,kind}' is distinct from 'employee_location_status'
  or (j.payload_json#>'{data_json,test_delivery}') is not null then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_job_superseded');end if;
 if coalesce((public.mz_validate_employee_location_reminder(p_job,p_lease,at_time)->>'current')::boolean,false) is not true then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_authority_superseded');end if;
 -- Derive content from current owning readers, not arbitrary queued data/title.
 select count(*) into authority_count from public.custodial_operational_location_assignments(service_date) x
  where x.location_id=j.source_id and x.assigned_employee_id=d.assigned_employee_id and x.assignment_status='ASSIGNED'
   and x.projection_status='current' and x.projection_id::text=j.payload_json#>>'{data_json,projection_id}'
   and x.publication_id::text=j.payload_json#>>'{data_json,publication_id}'
   and x.coverage_start<=(at_time at time zone 'America/Chicago')::time and x.coverage_end>(at_time at time zone 'America/Chicago')::time;
 if authority_count<>1 then return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_authority_ambiguous');end if;
 select x.*,s.source_id,s.source_digest into strict a from public.custodial_operational_location_assignments(service_date) x
  join public.weekly_schedule_versions version on version.version_id=x.version_id
  join public.weekly_schedule_publications publication on publication.publication_id=x.publication_id and publication.version_id=version.version_id
  join public.static_weekly_authority_source_documents s on s.source_id=version.authority_source_id
  where x.location_id=j.source_id and x.assigned_employee_id=d.assigned_employee_id and x.assignment_status='ASSIGNED'
   and x.projection_status='current' and x.projection_id::text=j.payload_json#>>'{data_json,projection_id}'
   and x.publication_id::text=j.payload_json#>>'{data_json,publication_id}'
   and x.coverage_start<=(at_time at time zone 'America/Chicago')::time and x.coverage_end>(at_time at time zone 'America/Chicago')::time;
 select * into strict v from public.mz_location_reminder_candidates(service_date,at_time) x where x.location_id=j.source_id;
 if j.job_key is distinct from 'employee-location-push:'||v.notification_key||':projection:'||a.projection_id::text||':'||c.credential_id::text then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_occurrence_key_superseded');end if;
 if a.authority_source not in ('static_weekly_projection','static_weekly_lunch_coverage') or a.occurrence_id is null
  or a.source_digest !~ '^[0-9a-f]{64}$' or a.location_code !~ '^[A-Z0-9._:-]{1,100}$' then raise exception 'unsupported exact native location authority';end if;
 coverage_end:=(service_date+a.coverage_end) at time zone 'America/Chicago';
 day_end:=((service_date+1)::timestamp+make_interval(hours=>public.get_setting_int('operational_day_start_hour',4))) at time zone 'America/Chicago';
 until_time:=least(coverage_end,day_end,c.expires_at,case when v.status_code='due_soon' then v.overdue_at
  else v.overdue_at+(floor(extract(epoch from at_time-v.overdue_at)/300)+1)*interval '5 minutes' end);
 if until_time<=at_time then return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_expired');end if;
 select * into prior from public.employee_native_push_delivery_receipts where job_id=p_job for update;
 if prior.job_id is not null then
  if prior.native_generation_id is distinct from g.generation_id or prior.registration_id<>r.registration_id
   or prior.credential_id<>c.credential_id or prior.assignment_epoch<>d.assignment_epoch or prior.token_hash<>g.token_digest
   or prior.job_key<>j.job_key or prior.source_id<>j.source_id or prior.native_valid_until<=at_time
   or prior.native_payload->>'projection_id' is distinct from a.projection_id::text
   or prior.native_payload->>'publication_id' is distinct from a.publication_id::text
   or prior.native_payload->>'version_id' is distinct from a.version_id::text
   or prior.native_payload->>'occurrence_id' is distinct from a.occurrence_id::text
   or prior.native_payload->>'authority_source_id' is distinct from a.source_id::text
   or prior.native_payload->>'authority_source_digest' is distinct from a.source_digest
   or prior.native_payload->>'authority_source' is distinct from a.authority_source
   or prior.native_payload->>'notification_key' is distinct from v.notification_key||':projection:'||a.projection_id::text then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_original_reservation_conflict');end if;
  if public.custodial_native_location_live(p_job,prior.native_payload,at_time) is not true then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_authority_superseded');end if;
  if exists(select 1 from public.employee_native_location_outcomes where job_id=p_job and outcome<>'delivery_outcome_unknown') then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_final_outcome_no_resend');end if;
  return jsonb_build_object('current',true,'dispatch_authorized',false,'replayed',true,'delivery_outcome_unknown',true,
   'reason','native_location_outcome_unknown_no_resend','payload',prior.native_payload,
   'wire',public.custodial_native_location_canonical(prior.native_payload));
 end if;
 data:=jsonb_build_object('schema','custodial.native-location-payload.v2','kind','employee_location_status','notification_type','location_status',
  'generation_id',g.generation_id::text,'principal_digest',g.principal_digest,'token_digest',g.token_digest,
  'receipt_job_id',j.job_id::text,'receipt_credential_id',c.credential_id::text,'receipt_employee_id',d.assigned_employee_id::text,
  'receipt_device_id',d.device_id,'receipt_assignment_epoch',d.assignment_epoch::text,
  'notification_key',v.notification_key||':projection:'||a.projection_id::text,
  'reservation_at',to_char(at_time at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'valid_until',to_char(until_time at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'title',a.location_name||case when v.status_code='overdue' then ' is overdue' else ' is due soon' end,
  'body',employee_name||', '||a.location_name||case when v.status_code='overdue' then ' on your assigned route is overdue and needs attention now.' else ' on your assigned route is due soon for a check.' end,
  'channel_id',case when v.status_code='overdue' then 'employee-overdue' else 'employee-due-soon' end,
  'route','employee-schedule.html?hub=employee&highlight='||a.location_code,'service_date',service_date::text,
  'reminder_contract','verified-visit-reminders.v2','cleaned_at',to_char(v.cleaned_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'cycle_base_at',to_char(v.cycle_base_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'cycle_base_evidence',v.cycle_base_evidence,
  'due_soon_at',to_char(v.due_soon_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'overdue_at',to_char(v.overdue_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'status_code',v.status_code,
  'location_id',a.location_id::text,'location_code',a.location_code,'location_name',a.location_name,'form_type',a.form_type,
  'group_code',coalesce(a.group_code,''),'group_name',coalesce(a.group_name,''),'projection_id',a.projection_id::text,
  'publication_id',a.publication_id::text,'version_id',a.version_id::text,'occurrence_id',a.occurrence_id::text,
  'authority_source',a.authority_source,'authority_source_id',a.source_id::text,'authority_source_digest',a.source_digest,
  'coverage_end_at',to_char(coverage_end at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'operational_end_at',to_char(day_end at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 -- Conservative UTF8 byte bounds also satisfy native UTF16 character bounds.
 -- Refuse unsupported source text BEFORE creating an immutable reservation;
 -- never truncate authoritative names or leave a permanently undecodable row.
 if exists(select 1 from jsonb_each_text(data) e where octet_length(e.value)>case
   when e.key in ('title','location_name','group_name') then 180
   when e.key in ('location_code','group_code') then 100
   when e.key='notification_key' then 240 else 1000 end
   or regexp_replace(e.value,E'[\\n\\r\\t]','','g') ~ '[[:cntrl:]]'
   or (e.key in ('title','location_name','group_name','group_code') and e.value ~ '[[:cntrl:]]')) then
  raise exception 'native location source text unsupported; no truncation';end if;
 if public.custodial_native_location_live(p_job,data,at_time) is not true then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_location_authority_superseded');end if;
 digest:=public.static_weekly_digest_text(public.custodial_native_location_canonical(data));
 data:=data||jsonb_build_object('content_sha256',digest);wire:=public.custodial_native_location_canonical(data);
 if octet_length(wire)>3500 then raise exception 'native location payload too large; no truncation';end if;
 insert into public.employee_native_push_delivery_receipts(job_id,job_key,source_id,lease_token,credential_id,assignment_epoch,
  registration_id,token_hash,prepared_at,native_generation_id,native_payload,native_payload_sha256,native_valid_until)
 values(j.job_id,j.job_key,j.source_id,p_lease,c.credential_id,d.assignment_epoch,r.registration_id,g.token_digest,at_time,g.generation_id,data,digest,until_time);
 return jsonb_build_object('current',true,'dispatch_authorized',true,'replayed',false,'delivery_outcome_unknown',false,'payload',data,'wire',wire);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_location_target_at(p_job uuid, p_lease uuid, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;r public.employee_push_registrations%rowtype;
 g public.employee_native_push_generations%rowtype;j public.operational_notification_jobs%rowtype;at_time timestamptz;cid uuid;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_lease is null then raise exception 'native target job/lease required' using errcode='22023';end if;
 select (payload_json->>'credential_id')::uuid into cid from public.operational_notification_jobs where job_id=p_job;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id where c0.credential_id=cid for update of d0;
 select * into c from public.device_auth_credentials where credential_id=cid for update;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 select * into g from public.employee_native_push_generations where device_id=d.id and dispatch_retired_at is null and revoked_at is null for update;
 select * into r from public.employee_push_registrations where registration_id=g.registration_id;
 select * into j from public.operational_notification_jobs where job_id=p_job for update;
 at_time:=coalesce(p_test_at,clock_timestamp());
 if d.id is null or not isfinite(at_time) or d.active is not true or d.device_id !~ '^KIOSK_(0[2-9]|10)$'
  or c.device_id is distinct from d.id or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=at_time
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$')
  or g.generation_id is null or g.credential_id is distinct from c.credential_id or g.employee_id is distinct from d.assigned_employee_id
  or g.assignment_epoch is distinct from d.assignment_epoch or g.device_identifier is distinct from d.device_id or g.activated_at>at_time
  or r.registration_id is null or r.device_id is distinct from d.id or r.credential_id is distinct from c.credential_id
  or r.employee_id is distinct from d.assigned_employee_id or r.assignment_epoch is distinct from d.assignment_epoch
  or r.active is not true or r.revoked_at is not null or r.platform is distinct from 'android'
  or r.token_hash is distinct from g.token_digest or public.static_weekly_digest_text(r.fcm_token) is distinct from g.token_digest
  or j.job_type is distinct from 'employee_native_push' or j.status is distinct from 'leased' or j.lease_token is distinct from p_lease
  or j.leased_until is null or j.leased_until<=at_time or j.payload_json->>'credential_id' is distinct from cid::text
  or j.payload_json->>'device_id' is distinct from d.id::text or j.payload_json->>'device_identifier' is distinct from d.device_id
  or j.payload_json->>'employee_id' is distinct from d.assigned_employee_id::text or j.payload_json->>'assignment_epoch' is distinct from d.assignment_epoch::text
  or j.payload_json#>>'{data_json,kind}' is distinct from 'employee_location_status' or j.payload_json#>'{data_json,test_delivery}' is not null
  or coalesce((public.mz_validate_employee_location_reminder(p_job,p_lease,at_time)->>'current')::boolean,false) is not true then
  return jsonb_build_object('current',false,'reason','native_location_target_unavailable');end if;
 return jsonb_build_object('current',true,'expected',jsonb_build_object('assignment_epoch',d.assignment_epoch::text,
  'credential_id',cid::text,'device_id',d.device_id,'employee_id',d.assigned_employee_id::text,'generation_id',g.generation_id::text,
  'principal_digest',g.principal_digest,'registration_id',r.registration_id::text,'token_digest',g.token_digest),'token',r.fcm_token);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_lunch_dispatch_prepare_at(p_job uuid, p_lease uuid, p_expected jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare reserved jsonb;a public.employee_native_lunch_dispatch_attempts%rowtype;ttl bigint;
begin
 perform public.custodial_begin_application_mutation();
 reserved:=public.custodial_native_lunch_reserve_at(p_job,p_lease,p_expected,p_test_at);
 if reserved->'dispatch_authorized' is distinct from 'true'::jsonb then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_lunch_dispatch_not_fresh');end if;
 insert into public.employee_native_lunch_dispatch_attempts(job_id) values(p_job) returning * into a;
 ttl:=least(2419200,floor(extract(epoch from
  (reserved#>>'{payload,valid_until}')::timestamptz-(reserved#>>'{payload,reservation_at}')::timestamptz))::bigint);
 if ttl<=0 then raise exception 'native LUNCH validity unavailable';end if;
 return jsonb_build_object('schema','custodial.native-lunch-dispatch.v1','dispatch_authorized',true,
  'reservation',reserved,'attempt_id',a.attempt_id,'outcome_operation_id',a.outcome_operation_id,'ttl_seconds',ttl);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_lunch_dispatch_status(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.employee_native_push_delivery_receipts%rowtype;a public.employee_native_lunch_dispatch_attempts%rowtype;b jsonb;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null then raise exception 'exact original lunch job required' using errcode='22023';end if;
 perform 1 from public.operational_notification_jobs where job_id=p_job for update;
 select * into r from public.employee_native_push_delivery_receipts where job_id=p_job for update;
 if r.job_id is null then return jsonb_build_object('schema','custodial.native-lunch-dispatch-status.v1',
  'reserved',false,'dispatch_authorized',false);end if;
 if r.native_generation_id is null or r.native_payload->>'schema' is distinct from 'custodial.native-provider-payload.v1'
  or r.native_payload->>'kind' is distinct from 'employee_lunch_coverage' then
  raise exception 'original LUNCH native reservation required' using errcode='42501';end if;
 select * into a from public.employee_native_lunch_dispatch_attempts where job_id=p_job;
 b:=jsonb_build_object('receipt_job_id',r.job_id::text,'lease_token',r.lease_token::text,
  'registration_id',r.registration_id::text,'generation_id',r.native_generation_id::text,
  'reservation_at',public.custodial_native_location_utc(r.prepared_at),'content_sha256',r.native_payload_sha256,
  'token_digest',r.token_hash,'principal_digest',r.native_payload->>'principal_digest',
  'receipt_credential_id',r.credential_id::text,'receipt_assignment_epoch',r.assignment_epoch::text,
  'receipt_employee_id',r.native_payload->>'receipt_employee_id','receipt_device_id',r.native_payload->>'receipt_device_id');
 return jsonb_build_object('schema','custodial.native-lunch-dispatch-status.v1','reserved',true,
  'dispatch_authorized',false,'binding',b,'attempt_id',a.attempt_id,'outcome_operation_id',a.outcome_operation_id);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_lunch_live(p_job uuid, p_payload jsonb, p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare j public.operational_notification_jobs%rowtype;authority record;
 doc public.weekly_schedule_lunch_documents%rowtype;intent jsonb;loan jsonb;responsibility jsonb;available jsonb;
 service_date date;scheduled timestamptz;ends_at timestamptz;
begin
 if p_job is null or p_at is null or not isfinite(p_at)
  or p_payload->>'schema' is distinct from 'custodial.native-provider-payload.v1'
  or p_payload->>'kind' is distinct from 'employee_lunch_coverage'
  or p_payload->>'valid_until' is null or (p_payload->>'valid_until')::timestamptz<=p_at then return false;end if;
 select * into j from public.operational_notification_jobs where job_id=p_job;
 if j.job_id is null or j.job_type is distinct from 'employee_native_push'
  or j.source_id::text is distinct from p_payload->>'projection_id'
  or j.job_key is distinct from 'employee-lunch-push:'||(p_payload->>'notification_key')||':'||(p_payload->>'receipt_credential_id')
  or j.payload_json->>'credential_id' is distinct from p_payload->>'receipt_credential_id'
  or j.payload_json->>'employee_id' is distinct from p_payload->>'receipt_employee_id'
  or j.payload_json->>'device_identifier' is distinct from p_payload->>'receipt_device_id'
  or j.payload_json->>'assignment_epoch' is distinct from p_payload->>'receipt_assignment_epoch'
  or j.payload_json#>>'{data_json,kind}' is distinct from 'employee_lunch_coverage'
  or j.payload_json#>'{data_json,test_delivery}' is not null then return false;end if;
 service_date:=(p_payload->>'service_date')::date;
 if public.sch_service_date(p_at) is distinct from service_date then return false;end if;
 select * into authority from public.static_weekly_v6_schedule_authority_state(service_date);
 if authority.governed is not true or authority.projection_status is distinct from 'current'
  or authority.projection_id is distinct from j.source_id then return false;end if;
 select * into doc from public.weekly_schedule_lunch_documents where projection_id=authority.projection_id;
 if doc.projection_id is null or doc.document_identity is distinct from p_payload->>'document_identity' then return false;end if;
 perform public.static_weekly_v8_assert_lunch_document(doc.projection_id,doc.document_json);
 select value into intent from jsonb_array_elements(doc.document_json->'notification_intents') value
  where value->>'notification_key'=p_payload->>'notification_key'
   and value->>'service_date'=service_date::text;
 select value into loan from jsonb_array_elements(doc.document_json->'loans') value
  where value->>'loan_id'=intent->>'loan_id' and value->>'status'='PLANNED';
 select value into responsibility from jsonb_array_elements(doc.document_json->'responsibilities') value
  where value->>'loan_id'=intent->>'loan_id'
   and value->>'coverer_slot_id'=intent->>'coverer_slot_id'
   and value->>'coverer_person_id'=p_payload->>'receipt_employee_id';
 select value into available from public.weekly_schedule_compiled_projections projection,
  jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}') value
  where projection.projection_id=authority.projection_id and value->>'serviceDate'=service_date::text
   and value->>'slotId'=intent->>'coverer_slot_id'
   and value->>'incumbentPersonId'=p_payload->>'receipt_employee_id' and value->>'status'='working';
 if intent is null or loan is null or responsibility is null or available is null
  or intent->>'event' not in ('start','end')
  or j.payload_json#>>'{data_json,notification_key}' is distinct from intent->>'notification_key'
  or j.payload_json#>>'{data_json,loan_id}' is distinct from intent->>'loan_id'
  or j.payload_json#>>'{data_json,event}' is distinct from intent->>'event'
  or j.payload_json#>>'{data_json,coverer_slot_id}' is distinct from intent->>'coverer_slot_id'
  or j.payload_json#>>'{data_json,scheduled_time}' is distinct from intent->>'scheduled_time'
  or j.payload_json#>>'{data_json,scheduled_at}' is distinct from public.custodial_native_location_utc(
    (service_date+(intent->>'scheduled_time')::time) at time zone 'America/Chicago')
  or j.payload_json#>>'{data_json,document_identity}' is distinct from doc.document_identity
  or p_payload->>'event' is distinct from intent->>'event'
  or p_payload->>'loan_id' is distinct from intent->>'loan_id'
  or p_payload->>'coverer_slot_id' is distinct from intent->>'coverer_slot_id'
  or p_payload->>'scheduled_time' is distinct from intent->>'scheduled_time'
  or p_payload->>'document_identity' is distinct from doc.document_identity then return false;end if;
 scheduled:=(service_date+(intent->>'scheduled_time')::time) at time zone 'America/Chicago';
 ends_at:=(service_date+(case when intent->>'event'='start' then loan->>'coverage_end'
  else available#>>'{shift,end}' end)::time) at time zone 'America/Chicago';
 if ends_at is null or ends_at<=scheduled or p_at<scheduled or p_at>=ends_at
  or p_payload->>'scheduled_at' is distinct from public.custodial_native_location_utc(scheduled)
  or (p_payload->>'valid_until')::timestamptz>ends_at
  or (intent->>'event'='start' and ends_at>scheduled+interval '1 hour') then return false;end if;
 return true;
exception when data_exception or invalid_datetime_format or datetime_field_overflow then return false;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_lunch_outcome_at(p_binding jsonb, p_evidence jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.employee_native_push_delivery_receipts%rowtype;v jsonb;
begin
 if p_binding->>'receipt_job_id' !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
  raise exception 'exact LUNCH outcome job required' using errcode='22023';end if;
 select * into r from public.employee_native_push_delivery_receipts where job_id=(p_binding->>'receipt_job_id')::uuid;
 if r.native_payload->>'schema' is distinct from 'custodial.native-provider-payload.v1'
  or r.native_payload->>'kind' is distinct from 'employee_lunch_coverage' then
  raise exception 'original LUNCH reservation required' using errcode='42501';end if;
 v:=public.custodial_native_location_outcome_at(p_binding,p_evidence,p_test_at);
 return (v-'schema')||jsonb_build_object('schema','custodial.native-lunch-outcome-receipt.v1');
end $function$

