CREATE OR REPLACE FUNCTION public.custodial_native_lunch_reserve_at(p_job uuid, p_lease uuid, p_expected jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare target jsonb;source jsonb;j public.operational_notification_jobs%rowtype;
 c public.device_auth_credentials%rowtype;r public.employee_push_registrations%rowtype;
 g public.employee_native_push_generations%rowtype;prior public.employee_native_push_delivery_receipts%rowtype;
 at_time timestamptz;until_time timestamptz;data jsonb;wire text;digest text;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_lease is null or jsonb_typeof(p_expected) is distinct from 'object'
  or (select array_agg(key order by key) from jsonb_object_keys(p_expected) key) is distinct from
   array['assignment_epoch','credential_id','device_id','employee_id','generation_id','principal_digest','registration_id','token_digest']
  or exists(select 1 from jsonb_each(p_expected) e where jsonb_typeof(e.value)<>'string') then
  raise exception 'exact native lunch recipient required' using errcode='22023';end if;
 -- The target call takes the current schedule, device, credential, registration,
 -- generation and job locks. The final time is sampled *after* those locks.
 target:=public.custodial_native_lunch_target_at(p_job,p_lease,p_test_at);
 if target->'current' is distinct from 'true'::jsonb or target->'expected' is distinct from p_expected then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_lunch_recipient_superseded');end if;
 at_time:=coalesce(p_test_at,clock_timestamp());
 select * into j from public.operational_notification_jobs where job_id=p_job;
 select * into c from public.device_auth_credentials where credential_id=(p_expected->>'credential_id')::uuid;
 select * into r from public.employee_push_registrations where registration_id=(p_expected->>'registration_id')::uuid;
 select * into g from public.employee_native_push_generations where generation_id=(p_expected->>'generation_id')::uuid;
 if not isfinite(at_time) or c.expires_at<=at_time or j.job_id is null or j.status is distinct from 'leased'
  or j.lease_token is distinct from p_lease or j.leased_until<=at_time
  or r.active is not true or r.revoked_at is not null or g.dispatch_retired_at is not null or g.revoked_at is not null then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_lunch_job_superseded');end if;
 source:=public.custodial_native_target_source_at('LUNCH',p_job,(p_expected->>'employee_id')::uuid,g.generation_id,at_time);
 if source->>'status' is distinct from 'CURRENT_SOURCE_ONLY'
  or (source#>>'{source,valid_from}')::timestamptz>at_time then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_lunch_authority_superseded');end if;
 until_time:=(source#>>'{source,valid_until}')::timestamptz;
 select * into prior from public.employee_native_push_delivery_receipts where job_id=p_job for update;
 if prior.job_id is not null then
  if prior.native_generation_id is distinct from g.generation_id or prior.registration_id is distinct from r.registration_id
   or prior.credential_id is distinct from c.credential_id or prior.assignment_epoch::text is distinct from p_expected->>'assignment_epoch'
   or prior.token_hash is distinct from g.token_digest or prior.job_key is distinct from j.job_key
   or prior.source_id is distinct from j.source_id or prior.native_payload->>'schema' is distinct from 'custodial.native-provider-payload.v1'
   or prior.native_valid_until<=at_time or public.custodial_native_lunch_live(p_job,prior.native_payload,at_time) is not true then
   return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_lunch_original_reservation_conflict');end if;
  return jsonb_build_object('current',true,'dispatch_authorized',false,'replayed',true,'delivery_outcome_unknown',true,
   'reason','native_lunch_outcome_unknown_no_resend','payload',prior.native_payload,
   'wire',public.custodial_native_location_canonical(prior.native_payload));
 end if;
 data:=jsonb_build_object('schema','custodial.native-provider-payload.v1','kind','employee_lunch_coverage',
  'notification_type','lunch_coverage','generation_id',g.generation_id::text,'principal_digest',g.principal_digest,
  'token_digest',g.token_digest,'receipt_job_id',j.job_id::text,'receipt_credential_id',c.credential_id::text,
  'receipt_employee_id',p_expected->>'employee_id','receipt_device_id',p_expected->>'device_id',
  'receipt_assignment_epoch',p_expected->>'assignment_epoch','notification_key',source#>>'{source,notification_key}',
  'reservation_at',public.custodial_native_location_utc(at_time),'valid_until',public.custodial_native_location_utc(until_time),
  'title',case source#>>'{source,event}' when 'start' then 'Lunch coverage starts now' else 'Lunch coverage ended' end,
  'body',case source#>>'{source,event}' when 'start' then 'Your temporary lunch coverage has started. Open My Schedule for borrowed areas.'
   else 'Your temporary lunch coverage has ended. Your normal assignments remain unchanged.' end,
  'channel_id','employee-lunch-coverage','route','employee-schedule.html?hub=employee',
  'service_date',j.payload_json#>>'{data_json,service_date}',
  'event',source#>>'{source,event}','loan_id',source#>>'{source,loan_id}',
  'scheduled_time',j.payload_json#>>'{data_json,scheduled_time}',
  'scheduled_at',public.custodial_native_location_utc((source#>>'{source,valid_from}')::timestamptz),
  'coverer_slot_id',source#>>'{source,coverer_slot_id}',
  'projection_id',j.source_id::text,'document_identity',source#>>'{source,source_digest}');
 if public.custodial_native_lunch_live(p_job,data,at_time) is not true then
  return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_lunch_authority_superseded');end if;
 if exists(select 1 from jsonb_each_text(data) e where octet_length(e.value)>case when e.key='title' then 180
   when e.key='notification_key' then 240 else 1000 end or e.value ~ '[[:cntrl:]]') then
  raise exception 'native lunch source text unsupported; no truncation';end if;
 digest:=public.static_weekly_digest_text(public.custodial_native_location_canonical(data));
 data:=data||jsonb_build_object('content_sha256',digest);wire:=public.custodial_native_location_canonical(data);
 if octet_length(wire)>3500 then raise exception 'native lunch payload too large; no truncation';end if;
 insert into public.employee_native_push_delivery_receipts(job_id,job_key,source_id,lease_token,credential_id,assignment_epoch,
  registration_id,token_hash,prepared_at,native_generation_id,native_payload,native_payload_sha256,native_valid_until)
 values(j.job_id,j.job_key,j.source_id,p_lease,c.credential_id,(p_expected->>'assignment_epoch')::bigint,
  r.registration_id,g.token_digest,at_time,g.generation_id,data,digest,until_time);
 return jsonb_build_object('current',true,'dispatch_authorized',true,'replayed',false,'delivery_outcome_unknown',false,
  'payload',data,'wire',wire);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_lunch_target_at(p_job uuid, p_lease uuid, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;r public.employee_push_registrations%rowtype;
 g public.employee_native_push_generations%rowtype;j public.operational_notification_jobs%rowtype;
 at_time timestamptz;cid uuid;source jsonb;
begin
 perform public.custodial_begin_application_mutation();
 if p_job is null or p_lease is null then raise exception 'native lunch target job/lease required' using errcode='22023';end if;
 select (payload_json->>'credential_id')::uuid into cid from public.operational_notification_jobs where job_id=p_job;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id
  where c0.credential_id=cid for update of d0;
 select * into c from public.device_auth_credentials where credential_id=cid for update;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 select * into g from public.employee_native_push_generations where device_id=d.id
  and dispatch_retired_at is null and revoked_at is null for update;
 select * into r from public.employee_push_registrations where registration_id=g.registration_id;
 select * into j from public.operational_notification_jobs where job_id=p_job for update;
 at_time:=coalesce(p_test_at,clock_timestamp());
 if d.id is null or not isfinite(at_time) or d.active is not true or d.device_id !~ '^KIOSK_(0[2-9]|10)$'
  or c.device_id is distinct from d.id or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=at_time
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$')
  or g.generation_id is null or g.credential_id is distinct from c.credential_id or g.employee_id is distinct from d.assigned_employee_id
  or g.assignment_epoch is distinct from d.assignment_epoch or g.device_identifier is distinct from d.device_id or g.activated_at>at_time
  or r.registration_id is null or r.device_id is distinct from d.id or r.credential_id is distinct from c.credential_id
  or r.employee_id is distinct from d.assigned_employee_id or r.assignment_epoch is distinct from d.assignment_epoch
  or r.active is not true or r.revoked_at is not null or r.platform is distinct from 'android'
  or r.token_hash is distinct from g.token_digest or public.static_weekly_digest_text(r.fcm_token) is distinct from g.token_digest
  or j.job_type is distinct from 'employee_native_push' or j.status is distinct from 'leased' or j.lease_token is distinct from p_lease
  or j.leased_until is null or j.leased_until<=at_time or j.payload_json->>'credential_id' is distinct from cid::text
  or j.payload_json->>'device_id' is distinct from d.id::text or j.payload_json->>'device_identifier' is distinct from d.device_id
  or j.payload_json->>'employee_id' is distinct from d.assigned_employee_id::text or j.payload_json->>'assignment_epoch' is distinct from d.assignment_epoch::text
  or j.payload_json#>>'{data_json,kind}' is distinct from 'employee_lunch_coverage' or j.payload_json#>'{data_json,test_delivery}' is not null then
  return jsonb_build_object('current',false,'reason','native_lunch_target_unavailable');end if;
 source:=public.custodial_native_target_source_at('LUNCH',p_job,d.assigned_employee_id,g.generation_id,at_time);
 if source->>'status' is distinct from 'CURRENT_SOURCE_ONLY' or
  (source#>>'{source,valid_from}')::timestamptz>at_time then
  return jsonb_build_object('current',false,'reason','native_lunch_target_unavailable');end if;
 return jsonb_build_object('current',true,'expected',jsonb_build_object('assignment_epoch',d.assignment_epoch::text,
  'credential_id',cid::text,'device_id',d.device_id,'employee_id',d.assigned_employee_id::text,'generation_id',g.generation_id::text,
  'principal_digest',g.principal_digest,'registration_id',r.registration_id::text,'token_digest',g.token_digest),'token',r.fcm_token);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_events_at(p_credential uuid, p_credential_hash text, p_native_request uuid, p_attestation_digest text, p_body jsonb, p_test_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;g public.employee_native_push_generations%rowtype;
 r public.employee_native_push_delivery_receipts%rowtype;
 alert public.employee_native_alert_finalizations%rowtype;
 reservation_started timestamptz;valid_cutoff timestamptz;
 prior public.employee_native_provider_events%rowtype;
 received public.employee_native_provider_events%rowtype;request public.employee_native_provider_event_requests%rowtype;
 e jsonb;first_event jsonb;payload jsonb;results jsonb:='[]';observed timestamptz;observed_last timestamptz;admitted timestamptz;admitted_last timestamptz;at_time timestamptz;
 other_event jsonb;field text;body_digest text;code text;replayed boolean;
begin
 perform public.custodial_begin_application_mutation();
 if p_credential is null or p_native_request is null or coalesce(p_credential_hash,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_attestation_digest,'') !~ '^[0-9a-f]{64}$' or jsonb_typeof(p_body) is distinct from 'object' or octet_length(p_body::text)>65536
  or (select array_agg(key order by key) from jsonb_object_keys(p_body) key) is distinct from array['events','schema']
  or p_body->>'schema' is distinct from 'custodial.native-provider-events.v2' or jsonb_typeof(p_body->'events') is distinct from 'array'
  or jsonb_array_length(p_body->'events') not between 1 and 16 then raise exception 'exact native event batch required' using errcode='22023';end if;
 first_event:=p_body->'events'->0;
 for e in select value from jsonb_array_elements(p_body->'events') loop
  perform public.custodial_native_provider_event_shape(e);
  foreach field in array array['receipt_credential_id','receipt_employee_id','receipt_device_id','receipt_assignment_epoch','principal_digest'] loop
   if e->field is distinct from first_event->field then raise exception 'one exact batch principal required' using errcode='22023';end if;
  end loop;
 end loop;
 if (select count(distinct x->>'event_id') from jsonb_array_elements(p_body->'events') x)<>jsonb_array_length(p_body->'events')
  or (select count(distinct (x->>'record_id',x->>'action')) from jsonb_array_elements(p_body->'events') x)<>jsonb_array_length(p_body->'events') then
  raise exception 'unique native events and transitions required' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id where c0.credential_id=p_credential for update of d0;
 select * into c from public.device_auth_credentials where credential_id=p_credential for update;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 perform 1 from public.employee_native_push_generations where generation_id in(select (x->>'generation_id')::uuid from jsonb_array_elements(p_body->'events') x) order by generation_id for update;
 perform 1 from public.operational_notification_jobs where job_id in(select (x->>'receipt_job_id')::uuid from jsonb_array_elements(p_body->'events') x) order by job_id for update;
 perform 1 from public.employee_native_push_delivery_receipts where job_id in(select (x->>'receipt_job_id')::uuid from jsonb_array_elements(p_body->'events') x) order by job_id for update;
 perform 1 from public.employee_native_alert_finalizations where job_id in(select (x->>'receipt_job_id')::uuid from jsonb_array_elements(p_body->'events') x) order by job_id for update;
 at_time:=coalesce(p_test_at,clock_timestamp());
 if not isfinite(at_time) or d.id is null or d.active is not true or c.token_hash is distinct from p_credential_hash
  or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=at_time
  or first_event->>'receipt_credential_id' is distinct from c.credential_id::text
  or first_event->>'receipt_device_id' is distinct from d.device_id or first_event->>'receipt_employee_id' is distinct from d.assigned_employee_id::text
  or first_event->>'receipt_assignment_epoch' is distinct from d.assignment_epoch::text
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$') then
  raise exception 'current event credential required' using errcode='42501';end if;
 body_digest:=public.static_weekly_digest_text(p_body::text);
 select * into request from public.employee_native_provider_event_requests where native_request_id=p_native_request;
 if request.native_request_id is null then
  insert into public.employee_native_provider_event_requests values(p_native_request,p_credential,body_digest,p_attestation_digest,at_time);
 elsif request.credential_id<>p_credential or request.body_digest<>body_digest or request.attestation_digest<>p_attestation_digest then
  raise exception 'native request identity conflict' using errcode='23505';end if;
 -- Received first even if a durable batch was enumerated in another order.
 for e in select value from jsonb_array_elements(p_body->'events') order by value->>'record_id',
  case value->>'action' when 'received' then 0 when 'displayed' then 1 when 'opened' then 2 else 3 end loop
  code:=null;replayed:=false;
  select * into g from public.employee_native_push_generations where generation_id=(e->>'generation_id')::uuid;
  select * into r from public.employee_native_push_delivery_receipts where job_id=(e->>'receipt_job_id')::uuid;
  select * into alert from public.employee_native_alert_finalizations where job_id=(e->>'receipt_job_id')::uuid;
  payload:=case when alert.job_id is not null then alert.payload else r.native_payload end;
  reservation_started:=case when alert.job_id is not null then alert.finalized_at else r.prepared_at end;
  valid_cutoff:=case when alert.job_id is not null then alert.valid_until else r.native_valid_until end;
  if alert.job_id is not null then
   if public.custodial_native_alert_event_binding(alert.job_id,e,c.credential_id,at_time) is not true then
    code:='native_provider_original_binding_invalid';end if;
  else
  if g.generation_id is null or g.device_id is distinct from d.id or g.device_identifier is distinct from d.device_id
   or g.credential_id is distinct from c.credential_id or g.employee_id is distinct from d.assigned_employee_id or g.assignment_epoch is distinct from d.assignment_epoch
   or g.principal_digest is distinct from e->>'principal_digest' or g.token_digest is distinct from e->>'token_digest' or g.revoked_at is not null
   or r.native_generation_id is distinct from g.generation_id or r.registration_id is distinct from g.registration_id
   or r.credential_id is distinct from c.credential_id or r.assignment_epoch is distinct from d.assignment_epoch
   or reservation_started<g.activated_at or reservation_started>at_time or (g.dispatch_retired_at is not null and reservation_started>g.dispatch_retired_at)
   or (payload->>'schema' is distinct from 'custodial.native-location-payload.v2'
    and not (payload->>'schema'='custodial.native-provider-payload.v1'
     and payload->>'kind'='employee_lunch_coverage')) then code:='native_provider_original_binding_invalid';end if;
  end if;
  foreach field in array array['generation_id','receipt_job_id','notification_key','receipt_credential_id','receipt_employee_id','receipt_device_id',
   'receipt_assignment_epoch','principal_digest','token_digest','content_sha256'] loop
   if e->>field is distinct from payload->>field then code:='native_provider_original_binding_invalid';end if;
  end loop;
  select * into prior from public.employee_native_provider_events where event_id=(e->>'event_id')::uuid;
  if code is null and prior.event_id is not null then
   if prior.original_event<>e then code:='native_provider_event_conflict';else replayed:=true;end if;
  end if;
  if code is null and not replayed then
   if exists(select 1 from public.employee_native_provider_events where record_id=e->>'record_id' and action=e->>'action') then
    code:='native_provider_event_conflict';
   else
    admitted:=public.custodial_native_provider_event_time(e#>'{admission_bounds,earliest_at}');
    admitted_last:=public.custodial_native_provider_event_time(e#>'{admission_bounds,latest_at}');
    observed:=case when e#>'{original_observation,earliest_at}'='null'::jsonb then null else public.custodial_native_provider_event_time(e#>'{original_observation,earliest_at}') end;
    observed_last:=case when observed is null then null else public.custodial_native_provider_event_time(e#>'{original_observation,latest_at}') end;
    -- BOTH endpoints for admission; a cutoff-straddling interval grants nothing.
    -- Server receipt can tighten its own upper bound, not rewrite original evidence.
    if admitted<reservation_started or admitted_last>=valid_cutoff or admitted>at_time or observed>at_time then code:='native_provider_observation_invalid';end if;
    if e->>'action'='received' then
     if observed>admitted_last or not public.custodial_native_provider_observation_order(e->'original_observation',e->'admission_bounds') then
      code:='native_provider_observation_invalid';end if;
    else
     select * into received from public.employee_native_provider_events where record_id=e->>'record_id' and action='received';
     if received.event_id is null then code:='native_provider_transition_pending';
     elsif received.original_event->>'schema' is distinct from 'custodial.native-provider-event.v2'
      or received.original_event->'admission_bounds'<>e->'admission_bounds' or received.original_event->>'content_sha256'<>e->>'content_sha256'
      or observed_last<admitted
      or not public.custodial_native_provider_observation_order(e->'admission_bounds',e->'original_observation') then code:='native_provider_observation_invalid';
     end if;
     if e->>'action'='displayed' and (observed is null or observed<reservation_started or observed_last>=valid_cutoff) then
      code:='native_provider_observation_invalid';end if;
    end if;
   end if;
   if code is null then
    insert into public.employee_native_provider_events values((e->>'event_id')::uuid,e->>'record_id',e->>'action',g.generation_id,(e->>'receipt_job_id')::uuid,c.credential_id,
     e,at_time,p_native_request,p_attestation_digest) returning * into prior;
   end if;
  end if;
  if code is null and prior.action='acknowledged'
   and payload->>'schema'='custodial.native-location-payload.v2' then
   perform public.custodial_native_location_project_ack(prior.event_id,at_time);end if;
  if code is not null then results:=results||jsonb_build_array(jsonb_build_object('event_id',e->>'event_id','admitted_state','REJECTED','code',code));
  else results:=results||jsonb_build_array(prior.original_event||jsonb_build_object('schema','custodial.native-provider-event-receipt.v2',
   'admitted_state','ACCEPTED','server_received_at',public.custodial_native_location_utc(prior.server_received_at),'replayed',replayed));end if;
 end loop;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('schema','custodial.native-provider-event-receipts.v2','results',results));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_event_shape(p_event jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare field text;
begin
 if jsonb_typeof(p_event) is distinct from 'object' or
  (select array_agg(key order by key) from jsonb_object_keys(p_event) key) is distinct from
  array['action','admission_bounds','content_sha256','event_id','generation_id','notification_key','original_observation','principal_digest',
   'receipt_assignment_epoch','receipt_credential_id','receipt_device_id','receipt_employee_id','receipt_job_id','record_id','schema','token_digest']
  or p_event->>'schema' is distinct from 'custodial.native-provider-event.v2'
  or p_event->>'action' not in ('received','displayed','opened','acknowledged') then
  raise exception 'exact finite native event required' using errcode='22023';end if;
 foreach field in array array['action','schema','event_id','generation_id','receipt_credential_id','receipt_employee_id','receipt_job_id',
  'record_id','content_sha256','principal_digest','token_digest','notification_key','receipt_device_id'] loop
  if jsonb_typeof(p_event->field) is distinct from 'string' then raise exception 'native event string required' using errcode='22023';end if;
 end loop;
 foreach field in array array['event_id','generation_id','receipt_credential_id','receipt_employee_id','receipt_job_id'] loop
  if p_event->>field !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then raise exception 'native event UUID required' using errcode='22023';end if;
 end loop;
 foreach field in array array['record_id','content_sha256','principal_digest','token_digest'] loop
  if p_event->>field !~ '^[0-9a-f]{64}$' then raise exception 'native event digest required' using errcode='22023';end if;
 end loop;
 if p_event->>'receipt_device_id' !~ '^KIOSK_(0[2-9]|10)$' or jsonb_typeof(p_event->'receipt_assignment_epoch') is distinct from 'number'
  or p_event->>'receipt_assignment_epoch' !~ '^[1-9][0-9]{0,15}$' or (p_event->>'receipt_assignment_epoch')::numeric>9007199254740991
  or length(p_event->>'notification_key') not between 1 and 1000 or p_event->>'notification_key' ~ '[[:cntrl:]]'
  or p_event->>'record_id'<>public.static_weekly_digest_text((p_event->>'generation_id')||E'\n'||(p_event->>'receipt_job_id')||E'\n'||(p_event->>'notification_key'))
 then raise exception 'native event identity required' using errcode='22023';end if;
 perform public.custodial_native_provider_interval_observation(p_event->'admission_bounds',true);
 perform public.custodial_native_provider_interval_observation(p_event->'original_observation',p_event->>'action'='displayed');
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_event_time(p_value jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare value timestamptz;
begin
 if jsonb_typeof(p_value) is distinct from 'string' or p_value#>>'{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$'
 then raise exception 'canonical native event time required' using errcode='22023';end if;
 value:=(p_value#>>'{}')::timestamptz;
 if not isfinite(value) or public.custodial_native_location_utc(value)<>(p_value#>>'{}') then
  raise exception 'canonical native event time required' using errcode='22023';end if;
 return value;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_inventory_clock_at(p_credential uuid, p_credential_hash text, p_native_request uuid, p_attestation_digest text, p_body jsonb, p_test_at timestamp with time zone, p_test_clock timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare page jsonb;sampled_at timestamptz;expires timestamptz;
begin
 page:=public.custodial_native_location_inventory_at(p_credential,p_credential_hash,p_native_request,p_attestation_digest,p_body,p_test_at);
 if page->'ok' is distinct from 'true'::jsonb then return page;end if; -- Cursor rejection grants no clock.
 sampled_at:=coalesce(p_test_clock,clock_timestamp());
 select c.expires_at into strict expires from public.device_auth_credentials c where c.credential_id=p_credential;
 if not isfinite(sampled_at) or expires is null or expires<=sampled_at
  or (p_test_at is not null and sampled_at<p_test_at)
  or public.custodial_native_provider_event_time(page#>'{data,server_now}')>sampled_at then
  raise exception 'native inventory clock unavailable' using errcode='42501';end if;
 return page||jsonb_build_object('clock',jsonb_build_object('native_request_id',p_native_request::text,
  'server_now',public.custodial_native_location_utc(sampled_at),
  'valid_until',public.custodial_native_location_utc(least(sampled_at+interval '15 minutes',expires))));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_original_tuple(p_job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.employee_native_alert_finalizations%rowtype;
 r public.employee_native_push_delivery_receipts%rowtype;
begin
 select * into a from public.employee_native_alert_finalizations where job_id=p_job;
 select * into r from public.employee_native_push_delivery_receipts where job_id=p_job;
 if a.job_id is not null then
  if r.native_payload is not null then return null;end if;
  return jsonb_build_object('reservation_at',public.custodial_native_location_utc(a.finalized_at),'job_id',a.job_id::text);
 end if;
 if r.job_id is null or r.native_payload is null then return null;end if;
 return jsonb_build_object('reservation_at',public.custodial_native_location_utc(r.prepared_at),'job_id',r.job_id::text);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_registration(p_credential uuid, p_credential_hash text, p_native_request uuid, p_attestation_digest text, p_body jsonb, p_status boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare d public.devices%rowtype; c public.device_auth_credentials%rowtype;
 r public.employee_push_registrations%rowtype; g public.employee_native_push_generations%rowtype;
 prior public.employee_native_push_generations%rowtype; expected_keys text[]; fingerprint text; at_time timestamptz;
 operation uuid; generation uuid; token text;
begin
 perform public.custodial_begin_application_mutation();
 if p_status is null or p_native_request is null or p_attestation_digest is null
  or p_attestation_digest !~ '^[0-9a-f]{64}$' or p_credential is null or p_credential_hash is null
  or p_credential_hash !~ '^[0-9a-f]{64}$' or p_body is null or jsonb_typeof(p_body)<>'object' or octet_length(p_body::text)>65536
 then raise exception using errcode='22023',message='exact bounded native provider request required'; end if;
 expected_keys:=array['assignment_epoch','credential_id','device_id','employee_id','generation_id','native_app','operation_id','principal_digest','schema','token_digest'];
 if not p_status then expected_keys:=array_append(expected_keys,'token'); end if;
 if (select array_agg(k order by k) from jsonb_object_keys(p_body) k) is distinct from
   (select array_agg(k order by k) from unnest(expected_keys) k)
  or p_body->>'schema' is distinct from (case when p_status then 'custodial.native-provider-status.v1' else 'custodial.native-provider-register.v1' end)
  or p_body->>'credential_id' is distinct from p_credential::text
  or coalesce(p_body->>'operation_id','') !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(p_body->>'generation_id','') !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(p_body->>'employee_id','') !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
  or coalesce(p_body->>'principal_digest','') !~ '^[0-9a-f]{64}$'
  or coalesce(p_body->>'token_digest','') !~ '^[0-9a-f]{64}$'
  or jsonb_typeof(p_body->'assignment_epoch') is distinct from 'number'
  or coalesce(p_body->>'assignment_epoch','') !~ '^[1-9][0-9]{0,15}$'
  or public.custodial_native_provider_app_valid(p_body->'native_app') is not true
 then raise exception using errcode='22023',message='native provider request binding invalid'; end if;
 if (p_body->>'assignment_epoch')::numeric>9007199254740991 then raise exception 'native provider epoch out of range'; end if;
 for token in select unnest(array['schema','operation_id','generation_id','credential_id','device_id','employee_id','principal_digest','token_digest']) loop
  if jsonb_typeof(p_body->token) is distinct from 'string' then raise exception 'native provider string field required'; end if;
 end loop;
 if not p_status then
  token:=p_body->>'token';
  if jsonb_typeof(p_body->'token') is distinct from 'string' or octet_length(token) not between 20 and 4096
   or token ~ '[[:cntrl:]]' or encode(extensions.digest(convert_to(token,'UTF8'),'sha256'),'hex') is distinct from p_body->>'token_digest'
  then raise exception 'native provider token binding invalid'; end if;
 end if;
 operation:=(p_body->>'operation_id')::uuid; generation:=(p_body->>'generation_id')::uuid;
 fingerprint:=public.static_weekly_digest_text((p_body-array['schema','token'])::text);
 -- Device, registration, generation order; never hold this transaction across FCM.
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id
  where c0.credential_id=p_credential for update of d0;
 select * into c from public.device_auth_credentials where credential_id=p_credential for update;
 if d.id is null or d.active is not true or c.device_id is distinct from d.id or c.token_hash is distinct from p_credential_hash
  or c.confirmed_at is null or c.revoked_at is not null or c.expires_at<=clock_timestamp()
  or d.device_id is distinct from p_body->>'device_id' or d.assigned_employee_id::text is distinct from p_body->>'employee_id'
  or d.assignment_epoch is distinct from (p_body->>'assignment_epoch')::bigint
  or not exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$')
 then raise exception using errcode='42501',message='current assigned native provider credential required'; end if;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for update;
 select * into g from public.employee_native_push_generations where operation_id=operation for update;
 if g.generation_id is not null then
  if g.generation_id<>generation or g.request_fingerprint<>fingerprint or g.device_id<>d.id
   then raise exception using errcode='23505',message='native provider original operation binding conflict'; end if;
  return public.custodial_native_provider_generation_json(g,true);
 end if;
 if p_status then raise exception using errcode='P0002',message='native provider original operation unknown'; end if;
 select * into prior from public.employee_native_push_generations where device_id=d.id
  and dispatch_retired_at is null and revoked_at is null for update;
 at_time:=clock_timestamp();
 if prior.generation_id is not null then
  update public.employee_native_push_generations set dispatch_retired_at=at_time where generation_id=prior.generation_id;
 end if;
 r:=public.mz_register_employee_push(p_credential,token,p_body->>'token_digest','android',
  p_body#>>'{native_app,version_name}',p_body#>>'{native_app,build_id}');
 insert into public.employee_native_push_generations(generation_id,operation_id,registration_id,device_id,device_identifier,
  credential_id,employee_id,assignment_epoch,principal_digest,token_digest,native_app,request_fingerprint,
  first_native_request_id,first_attestation_digest,activated_at,prior_generation_id,prior_dispatch_retired_at)
 values(generation,operation,r.registration_id,d.id,d.device_id,p_credential,d.assigned_employee_id,d.assignment_epoch,
  p_body->>'principal_digest',p_body->>'token_digest',p_body->'native_app',fingerprint,p_native_request,p_attestation_digest,at_time,
  prior.generation_id,case when prior.generation_id is not null then at_time end) returning * into g;
 return public.custodial_native_provider_generation_json(g,false);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_target_source_at(p_kind text, p_source_key uuid, p_employee_id uuid, p_generation_id uuid, p_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
 v_now timestamptz:=p_at;
 v_generation public.employee_native_push_generations%rowtype;
 v_registration public.employee_push_registrations%rowtype;
 v_device public.devices%rowtype;
 v_credential public.device_auth_credentials%rowtype;
 v_employee public.employees%rowtype;
 v_job public.operational_notification_jobs%rowtype;
 v_message record;
 v_occurrence public.weekly_schedule_occurrences%rowtype;
 v_authority record;
 v_document public.weekly_schedule_lunch_documents%rowtype;
 v_intent jsonb;
 v_loan jsonb;
 v_responsibility jsonb;
 v_availability jsonb;
 v_service_date date;
 v_scheduled_at timestamptz;
 v_valid_until timestamptz;
 v_source jsonb;
 v_recipient jsonb;
 v_status text;
begin
 if p_kind not in ('MESSAGE','SCHEDULE','LUNCH') or p_source_key is null
  or p_employee_id is null or p_generation_id is null or p_at is null or not isfinite(p_at) then
  raise exception using errcode='22023',message='exact native source kind, original key, employee and generation required';
 end if;
 select * into v_generation from public.employee_native_push_generations
  where generation_id=p_generation_id;
 if not found then
  return jsonb_build_object('schema','custodial.native-target-source.v1','kind',p_kind,
   'source_key',p_source_key,'status','TARGET_STALE','delivery_admitted',false);
 end if;
 select * into v_registration from public.employee_push_registrations
  where registration_id=v_generation.registration_id;
 select * into v_device from public.devices where id=v_generation.device_id;
 select * into v_credential from public.device_auth_credentials
  where credential_id=v_generation.credential_id;
 select * into v_employee from public.employees where id=p_employee_id;
 if v_generation.employee_id is distinct from p_employee_id
  or v_generation.dispatch_retired_at is not null or v_generation.revoked_at is not null
  or v_generation.activated_at>v_now or v_registration.registration_id is null
  or v_registration.active is not true or v_registration.revoked_at is not null
  or v_registration.device_id is distinct from v_generation.device_id
  or v_registration.credential_id is distinct from v_generation.credential_id
  or v_registration.employee_id is distinct from p_employee_id
  or v_registration.assignment_epoch is distinct from v_generation.assignment_epoch
  or v_registration.token_hash is distinct from v_generation.token_digest
  or v_device.id is null or v_device.active is not true
  or v_device.device_id is distinct from v_generation.device_identifier
  or v_device.assigned_employee_id is distinct from p_employee_id
  or v_device.assignment_epoch is distinct from v_generation.assignment_epoch
  or v_credential.credential_id is null or v_credential.device_id is distinct from v_device.id
  or v_credential.confirmed_at is null or v_credential.revoked_at is not null
  or v_credential.expires_at<=v_now or v_employee.id is null or v_employee.active is not true then
  return jsonb_build_object('schema','custodial.native-target-source.v1','kind',p_kind,
   'source_key',p_source_key,'status','TARGET_STALE','delivery_admitted',false);
 end if;
 v_recipient:=jsonb_build_object('employee_id',p_employee_id,'device_id',v_device.id,
  'device_identifier',v_device.device_id,'credential_id',v_credential.credential_id,
  'assignment_epoch',v_device.assignment_epoch,'generation_id',v_generation.generation_id,
  'principal_digest',v_generation.principal_digest,'token_digest',v_generation.token_digest);

 if p_kind='MESSAGE' then
  select * into v_job from public.operational_notification_jobs where job_id=p_source_key;
  if not found or v_job.job_type is distinct from 'employee_native_push'
   or v_job.job_key is distinct from 'employee-message-push:'||v_job.source_id::text||':'||v_credential.credential_id::text
   or v_job.status not in ('pending','leased')
   or v_job.payload_json->>'credential_id' is distinct from v_credential.credential_id::text
   or v_job.payload_json->>'employee_id' is distinct from p_employee_id::text
   or v_job.payload_json->>'device_id' is distinct from v_device.id::text
   or v_job.payload_json->>'device_identifier' is distinct from v_device.device_id
   or v_job.payload_json->>'assignment_epoch' is distinct from v_device.assignment_epoch::text
   or v_job.payload_json#>>'{data_json,kind}' is distinct from 'employee_message'
   or v_job.payload_json#>>'{data_json,message_id}' is distinct from v_job.source_id::text
   or v_job.payload_json#>>'{data_json,notification_key}' is distinct from 'message:'||v_job.source_id::text then
   v_status:='SOURCE_STALE';
  else
   select m.id,m.thread_id,m.sender_user_id,m.sent_at,m.body,m.metadata_json,
    recipient.id recipient_user_id,r.acknowledged_at
    into v_message
   from public.msg_messages m
   join public.msg_threads t on t.id=m.thread_id and t.is_active is true
    and t.system_key is distinct from 'ops_manager_shared_chat_v1'
   join public.msg_thread_participants tp on tp.thread_id=m.thread_id and tp.left_at is null
   join public.msg_users recipient on recipient.id=tp.user_id and recipient.is_active is true
    and recipient.employee_id=p_employee_id
   join public.msg_receipts r on r.message_id=m.id and r.user_id=recipient.id
   where m.id=v_job.source_id and m.is_deleted is false and m.sender_user_id<>recipient.id
    and m.sent_at<=v_now
    and r.acknowledged_at is null
    and not exists(select 1 from public.msg_message_deletions md
      where md.message_id=m.id and md.user_id=recipient.id)
    and not exists(select 1 from public.msg_thread_visibility visibility
      where visibility.thread_id=m.thread_id and visibility.user_id=recipient.id
       and (visibility.device_identifier is null
         or upper(btrim(visibility.device_identifier))=upper(btrim(v_device.device_id)))
       and coalesce(m.sent_at,m.created_at)<=visibility.hidden_before);
   if not found or v_job.payload_json#>>'{data_json,thread_id}' is distinct from v_message.thread_id::text then
    v_status:='SOURCE_STALE';
   else
    v_status:='SOURCE_ONLY_POLICY_MISSING';
    v_recipient:=v_recipient||jsonb_build_object('msg_user_id',v_message.recipient_user_id);
    v_source:=jsonb_build_object('source_id',v_message.id,'source_revision',
     public.static_weekly_digest_jsonb(jsonb_build_object('message_id',v_message.id,
      'thread_id',v_message.thread_id,'sender_user_id',v_message.sender_user_id,
      'sent_at',v_message.sent_at,'body',v_message.body,'metadata_json',v_message.metadata_json,
      'recipient_user_id',v_message.recipient_user_id)),
     'delivery_occurrence_id',v_job.job_id,'delivery_key',v_job.job_key,
     'job_status',v_job.status,'valid_from',v_message.sent_at,'valid_until',null);
   end if;
  end if;
 elsif p_kind='SCHEDULE' then
  select * into v_occurrence from public.weekly_schedule_occurrences
   where occurrence_id=p_source_key;
  if not found or v_occurrence.state is distinct from 'created'
   or v_occurrence.owner_person_id_snapshot is distinct from p_employee_id then
   v_status:='SOURCE_STALE';
  else
   select * into v_authority from public.static_weekly_v6_schedule_authority_state(v_occurrence.service_date);
   if v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
    or v_authority.projection_id is distinct from v_occurrence.projection_id
    or v_authority.publication_id is distinct from v_occurrence.publication_id
    or v_authority.version_id is distinct from v_occurrence.version_id then
    v_status:='SOURCE_STALE';
   else
    v_status:='SOURCE_ONLY_POLICY_MISSING';
    v_source:=jsonb_build_object('source_id',v_occurrence.projection_id,
     'source_revision',v_authority.projection_authority_revision::text,
     'source_digest',v_occurrence.occurrence_digest,
     'publication_id',v_occurrence.publication_id,'version_id',v_occurrence.version_id,
     'service_date',v_occurrence.service_date,'assignment_occurrence_id',v_occurrence.occurrence_id,
     'delivery_occurrence_id',null,'delivery_key',null,
     'valid_from',null,'valid_until',null);
   end if;
  end if;
 else
  select * into v_job from public.operational_notification_jobs where job_id=p_source_key;
  if not found or v_job.job_type is distinct from 'employee_native_push'
   or v_job.status not in ('pending','leased')
   or v_job.payload_json->>'credential_id' is distinct from v_credential.credential_id::text
   or v_job.payload_json->>'employee_id' is distinct from p_employee_id::text
   or v_job.payload_json->>'device_id' is distinct from v_device.id::text
   or v_job.payload_json->>'device_identifier' is distinct from v_device.device_id
   or v_job.payload_json->>'assignment_epoch' is distinct from v_device.assignment_epoch::text
   or v_job.payload_json#>>'{data_json,kind}' is distinct from 'employee_lunch_coverage'
   or v_job.payload_json#>>'{data_json,projection_id}' is distinct from v_job.source_id::text then
   v_status:='SOURCE_STALE';
  else
   v_service_date:=(v_job.payload_json#>>'{data_json,service_date}')::date;
   select * into v_authority from public.static_weekly_v6_schedule_authority_state(v_service_date);
   if v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
    or v_authority.projection_id is distinct from v_job.source_id then
    v_status:='SOURCE_STALE';
   else
    select * into v_document from public.weekly_schedule_lunch_documents
     where projection_id=v_authority.projection_id;
    if not found or v_document.document_identity is distinct from v_job.payload_json#>>'{data_json,document_identity}' then
     v_status:='SOURCE_STALE';
    else
     perform public.static_weekly_v8_assert_lunch_document(v_document.projection_id,v_document.document_json);
     select value into v_intent from jsonb_array_elements(v_document.document_json->'notification_intents')
      where value->>'notification_key'=v_job.payload_json#>>'{data_json,notification_key}'
       and value->>'service_date'=v_service_date::text;
     select value into v_loan from jsonb_array_elements(v_document.document_json->'loans')
      where value->>'loan_id'=v_intent->>'loan_id' and value->>'status'='PLANNED';
     select value into v_responsibility from jsonb_array_elements(v_document.document_json->'responsibilities')
      where value->>'loan_id'=v_intent->>'loan_id'
       and value->>'coverer_slot_id'=v_intent->>'coverer_slot_id'
       and value->>'coverer_person_id'=p_employee_id::text;
     select value into v_availability
      from public.weekly_schedule_compiled_projections projection,
       jsonb_array_elements(projection.projection_envelope#>'{authority,projectionAvailability}') value
      where projection.projection_id=v_authority.projection_id
       and value->>'serviceDate'=v_service_date::text
       and value->>'slotId'=v_intent->>'coverer_slot_id'
       and value->>'incumbentPersonId'=p_employee_id::text
       and value->>'status'='working';
     if v_intent is null or v_loan is null or v_responsibility is null or v_availability is null
      or v_job.job_key is distinct from 'employee-lunch-push:'||(v_intent->>'notification_key')||':'||v_credential.credential_id::text
      or v_job.payload_json#>>'{data_json,event}' is distinct from v_intent->>'event'
      or v_job.payload_json#>>'{data_json,loan_id}' is distinct from v_intent->>'loan_id'
      or v_job.payload_json#>>'{data_json,coverer_slot_id}' is distinct from v_intent->>'coverer_slot_id'
      or v_job.payload_json#>>'{data_json,scheduled_time}' is distinct from v_intent->>'scheduled_time'
      or v_job.payload_json#>>'{data_json,notification_key}' is distinct from v_intent->>'notification_key'
      or v_job.payload_json#>>'{data_json,service_date}' is distinct from v_intent->>'service_date'
      or v_intent->>'event' not in ('start','end') then
      v_status:='SOURCE_STALE';
     else
      v_scheduled_at:=(v_service_date+(v_intent->>'scheduled_time')::time) at time zone 'America/Chicago';
      v_valid_until:=(v_service_date+(case when v_intent->>'event'='start'
       then v_loan->>'coverage_end' else v_availability#>>'{shift,end}' end)::time)
       at time zone 'America/Chicago';
      if v_valid_until is null or v_valid_until<=v_scheduled_at or v_now>=v_valid_until
       or public.sch_service_date(v_now) is distinct from v_service_date then
       v_status:='SOURCE_EXPIRED';
      else
       v_status:='CURRENT_SOURCE_ONLY';
       v_source:=jsonb_build_object('source_id',v_document.projection_id,
        'source_revision',v_authority.projection_authority_revision::text,
        'source_digest',v_document.document_identity,
        'notification_key',v_intent->>'notification_key',
        'loan_id',v_intent->>'loan_id','event',v_intent->>'event',
        'coverer_slot_id',v_intent->>'coverer_slot_id',
        'service_date',v_service_date,
        'delivery_occurrence_id',v_job.job_id,'delivery_key',v_job.job_key,
        'job_status',v_job.status,'valid_from',v_scheduled_at,'valid_until',v_valid_until);
      end if;
     end if;
    end if;
   end if;
  end if;
 end if;
 return jsonb_build_object('schema','custodial.native-target-source.v1',
  'kind',p_kind,'source_key',p_source_key,'status',v_status,
  'delivery_admitted',false,'recipient',case when v_source is null then null else v_recipient end,
  'source',v_source);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_bridge_confirm(p_request uuid, p_manager uuid, p_preview uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare view public.custodial_place_bridge_previews%rowtype;replay public.custodial_place_bridge_versions%rowtype;
 prop jsonb;source jsonb;overlay jsonb;rev integer;canonical_rev integer;at_time timestamptz;old_time timestamptz;receipt jsonb;
begin
 perform public.custodial_assert_manager(p_manager);
 if p_request is null or p_preview is null then raise exception using errcode='22023',message='Stable request and original preview required';end if;
 perform 1 from public.custodial_place_control where singleton for update;
 select * into replay from public.custodial_place_bridge_versions where request_id=p_request;
 if found then
  if replay.actor_manager_id<>p_manager or replay.preview_id<>p_preview then raise exception using errcode='23505',message='Bridge request identity conflict';end if;
  return replay.receipt||jsonb_build_object('replayed',true);
 end if;
 select * into view from public.custodial_place_bridge_previews where preview_id=p_preview;
 if not found or view.actor_manager_id<>p_manager then raise exception using errcode='42501',message='Original manager preview required';end if;
 if view.expires_at<=clock_timestamp() then raise exception using errcode='40001',message='Bridge preview expired; review a fresh preview';end if;
 prop:=view.proposal;
 -- Fixed order, after the shared Place singleton: fence catalog write phantoms.
 lock table public.event_area_aliases,public.event_venues,public.location_group_aliases,public.location_group_memberships,public.location_groups,public.locations in share mode;
 if view.expires_at<=clock_timestamp() then raise exception using errcode='40001',message='Bridge preview expired while waiting; review again';end if;
 source:=public.place_bridge_source();
 if public.place_bridge_sha(source)<>prop->>'source_sha256' then raise exception using errcode='40001',message='Legacy catalog source changed; review again';end if;
 select revision,effective_at into rev,old_time from public.custodial_place_bridge_versions where legacy_kind=prop->>'legacy_kind' and legacy_id=(prop->>'legacy_id')::uuid order by revision desc limit 1;
 if coalesce(rev,0)<>(prop->>'expected_bridge_revision')::integer then raise exception using errcode='40001',message='Bridge revision changed';end if;
 select revision into canonical_rev from public.custodial_place_versions where place_id=(prop->>'place_id')::uuid order by revision desc limit 1;
 if canonical_rev is distinct from (prop->>'expected_canonical_revision')::integer then raise exception using errcode='40001',message='Canonical target changed';end if;
 at_time:=coalesce((prop->>'requested_effective_at')::timestamptz,clock_timestamp());
 if not isfinite(at_time) or at_time<clock_timestamp() and prop->>'requested_effective_at' is not null or old_time>at_time then raise exception using errcode='40001',message='Planned effective time elapsed or timeline changed';end if;
 overlay:=public.place_bridge_overlay(at_time,prop);
 if prop->'active'='true'::jsonb and not exists(select 1 from jsonb_array_elements(overlay->'venues') x where x->>'venue_id'=prop->>'legacy_id' and x->>'mapping_status'='MAPPED') then
  raise exception using errcode='23514',message='Current target or aliases require review';end if;
 receipt:=jsonb_build_object('request_id',p_request,'preview_id',p_preview,'actor_manager_id',p_manager,'legacy_rows_mutated',false,
  'data',jsonb_build_object('legacy_kind',prop->>'legacy_kind','legacy_id',prop->>'legacy_id','place_id',prop->>'place_id','revision',coalesce(rev,0)+1,
   'active',prop->'active','effective_at',at_time,'source_sha256',prop->>'source_sha256','action',prop->>'action'));
 insert into public.custodial_place_bridge_versions(legacy_kind,legacy_id,revision,place_id,active,effective_at,actor_manager_id,request_id,preview_id,action,reason,source_sha256,receipt)
 values(prop->>'legacy_kind',(prop->>'legacy_id')::uuid,coalesce(rev,0)+1,(prop->>'place_id')::uuid,(prop->>'active')::boolean,at_time,p_manager,p_request,p_preview,prop->>'action',prop->>'reason',prop->>'source_sha256',receipt);
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_bridge_preview(p_manager uuid, p_legacy_kind text, p_legacy_id uuid, p_action text, p_target uuid, p_effective_at timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source jsonb;sha text;old public.custodial_place_bridge_versions%rowtype;prior public.custodial_place_bridge_versions%rowtype;
 target uuid;active_state boolean;head jsonb;proposal jsonb;overlay jsonb;id uuid:=gen_random_uuid();clock timestamptz:=statement_timestamp();at_time timestamptz:=coalesce(p_effective_at,clock);
begin
 perform public.custodial_assert_manager(p_manager);
 if p_legacy_kind is distinct from 'event_venue' then raise exception using errcode='55000',message='Physical/group bridge cutover is not implemented; all member identities remain untouched';end if;
 if p_legacy_id is null or p_action not in('map','deactivate','reactivate','reverse') or p_action is null
  or p_reason is null or length(btrim(p_reason)) not between 1 and 500 or not isfinite(at_time) or at_time<clock then raise exception using errcode='22023',message='Invalid bridge preview';end if;
 perform 1 from public.custodial_place_control where singleton for update;
 source:=public.place_bridge_source();if octet_length(source::text)>1048576 then raise exception using errcode='54000',message='Catalog exceeds bounded bridge source manifest';end if;
 if not exists(select 1 from public.event_venues venue where venue.id=p_legacy_id) then raise exception using errcode='22023',message='Unknown legacy venue UUID';end if;
 sha:=public.place_bridge_sha(source);
 select * into old from public.custodial_place_bridge_versions where legacy_kind=p_legacy_kind and legacy_id=p_legacy_id order by revision desc limit 1;
 if old.effective_at>at_time then raise exception using errcode='22023',message='Bridge effective timeline must be appended monotonically';end if;
 if p_action='map' then target:=p_target;active_state:=true;
 else
  if old.revision is null or p_target is not null then raise exception using errcode='22023',message='Existing bridge required; target is selected only by map';end if;
  target:=old.place_id;active_state:=p_action='reactivate';
  if p_action='reverse' and old.revision>1 then
   select * into prior from public.custodial_place_bridge_versions where legacy_kind=p_legacy_kind and legacy_id=p_legacy_id and revision=old.revision-1;
   target:=prior.place_id;active_state:=prior.active;
  end if;
 end if;
 select snapshot||jsonb_build_object('revision',revision,'effective_at',effective_at) into head from public.custodial_place_versions where place_id=target order by revision desc limit 1;
 if head is null then raise exception using errcode='22023',message='Explicit existing canonical target required';end if;
 proposal:=jsonb_build_object('legacy_kind',p_legacy_kind,'legacy_id',p_legacy_id,'action',p_action,'place_id',target,'active',active_state,
  'reason',p_reason,'requested_effective_at',p_effective_at,'expected_bridge_revision',coalesce(old.revision,0),
  'expected_canonical_revision',head->'revision','source_sha256',sha,'revision',coalesce(old.revision,0)+1);
 overlay:=public.place_bridge_overlay(at_time,proposal);
 if active_state and not exists(select 1 from jsonb_array_elements(overlay->'venues') x where x->>'venue_id'=p_legacy_id::text and x->>'mapping_status'='MAPPED') then
  raise exception using errcode='23514',message='Target or alias conflict requires review; no bridge preview is confirmable';end if;
 -- Preserve complete source inputs in immutable preview; no reference/history payload.
 proposal:=proposal||jsonb_build_object('source_snapshot',source,'current_effective_bridge',
  (select to_jsonb(x)-'receipt' from public.custodial_place_bridge_versions x where legacy_kind=p_legacy_kind and legacy_id=p_legacy_id and effective_at<=clock order by effective_at desc,revision desc limit 1),
  'latest_bridge',case when old.revision is not null then to_jsonb(old)-'receipt' else null end,'canonical_latest',head,
  'canonical_effective',public.place_lifecycle_snapshot(target,clock),'proposed_overlay',overlay);
 insert into public.custodial_place_bridge_previews values(id,p_manager,clock,clock+interval '10 minutes',proposal,public.place_bridge_sha(proposal));
 return jsonb_build_object('preview_id',id,'actor_manager_id',p_manager,'created_at',clock,'expires_at',clock+interval '10 minutes','proposal',proposal,'proposal_sha256',public.place_bridge_sha(proposal),'legacy_rows_mutated',false);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_command(p_request uuid, p_manager uuid, p_place uuid, p_expected_revision integer, p_action text, p_effective_at timestamp with time zone, p_payload jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare old public.custodial_place_versions%rowtype; replay public.custodial_place_versions%rowtype;
 state jsonb; args_hash text; at_time timestamptz:=coalesce(p_effective_at,statement_timestamp());
 code text; physical uuid; names jsonb; allowed text[]; item record;
begin
 perform public.custodial_assert_manager(p_manager);
 if p_request is null or p_place is null or p_expected_revision is null or p_expected_revision<0
  or p_action is null or p_reason is null or length(btrim(p_reason)) not between 1 and 500
  or p_payload is null or jsonb_typeof(p_payload)<>'object' or octet_length(p_payload::text)>32768 then
  raise exception using errcode='22023',message='Invalid place command';
 end if;
 allowed:=case p_action when 'add' then array['canonical_code','display_name','aliases','cleaning_mode','event_eligible','physical_location_id']
  when 'rename' then array['display_name'] when 'aliases' then array['aliases']
  when 'deactivate' then array[]::text[] when 'reactivate' then array[]::text[]
  when 'merge' then array['target_place_id'] when 'reclassify' then array['cleaning_mode','event_eligible']
  when 'reverse' then array[]::text[] end;
 if allowed is null or exists(select 1 from jsonb_object_keys(p_payload) k where not k=any(allowed)) then
  raise exception using errcode='22023',message='Unknown place action or fields';
 end if;
 args_hash:=encode(extensions.digest(convert_to(jsonb_build_array(p_manager,p_place,p_expected_revision,p_action,p_effective_at,p_payload,p_reason)::text,'UTF8'),'sha256'),'hex');
 perform 1 from public.custodial_place_control where singleton for update;
 select * into replay from public.custodial_place_versions where request_id=p_request;
 if found then
  if replay.argument_sha256<>args_hash then raise exception using errcode='23505',message='Place request identity conflict'; end if;
  return replay.snapshot||jsonb_build_object('place_id',replay.place_id,'revision',replay.revision,
   'effective_at',replay.effective_at,'actor_manager_id',replay.actor_manager_id,'replayed',true);
 end if;
 if at_time<statement_timestamp() then raise exception using errcode='22023',message='Place changes cannot rewrite past effective history'; end if;
 select * into old from public.custodial_place_versions where place_id=p_place order by revision desc limit 1;
 if coalesce(old.revision,0)<>p_expected_revision then raise exception using errcode='40001',message='Place revision changed; preview again'; end if;
 if old.effective_at>at_time then raise exception using errcode='22023',message='Place effective dates must be appended monotonically'; end if;
 if p_action='add' then
  if old.revision is not null or p_expected_revision<>0 then raise exception using errcode='23505',message='Canonical place already exists'; end if;
  code:=p_payload->>'canonical_code'; physical:=(p_payload->>'physical_location_id')::uuid;
  insert into public.custodial_places(place_id,canonical_code,physical_location_id) values(p_place,code,physical);
  state:=jsonb_build_object('display_name',p_payload->>'display_name','aliases',coalesce(p_payload->'aliases','[]'::jsonb),
   'active',true,'cleaning_mode',coalesce(p_payload->>'cleaning_mode','NEVER_CLEAN'),
   'event_eligible',coalesce(p_payload->'event_eligible','false'::jsonb),'merged_into',null);
 else
  if old.revision is null then raise exception using errcode='22023',message='Unknown canonical place'; end if;
  select canonical_code,physical_location_id into code,physical from public.custodial_places where place_id=p_place;
  state:=old.snapshot;
  if state->>'merged_into' is not null and p_action<>'reverse' then raise exception using errcode='23514',message='Reverse the merge before editing its source'; end if;
  case p_action
   when 'rename' then state:=jsonb_set(state,'{display_name}',coalesce(p_payload->'display_name','null'::jsonb));
   when 'aliases' then state:=jsonb_set(state,'{aliases}',coalesce(p_payload->'aliases','null'::jsonb));
   when 'deactivate' then state:=jsonb_set(state,'{active}','false'::jsonb);
   when 'reactivate' then state:=jsonb_set(state,'{active}','true'::jsonb);
   when 'reclassify' then
    if not (p_payload ? 'cleaning_mode' or p_payload ? 'event_eligible') then raise exception 'Classification change required'; end if;
    state:=state||p_payload;
   when 'merge' then
    if physical is not null then raise exception using errcode='55000',message='Physical-place merge needs a verified tag/schedule cutover preview'; end if;
    if (p_payload->>'target_place_id')::uuid=p_place
      or public.place_lifecycle_root((p_payload->>'target_place_id')::uuid,at_time) is null then
     raise exception using errcode='23514',message='Merge requires another active canonical target';
    end if;
    state:=state||jsonb_build_object('active',false,'merged_into',(p_payload->>'target_place_id')::uuid);
   when 'reverse' then
    if old.revision=1 then state:=state||jsonb_build_object('active',false,'merged_into',null);
    else select snapshot into state from public.custodial_place_versions where place_id=p_place and revision=old.revision-1; end if;
   else raise exception 'Unsupported place command';
  end case;
 end if;
 if jsonb_typeof(state->'display_name') is distinct from 'string' or length(btrim(state->>'display_name')) not between 1 and 200
   or public.place_lifecycle_normalize(state->>'display_name')=''
   or jsonb_typeof(state->'aliases') is distinct from 'array' or jsonb_array_length(state->'aliases')>128
   or coalesce(state->>'cleaning_mode','') not in ('SCAN_TRACKED','REMINDER_ONLY','NEVER_CLEAN')
   or jsonb_typeof(state->'event_eligible') is distinct from 'boolean' then
  raise exception using errcode='22023',message='Invalid name, aliases or independent classification';
 end if;
 if exists(select 1 from jsonb_array_elements(state->'aliases') a where jsonb_typeof(a)<>'string'
   or length(btrim(a#>>'{}')) not between 1 and 200 or public.place_lifecycle_normalize(a#>>'{}')='') then
  raise exception using errcode='22023',message='Aliases must be bounded explicit text';
 end if;
 if state->>'cleaning_mode'='SCAN_TRACKED' and physical is null then
  raise exception using errcode='23514',message='SCAN_TRACKED needs an explicitly mapped physical location';
 end if;
 if code='STINGRAYS' and (state->>'cleaning_mode'<>'NEVER_CLEAN' or state->>'event_eligible'<>'true'
   or physical is not null or state->>'merged_into' is not null) then
  raise exception using errcode='23514',message='Stingrays remains event-eligible NEVER_CLEAN';
 end if;
 -- Every name remains an explicit historical alias. No fuzzy match remaps data.
 select jsonb_agg(name order by name) into names from (
  select distinct value name from jsonb_array_elements_text(state->'aliases')
  union select state->>'display_name' union select old.snapshot->>'display_name' where old.snapshot is not null
 ) n where name is not null;
 if jsonb_array_length(names)>128 then raise exception using errcode='22023',message='Aliases including retained names must remain bounded'; end if;
 state:=jsonb_set(state,'{aliases}',names);
 insert into public.custodial_place_versions(place_id,revision,request_id,actor_manager_id,action,reason,effective_at,argument_sha256,snapshot)
  values(p_place,coalesce(old.revision,0)+1,p_request,p_manager,p_action,p_reason,at_time,args_hash,state);
 perform public.place_lifecycle_assert_aliases(at_time);
 return state||jsonb_build_object('place_id',p_place,'revision',coalesce(old.revision,0)+1,'effective_at',at_time,'actor_manager_id',p_manager);
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_place_operational_begin(p_manager uuid, p_operation uuid, p_preview uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p public.custodial_place_operational_previews%rowtype;c public.custodial_place_operational_commands%rowtype;sid uuid:=gen_random_uuid();begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);perform public.place_source_locks();
 select * into c from public.custodial_place_operational_commands where operation_id=p_operation;
 if found then
  if c.manager_id<>p_manager or c.preview_id<>p_preview then raise exception using errcode='23505',message='Original operation, manager and preview identity required';end if;
  return jsonb_build_object('replayed',true,'receipt',public.custodial_place_operational_status(p_manager,p_operation));end if;
 select * into p from public.custodial_place_operational_previews where preview_id=p_preview;
 if not found or p.manager_id<>p_manager then raise exception using errcode='42501',message='Exact manager preview required';end if;
 if p.expires_at<=clock_timestamp() or p.effective_start<=public.sch_service_date(clock_timestamp()) or p.expected_revision<>(select current_revision from public.static_weekly_schedule_control where singleton)
  or p.source_sha256<>public.place_bridge_sha(public.place_source_manifest()) or p.dependency_sha256<>public.place_bridge_sha(public.place_source_dependencies())
  or p.base_source is distinct from public.static_weekly_v3_read_publication_source(p.source_publication_id,p.effective_start)->'compiler_input' then
  raise exception using errcode='40001',message='Place preview expired or exact source/dependencies changed';end if;
 insert into public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
 values(sid,p.candidate_source,p.candidate_sha256,'place-name-publication:'||p_operation);
 insert into public.custodial_place_operational_commands(operation_id,manager_id,preview_id,source_id) values(p_operation,p_manager,p_preview,sid);
 return public.place_operational_preview_document(p)||jsonb_build_object('source_id',sid,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_operational_finalize(p_manager uuid, p_operation uuid, p_publication uuid, p_projection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c public.custodial_place_operational_commands%rowtype;p public.custodial_place_operational_previews%rowtype;a record;l public.weekly_schedule_lunch_documents%rowtype;receipt jsonb;begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 select * into strict c from public.custodial_place_operational_commands where operation_id=p_operation;
 if c.manager_id<>p_manager or c.owner_xid<>pg_current_xact_id() then raise exception using errcode='42501',message='Exact original Place transaction required';end if;
 select * into strict p from public.custodial_place_operational_previews where preview_id=c.preview_id;
 if not exists(select 1 from public.weekly_schedule_publications pub join public.weekly_schedule_versions v using(version_id)
  where pub.publication_id=p_publication and pub.actor_manager_id=p_manager and pub.idempotency_key='place:'||p_operation||':publish'
   and v.authority_source_id=c.source_id and pub.effective_start=p.effective_start) then raise exception 'Exact Place publication child required';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p.effective_start);
 select * into l from public.weekly_schedule_lunch_documents where projection_id=p_projection;
 if a.publication_id is distinct from p_publication or a.projection_id is distinct from p_projection or a.projection_status is distinct from 'current'
  or l.accepted_by_manager_id is distinct from p_manager then raise exception 'Current complete Place projection and named-manager lunch companion required';end if;
 if not exists(select 1 from public.weekly_schedule_command_receipts r where actor_manager_id=p_manager and command_type='materialize_projection'
  and idempotency_key='place:'||p_operation||':projection:'||p.effective_start and r.response_json#>>'{data,projection_id}'=p_projection::text) then
  raise exception 'Exact Place projection child receipt required';end if;
 receipt:=jsonb_build_object('schema','custodial.place-name-publication-receipt.v1','operation_id',p_operation,'manager_id',p_manager,'preview_id',p.preview_id,
 'source_id',c.source_id,'source_sha256',p.source_sha256,'candidate_sha256',p.candidate_sha256,'publication_id',p_publication,'projection_id',p_projection,
 'authority_revision',a.projection_authority_revision,'effective_start',p.effective_start,'selection',p.selection,
 'accepted',true,'affected_phones_updated',false,'phone_delivery_state','PENDING','scope','SELECTED_NAMES_AND_HUMAN_ALIASES_ONLY');
 insert into public.custodial_place_operational_receipts(operation_id,publication_id,projection_id,receipt_json,receipt_sha256)
 values(p_operation,p_publication,p_projection,receipt,public.place_bridge_sha(receipt));return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_operational_preview(p_manager uuid, p_publication uuid, p_start date, p_revision bigint, p_selection jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare preview public.custodial_place_operational_previews%rowtype;source jsonb;candidate jsonb;overlay jsonb;item jsonb;record jsonb;selected jsonb:='[]';
 a jsonb;loc jsonb;rewritten jsonb:='[]';included jsonb;desired_members jsonb;raw_members jsonb;at_time timestamptz;matched integer;display text;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 perform public.place_source_locks();
 if p_start is null or extract(isodow from p_start)<>1 or p_start<=public.sch_service_date(clock_timestamp()) or p_start<'2026-10-05'
  or p_reason is null or length(btrim(p_reason)) not between 1 and 500 or p_selection is null or jsonb_typeof(p_selection)<>'array'
  or jsonb_array_length(p_selection) not between 1 and 100 or octet_length(p_selection::text)>32768 then
  raise exception using errcode='22023',message='Selected Place names require a future complete Monday outside the protected October dated plan';end if;
 if p_revision is distinct from (select current_revision from public.static_weekly_schedule_control where singleton) then
  raise exception using errcode='40001',message='Schedule authority revision changed';end if;
 source:=public.static_weekly_v3_read_publication_source(p_publication,p_start)->'compiler_input';
 if exists(select 1 from public.weekly_schedule_exception_commands where publication_id=p_publication and service_date>=p_start) then
  raise exception using errcode='55000',message='Name-only publication cannot migrate dated exception history; explicit plan reconciliation required';end if;
 if jsonb_typeof(source#>'{version,assignments}') is distinct from 'array' then raise exception 'Registered source required';end if;
 at_time:=(p_start+time '04:00') at time zone 'America/Chicago';overlay:=public.custodial_place_source_overlay(at_time);
 for item in select value from jsonb_array_elements(p_selection) order by value->>'legacy_kind',value->>'legacy_id' loop
  if jsonb_typeof(item)<>'object' or not item ?& array['legacy_kind','legacy_id','revision']
   or exists(select 1 from jsonb_object_keys(item) k where k not in('legacy_kind','legacy_id','revision'))
   or item->>'legacy_kind' not in('physical_location','location_group') or item->>'revision' !~ '^[1-9][0-9]*$' then
   raise exception using errcode='22023',message='Only exact namespace, original UUID and desired effective revision may be selected';end if;
  if exists(select 1 from jsonb_array_elements(selected) x where x->>'legacy_kind'=item->>'legacy_kind' and x->>'legacy_id'=item->>'legacy_id') then
   raise exception using errcode='22023',message='Duplicate selected identity';end if;
  select value into record from jsonb_array_elements(overlay->'records') where value->>'legacy_kind'=item->>'legacy_kind' and value->>'legacy_id'=(item->>'legacy_id')::uuid::text;
  if record is null or record->>'mapping_status'<>'MAPPED' or record->>'effective_revision'<>item->>'revision'
   or record#>>'{raw_legacy,active}' is distinct from 'true' then
   raise exception using errcode='40001',message='Exact mapped active existing identity required; setup, inactive, merge and drift need explicit reconciliation';end if;
  if record->>'legacy_kind'='physical_location' and record#>>'{effective_snapshot,cleaning_mode}'<>'SCAN_TRACKED' then
   raise exception using errcode='55000',message='Physical reclassification requires explicit replacement-duty preview';end if;
  if record->>'legacy_kind'='location_group' then
   select coalesce(jsonb_agg(x->>'location_id' order by x->>'location_id'),'[]') into raw_members from jsonb_array_elements(record#>'{raw_legacy,memberships}') x;
   select coalesce(jsonb_agg(x order by x),'[]') into desired_members from jsonb_array_elements_text(record->'source_member_location_ids') x;
   if desired_members<>raw_members then raise exception using errcode='55000',message='Membership changes require explicit replacement-duty preview';end if;
   if exists(select 1 from jsonb_array_elements(source#>'{version,assignments}') w where w->>'locationCodeSnapshot'=record#>>'{raw_legacy,group_code}'
    and coalesce(w->>'serviceMode','scan_tracked')<>case record#>>'{effective_snapshot,cleaning_mode}' when 'SCAN_TRACKED' then 'scan_tracked' when 'REMINDER_ONLY' then 'reminder_only' else 'response_only_no_clean' end) then
    raise exception using errcode='55000',message='Group reclassification requires explicit replacement-duty preview';end if;
  end if;
  -- Complete desired/effective/source evidence, not a fresh unbound name read.
  selected:=selected||jsonb_build_array(record);
 end loop;
 for a in select value from jsonb_array_elements(source#>'{version,assignments}') loop
  included:='[]';
  for loc in select value from jsonb_array_elements(coalesce(a->'includedLocations','[]')) loop
   select x#>>'{effective_snapshot,display_name}' into display from jsonb_array_elements(selected) x
    where x->>'legacy_kind'='physical_location' and x->>'legacy_id'=loc->>'locationId';
   included:=included||jsonb_build_array(case when display is null then loc else jsonb_set(loc,'{locationNameSnapshot}',to_jsonb(display)) end);
  end loop;
  if a ? 'includedLocations' then a:=jsonb_set(a,'{includedLocations}',included);end if;
  for record in select value from jsonb_array_elements(selected) order by case value->>'legacy_kind' when 'physical_location' then 0 else 1 end,value->>'legacy_id' loop
   if record->>'legacy_kind'='physical_location' and a->>'locationId'=record->>'legacy_id' and a->>'locationCodeSnapshot'=record#>>'{raw_legacy,location_code}'
    and not exists(select 1 from public.location_groups g join public.location_group_memberships m on m.location_group_id=g.id
     where g.group_code=a->>'locationCodeSnapshot' and m.location_id=(a->>'locationId')::uuid) then
    a:=jsonb_set(a,'{locationNameSnapshot}',record#>'{effective_snapshot,display_name}');
   elsif record->>'legacy_kind'='location_group' and a->>'locationCodeSnapshot'=record#>>'{raw_legacy,group_code}' then
    -- Stable group code alone is insufficient: the immutable accepted routing
    -- UUID and every included physical UUID must resolve through this group's
    -- exact legacy relationships. Never infer a group from a human name.
    if not (a->>'locationId'=record->>'legacy_id' or exists(select 1 from jsonb_array_elements(record#>'{raw_legacy,memberships}') m where m->>'location_id'=a->>'locationId'))
      or exists(select 1 from jsonb_array_elements(included) l where not exists(select 1 from jsonb_array_elements(record#>'{raw_legacy,memberships}') m where m->>'location_id'=l->>'locationId')) then
     raise exception using errcode='55000',message='Accepted group routing has no explicit original relationship; reconciliation required';end if;
    a:=jsonb_set(a,'{locationNameSnapshot}',record#>'{effective_snapshot,display_name}');
   end if;
  end loop;
  rewritten:=rewritten||jsonb_build_array(a);
 end loop;
 preview.preview_id:=gen_random_uuid();candidate:=jsonb_set(source,'{version,assignments}',rewritten);
 candidate:=jsonb_set(candidate,'{serviceDate}',to_jsonb(p_start::text));
 candidate:=jsonb_set(candidate,'{version}',(candidate->'version')||jsonb_build_object('id',preview.preview_id,'publicationId',gen_random_uuid(),'status','published','effectiveStart',p_start,'effectiveEnd',null));
 insert into public.custodial_place_operational_previews(preview_id,manager_id,source_publication_id,expected_revision,effective_start,selection,base_source,candidate_source,candidate_sha256,source_sha256,dependency_sha256,reason)
 values(preview.preview_id,p_manager,p_publication,p_revision,p_start,selected,source,candidate,public.place_bridge_sha(candidate),public.place_bridge_sha(public.place_source_manifest()),public.place_bridge_sha(public.place_source_dependencies()),p_reason) returning * into preview;
 return public.place_operational_preview_document(preview);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_operational_status(p_manager uuid, p_operation uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c public.custodial_place_operational_commands%rowtype;r public.custodial_place_operational_receipts%rowtype;begin
 perform public.static_weekly_v3_assert_control_plane();perform public.static_weekly_v3_manager_actor(p_manager);
 select * into c from public.custodial_place_operational_commands where operation_id=p_operation;
 if not found then return jsonb_build_object('operation_id',p_operation,'accepted',false,'status','NOT_FOUND');end if;
 if c.manager_id<>p_manager then raise exception using errcode='42501',message='Original named manager required';end if;
 select * into strict r from public.custodial_place_operational_receipts where operation_id=p_operation;
 return r.receipt_json;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_preview(p_manager uuid, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare places jsonb;
begin
 perform public.custodial_assert_manager(p_manager);
 if p_at is null then raise exception using errcode='22023',message='Place preview time required'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('place_id',p.place_id,'canonical_code',p.canonical_code,
  'physical_location_id',p.physical_location_id,'latest_revision',v.revision,
  'latest_effective_at',v.effective_at,'latest_snapshot',v.snapshot,
  'effective_snapshot',public.place_lifecycle_snapshot(p.place_id,p_at)) order by p.canonical_code),'[]'::jsonb)
 into places from public.custodial_places p cross join lateral
  (select revision,effective_at,snapshot from public.custodial_place_versions where place_id=p.place_id order by revision desc limit 1) v;
 return jsonb_build_object('as_of',p_at,'places',places,'legacy_consumer_cutover',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_place_resolve(p_raw text, p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare ids uuid[]; id uuid; s jsonb; physical uuid; normalized text;
begin
 if p_raw is null or length(p_raw)>500 or p_at is null then raise exception using errcode='22023',message='Bounded raw location and effective time required'; end if;
 normalized:=public.place_lifecycle_normalize(p_raw);
 select array_agg(distinct public.place_lifecycle_root(p.place_id,p_at)) into ids
 from public.custodial_places p cross join lateral public.place_lifecycle_snapshot(p.place_id,p_at) snapshot
 cross join lateral jsonb_array_elements_text(snapshot->'aliases') alias
 where public.place_lifecycle_root(p.place_id,p_at) is not null and public.place_lifecycle_normalize(alias.value)=normalized;
 if coalesce(cardinality(ids),0)<>1 then
  return jsonb_build_object('raw_location',p_raw,'normalized_alias',normalized,'status','NEEDS_REVIEW',
   'reason',case when coalesce(cardinality(ids),0)>1 then 'ambiguous_alias' else 'unknown_or_inactive_alias' end,
   'event_only',true,'schedule_eligible',false,'staffing_eligible',false,'nfc_eligible',false,'overdue_eligible',false);
 end if;
 id:=ids[1]; s:=public.place_lifecycle_snapshot(id,p_at); select physical_location_id into physical from public.custodial_places where place_id=id;
 return jsonb_build_object('raw_location',p_raw,'normalized_alias',normalized,'status',case when s->'event_eligible'='true'::jsonb then 'RESOLVED' else 'NEEDS_REVIEW' end,
  'place_id',id,'display_name',s->>'display_name','revision',s->'revision','cleaning_mode',s->>'cleaning_mode',
  'event_eligible',s->'event_eligible','event_only',s->'event_eligible'<>'true'::jsonb or s->>'cleaning_mode'='NEVER_CLEAN',
  -- These are safe routing hints for an event-location resolver, not permission
  -- to publish schedules or tag mappings. Needs Review never assigns work.
  'schedule_eligible',s->'event_eligible'='true'::jsonb and s->>'cleaning_mode'<>'NEVER_CLEAN',
  'staffing_eligible',s->'event_eligible'='true'::jsonb and s->>'cleaning_mode'<>'NEVER_CLEAN',
  'nfc_eligible',s->'event_eligible'='true'::jsonb and s->>'cleaning_mode'='SCAN_TRACKED' and physical is not null,
  'overdue_eligible',s->'event_eligible'='true'::jsonb and s->>'cleaning_mode'='SCAN_TRACKED' and physical is not null);
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_place_source_confirm(p_request uuid, p_manager uuid, p_preview uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v public.custodial_place_source_previews%rowtype;r public.custodial_place_source_versions%rowtype;p jsonb;rev integer;head integer;targethead integer;at_time timestamptz;receipt jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));perform public.custodial_assert_manager(p_manager);perform public.place_source_locks();
 if p_request is null or p_preview is null then raise exception using errcode='22023',message='Stable request/original preview required';end if;
 select * into r from public.custodial_place_source_versions where request_id=p_request;
 if found then
  if r.actor_manager_id<>p_manager or r.preview_id<>p_preview then raise exception using errcode='23505',message='Source request identity conflict';end if;return r.receipt||'{"replayed":true}'::jsonb;
 end if;
 select * into v from public.custodial_place_source_previews where preview_id=p_preview;
 if not found or v.actor_manager_id<>p_manager then raise exception using errcode='42501',message='Original manager preview required';end if;
 if v.expires_at<=clock_timestamp() then raise exception using errcode='40001',message='Source preview expired';end if;p:=v.proposal;
 if v.proposal_sha256<>public.place_bridge_sha(p) or p->>'source_sha256'<>public.place_bridge_sha(public.place_source_manifest())
  or p->>'dependency_sha256'<>public.place_bridge_sha(public.place_source_dependencies()) then raise exception using errcode='40001',message='Source/dependencies changed; review again';end if;
 select max(revision) into rev from public.custodial_place_source_versions where legacy_kind=p->>'legacy_kind' and legacy_id=(p->>'legacy_id')::uuid;
 select max(revision) into head from public.custodial_place_versions where place_id=(p->>'place_id')::uuid;
 select max(revision) into targethead from public.custodial_place_versions where place_id=(p->>'target_place_id')::uuid;
 if coalesce(rev,0)<>(p->>'expected_revision')::integer or coalesce(head,0)<>(p->>'expected_canonical_revision')::integer or coalesce(targethead,0)<>(p->>'expected_target_revision')::integer then raise exception using errcode='40001',message='Source/target revision changed';end if;
 at_time:=coalesce((p->>'requested_effective_at')::timestamptz,clock_timestamp());
 if not isfinite(at_time) or (p->>'requested_effective_at' is not null and at_time<clock_timestamp()) then raise exception using errcode='40001',message='Planned effective time elapsed';end if;
 insert into public.custodial_place_source_admissions values(p_request,p_preview,txid_current(),p_manager,public.place_bridge_sha(jsonb_build_array(p_request,p_manager,p_preview,at_time,p)),p->>'source_sha256',p->>'dependency_sha256',coalesce(head,0),coalesce(targethead,0));
 head:=public.place_source_apply(p_request,p_manager,p_preview,at_time);
 receipt:=jsonb_build_object('request_id',p_request,'preview_id',p_preview,'actor_manager_id',p_manager,'operational_cutover',false,
  'data',jsonb_build_object('legacy_kind',p->>'legacy_kind','legacy_id',p->>'legacy_id','place_id',p->>'place_id','revision',coalesce(rev,0)+1,'canonical_revision',head,
   'action',p->>'action','effective_at',at_time,'source_sha256',p->>'source_sha256','dependency_sha256',p->>'dependency_sha256','proposal_sha256',v.proposal_sha256,
   'setup_pending',p->'desired_snapshot'->'setup_pending','requires_explicit_republish',p->'requires_explicit_republish','protected_finish_uses_original_route',true));
 insert into public.custodial_place_source_versions(legacy_kind,legacy_id,revision,place_id,effective_at,request_id,preview_id,actor_manager_id,canonical_revision,action,reason,source_row_sha256,snapshot,receipt)
 values(p->>'legacy_kind',(p->>'legacy_id')::uuid,coalesce(rev,0)+1,(p->>'place_id')::uuid,at_time,p_request,p_preview,p_manager,head,p->>'action',p->>'reason',
  public.place_bridge_sha(public.place_source_row(p->>'legacy_kind',(p->>'legacy_id')::uuid)),p->'desired_snapshot',receipt);
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_source_overlay(p_at timestamp with time zone DEFAULT statement_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare k text;id uuid;raw jsonb;v public.custodial_place_source_versions%rowtype;latest public.custodial_place_source_versions%rowtype;
 root_version public.custodial_place_source_versions%rowtype;s jsonb;root_state jsonb;root uuid;output jsonb:='[]';status text;members jsonb;consolidated jsonb;
begin
 if p_at is null or not isfinite(p_at) then raise exception using errcode='22023',message='Finite source overlay time required';end if;
 for k,id in select 'physical_location',l.id from public.locations l union all select 'location_group',g.id from public.location_groups g loop
  if jsonb_array_length(output)>=10000 then raise exception using errcode='54000',message='Bounded source overlay limit exceeded';end if;
  raw:=public.place_source_row(k,id);
  select * into latest from public.custodial_place_source_versions where legacy_kind=k and legacy_id=id order by revision desc limit 1;
  select * into v from public.custodial_place_source_versions where legacy_kind=k and legacy_id=id and effective_at<=p_at order by effective_at desc,revision desc limit 1;
  s:=null;root:=null;members:='[]';consolidated:='[]';status:='UNMAPPED';
  if v.revision is not null then
   s:=public.place_lifecycle_snapshot(v.place_id,p_at);root:=public.place_lifecycle_root(v.place_id,p_at);members:=v.snapshot->'member_location_ids';
   root_state:=public.place_lifecycle_snapshot(root,p_at);
   select * into root_version from public.custodial_place_source_versions where place_id=root and effective_at<=p_at order by effective_at desc,revision desc limit 1;
   status:=case when public.place_bridge_sha(raw)<>v.source_row_sha256 or s is null or (s->>'revision')::integer<>v.canonical_revision
     or (root is not null and (root_version.revision is null or root_version.legacy_kind<>k
      or public.place_bridge_sha(public.place_source_row(k,root_version.legacy_id))<>root_version.source_row_sha256
      or (root_state->>'revision')::integer<>root_version.canonical_revision or root_state->>'cleaning_mode'<>s->>'cleaning_mode')) then 'NEEDS_REVIEW'
    when v.snapshot->'setup_pending'='true'::jsonb or root_version.snapshot->'setup_pending'='true'::jsonb then 'SETUP_PENDING'
    when root is null then 'INACTIVE' when s->>'merged_into' is not null then 'LOGICALLY_MERGED' else 'MAPPED' end;
   if k='location_group' and root is not null then
    select coalesce(jsonb_agg(member order by member),'[]'::jsonb) into consolidated from (
     select distinct m.value member from (select distinct on(legacy_kind,legacy_id) * from public.custodial_place_source_versions
      where legacy_kind='location_group' and effective_at<=p_at order by legacy_kind,legacy_id,effective_at desc,revision desc) x
     cross join lateral jsonb_array_elements_text(x.snapshot->'member_location_ids') m
     where public.place_lifecycle_root(x.place_id,p_at)=root) all_members;
   else consolidated:=members;end if;
  end if;
  output:=output||jsonb_build_array(jsonb_build_object('legacy_kind',k,'legacy_id',id,'raw_legacy',raw,'mapping_status',status,
   'place_id',v.place_id,'canonical_root_id',root,'effective_revision',v.revision,'latest_revision',latest.revision,'latest_effective_at',latest.effective_at,
   'effective_snapshot',s,'metadata',v.snapshot->'metadata','source_member_location_ids',members,'proposed_consolidation_member_location_ids',consolidated,
   'proposed_included_locations',case when status in('MAPPED','LOGICALLY_MERGED') and s->>'cleaning_mode'='SCAN_TRACKED' then members else '[]'::jsonb end,
   'operational_cutover',false,'new_scan_authority',false,'protected_finish_uses_original_route',true,'requires_explicit_republish',true));
 end loop;
 return jsonb_build_object('as_of',p_at,'records',output,'source_sha256',public.place_bridge_sha(public.place_source_manifest()),'operational_cutover',false);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_place_source_preview(p_manager uuid, p_kind text, p_id uuid, p_action text, p_payload jsonb, p_effective_at timestamp with time zone, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
<<source_preview>>
declare clock timestamptz:=statement_timestamp();at_time timestamptz:=coalesce(p_effective_at,clock);id uuid:=coalesce(p_id,gen_random_uuid());pid uuid;
 old public.custodial_place_source_versions%rowtype;prior public.custodial_place_source_versions%rowtype;
 raw jsonb;state jsonb;desired jsonb;source jsonb;deps jsonb;proposal jsonb;preview uuid:=gen_random_uuid();
 head integer:=0;target_head integer:=0;target uuid;target_state jsonb;allowed text[];members jsonb;names jsonb;code text;item record;check_at timestamptz;candidate_root uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.custodial_assert_manager(p_manager);perform public.place_source_locks();
 if p_kind not in('physical_location','location_group') or p_kind is null or p_action is null
  or p_reason is null or length(btrim(p_reason)) not between 1 and 500 or p_payload is null or jsonb_typeof(p_payload)<>'object'
  or octet_length(p_payload::text)>32768 or not isfinite(at_time) or at_time<clock then raise exception using errcode='22023',message='Invalid operational metadata preview';end if;
 allowed:=case p_action when 'enroll' then array['canonical_code','display_name','aliases','cleaning_mode','event_eligible','metadata']
  when 'add' then array['canonical_code','legacy_code','display_name','aliases','cleaning_mode','event_eligible','location_type','member_location_ids','metadata']
  when 'rename' then array['display_name'] when 'aliases' then array['aliases']
  when 'reclassify' then array['cleaning_mode','event_eligible','metadata'] when 'memberships' then array['member_location_ids']
  when 'merge' then array['target_legacy_id'] when 'deactivate' then array[]::text[] when 'reactivate' then array[]::text[] when 'reverse' then array[]::text[] end;
 if allowed is null or exists(select 1 from jsonb_object_keys(p_payload) k where not k=any(allowed)) then raise exception using errcode='22023',message='Unknown metadata action or fields';end if;
 raw:=public.place_source_row(p_kind,id);
 select * into old from public.custodial_place_source_versions where legacy_kind=p_kind and legacy_id=id order by revision desc limit 1;
 if p_action='add' then
  if p_id is not null or raw is not null then raise exception using errcode='22023',message='New UUID is server-issued only';end if;
  code:=p_payload->>'legacy_code';
  if code is null or code !~ '^[A-Z][A-Z0-9_]{0,79}$' then raise exception using errcode='22023',message='Explicit stable legacy code required';end if;
  if p_kind='physical_location' and exists(select 1 from public.locations where location_code=code)
   or p_kind='location_group' and exists(select 1 from public.location_groups where group_code=code) then raise exception using errcode='23505',message='Legacy stable code already exists';end if;
  if p_kind='physical_location' and (p_payload->>'location_type') not in('restroom','exhibit') or p_kind='physical_location' and p_payload->>'location_type' is null then raise exception using errcode='22023',message='Supported physical location type required';end if;
  if p_kind='physical_location' and p_payload ? 'member_location_ids' then raise exception using errcode='22023',message='A physical identity is not a group';end if;
 elsif p_id is null or raw is null then raise exception using errcode='22023',message='Explicit existing legacy UUID required';end if;
 if p_action in('add','enroll') then
  if old.revision is not null then raise exception using errcode='23505',message='Legacy identity already enrolled';end if;
  if p_kind='physical_location' and exists(select 1 from public.custodial_places where physical_location_id=id) then raise exception using errcode='55000',message='Existing canonical physical binding needs separate explicit reconciliation';end if;
  pid:=gen_random_uuid();state:=jsonb_build_object('display_name',p_payload->>'display_name','aliases',coalesce(p_payload->'aliases','[]'::jsonb),'active',true,
   'cleaning_mode',p_payload->>'cleaning_mode','event_eligible',p_payload->'event_eligible','merged_into',null);
  members:=case when p_kind='physical_location' then jsonb_build_array(id) when p_action='add' then coalesce(p_payload->'member_location_ids','[]'::jsonb)
   else coalesce((select jsonb_agg(m.location_id order by m.location_id) from public.location_group_memberships m where m.location_group_id=source_preview.id),'[]'::jsonb) end;
  desired:=jsonb_build_object('setup_pending',p_action='add','member_location_ids',members,'metadata',coalesce(p_payload->'metadata','{}'::jsonb),'merged_legacy_id',null);
 else
  if old.revision is null then raise exception using errcode='55000',message='Enroll exact existing UUID before lifecycle changes';end if;
  pid:=old.place_id;
  select revision,snapshot into head,state from public.custodial_place_versions where place_id=pid order by revision desc limit 1;
  if head<>old.canonical_revision then raise exception using errcode='40001',message='Canonical source changed outside bridge; explicit reconciliation required';end if;
  desired:=old.snapshot;
  if state->>'merged_into' is not null and p_action<>'reverse' then raise exception using errcode='23514',message='Reverse logical merge before editing its source';end if;
  case p_action
   when 'rename' then state:=state||jsonb_build_object('display_name',p_payload->'display_name');
   when 'aliases' then state:=state||jsonb_build_object('aliases',p_payload->'aliases');
   when 'deactivate' then state:=state||'{"active":false}'::jsonb;
   when 'reactivate' then state:=state||'{"active":true}'::jsonb;
   when 'reclassify' then
    if not(p_payload ? 'cleaning_mode' or p_payload ? 'event_eligible' or p_payload ? 'metadata') then raise exception using errcode='22023',message='Classification change required';end if;
    state:=state||(p_payload-'metadata');if p_payload ? 'metadata' then desired:=desired||jsonb_build_object('metadata',p_payload->'metadata');end if;
   when 'memberships' then
    if p_kind<>'location_group' or not(p_payload ? 'member_location_ids') then raise exception using errcode='22023',message='Explicit complete group member UUID list required';end if;
    desired:=desired||jsonb_build_object('member_location_ids',p_payload->'member_location_ids');
   when 'merge' then
    select place_id,canonical_revision into target,target_head from public.custodial_place_source_versions where legacy_kind=p_kind and legacy_id=(p_payload->>'target_legacy_id')::uuid order by revision desc limit 1;
    select snapshot into target_state from public.custodial_place_versions where place_id=target and revision=target_head and effective_at<=at_time;
    if target is null or target=pid or target_state is null or target_state->'active'<>'true'::jsonb or target_state->>'merged_into' is not null
     or target_state->>'cleaning_mode' is distinct from state->>'cleaning_mode'
     or exists(select 1 from public.custodial_place_versions where place_id=target and revision>target_head)
     or public.place_bridge_sha(public.place_source_row(p_kind,(p_payload->>'target_legacy_id')::uuid)) is distinct from
      (select source_row_sha256 from public.custodial_place_source_versions where legacy_kind=p_kind and legacy_id=(p_payload->>'target_legacy_id')::uuid order by revision desc limit 1) then
     raise exception using errcode='23514',message='Logical merge requires current compatible same-namespace target';end if;
    state:=state||jsonb_build_object('active',false,'merged_into',target);
    desired:=desired||jsonb_build_object('merged_legacy_id',p_payload->>'target_legacy_id');
   when 'reverse' then
    if old.revision=1 then state:=state||'{"active":false,"merged_into":null}'::jsonb;desired:=desired||'{"merged_legacy_id":null}'::jsonb;
    else
     select * into prior from public.custodial_place_source_versions where legacy_kind=p_kind and legacy_id=id and revision=old.revision-1;
     select snapshot into state from public.custodial_place_versions where place_id=pid and revision=prior.canonical_revision;desired:=prior.snapshot;
    end if;
  end case;
 end if;
 if old.effective_at>at_time then raise exception using errcode='22023',message='Append after latest planned source effective time';end if;
 code:=coalesce(p_payload->>'canonical_code',(select canonical_code from public.custodial_places where place_id=pid));
 if code is null or code !~ '^[A-Z][A-Z0-9_]{0,79}$' or code='STINGRAYS' then raise exception using errcode='22023',message='Valid distinct canonical code required; Stingrays remains event-only';end if;
 if p_action in('add','enroll') and exists(select 1 from public.custodial_places where canonical_code=code) then raise exception using errcode='23505',message='Canonical stable code already exists';end if;
 if jsonb_typeof(state->'display_name') is distinct from 'string' or length(btrim(state->>'display_name')) not between 1 and 200
  or public.place_lifecycle_normalize(state->>'display_name')='' or jsonb_typeof(state->'aliases') is distinct from 'array' or jsonb_array_length(state->'aliases')>128
  or coalesce(state->>'cleaning_mode','') not in('SCAN_TRACKED','REMINDER_ONLY','NEVER_CLEAN') or jsonb_typeof(state->'event_eligible') is distinct from 'boolean'
  or exists(select 1 from jsonb_array_elements(state->'aliases') a where jsonb_typeof(a)<>'string' or length(btrim(a#>>'{}')) not between 1 and 200 or public.place_lifecycle_normalize(a#>>'{}')='') then raise exception using errcode='22023',message='Invalid name/aliases/independent classification';end if;
 select jsonb_agg(name order by name) into names from(select distinct value name from jsonb_array_elements_text(state->'aliases') union select state->>'display_name'
  union select snapshot->>'display_name' from public.custodial_place_versions where place_id=pid) n;
 if jsonb_array_length(names)>128 then raise exception using errcode='22023',message='Retained name aliases exceed bound';end if;state:=state||jsonb_build_object('aliases',names);
 candidate_root:=case when state->>'merged_into' is not null then (state->>'merged_into')::uuid when state->'active'='true'::jsonb then pid else null end;
 if candidate_root is not null then
  for check_at in select at_time union select effective_at from public.custodial_place_versions where effective_at>=at_time loop
   if exists(select 1 from public.custodial_places x cross join lateral public.place_lifecycle_snapshot(x.place_id,check_at) other
    cross join lateral jsonb_array_elements_text(other->'aliases') a cross join lateral jsonb_array_elements_text(names) proposed
    where x.place_id<>pid and public.place_lifecycle_root(x.place_id,check_at) is not null
     and public.place_lifecycle_root(x.place_id,check_at)<>candidate_root and public.place_lifecycle_normalize(a.value)=public.place_lifecycle_normalize(proposed.value)) then
    raise exception using errcode='23514',message='Proposed alias conflicts in current/future canonical timeline';end if;
  end loop;
 end if;
 members:=desired->'member_location_ids';
 if jsonb_typeof(members) is distinct from 'array' or jsonb_array_length(members)>256
  or exists(select 1 from jsonb_array_elements(members) m where jsonb_typeof(m)<>'string')
  or (select count(distinct value) from jsonb_array_elements_text(members))<>jsonb_array_length(members) then raise exception using errcode='22023',message='Distinct explicit member UUID array required';end if;
 if p_kind='location_group' and exists(select 1 from jsonb_array_elements_text(members) m where not exists(select 1 from public.locations l where l.id=m.value::uuid)) then raise exception using errcode='22023',message='Unknown physical member UUID';end if;
 if state->>'cleaning_mode'='SCAN_TRACKED' and jsonb_array_length(members)=0 then raise exception using errcode='23514',message='SCAN_TRACKED group requires actual physical members';end if;
 if jsonb_typeof(desired->'metadata') is distinct from 'object' or exists(select 1 from jsonb_object_keys(desired->'metadata') k where k not in('coordinates','schedule_eligible','staffing_eligible','public_restroom','staff_restroom','exhibit','restaurant','administrative','zoo_wide','offsite')) then raise exception using errcode='22023',message='Unknown place metadata fields';end if;
 for item in select key,value from jsonb_each(desired->'metadata') where key<>'coordinates' loop
  if jsonb_typeof(item.value)<>'boolean' then raise exception using errcode='22023',message='Independent capabilities must be explicit booleans';end if;
 end loop;
 if desired->'metadata' ? 'coordinates' and desired->'metadata'->'coordinates'<>'null'::jsonb then
  if jsonb_typeof(desired->'metadata'->'coordinates')<>'object' or exists(select 1 from jsonb_object_keys(desired->'metadata'->'coordinates') k where k not in('latitude','longitude'))
   or jsonb_typeof(desired->'metadata'->'coordinates'->'latitude') is distinct from 'number' or jsonb_typeof(desired->'metadata'->'coordinates'->'longitude') is distinct from 'number'
   or (desired->'metadata'->'coordinates'->>'latitude')::numeric not between -90 and 90 or (desired->'metadata'->'coordinates'->>'longitude')::numeric not between -180 and 180 then raise exception using errcode='22023',message='Explicit bounded coordinates required';end if;
 end if;
 source:=public.place_source_manifest();deps:=public.place_source_dependencies();
 if octet_length(source::text)+octet_length(deps::text)>2097152 then raise exception using errcode='54000',message='Source/dependency manifest exceeds bounded preview';end if;
 proposal:=jsonb_build_object('legacy_kind',p_kind,'legacy_id',id,'place_id',pid,'action',p_action,'payload',p_payload,'reason',p_reason,'requested_effective_at',p_effective_at,
  'expected_revision',coalesce(old.revision,0),'expected_canonical_revision',head,'target_place_id',target,'expected_target_revision',target_head,'canonical_code',code,
  'source_sha256',public.place_bridge_sha(source),'dependency_sha256',public.place_bridge_sha(deps),'raw_legacy',raw,'desired_snapshot',desired,'canonical_snapshot',state,
  'current_effective',public.place_lifecycle_snapshot(pid,clock),'latest_effective_at',old.effective_at,'operational_cutover',false,
  'requires_explicit_republish',p_action not in('rename','aliases','enroll'),'protected_finish_uses_original_route',true,
  'dependency_inventory',deps);
 insert into public.custodial_place_source_previews values(preview,p_manager,clock,clock+interval '10 minutes',proposal,public.place_bridge_sha(proposal));
 return jsonb_build_object('preview_id',preview,'actor_manager_id',p_manager,'created_at',clock,'expires_at',clock+interval '10 minutes','proposal_sha256',public.place_bridge_sha(proposal),'proposal',proposal);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_quarantine_malformed_scan_http(p_request_digest text, p_authenticated_credential_id text, p_content_length integer, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_digest text := lower(btrim(coalesce(p_request_digest,'')));
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if v_digest !~ '^[0-9a-f]{64}$' or nullif(lower(btrim(coalesce(p_authenticated_credential_id,''))), '')::uuid is null
     or coalesce(p_content_length, -1) < 0 or p_content_length > 10485760 then
    raise exception using errcode='22023',message='malformed HTTP quarantine requires a bounded request digest and authenticated credential';
  end if;
  return public.custodial_quarantine_offline_submission(
    'http-malformed-session:' || substr(v_digest,1,48),
    'http-malformed-completion:' || substr(v_digest,1,45),
    null,v_digest,
    jsonb_build_object('http_payload_digest',v_digest,'content_length',p_content_length,'authenticated_credential_id',p_authenticated_credential_id),
    'malformed_or_oversized_http_scan_request','{}'::jsonb,p_backend_execution_secret
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_quarantine_offline_submission(p_client_session_id text, p_client_completion_id text, p_context_id uuid, p_payload_fingerprint text, p_payload_json jsonb, p_reason text, p_details jsonb, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_existing public.custodial_offline_reconciliation_records%rowtype;
  v_context public.custodial_offline_actor_contexts%rowtype;
  v_reconciliation_id uuid;
  v_reason text := left(nullif(btrim(coalesce(p_reason,'')), ''), 200);
  v_fingerprint text;
  v_session_id text;
  v_completion_id text;
  v_safe_payload jsonb := coalesce(p_payload_json,'{}'::jsonb);
  v_result jsonb;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  v_reason := coalesce(v_reason, 'offline_authority_rejected');
  v_fingerprint := case when coalesce(p_payload_fingerprint,'') ~ '^[0-9a-f]{64}$' then p_payload_fingerprint
    else encode(extensions.digest(convert_to(coalesce(p_client_session_id,'') || ':' || coalesce(p_client_completion_id,'') || ':' || v_safe_payload::text,'UTF8'),'sha256'),'hex') end;
  v_session_id := nullif(btrim(coalesce(p_client_session_id,'')), '');
  v_completion_id := nullif(btrim(coalesce(p_client_completion_id,'')), '');
  if v_session_id is null or length(v_session_id)>200 then v_session_id := 'invalid-session:' || substr(v_fingerprint,1,48); end if;
  if v_completion_id is null or length(v_completion_id)>200 then v_completion_id := 'invalid-completion:' || substr(v_fingerprint,1,45); end if;
  if pg_column_size(v_safe_payload)>1048576 then
    v_safe_payload := jsonb_build_object('payload_omitted',true,'payload_bytes',pg_column_size(coalesce(p_payload_json,'{}'::jsonb)),'payload_fingerprint',v_fingerprint);
  end if;
  perform public.custodial_lock_offline_reconciliation_keys(v_session_id,v_completion_id);
  if p_context_id is not null then
    select * into v_context from public.custodial_offline_actor_contexts where context_id=p_context_id for update;
  end if;
  select * into v_existing from public.custodial_offline_reconciliation_records
  where client_completion_id=v_completion_id or client_session_id=v_session_id
  order by case when client_completion_id=v_completion_id then 0 else 1 end
  limit 1 for update;
  if v_existing.reconciliation_id is not null then
    if v_context.context_id is not null then
      update public.custodial_offline_actor_contexts set status='quarantined'
       where context_id=v_context.context_id and status='activated';
      update public.custodial_offline_submission_proofs set state='quarantined', consumed_at=now()
       where context_id=v_context.context_id and state='issued';
    end if;
    insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,reason,evidence_json)
    values (v_existing.reconciliation_id,'conflict_fenced',v_reason,
      jsonb_build_object('attempt_payload_fingerprint',v_fingerprint,'attempt_context_id',p_context_id,
        'attempt_occurrence_id',v_context.occurrence_id,'details',coalesce(p_details,'{}'::jsonb),'payload',v_safe_payload));
    perform public.custodial_enqueue_offline_reconciliation_notification(v_existing.reconciliation_id);
    return jsonb_build_object('status','quarantined','terminal',true,'automatic_replay_fenced',true,
      'reconciliation_id',v_existing.reconciliation_id,'reason',v_reason,'replayed',true,
      'attempt_context_fenced',v_context.context_id is not null);
  end if;
  v_result := jsonb_build_object('status','quarantined','terminal',true,'automatic_replay_fenced',true,
    'discard_local_workflow',false,'reason',v_reason,'client_session_id',v_session_id,'client_completion_id',v_completion_id);
  insert into public.custodial_offline_reconciliation_records(
    context_id,occurrence_id,occurrence_fingerprint,original_employee_id,device_id,credential_id,location_id,
    client_session_id,client_completion_id,payload_fingerprint,payload_json,state,quarantine_reason,result_json
  ) values (
    v_context.context_id,v_context.occurrence_id,v_context.occurrence_fingerprint,v_context.employee_id,v_context.device_id,v_context.credential_id,v_context.location_id,
    v_session_id,v_completion_id,v_fingerprint,v_safe_payload,'quarantined',v_reason,v_result
  ) returning reconciliation_id into v_reconciliation_id;
  if v_context.context_id is not null then
    update public.custodial_offline_actor_contexts set status='quarantined' where context_id=v_context.context_id and status='activated';
    update public.custodial_offline_submission_proofs set state='quarantined', consumed_at=now() where context_id=v_context.context_id and state='issued';
  end if;
  insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,reason,evidence_json)
  values (v_reconciliation_id,'quarantined',v_reason,coalesce(p_details,'{}'::jsonb));
  perform public.custodial_enqueue_offline_reconciliation_notification(v_reconciliation_id);
  return v_result || jsonb_build_object('reconciliation_id',v_reconciliation_id,'occurrence_id',v_context.occurrence_id);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_record_release_canary_transport_probe(p_device_identifier text, p_credential_id uuid, p_request_sha256 text, p_backend_commit_sha text, p_release_id text, p_native_origin text, p_app_edition text, p_native_request_id uuid, p_native_request_timestamp text, p_native_request_attestation_sha256 text, p_native_route_proof_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device text:=upper(btrim(coalesce(p_device_identifier,'')));
  v_control public.custodial_release_canary_controls%rowtype;
  v_probe public.custodial_release_canary_transport_probes%rowtype;
begin
  perform public.custodial_require_native_route_proof_secret(p_native_route_proof_secret);
  if v_device !~ '^KIOSK_(0[2-9]|10)$' or p_credential_id is null
     or lower(btrim(coalesce(p_request_sha256,''))) !~ '^[0-9a-f]{64}$'
     or lower(btrim(coalesce(p_backend_commit_sha,''))) !~ '^[0-9a-f]{40}$'
     or length(btrim(coalesce(p_release_id,''))) not between 1 and 200
     or btrim(coalesce(p_native_origin,'')) not in ('https://localhost','http://localhost','capacitor://localhost','ionic://localhost')
     or lower(btrim(coalesce(p_app_edition,'')))<>'custodial'
     or p_native_request_id is null
     or lower(btrim(coalesce(p_native_request_attestation_sha256,''))) !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='exact native canary transport evidence is required';
  end if;
  begin
    if nullif(btrim(coalesce(p_native_request_timestamp,'')),'')::timestamptz>statement_timestamp()+interval '15 seconds'
       or nullif(btrim(coalesce(p_native_request_timestamp,'')),'')::timestamptz<statement_timestamp()-interval '2 minutes' then
      raise exception using errcode='42501',message='native request proof is outside its accepted time window';
    end if;
  exception when invalid_datetime_format then
    raise exception using errcode='22023',message='native request proof timestamp is invalid';
  end;
  perform pg_advisory_xact_lock(hashtextextended('custodial-release-canary:'||v_device,0));
  select * into v_control from public.custodial_release_canary_controls
   where device_identifier=v_device for update;
  if v_control.device_identifier is null or not v_control.paused then
    raise exception using errcode='55000',message='the exact release canary must remain paused while phone transport is proven';
  end if;
  if not exists(
    select 1 from public.device_auth_credentials c join public.devices d on d.id=c.device_id
    where c.credential_id=p_credential_id and c.confirmed_at is not null and c.revoked_at is null
      and c.expires_at>statement_timestamp() and d.active=true and upper(btrim(d.device_id))=v_device
  ) then
    raise exception using errcode='42501',message='a current credential for the exact physical canary is required';
  end if;
  insert into public.custodial_release_canary_transport_probes(
    device_identifier,credential_id,control_updated_at,expires_at,request_sha256,
    native_request_id,native_request_timestamp,native_request_attestation_sha256,
    backend_commit_sha,release_id,native_origin,app_edition
  ) values(
    v_device,p_credential_id,v_control.updated_at,statement_timestamp()+interval '5 minutes',
    lower(btrim(p_request_sha256)),p_native_request_id,p_native_request_timestamp::timestamptz,
    lower(btrim(p_native_request_attestation_sha256)),lower(btrim(p_backend_commit_sha)),btrim(p_release_id),
    btrim(p_native_origin),lower(btrim(p_app_edition))
  ) returning * into v_probe;
  return jsonb_build_object(
    'probe_id',v_probe.probe_id,'device_identifier',v_device,'observed_at',v_probe.observed_at,
    'expires_at',v_probe.expires_at,'backend_commit_sha',v_probe.backend_commit_sha,
    'release_id',v_probe.release_id,'route_path',v_probe.route_path,
    'probe_function',v_probe.probe_function,'ready',v_probe.expires_at>statement_timestamp()
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_reject_offline_evidence_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_expiry_owner name;
begin
  if tg_op='DELETE' then
    raise exception using errcode='23514',message='Custodial offline authority evidence is append-only';
  end if;
  select pg_get_userbyid(proowner) into v_expiry_owner
  from pg_proc
  where oid=to_regprocedure('public.expire_stale_open_sessions(timestamp with time zone)');
  if current_setting('custodial.offline_expiry_transition',true)='expire_stale_open_sessions'
     and current_user=v_expiry_owner then
    return new;
  end if;
  if not public.custodial_backend_transition_allowed() then
    raise exception using errcode='23514',message='Custodial offline authority evidence is immutable outside the canonical writer';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_release_authority_current_column_set_definition(p_relation_identity text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_relation oid:=to_regclass(p_relation_identity); v_columns text;
begin
  if v_relation is null then return null; end if;
  select string_agg(quote_literal(a.attname),',' order by a.attname) into v_columns
  from pg_attribute a where a.attrelid=v_relation and a.attnum>0 and not a.attisdropped;
  return 'select public.custodial_release_authority_restore_column_set('||quote_literal(p_relation_identity)
    ||',array['||coalesce(v_columns,'')||']::text[]);';
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_release_authority_current_constraint_definition(p_object_identity text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_relation_text text:=split_part(p_object_identity,':',1); v_relation oid:=to_regclass(v_relation_text); v_constraint text:=substr(p_object_identity,position(':' in p_object_identity)+1); v_definition text;
begin
  select pg_get_constraintdef(c.oid,true) into v_definition from pg_constraint c where c.conrelid=v_relation and c.conname=v_constraint;
  if v_definition is null then return null; end if;
  return 'select public.custodial_release_authority_restore_constraint('||quote_literal(v_relation_text)||','||quote_literal(v_constraint)||','||quote_literal(v_definition)||');';
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_release_authority_current_view_definition(p_object_identity text)
 RETURNS text
 LANGUAGE sql
 STABLE STRICT
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select format(
    'create or replace view %I.%I as %s; alter view %I.%I reset (check_option,security_barrier,security_invoker);%s alter view %I.%I owner to %I;',
    namespace.nspname,relation.relname,
    rtrim(pg_get_viewdef(relation.oid,true),E' \n\r\t;'),
    namespace.nspname,relation.relname,
    case when coalesce(cardinality(relation.reloptions),0)=0 then '' else format(
      ' alter view %I.%I set (%s);',namespace.nspname,relation.relname,
      (select string_agg(format('%I=%L',option.option_name,option.option_value),', ' order by option.option_name)
       from pg_options_to_table(relation.reloptions) option)
    ) end,
    namespace.nspname,relation.relname,pg_get_userbyid(relation.relowner)
  )
  from pg_class relation
  join pg_namespace namespace on namespace.oid=relation.relnamespace
  where relation.oid=to_regclass(p_object_identity) and relation.relkind='v';
$function$

CREATE OR REPLACE FUNCTION public.custodial_release_authority_reset_grants(p_object_identity text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_relation oid:=to_regclass(p_object_identity); v_function oid:=to_regprocedure(p_object_identity); v_role record; v_column record;
begin
  if v_relation is not null then
    execute format('revoke all privileges on table %s from public',v_relation::regclass);
    for v_role in
      select distinct r.rolname from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a join pg_roles r on r.oid=a.grantee
      where c.oid=v_relation and a.grantee<>c.relowner
    loop execute format('revoke all privileges on table %s from %I',v_relation::regclass,v_role.rolname); end loop;
    for v_column in
      select a.attname,x.grantee,r.rolname from pg_attribute a join pg_class c on c.oid=a.attrelid
      cross join lateral aclexplode(a.attacl) x left join pg_roles r on r.oid=x.grantee
      where c.oid=v_relation and a.attnum>0 and not a.attisdropped and a.attacl is not null and x.grantee<>c.relowner
    loop
      execute format('revoke all privileges (%I) on table %s from %s',v_column.attname,v_relation::regclass,case when v_column.grantee=0 then 'public' else quote_ident(v_column.rolname) end);
    end loop;
    return;
  end if;
  if v_function is not null then
    execute format('revoke all privileges on function %s from public',v_function::regprocedure);
    for v_role in
      select distinct r.rolname from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a join pg_roles r on r.oid=a.grantee
      where p.oid=v_function and a.grantee<>p.proowner
    loop execute format('revoke all privileges on function %s from %I',v_function::regprocedure,v_role.rolname); end loop;
    return;
  end if;
  raise exception using errcode='42704',message='release authority grant target is missing';
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_release_authority_restore_column(p_relation_identity text, p_column_name text, p_data_type text, p_collation_identity text, p_identity_kind text, p_generated_kind text, p_expression text, p_not_null boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_relation oid:=to_regclass(p_relation_identity); v_current record; v_target_type text;
  v_declaration text; v_expected_identity text:=coalesce(p_identity_kind,'');
  v_expected_generated text:=coalesce(p_generated_kind,'');
begin
  if v_relation is null then raise exception using errcode='42704',message='release authority column relation is missing'; end if;
  if p_column_name is null or p_column_name='' or p_data_type is null or p_data_type='' then
    raise exception using errcode='22023',message='release authority column definition is incomplete';
  end if;
  v_target_type:=p_data_type||case when p_collation_identity is null then '' else ' collate '||p_collation_identity end;
  v_declaration:=quote_ident(p_column_name)||' '||v_target_type
    ||case
      when v_expected_generated<>'' then ' generated always as ('||p_expression||') stored'
      when v_expected_identity<>'' then ' generated '||case v_expected_identity when 'a' then 'always' else 'by default' end||' as identity'
      when p_expression is not null then ' default '||p_expression
      else ''
    end
    ||case when p_not_null then ' not null' else '' end;
  select format_type(a.atttypid,a.atttypmod) data_type,a.attidentity identity_kind,a.attgenerated generated_kind,
    pg_get_expr(d.adbin,d.adrelid) expression,a.attnotnull not_null,
    case when a.attcollation<>t.typcollation then quote_ident(cn.nspname)||'.'||quote_ident(co.collname) end collation_identity
  into v_current
  from pg_attribute a join pg_type t on t.oid=a.atttypid
  left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum
  left join pg_collation co on co.oid=a.attcollation left join pg_namespace cn on cn.oid=co.collnamespace
  where a.attrelid=v_relation and a.attname=p_column_name and a.attnum>0 and not a.attisdropped;
  if not found then
    execute format('alter table %s add column %s',v_relation::regclass,v_declaration);
    return;
  end if;
  if v_expected_generated<>'' or coalesce(v_current.generated_kind,'')<>'' then
    if v_current.data_type=p_data_type and v_current.collation_identity is not distinct from p_collation_identity
       and coalesce(v_current.generated_kind,'')=v_expected_generated
       and v_current.expression is not distinct from p_expression and v_current.not_null=p_not_null then return; end if;
    execute format('alter table %s drop column %I cascade',v_relation::regclass,p_column_name);
    execute format('alter table %s add column %s',v_relation::regclass,v_declaration);
    return;
  end if;
  if v_current.data_type<>p_data_type or v_current.collation_identity is distinct from p_collation_identity then
    execute format('alter table %s alter column %I type %s using %I::%s',v_relation::regclass,p_column_name,v_target_type,p_column_name,p_data_type);
  end if;
  if coalesce(v_current.identity_kind,'')<>v_expected_identity then
    if coalesce(v_current.identity_kind,'')<>'' then execute format('alter table %s alter column %I drop identity if exists',v_relation::regclass,p_column_name); end if;
    if v_expected_identity<>'' then execute format('alter table %s alter column %I add generated %s as identity',v_relation::regclass,p_column_name,case v_expected_identity when 'a' then 'always' else 'by default' end); end if;
  end if;
  if v_expected_identity='' then
    execute format('alter table %s alter column %I drop default',v_relation::regclass,p_column_name);
    if p_expression is not null then execute format('alter table %s alter column %I set default %s',v_relation::regclass,p_column_name,p_expression); end if;
  end if;
  execute format('alter table %s alter column %I %s not null',v_relation::regclass,p_column_name,case when p_not_null then 'set' else 'drop' end);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_release_authority_restore_constraint(p_relation_identity text, p_constraint_name text, p_constraint_definition text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_relation oid:=to_regclass(p_relation_identity); v_current text;
begin
  if v_relation is null then raise exception using errcode='42704',message='release authority constraint relation is missing'; end if;
  select pg_get_constraintdef(c.oid,true) into v_current from pg_constraint c where c.conrelid=v_relation and c.conname=p_constraint_name;
  if v_current is null then
    execute format('alter table %s add constraint %I %s',v_relation::regclass,p_constraint_name,p_constraint_definition);
  elsif v_current<>p_constraint_definition then
    execute format('alter table %s drop constraint %I cascade',v_relation::regclass,p_constraint_name);
    execute format('alter table %s add constraint %I %s',v_relation::regclass,p_constraint_name,p_constraint_definition);
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_release_canary_is_paused(p_device_identifier text, p_backend_execution_secret text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_device text:=upper(btrim(coalesce(p_device_identifier,''))); v_paused boolean;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if v_device !~ '^KIOSK_(0[2-9]|10)$' then
    raise exception using errcode='22023',message='an exact employee-phone canary identifier is required';
  end if;
  select paused into v_paused from public.custodial_release_canary_controls where device_identifier=v_device;
  if not found then raise exception using errcode='55000',message='the exact release canary control has not been initialized'; end if;
  return v_paused;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_report_device_sync_status_internal(p_device_identifier text, p_queue_count integer, p_oldest_item_at timestamp with time zone, p_retry_count integer, p_last_server_ack_at timestamp with time zone, p_frontend_version text, p_last_error text, p_correlation_id text, p_queue_authority_groups jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device public.devices%rowtype;
  v_now timestamptz:=clock_timestamp();
  v_group jsonb; v_groups jsonb:='[]'::jsonb; v_seen text[]:='{}'::text[];
  v_employee_id uuid; v_epoch integer; v_snapshot_id text; v_count integer;
  v_oldest timestamptz; v_key text; v_bound_count integer:=0;
begin
  if p_queue_count is null or p_queue_count<0 or p_queue_count>10000
     or p_retry_count is null or p_retry_count<0 then
    raise exception using errcode='22023',message='device sync counts are invalid';
  end if;
  if jsonb_typeof(coalesce(p_queue_authority_groups,'null'::jsonb))<>'array'
     or jsonb_array_length(p_queue_authority_groups)>100 then
    raise exception using errcode='22023',message='queue authority groups must be a bounded array';
  end if;
  select d.* into v_device from public.device_aliases da join public.devices d
    on d.id=da.canonical_device_id and d.active=true
   where da.alias_identifier=btrim(p_device_identifier) and da.active=true limit 1;
  if not found then
    select d.* into v_device from public.devices d
     where d.device_id=btrim(p_device_identifier) and d.active=true limit 1;
  end if;
  if v_device.id is null then raise exception 'Active device not found.'; end if;

  for v_group in select value from jsonb_array_elements(p_queue_authority_groups) loop
    if jsonb_typeof(v_group)<>'object' or exists(
      select 1 from jsonb_object_keys(v_group) key
       where key not in ('employee_id','assignment_epoch','snapshot_id','queue_count','oldest_item_at')
    ) then raise exception using errcode='22023',message='queue authority group has an invalid shape'; end if;
    begin
      v_employee_id:=nullif(lower(btrim(v_group->>'employee_id')),'')::uuid;
      v_epoch:=(v_group->>'assignment_epoch')::integer;
      v_snapshot_id:=lower(btrim(v_group->>'snapshot_id'));
      v_count:=(v_group->>'queue_count')::integer;
      v_oldest:=nullif(btrim(v_group->>'oldest_item_at'),'')::timestamptz;
    exception when others then
      raise exception using errcode='22023',message='queue authority group values are invalid';
    end;
    if v_employee_id is null or v_epoch is null or v_epoch<1
       or v_snapshot_id is null or v_snapshot_id !~ '^[0-9a-f]{64}$'
       or v_count is null or v_count<1 or v_oldest is null
       or not isfinite(v_oldest) or v_oldest>v_now+interval '10 minutes' then
      raise exception using errcode='22023',message='queue authority group values are outside their accepted bounds';
    end if;
    v_key:=v_employee_id::text||':'||v_epoch::text||':'||v_snapshot_id;
    if v_key=any(v_seen) then raise exception using errcode='22023',message='queue authority groups contain a duplicate identity'; end if;
    v_seen:=array_append(v_seen,v_key); v_bound_count:=v_bound_count+v_count;
    if v_bound_count>p_queue_count then raise exception using errcode='22023',message='queue authority group counts exceed the reported queue'; end if;
    if not exists(select 1 from public.custodial_offline_scan_authority_snapshots s
      where s.snapshot_id=v_snapshot_id and s.device_id=v_device.id
        and s.employee_id=v_employee_id and s.assignment_epoch=v_epoch) then
      raise exception using errcode='42501',message='queue authority group does not match an issued device snapshot';
    end if;
    v_groups:=v_groups||jsonb_build_array(jsonb_build_object(
      'employee_id',v_employee_id,'assignment_epoch',v_epoch,'snapshot_id',v_snapshot_id,
      'queue_count',v_count,'oldest_item_at',v_oldest));
  end loop;
  select coalesce(jsonb_agg(value order by value->>'employee_id',(value->>'assignment_epoch')::integer,value->>'snapshot_id'),'[]'::jsonb)
    into v_groups from jsonb_array_elements(v_groups);

  insert into public.device_sync_status(
    device_id,presented_identifier,queue_count,oldest_item_at,retry_count,last_server_ack_at,
    frontend_version,last_error,correlation_id,queue_authority_groups,updated_at
  ) values(
    v_device.id,btrim(p_device_identifier),p_queue_count,p_oldest_item_at,p_retry_count,p_last_server_ack_at,
    nullif(btrim(coalesce(p_frontend_version,'')),''),left(nullif(coalesce(p_last_error,''),''),1000),
    nullif(btrim(coalesce(p_correlation_id,'')),''),v_groups,v_now
  ) on conflict(device_id) do update set
    presented_identifier=excluded.presented_identifier,queue_count=excluded.queue_count,
    oldest_item_at=excluded.oldest_item_at,retry_count=excluded.retry_count,
    last_server_ack_at=excluded.last_server_ack_at,frontend_version=excluded.frontend_version,
    last_error=excluded.last_error,correlation_id=excluded.correlation_id,
    queue_authority_groups=excluded.queue_authority_groups,updated_at=v_now;
  update public.devices set last_seen_at=v_now,updated_at=v_now where id=v_device.id;
  return jsonb_build_object('ok',true,'device_id',v_device.device_id,'updated_at',v_now,
    'last_seen_at',v_now,'bound_queue_count',v_bound_count,'unbound_queue_count',p_queue_count-v_bound_count);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_require_backend_execution_secret(p_execution_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_expected text;
  v_enabled boolean;
begin
  select execution_secret_digest,enabled into v_expected,v_enabled
  from public.custodial_backend_execution_config where config_key=true;
  if v_enabled is not true or v_expected is null or length(coalesce(p_execution_secret,''))<32
     or encode(extensions.digest(convert_to(p_execution_secret,'UTF8'),'sha256'),'hex')<>v_expected then
    raise exception using errcode='42501',message='custodial backend execution boundary is not authorized';
  end if;
  perform set_config('custodial.backend_execution_secret',p_execution_secret,true);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_run_release_canary_recovery_probe(p_device_identifier text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device text:=upper(btrim(coalesce(p_device_identifier,'')));
  v_health jsonb;
  v_probe public.custodial_release_canary_recovery_probes%rowtype;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if v_device !~ '^KIOSK_(0[2-9]|10)$' then
    raise exception using errcode='22023',message='an exact employee-phone canary identifier is required';
  end if;
  if not exists(select 1 from public.custodial_release_canary_controls where device_identifier=v_device and paused=true) then
    raise exception using errcode='55000',message='the exact release canary must exist and remain paused during its recovery probe';
  end if;
  v_health:=public.custodial_backend_authority_health(p_backend_execution_secret);
  insert into public.custodial_release_canary_recovery_probes(
    device_identifier,expires_at,passed,authority_health,authority_health_sha256
  ) values(
    v_device,statement_timestamp()+interval '5 minutes',coalesce((v_health->>'ok')::boolean,false),v_health,
    encode(extensions.digest(convert_to(v_health::text,'UTF8'),'sha256'),'hex')
  ) returning * into v_probe;
  return jsonb_build_object(
    'probe_id',v_probe.probe_id,'device_identifier',v_device,'checked_at',v_probe.checked_at,
    'expires_at',v_probe.expires_at,'passed',v_probe.passed,'authority_health_sha256',v_probe.authority_health_sha256,
    'authority_health',v_health
  );
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_sessions_preserve_original_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_employee_name text;
  v_location_code text;
  v_location_name text;
  v_device_identifier text;
  v_device_name text;
  v_assignment_epoch bigint;
begin
  if tg_op = 'INSERT' then
    select e.display_name into v_employee_name
    from public.employees e where e.id = new.employee_id;
    select l.location_code, l.location_name into v_location_code, v_location_name
    from public.locations l where l.id = new.location_id;
    select d.device_id, d.device_name, d.assignment_epoch
      into v_device_identifier, v_device_name, v_assignment_epoch
    from public.devices d where d.id = new.device_id;
    if v_employee_name is null or v_location_code is null or v_location_name is null
       or v_device_identifier is null or v_device_name is null or v_assignment_epoch is null then
      raise exception using errcode='23503', message='Cleaning identity must resolve before a session is created';
    end if;
    new.employee_name_snapshot := v_employee_name;
    new.location_code_snapshot := v_location_code;
    new.location_name_snapshot := v_location_name;
    new.device_identifier_snapshot := v_device_identifier;
    new.device_name_snapshot := v_device_name;
    new.assignment_epoch_snapshot := v_assignment_epoch;
    new.identity_snapshot_provenance := 'session_create';
    return new;
  end if;

  if row(new.id,new.session_uuid,new.client_session_id,new.employee_id,new.location_id,new.device_id,new.started_at,new.created_at)
     is distinct from
     row(old.id,old.session_uuid,old.client_session_id,old.employee_id,old.location_id,old.device_id,old.started_at,old.created_at) then
    raise exception using errcode='23514', message='Original cleaning identity is immutable; append a named-manager correction instead';
  end if;
  if row(new.employee_name_snapshot,new.location_code_snapshot,new.location_name_snapshot,
         new.device_identifier_snapshot,new.device_name_snapshot,new.assignment_epoch_snapshot,new.identity_snapshot_provenance)
     is distinct from
     row(old.employee_name_snapshot,old.location_code_snapshot,old.location_name_snapshot,
         old.device_identifier_snapshot,old.device_name_snapshot,old.assignment_epoch_snapshot,old.identity_snapshot_provenance) then
    raise exception using errcode='23514', message='At-event cleaning identity snapshots are immutable';
  end if;
  if old.finish_operation_id is not null and new.finish_operation_id is distinct from old.finish_operation_id then
    raise exception using errcode='23514', message='Cleaning finish operation identity is immutable once assigned';
  end if;
  if old.ended_at is not null and new.ended_at is distinct from old.ended_at then
    raise exception using errcode='23514', message='Cleaning end time is immutable once assigned';
  end if;
  if old.duration_minutes is not null and new.duration_minutes is distinct from old.duration_minutes then
    raise exception using errcode='23514', message='Cleaning duration is immutable once assigned';
  end if;
  if old.duration_display is not null and new.duration_display is distinct from old.duration_display then
    raise exception using errcode='23514', message='Cleaning duration display is immutable once assigned';
  end if;
  if old.completion_source is not null and new.completion_source is distinct from old.completion_source then
    raise exception using errcode='23514', message='Cleaning completion source is immutable once assigned';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_set_employee_active(p_employee_id uuid, p_active boolean, p_changed_by_manager_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_release_devices boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_manager public.ops_manager_managers%rowtype;
  v_employee public.employees%rowtype;
  v_device public.devices%rowtype;
  v_previous boolean;
  v_reason text := left(nullif(btrim(coalesce(p_reason, '')), ''), 500);
  v_released text[] := '{}'::text[];
begin
  v_manager := public.custodial_assert_manager(p_changed_by_manager_id);
  select * into v_employee from public.employees where id = p_employee_id for update;
  if v_employee.id is null then
    raise exception using errcode = 'P0002', message = 'Employee not found.';
  end if;
  if v_employee.employee_code !~ '^EMP[0-9]+$' then
    raise exception using errcode = '22023', message = 'CoverAll and system staffing slots cannot be changed from Employee Phones.';
  end if;
  v_previous := v_employee.active;
  if v_previous = p_active then
    return jsonb_build_object('changed', false, 'employee', to_jsonb(v_employee), 'released_devices', v_released);
  end if;

  if p_active is false and not p_release_devices and exists (
    select 1 from public.devices where assigned_employee_id = v_employee.id and active is true
  ) then
    raise exception using errcode = '23503', message = 'Release the employee phone before marking this employee inactive.';
  end if;

  if p_active is false and p_release_devices then
    for v_device in
      select * from public.devices
      where assigned_employee_id = v_employee.id and active is true
      order by device_id
      for update
    loop
      update public.devices
      set assigned_employee_id = null,
          device_name = 'Unassigned ' || v_device.device_id,
          updated_at = now()
      where id = v_device.id;

      update public.msg_device_assignments
      set is_active = false,
          notes = 'Employee inactive; phone released by Operations app',
          updated_at = now()
      where upper(device_identifier) = upper(v_device.device_id)
         or upper(device_identifier) in (
           select upper(alias_identifier) from public.device_aliases
           where canonical_device_id = v_device.id and active is true
         );

      insert into public.custodial_employee_device_assignment_history(
        device_id, device_identifier, previous_employee_id, previous_employee_name,
        new_employee_id, new_employee_name, changed_by_manager_id,
        change_reason, source, metadata_json
      ) values (
        v_device.id, v_device.device_id, v_employee.id, v_employee.display_name,
        null, null, v_manager.manager_id,
        coalesce(v_reason, 'employee_inactivated'), 'operations_app',
        jsonb_build_object('employee_status_changed', true)
      );
      v_released := array_append(v_released, v_device.device_id);
    end loop;
  end if;

  update public.employees
  set active = p_active,
      updated_at = now(),
      notes = case
        when p_active then notes
        when v_reason is null then notes
        when notes is null or btrim(notes) = '' then 'Inactive: ' || v_reason
        else notes || E'\nInactive: ' || v_reason
      end
  where id = v_employee.id
  returning * into v_employee;

  update public.msg_users
  set is_active = p_active,
      display_name = v_employee.display_name,
      updated_at = now()
  where employee_id = v_employee.id;

  insert into public.custodial_employee_status_history(
    employee_id, employee_name, previous_active, new_active,
    changed_by_manager_id, change_reason, source, metadata_json
  ) values (
    v_employee.id, v_employee.display_name, v_previous, p_active,
    v_manager.manager_id,
    coalesce(v_reason, case when p_active then 'employee_reactivated' else 'employee_inactivated' end),
    'operations_app',
    jsonb_build_object('released_devices', to_jsonb(v_released))
  );

  return jsonb_build_object(
    'changed', true,
    'employee', to_jsonb(v_employee),
    'released_devices', to_jsonb(v_released)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.custodial_set_maintenance_ticket_outcome(p_ticket_id uuid, p_outcome text, p_manager_id uuid, p_external_work_order_reference text, p_notes text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_ticket public.maintenance_tickets%rowtype;
  v_manager public.ops_manager_managers%rowtype;
  v_outcome text:=btrim(coalesce(p_outcome,''));
  v_reference text:=nullif(btrim(coalesce(p_external_work_order_reference,'')),'');
  v_notes text:=nullif(btrim(coalesce(p_notes,'')),'');
  v_at timestamptz:=statement_timestamp();
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if p_ticket_id is null or p_manager_id is null or v_outcome not in ('mark_fixed','work_order_sent') then
    raise exception using errcode='22023',message='ticket, named manager, and supported outcome are required';
  end if;
  select * into v_manager from public.ops_manager_managers m
    where m.manager_id=p_manager_id and m.active=true and m.revoked_at is null
      and m.is_system_principal=false
      and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[] for share;
  if not found or nullif(btrim(v_manager.display_name),'') is null then
    raise exception using errcode='42501',message='active named manager authority is required';
  end if;
  if v_outcome='work_order_sent' and (v_reference is null or length(v_reference)>120) then
    raise exception using errcode='22023',message='a real external work-order reference is required';
  end if;
  if v_outcome='mark_fixed' and v_reference is not null then
    raise exception using errcode='22023',message='Mark fixed cannot claim an external work-order reference';
  end if;
  if v_notes is not null and length(v_notes)>1000 then
    raise exception using errcode='22023',message='outcome notes exceed 1000 characters';
  end if;
  select * into v_ticket from public.maintenance_tickets t where t.id=p_ticket_id for update;
  if not found then raise exception using errcode='P0002',message='maintenance reminder not found'; end if;
  if v_ticket.status<>'open' then
    raise exception using errcode='40901',message='Maintenance reminder already has a closed outcome. Refresh before acting.';
  end if;
  update public.maintenance_tickets t set status='closed',closed_at=v_at,
    closed_by=left(btrim(v_manager.display_name),200),close_notes=v_notes,closed_via='manager_issue_outcome',
    resolution_outcome=v_outcome,external_work_order_reference=v_reference,
    resolution_actor_manager_id=p_manager_id
    where t.id=p_ticket_id;
  insert into public.maintenance_ticket_outcome_history(
    ticket_id,outcome,actor_manager_id,actor_name_snapshot,external_work_order_reference,notes,previous_status,created_at
  ) values(p_ticket_id,v_outcome,p_manager_id,left(btrim(v_manager.display_name),200),v_reference,v_notes,v_ticket.status,v_at);
  return jsonb_build_object('ticket_id',p_ticket_id,'status','closed','outcome',v_outcome,
    'external_work_order_reference',v_reference,'actor_manager_id',p_manager_id,
    'actor_name',left(btrim(v_manager.display_name),200),'recorded_at',v_at);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_start_offline_occurrence_native(p_device_id text, p_location_code text, p_client_session_id text, p_client_started_at text, p_snapshot_id text, p_snapshot_employee_id text, p_snapshot_assignment_epoch integer, p_snapshot_credential_id text, p_authenticated_credential_id text, p_native_scan_entry_id text, p_native_start_attestation_version text, p_native_start_attestation text, p_native_route_proof_secret text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare v_result jsonb; v_context_id uuid; v_attestation_sha256 text; v_scan_entry_id uuid;
begin
  perform public.custodial_require_native_route_proof_secret(p_native_route_proof_secret);
  begin
    v_scan_entry_id:=nullif(lower(btrim(coalesce(p_native_scan_entry_id,''))),'')::uuid;
  exception when others then
    raise exception using errcode='42501',message='a verified native NFC start handoff is required';
  end;
  if v_scan_entry_id is null or btrim(coalesce(p_native_start_attestation_version,''))<>'custodial-native-start.v1'
     or lower(btrim(coalesce(p_native_start_attestation,''))) !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='42501',message='a verified native start attestation is required';
  end if;
  v_result:=public.custodial_start_offline_occurrence(
    p_device_id,p_location_code,p_client_session_id,p_client_started_at,p_snapshot_id,
    p_snapshot_employee_id,p_snapshot_assignment_epoch,p_snapshot_credential_id,
    p_authenticated_credential_id,p_backend_execution_secret
  );
  v_context_id:=(v_result->>'context_id')::uuid;
  v_attestation_sha256:=encode(extensions.digest(convert_to(lower(btrim(p_native_start_attestation)),'UTF8'),'sha256'),'hex');
  if exists(select 1 from public.custodial_offline_actor_contexts c where c.context_id=v_context_id
    and (c.native_start_attestation_version is not null and (c.native_scan_entry_id<>v_scan_entry_id
      or c.native_start_attestation_version<>p_native_start_attestation_version
      or c.native_start_attestation_sha256<>v_attestation_sha256))) then
    raise exception using errcode='23505',message='native start attestation replay does not match the frozen occurrence';
  end if;
  update public.custodial_offline_actor_contexts
     set native_scan_entry_id=v_scan_entry_id,
         native_start_attestation_version=p_native_start_attestation_version,
         native_start_attestation_sha256=v_attestation_sha256
   where context_id=v_context_id and native_start_attestation_version is null;
  return v_result||jsonb_build_object('native_start_attested',true);
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_start_offline_occurrence(p_device_id text, p_location_code text, p_client_session_id text, p_client_started_at text, p_snapshot_id text, p_snapshot_employee_id text, p_snapshot_assignment_epoch integer, p_snapshot_credential_id text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_client_session_id text:=nullif(btrim(coalesce(p_client_session_id,'')), ''); v_started_at timestamptz;
  v_credential_id uuid; v_snapshot_employee_id uuid; v_snapshot_credential_id uuid;
  v_snapshot public.custodial_offline_scan_authority_snapshots%rowtype;
  v_existing public.custodial_offline_actor_contexts%rowtype; v_proof public.custodial_offline_submission_proofs%rowtype;
  v_device record; v_location record; v_assignment_change_id uuid; v_context public.custodial_offline_actor_contexts%rowtype;
  v_proof_value text:=encode(extensions.gen_random_bytes(32),'hex'); v_fingerprint text; v_snapshot_location_code text;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  if v_client_session_id is null or length(v_client_session_id)>200 then raise exception using errcode='22023',message='client_session_id is required for offline occurrence activation'; end if;
  begin
    v_started_at:=nullif(btrim(coalesce(p_client_started_at,'')),'')::timestamptz;
    v_credential_id:=nullif(lower(btrim(coalesce(p_authenticated_credential_id,''))),'')::uuid;
    v_snapshot_employee_id:=nullif(lower(btrim(coalesce(p_snapshot_employee_id,''))),'')::uuid;
    v_snapshot_credential_id:=nullif(lower(btrim(coalesce(p_snapshot_credential_id,''))),'')::uuid;
  exception when others then raise exception using errcode='22023',message='offline activation requires canonical snapshot identity and credential'; end;
  if nullif(lower(btrim(coalesce(p_snapshot_id,''))),'') !~ '^[0-9a-f]{64}$' or p_snapshot_assignment_epoch is null
     then raise exception using errcode='22023',message='exact authenticated snapshot identity is required for offline occurrence activation'; end if;
  if not isfinite(v_started_at) or v_started_at>now()+interval '10 minutes' or v_started_at<now()-interval '7 days' then raise exception using errcode='22023',message='offline occurrence start timestamp is outside the accepted window'; end if;
  select * into v_snapshot from public.custodial_offline_scan_authority_snapshots where snapshot_id=lower(btrim(p_snapshot_id)) for share;
  select x->>'location_code' into v_snapshot_location_code
    from jsonb_array_elements(v_snapshot.locations_json) x
   where upper(regexp_replace(x->>'location_code','[^A-Z0-9]+','','g'))=case upper(regexp_replace(btrim(coalesce(p_location_code,'')),'[^A-Z0-9]+','','g'))
     when 'TETON' then 'TETX' when 'TETONRR' then 'TETM' when 'TETONRESTROOMS' then 'TETM'
     else upper(regexp_replace(btrim(coalesce(p_location_code,'')),'[^A-Z0-9]+','','g')) end
   order by x->>'location_code' limit 1;
  perform pg_advisory_xact_lock(hashtextextended('custodial-offline-activation:'||v_client_session_id,0));
  select * into v_existing from public.custodial_offline_actor_contexts where client_session_id=v_client_session_id for update;
  if v_existing.context_id is not null then
    if upper(btrim(coalesce(p_device_id,'')))<>upper((select device_id from public.devices where id=v_existing.device_id))
       or not public.custodial_credential_may_transmit_frozen_work(v_existing.credential_id,v_credential_id,v_existing.device_id) or v_existing.canonical_location_code<>v_snapshot_location_code
       or v_existing.started_at<>v_started_at or v_existing.snapshot_id<>lower(btrim(p_snapshot_id))
       or v_existing.snapshot_employee_id<>v_snapshot_employee_id or v_existing.snapshot_assignment_epoch<>p_snapshot_assignment_epoch
       or v_existing.snapshot_credential_id<>v_snapshot_credential_id then raise exception using errcode='23505',message='offline occurrence activation replay does not match the original frozen snapshot'; end if;
    select * into v_proof from public.custodial_offline_submission_proofs where context_id=v_existing.context_id for update;
    if v_proof.state='issued' and v_proof.issued_submission_proof is not null then
      return jsonb_build_object('context_id',v_existing.context_id,'occurrence_id',v_existing.occurrence_id,'client_session_id',v_existing.client_session_id,
        'canonical_location_code',v_existing.canonical_location_code,'location_aliases',v_existing.location_aliases,'started_at',public.custodial_canonical_utc_millis(v_existing.started_at),
        'employee_id',v_existing.employee_id,'assignment_epoch',v_existing.assignment_epoch,'submission_proof',v_proof.issued_submission_proof,
        'expires_at',public.custodial_canonical_utc_millis(v_existing.expires_at),'snapshot_id',v_existing.snapshot_id,'schema_version','offline-authority.v4',
        'committable',true,'replayed',true,'frozen_actor',true);
    end if;
    raise exception using errcode='40901',message='the frozen occurrence cannot recover a completion proof; create a manager-visible recovery disposition';
  end if;
  if v_snapshot.snapshot_id is null or v_snapshot.employee_id<>v_snapshot_employee_id or v_snapshot.assignment_epoch<>p_snapshot_assignment_epoch
     or v_snapshot.credential_id<>v_snapshot_credential_id or not public.custodial_credential_may_transmit_frozen_work(v_snapshot.credential_id,v_credential_id,v_snapshot.device_id) or v_started_at>=v_snapshot.expires_at
     or v_started_at<v_snapshot.generated_at then
    raise exception using errcode='42501',message='issued offline authority snapshot was not valid when the occurrence began';
  end if;
  select d.id,d.device_id,c.confirmed_at,c.revoked_at,c.expires_at into v_device
    from public.devices d join public.device_auth_credentials c on c.credential_id=v_snapshot_credential_id and c.device_id=d.id
   where upper(btrim(d.device_id))=upper(btrim(coalesce(p_device_id,''))) for update of d;
  if v_device.id is null or v_device.id<>v_snapshot.device_id or v_device.confirmed_at is null
     or v_device.confirmed_at>v_snapshot.generated_at
     or v_started_at<v_device.confirmed_at
     or v_started_at>=v_device.expires_at or (v_device.revoked_at is not null and v_started_at>=v_device.revoked_at) then
    raise exception using errcode='42501',message='the device credential was not valid when the offline occurrence began';
  end if;
  if exists(
    select 1 from public.custodial_employee_device_assignment_history h
    where h.device_id=v_snapshot.device_id and h.changed_at>v_snapshot.generated_at and h.changed_at<=v_started_at
  ) then raise exception using errcode='42501',message='the issued offline snapshot no longer owned the phone when the occurrence began'; end if;
  select l.id,l.location_code,jsonb_build_array(l.location_code,upper(btrim(p_location_code))) aliases into v_location
    from public.locations l where l.location_code=v_snapshot_location_code for share;
  if v_location.id is null or v_snapshot_location_code is null then raise exception using errcode='22023',message='location is not authorized by the issued offline snapshot'; end if;
  if not public.custodial_offline_authority_active_at('device',v_snapshot.device_id,v_started_at)
     or not public.custodial_offline_authority_active_at('location',v_location.id,v_started_at) then
    raise exception using errcode='42501',message='device or location was not active when the offline occurrence began';
  end if;
  select h.assignment_change_id into v_assignment_change_id from public.custodial_employee_device_assignment_history h
   where h.device_id=v_snapshot.device_id and h.new_employee_id=v_snapshot.employee_id and h.changed_at<=v_snapshot.generated_at
   order by h.changed_at desc limit 1;
  if v_assignment_change_id is null then raise exception using errcode='42501',message='an authoritative device assignment epoch is required for offline occurrence activation'; end if;
  v_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('client_session_id',v_client_session_id,'device_id',v_snapshot.device_id::text,
    'employee_id',v_snapshot.employee_id::text,'credential_id',v_snapshot_credential_id::text,'assignment_epoch',v_snapshot.assignment_epoch,
    'snapshot_id',v_snapshot.snapshot_id,'snapshot_employee_id',v_snapshot.employee_id::text,'snapshot_assignment_epoch',v_snapshot.assignment_epoch,
    'snapshot_credential_id',v_snapshot.credential_id::text,'assignment_change_id',v_assignment_change_id::text,'location_id',v_location.id::text,
    'location_code',v_location.location_code,'location_aliases',v_location.aliases,'started_at',v_started_at)::text,'UTF8'),'sha256'),'hex');
  insert into public.custodial_offline_actor_contexts(client_session_id,device_id,employee_id,credential_id,assignment_epoch,assignment_change_id,location_id,canonical_location_code,location_aliases,started_at,occurrence_fingerprint,expires_at,snapshot_id,snapshot_employee_id,snapshot_assignment_epoch,snapshot_credential_id)
  values(v_client_session_id,v_snapshot.device_id,v_snapshot.employee_id,v_snapshot_credential_id,v_snapshot.assignment_epoch,v_assignment_change_id,v_location.id,v_location.location_code,v_location.aliases,v_started_at,v_fingerprint,now()+interval '7 days',v_snapshot.snapshot_id,v_snapshot.employee_id,v_snapshot.assignment_epoch,v_snapshot.credential_id) returning * into v_context;
  insert into public.custodial_offline_submission_proofs(context_id,proof_digest,issued_submission_proof) values(v_context.context_id,encode(extensions.digest(convert_to(v_proof_value,'UTF8'),'sha256'),'hex'),v_proof_value);
  return jsonb_build_object('context_id',v_context.context_id,'occurrence_id',v_context.occurrence_id,'client_session_id',v_context.client_session_id,
    'canonical_location_code',v_context.canonical_location_code,'location_aliases',v_context.location_aliases,'started_at',public.custodial_canonical_utc_millis(v_context.started_at),
    'employee_id',v_context.employee_id,'assignment_epoch',v_context.assignment_epoch,'submission_proof',v_proof_value,'expires_at',public.custodial_canonical_utc_millis(v_context.expires_at),
    'snapshot_id',v_snapshot.snapshot_id,'schema_version','offline-authority.v4','committable',true,'replayed',false,'frozen_actor',true);
end
$function$

CREATE OR REPLACE FUNCTION public.device_auth_consume_enrollment_code(p_device_id uuid, p_code_hash text, p_credential_id uuid, p_token_hash text, p_device_label text, p_expires_at timestamp with time zone, p_user_agent_hash text DEFAULT NULL::text, p_ip_hash text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_code public.device_auth_enrollment_codes%rowtype;
  v_now timestamptz := now();
  v_credential public.device_auth_credentials%rowtype;
  v_replaced_id uuid;
  v_replaced_ids uuid[] := array[]::uuid[];
begin
  if p_device_id is null then raise exception 'device_id is required'; end if;
  if p_code_hash is null or length(p_code_hash)<>64 then raise exception 'valid code_hash is required'; end if;
  if p_credential_id is null then raise exception 'credential_id is required'; end if;
  if p_token_hash is null or length(p_token_hash)<>64 then raise exception 'valid token_hash is required'; end if;
  if p_expires_at is null or p_expires_at<=v_now then raise exception 'future expires_at is required'; end if;

  select * into v_code
  from public.device_auth_enrollment_codes c
  where c.device_id=p_device_id and c.consumed_at is null and c.revoked_at is null and c.status='active'
  for update;

  if not found then return jsonb_build_object('ok',false,'reason','missing'); end if;
  if v_code.expires_at<=v_now then
    update public.device_auth_enrollment_codes c set status='expired' where c.enrollment_id=v_code.enrollment_id;
    return jsonb_build_object('ok',false,'reason','expired','enrollment_id',v_code.enrollment_id);
  end if;
  if v_code.code_hash<>p_code_hash then
    update public.device_auth_enrollment_codes c
       set failed_attempts=least(10,c.failed_attempts+1),last_failed_at=v_now
     where c.enrollment_id=v_code.enrollment_id;
    return jsonb_build_object('ok',false,'reason','invalid','enrollment_id',v_code.enrollment_id);
  end if;

  for v_replaced_id in
    update public.device_auth_credentials dc
       set revoked_at=v_now,revoked_reason='replaced_by_new_enrollment'
     where dc.device_id=p_device_id and dc.revoked_at is null
     returning dc.credential_id
  loop
    v_replaced_ids:=array_append(v_replaced_ids,v_replaced_id);
  end loop;

  insert into public.device_auth_credentials(
    credential_id,device_id,token_hash,device_label,user_agent_hash,
    created_ip_hash,expires_at,metadata_json
  ) values (
    p_credential_id,p_device_id,p_token_hash,nullif(left(coalesce(p_device_label,''),160),''),
    p_user_agent_hash,p_ip_hash,p_expires_at,coalesce(p_metadata_json,'{}'::jsonb)
  ) returning * into v_credential;

  insert into public.custodial_device_credential_replacements(
    device_id,predecessor_credential_id,successor_credential_id,enrollment_id,
    replaced_at,replaced_by,metadata_json
  )
  select p_device_id,replaced_id,p_credential_id,v_code.enrollment_id,v_now,
    v_code.created_by,jsonb_build_object('enrollment_flow',coalesce(p_metadata_json->>'enrollment_flow','enrollment'))
  from unnest(v_replaced_ids) replaced_id;

  update public.device_auth_enrollment_codes c
     set consumed_at=v_now,consumed_by_credential_id=p_credential_id,use_count=1,status='used'
   where c.enrollment_id=v_code.enrollment_id;

  return jsonb_build_object(
    'ok',true,'enrollment_id',v_code.enrollment_id,'credential_id',v_credential.credential_id,
    'expires_at',v_credential.expires_at,'replaced_credential_count',cardinality(v_replaced_ids)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.device_auth_consume_enrollment_operation(p_operation_id uuid, p_flow text, p_device_id uuid, p_code_hash text, p_request_fingerprint text, p_credential_id uuid, p_token_hash text, p_device_label text, p_expires_at timestamp with time zone, p_result_ciphertext text, p_result_iv text, p_result_auth_tag text, p_result_expires_at timestamp with time zone, p_encryption_version text, p_user_agent_hash text DEFAULT NULL::text, p_ip_hash text DEFAULT NULL::text, p_metadata_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_now timestamptz:=clock_timestamp();
  v_operation public.device_auth_enrollment_operations%rowtype;
  v_code public.device_auth_enrollment_codes%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_failed_attempts integer;
  v_replaced_id uuid;
  v_replaced_ids uuid[]:=array[]::uuid[];
begin
  if p_operation_id is null or p_device_id is null or p_credential_id is null then
    raise exception using errcode='22023',message='operation_id, device_id, and credential_id are required';
  end if;
  if p_flow not in ('enrollment','recovery') then
    raise exception using errcode='22023',message='flow must be enrollment or recovery';
  end if;
  if p_code_hash is null or length(p_code_hash)<>64
     or p_request_fingerprint is null or length(p_request_fingerprint)<>64
     or p_token_hash is null or length(p_token_hash)<>64 then
    raise exception using errcode='22023',message='valid enrollment hashes are required';
  end if;
  if p_expires_at is null or p_expires_at<=v_now then
    raise exception using errcode='22023',message='future credential expiry is required';
  end if;
  if p_result_expires_at is null
     or p_result_expires_at<=v_now
     or p_result_expires_at>v_now+interval '1 hour' then
    raise exception using errcode='22023',message='resumable result expiry must be within one hour';
  end if;
  if nullif(btrim(coalesce(p_encryption_version,'')),'') is null
     or length(coalesce(p_result_ciphertext,''))<32
     or length(coalesce(p_result_ciphertext,''))>16384
     or length(coalesce(p_result_iv,'')) not between 12 and 128
     or length(coalesce(p_result_auth_tag,'')) not between 16 and 128 then
    raise exception using errcode='22023',message='valid encrypted enrollment result is required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('custodial-enrollment-operation:'||p_operation_id::text,0));


  if exists(select 1 from public.custodial_assigned_activation_operations where operation_id=p_operation_id) then
   perform public.custodial_activation_assert_consume(p_operation_id,p_device_id,p_code_hash);
  elsif not exists(select 1 from public.device_auth_enrollment_operations where operation_id=p_operation_id)
   and (p_metadata_json->>'activation_kind'='assigned_device_activation' or exists(
    select 1 from public.device_auth_enrollment_codes where device_id=p_device_id and code_hash=p_code_hash
     and metadata_json->>'purpose'='assigned_device_activation')) then
   raise exception 'assigned activation transport operation required';
  end if;
  select * into v_operation
  from public.device_auth_enrollment_operations
  where operation_id=p_operation_id
  for update;

  if v_operation.operation_id is not null then
    if v_operation.device_id<>p_device_id
       or v_operation.flow<>p_flow
       or v_operation.request_fingerprint<>p_request_fingerprint then
      return jsonb_build_object('ok',false,'reason','operation_conflict');
    end if;

    if v_operation.status='committed' and v_operation.resume_expires_at<=v_now then
      update public.device_auth_credentials
         set revoked_at=coalesce(revoked_at,v_now),
             revoked_reason=case when revoked_at is null then 'enrollment_operation_unconfirmed_timeout' else revoked_reason end
       where credential_id=v_operation.credential_id;
      update public.device_auth_enrollment_operations
         set status='expired',expired_at=coalesce(expired_at,v_now),
             result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
       where operation_id=v_operation.operation_id
       returning * into v_operation;
      return jsonb_build_object('ok',false,'reason','operation_expired','operation_id',v_operation.operation_id);
    end if;

    if v_operation.status='committed' then
      select * into v_credential
      from public.device_auth_credentials
      where credential_id=v_operation.credential_id
        and device_id=v_operation.device_id
        and revoked_at is null
        and expires_at>v_now;
      if v_credential.credential_id is null then
        update public.device_auth_enrollment_operations
           set status='cancelled',cancelled_at=coalesce(cancelled_at,v_now),
               result_ciphertext=null,result_iv=null,result_auth_tag=null,updated_at=v_now
         where operation_id=v_operation.operation_id;
        return jsonb_build_object('ok',false,'reason','credential_unavailable','operation_id',v_operation.operation_id);
      end if;
      return jsonb_build_object(
        'ok',true,'replayed',true,'status',v_operation.status,
        'operation_id',v_operation.operation_id,'flow',v_operation.flow,
        'credential_id',v_operation.credential_id,
        'credential_expires_at',v_credential.expires_at,
        'resume_expires_at',v_operation.resume_expires_at,
        'encryption_version',v_operation.encryption_version,
        'result_ciphertext',v_operation.result_ciphertext,
        'result_iv',v_operation.result_iv,
        'result_auth_tag',v_operation.result_auth_tag
      );
    end if;

    return jsonb_build_object(
      'ok',false,'reason','operation_'||v_operation.status,
      'operation_id',v_operation.operation_id,'credential_id',v_operation.credential_id
    );
  end if;

  perform 1 from public.devices where id=p_device_id for update;
  if not found then
    raise exception using errcode='P0002',message='device was not found';
  end if;

  select * into v_code
  from public.device_auth_enrollment_codes
  where device_id=p_device_id and consumed_at is null and revoked_at is null
  order by created_at desc
  limit 1
  for update;

  if v_code.enrollment_id is null or v_code.expires_at<=v_now then
    if v_code.enrollment_id is not null then
      update public.device_auth_enrollment_codes
         set revoked_at=coalesce(revoked_at,v_now),
             metadata_json=metadata_json||jsonb_build_object('revoked_reason','expired')
       where enrollment_id=v_code.enrollment_id;
    end if;
    return jsonb_build_object('ok',false,'reason','invalid_or_expired');
  end if;

  if v_code.failed_attempts>=10 then
    update public.device_auth_enrollment_codes
       set revoked_at=coalesce(revoked_at,v_now),
           metadata_json=metadata_json||jsonb_build_object('revoked_reason','attempt_limit')
     where enrollment_id=v_code.enrollment_id;
    return jsonb_build_object('ok',false,'reason','invalid_or_expired');
  end if;

  if v_code.code_hash<>p_code_hash then
    v_failed_attempts:=least(v_code.failed_attempts+1,10);
    update public.device_auth_enrollment_codes
       set failed_attempts=v_failed_attempts,last_failed_at=v_now,
           revoked_at=case when v_failed_attempts>=10 then v_now else revoked_at end,
           metadata_json=case when v_failed_attempts>=10
             then metadata_json||jsonb_build_object('revoked_reason','attempt_limit')
             else metadata_json end
     where enrollment_id=v_code.enrollment_id;
    insert into public.device_auth_events(
      device_id,credential_id,event_type,success,reason,ip_hash,user_agent_hash,metadata_json
    ) values (
      p_device_id,null,'custodial_enrollment_operation_failed',false,'invalid_code',
      p_ip_hash,p_user_agent_hash,
      jsonb_build_object('operation_id',p_operation_id,'flow',p_flow,'enrollment_id',v_code.enrollment_id,'failed_attempts',v_failed_attempts)
    );
    return jsonb_build_object('ok',false,'reason','invalid_or_expired');
  end if;

  for v_replaced_id in
    update public.device_auth_credentials
       set revoked_at=v_now,revoked_reason='re_enrolled'
     where device_id=p_device_id and revoked_at is null
     returning credential_id
  loop
    v_replaced_ids:=array_append(v_replaced_ids,v_replaced_id);
  end loop;

  insert into public.device_auth_credentials(
    credential_id,device_id,token_hash,device_label,
    user_agent_hash,created_ip_hash,last_user_agent_hash,last_ip_hash,
    metadata_json,confirmed_at,last_used_at,expires_at
  ) values (
    p_credential_id,p_device_id,p_token_hash,
    nullif(left(btrim(coalesce(p_device_label,'')),160),''),
    p_user_agent_hash,p_ip_hash,p_user_agent_hash,p_ip_hash,
    coalesce(p_metadata_json,'{}'::jsonb)||jsonb_build_object('enrollment_operation_id',p_operation_id,'enrollment_flow',p_flow),
    null,null,p_expires_at
  ) returning * into v_credential;

  insert into public.custodial_device_credential_replacements(
    device_id,predecessor_credential_id,successor_credential_id,enrollment_id,
    replaced_at,replaced_by,metadata_json
  )
  select p_device_id,replaced_id,p_credential_id,v_code.enrollment_id,v_now,
    v_code.created_by,jsonb_build_object('enrollment_flow',p_flow,'resumable_operation_id',p_operation_id)
  from unnest(v_replaced_ids) replaced_id;

  update public.device_auth_enrollment_codes
     set consumed_at=v_now,consumed_by_credential_id=v_credential.credential_id
   where enrollment_id=v_code.enrollment_id;

  insert into public.device_auth_enrollment_operations(
    operation_id,device_id,credential_id,enrollment_id,flow,request_fingerprint,status,
    encryption_version,result_ciphertext,result_iv,result_auth_tag,resume_expires_at,metadata_json
  ) values (
    p_operation_id,p_device_id,v_credential.credential_id,v_code.enrollment_id,p_flow,p_request_fingerprint,'committed',
    left(p_encryption_version,80),p_result_ciphertext,p_result_iv,p_result_auth_tag,p_result_expires_at,
    coalesce(p_metadata_json,'{}'::jsonb)
  ) returning * into v_operation;

  insert into public.device_auth_events(
    device_id,credential_id,event_type,success,reason,ip_hash,user_agent_hash,metadata_json
  ) values (
    p_device_id,v_credential.credential_id,'custodial_enrollment_operation_committed',true,null,
    p_ip_hash,p_user_agent_hash,
    coalesce(p_metadata_json,'{}'::jsonb)||jsonb_build_object(
      'operation_id',p_operation_id,'flow',p_flow,'enrollment_id',v_code.enrollment_id,
      'resume_expires_at',p_result_expires_at
    )
  );

  return jsonb_build_object(
    'ok',true,'replayed',false,'status','committed',
    'operation_id',v_operation.operation_id,'flow',v_operation.flow,
    'credential_id',v_credential.credential_id,
    'credential_expires_at',v_credential.expires_at,
    'resume_expires_at',v_operation.resume_expires_at,
    'encryption_version',v_operation.encryption_version,
    'result_ciphertext',v_operation.result_ciphertext,
    'result_iv',v_operation.result_iv,
    'result_auth_tag',v_operation.result_auth_tag
  );
end
$function$

CREATE OR REPLACE FUNCTION public.enforce_session_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
                                                                                                                                                                        begin
                                                                                                                                                                          if tg_op = 'UPDATE' and old.status is distinct from new.status then
                                                                                                                                                                              if old.status = 'active' and new.status not in ('pending_submit', 'cancelled') then
                                                                                                                                                                                    raise exception 'Invalid session transition: active -> %', new.status;
                                                                                                                                                                                        end if;

                                                                                                                                                                                            if old.status = 'pending_submit' and new.status not in ('closed', 'cancelled') then
                                                                                                                                                                                                  raise exception 'Invalid session transition: pending_submit -> %', new.status;
                                                                                                                                                                                                      end if;

                                                                                                                                                                                                          if old.status = 'closed' and new.status <> 'closed' then
                                                                                                                                                                                                                raise exception 'Closed sessions cannot transition to %', new.status;
                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                        if old.status = 'cancelled' and new.status <> 'cancelled' then
                                                                                                                                                                                                                              raise exception 'Cancelled sessions cannot transition to %', new.status;
                                                                                                                                                                                                                                  end if;
                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                      return new;
                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                      $function$

CREATE OR REPLACE FUNCTION public.evaluate_location_proximity_v2(p_location_code text, p_device_identifier text, p_latitude numeric, p_longitude numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_session_uuid text DEFAULT NULL::text, p_client_event_id text DEFAULT NULL::text, p_correlation_id text DEFAULT NULL::text, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_session_key text:=nullif(btrim(coalesce(p_session_uuid,'')),'');
  v_session_state text;
  v_result jsonb;
  v_location_code text;
  v_target_lat numeric;
  v_target_lon numeric;
  v_radius numeric;
  v_surveyed_at timestamptz;
  v_confidence text;
  v_source text;
  v_distance numeric;
  v_uncertainty numeric;
  v_result_code text;
  v_authoritative boolean:=false;
  v_scope text:='advisory_uncalibrated';
  v_event_id uuid;
  v_event_count integer;
begin
  if v_session_key is not null then
    v_session_state:=public.custodial_gps_session_state(p_location_code,p_device_identifier,v_session_key);
    if v_session_state is null then
      raise exception using errcode='23503', message='Session does not belong to this device and location';
    end if;
  end if;

  v_location_code:=public.resolve_scan_location_code(p_location_code);
  if v_location_code is null then
    raise exception using errcode='23503', message='Active scanned location was not found';
  end if;
  -- The measurement core historically substitutes clock_timestamp() for NULL.
  -- Settle an old queued reading as unavailable without a status/event write;
  -- an arrival time is not a phone capture time. This keeps saved cleaning
  -- actions moving and does not reject or defer a cleaning submission.
  if p_observed_at is null then
    return jsonb_build_object('ok',true,'result','gps_timestamp_unavailable',
      'authoritative',false,'authority_scope','advisory_missing_capture_time',
      'scan_event_id',null);
  end if;
  select lp.latitude,lp.longitude,lp.authority_radius_m,lp.authority_surveyed_at,
         lp.coordinate_confidence,lp.coordinate_source
    into v_target_lat,v_target_lon,v_radius,v_surveyed_at,v_confidence,v_source
  from public.locations l
  join public.location_proximity_settings lp on lp.location_id=l.id
  where l.active=true and l.location_code=v_location_code and lp.active=true
    and lp.latitude is not null and lp.longitude is not null
  order by lp.updated_at desc
  limit 1
  for share of lp;

  v_result:=public.custodial_evaluate_location_proximity_v2_measurement(
    p_location_code,p_device_identifier,p_latitude,p_longitude,p_accuracy_m,
    p_session_uuid,p_client_event_id,p_correlation_id,p_observed_at
  );

  v_result_code:=coalesce(v_result->>'result','gps_unavailable');
  if v_target_lat is not null and v_target_lon is not null
     and v_radius is not null and v_surveyed_at is not null and v_surveyed_at<=clock_timestamp()
     and lower(btrim(coalesce(v_confidence,'')))='surveyed'
     and nullif(btrim(coalesce(v_source,'')),'') is not null then
    v_scope:='surveyed_location_radius';
    -- The core has already checked observation age, accuracy and motion. Its
    -- global-radius near/away/boundary result is replaced using the surveyed
    -- exact location and radius; terminal session handling remains below.
    if v_result_code in ('near','away','boundary_uncertain') then
      v_distance:=6371000 * 2 * asin(sqrt(
        power(sin(radians((p_latitude-v_target_lat)::double precision)/2),2)
        + cos(radians(v_target_lat::double precision))*cos(radians(p_latitude::double precision))
        * power(sin(radians((p_longitude-v_target_lon)::double precision)/2),2)
      ));
      v_uncertainty:=greatest(
        greatest(5,public.get_setting_int('gps_boundary_hysteresis_m',15)),
        least(greatest(coalesce(p_accuracy_m,0),0),greatest(25,public.get_setting_int('gps_max_accuracy_m',100)))
      );
      if abs(v_distance-v_radius)<=v_uncertainty then
        v_result_code:='boundary_uncertain';
      elsif v_distance<v_radius then
        v_result_code:='near';
        v_authoritative:=true;
      else
        v_result_code:='away';
        v_authoritative:=true;
      end if;
    end if;
  elsif v_result_code in ('near','away','boundary_uncertain') then
    v_result_code:='location_uncalibrated';
  end if;

  if v_session_state is not null and v_session_state not in ('active','pending_submit') then
    v_result_code:='post_session';
    v_authoritative:=false;
    v_scope:='post_session_advisory';
  end if;

  v_event_id:=nullif(v_result->>'scan_event_id','')::uuid;
  -- A repeated client event ID may refer to an earlier, different reading.
  -- Never rewrite that evidence or return a new authoritative claim for it.
  update public.scan_events se
     set result=v_result_code,
         notes=case
           when v_result_code='near' then 'Phone is within the surveyed scanned-location radius.'
           when v_result_code='away' then 'Phone is outside the surveyed scanned-location radius.'
           when v_result_code='location_uncalibrated' then 'GPS estimate is advisory; the scanned location has no surveyed coordinate and radius.'
           when v_result_code='post_session' then 'GPS arrived after the cleaning was no longer active; advisory evidence only.'
           else se.notes end,
         payload_json=coalesce(se.payload_json,'{}'::jsonb) || jsonb_build_object(
           'authoritative',v_authoritative,'authority_scope',v_scope,
           'evidence_scope',case when v_scope='post_session_advisory' then 'post_session_advisory' else 'active_work_advisory' end,
           'session_state',v_session_state,
           'allowed_radius_m',case when v_scope='surveyed_location_radius' then v_radius else null end,
           'coordinate_source',case when v_scope='surveyed_location_radius' then v_source else se.payload_json->>'coordinate_source' end,
           'surveyed_at',v_surveyed_at
         )
  where se.id=v_event_id
    and se.event_type='work_position_check'
    and se.location_code=v_result->>'location_code'
    and se.device_identifier=v_result->>'device_id'
    and se.session_id is not distinct from (
      select s.id from public.sessions s where s.session_uuid=v_result->>'session_uuid' limit 1
    )
    and (se.payload_json->>'observed_at')::timestamptz=p_observed_at
    and se.payload_json->>'correlation_id' is not distinct from p_correlation_id
    and (se.payload_json->>'client_latitude')::numeric is not distinct from p_latitude
    and (se.payload_json->>'client_longitude')::numeric is not distinct from p_longitude
    and (se.payload_json->>'accuracy_m')::numeric is not distinct from p_accuracy_m;
  get diagnostics v_event_count=row_count;
  if v_event_count<>1 then
    v_result_code:='gps_duplicate_event';
    v_authoritative:=false;
    v_scope:='advisory_duplicate_event';
  end if;

  update public.device_location_proximity_status gps
     set result=v_result_code,
         badge_color=case when v_result_code='near' then 'green' when v_result_code='away' then 'red' else 'amber' end,
         allowed_radius_m=case when v_scope='surveyed_location_radius' then v_radius else gps.allowed_radius_m end,
         metadata_json=coalesce(gps.metadata_json,'{}'::jsonb) || jsonb_build_object(
           'authoritative',v_authoritative,'authority_scope',v_scope,
           'evidence_scope',case when v_scope='post_session_advisory' then 'post_session_advisory' else 'active_work_advisory' end,
           'session_state',v_session_state,
           'surveyed_at',v_surveyed_at
         )
  where gps.device_id=(select d.id from public.devices d where d.device_id=v_result->>'device_id' limit 1)
    and gps.location_id=(select l.id from public.locations l where l.location_code=v_result->>'location_code' limit 1)
    and gps.session_uuid=coalesce(v_result->>'session_uuid','')
    and gps.evaluated_at=(v_result->>'evaluated_at')::timestamptz;

  return v_result || jsonb_build_object(
    'result',v_result_code,
    'authoritative',v_authoritative,
    'authority_scope',v_scope,
    'evidence_scope',case when v_scope='post_session_advisory' then 'post_session_advisory' else 'active_work_advisory' end,
    'session_state',v_session_state,
    'badge_color',case when v_result_code='near' then 'green' when v_result_code='away' then 'red' else 'amber' end,
    'allowed_radius_m',case when v_scope='surveyed_location_radius' then v_radius else null end,
    'surveyed_at',v_surveyed_at
  );
end
$function$

CREATE OR REPLACE FUNCTION public.events_app_delete_retention_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_days integer := public.mz_retention_setting_int('retention_event_days',14,1,3650);
  v_local_today date := (clock_timestamp() at time zone 'America/Chicago')::date;
begin
  -- Old clients still send DELETE for every event whose end date is in the
  -- past. Treat that request as a retention attempt rather than authority to
  -- erase a recent event.
  if coalesce(old.end_date,old.event_date)>v_local_today-v_days then
    return null;
  end if;

  -- The row is now outside the review window. Remove its short-lived audit
  -- history explicitly; notification rows follow the parent by cascade.
  perform set_config('app.event_retention_delete',old.id::text,true);
  delete from public.events_app_event_history where event_id=old.id;
  return old;
end
$function$

CREATE OR REPLACE FUNCTION public.events_app_events_set_end_date()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.end_date is null then
    new.end_date := new.event_date;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.events_app_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.events_app_validate_scope_venue()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_scope text;
  v_zoo_venue public.event_venues%rowtype;
  v_primary public.event_venues%rowtype;
  v_bad_count integer;
begin
  v_scope := upper(replace(btrim(coalesce(new.event_scope, 'UNKNOWN')), '-', '_'));
  if v_scope in ('ZOO', 'ZOO_FOOTPRINT') then
    v_scope := 'ZOO_WIDE';
  elsif v_scope in ('SINGLE') then
    v_scope := 'SINGLE_VENUE';
  elsif v_scope in ('MULTI', 'MULTIPLE', 'MULTIPLE_VENUES') then
    v_scope := 'MULTI_VENUE';
  elsif v_scope = 'OFF_SITE' then
    v_scope := 'OFFSITE';
  end if;

  if v_scope not in ('ZOO_WIDE', 'SINGLE_VENUE', 'MULTI_VENUE', 'OFFSITE', 'UNKNOWN') then
    raise exception 'Invalid event scope %', new.event_scope using errcode = '23514';
  end if;

  new.event_scope := v_scope;
  new.event_timezone := coalesce(nullif(btrim(new.event_timezone), ''), 'America/Chicago');
  if new.event_timezone <> 'America/Chicago' then
    raise exception 'event_timezone must be America/Chicago' using errcode = '23514';
  end if;
  new.venue_ids := coalesce(new.venue_ids, '{}'::uuid[]);
  new.coverage_location_ids := coalesce(new.coverage_location_ids, '{}'::uuid[]);
  new.staffing_area_ids := coalesce(new.staffing_area_ids, '{}'::uuid[]);
  new.display_location := nullif(btrim(coalesce(new.display_location, '')), '');

  if new.parser_confidence is not null and new.parser_confidence not in ('high', 'medium', 'low') then
    raise exception 'parser_confidence must be high, medium, or low' using errcode = '23514';
  end if;

  if v_scope = 'ZOO_WIDE' then
    select * into v_zoo_venue
    from public.event_venues
    where venue_code = 'ZOO_FOOTPRINT' and active = true
    limit 1;
    if v_zoo_venue.id is null then
      raise exception 'Zoo Footprint venue is not configured' using errcode = '23514';
    end if;
    new.primary_venue_id := v_zoo_venue.id;
    new.venue_ids := array[v_zoo_venue.id]::uuid[];
    new.location_group_id := v_zoo_venue.location_group_id;
    new.display_location := 'Zoo Footprint';
    new.needs_review := false;
  elsif v_scope = 'SINGLE_VENUE' then
    if new.primary_venue_id is null then
      raise exception 'SINGLE_VENUE events require one eligible event venue' using errcode = '23514';
    end if;
    select * into v_primary
    from public.event_venues
    where id = new.primary_venue_id and active = true
    limit 1;
    if v_primary.id is null or v_primary.eligible_event_venue is not true or v_primary.event_scope = 'ZOO_WIDE' then
      raise exception 'Selected event venue is not eligible as a primary event venue' using errcode = '23514';
    end if;
    if not (new.primary_venue_id = any(new.venue_ids)) then
      new.venue_ids := array_prepend(new.primary_venue_id, new.venue_ids);
    end if;
    new.location_group_id := coalesce(v_primary.location_group_id, new.location_group_id);
    new.display_location := coalesce(new.display_location, v_primary.display_name);
    new.needs_review := false;
  elsif v_scope = 'MULTI_VENUE' then
    if coalesce(array_length(new.venue_ids, 1), 0) < 2 then
      raise exception 'MULTI_VENUE events require at least two eligible event venues' using errcode = '23514';
    end if;
    select count(*) into v_bad_count
    from unnest(new.venue_ids) as selected(venue_id)
    left join public.event_venues ev on ev.id = selected.venue_id and ev.active = true
    where ev.id is null or ev.eligible_event_venue is not true or ev.event_scope = 'ZOO_WIDE';
    if v_bad_count > 0 then
      raise exception 'MULTI_VENUE events contain an ineligible venue' using errcode = '23514';
    end if;
    if new.primary_venue_id is null or not (new.primary_venue_id = any(new.venue_ids)) then
      new.primary_venue_id := new.venue_ids[1];
    end if;
    select * into v_primary from public.event_venues where id = new.primary_venue_id limit 1;
    new.location_group_id := coalesce(v_primary.location_group_id, new.location_group_id);
    new.display_location := coalesce(
      new.display_location,
      (
        select string_agg(ev.display_name, ', ' order by ev.display_name)
        from public.event_venues ev
        where ev.id = any(new.venue_ids)
      )
    );
    new.needs_review := false;
  elsif v_scope = 'OFFSITE' then
    new.display_location := coalesce(new.display_location, 'Offsite');
    new.needs_review := false;
  else
    new.needs_review := true;
    new.display_location := coalesce(new.display_location, 'Needs Review');
  end if;

  select count(*) into v_bad_count
  from unnest(new.coverage_location_ids) as selected(location_group_id)
  left join public.location_groups lg on lg.id = selected.location_group_id
  where lg.id is null or lg.eligible_custodial_coverage is not true;
  if v_bad_count > 0 then
    raise exception 'coverage_location_ids contains an ineligible custodial coverage location' using errcode = '23514';
  end if;

  select count(*) into v_bad_count
  from unnest(new.staffing_area_ids) as selected(location_group_id)
  left join public.location_groups lg on lg.id = selected.location_group_id
  where lg.id is null or lg.eligible_staffing_assignment is not true;
  if v_bad_count > 0 then
    raise exception 'staffing_area_ids contains an ineligible staffing location' using errcode = '23514';
  end if;

  if new.event_scope <> 'UNKNOWN' and exists (
    select 1
    from public.location_groups lg
    where lg.id = new.location_group_id
      and lg.eligible_event_venue is not true
      and lg.eligible_event_scope is not true
      and (lg.public_restroom is true or lg.staff_restroom is true or lg.group_name ilike '%restroom%' or lg.group_code ilike '%RESTROOM%')
  ) then
    raise exception 'Restroom/custodial coverage locations cannot be saved as primary event venues' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_email_relay_command(p_principal text, p_verb text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  cfg public.system_feedback_email_relay_config%rowtype;
  item public.system_feedback_email_intents%rowtype;
  attempt public.system_feedback_email_attempts%rowtype;
  previous public.system_feedback_email_relay_requests%rowtype;
  req uuid;
  arg_hash text;
  result jsonb;
  observed jsonb;
  kind text;
  allowed text[];
  receipt_id uuid;
  proof jsonb;
  proof_key text;
begin
  if p_principal is null or p_principal !~ '^relay:[0-9a-f]{64}$' then
    raise exception using errcode='42501', message='Verified relay principal required';
  end if;
  if p_args is null or jsonb_typeof(p_args) <> 'object' or octet_length(p_args::text)>32768
     or p_args->>'contract_version' is distinct from 'custodial-feedback-relay.v2'
     or jsonb_typeof(p_args->'adapter_schema_sha256') is distinct from 'string'
     or p_args->>'adapter_schema_sha256' !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023', message='Invalid feedback relay contract';
  end if;
  allowed := case p_verb
    when 'status' then array['contract_version']
    when 'claim' then array['contract_version','request_id']
    when 'begin' then array['contract_version','request_id','intent_id','claim_token','claim_generation','envelope_sha256']
    when 'receipt' then array['contract_version','request_id','intent_id','attempt_id','envelope_sha256','observation']
    when 'defer' then array['contract_version','request_id','intent_id','claim_token','claim_generation','reason']
    when 'control' then array['contract_version','request_id','action','reason'] end;
  allowed:=allowed||array['adapter_schema_sha256'];
  if p_verb='control' and p_args->>'action'='resume_preflight_verified' then allowed:=allowed||array['preflight']; end if;
  if allowed is null or exists(select 1 from jsonb_object_keys(p_args) k where not k=any(allowed))
     or exists(select 1 from unnest(allowed) k where not p_args ? k or p_args->k='null'::jsonb) then
    raise exception using errcode='22023', message='Missing or unknown relay arguments';
  end if;
  -- Serialize the small queue's authority transitions and idempotent requests.
  -- Row locks never span a provider call. No external exactly-once assertion.
  select * into strict cfg from public.system_feedback_email_relay_config where singleton for update;
  if p_verb='status' then
    return jsonb_build_object('contract_version','custodial-feedback-relay.v2','server_now',now(),
      'paused',cfg.paused,'pause_reason',cfg.pause_reason,'recipient','eoperle@memphiszoo.org',
      'provider','outlook','provider_account','eoperle@memphiszoo.org',
      'transport_verified',coalesce(cfg.transport_verified_at>=now()-interval '15 minutes'
        and cfg.transport_principal=p_principal and cfg.transport_account='eoperle@memphiszoo.org'
        and cfg.transport_schema_sha256=p_args->>'adapter_schema_sha256',false),
      'transport_verified_at',cfg.transport_verified_at,'adapter_schema_sha256',p_args->>'adapter_schema_sha256',
      'verified_schema_sha256',cfg.transport_schema_sha256,
      'preflight_evidence_source','authenticated_connected_agent_observation',
      'counts',(select coalesce(jsonb_object_agg(state,n),'{}'::jsonb) from
        (select state,count(*) n from public.system_feedback_email_intents group by state) s),
      'protected_attachment_pending',(select count(*) from public.system_feedback_email_intents
        where feedback_snapshot->'image_attachment' is not null and feedback_snapshot->'image_attachment'<>'null'::jsonb),
      'oldest_queued_at',(select min(captured_at) from public.system_feedback_email_intents where state='queued'),
      'last_receipt_at',(select max(recorded_at) from public.system_feedback_email_receipts),
      'recoverable',(select jsonb_build_object('intent_id',id,'attempt_id',attempt_id,
        'envelope_sha256',envelope_sha256,'claim_generation',claim_generation,'claim_until',claim_until,'next_reconcile_at',next_reconcile_at,
        'reconciliation_until',reconciliation_until,'reconciliation_count',reconciliation_count,
        'mode',case when attempt_id is null then 'send' else 'reconcile' end)
        from public.system_feedback_email_intents where claim_principal=p_principal
        and (attempt_id is not null or claim_until>now()) and state not in ('inbox_observed','needs_attention')
        order by captured_at limit 1));
  end if;
  if jsonb_typeof(p_args->'request_id')<>'string' or p_args->>'request_id' !~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception using errcode='22023', message='UUID request_id required';
  end if;
  req := (p_args->>'request_id')::uuid;
  arg_hash := encode(extensions.digest(convert_to(p_args::text,'UTF8'),'sha256'),'hex');
  select * into previous from public.system_feedback_email_relay_requests where request_id=req;
  if found then
    if previous.principal<>p_principal or previous.verb<>p_verb or previous.argument_sha256<>arg_hash then
      raise exception using errcode='23505', message='Relay request_id conflict';
    end if;
    if p_verb='begin' then return previous.result || '{"may_send":false,"replayed":true}'::jsonb; end if;
    if p_verb='claim' and previous.result ? 'intent_id' then
      select * into item from public.system_feedback_email_intents where id=(previous.result->>'intent_id')::uuid;
      return previous.result || jsonb_build_object('mode',case when item.attempt_id is null then 'send' else 'reconcile' end,
        'attempt_id',item.attempt_id,'replayed',true);
    end if;
    return previous.result || '{"replayed":true}'::jsonb;
  end if;

  if p_verb='control' then
    if jsonb_typeof(p_args->'reason')<>'string' or length(p_args->>'reason') not between 1 and 300 then
      raise exception using errcode='22023', message='Bounded control reason required';
    end if;
    if p_args->>'action'='pause' then
      update public.system_feedback_email_relay_config set paused=true,pause_reason=p_args->>'reason',updated_at=now();
    elsif p_args->>'action'='prepare_preflight' then
      update public.system_feedback_email_relay_config set paused=true,pause_reason='preflight_pending',
        preflight_challenge_id=gen_random_uuid(),preflight_challenge_nonce=gen_random_uuid(),
        preflight_issued_at=now(),preflight_principal=p_principal,
        preflight_schema_sha256=p_args->>'adapter_schema_sha256',updated_at=now()
        where singleton returning * into cfg;
      result:=jsonb_build_object('ok',true,'paused',true,'challenge_id',cfg.preflight_challenge_id,
        'challenge_nonce',cfg.preflight_challenge_nonce,'issued_at',cfg.preflight_issued_at,
        'expires_at',cfg.preflight_issued_at+interval '5 minutes',
        'adapter_schema_sha256',cfg.preflight_schema_sha256,'provider_account','eoperle@memphiszoo.org');
    elsif p_args->>'action'='resume_preflight_verified' then
      proof:=p_args->'preflight';
      if jsonb_typeof(proof) is distinct from 'object'
        or exists(select 1 from jsonb_object_keys(proof) k where not k=any(array['challenge_id','challenge_nonce',
          'provider_account','profile_observed_at','profile_result_sha256','sent_folder_id','inbox_folder_id',
          'sent_read_at','sent_result_sha256','inbox_read_at','inbox_result_sha256']))
        or exists(select 1 from unnest(array['challenge_id','challenge_nonce','provider_account','profile_observed_at',
          'profile_result_sha256','sent_folder_id','inbox_folder_id','sent_read_at','sent_result_sha256',
          'inbox_read_at','inbox_result_sha256']) k where jsonb_typeof(proof->k) is distinct from 'string') then
        raise exception using errcode='22023',message='Exact typed transport preflight observation required';
      end if;
      if cfg.preflight_challenge_id is null or proof->>'challenge_id' is distinct from cfg.preflight_challenge_id::text
        or proof->>'challenge_nonce' is distinct from cfg.preflight_challenge_nonce::text
        or cfg.preflight_principal is distinct from p_principal
        or cfg.preflight_schema_sha256 is distinct from p_args->>'adapter_schema_sha256'
        or cfg.preflight_issued_at<now()-interval '5 minutes'
        or proof->>'provider_account' is distinct from 'eoperle@memphiszoo.org' then
        raise exception using errcode='55000',message='Transport preflight challenge is stale, foreign or mismatched';
      end if;
      foreach proof_key in array array['profile_result_sha256','sent_result_sha256','inbox_result_sha256'] loop
        if proof->>proof_key !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='Preflight result digest required';end if;
      end loop;
      foreach proof_key in array array['profile_observed_at','sent_read_at','inbox_read_at'] loop
        if proof->>proof_key !~ '(Z|[+-][0-9]{2}:[0-9]{2})$'
          or (proof->>proof_key)::timestamptz<cfg.preflight_issued_at
          or (proof->>proof_key)::timestamptz>now()+interval '30 seconds' then
          raise exception using errcode='22023',message='Preflight requires fresh reads after the server challenge';
        end if;
      end loop;
      if length(proof->>'sent_folder_id') not between 1 and 512 or length(proof->>'inbox_folder_id') not between 1 and 512
        or proof->>'sent_folder_id'=proof->>'inbox_folder_id' then
        raise exception using errcode='22023',message='Distinct exact Sent and Inbox folder identities required';
      end if;
      update public.system_feedback_email_relay_config set paused=false,pause_reason='',
        transport_verified_at=now(),transport_principal=p_principal,transport_account='eoperle@memphiszoo.org',
        transport_schema_sha256=p_args->>'adapter_schema_sha256',preflight_challenge_id=null,
        preflight_challenge_nonce=null,updated_at=now() where singleton;
      -- The immutable request receipt retains bounded observations, not a
      -- cryptographic Microsoft attestation, configuration proof or send result.
      result:=jsonb_build_object('ok',true,'paused',false,'preflight',proof,
        'observer_principal',p_principal,'adapter_schema_sha256',p_args->>'adapter_schema_sha256',
        'evidence_source','authenticated_connected_agent_observation','verified_until',now()+interval '15 minutes');
    else raise exception using errcode='22023', message='Unsupported relay control'; end if;
    result:=coalesce(result,jsonb_build_object('ok',true,'paused',p_args->>'action'='pause'));
  elsif p_verb='claim' then
    -- Persisted due times and fenced observation lease prevent overlapping
    -- minutely polls from burning the budget. No reconciliation permits resend.
    update public.system_feedback_email_intents set state='needs_attention',attention_reason='reconciliation_exhausted'
      where state in ('outcome_unknown','connector_accepted','sent_observed') and reconciliation_count>=5
        and reconciliation_until<=now();
    if exists(select 1 from public.system_feedback_email_intents where claim_principal=p_principal
      and state in ('outcome_unknown','connector_accepted','sent_observed') and reconciliation_until>now()) then
      result:=jsonb_build_object('ok',true,'busy',true,'reason','reconciliation_lease_active');
    else
      select * into item from public.system_feedback_email_intents where claim_principal=p_principal
        and state in ('outcome_unknown','connector_accepted','sent_observed') and reconciliation_count<5
        and coalesce(next_reconcile_at,'-infinity')<=now()
        order by captured_at,id limit 1 for update;
    end if;
    if item.id is not null then
      update public.system_feedback_email_intents set reconciliation_count=reconciliation_count+1,
        reconciliation_token=gen_random_uuid(),reconciliation_until=now()+interval '120 seconds',
        next_reconcile_at=now()+make_interval(secs=>case reconciliation_count
          when 0 then 300 when 1 then 900 when 2 then 1800 when 3 then 3600 else 120 end)
        where id=item.id returning * into item;
    elsif result is null then
      select * into item from public.system_feedback_email_intents where claim_principal=p_principal
        and state='claimed' and claim_until>now() order by captured_at,id limit 1 for update;
      if not found then
        if cfg.paused or cfg.transport_verified_at is null or cfg.transport_verified_at<now()-interval '15 minutes'
          or cfg.transport_principal is distinct from p_principal
          or cfg.transport_schema_sha256 is distinct from p_args->>'adapter_schema_sha256' then
          result:=jsonb_build_object('ok',true,'paused',true,'reason','transport_not_verified_or_paused');
        else
          select * into item from public.system_feedback_email_intents
            where attempt_id is null and (state='queued' or (state='claimed' and claim_until<=now()))
              and next_claim_at<=now()
            order by captured_at,id limit 1 for update skip locked;
          if found then
            update public.system_feedback_email_intents set state='claimed',claim_principal=p_principal,
              claim_token=gen_random_uuid(),claim_generation=claim_generation+1,claim_until=now()+interval '300 seconds'
              where id=item.id returning * into item;
          end if;
        end if;
      end if;
    end if;
    if item.id is not null and result is null then
      result:=jsonb_build_object('ok',true,'intent_id',item.id,'operation_id',item.operation_id,'feedback_id',item.feedback_id,
        'mode',case when item.attempt_id is null then 'send' else 'reconcile' end,'attempt_id',item.attempt_id,
        'request_fingerprint',item.request_fingerprint,'reconciliation_token',item.reconciliation_token,
        'reconciliation_until',item.reconciliation_until,'next_reconcile_at',item.next_reconcile_at,
        'envelope_sha256',item.envelope_sha256,'claim_token',item.claim_token,'claim_generation',item.claim_generation,
        'claim_until',item.claim_until,'provider','outlook','provider_account','eoperle@memphiszoo.org',
        'recipient','eoperle@memphiszoo.org','protected_attachment',(item.feedback_snapshot->'image_attachment' is not null and item.feedback_snapshot->'image_attachment'<>'null'::jsonb),'expected_subject',item.email_subject,'expected_text',item.email_text);
    end if;
    result:=coalesce(result,'{"ok":true,"empty":true}'::jsonb);
  else
    if jsonb_typeof(p_args->'intent_id')<>'string' or p_args->>'intent_id' !~*
      '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception using errcode='22023', message='UUID intent_id required';
    end if;
    select * into strict item from public.system_feedback_email_intents where id=(p_args->>'intent_id')::uuid for update;
    if p_verb in ('begin','defer') then
      if jsonb_typeof(p_args->'claim_generation')<>'number' or p_args->>'claim_generation' !~ '^[1-9][0-9]{0,8}$'
        or jsonb_typeof(p_args->'claim_token')<>'string' then
        raise exception using errcode='22023', message='Invalid claim fence';
      end if;
      if item.claim_principal is distinct from p_principal or item.claim_token::text is distinct from p_args->>'claim_token'
         or item.claim_generation<>(p_args->>'claim_generation')::integer then
        raise exception using errcode='42501', message='Stale or foreign claim';
      end if;
    end if;
    if p_verb='begin' then
      if item.envelope_sha256 is distinct from p_args->>'envelope_sha256' then
        raise exception using errcode='22023', message='Envelope mismatch';
      end if;
      if item.attempt_id is not null then
        result:=jsonb_build_object('ok',true,'may_send',false,'attempt_id',item.attempt_id,'mode','reconcile');
      elsif cfg.paused or cfg.transport_principal is distinct from p_principal or cfg.transport_verified_at is null
        or cfg.transport_verified_at<now()-interval '15 minutes' or item.claim_until<=now() or item.state<>'claimed'
        or cfg.transport_schema_sha256 is distinct from p_args->>'adapter_schema_sha256' then
        raise exception using errcode='55000', message='Send preparation is paused or expired';
      elsif item.feedback_snapshot->'image_attachment' is not null
        and item.feedback_snapshot->'image_attachment'<>'null'::jsonb and (
          item.attachment_verification_state<>'verified'
          or item.attachment_verification_claim_token is distinct from item.claim_token
          or item.attachment_verification_generation is distinct from item.claim_generation
          or item.attachment_verification_source_digest is distinct from public.static_weekly_digest_jsonb(item.feedback_snapshot->'image_attachment')
          or item.attachment_verification_sha256 is null
          or item.attachment_verified_at<now()-interval '60 seconds'
          or not public.feedback_email_attachment_source_matches(item.id)) then
        raise exception using errcode='55000',message='Protected attachment admission is missing or stale';
      else
        insert into public.system_feedback_email_attempts(intent_id,principal,envelope_sha256,claim_generation)
          values(item.id,p_principal,item.envelope_sha256,item.claim_generation) returning * into attempt;
        update public.system_feedback_email_intents set attempt_id=attempt.id,state='outcome_unknown',
          next_reconcile_at=now()+interval '60 seconds' where id=item.id;
        result:=jsonb_build_object('ok',true,'may_send',true,'attempt_id',attempt.id,
          'attempt_generation',1,'provider_generation',1,'envelope_sha256',item.envelope_sha256);
      end if;
    elsif p_verb='defer' then
      if item.attempt_id is not null or item.state<>'claimed' or item.claim_until<=now() then
        raise exception using errcode='55000', message='Only a current pre-begin claim can defer';
      end if;
      if p_args->>'reason' in ('missing_profile','auth_unavailable','configuration_unavailable','attachment_unavailable') then
        update public.system_feedback_email_relay_config set paused=true,pause_reason=p_args->>'reason',updated_at=now();
        update public.system_feedback_email_intents set state='queued',claim_until=null,claim_token=null where id=item.id;
      elsif p_args->>'reason'='transient_preflight' then
        update public.system_feedback_email_intents set preflight_failures=preflight_failures+1,
          state=case when preflight_failures>=2 then 'needs_attention' else 'queued' end,
          next_claim_at=now()+make_interval(secs=>case preflight_failures when 0 then 60 when 1 then 300 else 900 end),
          attention_reason=case when preflight_failures>=2 then 'preflight_retry_exhausted' else null end,
          claim_until=null,claim_token=null where id=item.id;
      else raise exception using errcode='22023', message='Unsupported preflight defer reason'; end if;
      result:=jsonb_build_object('ok',true,'intent_id',item.id,'deferred',true);
    elsif p_verb='receipt' then
      if item.attempt_id is null or item.attempt_id::text is distinct from p_args->>'attempt_id'
         or item.envelope_sha256 is distinct from p_args->>'envelope_sha256' then
        raise exception using errcode='22023', message='Exact attempt and envelope required';
      end if;
      select * into strict attempt from public.system_feedback_email_attempts where id=item.attempt_id;
      if attempt.principal<>p_principal then raise exception using errcode='42501', message='Foreign attempt receipt'; end if;
      observed:=p_args->'observation'; kind:=observed->>'kind';
      if jsonb_typeof(observed)<>'object' or octet_length(observed::text)>16384
        or exists(select 1 from jsonb_object_keys(observed) k where not k=any(array['kind','provider_account','to','cc','bcc',
          'subject','operation_id','feedback_id','request_fingerprint','full_text_matches','folder','provider_message_id',
          'internet_message_id','observed_at','result_sha256','match_count','reconciliation_token']))
        or observed->>'provider_account' is distinct from 'eoperle@memphiszoo.org'
        or observed->'to' is distinct from '["eoperle@memphiszoo.org"]'::jsonb
        or observed->'cc' is distinct from '[]'::jsonb or observed->'bcc' is distinct from '[]'::jsonb
        or observed->>'subject' is distinct from item.email_subject
        or observed->>'operation_id' is distinct from item.operation_id::text
        or observed->>'feedback_id' is distinct from item.feedback_id::text
        or observed->>'request_fingerprint' is distinct from item.request_fingerprint then
        raise exception using errcode='22023', message='Receipt does not bind the fixed envelope';
      end if;
      if kind not in ('connector_accepted','outcome_unknown','sent_observed','inbox_observed','multiple_matching_messages','reconciliation_not_found') or kind is null then
        -- P-01: no reviewed positive-nonacceptance mapping exists yet. Unknown
        -- tool errors/HTTP codes/absence must never create a retry generation.
        raise exception using errcode='22023', message='Unsupported observation; no nonacceptance proof mapping exists';
      end if;
      if kind in ('sent_observed','inbox_observed','multiple_matching_messages') and (
        observed->'full_text_matches' is distinct from 'true'::jsonb
        or jsonb_typeof(observed->'provider_message_id') is distinct from 'string'
        or length(observed->>'provider_message_id') not between 1 and 512
        or (kind<>'multiple_matching_messages' and observed->>'folder' is distinct from case when kind='sent_observed' then 'sent' else 'inbox' end)
        or (kind='multiple_matching_messages' and coalesce(observed->>'folder','') not in ('sent','inbox'))
        or jsonb_typeof(observed->'observed_at') is distinct from 'string') then
        raise exception using errcode='22023', message='Positive mailbox receipt requires exact text, folder and provider message ID';
      end if;
      if kind in ('sent_observed','inbox_observed','multiple_matching_messages') then
        if (observed->>'observed_at')::timestamptz>now()+interval '5 minutes' then
          raise exception using errcode='22023', message='Mailbox observation is in the future';
        end if;
      end if;
      if kind='multiple_matching_messages' and (jsonb_typeof(observed->'match_count') is distinct from 'number'
        or observed->>'match_count' !~ '^[0-9]{1,6}$' or (observed->>'match_count')::integer<2) then
        raise exception using errcode='22023', message='Duplicate observation requires multiple matches';
      end if;
      if kind='reconciliation_not_found' then
        if item.reconciliation_token is null or observed->>'reconciliation_token' is distinct from item.reconciliation_token::text
          or item.reconciliation_until<=now() or jsonb_typeof(observed->'observed_at') is distinct from 'string'
          or jsonb_typeof(observed->'result_sha256') is distinct from 'string'
          or observed->>'result_sha256' !~ '^[0-9a-f]{64}$'
          or (observed->>'observed_at')::timestamptz>now()+interval '30 seconds'
          or (observed->>'observed_at')::timestamptz<item.reconciliation_until-interval '120 seconds' then
          raise exception using errcode='22023',message='Current bounded reconciliation observation required';
        end if;
      end if;
      insert into public.system_feedback_email_receipts(intent_id,attempt_id,principal,observation)
        values(item.id,attempt.id,p_principal,observed) returning id into receipt_id;
      update public.system_feedback_email_intents set
        state=case when kind='inbox_observed' or state='inbox_observed' then 'inbox_observed'
          when kind='multiple_matching_messages' then 'needs_attention'
          when state='needs_attention' then state
          when kind='reconciliation_not_found' and reconciliation_count>=5 then 'needs_attention'
          when kind='sent_observed' or state='sent_observed' then 'sent_observed'
          when kind='connector_accepted' or state='connector_accepted' then 'connector_accepted'
          else 'outcome_unknown' end,
        possible_duplicate=possible_duplicate or kind='multiple_matching_messages',
        attention_reason=case when kind='multiple_matching_messages' then 'multiple_matching_messages'
          when kind='reconciliation_not_found' and reconciliation_count>=5 then 'reconciliation_exhausted' else attention_reason end,
        reconciliation_until=case when kind='reconciliation_not_found' then now() else reconciliation_until end
        where id=item.id;
      result:=jsonb_build_object('ok',true,'receipt_id',receipt_id,'intent_id',item.id,'attempt_id',attempt.id,
        'observer_principal',p_principal,'evidence_source','connected_agent_observation');
    else raise exception using errcode='22023', message='Unsupported relay command'; end if;
  end if;
  insert into public.system_feedback_email_relay_requests(request_id,principal,verb,argument_sha256,result)
    values(req,p_principal,p_verb,arg_hash,result);
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_email_relay_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_table_name = 'system_feedback_email_intents' and tg_op = 'UPDATE' then
    if (to_jsonb(new) - array['state','claim_principal','claim_token','claim_generation','claim_until',
      'attempt_id','preflight_failures','next_claim_at','attention_reason','reconciliation_count','possible_duplicate','next_reconcile_at','reconciliation_token','reconciliation_until','attachment_verification_ticket','attachment_verification_state','attachment_verification_claim_token','attachment_verification_generation','attachment_verification_source_digest','attachment_verification_sha256','attachment_verification_size','attachment_verification_type','attachment_verified_at'])
       = (to_jsonb(old) - array['state','claim_principal','claim_token','claim_generation','claim_until',
      'attempt_id','preflight_failures','next_claim_at','attention_reason','reconciliation_count','possible_duplicate','next_reconcile_at','reconciliation_token','reconciliation_until','attachment_verification_ticket','attachment_verification_state','attachment_verification_claim_token','attachment_verification_generation','attachment_verification_source_digest','attachment_verification_sha256','attachment_verification_size','attachment_verification_type','attachment_verified_at']) then
      return new;
    end if;
  end if;
  raise exception using errcode='23514', message='Feedback email evidence and envelope are immutable';
end;
$function$

CREATE OR REPLACE FUNCTION public.list_device_notification_acknowledgements(p_device_identifier text, p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_requested text := nullif(btrim(coalesce(p_device_identifier,'')), '');
  v_device text;
  v_limit integer := greatest(1, least(coalesce(p_limit,500), 2000));
  v_result jsonb;
begin
  if v_requested is null or length(v_requested) > 200 then
    raise exception 'device_identifier is required and must be at most 200 characters';
  end if;

  select d.device_id into v_device
  from public.devices d
  where d.active = true and upper(btrim(d.device_id)) = upper(v_requested)
  limit 1;

  if v_device is null then
    select d.device_id into v_device
    from public.device_aliases da
    join public.devices d on d.id = da.canonical_device_id and d.active = true
    where da.active = true and upper(btrim(da.alias_identifier)) = upper(v_requested)
    limit 1;
  end if;

  if v_device is null then raise exception 'Active device not found: %', v_requested; end if;

  select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at desc), '[]'::jsonb)
    into v_result
  from (
    select notification_key, notification_type, displayed_at, dismissed_at,
           opened_at, acknowledged_at, updated_at
    from public.device_notification_acknowledgements
    where device_identifier = v_device
      and acknowledged_at is not null
    order by updated_at desc
    limit v_limit
  ) x;

  return jsonb_build_object(
    'device_identifier', v_device,
    'acknowledgements', v_result
  );
end
$function$

CREATE OR REPLACE FUNCTION public.msg_acknowledge_event_device_notification(p_device_identifier text, p_notification_key text, p_notification_type text, p_action text, p_metadata_json jsonb, p_message_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device public.devices%rowtype;
  v_instance public.event_push_instances%rowtype;
  v_log public.events_app_notification_log%rowtype;
  v_linked_user public.msg_users%rowtype;
  v_message public.msg_messages%rowtype;
  v_thread_id uuid;
  v_notification jsonb;
  v_receipt public.msg_receipts%rowtype;
begin
  select * into v_device
  from public.devices d
  where d.active is true
    and upper(btrim(d.device_id))=upper(btrim(coalesce(p_device_identifier,'')))
  for update;
  if v_device.id is null then
    raise exception using errcode='P0002',message='Active canonical device was not found for event acknowledgement';
  end if;

  select i.* into v_instance
  from public.event_push_instances i
  join public.device_auth_credentials c
    on c.credential_id=i.credential_id
   and c.device_id=v_device.id
   and c.confirmed_at is not null
   and c.revoked_at is null
   and c.expires_at>now()
  where i.notification_key=btrim(coalesce(p_notification_key,''))
    and i.device_id=v_device.id
    and i.employee_id=v_device.assigned_employee_id
    and i.assignment_epoch=v_device.assignment_epoch
    and i.state in ('sent','opened')
  for update of i;
  if v_instance.instance_id is null then
    raise exception using errcode='P0002',message='Active event notification was not found for this device assignment';
  end if;

  select * into v_log
  from public.events_app_notification_log l
  where l.event_id=v_instance.event_id
    and l.employee_id=v_instance.employee_id
    and l.notification_kind=v_instance.notification_kind
  for update;

  if v_log.id is not null and v_log.response_message_id is not null then
    if v_log.status<>'sent' or v_log.msg_user_id is null or v_log.thread_id is null then
      raise exception using errcode='23514',message='Authoritative Event-to-Messenger notification linkage is invalid';
    end if;
    select * into v_linked_user
    from public.msg_users u
    where u.id=v_log.msg_user_id
      and u.employee_id=v_instance.employee_id
      and u.is_active is true
    for key share;
    if v_linked_user.id is null or p_user_id is null or p_user_id<>v_linked_user.id then
      raise exception using errcode='42501',message='Server-derived Messenger user does not match the authoritative event notification recipient';
    end if;
    select * into v_message
    from public.msg_messages m
    where m.id=v_log.response_message_id
      and m.thread_id=v_log.thread_id
    for key share;
    if v_message.id is null then
      raise exception using errcode='23514',message='Authoritative Event-to-Messenger response message linkage is invalid';
    end if;
    if p_message_id is not null and p_message_id<>v_message.id then
      raise exception using errcode='23514',message='Provided message id does not match the authoritative event notification link';
    end if;
    v_thread_id:=v_message.thread_id;
    perform public.msg_assert_active_mutable_thread(v_thread_id);
    if not exists (
      select 1 from public.msg_thread_participants p
      where p.thread_id=v_thread_id and p.user_id=v_linked_user.id and p.left_at is null
    ) then
      raise exception using errcode='42501',message='Authoritative event recipient is not an active Messenger participant';
    end if;
    if not exists (
      select 1 from public.msg_receipts r
      where r.message_id=v_message.id and r.user_id=v_linked_user.id
    ) then
      raise exception using errcode='P0002',message='Authoritative event message receipt was not found';
    end if;
  elsif p_message_id is not null then
    raise exception using errcode='23514',message='Provided message id has no authoritative Event-to-Messenger link';
  end if;

  v_notification:=public.ack_device_notification(
    v_device.device_id,v_instance.notification_key,p_notification_type,p_action,p_metadata_json
  );
  if v_message.id is not null then
    v_receipt:=public.msg_acknowledge_message(v_message.id,v_linked_user.id,v_device.device_id);
  end if;
  return v_notification || jsonb_build_object(
    'event_push_instance_id',v_instance.instance_id,
    'message_receipt_id',v_receipt.id,
    'linked_message_id',v_message.id
  );
end
$function$

CREATE OR REPLACE FUNCTION public.msg_memphis_pre_generate_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_body text := coalesce(new.body, '');
  v_lower text := lower(coalesce(new.body, ''));
  v_start_offset integer := 0;
  v_offsets integer[] := array[0];
  v_offset integer;
  v_service_date date;
begin
  if coalesce(new.metadata_json->>'channel', '') <> 'memphis' then
    return new;
  end if;

  if coalesce(new.message_type, '') <> 'text' then
    return new;
  end if;

  if v_lower !~ '(schedule|scheduled|shift|shifts|assigned|assignment|assignments|staff|staffing|working|works|work today|work tomorrow|who cleans|cleans|cleaning|cover|coverage|open area|open areas|open segment|uncovered|unassigned|restroom|restrooms|aquarium|teton|zambezi|expo|courtyard|breezeway|bonobos|cathouse|memmex|splash pad|event center|east admin|west admin|china|primate|pavilion)' then
    return new;
  end if;

  if v_lower ~ '\mtomorrow\M' then
    v_offsets := array[1];
  elsif v_lower ~ '\myesterday\M' then
    v_offsets := array[-1];
  elsif v_lower ~ '(this week|next week|weekly|week schedule|whole week|entire week|all week)' then
    if v_lower ~ 'next week' then
      v_start_offset := 7;
    else
      v_start_offset := 0;
    end if;
    v_offsets := array[
      v_start_offset,
      v_start_offset + 1,
      v_start_offset + 2,
      v_start_offset + 3,
      v_start_offset + 4,
      v_start_offset + 5,
      v_start_offset + 6
    ];
  end if;

  foreach v_offset in array v_offsets loop
    v_service_date := public.sch_service_date(now() + make_interval(days => v_offset));
    perform public.sch_generate_daily_schedule(v_service_date, false);
  end loop;

  return new;
exception when others then
  raise warning 'msg_memphis_pre_generate_schedule failed for message %, error: %', new.id, sqlerrm;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.msg_reject_retired_ops_manager_shared_message_deletion_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op = 'INSERT'
     and exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = new.message_id and t.system_key = 'ops_manager_shared_chat_v1') then
    raise exception using errcode = '23514', message = 'The retired Operations Leadership message state is immutable';
  end if;
  if tg_op = 'UPDATE'
     and (
       exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = old.message_id and t.system_key = 'ops_manager_shared_chat_v1')
       or exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = new.message_id and t.system_key = 'ops_manager_shared_chat_v1')
     ) then
    raise exception using errcode = '23514', message = 'The retired Operations Leadership message state is immutable';
  end if;
  if tg_op = 'DELETE'
     and exists (select 1 from public.msg_messages m join public.msg_threads t on t.id = m.thread_id where m.id = old.message_id and t.system_key = 'ops_manager_shared_chat_v1') then
    raise exception using errcode = '23514', message = 'The retired Operations Leadership message state cannot be deleted';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_reject_retired_ops_manager_shared_thread_evidence_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_old_thread_id uuid;
  v_new_thread_id uuid;
begin
  if tg_op<>'INSERT' then v_old_thread_id:=old.thread_id; end if;
  if tg_op<>'DELETE' then v_new_thread_id:=new.thread_id; end if;
  if exists (
    select 1 from public.msg_threads t
    where t.id in (v_old_thread_id,v_new_thread_id)
      and t.system_key='ops_manager_shared_chat_v1'
  ) then
    raise exception using errcode='23514',message='The retired Operations Leadership conversation evidence is immutable';
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$function$

CREATE OR REPLACE FUNCTION public.msg_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.mz_claim_employee_event_push_delivery(p_job_id uuid, p_lease_token uuid, p_instance_id uuid, p_credential_id uuid, p_assignment_epoch bigint, p_registration_id uuid, p_token_hash text, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_delivery jsonb; v_job public.operational_notification_jobs%rowtype; v_instance public.event_push_instances%rowtype; v_event public.events_app_events%rowtype; v_reason text;
begin
  if p_job_id is null or p_lease_token is null or p_instance_id is null or p_credential_id is null
     or p_assignment_epoch is null or p_assignment_epoch<1 or p_registration_id is null
     or coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='exact event job, lease, recipient, and token generation are required';
  end if;
  v_delivery:=public.mz_resolve_employee_push_delivery(p_credential_id,p_assignment_epoch,p_now);
  if coalesce((v_delivery->>'ok')::boolean,false) is not true then return v_delivery; end if;
  if (v_delivery#>>'{registration,registration_id}')::uuid is distinct from p_registration_id
     or v_delivery#>>'{registration,token_hash}' is distinct from p_token_hash then
    return jsonb_build_object('ok',false,'terminal',true,'reason','push_registration_superseded');
  end if;
  select * into v_job from public.operational_notification_jobs where job_id=p_job_id for update;
  select * into v_instance from public.event_push_instances where instance_id=p_instance_id;
  if v_instance.instance_id is not null then
    select * into v_event from public.events_app_events where id=v_instance.event_id for share;
  end if;
  select * into v_instance from public.event_push_instances where instance_id=p_instance_id for update;
  if v_job.job_id is not null and v_job.job_type='employee_event_push' and v_job.source_id=p_instance_id
     and v_job.status='leased' and v_job.lease_token is not distinct from p_lease_token
     and v_job.leased_until>statement_timestamp() and v_instance.state='sent'
     and v_instance.credential_id=p_credential_id and v_instance.assignment_epoch=p_assignment_epoch
     and v_instance.provider_message_id is not null and v_event.id is not null
     and v_event.revision=v_instance.event_revision then
    return jsonb_build_object('ok',true,'terminal',false,'dispatch_authorized',false,'already_recorded',true,
      'instance_id',p_instance_id,'state','sent','provider_message_id',v_instance.provider_message_id);
  end if;
  v_reason:=case
    when v_job.job_id is null then 'employee_event_push_job_missing'
    when v_job.job_type<>'employee_event_push' or v_job.source_id<>p_instance_id then 'employee_event_push_job_mismatch'
    when v_job.status<>'leased' or v_job.lease_token is distinct from p_lease_token
      or v_job.leased_until is null or v_job.leased_until<=statement_timestamp() then 'employee_event_push_lease_superseded'
    when v_instance.instance_id is null then 'event_push_instance_missing'
    when v_instance.credential_id<>p_credential_id or v_instance.assignment_epoch<>p_assignment_epoch then 'event_push_recipient_superseded'
    when not exists(select 1 from public.mz_event_reminder_schedule(v_instance.event_id,v_instance.event_revision,v_instance.employee_id,v_instance.notification_kind) s
      where s.scheduled_for=v_instance.scheduled_for) then 'event_owner_or_schedule_superseded'
    when v_instance.scheduled_for>p_now then 'event_push_not_due'
    when v_instance.state='leased' and v_instance.dispatch_job_id=p_job_id
      and v_instance.dispatch_lease_token=p_lease_token and v_instance.dispatch_registration_id=p_registration_id
      and v_instance.dispatch_token_hash=p_token_hash then 'event_push_delivery_in_flight'
    when v_instance.state='leased' and v_instance.dispatch_job_id is not null then 'event_push_delivery_outcome_unknown'
    when v_instance.state not in ('pending','failed') then 'event_push_instance_'||v_instance.state
    when v_event.id is null or v_event.revision<>v_instance.event_revision or v_event.status<>'SCHEDULED'
      or v_event.cancelled_at is not null or v_event.archived_at is not null then 'event_or_revision_superseded'
    when v_instance.employee_id is distinct from (v_delivery->>'employee_id')::uuid
      or v_instance.device_id is distinct from (v_delivery->>'device_id')::uuid then 'event_push_recipient_superseded'
    else null
  end;
  if v_reason is not null then
    if v_reason='event_push_not_due' then
      return jsonb_build_object('ok',false,'terminal',false,'defer_finish',true,'dispatch_authorized',false,'reason',v_reason);
    end if;
    if v_reason='event_push_delivery_in_flight' then
      return jsonb_build_object('ok',false,'terminal',false,'defer_finish',true,'dispatch_authorized',false,
        'reason',v_reason,'instance_id',p_instance_id,'state','leased');
    end if;
    update public.event_push_instances set state='cancelled',cancelled_at=coalesce(cancelled_at,p_now),
      last_error=case when v_reason='event_owner_or_schedule_superseded' then 'event_or_assignment_superseded' else v_reason end,updated_at=p_now
    where instance_id=p_instance_id and state in ('pending','leased','failed');
    return jsonb_build_object('ok',false,'terminal',true,'reason',v_reason,'instance_id',p_instance_id);
  end if;
  update public.event_push_instances set state='leased',dispatch_job_id=p_job_id,dispatch_lease_token=p_lease_token,
    dispatch_registration_id=p_registration_id,dispatch_token_hash=p_token_hash,dispatch_started_at=p_now,
    last_error=null,updated_at=p_now
  where instance_id=p_instance_id;
  return jsonb_build_object('ok',true,'terminal',false,'dispatch_authorized',true,'instance_id',p_instance_id,'state','leased');
end
$function$

CREATE OR REPLACE FUNCTION public.mz_cleaning_reminder_cycle(p_form_type text, p_cleaned_at timestamp with time zone, p_overdue_sent_at timestamp with time zone, p_now timestamp with time zone)
 RETURNS TABLE(cycle_base_at timestamp with time zone, cycle_base_evidence text, due_soon_at timestamp with time zone, overdue_at timestamp with time zone, status_code text)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_soon integer;v_overdue integer;
begin
 if p_now is null or not isfinite(p_now) then raise exception 'reminder time is required'; end if;
 if p_cleaned_at is null then return; end if;
 if not isfinite(p_cleaned_at) or p_cleaned_at>p_now then return; end if;
 if p_form_type='restroom' then v_soon:=75;v_overdue:=90;
 elsif p_form_type='exhibit' then v_soon:=195;v_overdue:=210;
 else return; end if;
 cycle_base_at:=p_cleaned_at;cycle_base_evidence:='completed_cleaning';
 if p_overdue_sent_at is not null and isfinite(p_overdue_sent_at)
    and p_overdue_sent_at>=p_cleaned_at and p_overdue_sent_at<=p_now then
   cycle_base_at:=p_overdue_sent_at;cycle_base_evidence:='provider_accepted_overdue';
 end if;
 due_soon_at:=cycle_base_at+make_interval(mins=>v_soon);
 overdue_at:=cycle_base_at+make_interval(mins=>v_overdue);
 status_code:=case when p_now>=overdue_at then 'overdue'
                   when p_now>=due_soon_at then 'due_soon' else null end;
 return next;
end $function$

CREATE OR REPLACE FUNCTION public.mz_get_employee_native_push_delivery_receipt(p_job_id uuid, p_lease_token uuid, p_credential_id uuid, p_assignment_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_job public.operational_notification_jobs%rowtype; v_receipt public.employee_native_push_delivery_receipts%rowtype; v_reason text;
begin
  if p_job_id is null or p_lease_token is null or p_credential_id is null or p_assignment_epoch is null or p_assignment_epoch<1 then
    raise exception using errcode='22023',message='exact native push job lease and assignment recipient are required';
  end if;
  select * into v_job from public.operational_notification_jobs where job_id=p_job_id for update;
  v_reason:=case
    when v_job.job_id is null then 'employee_native_push_job_missing'
    when v_job.job_type<>'employee_native_push' then 'employee_native_push_job_type_mismatch'
    when v_job.status<>'leased' or v_job.lease_token is distinct from p_lease_token
      or v_job.leased_until is null or v_job.leased_until<=statement_timestamp() then 'employee_native_push_lease_superseded'
    when v_job.payload_json->>'credential_id' is distinct from p_credential_id::text
      or v_job.payload_json->>'assignment_epoch' is distinct from p_assignment_epoch::text then 'employee_native_push_recipient_superseded'
    else null
  end;
  if v_reason is not null then return jsonb_build_object('current',false,'terminal',true,'reason',v_reason); end if;
  select * into v_receipt from public.employee_native_push_delivery_receipts where job_id=p_job_id;
  if v_receipt.job_id is not null then
    if v_receipt.job_key<>v_job.job_key or v_receipt.source_id<>v_job.source_id
       or v_receipt.credential_id<>p_credential_id or v_receipt.assignment_epoch<>p_assignment_epoch then
      raise exception using errcode='23514',message='native push delivery receipt is bound to different job inputs';
    end if;
    if v_receipt.delivery_state='prepared' then
      return jsonb_build_object('current',true,'terminal',true,'already_recorded',false,'recorded',false,
        'dispatch_prepared',true,'delivery_outcome_unknown',true,'reason','native_push_delivery_outcome_unknown',
        'prepared_at',v_receipt.prepared_at);
    end if;
    return jsonb_build_object('current',true,'already_recorded',true,'recorded',true,
      'dispatch_prepared',true,'delivery_outcome_unknown',false,
      'provider_message_id',v_receipt.provider_message_id,'delivered_at',v_receipt.delivered_at);
  end if;
  return jsonb_build_object('current',true,'already_recorded',false,'recorded',false);
end
$function$

CREATE OR REPLACE FUNCTION public.mz_prepare_employee_native_push_delivery(p_job_id uuid, p_lease_token uuid, p_credential_id uuid, p_assignment_epoch bigint, p_registration_id uuid, p_token_hash text, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_delivery jsonb; v_job public.operational_notification_jobs%rowtype; v_receipt public.employee_native_push_delivery_receipts%rowtype; v_reason text; v_message_projection jsonb;
begin
  if p_job_id is null or p_lease_token is null or p_credential_id is null or p_assignment_epoch is null or p_assignment_epoch<1
     or p_registration_id is null or coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='exact native push job, recipient, and token generation are required';
  end if;
  -- Same schedule lock as publication, before registration/job row locks.
  -- A publication that wins before preparation must be seen by the validator.
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  v_delivery:=public.mz_resolve_employee_push_delivery(p_credential_id,p_assignment_epoch,p_now);
  if coalesce((v_delivery->>'ok')::boolean,false) is not true then
    return jsonb_build_object('current',false,'dispatch_authorized',false,
      'reason',coalesce(v_delivery->>'reason','employee_push_recipient_superseded'));
  end if;
  if (v_delivery#>>'{registration,registration_id}')::uuid is distinct from p_registration_id
     or v_delivery#>>'{registration,token_hash}' is distinct from p_token_hash then
    return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','push_registration_superseded');
  end if;
  select * into v_job from public.operational_notification_jobs where job_id=p_job_id for update;
  v_reason:=case
    when v_job.job_id is null then 'employee_native_push_job_missing'
    when v_job.job_type<>'employee_native_push' then 'employee_native_push_job_type_mismatch'
    when v_job.status<>'leased' or v_job.lease_token is distinct from p_lease_token
      or v_job.leased_until is null or v_job.leased_until<=statement_timestamp() then 'employee_native_push_lease_superseded'
    when v_job.payload_json->>'credential_id' is distinct from p_credential_id::text
      or v_job.payload_json->>'assignment_epoch' is distinct from p_assignment_epoch::text then 'employee_native_push_recipient_superseded'
    else null
  end;
  if v_reason is not null then
    return jsonb_build_object('current',false,'dispatch_authorized',false,'reason',v_reason);
  end if;
  -- Recheck in THIS transaction, not only the earlier worker RPC. The job
  -- row lock also serializes exact native ACK admission against preparation.
  if v_job.payload_json#>>'{data_json,kind}'='employee_location_status'
     and (v_job.payload_json#>'{data_json,test_delivery}') is distinct from 'true'::jsonb then
    v_delivery:=public.mz_validate_employee_location_reminder(p_job_id,p_lease_token,p_now);
    if coalesce((v_delivery->>'current')::boolean,false) is not true then
      return jsonb_build_object('current',false,'dispatch_authorized',false,
        'reason',coalesce(v_delivery->>'reason','location_reminder_superseded'));
    end if;
  end if;
  select * into v_receipt from public.employee_native_push_delivery_receipts where job_id=p_job_id for update;
  if v_receipt.job_id is not null then
    if v_receipt.job_key<>v_job.job_key or v_receipt.source_id<>v_job.source_id
       or v_receipt.credential_id<>p_credential_id or v_receipt.assignment_epoch<>p_assignment_epoch
       or v_receipt.registration_id<>p_registration_id or v_receipt.token_hash<>p_token_hash then
      return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','native_push_delivery_receipt_input_mismatch');
    end if;
    return jsonb_build_object('current',true,'dispatch_authorized',false,'already_prepared',true,
      'already_recorded',v_receipt.delivery_state='delivered','delivery_state',v_receipt.delivery_state,
      'delivery_outcome_unknown',v_receipt.delivery_state='prepared','reason',
      case when v_receipt.delivery_state='prepared' then 'native_push_delivery_outcome_unknown' else 'native_push_delivery_already_recorded' end,
      'provider_message_id',v_receipt.provider_message_id,'prepared_at',v_receipt.prepared_at,'delivered_at',v_receipt.delivered_at);
  end if;
  if (v_job.payload_json#>>'{data_json,kind}'='employee_message'
       or v_job.job_key like 'employee-message-push:%')
     and (v_job.payload_json#>'{data_json,test_delivery}') is distinct from 'true'::jsonb then
    -- Original prepared/delivered receipts returned above remain untouched.
    -- Keep existing schedule -> registration -> job ordering, then the same
    -- thread lock used by official read/ACK/delete/hide operations.
    declare
      v_message public.msg_messages%rowtype;
      v_thread public.msg_threads%rowtype;
      v_user public.msg_users%rowtype;
      v_message_receipt public.msg_receipts%rowtype;
      v_target record;v_thread_id uuid;v_now timestamptz:=statement_timestamp();
      v_payload jsonb;v_data jsonb;
    begin
      select d.id device_id,d.device_id device_identifier,d.assigned_employee_id employee_id,
       d.assignment_epoch,c.credential_id,c.expires_at credential_expires_at,r.registration_id,r.token_hash
      into v_target from public.devices d
      join public.device_auth_credentials c on c.device_id=d.id and c.credential_id=p_credential_id
      join public.employee_push_registrations r on r.device_id=d.id and r.credential_id=c.credential_id
      join public.employees e on e.id=d.assigned_employee_id and e.active is true
      where d.active is true and d.assignment_epoch=p_assignment_epoch
       and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>v_now
       and r.registration_id=p_registration_id and r.employee_id=d.assigned_employee_id
       and r.assignment_epoch=d.assignment_epoch and r.active is true and r.revoked_at is null
       and r.token_hash=p_token_hash
      for share of d,c,r,e;
      if not found then return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_recipient_superseded');end if;
      v_payload:=v_job.payload_json;v_data:=v_payload->'data_json';
      if jsonb_typeof(v_payload) is distinct from 'object' or jsonb_typeof(v_data) is distinct from 'object'
       or not(v_payload ?& array['credential_id','employee_id','device_id','device_identifier','assignment_epoch','channel_id','title','body','data_json'])
       or v_payload-array['credential_id','employee_id','device_id','device_identifier','assignment_epoch','channel_id','title','body','data_json']<>'{}'::jsonb
       or not(v_data ?& array['kind','notification_type','notification_key','thread_id','message_id','route','sender_name','thread_title'])
       or v_data-array['kind','notification_type','notification_key','thread_id','message_id','route','sender_name','thread_title']<>'{}'::jsonb
       or v_job.job_key is distinct from 'employee-message-push:'||v_job.source_id::text||':'||p_credential_id::text
       or v_payload->>'credential_id' is distinct from p_credential_id::text
       or v_payload->>'employee_id' is distinct from v_target.employee_id::text
       or v_payload->>'device_id' is distinct from v_target.device_id::text
       or v_payload->>'device_identifier' is distinct from v_target.device_identifier
       or jsonb_typeof(v_payload->'assignment_epoch') is distinct from 'number'
       or v_payload->>'assignment_epoch' is distinct from p_assignment_epoch::text
       or v_payload->>'channel_id' is distinct from 'employee-messages'
       or v_data->>'kind' is distinct from 'employee_message'
       or v_data->>'notification_type' is distinct from 'message'
       or v_data->>'message_id' is distinct from v_job.source_id::text
       or v_data->>'notification_key' is distinct from 'message:'||v_job.source_id::text then
       return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_source_binding_invalid');end if;
      select thread_id into v_thread_id from public.msg_messages where id=v_job.source_id;
      -- Official read/ACK/delete/hide mutators share the owning thread row lock.
      -- Read current facts after acquiring it; no stale pre-lock snapshot is used.
      select * into v_thread from public.msg_threads where id=v_thread_id for update;
      if v_thread.id is null or v_thread.is_active is not true
       or v_thread.system_key='ops_manager_shared_chat_v1' then
       return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_thread_stale');end if;
      select * into v_message from public.msg_messages where id=v_job.source_id for share;
      select * into v_user from public.msg_users
       where employee_id=v_target.employee_id and is_active is true for share;
      if v_message.id is null or v_user.id is null or v_message.thread_id is distinct from v_thread.id
       or v_message.is_deleted is not false or v_message.sender_user_id=v_user.id
       or v_message.sent_at is null or v_message.sent_at>v_now
       or v_data->>'thread_id' is distinct from v_thread.id::text
       or v_data->>'route' is distinct from 'messages.html?hub=employee&thread_id='||v_thread.id::text then
       return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_source_stale');end if;
      perform 1 from public.msg_thread_participants
       where thread_id=v_thread.id and user_id=v_user.id and left_at is null for share;
      if not found then return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_membership_stale');end if;
      select * into v_message_receipt from public.msg_receipts
       where message_id=v_message.id and user_id=v_user.id for share;
      if v_message_receipt.message_id is null or v_message_receipt.acknowledged_at is not null then
       return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_acknowledged_or_receipt_missing');end if;
      if exists(select 1 from public.msg_message_deletions where message_id=v_message.id and user_id=v_user.id)
       or exists(select 1 from public.msg_thread_visibility visibility
        where visibility.thread_id=v_thread.id and visibility.user_id=v_user.id
         and (visibility.device_identifier is null
          or upper(btrim(visibility.device_identifier))=upper(btrim(v_target.device_identifier)))
         and coalesce(v_message.sent_at,v_message.created_at)<=visibility.hidden_before) then
       return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_hidden');end if;
      -- Preserve the exact existing producer transformation; do not replace queued
      -- speech with new policy or current display names after a rename.
      if jsonb_typeof(v_payload->'body') is distinct from 'string'
       or v_payload->>'body' is distinct from left(coalesce(nullif(regexp_replace(v_message.body,'[[:space:]]+',' ','g'),''),'New message'),1000)
       or jsonb_typeof(v_payload->'title') is distinct from 'string'
       or jsonb_typeof(v_data->'sender_name') is distinct from 'string'
       or jsonb_typeof(v_data->'thread_title') is distinct from 'string'
       or coalesce(v_payload->>'title','')=''
       or v_payload->>'title' is distinct from v_data->>'sender_name' then
       return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_content_changed');end if;
      -- Lock waits must not extend the original lease/credential validity.
      v_now:=clock_timestamp();
      if v_job.leased_until<=v_now or v_target.credential_expires_at<=v_now then
       return jsonb_build_object('current',false,'dispatch_authorized',false,'reason','message_lease_or_credential_expired');end if;
      v_message_projection:=jsonb_build_object(
       'schema','custodial.employee-message-admission.v1','job_id',v_job.job_id,'job_key',v_job.job_key,
       'lease_token',v_job.lease_token,'source_id',v_job.source_id,'message_id',v_message.id,'thread_id',v_thread.id,
       'recipient_user_id',v_user.id,'employee_id',v_target.employee_id,'device_id',v_target.device_id,
       'device_identifier',v_target.device_identifier,'credential_id',p_credential_id,'assignment_epoch',p_assignment_epoch,
       'registration_id',p_registration_id,'token_hash',p_token_hash,
       'logical_key','message:'||v_message.id::text||':recipient:'||v_user.id::text,
       'source_revision',public.static_weekly_digest_jsonb(jsonb_build_object('message_id',v_message.id,
        'thread_id',v_message.thread_id,'sender_user_id',v_message.sender_user_id,'sent_at',v_message.sent_at,
        'body',v_message.body,'metadata_json',v_message.metadata_json,'recipient_user_id',v_user.id)),
       'payload',v_payload);
    end;
  end if;
  insert into public.employee_native_push_delivery_receipts(
    job_id,job_key,source_id,lease_token,credential_id,assignment_epoch,registration_id,token_hash,delivery_state,prepared_at
  ) values (
    v_job.job_id,v_job.job_key,v_job.source_id,p_lease_token,p_credential_id,p_assignment_epoch,
    p_registration_id,p_token_hash,'prepared',p_now
  ) returning * into v_receipt;
  return jsonb_build_object('current',true,'dispatch_authorized',true,'already_prepared',false,
    'already_recorded',false,'delivery_state','prepared','delivery_outcome_unknown',false,'prepared_at',v_receipt.prepared_at)
    ||case when v_message_projection is null then '{}'::jsonb
      else jsonb_build_object('message_projection',v_message_projection) end;
end
$function$

CREATE OR REPLACE FUNCTION public.mz_preview_event_impact(p_candidate jsonb, p_manager_id uuid, p_event_id uuid, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_current public.events_app_events%rowtype;
  v_candidate jsonb;
  v_recipients jsonb;
  v_total integer;
  v_now timestamptz:=statement_timestamp();
begin
  if p_manager_id is null or not exists(select 1 from public.ops_manager_managers m
    where m.manager_id=p_manager_id and m.active=true and m.revoked_at is null and m.is_system_principal=false
      and m.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]) then
    raise exception using errcode='42501',message='active named manager authority is required for event impact preview';
  end if;
  if jsonb_typeof(p_candidate) is distinct from 'object' then
    raise exception using errcode='22023',message='normalized event candidate is required';
  end if;
  if p_event_id is not null then
    select * into v_current from public.events_app_events e where e.id=p_event_id;
    if not found then raise exception using errcode='P0002',message='event not found'; end if;
    if p_expected_revision is null or p_expected_revision<1 or v_current.revision is distinct from p_expected_revision then
      raise exception using errcode='40901',message='Event changed since this preview. Refresh before saving.';
    end if;
  end if;
  v_candidate:=p_candidate || jsonb_build_object(
    'audience_scope',coalesce(v_current.audience_scope,'assigned_location'),
    'audience_employee_ids',coalesce(to_jsonb(v_current.audience_employee_ids),'[]'::jsonb));
  if v_candidate->>'status'='NEEDS_REVIEW' or v_candidate->>'event_scope'='UNKNOWN' then
    return jsonb_build_object('status','needs_review','projected_at',v_now,'schedule_mutation',false,
      'recipients','[]'::jsonb,'recipient_count',0,'reason','Unresolved venue has no employee reminder or cleaning coverage.');
  end if;
  if v_candidate->>'status'<>'SCHEDULED' or nullif(v_candidate->>'location_group_id','') is null
     or nullif(v_candidate->>'event_date','') is null then
    raise exception using errcode='22023',message='scheduled event date and resolved venue are required for impact preview';
  end if;
  if (public.app_event_place_authority(v_candidate,v_now)->>'admissible')::boolean is not true then
    raise exception using errcode='40901',message='Event venue mapping requires manager review; refresh impact preview.';
  end if;
  with projected as (
    select emp.id employee_id,emp.display_name employee_name,k.kind notification_kind,
      scheduled.reminder_date,scheduled.scheduled_for,
      (select count(distinct d.id)::integer from public.devices d
       join public.device_auth_credentials c on c.device_id=d.id and c.confirmed_at is not null
         and c.revoked_at is null and c.expires_at>v_now
       join public.employee_push_registrations pr on pr.device_id=d.id and pr.credential_id=c.credential_id
         and pr.employee_id=emp.id and pr.assignment_epoch=d.assignment_epoch and pr.active=true and pr.revoked_at is null
       where d.assigned_employee_id=emp.id and d.active=true) registered_phone_count
    from public.employees emp
    cross join (values('three_days_before'::text),('two_days_before'::text),('shift_plus_15'::text)) k(kind)
    cross join lateral public.mz_event_reminder_schedule_candidate(v_candidate,emp.id,k.kind) scheduled
    where emp.active=true
  )
  select count(distinct employee_id)::integer,
    coalesce(jsonb_agg(jsonb_build_object('employee_id',employee_id,'employee_name',employee_name,
      'notification_kind',notification_kind,'reminder_date',reminder_date,'scheduled_for',scheduled_for,
      'registered_phone_count',registered_phone_count,'within_enqueue_horizon',
        (v_candidate->>'event_date')::date between ((v_now at time zone 'America/Chicago')::date-1)
          and ((v_now at time zone 'America/Chicago')::date+60),
      'reminder_date_not_past',reminder_date>=(v_now at time zone 'America/Chicago')::date)
      order by reminder_date,scheduled_for,employee_name,notification_kind),'[]'::jsonb)
    into v_total,v_recipients from projected;
  return jsonb_build_object('status','projected','projected_at',v_now,'schedule_mutation',false,
    'recipient_count',v_total,'recipients',v_recipients,
    'notice','Projection only; staffing is not changed and recipient/phone authority is revalidated before delivery.');
end $function$

CREATE OR REPLACE FUNCTION public.mz_record_employee_event_push_delivery(p_job_id uuid, p_lease_token uuid, p_instance_id uuid, p_credential_id uuid, p_assignment_epoch bigint, p_registration_id uuid, p_token_hash text, p_provider_message_id text, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_delivery jsonb; v_job public.operational_notification_jobs%rowtype; v_instance public.event_push_instances%rowtype; v_event public.events_app_events%rowtype; v_reason text;
begin
  if p_job_id is null or p_lease_token is null or p_instance_id is null or p_credential_id is null or p_assignment_epoch is null or p_assignment_epoch<1
     or p_registration_id is null or coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$'
     or length(btrim(coalesce(p_provider_message_id,''))) not between 1 and 1000 then
    raise exception using errcode='22023',message='exact event, recipient, token generation, and provider result are required';
  end if;
  v_delivery:=public.mz_resolve_employee_push_delivery(p_credential_id,p_assignment_epoch,p_now);
  if coalesce((v_delivery->>'ok')::boolean,false) is not true then
    return jsonb_build_object('current',false,'recorded',false,'reason',coalesce(v_delivery->>'reason','employee_push_recipient_superseded'));
  end if;
  select * into v_job from public.operational_notification_jobs where job_id=p_job_id for update;
  select * into v_instance from public.event_push_instances where instance_id=p_instance_id;
  if v_instance.instance_id is not null then
    select * into v_event from public.events_app_events where id=v_instance.event_id for share;
  end if;
  select * into v_instance from public.event_push_instances where instance_id=p_instance_id for update;
  if v_instance.state='sent' then
    if v_instance.dispatch_job_id=p_job_id and v_instance.dispatch_lease_token=p_lease_token
       and v_instance.credential_id=p_credential_id and v_instance.assignment_epoch=p_assignment_epoch
       and v_instance.dispatch_registration_id=p_registration_id and v_instance.dispatch_token_hash=p_token_hash
       and v_instance.provider_message_id=btrim(p_provider_message_id) then
      return jsonb_build_object('current',true,'already_recorded',true,'recorded',true,
        'instance_id',p_instance_id,'state','sent','provider_message_id',v_instance.provider_message_id);
    end if;
    return jsonb_build_object('current',false,'recorded',false,'reason','event_push_delivery_receipt_input_mismatch');
  end if;
  v_reason:=case
    when v_job.job_id is null then 'employee_event_push_job_missing'
    when v_job.job_type<>'employee_event_push' or v_job.source_id<>p_instance_id then 'employee_event_push_job_mismatch'
    when v_job.status<>'leased' or v_job.lease_token is distinct from p_lease_token
      or v_job.leased_until is null or v_job.leased_until<=statement_timestamp() then 'employee_event_push_lease_superseded'
    when (v_delivery#>>'{registration,registration_id}')::uuid is distinct from p_registration_id
      or v_delivery#>>'{registration,token_hash}' is distinct from p_token_hash then 'push_registration_superseded'
    when v_instance.instance_id is null then 'event_push_instance_missing'
    when v_instance.credential_id<>p_credential_id or v_instance.assignment_epoch<>p_assignment_epoch
      or v_instance.employee_id is distinct from (v_delivery->>'employee_id')::uuid
      or v_instance.device_id is distinct from (v_delivery->>'device_id')::uuid then 'event_push_recipient_superseded'
    when v_instance.state<>'leased' then 'event_push_instance_'||v_instance.state
    when v_instance.dispatch_job_id<>p_job_id or v_instance.dispatch_lease_token<>p_lease_token
      or v_instance.dispatch_registration_id<>p_registration_id or v_instance.dispatch_token_hash<>p_token_hash then 'event_push_dispatch_superseded'
    when v_event.id is null or v_event.revision<>v_instance.event_revision or v_event.status<>'SCHEDULED'
      or v_event.cancelled_at is not null or v_event.archived_at is not null then 'event_or_revision_superseded'
    else null
  end;
  if v_reason is not null then
    update public.event_push_instances set state='cancelled',cancelled_at=coalesce(cancelled_at,p_now),
      last_error=v_reason,updated_at=p_now
    where instance_id=p_instance_id and state in ('pending','leased','failed');
    return jsonb_build_object('current',false,'recorded',false,'reason',v_reason,'instance_id',p_instance_id);
  end if;
  update public.employee_push_registrations
  set last_successful_delivery_at=p_now,last_error=null,updated_at=p_now
  where registration_id=p_registration_id and token_hash=p_token_hash;
  update public.event_push_instances
  set state='sent',sent_at=p_now,provider_message_id=btrim(p_provider_message_id),last_error=null,updated_at=p_now
  where instance_id=p_instance_id;
  return jsonb_build_object('current',true,'already_recorded',false,'recorded',true,
    'instance_id',p_instance_id,'state','sent','provider_message_id',btrim(p_provider_message_id));
end
$function$

CREATE OR REPLACE FUNCTION public.mz_record_employee_native_push_delivery(p_job_id uuid, p_lease_token uuid, p_credential_id uuid, p_assignment_epoch bigint, p_registration_id uuid, p_token_hash text, p_provider_message_id text, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_delivery jsonb; v_job public.operational_notification_jobs%rowtype; v_receipt public.employee_native_push_delivery_receipts%rowtype; v_reason text;
begin
  if p_job_id is null or p_lease_token is null or p_credential_id is null or p_assignment_epoch is null or p_assignment_epoch<1
     or p_registration_id is null or coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$'
     or length(btrim(coalesce(p_provider_message_id,''))) not between 1 and 1000 then
    raise exception using errcode='22023',message='exact native push job, recipient, token generation, and provider result are required';
  end if;
  v_delivery:=public.mz_resolve_employee_push_delivery(p_credential_id,p_assignment_epoch,p_now);
  if coalesce((v_delivery->>'ok')::boolean,false) is not true then
    return jsonb_build_object('current',false,'recorded',false,'reason',coalesce(v_delivery->>'reason','employee_push_recipient_superseded'));
  end if;
  if (v_delivery#>>'{registration,registration_id}')::uuid is distinct from p_registration_id
     or v_delivery#>>'{registration,token_hash}' is distinct from p_token_hash then
    return jsonb_build_object('current',false,'recorded',false,'reason','push_registration_superseded');
  end if;
  select * into v_job from public.operational_notification_jobs where job_id=p_job_id for update;
  v_reason:=case
    when v_job.job_id is null then 'employee_native_push_job_missing'
    when v_job.job_type<>'employee_native_push' then 'employee_native_push_job_type_mismatch'
    when v_job.status<>'leased' or v_job.lease_token is distinct from p_lease_token
      or v_job.leased_until is null or v_job.leased_until<=statement_timestamp() then 'employee_native_push_lease_superseded'
    when v_job.payload_json->>'credential_id' is distinct from p_credential_id::text
      or v_job.payload_json->>'assignment_epoch' is distinct from p_assignment_epoch::text then 'employee_native_push_recipient_superseded'
    else null
  end;
  if v_reason is not null then return jsonb_build_object('current',false,'recorded',false,'reason',v_reason); end if;
  select * into v_receipt from public.employee_native_push_delivery_receipts where job_id=p_job_id for update;
  if v_receipt.job_id is null then
    return jsonb_build_object('current',false,'recorded',false,'reason','native_push_delivery_not_prepared');
  end if;
  if v_receipt.job_key<>v_job.job_key or v_receipt.source_id<>v_job.source_id
     or v_receipt.lease_token<>p_lease_token or v_receipt.credential_id<>p_credential_id
     or v_receipt.assignment_epoch<>p_assignment_epoch or v_receipt.registration_id<>p_registration_id
     or v_receipt.token_hash<>p_token_hash then
    return jsonb_build_object('current',false,'recorded',false,'reason','native_push_delivery_receipt_input_mismatch');
  end if;
  if v_receipt.delivery_state='delivered' then
    if v_receipt.provider_message_id<>btrim(p_provider_message_id) then
      return jsonb_build_object('current',false,'recorded',false,'reason','native_push_delivery_receipt_input_mismatch');
    end if;
    return jsonb_build_object('current',true,'already_recorded',true,'recorded',true,
      'provider_message_id',v_receipt.provider_message_id,'delivered_at',v_receipt.delivered_at);
  end if;
  update public.employee_native_push_delivery_receipts
  set delivery_state='delivered',provider_message_id=btrim(p_provider_message_id),delivered_at=p_now
  where job_id=p_job_id and delivery_state='prepared'
  returning * into v_receipt;
  if v_receipt.job_id is null then
    raise exception using errcode='40001',message='native push delivery preparation changed concurrently';
  end if;
  update public.employee_push_registrations
  set last_successful_delivery_at=p_now,last_error=null,updated_at=p_now
  where registration_id=p_registration_id and token_hash=p_token_hash;
  return jsonb_build_object('current',true,'already_recorded',false,'recorded',true,
    'provider_message_id',v_receipt.provider_message_id,'delivered_at',v_receipt.delivered_at);
end
$function$

CREATE OR REPLACE FUNCTION public.mz_release_employee_native_push_delivery(p_job_id uuid, p_lease_token uuid, p_credential_id uuid, p_assignment_epoch bigint, p_registration_id uuid, p_token_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_job public.operational_notification_jobs%rowtype; v_receipt public.employee_native_push_delivery_receipts%rowtype; v_reason text;
begin
  select * into v_job from public.operational_notification_jobs where job_id=p_job_id for update;
  v_reason:=case
    when v_job.job_id is null then 'employee_native_push_job_missing'
    when v_job.job_type<>'employee_native_push' then 'employee_native_push_job_type_mismatch'
    when v_job.status<>'leased' or v_job.lease_token is distinct from p_lease_token
      or v_job.leased_until is null or v_job.leased_until<=statement_timestamp() then 'employee_native_push_lease_superseded'
    else null
  end;
  if v_reason is not null then return jsonb_build_object('current',false,'released',false,'reason',v_reason); end if;
  select * into v_receipt from public.employee_native_push_delivery_receipts where job_id=p_job_id for update;
  if v_receipt.job_id is null then return jsonb_build_object('current',true,'released',false,'reason','native_push_delivery_not_prepared'); end if;
  if v_receipt.delivery_state<>'prepared' or v_receipt.lease_token<>p_lease_token
     or v_receipt.credential_id<>p_credential_id or v_receipt.assignment_epoch<>p_assignment_epoch
     or v_receipt.registration_id<>p_registration_id or v_receipt.token_hash<>p_token_hash then
    return jsonb_build_object('current',false,'released',false,'reason','native_push_delivery_receipt_input_mismatch');
  end if;
  delete from public.employee_native_push_delivery_receipts where job_id=p_job_id;
  return jsonb_build_object('current',true,'released',true,'job_id',p_job_id);
end
$function$

CREATE OR REPLACE FUNCTION public.mz_resolve_employee_push_delivery(p_credential_id uuid, p_assignment_epoch bigint, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_registration public.employee_push_registrations%rowtype;
  v_credential public.device_auth_credentials%rowtype;
  v_device public.devices%rowtype;
  v_employee_active boolean;
  v_reason text;
begin
  if p_credential_id is null or p_assignment_epoch is null or p_assignment_epoch<1 then
    raise exception using errcode='22023',message='credential and assignment epoch are required';
  end if;

  select * into v_registration
  from public.employee_push_registrations
  where credential_id=p_credential_id and assignment_epoch=p_assignment_epoch
  order by active desc,last_seen_at desc
  limit 1
  for update;

  select * into v_credential from public.device_auth_credentials
   where credential_id=p_credential_id;
  if v_credential.credential_id is not null then
    select * into v_device from public.devices where id=v_credential.device_id;
  end if;
  if v_registration.registration_id is not null then
    select active into v_employee_active from public.employees where id=v_registration.employee_id;
  end if;

  v_reason:=case
    when v_registration.registration_id is null then 'push_registration_missing'
    when v_credential.credential_id is null then 'device_credential_missing'
    when v_credential.revoked_at is not null then 'device_credential_revoked'
    when v_credential.expires_at<=p_now then 'device_credential_expired'
    when v_credential.confirmed_at is null then 'device_credential_unconfirmed'
    when v_registration.active is not true or v_registration.revoked_at is not null then 'push_registration_revoked'
    when v_device.id is null or v_device.id<>v_registration.device_id or v_credential.device_id<>v_registration.device_id then 'device_credential_device_mismatch'
    when v_device.active is not true then 'device_inactive'
    when v_device.assigned_employee_id is null or v_device.assigned_employee_id<>v_registration.employee_id then 'employee_assignment_superseded'
    when v_device.assignment_epoch<>v_registration.assignment_epoch or v_device.assignment_epoch<>p_assignment_epoch then 'assignment_epoch_superseded'
    when v_employee_active is not true then 'employee_inactive'
    else null
  end;

  if v_reason is not null then
    if v_registration.registration_id is not null and (v_registration.active=true or v_registration.revoked_at is null) then
      update public.employee_push_registrations
         set active=false,revoked_at=coalesce(revoked_at,p_now),revoked_reason=v_reason,updated_at=p_now
       where registration_id=v_registration.registration_id;
    end if;
    update public.event_push_instances
       set state='cancelled',cancelled_at=coalesce(cancelled_at,p_now),last_error=v_reason,updated_at=p_now
     where credential_id=p_credential_id and assignment_epoch=p_assignment_epoch and state in ('pending','leased');
    update public.operational_notification_jobs
       set status='dead',completed_at=coalesce(completed_at,p_now),last_error=v_reason,updated_at=p_now
     where job_type in ('employee_event_push','employee_native_push')
       and status in ('pending','leased')
       and payload_json->>'credential_id'=p_credential_id::text
       and payload_json->>'assignment_epoch'=p_assignment_epoch::text
       and (status='pending' or leased_until<p_now);
    return jsonb_build_object('ok',false,'terminal',true,'reason',v_reason);
  end if;

  return jsonb_build_object(
    'ok',true,'checked_at',p_now,
    'registration',to_jsonb(v_registration),
    'credential_id',p_credential_id,
    'device_id',v_registration.device_id,
    'employee_id',v_registration.employee_id,
    'assignment_epoch',v_registration.assignment_epoch
  );
end
$function$

CREATE OR REPLACE FUNCTION public.mz_verified_visit_reminder_cycle(p_form_type text, p_cleaned_at timestamp with time zone, p_checked_at timestamp with time zone, p_now timestamp with time zone)
 RETURNS TABLE(cycle_base_at timestamp with time zone, cycle_base_evidence text, due_soon_at timestamp with time zone, overdue_at timestamp with time zone, status_code text, repeat_index bigint)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_soon integer;v_overdue integer;
begin
 if p_now is null or not isfinite(p_now) then raise exception 'reminder time is required'; end if;
 -- An uncleaned location cannot be armed by a check-only visit.
 if p_cleaned_at is null or not isfinite(p_cleaned_at) or p_cleaned_at>p_now then return; end if;
 if p_form_type='restroom' then v_soon:=75;v_overdue:=90;
 elsif p_form_type='exhibit' then v_soon:=195;v_overdue:=210;
 else return; end if;
 cycle_base_at:=p_cleaned_at;cycle_base_evidence:='completed_cleaning';
 if p_checked_at is not null and isfinite(p_checked_at)
    and p_checked_at>p_cleaned_at and p_checked_at<=p_now then
   cycle_base_at:=p_checked_at;cycle_base_evidence:='verified_check_checkout';
 end if;
 due_soon_at:=cycle_base_at+make_interval(mins=>v_soon);
 overdue_at:=cycle_base_at+make_interval(mins=>v_overdue);
 status_code:=case when p_now>=overdue_at then 'overdue'
                   when p_now>=due_soon_at then 'due_soon' else null end;
 repeat_index:=case when p_now>=overdue_at
   then floor(extract(epoch from(p_now-overdue_at))/300)::bigint else 0 end;
 return next;
end $function$

CREATE OR REPLACE FUNCTION public.operational_day_start(p_ref timestamp with time zone DEFAULT now())
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_start_hour integer := public.get_setting_int('operational_day_start_hour', 4);
  v_local timestamp;
begin
  v_local := timezone('America/Chicago', p_ref);

  return (
    date_trunc('day', v_local - make_interval(hours => v_start_hour))
    + make_interval(hours => v_start_hour)
  ) at time zone 'America/Chicago';
end;
$function$

CREATE OR REPLACE FUNCTION public.ops_manager_enqueue_lunch_delivery_failure(p_employee_job_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_job public.operational_notification_jobs%rowtype;
  v_inserted integer := 0;
  v_data jsonb;
  v_event text;
  v_device text;
  v_receipt public.employee_native_push_delivery_receipts%rowtype;
  v_delivery_evidence text;
  v_title text;
  v_body text;
begin
  if p_employee_job_id is null then
    return jsonb_build_object('ok',false,'enqueued',0,'reason','employee_job_id_required');
  end if;

  select * into v_job
  from public.operational_notification_jobs
  where job_id=p_employee_job_id;

  if v_job.job_id is null then
    return jsonb_build_object('ok',false,'enqueued',0,'reason','employee_job_missing');
  end if;

  v_data:=coalesce(v_job.payload_json->'data_json','{}'::jsonb);
  if v_job.job_type is distinct from 'employee_native_push'
     or v_job.status is distinct from 'dead'
     or v_data->>'kind' is distinct from 'employee_lunch_coverage'
     or v_data->>'notification_type' is distinct from 'lunch_coverage' then
    return jsonb_build_object('ok',true,'enqueued',0,'ignored','not_terminal_lunch_coverage');
  end if;

  v_event:=case when v_data->>'event' in ('start','end') then v_data->>'event' else 'coverage' end;
  v_device:=coalesce(nullif(btrim(v_job.payload_json->>'device_identifier'),''),'assigned custodial phone');

  -- A terminal worker state does not prove that the provider rejected a send.
  -- Preserve prepared/accepted evidence without inventing a handset receipt.
  select * into v_receipt from public.employee_native_push_delivery_receipts
  where job_id=v_job.job_id;
  v_delivery_evidence:=case
    when v_receipt.job_id is null then 'not_dispatched_or_rejected'
    when v_receipt.job_key is distinct from v_job.job_key
      or v_receipt.source_id is distinct from v_job.source_id
      or v_receipt.credential_id::text is distinct from v_job.payload_json->>'credential_id'
      or v_receipt.assignment_epoch::text is distinct from v_job.payload_json->>'assignment_epoch'
      then 'receipt_binding_unverified'
    when v_receipt.delivery_state='delivered' then 'provider_accepted'
    else 'provider_outcome_unknown'
  end;
  if v_delivery_evidence='not_dispatched_or_rejected' then
    v_title:='Lunch coverage notification failed';
    v_body:='A lunch coverage '||v_event||' notification could not be delivered to '||v_device||
      '. Review coverage and contact the custodian if needed.';
  elsif v_delivery_evidence='provider_accepted' then
    v_title:='Lunch coverage delivery needs review';
    v_body:='The notification service accepted a lunch coverage '||v_event||
      ' notification for '||v_device||', but delivery recording needs review. Confirm coverage with the custodian.';
  else
    v_title:='Lunch coverage delivery unconfirmed';
    v_body:='Delivery of a lunch coverage '||v_event||' notification to '||v_device||
      ' could not be confirmed. Review coverage and contact the custodian if needed.';
  end if;

  insert into public.ops_manager_notification_queue(
    job_key,credential_id,manager_id,notification_type,source_id,title,body,data_json,available_at
  )
  select
    'manager-lunch-delivery-failure:'||v_job.job_id::text||':'||pd.credential_id::text,
    pd.credential_id,
    pd.manager_id,
    'lunch_delivery_failure',
    v_job.job_id,
    v_title,
    left(v_body,1000),
    jsonb_build_object(
      'kind','lunch_delivery_failure',
      'route','schedule.html',
      'employee_job_id',v_job.job_id::text,
      'notification_key',coalesce(v_data->>'notification_key',''),
      'lunch_event',v_event,
      'service_date',coalesce(v_data->>'service_date',''),
      'loan_id',coalesce(v_data->>'loan_id',''),
      'device_identifier',v_device,
      'employee_id',coalesce(v_job.payload_json->>'employee_id',''),
      'terminal_delivery_failure',v_delivery_evidence='not_dispatched_or_rejected',
      'delivery_evidence',v_delivery_evidence,
      'device_receipt_status','not_evaluated'
    ),
    p_now
  from public.ops_manager_push_devices pd
  join public.ops_manager_trusted_devices td
    on td.credential_id=pd.credential_id and td.manager_id=pd.manager_id
  join public.ops_manager_managers manager on manager.manager_id=pd.manager_id
  where pd.enabled=true and pd.revoked_at is null
    and td.revoked_at is null and td.expires_at>p_now
    and manager.active=true and manager.revoked_at is null
    and manager.is_system_principal=false
  on conflict(job_key) do nothing;
  get diagnostics v_inserted=row_count;

  return jsonb_build_object('ok',true,'enqueued',v_inserted,'employee_job_id',v_job.job_id);
end
$function$

CREATE OR REPLACE FUNCTION public.ops_manager_finish_notification_job(p_queue_id uuid, p_lease_token uuid, p_push_device_id uuid, p_fcm_token_sha256 text, p_succeeded boolean, p_provider_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_retry_seconds integer DEFAULT 30, p_delivery_outcome_unknown boolean DEFAULT false)
 RETURNS ops_manager_notification_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_row public.ops_manager_notification_queue%rowtype; v_job_current boolean; v_recipient_current boolean; v_dispatch_matches boolean;
begin
  if p_succeeded and p_delivery_outcome_unknown then raise exception using errcode='22023',message='a successful manager push cannot have an unknown provider outcome'; end if;
  select * into v_row from public.ops_manager_notification_queue where queue_id=p_queue_id and status='leased' and lease_token=p_lease_token for update;
  if v_row.queue_id is null then raise exception using errcode='P0002',message='Notification job lease was not found'; end if;
  v_dispatch_matches:=v_row.dispatch_started_at is not null
    and v_row.dispatch_lease_token=p_lease_token and v_row.dispatch_push_device_id=p_push_device_id
    and v_row.dispatch_fcm_token_sha256=p_fcm_token_sha256;
  if (p_succeeded or p_delivery_outcome_unknown or v_row.dispatch_started_at is not null) and not v_dispatch_matches then
    raise exception using errcode='22023',message='manager notification dispatch preparation does not match the exact lease and provider target';
  end if;
  v_recipient_current:=public.custodial_ops_manager_notification_binding_is_current(
    p_push_device_id,v_row.credential_id,v_row.manager_id,p_fcm_token_sha256,now()
  );
  v_job_current:=v_recipient_current;
  if v_row.notification_type='event_digest' then
    v_job_current:=v_job_current and public.app_event_manager_digest_is_current(v_row.data_json,now());
  end if;
  if v_row.notification_type='location_digest' then
    v_job_current:=v_job_current and public.custodial_ops_manager_location_digest_is_current(v_row.credential_id,v_row.data_json->>'location_fingerprint');
  end if;
  if p_delivery_outcome_unknown then
    update public.ops_manager_notification_queue set status='failed',completed_at=now(),leased_until=null,lease_token=null,worker_id=null,
      provider_message_id=null,last_error=left('provider delivery outcome unknown: '||coalesce(p_error,'FCM response was not authoritative'),2000),updated_at=now()
    where queue_id=p_queue_id returning * into v_row;
  elsif not v_job_current then
    update public.ops_manager_notification_queue set status='cancelled',completed_at=now(),leased_until=null,lease_token=null,worker_id=null,
      last_error=case when not v_recipient_current then 'notification recipient authority is no longer current' when v_row.notification_type='location_digest' then 'location dashboard state has changed' else 'event occurrence is no longer upcoming' end,
      updated_at=now() where queue_id=p_queue_id returning * into v_row;
  elsif p_succeeded then
    update public.ops_manager_notification_queue set status='sent',sent_at=now(),completed_at=now(),leased_until=null,lease_token=null,worker_id=null,
      provider_message_id=nullif(left(coalesce(p_provider_message_id,''),500),''),last_error=null,updated_at=now()
    where queue_id=p_queue_id returning * into v_row;
    update public.ops_manager_notification_state set last_sent_at=now(),updated_at=now()
    where credential_id=v_row.credential_id and state_key=case when v_row.notification_type='location_digest' then 'location_digest' else '__none__' end;
  else
    update public.ops_manager_notification_queue set status=case when attempts>=max_attempts then 'failed' else 'pending' end,
      available_at=case when attempts>=max_attempts then available_at else now()+make_interval(secs=>greatest(15,least(coalesce(p_retry_seconds,30),86400))) end,
      completed_at=case when attempts>=max_attempts then now() else null end,leased_until=null,lease_token=null,worker_id=null,
      dispatch_lease_token=null,dispatch_push_device_id=null,dispatch_fcm_token_sha256=null,dispatch_started_at=null,
      last_error=left(coalesce(p_error,'Notification delivery failed'),2000),updated_at=now() where queue_id=p_queue_id returning * into v_row;
  end if;
  return v_row;
end $function$

CREATE OR REPLACE FUNCTION public.ops_manager_prepare_notification_dispatch(p_queue_id uuid, p_lease_token uuid, p_push_device_id uuid, p_fcm_token_sha256 text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_row public.ops_manager_notification_queue%rowtype;
begin
  if p_queue_id is null or p_lease_token is null or p_push_device_id is null
     or coalesce(p_fcm_token_sha256,'') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='exact manager notification lease, device, and token generation are required';
  end if;
  select * into v_row from public.ops_manager_notification_queue
  where queue_id=p_queue_id and status='leased' and lease_token=p_lease_token and leased_until>=now() for update;
  if v_row.queue_id is null or v_row.dispatch_started_at is not null then return false; end if;
  if public.ops_manager_notification_job_is_current(
    p_queue_id,p_lease_token,p_push_device_id,p_fcm_token_sha256
  ) is not true then return false; end if;
  update public.ops_manager_notification_queue set
    dispatch_lease_token=p_lease_token,dispatch_push_device_id=p_push_device_id,
    dispatch_fcm_token_sha256=p_fcm_token_sha256,dispatch_started_at=now(),updated_at=now()
  where queue_id=p_queue_id;
  return true;
end $function$

CREATE OR REPLACE FUNCTION public.place_bridge_overlay(p_at timestamp with time zone, p_proposed jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source jsonb:=public.place_bridge_source(); sha text; v jsonb; b jsonb; latest jsonb; s jsonb; head jsonb; p uuid;
 status text; why text; output jsonb:='[]'; item jsonb; other jsonb; ambiguous boolean;
begin
 if p_at is null or not isfinite(p_at) then raise exception using errcode='22023',message='Finite overlay clock required'; end if;
 if octet_length(source::text)>1048576 then raise exception using errcode='54000',message='Catalog exceeds bounded bridge source manifest'; end if;
 sha:=public.place_bridge_sha(source);
 for v in select value from jsonb_array_elements(source->'event_venues') loop
  select to_jsonb(x) into latest from public.custodial_place_bridge_versions x where legacy_kind='event_venue' and legacy_id=(v->>'id')::uuid order by revision desc limit 1;
  select to_jsonb(x) into b from public.custodial_place_bridge_versions x where legacy_kind='event_venue' and legacy_id=(v->>'id')::uuid and effective_at<=p_at order by effective_at desc,revision desc limit 1;
  if p_proposed->>'legacy_id'=v->>'id' then b:=p_proposed; end if;
  s:=null;head:=null;p:=null;why:=null;status:='UNMAPPED';
  if b is not null then
   p:=(b->>'place_id')::uuid;s:=public.place_lifecycle_snapshot(p,p_at);
   select snapshot||jsonb_build_object('revision',revision,'effective_at',effective_at) into head from public.custodial_place_versions where place_id=p order by revision desc limit 1;
   if b->'active'='false'::jsonb then status:='INACTIVE';why:='bridge_inactive';
   elsif b->>'source_sha256' is distinct from sha then status:='NEEDS_REVIEW';why:='legacy_source_drift';
   elsif v->'active'<>'true'::jsonb or v->'eligible_event_venue'<>'true'::jsonb then status:='NEEDS_REVIEW';why:='legacy_venue_not_active_eligible';
   elsif s is null or s->'active'<>'true'::jsonb or s->'event_eligible'<>'true'::jsonb or s->>'cleaning_mode'<>'NEVER_CLEAN'
    or s->>'merged_into' is not null or exists(select 1 from public.custodial_places where place_id=p and physical_location_id is not null) then
    status:='NEEDS_REVIEW';why:='canonical_target_not_active_event_only';
   else status:='MAPPED';end if;
  end if;
  output:=output||jsonb_build_array(jsonb_build_object('venue_id',v->>'id','mapping_status',status,'review_reason',why,
   'bridge_revision',b->'revision','bridge_effective_at',b->'effective_at','bridge_latest_revision',latest->'revision','bridge_latest_effective_at',latest->'effective_at',
   'canonical_place_id',p,'canonical_revision',s->'revision','canonical_effective_at',s->'effective_at','canonical_latest_revision',head->'revision','canonical_latest_effective_at',head->'effective_at',
   'display_name',case when status='MAPPED' then s->'display_name' else v->'display_name' end,
   'aliases',case when status='MAPPED' then s->'aliases' else v->'aliases' end,'raw_legacy',v,
   'source_drift',b is not null and b->>'source_sha256' is distinct from sha,
   'cleaning_mode',case when b is not null then 'NEVER_CLEAN' else null end,
   'event_eligible',status='MAPPED' or (status='UNMAPPED' and v->'active'='true'::jsonb and (v->'eligible_event_venue'='true'::jsonb or v->'eligible_event_scope'='true'::jsonb)),
   'capability_authority',case when status='UNMAPPED' then 'LEGACY_UNMAPPED' else 'CANONICAL_EVENT_ONLY' end,
   'schedule_eligible',case when status='UNMAPPED' then null else false end,'staffing_eligible',case when status='UNMAPPED' then null else false end,
   'nfc_eligible',case when status='UNMAPPED' then null else false end,'overdue_eligible',case when status='UNMAPPED' then null else false end));
 end loop;
 -- A mapped alias may not steal an active eligible legacy venue alias.
 for item in select value from jsonb_array_elements(output) where value->>'mapping_status'='MAPPED' loop
  ambiguous:=false;
  for other in select value from jsonb_array_elements(output) where value->>'venue_id'<>item->>'venue_id'
   and (value->>'mapping_status'='MAPPED' or (value->'raw_legacy'->'active'='true'::jsonb and (value->'raw_legacy'->'eligible_event_venue'='true'::jsonb or value->'raw_legacy'->'eligible_event_scope'='true'::jsonb))) loop
   if exists(select 1 from jsonb_array_elements_text((item->'aliases')||jsonb_build_array(item->'display_name')) a
    join jsonb_array_elements_text((other->'aliases')||jsonb_build_array(other->'display_name')) z
    on public.place_lifecycle_normalize(a.value)=public.place_lifecycle_normalize(z.value)) then ambiguous:=true;end if;
  end loop;
  if ambiguous then output:=(select jsonb_agg(case when x->>'venue_id'=item->>'venue_id' then x||'{"mapping_status":"NEEDS_REVIEW","review_reason":"alias_conflict","event_eligible":false}'::jsonb else x end order by ordinal)
   from jsonb_array_elements(output) with ordinality t(x,ordinal));end if;
 end loop;
 return jsonb_build_object('as_of',p_at,'source_sha256',sha,'venues',output,'physical_and_group_cutover',false);
end $function$

CREATE OR REPLACE FUNCTION public.place_lifecycle_assert_aliases(p_from timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare at_time timestamptz; collision text; id uuid;
begin
 -- Check the whole affected future timeline, not just today's aliases.
 for at_time in select p_from union select effective_at from public.custodial_place_versions where effective_at>=p_from loop
  for id in select place_id from public.custodial_places loop
   perform public.place_lifecycle_root(id,at_time);
  end loop;
  select key into collision from (
   select public.place_lifecycle_normalize(a.value) key,count(distinct public.place_lifecycle_root(p.place_id,at_time)) n
   from public.custodial_places p
   cross join lateral public.place_lifecycle_snapshot(p.place_id,at_time) s
   cross join lateral jsonb_array_elements_text(s->'aliases') a
   where public.place_lifecycle_root(p.place_id,at_time) is not null
   group by public.place_lifecycle_normalize(a.value)
  ) aliases where n>1 limit 1;
  if collision is not null then raise exception using errcode='23514',message='Alias conflicts with another canonical place: '||collision; end if;
 end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.place_lifecycle_root(p_place uuid, p_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare id uuid:=p_place; seen uuid[]:='{}'; s jsonb;
begin
 loop
  if id=any(seen) or cardinality(seen)>=32 then raise exception using errcode='23514',message='Place merge cycle'; end if;
  seen:=array_append(seen,id); s:=public.place_lifecycle_snapshot(id,p_at);
  if s is null then return null; end if;
  if s->>'merged_into' is null then return case when s->'active'='true'::jsonb then id else null end; end if;
  id:=(s->>'merged_into')::uuid;
 end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.place_operational_assert_accepted_names(p_source uuid, p_date date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source jsonb;a jsonb;loc jsonb;expected jsonb;record jsonb;override jsonb:='[]';at_time timestamptz;primary_name text;
begin
 -- Empty/unmapped catalogs keep the existing authority path. This does not
 -- enroll, activate or replace any source just because the registry is empty.
 if not exists(select 1 from public.custodial_place_operational_receipts) and not exists(select 1 from public.custodial_place_operational_commands where source_id=p_source) then return;end if;
 select canonical_source into source from public.static_weekly_authority_source_documents where source_id=p_source;
 select p.selection into override from public.custodial_place_operational_commands c join public.custodial_place_operational_previews p using(preview_id)
  where c.source_id=p_source and c.owner_xid=pg_current_xact_id() and not exists(select 1 from public.custodial_place_operational_receipts where operation_id=c.operation_id);
 override:=coalesce(override,'[]');at_time:=(p_date+time '04:00') at time zone 'America/Chicago';
 for a in select value from jsonb_array_elements(source#>'{version,assignments}') loop
  for loc in select value from jsonb_array_elements(coalesce(a->'includedLocations','[]')) loop
   select value into expected from jsonb_array_elements(override) where value->>'legacy_kind'='physical_location' and value->>'legacy_id'=loc->>'locationId';
   expected:=coalesce(expected,public.place_operational_accepted_record('physical_location',(loc->>'locationId')::uuid,at_time));
   if expected is not null and loc->>'locationNameSnapshot' is distinct from expected#>>'{effective_snapshot,display_name}' then
    raise exception using errcode='55000',message='Publication would silently replace an accepted physical display snapshot';end if;
  end loop;
  primary_name:=null;
  -- Prefer an explicitly accepted group routing relation, not a human-name
  -- join or an accidental physical/group code collision.
  for record in select coalesce((select value from jsonb_array_elements(override) where value->>'legacy_kind'='location_group' and value->>'legacy_id'=g.id::text),
   public.place_operational_accepted_record('location_group',g.id,at_time)) from public.location_groups g where g.group_code=a->>'locationCodeSnapshot' loop
   if record is not null and (a->>'locationId'=record->>'legacy_id' or exists(select 1 from jsonb_array_elements(record#>'{raw_legacy,memberships}') m where m->>'location_id'=a->>'locationId')) then
    primary_name:=record#>>'{effective_snapshot,display_name}';end if;
  end loop;
  if primary_name is null and not exists(select 1 from public.location_groups g join public.location_group_memberships m on m.location_group_id=g.id
   where g.group_code=a->>'locationCodeSnapshot' and m.location_id=(a->>'locationId')::uuid) then
   select value into expected from jsonb_array_elements(override) where value->>'legacy_kind'='physical_location' and value->>'legacy_id'=a->>'locationId';
   expected:=coalesce(expected,public.place_operational_accepted_record('physical_location',(a->>'locationId')::uuid,at_time));
   if expected#>>'{raw_legacy,location_code}'=a->>'locationCodeSnapshot' then primary_name:=expected#>>'{effective_snapshot,display_name}';end if;
  end if;
  if primary_name is not null and a->>'locationNameSnapshot' is distinct from primary_name then
   raise exception using errcode='55000',message='Publication would silently replace an accepted routing display snapshot',
    detail=jsonb_build_object('original_location_id',a->>'locationId','original_code',a->>'locationCodeSnapshot','expected_display',primary_name,'candidate_display',a->>'locationNameSnapshot')::text;end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.place_operational_assert_source_use(p_source uuid, p_manager uuid, p_key text, p_stage text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c public.custodial_place_operational_commands%rowtype;begin
 select * into c from public.custodial_place_operational_commands where source_id=p_source;
 if not found or exists(select 1 from public.custodial_place_operational_receipts where operation_id=c.operation_id) then return;end if;
 if c.owner_xid<>pg_current_xact_id() or c.manager_id<>p_manager or p_stage not in('draft','publish')
  or p_key is distinct from 'place:'||c.operation_id||':'||p_stage then
  raise exception using errcode='42501',message='Unaccepted Place source is limited to its exact transaction and child operation';end if;
end $function$

CREATE OR REPLACE FUNCTION public.place_operational_assert_unchanged_draft(p_version uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c public.custodial_place_operational_commands%rowtype;p public.custodial_place_operational_previews%rowtype;old_version uuid;old_facts jsonb;new_facts jsonb;begin
 select c1.* into c from public.custodial_place_operational_commands c1 join public.weekly_schedule_versions v on v.authority_source_id=c1.source_id where v.version_id=p_version;
 if not found or exists(select 1 from public.custodial_place_operational_receipts where operation_id=c.operation_id) then return;end if;
 select * into strict p from public.custodial_place_operational_previews where preview_id=c.preview_id;
 select version_id into strict old_version from public.weekly_schedule_publications where publication_id=p.source_publication_id;
 -- Compare the ACTUALLY ACCEPTED assignment decisions, not merely the input's
 -- preferred owner. Stable work/day identities survive new version UUIDs.
 select jsonb_agg(to_jsonb(a)-array['assignment_id','version_id','location_name_snapshot','payload_json','authority_facts_json','content_digest','created_at'] order by day_of_week,work_id)
  into old_facts from public.weekly_schedule_slot_assignments a where version_id=old_version;
 select jsonb_agg(to_jsonb(a)-array['assignment_id','version_id','location_name_snapshot','payload_json','authority_facts_json','content_digest','created_at'] order by day_of_week,work_id)
  into new_facts from public.weekly_schedule_slot_assignments a where version_id=p_version;
 if old_facts is distinct from new_facts then raise exception using errcode='55000',message='Name-only compiler decision changed accepted ownership, work, windows, effort or restrictions';end if;
 select jsonb_agg(to_jsonb(a)-array['availability_id','version_id','content_digest','created_at'] order by slot_id,day_of_week) into old_facts
  from public.weekly_schedule_slot_availability a where version_id=old_version;
 select jsonb_agg(to_jsonb(a)-array['availability_id','version_id','content_digest','created_at'] order by slot_id,day_of_week) into new_facts
  from public.weekly_schedule_slot_availability a where version_id=p_version;
 if old_facts is distinct from new_facts then raise exception using errcode='55000',message='Name-only compiler decision changed accepted people, workdays, shifts or lunches';end if;
end $function$

CREATE OR REPLACE FUNCTION public.place_source_apply(p_request uuid, p_manager uuid, p_preview uuid, p_at timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v public.custodial_place_source_previews%rowtype;a public.custodial_place_source_admissions%rowtype;p jsonb;rev integer;targetrev integer;
begin
 perform public.custodial_assert_manager(p_manager);
 select * into v from public.custodial_place_source_previews where preview_id=p_preview;
 select * into a from public.custodial_place_source_admissions where request_id=p_request;
 p:=v.proposal;
 if v.actor_manager_id is distinct from p_manager or a.actor_manager_id is distinct from p_manager or a.preview_id is distinct from p_preview
  or a.transaction_id is distinct from txid_current() or a.argument_sha256 is distinct from public.place_bridge_sha(jsonb_build_array(p_request,p_manager,p_preview,p_at,p))
  or a.source_sha256 is distinct from public.place_bridge_sha(public.place_source_manifest())
  or a.dependency_sha256 is distinct from public.place_bridge_sha(public.place_source_dependencies()) then raise exception using errcode='42501',message='Private current-transaction full-argument admission required';end if;
 select max(revision) into rev from public.custodial_place_versions where place_id=(p->>'place_id')::uuid;
 select max(revision) into targetrev from public.custodial_place_versions where place_id=(p->>'target_place_id')::uuid;
 if coalesce(rev,0)<>a.source_head or coalesce(targetrev,0)<>a.target_head then raise exception using errcode='40001',message='Canonical source/target heads changed';end if;
 if p->>'action' in('add','enroll') then
  if p->>'action'='add' then
   if p->>'legacy_kind'='physical_location' then
    insert into public.locations(id,location_code,location_name,location_type,active) values((p->>'legacy_id')::uuid,p->'payload'->>'legacy_code',p->'canonical_snapshot'->>'display_name',p->'payload'->>'location_type',false);
   else
    insert into public.location_groups(id,group_code,group_name,active) values((p->>'legacy_id')::uuid,p->'payload'->>'legacy_code',p->'canonical_snapshot'->>'display_name',false);
    -- Legacy membership has UNIQUE(location_id). Proposed full members remain
    -- private setup metadata; no physical member is stolen from its group.
   end if;
  end if;
  insert into public.custodial_places(place_id,canonical_code,physical_location_id) values((p->>'place_id')::uuid,p->>'canonical_code',
   case when p->>'legacy_kind'='physical_location' then (p->>'legacy_id')::uuid else null end);
 end if;
 insert into public.custodial_place_versions(place_id,revision,request_id,actor_manager_id,action,reason,effective_at,argument_sha256,snapshot)
  values((p->>'place_id')::uuid,coalesce(rev,0)+1,p_request,p_manager,'source_'||(p->>'action'),p->>'reason',p_at,a.argument_sha256,p->'canonical_snapshot');
 perform public.place_lifecycle_assert_aliases(p_at);return coalesce(rev,0)+1;
end $function$

CREATE OR REPLACE FUNCTION public.place_source_locks()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 -- Common recurring authority FIRST, then Place, then catalog/dependencies.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform 1 from public.custodial_place_control where singleton for update;
 lock table public.event_area_aliases,public.event_venues,public.location_group_aliases,public.location_group_memberships,public.location_groups,public.locations in share mode;
 lock table public.weekly_schedule_publications,public.custodial_offline_actor_contexts in share mode;
end $function$

CREATE OR REPLACE FUNCTION public.app_apply_operational_command(p_command text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_command text := nullif(btrim(coalesce(p_command, '')), '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_id uuid;
begin
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception using errcode='22023', message='operational command payload must be an object';
  end if;
  if v_command = 'public_rate_limit' then
    if coalesce(v_payload->>'bucket_key','') !~ '^[0-9a-f]{64}$' or length(coalesce(v_payload->>'scope','')) not between 1 and 80 then
      raise exception using errcode='22023', message='bounded rate-limit key and scope are required';
    end if;
    insert into public.public_submission_rate_limits(bucket_key,scope,window_started_at,request_count,updated_at)
    values(v_payload->>'bucket_key',v_payload->>'scope',now(),1,now())
    on conflict(bucket_key) do update set
      scope=excluded.scope,
      window_started_at=case when public.public_submission_rate_limits.window_started_at <= now()-interval '60 seconds' then now() else public.public_submission_rate_limits.window_started_at end,
      request_count=case when public.public_submission_rate_limits.window_started_at <= now()-interval '60 seconds' then 1 else public.public_submission_rate_limits.request_count+1 end,
      updated_at=now();
    return jsonb_build_object('ok',true);
  elsif v_command = 'attendance_state_upsert' then
    if nullif(v_payload->>'fetched_at','') is null or not isfinite((v_payload->>'fetched_at')::timestamptz) then
      raise exception using errcode='22023',message='visitor observation requires a finite source timestamp';
    end if;
    if (v_payload->>'fetched_at')::timestamptz < statement_timestamp()-interval '1 hour'
      or (v_payload->>'fetched_at')::timestamptz > statement_timestamp()+interval '60 seconds' then
      raise exception using errcode='22023',message='visitor observation requires a current source timestamp';
    end if;
    insert into public.current_attendance_state(id,attendance,last_year,planned,yesterday,yesterday_plan,source,fetched_at,updated_at)
    values(1,(v_payload->>'attendance')::integer,nullif(v_payload->>'last_year','')::integer,nullif(v_payload->>'planned','')::integer,
      nullif(v_payload->>'yesterday','')::integer,nullif(v_payload->>'yesterday_plan','')::integer,nullif(v_payload->>'source',''),
      nullif(v_payload->>'fetched_at','')::timestamptz,now())
    on conflict(id) do update set attendance=excluded.attendance,last_year=excluded.last_year,planned=excluded.planned,
      yesterday=excluded.yesterday,yesterday_plan=excluded.yesterday_plan,source=excluded.source,fetched_at=excluded.fetched_at,updated_at=now()
    where public.current_attendance_state.fetched_at is null
      or not isfinite(public.current_attendance_state.fetched_at)
      -- The conflicting row may have committed after this statement began.
      -- Classify poison when that row is considered, not with a stale start time.
      or public.current_attendance_state.fetched_at>clock_timestamp()+interval '60 seconds'
      or excluded.fetched_at>public.current_attendance_state.fetched_at
      or (excluded.fetched_at=public.current_attendance_state.fetched_at
        and row(excluded.attendance,excluded.last_year,excluded.planned,excluded.yesterday,excluded.yesterday_plan,excluded.source)
          is not distinct from row(public.current_attendance_state.attendance,public.current_attendance_state.last_year,
            public.current_attendance_state.planned,public.current_attendance_state.yesterday,
            public.current_attendance_state.yesterday_plan,public.current_attendance_state.source));
    if not found then
      raise exception using errcode='23514',message='visitor observation is older than or conflicts with the saved source version';
    end if;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_create' then
    insert into public.guest_cleanliness_reports(
      id,operation_id,request_fingerprint,location_code,location_name,issue_type,severity,notes,status,marketing_review_status,notification_status,metadata_json
    ) values(
      (v_payload->>'id')::uuid,(v_payload->>'operation_id')::uuid,v_payload->>'request_fingerprint',v_payload->>'location_code',
      nullif(v_payload->>'location_name',''),v_payload->>'issue_type',v_payload->>'severity',nullif(v_payload->>'notes',''),
      'pending_marketing_review','pending','awaiting_marketing_review',coalesce(v_payload->'metadata_json','{}'::jsonb)
    ) on conflict(operation_id) do nothing;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_notification' then
    update public.guest_cleanliness_reports set
      notification_status=v_payload->>'notification_status', notified_employee_user_id=nullif(v_payload->>'notified_employee_user_id','')::uuid,
      notified_ops_count=coalesce((v_payload->>'notified_ops_count')::integer,0),
      dispatched_at=case when coalesce((v_payload->>'delivered_count')::integer,0)>0 then now() else dispatched_at end,
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('notification_errors',coalesce(v_payload->'notification_errors','[]'::jsonb))
    where id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_review' then
    if v_payload->>'action' = 'approve' then
      update public.guest_cleanliness_reports set marketing_review_status='approved',marketing_reviewed_at=now(),
        marketing_reviewed_by=v_payload->>'actor',marketing_review_notes=nullif(v_payload->>'notes',''),status='open',notification_status='pending'
      where id=(v_payload->>'id')::uuid and status='pending_marketing_review' and marketing_review_status='pending';
      insert into public.operational_notification_jobs(job_key,job_type,source_id,payload_json)
      select 'guest-report:'||id::text,'guest_cleanliness_report',id,jsonb_build_object('operation_id',operation_id,'marketing_approved',true)
      from public.guest_cleanliness_reports where id=(v_payload->>'id')::uuid and status='open' and marketing_review_status='approved'
      on conflict(job_key) do nothing;
    elsif v_payload->>'action' = 'reject' then
      update public.guest_cleanliness_reports set marketing_review_status='rejected',marketing_reviewed_at=now(),
        marketing_reviewed_by=v_payload->>'actor',marketing_review_notes=nullif(v_payload->>'notes',''),status='rejected',resolved_at=now(),
        resolved_by=v_payload->>'actor',notification_status='not_dispatched'
      where id=(v_payload->>'id')::uuid and status='pending_marketing_review' and marketing_review_status='pending';
    else
      raise exception using errcode='22023', message='guest report review action is unsupported';
    end if;
    return jsonb_build_object('ok',true);
  elsif v_command = 'guest_report_resolve' then
    update public.guest_cleanliness_reports set status='resolved',resolved_at=now(),resolved_by=v_payload->>'actor',
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('resolution_notes',nullif(v_payload->>'notes',''))
    where id=(v_payload->>'id')::uuid and status='open' and marketing_review_status='approved';
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_legacy_image_migration' then
    update public.system_feedback_items set metadata_json=coalesce(v_payload->'metadata_json','{}'::jsonb),updated_at=now()
    where id=(v_payload->>'id')::uuid and metadata_json->'image_attachment'->>'data_url' is not null;
    update public.system_feedback_legacy_image_backups set migrated_at=now(),storage_bucket=v_payload->>'storage_bucket',storage_path=v_payload->>'storage_path'
    where feedback_id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_create' then
    insert into public.system_feedback_items(id,operation_id,request_fingerprint,category,priority,message,submitted_by,hub_context,device_id,page_url,summary,metadata_json)
    values((v_payload->>'id')::uuid,(v_payload->>'operation_id')::uuid,v_payload->>'request_fingerprint',v_payload->>'category',
      v_payload->>'priority',v_payload->>'message',nullif(v_payload->>'submitted_by',''),v_payload->>'hub_context',nullif(v_payload->>'device_id',''),
      nullif(v_payload->>'page_url',''),v_payload->>'summary',coalesce(v_payload->'metadata_json','{}'::jsonb))
    on conflict(operation_id) do nothing;
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_notification' then
    update public.system_feedback_items set notification_status=v_payload->>'notification_status',
      notified_ops_count=coalesce(notified_ops_count,0)+coalesce((v_payload->>'notified_ops_count')::integer,0),last_feedback_reminder_at=now(),
      feedback_reminder_count=coalesce(feedback_reminder_count,0)+coalesce((v_payload->>'reminder_increment')::integer,0),updated_at=now(),
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('notification_errors',coalesce(v_payload->'notification_errors','[]'::jsonb))
    where id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_status' then
    update public.system_feedback_items set status=v_payload->>'status',
      acknowledged_at=case when v_payload->>'status'='acknowledged' then now() else acknowledged_at end,
      acknowledged_by=case when v_payload->>'status'='acknowledged' then v_payload->>'actor' else acknowledged_by end,
      updated_at=now(),metadata_json=coalesce(metadata_json,'{}'::jsonb)||coalesce(v_payload->'metadata_patch','{}'::jsonb)
    where id=(v_payload->>'id')::uuid and status not in ('closed','resolved');
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_reminder_exhausted' then
    update public.system_feedback_items set status='reminder_exhausted',updated_at=now(),
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('reminder_exhausted_reason',v_payload->>'reason')
    where id=(v_payload->>'id')::uuid and status not in ('acknowledged','resolved','closed');
    return jsonb_build_object('ok',true);
  elsif v_command = 'feedback_dashboard_only' then
    update public.system_feedback_items set notification_status='dashboard_only',notified_ops_count=0,updated_at=now(),
      metadata_json=coalesce(metadata_json,'{}'::jsonb)||jsonb_build_object('notification_delivery','dashboard_only')
    where id=(v_payload->>'id')::uuid;
    return jsonb_build_object('ok',true);
  end if;
  raise exception using errcode='22023', message='unsupported bounded operational command';
end
$function$

CREATE OR REPLACE FUNCTION public.custodial_dated_control(op text, args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;manager uuid;plan jsonb;dep text;state jsonb;r public.custodial_dated_publications%rowtype;
 request jsonb;response jsonb;rev bigint;slot jsonb;day jsonb;work jsonb;inc record;actual text;expected bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 -- Direct callers use the same fence-before-authority order as the adapter.
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 if jsonb_typeof(args) is distinct from 'object' then raise exception using errcode='22023',message='typed operation arguments required'; end if;
 manager:=nullif(args->>'managerId','')::uuid;
 if op in ('snapshot','receipt','stage','staged','finalize','rollback') then
  actor:=public.static_weekly_v3_manager_actor(manager);
 end if;
 if op='snapshot' then
  -- Status and exact rollback remain available after dependency drift.
  -- This does not authorize a new stage or skip its full admission checks.
  if args->'authorityOnly'='true'::jsonb then return jsonb_build_object('authorizedManagerId',manager,
   'authorityRevision',(select current_revision from public.static_weekly_schedule_control where singleton));end if;
  plan:=args->'plan';perform public.custodial_dated_assert_plan(plan);
  if args->>'start' is distinct from '2026-10-01' or args->>'end' is distinct from '2026-10-05' then
   raise exception using errcode='23514',message='exact bounded date range required'; end if;
  for slot in select value from jsonb_array_elements(plan->'rosterSlots') loop
   if not exists(select 1 from public.weekly_roster_slots s where s.slot_id::text=slot->>'slotId') then
    raise exception using errcode='23514',message='current stable slot missing'; end if;
   for day in select value from jsonb_array_elements(plan->'days') loop
    select count(*)::text into actual from public.v_weekly_roster_slot_incumbency_ranges i
      where i.slot_id::text=slot->>'slotId' and i.effective_start<=(day->>'serviceDate')::date
      and (i.effective_end is null or (day->>'serviceDate')::date<i.effective_end);
    if (slot->>'personId' is null and actual<>'0') or (slot->>'personId' is not null and actual<>'1') then
     raise exception using errcode='23514',message='current incumbent/vacancy mismatch'; end if;
    if slot->>'personId' is not null and not exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges i
     join public.employees e on e.id=i.person_id and e.active=true
     where i.slot_id::text=slot->>'slotId' and i.person_id::text=slot->>'personId' and e.display_name=slot->>'displayName'
      and i.effective_start<=(day->>'serviceDate')::date and (i.effective_end is null or (day->>'serviceDate')::date<i.effective_end)) then
     raise exception using errcode='23514',message='current employee identity mismatch'; end if;
   end loop;
  end loop;
  if exists(select 1 from jsonb_array_elements(plan->'days') d cross join lateral jsonb_array_elements(d->'assignments') w
   where not exists(select 1 from public.location_groups g where g.group_code=w#>>'{workSnapshot,locationCodeSnapshot}' and g.active))
   or exists(select 1 from jsonb_array_elements(plan->'days') d cross join lateral jsonb_array_elements(d->'assignments') w
    cross join lateral jsonb_array_elements(w#>'{workSnapshot,includedLocations}') x
    where not exists(select 1 from public.locations l where l.id::text=x->>'locationId' and l.active)) then
    raise exception using errcode='23514',message='active physical location mapping required'; end if;
  if exists(select 1 from public.weekly_schedule_exception_commands e where e.service_date>=date '2026-10-01' and e.service_date<date '2026-10-05')
   or exists(select 1 from jsonb_array_elements(plan->'days') d cross join lateral jsonb_array_elements(d->'availability') a
    join lateral(select s.staffing_state from public.weekly_roster_slot_staffing_states s
     where s.slot_id::text=a->>'slotId' and s.effective_start<=(d->>'serviceDate')::date
     order by s.effective_start desc,s.authority_revision desc limit 1) staffing on true
    where a->>'status'='working' and staffing.staffing_state<>'working') then
   raise exception using errcode='23514',message='current staffing/dated exceptions require reconciliation';end if;
  return jsonb_build_object('authorizedManagerId',manager,'authorityRevision',(select current_revision from public.static_weekly_schedule_control where singleton),
   'dependencyDigest',public.static_weekly_digest_jsonb(public.custodial_dated_dependencies(plan)),'rosterSlots',plan->'rosterSlots',
   'approvedAvailability',(select jsonb_agg(jsonb_build_object('serviceDate',d->'serviceDate','availability',d->'availability') order by d->>'serviceDate') from jsonb_array_elements(plan->'days') d),
   'hasExistingOccurrences',exists(select 1 from public.weekly_schedule_occurrences o where service_date>=date '2026-10-01' and service_date<date '2026-10-05')
    or public.custodial_dated_record() is not null);
 elsif op='receipt' then
  select jsonb_build_object('request',x.request,'response',x.response) into response from public.custodial_dated_receipts x
    where manager_id=manager and operation_key=args->>'key';return response;
 elsif op='stage' then
  plan:=args->'plan';perform public.custodial_dated_assert_plan(plan);
  if public.custodial_dated_record() is not null or exists(select 1 from public.weekly_schedule_occurrences o
    where o.service_date>=date '2026-10-01' and o.service_date<date '2026-10-05') then
   raise exception using errcode='23514',message='existing occurrences require explicit reconciliation'; end if;
  if exists(select 1 from public.custodial_dated_publications where staged_transaction=pg_current_xact_id()) then
   raise exception using errcode='23514',message='one bounded stage per transaction'; end if;
  -- Recheck identities at the writer even if the caller bypassed JS preview.
  state:=public.custodial_dated_control('snapshot',jsonb_build_object('managerId',manager,'plan',plan,'start','2026-10-01','end','2026-10-05'));
  insert into public.custodial_dated_publications(plan_digest,plan,dependency_digest,manager_id,staged_transaction,expected_revision)
   values(plan->>'planDigest',plan,state->>'dependencyDigest',manager,pg_current_xact_id(),(state->>'authorityRevision')::bigint) returning * into r;
  for day in select value from jsonb_array_elements(plan->'days') loop
   for work in select value from jsonb_array_elements(day->'assignments') loop
    insert into public.custodial_dated_occurrences(publication_id,service_date,plan_work_id,assignment)
     values(r.publication_id,(day->>'serviceDate')::date,work->>'planWorkId',work);
   end loop;
  end loop;
  return null;
 elsif op='staged' then
  select * into r from public.custodial_dated_publications where staged_transaction=pg_current_xact_id() and manager_id=manager;
  if not found then raise exception using errcode='55000',message='transaction-local stage required'; end if;
  return jsonb_build_object('persistenceStatus','PERSISTED','publicationId',r.publication_id,'projectionId',r.projection_id,
   'planDigest',r.plan_digest,'phonePdfRevision',r.plan->>'phonePdfRevision','days',r.plan->'days');
 elsif op in ('finalize','rollback') then
  request:=args->'request';expected:=(request->>'expectedRevision')::bigint;
  if request->>'managerId' is distinct from manager::text or request->>'planDigest' is distinct from '89f600b965259f6bbf30488ff5eef2a6d754b3cbd0072f00419b318245e9459d'
   or request->>'phonePdfRevision' is distinct from 'ee75f76a21e0d3a82291b8c720b5548532e1f168f1941a0cd74e80662302bd08'
   or nullif(btrim(request->>'idempotencyKey'),'') is null or length(request->>'idempotencyKey')>200 then
    raise exception using errcode='23514',message='exact authorized operation identity required'; end if;
  if op='finalize' then
   select * into r from public.custodial_dated_publications where staged_transaction=pg_current_xact_id() and manager_id=manager;
   if not found or r.expected_revision is distinct from expected or args#>>'{record,publicationId}' is distinct from r.publication_id::text
     or args#>>'{record,projectionId}' is distinct from r.projection_id::text then
    raise exception using errcode='23514',message='complete transaction-local stage identity required'; end if;
   if request->>'operation' is distinct from 'materialize' or request->>'previewDigest' is distinct from public.static_weekly_digest_jsonb(
     jsonb_build_object('planDigest',r.plan_digest,'managerId',manager::text,'authorityRevision',expected,'dependencyDigest',r.dependency_digest)) then
    raise exception using errcode='23514',message='preview acceptance identity mismatch'; end if;
  else
   state:=public.custodial_dated_record();
   if state is null or request->>'operation' is distinct from 'rollback'
    or request->>'publicationId' is distinct from state->>'publicationId' or request->>'projectionId' is distinct from state->>'projectionId' then
    raise exception using errcode='23514',message='rollback must name exact current publication'; end if;
   select * into strict r from public.custodial_dated_publications where publication_id=(state->>'publicationId')::uuid;
  end if;
  rev:=public.static_weekly_advance_authority(expected,case when op='finalize' then 'materialize_projection' else 'rollback' end,
    manager,actor->>'manager_name',gen_random_uuid(),public.static_weekly_digest_jsonb(request));
  insert into public.custodial_dated_activations(publication_id,authority_revision,active,manager_id) values(r.publication_id,rev,op='finalize',manager);
  response:=jsonb_build_object('state',case when op='finalize' then 'PERSISTED' else 'ROLLED_BACK' end,'revision',rev,
   'publicationId',r.publication_id,'projectionId',r.projection_id,'planDigest',r.plan_digest,'phonePdfRevision',r.plan->>'phonePdfRevision',
   'phoneDeliveryState','PENDING','affectedPhonesUpdated',false);
  insert into public.custodial_dated_receipts values(manager,request->>'idempotencyKey',request,response);
  return response;
 elsif op='current' then return public.custodial_dated_record();
 elsif op='day' then
  state:=public.custodial_dated_record((args->>'date')::date);
  if state->>'projectionStatus' is distinct from 'current' then return null; end if;
  return (select d from jsonb_array_elements(state->'days') d where d->>'serviceDate'=args->>'date');
 else raise exception using errcode='22023',message='unknown bounded operation'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_memphis_schedule_day(p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_authority record;
  v_dated jsonb;
  v_dated_day jsonb;
  v_envelope jsonb;
  v_row record;
  v_entry jsonb;
  v_matches integer;
  v_identity_matches integer;
  v_seen uuid[]:=array[]::uuid[];
  v_rows jsonb:='[]'::jsonb;
  v_working boolean;
  v_start text;
  v_end text;
begin
  if p_service_date is null or not isfinite(p_service_date) then
    raise exception using errcode='22023',message='Finite schedule service date required';
  end if;
  select * into strict v_authority from public.static_weekly_v6_schedule_authority_state(p_service_date);
  if v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
    or v_authority.publication_id is null or v_authority.projection_id is null then
    return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
      'service_date',p_service_date,'projection_status',v_authority.projection_status,
      'governed',v_authority.governed,'rows','[]'::jsonb);
  end if;
  v_dated:=public.custodial_dated_record(p_service_date);
  if v_dated is not null then
    if v_dated->>'projectionStatus' is distinct from 'current'
      or v_dated->>'publicationId' is distinct from v_authority.publication_id::text
      or v_dated->>'projectionId' is distinct from v_authority.projection_id::text
      or jsonb_typeof(v_dated->'days') is distinct from 'array'
      or jsonb_typeof(v_dated#>'{plan,rosterSlots}') is distinct from 'array' then
      return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
        'service_date',p_service_date,'projection_status','dated_authority_mismatch','rows','[]'::jsonb);
    end if;
    select count(*),(jsonb_agg(day.value)->0) into v_matches,v_dated_day
    from jsonb_array_elements(v_dated->'days') day(value)
    where day.value->>'serviceDate'=p_service_date::text;
    if v_matches<>1 or jsonb_typeof(v_dated_day->'availability') is distinct from 'array' then
      return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
        'service_date',p_service_date,'projection_status','dated_day_missing','rows','[]'::jsonb);
    end if;
  else
    select projection.projection_envelope into v_envelope
    from public.weekly_schedule_compiled_projections projection
    where projection.projection_id=v_authority.projection_id
      and projection.publication_id=v_authority.publication_id
      and projection.version_id=v_authority.version_id;
    if jsonb_typeof(v_envelope#>'{authority,projectionAvailability}') is distinct from 'array' then
      return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
        'service_date',p_service_date,'projection_status','availability_missing','rows','[]'::jsonb);
    end if;
  end if;
  for v_row in select roster.* from public.static_weekly_v6_read_roster(p_service_date) roster loop
    if v_row.governed is not true or v_row.projection_status is distinct from 'current'
      or v_row.publication_id is distinct from v_authority.publication_id
      or v_row.projection_id is distinct from v_authority.projection_id then
      return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
        'service_date',p_service_date,'projection_status','roster_authority_mismatch','rows','[]'::jsonb);
    end if;
    if v_row.employee_id is null then continue;end if;
    if v_row.employee_id=any(v_seen) then
      return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
        'service_date',p_service_date,'projection_status','duplicate_employee_slot','rows','[]'::jsonb);
    end if;
    v_seen:=array_append(v_seen,v_row.employee_id);
    if not exists(select 1 from public.employees employee where employee.id=v_row.employee_id and employee.active=true) then
      continue;
    end if;
    v_working:=v_row.active is true;
    v_start:=left(coalesce(v_row.shift_start,''),5);
    v_end:=left(coalesce(v_row.shift_end,''),5);
    if v_dated is not null then
      select count(*) into v_identity_matches
      from jsonb_array_elements(v_dated#>'{plan,rosterSlots}') slot(value)
      where slot.value->>'slotId'=v_row.slot_id::text
        and slot.value->>'personId'=v_row.employee_id::text;
      select count(*),(jsonb_agg(availability.value)->0) into v_matches,v_entry
      from jsonb_array_elements(v_dated_day->'availability') availability(value)
      where availability.value->>'slotId'=v_row.slot_id::text;
      if v_identity_matches<>1 or v_matches<>1 or jsonb_typeof(v_entry) is distinct from 'object'
        or coalesce(v_entry->>'status','') not in ('working','absent','unavailable','departed_named_absent','vacant_unfilled')
        or (v_row.active is true) is distinct from (v_entry->>'status'='working') then
        return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
          'service_date',p_service_date,'projection_status','dated_identity_ambiguous','rows','[]'::jsonb);
      end if;
      v_working:=v_entry->>'status'='working';
      v_start:=v_entry#>>'{shift,start}';
      v_end:=v_entry#>>'{shift,end}';
    else
      if v_row.slot_id is null then
        return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
          'service_date',p_service_date,'projection_status','slot_identity_missing','rows','[]'::jsonb);
      end if;
      select count(*),(jsonb_agg(item.value)->0) into v_matches,v_entry
      from jsonb_array_elements(v_envelope#>'{authority,projectionAvailability}') item(value)
      where item.value->>'serviceDate'=p_service_date::text
        and item.value->>'slotId'=v_row.slot_id::text
        and item.value->>'incumbentSlotId'=v_row.slot_id::text
        and item.value->>'incumbentPersonId'=v_row.employee_id::text
        and item.value->'dayOfWeek'=to_jsonb(extract(dow from p_service_date)::integer);
      if v_matches<>1 or jsonb_typeof(v_entry) is distinct from 'object'
        or coalesce(v_entry->>'status','') not in ('working','absent','unavailable','departed_named_absent','vacant_unfilled') then
        return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
          'service_date',p_service_date,'projection_status','availability_ambiguous','rows','[]'::jsonb);
      end if;
      v_working:=v_working and v_entry->>'status'='working';
      v_start:=v_entry#>>'{shift,start}';
      v_end:=v_entry#>>'{shift,end}';
    end if;
    if v_working and (coalesce(v_start,'') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      or coalesce(v_end,'') !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$'
      or v_start>=v_end) then
      return jsonb_build_object('schema','memphis.schedule-day.v1','status','unavailable',
        'service_date',p_service_date,'projection_status','shift_invalid','rows','[]'::jsonb);
    end if;
    v_rows:=v_rows||jsonb_build_array(jsonb_build_object('employee_id',v_row.employee_id,
      'employee_name',v_row.employee_name,'employee_code',v_row.employee_code,
      'working',v_working,'shift_start',case when v_working then v_start else null end,
      'shift_end',case when v_working then v_end else null end,
      'slot_id',v_row.slot_id));
  end loop;
  return jsonb_build_object('schema','memphis.schedule-day.v1','status','current',
    'service_date',p_service_date,'governed',true,'publication_id',v_authority.publication_id,
    'projection_id',v_authority.projection_id,'rows',v_rows);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_event_decisions(p_credential uuid, p_credential_hash text, p_native_request uuid, p_attestation_digest text, p_raw_body_sha256 text, p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare d public.devices%rowtype;c public.device_auth_credentials%rowtype;
 current_g public.employee_native_push_generations%rowtype;g public.employee_native_push_generations%rowtype;
 registration public.employee_push_registrations%rowtype;r public.employee_native_push_delivery_receipts%rowtype;
 prior public.employee_native_provider_events%rowtype;
 alert public.employee_native_alert_finalizations%rowtype;
 requester jsonb;e jsonb;payload jsonb;results jsonb:='[]';field text;at_time timestamptz;
 current_ok boolean;original_ok boolean;
begin
 -- The service-only HTTP adapter verifies the CURRENT credential and fresh
 -- path/method/nonce/timestamp/raw-body HMAC before this RPC. The exact request
 -- nonce and raw digest are echoed, not promoted to a time anchor or receipt.
 if p_credential is null or p_native_request is null or coalesce(p_credential_hash,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_attestation_digest,'') !~ '^[0-9a-f]{64}$' or coalesce(p_raw_body_sha256,'') !~ '^[0-9a-f]{64}$'
  or jsonb_typeof(p_body) is distinct from 'object' or octet_length(p_body::text)>65536
  or (select array_agg(key order by key) from jsonb_object_keys(p_body) key) is distinct from array['events','requester','schema']
  or p_body->>'schema' is distinct from 'custodial.native-provider-event-decision-query.v1'
  or jsonb_typeof(p_body->'events') is distinct from 'array' or jsonb_array_length(p_body->'events') not between 1 and 16 then
  raise exception 'exact native original event query required' using errcode='22023';end if;
 requester:=p_body->'requester';
 if jsonb_typeof(requester) is distinct from 'object' or
  (select array_agg(key order by key) from jsonb_object_keys(requester) key) is distinct from
   array['assignment_epoch','credential_id','current_generation_id','device_id','employee_id','principal_digest','token_digest'] then
  raise exception 'exact native current requester required' using errcode='22023';end if;
 foreach field in array array['credential_id','current_generation_id','employee_id'] loop
  if jsonb_typeof(requester->field) is distinct from 'string' or requester->>field !~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
   raise exception 'exact native requester UUID required' using errcode='22023';end if;
 end loop;
 foreach field in array array['principal_digest','token_digest'] loop
  if jsonb_typeof(requester->field) is distinct from 'string' or requester->>field !~ '^[0-9a-f]{64}$' then
   raise exception 'exact native requester digest required' using errcode='22023';end if;
 end loop;
 if requester->>'credential_id' is distinct from p_credential::text or jsonb_typeof(requester->'device_id') is distinct from 'string'
  or requester->>'device_id' !~ '^KIOSK_(0[2-9]|10)$' or jsonb_typeof(requester->'assignment_epoch') is distinct from 'number'
  or requester->>'assignment_epoch' !~ '^[1-9][0-9]{0,15}$' or (requester->>'assignment_epoch')::numeric>9007199254740991 then
  raise exception 'exact native requester identity required' using errcode='22023';end if;
 for e in select value from jsonb_array_elements(p_body->'events') loop
  perform public.custodial_native_provider_event_shape(e);
  if e->>'receipt_credential_id' is distinct from requester->>'credential_id'
   or e->>'receipt_employee_id' is distinct from requester->>'employee_id'
   or e->>'receipt_device_id' is distinct from requester->>'device_id'
   or e->'receipt_assignment_epoch' is distinct from requester->'assignment_epoch'
   or e->>'principal_digest' is distinct from requester->>'principal_digest' then
   raise exception 'one exact original query principal required' using errcode='22023';end if;
 end loop;
 if (select count(distinct x->>'event_id') from jsonb_array_elements(p_body->'events') x)<>jsonb_array_length(p_body->'events')
  or (select count(distinct (x->>'record_id',x->>'action')) from jsonb_array_elements(p_body->'events') x)<>jsonb_array_length(p_body->'events') then
  raise exception 'unique original events and transitions required' using errcode='22023';end if;

 -- Existing authority order: global -> device -> credential -> employee ->
 -- registrations -> generations -> original reservations. SHARE locks prevent
 -- a current binding from being revoked between check and readback. No network
 -- and no INSERT/UPDATE/DELETE or application-mutation/control call occurs here.
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select d0.* into d from public.devices d0 join public.device_auth_credentials c0 on c0.device_id=d0.id
  where c0.credential_id=p_credential for share of d0;
 select * into c from public.device_auth_credentials where credential_id=p_credential for share;
 perform 1 from public.employees where id=d.assigned_employee_id for share;
 perform 1 from public.employee_push_registrations where device_id=d.id order by registration_id for share;
 perform 1 from public.employee_native_push_generations where generation_id=(requester->>'current_generation_id')::uuid
  or generation_id in(select (x->>'generation_id')::uuid from jsonb_array_elements(p_body->'events') x) order by generation_id for share;
 perform 1 from public.employee_native_push_delivery_receipts where job_id in
  (select (x->>'receipt_job_id')::uuid from jsonb_array_elements(p_body->'events') x) order by job_id for share;
 perform 1 from public.employee_native_alert_finalizations where job_id in
  (select (x->>'receipt_job_id')::uuid from jsonb_array_elements(p_body->'events') x) order by job_id for share;
 select * into current_g from public.employee_native_push_generations where generation_id=(requester->>'current_generation_id')::uuid;
 select * into registration from public.employee_push_registrations where registration_id=current_g.registration_id;
 at_time:=clock_timestamp();
 current_ok:=isfinite(at_time) and d.id is not null and d.active is true and c.device_id=d.id
  and c.token_hash=p_credential_hash and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>at_time
  and requester->>'device_id'=d.device_id and requester->>'employee_id'=d.assigned_employee_id::text
  and requester->>'assignment_epoch'=d.assignment_epoch::text
  and exists(select 1 from public.employees where id=d.assigned_employee_id and active and employee_code ~ '^EMP[0-9]+$')
  and current_g.generation_id is not null and current_g.device_id=d.id and current_g.device_identifier=d.device_id
  and current_g.credential_id=c.credential_id and current_g.employee_id=d.assigned_employee_id and current_g.assignment_epoch=d.assignment_epoch
  and current_g.principal_digest=requester->>'principal_digest' and current_g.token_digest=requester->>'token_digest'
  and current_g.activated_at<=at_time and current_g.dispatch_retired_at is null and current_g.revoked_at is null
  and registration.registration_id is not null and registration.device_id=d.id and registration.credential_id=c.credential_id
  and registration.employee_id=d.assigned_employee_id and registration.assignment_epoch=d.assignment_epoch
  and registration.active is true and registration.revoked_at is null and registration.platform='android'
  and registration.token_hash=current_g.token_digest and public.static_weekly_digest_text(registration.fcm_token)=current_g.token_digest;
 for e in select value from jsonb_array_elements(p_body->'events') loop
  original_ok:=false;
  -- Denied current state deliberately does not disclose whether an event exists.
  if current_ok is true then
   select * into g from public.employee_native_push_generations where generation_id=(e->>'generation_id')::uuid;
   select * into r from public.employee_native_push_delivery_receipts where job_id=(e->>'receipt_job_id')::uuid;
   select * into alert from public.employee_native_alert_finalizations where job_id=(e->>'receipt_job_id')::uuid;
   payload:=case when alert.job_id is not null then alert.payload else r.native_payload end;
   if alert.job_id is not null then
    original_ok:=public.custodial_native_alert_event_binding(alert.job_id,e,c.credential_id,at_time);
   else
   original_ok:=g.generation_id is not null and g.device_id=d.id and g.device_identifier=d.device_id
    and g.credential_id=c.credential_id and g.employee_id=d.assigned_employee_id and g.assignment_epoch=d.assignment_epoch
    and g.principal_digest=requester->>'principal_digest' and g.token_digest=e->>'token_digest' and g.revoked_at is null
    and r.native_generation_id=g.generation_id and r.registration_id=g.registration_id and r.credential_id=c.credential_id
    and r.assignment_epoch=d.assignment_epoch and r.prepared_at>=g.activated_at and r.prepared_at<=at_time
    and (g.dispatch_retired_at is null or r.prepared_at<=g.dispatch_retired_at)
    and r.native_payload_sha256=payload->>'content_sha256' and r.token_hash=g.token_digest
    and (payload->>'schema'='custodial.native-location-payload.v2' or
      (payload->>'schema'='custodial.native-provider-payload.v1' and payload->>'kind'='employee_lunch_coverage'));
   end if;
   foreach field in array array['generation_id','receipt_job_id','notification_key','receipt_credential_id','receipt_employee_id',
    'receipt_device_id','receipt_assignment_epoch','principal_digest','token_digest','content_sha256'] loop
    if e->>field is distinct from payload->>field then original_ok:=false;end if;
   end loop;
   select * into prior from public.employee_native_provider_events where event_id=(e->>'event_id')::uuid;
   original_ok:=original_ok and prior.event_id is not null and prior.original_event=e
    and prior.generation_id=g.generation_id and prior.job_id=(e->>'receipt_job_id')::uuid and prior.credential_id=c.credential_id
    and prior.record_id=e->>'record_id' and prior.action=e->>'action';
  end if;
  if original_ok is true then
   -- This is the immutable prior ACCEPTED fact, not a new effect. Business
   -- expiry/supersession cannot rewrite it; supported same-principal rotation
   -- keeps the ORIGINAL generation/token/observation/server receipt unchanged.
   results:=results||jsonb_build_array(jsonb_build_object('event_id',e->>'event_id','decision','ORIGINAL_ACCEPTED',
    'receipt',prior.original_event||jsonb_build_object('schema','custodial.native-provider-event-receipt.v2',
     'admitted_state','ACCEPTED','server_received_at',public.custodial_native_location_utc(prior.server_received_at),'replayed',true)));
  else
   results:=results||jsonb_build_array(jsonb_build_object('event_id',e->>'event_id','decision','UNRESOLVED'));
  end if;
 end loop;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('schema','custodial.native-provider-event-decisions.v1',
  'native_request_id',p_native_request::text,'request_body_sha256',p_raw_body_sha256,'requester',requester,'results',results));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_native_provider_registration_clock(p_credential uuid, p_credential_hash text, p_native_request uuid, p_attestation_digest text, p_body jsonb, p_status boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare admission jsonb; sampled_at timestamptz; expires timestamptz;
begin
 -- Existing proof validates exact native request, full current recipient and secret
 -- hash, then takes device -> credential -> registration -> generation locks.
 -- It obeys the mutation fence and keeps every original admission fact immutable.
 admission:=public.custodial_native_provider_registration(p_credential,p_credential_hash,p_native_request,p_attestation_digest,p_body,p_status);
 -- Read AFTER proof, never transaction_timestamp/now, activation time or a cached
 -- inventory ceiling. The locked credential cannot be concurrently revoked here.
 sampled_at:=clock_timestamp();
 select c.expires_at into strict expires from public.device_auth_credentials c where c.credential_id=p_credential;
 if not isfinite(sampled_at) or expires is null or expires<=sampled_at or (admission->>'server_now')::timestamptz>sampled_at then
  raise exception 'native provider clock unavailable' using errcode='42501';
 end if;
 return jsonb_build_object('data',admission,'clock',jsonb_build_object(
  'native_request_id',p_native_request::text,
  'server_now',to_char(sampled_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'valid_until',to_char(least(sampled_at+interval '15 minutes',expires) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
end $function$

CREATE OR REPLACE FUNCTION public.custodial_oc24_assert_completion_selection(p_response jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare services jsonb; outcome text;
begin
 if jsonb_typeof(p_response) is distinct from 'object' then
  raise exception using errcode='22023',message='completion response must be an object';
 end if;
 if not (p_response ? 'work_result') then
  raise exception using errcode='22023',message='explicit work_result required for new completion';
 end if;
 outcome:=p_response->>'work_result'; services:=p_response->'services_performed';
 if outcome is null or outcome not in ('full','details','checked_no_cleaning_needed') then
  raise exception using errcode='22023',message='unsupported completion outcome';
 end if;
 if jsonb_typeof(services) is distinct from 'array' then
  raise exception using errcode='22023',message='completion services must be an array';
 end if;
 if outcome='full' then
  if jsonb_array_length(services)<>1 or jsonb_typeof(services->0) is distinct from 'string'
   or lower(public.custodial_oc24_service_trim(services->>0))<>'full cleaning services' then
   raise exception using errcode='22023',message='full cleaning is one selection, not individual services';
  end if;
 elsif outcome='checked_no_cleaning_needed' then
  if services<>'[]'::jsonb then
   raise exception using errcode='22023',message='check-only outcome cannot claim cleaning services';
  end if;
 elsif jsonb_array_length(services)=0 or exists (
  select 1 from jsonb_array_elements(services) item
  where jsonb_typeof(item)<>'string' or public.custodial_oc24_service_trim(item#>>'{}')=''
   or lower(public.custodial_oc24_service_trim(item#>>'{}'))='full cleaning services'
 ) then
  raise exception using errcode='22023',message='selective cleaning requires individual services, never full cleaning';
 end if;
end $function$

CREATE OR REPLACE FUNCTION public.custodial_oc24_legacy_replay_allowed(p_context_id text, p_client_session_id text, p_client_completion_id text, p_device_id text, p_location_code text, p_client_started_at text, p_client_ended_at text, p_response_json jsonb, p_scan_evidence jsonb, p_correlation_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare c public.custodial_offline_actor_contexts; r public.custodial_offline_reconciliation_records;
 started timestamptz; ended timestamptz; services jsonb;
begin
 if jsonb_typeof(p_response_json) is distinct from 'object' or p_response_json ? 'work_result' then return false; end if;
 services:=p_response_json->'services_performed';
 if jsonb_typeof(services) is distinct from 'array' then return false; end if;
 if jsonb_array_length(services)=0 or exists(select 1 from jsonb_array_elements(services) x
  where jsonb_typeof(x)<>'string' or public.custodial_oc24_service_trim(x#>>'{}')='') then return false; end if;
 if jsonb_array_length(services)>1 and exists(select 1 from jsonb_array_elements(services) x
  where lower(public.custodial_oc24_service_trim(x#>>'{}'))='full cleaning services') then return false; end if;
 begin
  started:=p_client_started_at::timestamptz; ended:=p_client_ended_at::timestamptz;
  select * into c from public.custodial_offline_actor_contexts where context_id=p_context_id::uuid;
 exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then return false;
 end;
 if c.context_id is null or c.status<>'committed' or not isfinite(started) or not isfinite(ended)
  or c.client_session_id is distinct from p_client_session_id or c.started_at is distinct from started
  or c.canonical_location_code is distinct from public.resolve_scan_location_code(p_location_code)
  or not exists(select 1 from public.devices d where d.id=c.device_id and upper(d.device_id)=upper(p_device_id))
 then return false; end if;
 select * into r from public.custodial_offline_reconciliation_records
  where context_id=c.context_id and client_session_id=p_client_session_id
   and client_completion_id=p_client_completion_id and state='committed';
 return coalesce(r.reconciliation_id is not null and r.result_json->>'status'='closed'
  and r.payload_fingerprint=public.custodial_offline_payload_fingerprint(c,p_client_completion_id,started,ended,p_response_json,p_scan_evidence,p_correlation_id)
  and r.payload_json->'response_json'=p_response_json and r.payload_json->'scan_evidence'=p_scan_evidence
  and exists(select 1 from public.completion_responses cr
   where cr.id=r.completion_response_id and cr.session_id=r.session_id
    and cr.client_completion_id=p_client_completion_id and cr.response_json=p_response_json),false);
end $function$

CREATE OR REPLACE FUNCTION public.custodial_v12_inactivate_preserving_work(p_employee_id uuid, p_slot_id uuid, p_manager_id uuid, p_reason text, p_authority_revision bigint, p_command_id uuid, p_effective_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_employee public.employees%rowtype;
  v_devices jsonb;
  v_cutoff timestamptz:=statement_timestamp();
  v_separation_id uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.custodial_assert_manager(p_manager_id);
  select * into v_employee from public.employees where id=p_employee_id for update;
  if not found or v_employee.active is distinct from true
    or v_employee.employee_code !~ '^EMP[0-9]+$' then
    raise exception using errcode='23514',message='exact active custodian required for protected separation';
  end if;
  if p_slot_id is null or p_authority_revision is null or p_command_id is null
    or p_effective_date is null or p_effective_date<>public.sch_service_date(v_cutoff)
    or nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception using errcode='23514',message='protected separation identity or effective date missing';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'schema','custodial.separation-principal.v1','device_uuid',d.id,'device_identifier',d.device_id,
    'employee_id',p_employee_id,'assignment_epoch',d.assignment_epoch,
    'credentials',coalesce((select jsonb_agg(jsonb_build_object('credential_id',c.credential_id)
       order by c.credential_id) from public.device_auth_credentials c
       where c.device_id=d.id and c.revoked_at is null and c.created_at<v_cutoff
         and c.expires_at>v_cutoff and c.confirmed_at is not null and c.confirmed_at<v_cutoff),'[]'::jsonb),
    'server_known_open_sessions',coalesce((select jsonb_agg(jsonb_build_object(
       'session_id',s.id,'session_uuid',s.session_uuid,'client_session_id',s.client_session_id,
       'started_at',s.started_at,'status_at_separation',s.status) order by s.id)
       from public.sessions s where s.employee_id=p_employee_id and s.device_id=d.id
         and s.assignment_epoch_snapshot=d.assignment_epoch and s.created_at<v_cutoff
         and s.status in ('active','pending_submit')),'[]'::jsonb))
    order by d.device_id),'[]'::jsonb) into v_devices
    from public.devices d where d.assigned_employee_id=p_employee_id and d.active is true;
  update public.employees set active=false,updated_at=v_cutoff where id=p_employee_id;
  update public.msg_users set is_active=false,updated_at=v_cutoff where employee_id=p_employee_id;
  insert into public.custodial_employee_status_history(
    employee_id,employee_name,previous_active,new_active,changed_by_manager_id,
    change_reason,source,metadata_json,changed_at)
  values(p_employee_id,v_employee.display_name,true,false,p_manager_id,p_reason,
    'static_weekly_protected_separation',
    jsonb_build_object('slot_id',p_slot_id,'authority_revision',p_authority_revision,
      'command_id',p_command_id,'device_inventory',v_devices,
      'native_inventory_state','UNKNOWN','phone_released',false),v_cutoff);
  insert into public.custodial_employee_separation_fences(
