    if p_publication_kind='supersede' and p_rollback_of_version_id is not null then raise exception using errcode='23514',message='supersede may not claim a rollback target'; end if;
  end if;
  if p_publication_kind='rollback_compensation' then
    select * into v_target from public.weekly_schedule_versions where version_id=p_rollback_of_version_id and lifecycle_state='published';
    if not found or p_rollback_of_version_id is null or public.static_weekly_rollback_semantic_snapshot(v_draft.draft_document) is distinct from public.static_weekly_rollback_semantic_snapshot(v_target.draft_document) then raise exception using errcode='23514',message='rollback compensation must restore the target recurring semantics with new version and effective-date identities'; end if;
  elsif p_rollback_of_version_id is not null then raise exception using errcode='23514',message='only rollback compensation accepts a rollback target'; end if;
  v_operation:=case p_publication_kind when 'rollback_compensation' then 'rollback' when 'supersede' then 'supersede' else 'publish' end; v_revision:=public.static_weekly_advance_authority(p_expected_revision,v_operation,p_actor_manager_id,p_actor_manager_name,v_command,v_draft.content_digest); select coalesce(max(version_number),0)+1 into v_version_number from public.weekly_schedule_versions where lifecycle_state='published';
  begin v_publication:=(v_draft.draft_document#>>'{authority,compilerInput,version,publicationId}')::uuid; exception when others then raise exception using errcode='23514',message='compiler publication identity must be a canonical UUID'; end;
  perform set_config('app.static_weekly_publish_write','on',true); update public.weekly_schedule_versions set version_number=v_version_number,lifecycle_state='published',publication_kind=p_publication_kind,rollback_of_version_id=p_rollback_of_version_id,published_by_manager_id=p_actor_manager_id,published_by_manager_name_snapshot=p_actor_manager_name,published_at=statement_timestamp() where version_id=v_draft.version_id;
  v_response:=public.static_weekly_response_json(v_operation,v_revision,v_draft.content_digest,v_request_digest,jsonb_build_object('version_id',v_draft.version_id,'version_number',v_version_number,'publication_id',v_publication,'effective_start',v_draft.effective_start,'replay_digest',v_draft.draft_document#>>'{validation,replay_digest}','rollback_of_version_id',p_rollback_of_version_id));
  insert into public.weekly_schedule_publications(publication_id,version_id,authority_revision,publication_kind,effective_start,prior_version_id,expected_revision,idempotency_key,actor_manager_id,actor_manager_name_snapshot,request_digest,replay_digest,content_digest,output_digest) values(v_publication,v_draft.version_id,v_revision,p_publication_kind,v_draft.effective_start,v_previous,p_expected_revision,p_idempotency_key,p_actor_manager_id,p_actor_manager_name,v_request_digest,v_draft.draft_document#>>'{validation,replay_digest}',v_draft.content_digest,v_response->>'output_digest');
  if v_previous is not null and v_draft.effective_start > (select effective_start from public.weekly_schedule_versions where version_id=v_previous) then insert into public.weekly_schedule_effective_range_closures(closed_version_id,closed_at_effective_date,superseding_version_id,publication_id,created_by_manager_id,created_by_manager_name_snapshot,content_digest) values(v_previous,v_draft.effective_start,v_draft.version_id,v_publication,p_actor_manager_id,p_actor_manager_name,v_draft.content_digest); end if;
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,v_operation,p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_draft.content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_document_attested(p_document jsonb, p_effective_start date, p_require_publishable boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_legacy jsonb;
begin
  perform public.static_weekly_assert_exact_object(p_document,
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],
    array['adapter','authority','receipt','slot_availability','assignments','objective_inputs','validation','semantic_snapshot','attestation'],'attested adapter document');
  perform public.static_weekly_v6_assert_document_attestation(p_document);
  perform public.static_weekly_assert_exact_object(p_document->'semantic_snapshot',
    array['schema','recurring_source_digest','relational_slot_availability_digest','relational_assignments_digest']||case when p_document#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    array['schema','recurring_source_digest','relational_slot_availability_digest','relational_assignments_digest']||case when p_document#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,'recurring semantic snapshot');
  if p_document#>>'{semantic_snapshot,schema}' is distinct from (case p_document#>>'{adapter,schema}' when 'memphis-zoo.static-weekly-database-adapter.v2' then 'memphis-zoo.static-weekly-recurring-semantic-snapshot.v3' else 'memphis-zoo.static-weekly-recurring-semantic-snapshot.v2' end)
    or p_document#>>'{semantic_snapshot,recurring_source_digest}' is distinct from public.static_weekly_digest_jsonb(p_document#>'{authority,compilerInput}')
    or p_document#>>'{semantic_snapshot,relational_slot_availability_digest}' is distinct from public.static_weekly_digest_jsonb(p_document->'slot_availability')
    or p_document#>>'{semantic_snapshot,relational_assignments_digest}' is distinct from public.static_weekly_digest_jsonb(p_document->'assignments') then
    raise exception using errcode='23514',message='attested recurring semantic snapshot and relational materialization must be exact';
  end if;

  if p_document#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' and (
   p_document#>'{semantic_snapshot,derived_baseline_digest}' is distinct from coalesce(p_document#>'{authority,derivedBaselineDigest}',p_document#>'{authority,baselineInputDigest}')
   or p_document#>'{semantic_snapshot,shift_end_derivation_digest}' is distinct from to_jsonb(public.static_weekly_digest_jsonb(coalesce(p_document#>'{authority,shiftEndDerivation}','null'::jsonb)))) then
   raise exception 'recurring snapshot does not bind exact derived baseline'; end if;
  v_legacy:=p_document-'semantic_snapshot'-'attestation';
  v_legacy:=jsonb_set(v_legacy,'{validation,database_document_identity}',to_jsonb(public.static_weekly_document_identity(v_legacy)),true);
  perform public.static_weekly_assert_document(v_legacy,p_effective_start,p_require_publishable);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_exception_payload(p_exception_type text, p_service_date date, p_starts_at time without time zone, p_ends_at time without time zone, p_base_version_id uuid, p_publication_id uuid, p_payload jsonb, p_reverses_exception_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_slot text; v_lock jsonb; v_patch jsonb; v_add jsonb; v_ids text[]; v_effort numeric;
begin
  if jsonb_typeof(p_payload) is distinct from 'object' then raise exception using errcode='23514',message='exception payload must be an exact JSON object'; end if;
  if exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.base_version_id=p_base_version_id and e.service_date=p_service_date and e.exception_type=p_exception_type and e.payload_digest=public.static_weekly_digest_jsonb(p_payload) and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
    raise exception using errcode='23514',message='duplicate semantic exception command is already effective';
  end if;
  if p_exception_type in ('pto','daily_absence') then
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId'],array['slotId'],p_exception_type||' payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId',p_exception_type||' slotId'); v_slot:=p_payload->>'slotId';
    if p_starts_at is not null or p_ends_at is not null or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,true)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('pto','daily_absence','partial_absence','lunch') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
      raise exception using errcode='23514',message='full-day absence must target one currently working slot without conflict or no-op';
    end if;
  elsif p_exception_type in ('partial_absence','lunch') then
    if p_exception_type='lunch' and exists(select 1 from public.weekly_schedule_exception_commands e
      where e.publication_id=p_publication_id and e.base_version_id=p_base_version_id and e.service_date=p_service_date
       and e.exception_type='cover_all' and e.payload_json#>>'{availability,slotId}'=p_payload->>'slotId'
       and e.payload_json#>>'{availability,breakChoice}'='NONE'
       and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then
      raise exception using errcode='23514',message='Explicit no-break conflicts with a lunch; reverse and replace the dated engagement';end if;
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId'],array['slotId'],p_exception_type||' payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId',p_exception_type||' slotId'); v_slot:=p_payload->>'slotId';
    if p_starts_at is null or p_ends_at is null or not (
      public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,true)
      or (p_exception_type='lunch' and p_ends_at-p_starts_at=interval '1 hour'
        and public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,false)
        and exists(select 1 from public.weekly_schedule_versions v
          cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') slot
          where v.version_id=p_base_version_id and slot->>'id'=v_slot and slot->'contractorCapacity'='true'::jsonb)
        and exists(select 1 from public.weekly_schedule_exception_commands capacity
          where capacity.base_version_id=p_base_version_id and capacity.publication_id=p_publication_id
            and capacity.service_date=p_service_date and capacity.exception_type='cover_all'
            and capacity.payload_json#>>'{availability,slotId}'=v_slot
            and (capacity.payload_json#>>'{availability,shift,start}')::time<=p_starts_at
            and p_ends_at<=(capacity.payload_json#>>'{availability,shift,end}')::time
            and not exists(select 1 from public.weekly_schedule_exception_commands reversal
              where reversal.reverses_exception_id=capacity.exception_id))))
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('pto','daily_absence') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id))
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('partial_absence','lunch') and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id) and p_starts_at<e.ends_at and e.starts_at<p_ends_at) then
      raise exception using errcode='23514',message='partial absence or lunch must target one working slot with a nonoverlapping effective window';
    end if;
  elsif p_exception_type='shift_override' then
    perform public.static_weekly_assert_exact_object(p_payload,array['slotId','status','shift'],array['slotId','status','shift'],'shift override payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'slotId','shift override slotId'); perform public.static_weekly_v3_assert_window(p_payload->'shift','shift override shift'); v_slot:=p_payload->>'slotId';
    if p_starts_at is not null or p_ends_at is not null or p_payload->>'status' not in ('working','absent','unavailable') or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_slot,false)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='shift_override' and e.payload_json->>'slotId'=v_slot and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then raise exception using errcode='23514',message='shift override requires one extant slot and one nonduplicate exact replacement'; end if;
  elsif p_exception_type='cover_all' then
    perform public.static_weekly_assert_exact_object(p_payload,array['availability'],array['availability'],'coverall payload');
    perform public.static_weekly_assert_exact_object(p_payload->'availability',array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance'],array['slotId','shift','productiveCapacityProvenance','maxServiceEffortMinutes','maxServiceEffortProvenance','qualifications','qualificationProvenance','restrictions','restrictionProvenance','acceptedRouteAnchorLocationId','acceptedRouteProvenance','breakChoice'],'coverall availability');
    if p_payload->'availability' ? 'breakChoice' then
      if p_payload#>'{availability,breakChoice}' is distinct from '"NONE"'::jsonb
       or not exists(select 1 from public.weekly_schedule_versions v
        cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
        where v.version_id=p_base_version_id and s->>'id'=p_payload#>>'{availability,slotId}'
         and s->>'kind'='CONTRACTOR_CAPACITY' and public.static_weekly_capacity_registered(s)) then
        raise exception using errcode='23514',message='Explicit no-break requires source-bound registered nonemployee capacity';
      end if;
    end if;
    perform public.static_weekly_v3_assert_uuid(p_payload#>'{availability,slotId}','coverall slotId'); perform public.static_weekly_v3_assert_window(p_payload#>'{availability,shift}','coverall shift'); perform public.static_weekly_v3_assert_uuid(p_payload#>'{availability,acceptedRouteAnchorLocationId}','coverall route anchor');
    foreach v_slot in array array['productiveCapacityProvenance','maxServiceEffortProvenance','qualificationProvenance','restrictionProvenance','acceptedRouteProvenance'] loop perform public.static_weekly_v3_assert_text(p_payload#>array['availability',v_slot],'coverall '||v_slot); end loop;
    perform public.static_weekly_v3_assert_string_array(p_payload#>'{availability,qualifications}','coverall qualifications'); perform public.static_weekly_v3_assert_string_array(p_payload#>'{availability,restrictions}','coverall restrictions');
    if jsonb_typeof(p_payload#>'{availability,maxServiceEffortMinutes}') is distinct from 'number' then raise exception using errcode='23514',message='coverall maximum effort must be a JSON integer'; end if; v_effort:=(p_payload#>>'{availability,maxServiceEffortMinutes}')::numeric;
    if v_effort<>trunc(v_effort) or v_effort<1 or v_effort>1440 or p_starts_at is not null or p_ends_at is not null or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,p_payload#>>'{availability,slotId}',false)
      or exists(select 1 from public.weekly_schedule_exception_commands e where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='cover_all' and e.payload_json#>>'{availability,slotId}'=p_payload#>>'{availability,slotId}' and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id)) then raise exception using errcode='23514',message='coverall requires one extant slot and one bounded nonduplicate availability replacement'; end if;
  elsif p_exception_type in ('nine_forty_five_rebalance','manager_correction') then
    perform public.static_weekly_assert_exact_object(p_payload,array['locks'],array['locks'],p_exception_type||' payload');
    if jsonb_typeof(p_payload->'locks') is distinct from 'array' or jsonb_array_length(p_payload->'locks')=0 or p_starts_at is not null or p_ends_at is not null then raise exception using errcode='23514',message='rebalance and correction require nonempty lock arrays without a window'; end if;
    for v_lock in select value from jsonb_array_elements(p_payload->'locks') loop
      perform public.static_weekly_assert_exact_object(v_lock,array['workId','slotId'],array['workId','slotId'],'manager correction lock'); perform public.static_weekly_v3_assert_text(v_lock->'workId','manager correction workId',160); perform public.static_weekly_v3_assert_uuid(v_lock->'slotId','manager correction slotId');
      if not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,v_lock->>'workId') or not (public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_lock->>'slotId',true)
       or exists(select 1 from public.weekly_schedule_versions v
        cross join lateral jsonb_array_elements(v.draft_document#>'{authority,compilerInput,slots}') s
        join public.weekly_schedule_exception_commands e on e.base_version_id=v.version_id
         and e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type='cover_all'
         and e.payload_json#>>'{availability,slotId}'=s->>'id'
        where v.version_id=p_base_version_id and s->>'id'=v_lock->>'slotId'
         and s->>'kind'='CONTRACTOR_CAPACITY' and public.static_weekly_capacity_registered(s)
         and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id))) then raise exception using errcode='23514',message='rebalance and correction locks must target current weekday work and working slots'; end if;
    end loop;
    if (select count(*) from jsonb_array_elements(p_payload->'locks'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'locks')) or exists(select 1 from public.weekly_schedule_exception_commands e cross join lateral jsonb_array_elements(coalesce(e.payload_json->'locks','[]'::jsonb)) l(value) where e.publication_id=p_publication_id and e.service_date=p_service_date and e.exception_type in ('nine_forty_five_rebalance','manager_correction') and not exists(select 1 from public.weekly_schedule_exception_commands r where r.reverses_exception_id=e.exception_id) and l.value->>'workId' in (select value->>'workId' from jsonb_array_elements(p_payload->'locks'))) then raise exception using errcode='23514',message='rebalance and correction locks may not duplicate or contradict effective commands'; end if;
  elsif p_exception_type='event_impact' then
    perform public.static_weekly_assert_exact_object(p_payload,array['removeWorkIds','patchWork','addWork'],array['removeWorkIds','patchWork','addWork'],'event impact payload');
    if p_starts_at is not null or p_ends_at is not null or jsonb_typeof(p_payload->'removeWorkIds') is distinct from 'array' or jsonb_typeof(p_payload->'patchWork') is distinct from 'array' or jsonb_typeof(p_payload->'addWork') is distinct from 'array' or jsonb_array_length(p_payload->'removeWorkIds')+jsonb_array_length(p_payload->'patchWork')+jsonb_array_length(p_payload->'addWork')=0 then raise exception using errcode='23514',message='event impact requires nonempty exact command arrays without a window'; end if;
    perform public.static_weekly_v3_assert_string_array(p_payload->'removeWorkIds','event removal targets',true,160);
    if exists(select 1 from jsonb_array_elements(p_payload->'removeWorkIds') x(value) where not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,x.value#>>'{}')) then raise exception using errcode='23514',message='event removal must target work on the exception service weekday'; end if;
    for v_patch in select value from jsonb_array_elements(p_payload->'patchWork') loop perform public.static_weekly_v3_assert_work_payload(v_patch,false); if not public.static_weekly_exception_work_exists(p_base_version_id,p_service_date,v_patch->>'workId') then raise exception using errcode='23514',message='event patch must target work on the exception service weekday'; end if; end loop;
    for v_add in select value from jsonb_array_elements(p_payload->'addWork') loop perform public.static_weekly_v3_assert_work_payload(v_add,true); if (v_add->>'dayOfWeek')::integer<>extract(dow from p_service_date)::integer or exists(select 1 from public.weekly_schedule_slot_assignments a where a.version_id=p_base_version_id and a.day_of_week=extract(dow from p_service_date)::smallint and a.work_id=v_add->>'workId') or not public.static_weekly_exception_slot_exists(p_base_version_id,p_service_date,v_add->>'originSlotId',false) then raise exception using errcode='23514',message='event addition must be a new work identity for the service weekday and an extant origin slot'; end if; end loop;
    select array_agg(value#>>'{}') into v_ids from jsonb_array_elements(p_payload->'removeWorkIds');
    if exists(select 1 from jsonb_array_elements(p_payload->'patchWork') x(value) where x.value->>'workId'=any(coalesce(v_ids,array[]::text[]))) or exists(select 1 from jsonb_array_elements(p_payload->'addWork') x(value) where x.value->>'workId'=any(coalesce(v_ids,array[]::text[]))) or (select count(*) from jsonb_array_elements(p_payload->'patchWork'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'patchWork')) or (select count(*) from jsonb_array_elements(p_payload->'addWork'))<>(select count(distinct value->>'workId') from jsonb_array_elements(p_payload->'addWork')) then raise exception using errcode='23514',message='event targets must be unique and may not remove, patch, and add the same work'; end if;
  elsif p_exception_type='reverse' then
    perform public.static_weekly_assert_exact_object(p_payload,array['reversesExceptionId'],array['reversesExceptionId'],'reverse payload'); perform public.static_weekly_v3_assert_uuid(p_payload->'reversesExceptionId','reverse target');
    if p_starts_at is not null or p_ends_at is not null or p_reverses_exception_id is distinct from (p_payload->>'reversesExceptionId')::uuid then raise exception using errcode='23514',message='reversal requires one coherent UUID target without a window'; end if;
  else raise exception using errcode='23514',message='unsupported exception operation';
  end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_assert_projection_envelope_attested(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_legacy jsonb;
  v_snapshot jsonb;
  v_document jsonb;
  v_recurring_source_digest text;
  v_published_source_digest text;
  v_overlay_source_digest text;
begin
  perform public.static_weekly_assert_exact_object(
    p_envelope,
    array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],
    array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity','semantic_snapshot','attestation'],
    'attested projection envelope'
  );
  perform public.static_weekly_assert_authority_attestation(
    p_envelope->'attestation','dated_projection',public.static_weekly_projection_attestation_payload(p_envelope)
  );
  if p_envelope->>'database_projection_identity' is distinct from
     public.static_weekly_digest_jsonb((p_envelope-'attestation')-'database_projection_identity') then
    raise exception using errcode='23514',message='projection semantic identity must bind the complete attested envelope';
  end if;

  v_snapshot:=p_envelope->'semantic_snapshot';
  perform public.static_weekly_assert_exact_object(
    v_snapshot,
    array['schema','recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']||case when p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    array['schema','recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']||case when p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' then array['derived_baseline_digest','shift_end_derivation_digest'] else '{}'::text[] end,
    'projection semantic snapshot'
  );
  if exists(
    select 1
    from unnest(array['recurring_source_digest','overlay_source_digest','applied_exceptions_digest','active_assignments_digest']) field_name
    where jsonb_typeof(v_snapshot->field_name) is distinct from 'string'
       or coalesce(v_snapshot->>field_name,'') !~ '^[0-9a-f]{64}$'
  ) then
    raise exception using errcode='23514',message='projection semantic snapshot requires exact canonical SHA-256 identities';
  end if;

  select v.draft_document into v_document
  from public.weekly_schedule_versions v
  join public.weekly_schedule_publications p on p.version_id=v.version_id
  where p.publication_id=p_publication_id;
  if not found then
    raise exception using errcode='23514',message='projection publication is unknown';
  end if;

  v_recurring_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,compilerInput}')
  );
  v_published_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(v_document#>'{authority,compilerInput}')
  );
  v_overlay_source_digest:=public.static_weekly_digest_jsonb(
    public.static_weekly_v5_projection_source_identity(p_envelope#>'{authority,overlayCompilerInput}')
  );

  if v_snapshot->>'schema' is distinct from (case p_envelope#>>'{adapter,schema}' when 'memphis-zoo.static-weekly-database-adapter.v2' then 'memphis-zoo.static-weekly-projection-semantic-snapshot.v3' else 'memphis-zoo.static-weekly-projection-semantic-snapshot.v2' end)
    or v_snapshot->>'recurring_source_digest' is distinct from v_recurring_source_digest
    or v_snapshot->>'recurring_source_digest' is distinct from v_published_source_digest
    or v_snapshot->>'overlay_source_digest' is distinct from v_overlay_source_digest
    or v_snapshot->>'applied_exceptions_digest' is distinct from public.static_weekly_digest_jsonb(p_envelope->'applied_exceptions')
    or v_snapshot->>'active_assignments_digest' is distinct from public.static_weekly_digest_jsonb(p_envelope->'assignments') then
    raise exception using errcode='23514',message='projection must bind stable recurring source, dated staffing and exceptions, and active assignments';
  end if;

  -- The established v4 validator still performs the complete structural,
  -- optimizer, work-snapshot, service-mode, and location checks.  Only the
  -- redundant semantic copies have been replaced by independently recomputed
  -- identities.

  if p_envelope#>>'{adapter,schema}'='memphis-zoo.static-weekly-database-adapter.v2' and (
   v_snapshot->'derived_baseline_digest' is distinct from coalesce(p_envelope#>'{authority,derivedBaselineDigest}',p_envelope#>'{authority,baselineInputDigest}')
   or v_snapshot->'shift_end_derivation_digest' is distinct from to_jsonb(public.static_weekly_digest_jsonb(coalesce(p_envelope#>'{authority,shiftEndDerivation}','null'::jsonb)))) then
   raise exception 'projection snapshot does not bind exact derived baseline'; end if;
  v_legacy:=p_envelope-'semantic_snapshot'-'attestation';
  v_legacy:=jsonb_set(
    v_legacy,'{database_projection_identity}',
    to_jsonb(public.static_weekly_digest_jsonb(v_legacy-'database_projection_identity')),true
  );
  perform public.static_weekly_v4_assert_projection_envelope(
    v_legacy,p_publication_id,p_week_start,p_exception_set
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_event_brief_candidates(p_manager_id uuid, p_capacity_slot_id uuid, p_service_date date, p_projection_id uuid, p_expected_authority_revision bigint, p_lunch_document_identity text, p_print_document_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
 v_manager public.ops_manager_managers%rowtype;
 v_authority record;
 v_control_revision bigint;
 v_capacity public.static_weekly_contractor_capacity_registrations%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_lunch_read jsonb;
 v_event record;
 v_row jsonb;
 v_rows jsonb:='[]'::jsonb;
 v_count integer:=0;
 v_scanned integer;
 v_replay_digest text;
begin
 if p_manager_id is null or p_capacity_slot_id is null or p_service_date is null
  or p_projection_id is null or p_expected_authority_revision is null
  or p_expected_authority_revision<1
  or coalesce(p_lunch_document_identity,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_print_document_digest,'') !~ '^[0-9a-f]{64}$' then
  raise exception using errcode='22023',message='exact manager, capacity and accepted print basis required';
 end if;
 select * into v_manager from public.ops_manager_managers where manager_id=p_manager_id;
 if v_manager.manager_id is null or v_manager.active is not true or v_manager.revoked_at is not null
  or v_manager.is_system_principal is true
  or (v_manager.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]) is not true then
  raise exception using errcode='42501',message='active named manager required for contractor Event list';
 end if;
 select current_revision into v_control_revision from public.static_weekly_schedule_control where singleton;
 select * into v_authority from public.static_weekly_v6_schedule_authority_state(p_service_date);
 select p.replay_digest into v_replay_digest from public.weekly_schedule_compiled_projections p
  where p.projection_id=p_projection_id and p.publication_id=v_authority.publication_id
   and p.version_id=v_authority.version_id;
 if v_control_revision is distinct from p_expected_authority_revision
  or v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
  or v_authority.projection_id is distinct from p_projection_id
  or coalesce(v_replay_digest,'') !~ '^[0-9a-f]{64}$' then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false,'candidates','[]'::jsonb);
 end if;
 select * into v_capacity from public.static_weekly_contractor_capacity_registrations
  where capacity_slot_id=p_capacity_slot_id;
 if v_capacity.capacity_slot_id is null or not public.static_weekly_capacity_registered(v_capacity.slot_snapshot)
  or not exists(select 1 from jsonb_array_elements(public.static_weekly_compiler_exception_set(
    v_authority.publication_id,v_authority.week_start)) item(value)
    where item.value->>'type'='cover_all' and item.value->>'serviceDate'=p_service_date::text
      and item.value#>>'{payload,availability,slotId}'=p_capacity_slot_id::text) then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','CAPACITY_NOT_ACCEPTED','disclosure_approved',false,'candidates','[]'::jsonb);
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents where projection_id=p_projection_id;
 v_lunch_read:=public.static_weekly_v8_read_lunch_document(p_service_date);
 if v_lunch.projection_id is null or v_lunch.document_identity is distinct from p_lunch_document_identity
  or v_lunch_read->>'persistence_status' is distinct from 'PERSISTED'
  or v_lunch_read->>'document_identity' is distinct from p_lunch_document_identity
  or v_lunch_read->>'projection_id' is distinct from p_projection_id::text then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false,'candidates','[]'::jsonb);
 end if;
 select count(*) into v_scanned from (
  select 1 from public.events_app_events e
   where e.event_date=p_service_date and e.status='SCHEDULED'
   order by e.start_instant_utc,e.id limit 33
 ) bounded;
 if v_scanned>32 then
  return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
   'status','LIMIT_EXCEEDED','limit_reason','same_day_scan','disclosure_approved',false,
   'candidates','[]'::jsonb);
 end if;
 for v_event in select e.id,e.revision from public.events_app_events e
  where e.event_date=p_service_date and e.status='SCHEDULED'
  order by e.start_instant_utc,e.id
 loop
  v_row:=public.static_weekly_coverall_event_brief_candidate(p_manager_id,v_event.id,
    v_event.revision,p_capacity_slot_id,p_service_date,p_projection_id,
    p_expected_authority_revision,p_lunch_document_identity,p_print_document_digest);
  if v_row->>'status'='PREVIEW_ONLY' then
   if octet_length(v_row::text)>8192 or v_count>=16 then
    return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
     'status','LIMIT_EXCEEDED','limit_reason','eligible_count_or_size',
     'disclosure_approved',false,'candidates','[]'::jsonb);
   end if;
   v_rows:=v_rows||jsonb_build_array(v_row);
   v_count:=v_count+1;
  end if;
 end loop;
 return jsonb_build_object('schema','custodial.coverall-event-brief-list.v1',
  'status','PREVIEW_ONLY','disclosure_approved',false,
  'manager_id',p_manager_id,'capacity_slot_id',p_capacity_slot_id,
  'service_date',p_service_date,'projection_id',p_projection_id,
  'publication_id',v_authority.publication_id,'projection_replay_digest',v_replay_digest,
  'authority_revision',v_control_revision,'lunch_document_identity',p_lunch_document_identity,
  'print_document_digest',p_print_document_digest,'candidate_limit',16,'scan_limit',32,
  'candidates',v_rows);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_coverall_event_brief_candidate(p_manager_id uuid, p_event_id uuid, p_event_revision integer, p_capacity_slot_id uuid, p_service_date date, p_projection_id uuid, p_expected_authority_revision bigint, p_lunch_document_identity text, p_print_document_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
 v_manager public.ops_manager_managers%rowtype;
 v_authority record;
 v_control_revision bigint;
 v_capacity public.static_weekly_contractor_capacity_registrations%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_lunch_read jsonb;
 v_event public.events_app_events%rowtype;
 v_place jsonb;
 v_areas jsonb;
 v_replay_digest text;
begin
 if p_manager_id is null or p_event_id is null or p_event_revision is null or p_event_revision<1
  or p_capacity_slot_id is null or p_service_date is null or p_projection_id is null
  or p_expected_authority_revision is null or p_expected_authority_revision<1
  or coalesce(p_lunch_document_identity,'') !~ '^[0-9a-f]{64}$'
  or coalesce(p_print_document_digest,'') !~ '^[0-9a-f]{64}$' then
  raise exception using errcode='22023',message='exact manager, event, capacity and accepted print basis required';
 end if;
 select * into v_manager from public.ops_manager_managers where manager_id=p_manager_id;
 if v_manager.manager_id is null or v_manager.active is not true or v_manager.revoked_at is not null
  or v_manager.is_system_principal is true
  or (v_manager.roles && array['OPS_MANAGER','CUSTODIAL_MANAGER','DIRECTOR','SECURITY_ADMIN']::text[]) is not true then
  raise exception using errcode='42501',message='active named manager required for contractor Event brief';
 end if;
 select current_revision into v_control_revision from public.static_weekly_schedule_control where singleton;
 select * into v_authority from public.static_weekly_v6_schedule_authority_state(p_service_date);
 if v_control_revision is distinct from p_expected_authority_revision
  or v_authority.governed is not true or v_authority.projection_status is distinct from 'current'
  or v_authority.projection_id is distinct from p_projection_id then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false);
 end if;
 select * into v_capacity from public.static_weekly_contractor_capacity_registrations
  where capacity_slot_id=p_capacity_slot_id;
 if v_capacity.capacity_slot_id is null or not public.static_weekly_capacity_registered(v_capacity.slot_snapshot)
  or not exists(select 1 from jsonb_array_elements(public.static_weekly_compiler_exception_set(
    v_authority.publication_id,v_authority.week_start)) item(value)
    where item.value->>'type'='cover_all' and item.value->>'serviceDate'=p_service_date::text
      and item.value#>>'{payload,availability,slotId}'=p_capacity_slot_id::text) then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','CAPACITY_NOT_ACCEPTED','disclosure_approved',false);
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents
  where projection_id=p_projection_id;
 v_lunch_read:=public.static_weekly_v8_read_lunch_document(p_service_date);
 if v_lunch.projection_id is null or v_lunch.document_identity is distinct from p_lunch_document_identity
  or v_lunch_read->>'persistence_status' is distinct from 'PERSISTED'
  or v_lunch_read->>'document_identity' is distinct from p_lunch_document_identity
  or v_lunch_read->>'projection_id' is distinct from p_projection_id::text then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false);
 end if;
 select replay_digest into v_replay_digest from public.weekly_schedule_compiled_projections
  where projection_id=p_projection_id and publication_id=v_authority.publication_id
   and version_id=v_authority.version_id;
 if v_replay_digest is null then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','STALE_PRINT_BASIS','disclosure_approved',false);
 end if;
 select * into v_event from public.events_app_events where id=p_event_id;
 if v_event.id is null or v_event.revision is distinct from p_event_revision
  or v_event.status is distinct from 'SCHEDULED' or coalesce(v_event.needs_review,false)
  or v_event.event_scope='UNKNOWN' or v_event.cancelled_at is not null
  or v_event.archived_at is not null or v_event.superseded_by_event_id is not null
  or v_event.start_instant_utc is null or v_event.end_instant_utc is null
  or v_event.end_instant_utc<=v_event.start_instant_utc
  or v_event.event_date is distinct from p_service_date
  or (v_event.start_instant_utc at time zone 'America/Chicago')::date is distinct from p_service_date
  or coalesce(cardinality(v_event.coverage_location_ids),0)=0 then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','EVENT_NOT_CURRENT_OR_UNSCOPED','disclosure_approved',false);
 end if;
 v_place:=public.app_event_place_authority(to_jsonb(v_event),statement_timestamp());
 if (v_place->>'admissible')::boolean is not true then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','EVENT_PLACE_NEEDS_REVIEW','disclosure_approved',false);
 end if;
 -- The typed readers prove current group/physical identities. Ordinary
 -- ownership and exact accepted lunch loans are separate branches. No Event
 -- venue or display-name equivalence is used as custodial coverage.
 with ordinary as (
  select s.location_group_id,s.group_name,s.coverage_start::time as starts,
   s.coverage_end::time as ends,s.included_location_ids,'area_owner'::text as purpose
  from public.static_weekly_v6_read_schedule_segments(p_service_date) s
  join public.weekly_schedule_occurrences o on o.occurrence_id=s.segment_id
  where s.projection_id=p_projection_id and s.status='ASSIGNED' and s.owner_type='COVERALL'
   and s.service_mode='scan_tracked' and cardinality(s.included_location_ids)>0
   and o.owner_kind='CONTRACTOR_CAPACITY' and o.owner_capacity_id=p_capacity_slot_id
 ), temporary as (
  select s.location_group_id,s.group_name,s.coverage_start starts,s.coverage_end ends,
   s.included_location_ids,'lunch_coverage'::text purpose
  from public.static_weekly_v8_read_lunch_segments(p_service_date) s
  join jsonb_array_elements(v_lunch.document_json->'responsibilities') r(value)
   on r.value->>'responsibility_id'=s.responsibility_id
  where s.projection_id=p_projection_id and s.service_mode='scan_tracked'
   and cardinality(s.included_location_ids)>0
   and r.value->>'coverer_slot_id'=p_capacity_slot_id::text
   and r.value->>'coverer_capacity_id'=p_capacity_slot_id::text
   and r.value->'coverer_person_id'='null'::jsonb
 ), matched as (
  select distinct * from (select * from ordinary union all select * from temporary) areas
  where areas.location_group_id=any(v_event.coverage_location_ids)
 ) select coalesce(jsonb_agg(jsonb_build_object('location_group_id',location_group_id,
    'group_name',group_name,'starts',to_char(starts,'HH24:MI'),
    'ends',to_char(ends,'HH24:MI'),'included_location_ids',included_location_ids,
    'purpose',purpose) order by starts,ends,location_group_id,purpose),'[]'::jsonb)
  into v_areas from matched;
 if jsonb_array_length(v_areas)=0 then
  return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
   'status','NO_MATCHED_ACCEPTED_COVERAGE','disclosure_approved',false);
 end if;
 return jsonb_build_object('schema','custodial.coverall-event-brief-candidate.v1',
  'status','PREVIEW_ONLY','disclosure_approved',false,
  'manager_id',p_manager_id,'capacity_slot_id',p_capacity_slot_id,
  'service_date',p_service_date,'projection_id',p_projection_id,
  'publication_id',v_authority.publication_id,
  'authority_revision',v_control_revision,'projection_replay_digest',v_replay_digest,
  'lunch_document_identity',p_lunch_document_identity,
  'print_document_digest',p_print_document_digest,
  'event_id',v_event.id,'event_revision',v_event.revision,
  'event_name',v_event.event_name,
  'display_location',coalesce(nullif(v_place->>'primary_display_name',''),v_event.display_location),
  'event_date',v_event.event_date,
  'start_instant_utc',v_event.start_instant_utc,'end_instant_utc',v_event.end_instant_utc,
  'start_time',v_event.start_time,'end_time',v_event.end_time,
  'custodial_note_codes',v_event.custodial_note_codes,
  'custodial_public_notes',v_event.custodial_public_notes,
  'matched_areas',v_areas);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_materialize_approved_initial_baseline(p_manager_id uuid, p_source_id uuid, p_date date, p_revision bigint, p_generation bigint, p_key text, p_envelope jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;basis jsonb;baseline public.static_weekly_approved_initial_baselines%rowtype;prior public.static_weekly_approved_initial_confirmations%rowtype;
 document jsonb;projection jsonb;draft jsonb;published jsonb;materialized jsonb;lunch jsonb;receipt jsonb;provenance jsonb;
 v_version_id uuid;v_publication_id uuid;v_projection_id uuid;revision bigint;kind text;
begin
 perform public.static_weekly_v3_assert_control_plane();perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 if p_key is null or length(btrim(p_key)) not between 1 and 150 then raise exception 'exact initial idempotency key required';end if;
 select * into prior from public.static_weekly_approved_initial_confirmations where manager_id=p_manager_id and idempotency_key=p_key;
 if found then
  if prior.request_json is distinct from p_envelope->'request' then raise exception using errcode='23505',message='initial confirmation identity conflict';end if;
  return prior.receipt_json;end if;
 basis:=public.static_weekly_read_approved_initial_basis(p_manager_id,p_source_id,p_date,p_revision,p_envelope#>>'{request,templateId}');
 select * into strict baseline from public.static_weekly_approved_initial_baselines where source_id=p_source_id;
 if p_envelope->>'schema' is distinct from 'custodial.approved-static-initial-materialization.v1'
  or p_envelope->>'managerId' is distinct from p_manager_id::text or p_envelope->>'sourceId' is distinct from p_source_id::text
  or p_envelope->>'effectiveStart' is distinct from p_date::text or p_envelope->'expectedRevision' is distinct from to_jsonb(p_revision)
  or p_generation is distinct from (basis->>'generation')::bigint or p_envelope->'generation' is distinct from to_jsonb(p_generation)
  or p_envelope->>'templateCatalogDigest' is distinct from basis->>'templateCatalogDigest'
  or p_envelope->'feasibility' is distinct from baseline.feasibility
  or p_envelope->>'previewDigest' is distinct from public.static_weekly_digest_jsonb(p_envelope-'request'-'previewDigest')
  or p_envelope->'request' is distinct from jsonb_build_object('sourceId',p_source_id,'effectiveStart',p_date,
    'templateId',baseline.template_id,'expectedRevision',p_revision,'previewDigest',p_envelope->>'previewDigest','idempotencyKey',p_key) then
  raise exception using errcode='23514',message='initial baseline must bind exact current source/catalog/actor/revision/generation and independently prepared fixed snapshot';end if;
 document:=baseline.feasibility#>'{initialBaseline,document}';projection:=baseline.feasibility#>'{initialBaseline,projection}';
 provenance:=jsonb_build_object('adapter_schema',document#>>'{adapter,schema}','compiler_version',document#>>'{validation,compiler_version}',
  'input_digest',document#>>'{validation,input_digest}','baseline_input_digest',document#>>'{validation,baseline_input_digest}',
  'authority_digest',document#>>'{validation,authority_digest}','replay_digest',document#>>'{validation,replay_digest}');
 draft:=public.static_weekly_approved_initial_create_draft(p_date,projection->>'compiler_version',projection->'objective',provenance,
  document,p_revision,p_manager_id,actor->>'manager_name',p_key||':draft');
 v_version_id:=(draft#>>'{data,version_id}')::uuid;revision:=(draft->>'revision')::bigint;
 perform set_config('app.static_weekly_source_bind','on',true);
 update public.weekly_schedule_versions set authority_source_id=p_source_id where version_id=v_version_id and authority_source_id is null;
 if not exists(select 1 from public.weekly_schedule_versions v where v.version_id=v_version_id and v.authority_source_id=p_source_id) then raise exception 'initial source identity was not retained';end if;
 perform public.static_weekly_v3_assert_draft_incumbency(v_version_id);
 kind:=case when exists(select 1 from public.weekly_schedule_publications) then 'supersede' else 'publish' end;
 published:=public.static_weekly_approved_initial_publish_draft(v_version_id,(draft#>>'{data,draft_revision}')::bigint,revision,
  p_manager_id,actor->>'manager_name',p_key||':publish',kind,null);
 v_publication_id:=(published#>>'{data,publication_id}')::uuid;revision:=(published->>'revision')::bigint;
 materialized:=public.static_weekly_approved_initial_materialize_projection(v_publication_id,p_date,public.static_weekly_digest_jsonb('[]'::jsonb),
  projection->>'compiler_version',projection->'objective',projection->'metrics',projection->>'replay_digest',projection,revision,
  p_manager_id,actor->>'manager_name',p_key||':projection');
 v_projection_id:=(materialized#>>'{data,projection_id}')::uuid;revision:=(materialized->>'revision')::bigint;
 lunch:=public.static_weekly_v8_materialize_lunch_document(v_projection_id,baseline.feasibility->'lunchDocument',p_manager_id);
 if lunch->>'persistence_status' is distinct from 'PERSISTED' then raise exception 'initial lunch not persisted';end if;
 receipt:=jsonb_build_object('schema','custodial.approved-static-initial-confirmation.v1','status','PERSISTED_CURRENT',
  'ok',true,'persistence_status','PERSISTED','source_id',p_source_id,'publication_id',v_publication_id,'projection_id',v_projection_id,
  'authority_revision',revision,'revision',revision,'feasibility_digest',baseline.feasibility->>'digest',
  'lunch_document_identity',lunch->>'document_identity','previewDigest',p_envelope->>'previewDigest','solverInvoked',false);
 insert into public.static_weekly_approved_initial_confirmations values(p_manager_id,p_key,p_envelope->'request',receipt,v_publication_id,v_projection_id);
 return receipt;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_initial_basis(p_manager_id uuid, p_source_id uuid, p_date date, p_revision bigint, p_template_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare baseline public.static_weekly_approved_initial_baselines%rowtype;entry public.static_weekly_approved_template_catalog%rowtype;
 source jsonb;revision bigint;templates jsonb;bindings jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 select current_revision into strict revision from public.static_weekly_schedule_control where singleton;
 if revision is distinct from p_revision then raise exception using errcode='40001',message='stale initial baseline revision';end if;
 select * into strict baseline from public.static_weekly_approved_initial_baselines
  where source_id=p_source_id and template_id=p_template_id and effective_start=p_date;
 select * into strict entry from public.static_weekly_approved_template_catalog where template_id=p_template_id;
 source:=(public.static_weekly_v3_read_authority_source(p_source_id,p_date))->'compiler_input';
 if exists(select 1 from public.static_weekly_approved_template_retirements where template_id=p_template_id)
  or baseline.snapshot_digest<>public.static_weekly_digest_jsonb(baseline.feasibility)
  or baseline.feasibility->'candidateSource' is distinct from source
  or entry.catalog_entry_digest<>public.static_weekly_digest_jsonb(jsonb_build_object('template',entry.template_json,
    'binding',entry.binding_json,'ownerConfig',entry.owner_config,'approvalEvidence',entry.approval_evidence)) then
  raise exception 'approved initial source or current people/availability changed';end if;
 templates:=jsonb_build_array(entry.template_json);bindings:=jsonb_build_array(entry.binding_json);
 return jsonb_build_object('schema','custodial.approved-static-initial-basis.v1','sourceId',p_source_id,'serviceDate',p_date,
  'authorityRevision',revision,'generation',public.static_weekly_v15_read_recurring_generation(),
  'currentSource',source,'currentSourceDigest',public.static_weekly_digest_jsonb(source),
  'ownerConfig',entry.owner_config,'templates',templates,'admittedBindings',bindings,
  'templateCatalogDigest',public.static_weekly_digest_jsonb(jsonb_build_object('templates',templates,'admittedBindings',bindings,'ownerConfig',entry.owner_config)));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_initial_confirmation(p_manager_id uuid, p_key text)
 RETURNS jsonb
