CREATE OR REPLACE FUNCTION public.static_weekly_read_approved_template_basis(p_manager_id uuid, p_publication_id uuid, p_service_date date, p_kind text, p_template_id text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source_row jsonb;source_input jsonb;config jsonb;templates jsonb;bindings jsonb;catalog jsonb;
 week_start date;revision bigint;generation bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_service_date is null or not isfinite(p_service_date)
  or p_kind is null or p_kind not in ('RECURRING_STAFFING','DATED_ABSENCE')
  or (p_kind='RECURRING_STAFFING' and extract(isodow from p_service_date)<>1) then
  raise exception using errcode='22023',message='one finite date and explicit static template operation kind required';end if;
 week_start:=p_service_date-(extract(isodow from p_service_date)::integer-1);
 select current_revision into strict revision from public.static_weekly_schedule_control where singleton;
 if p_expected_revision is distinct from revision then raise exception using errcode='40001',message='stale approved template preview revision';end if;
 source_row:=public.static_weekly_v3_read_publication_source(p_publication_id,week_start);
 source_input:=jsonb_set(jsonb_set(source_row->'compiler_input','{serviceDate}',to_jsonb(p_service_date::text),true),
  '{exceptions}',source_row->'exceptions',true);
 select c.owner_config into config from public.static_weekly_approved_template_source_configs c
  join public.static_weekly_authority_source_documents s using(source_id)
  where c.source_id=(source_row->>'source_id')::uuid and s.active and s.retired_at is null
   and c.config_digest=public.static_weekly_digest_jsonb(c.owner_config)
   and s.source_digest=public.static_weekly_digest_jsonb(s.canonical_source);
 if config is null then raise exception using errcode='55000',message='current publication lacks release-admitted static template owner configuration';end if;
 select coalesce(jsonb_agg(c.template_json order by c.template_id),'[]'::jsonb),
  coalesce(jsonb_agg(c.binding_json order by c.template_id),'[]'::jsonb),
  coalesce(jsonb_agg(jsonb_build_object('templateId',c.template_id,'entryDigest',c.catalog_entry_digest) order by c.template_id),'[]'::jsonb)
  into templates,bindings,catalog from public.static_weekly_approved_template_catalog c
  where c.owner_config=config and (p_template_id is null or c.template_id=p_template_id)
   and not exists(select 1 from public.static_weekly_approved_template_retirements r where r.template_id=c.template_id)
   and c.catalog_entry_digest=public.static_weekly_digest_jsonb(jsonb_build_object(
    'template',c.template_json,'binding',c.binding_json,'ownerConfig',c.owner_config,'approvalEvidence',c.approval_evidence));
 if jsonb_array_length(templates)=0 then raise exception using errcode='55000',message='missing approved static template; automatic solver generation is not authorized';end if;
 select public.static_weekly_v15_read_recurring_generation() into generation;
 return jsonb_build_object('schema','custodial.approved-static-template-basis.v1',
  'publicationId',p_publication_id,'serviceDate',p_service_date,'kind',p_kind,
  'authorityRevision',revision,'generation',generation,
  'templateCatalogDigest',public.static_weekly_digest_jsonb(catalog),
  'currentSource',source_input,'ownerConfig',config,'templates',templates,'admittedBindings',bindings);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_register_approved_template(p_source_id uuid, p_template jsonb, p_binding jsonb, p_owner_config jsonb, p_approval_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare id text;count_people integer;body jsonb;entry_digest text;prior record;source_row record;
begin
 perform public.static_weekly_v3_assert_release_operator();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into source_row from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active and retired_at is null for share;
 if not found or source_row.source_digest is distinct from public.static_weekly_digest_jsonb(source_row.canonical_source) then
  raise exception using errcode='23514',message='approved template requires an exact active registered current source';end if;
 perform public.static_weekly_assert_exact_object(p_template,
  array['templateId','staffingCount','source','roleSlotIds'],
  array['templateId','staffingCount','source','roleSlotIds'],'approved static template');
 perform public.static_weekly_assert_exact_object(p_binding,
  array['schema','templateId','staffingCount','sourceDigest','roleSlotIdsDigest','patternAuthority','artifactSha256','ownerConfigDigest','patternPublicationStatus'],
  array['schema','templateId','staffingCount','sourceDigest','roleSlotIdsDigest','patternAuthority','artifactSha256','ownerConfigDigest','patternPublicationStatus'],'approved static binding');
 id:=p_template->>'templateId';
 if id is null or length(id) not between 1 and 160
  or jsonb_typeof(p_template->'staffingCount') is distinct from 'number'
  or (p_template->>'staffingCount')!~'^[1-9][0-9]?$'
  or jsonb_typeof(p_template->'source') is distinct from 'object'
  or jsonb_typeof(p_template->'roleSlotIds') is distinct from 'array'
  or jsonb_typeof(p_owner_config) is distinct from 'object'
  or jsonb_typeof(p_approval_evidence) is distinct from 'object'
  or p_binding->>'schema' is distinct from 'custodial.approved-static-template-binding.v1'
  or p_binding->>'templateId' is distinct from id
  or p_binding->'staffingCount' is distinct from p_template->'staffingCount'
  or p_binding->>'patternAuthority' is distinct from 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  or p_approval_evidence->>'classification' is distinct from 'OWNER_APPROVED_OPERATIONAL_PATTERN'
  or coalesce(p_approval_evidence->>'sourceReference','')=''
  or coalesce(p_approval_evidence->>'ownerDecisionReference','')=''
  or p_approval_evidence->>'artifactSha256' is distinct from p_binding->>'artifactSha256'
  or exists(select 1 from unnest(array['sourceDigest','roleSlotIdsDigest','artifactSha256','ownerConfigDigest']) key
     where coalesce(p_binding->>key,'')!~'^[0-9a-f]{64}$') then
  raise exception using errcode='23514',message='exact approved artifact, owner decision and complete template/config binding required';end if;
 count_people:=(p_template->>'staffingCount')::integer;
 if count_people not between 1 and 32 or jsonb_array_length(p_template->'roleSlotIds')<>count_people
  or exists(select 1 from jsonb_array_elements(p_template->'roleSlotIds') item
      where jsonb_typeof(item) is distinct from 'string' or coalesce(item#>>'{}','')='')
  or (select count(distinct item#>>'{}') from jsonb_array_elements(p_template->'roleSlotIds') item)<>count_people then
  raise exception using errcode='23514',message='approved role identities must be complete and unique';end if;
 body:=jsonb_build_object('template',p_template,'binding',p_binding,'ownerConfig',p_owner_config,'approvalEvidence',p_approval_evidence);
 entry_digest:=public.static_weekly_digest_jsonb(body);
 select * into prior from public.static_weekly_approved_template_catalog where template_id=id;
 if found then
  if prior.catalog_entry_digest is distinct from entry_digest then
   raise exception using errcode='23505',message='approved template ID already binds different immutable bytes';end if;
 else
  insert into public.static_weekly_approved_template_catalog
   (template_id,staffing_count,template_json,binding_json,owner_config,approval_evidence,catalog_entry_digest)
   values(id,count_people,p_template,p_binding,p_owner_config,p_approval_evidence,entry_digest);
 end if;
 if exists(select 1 from public.static_weekly_approved_template_retirements where template_id=id) then
  raise exception using errcode='23514',message='retired template cannot be readmitted under the same identity';end if;
 insert into public.static_weekly_approved_template_source_configs(source_id,owner_config,config_digest)
  values(p_source_id,p_owner_config,public.static_weekly_digest_jsonb(p_owner_config)) on conflict(source_id) do nothing;
 if not exists(select 1 from public.static_weekly_approved_template_source_configs
   where source_id=p_source_id and owner_config=p_owner_config and config_digest=public.static_weekly_digest_jsonb(p_owner_config)) then
  raise exception using errcode='23505',message='current source already binds a different owner configuration';end if;
 return jsonb_build_object('registered',true,'template_id',id,'catalog_entry_digest',entry_digest,'published',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v13_begin_recurring_confirmation(p_manager_id uuid, p_confirmation_key uuid, p_effective_start date, p_expected_revision bigint, p_preview_digest text, p_full_nine_source_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_request jsonb; v_digest text; v_revision bigint;
  v_parent public.static_weekly_recurring_confirmations%rowtype;
  v_receipt jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);
  if p_confirmation_key is null or p_effective_start is null
    or extract(isodow from p_effective_start)<>1 or not isfinite(p_effective_start)
    or p_expected_revision is null or p_expected_revision<0
    or p_preview_digest is null or p_preview_digest!~'^[0-9a-f]{64}$'
    or (p_full_nine_source_id is not null
      and p_full_nine_source_id<>'a00cdf2a-0623-5e2d-bc65-338c1dd67202'::uuid) then
    raise exception using errcode='22023',message='exact recurring confirmation request required';
  end if;
  v_request:=jsonb_build_object('schema','static-weekly.recurring-confirmation-request.v1',
    'managerId',p_manager_id,'confirmationKey',p_confirmation_key,
    'effectiveStart',p_effective_start,'expectedRevision',p_expected_revision,
    'previewDigest',p_preview_digest,'fullNineSourceId',p_full_nine_source_id);
  v_digest:=public.static_weekly_digest_jsonb(v_request);

  -- Reread a same-key parent BEFORE time/revision staleness. A committed retry
  -- must not accidentally compile/publish against today's roster.
  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key for update;
  if found then
    if v_parent.request_digest<>v_digest or v_parent.request_json<>v_request then
      raise exception using errcode='23505',message='recurring confirmation idempotency conflict';
    end if;
    select receipt_json into v_receipt from public.static_weekly_recurring_confirmation_receipts
      where operation_id=v_parent.operation_id;
    if v_receipt is not null then
      return jsonb_build_object('state','ACCEPTED','operationId',v_parent.operation_id,'receipt',v_receipt);
    end if;
    if v_parent.owner_xid<>pg_current_xact_id() then
      raise exception using errcode='23514',message='incomplete recurring confirmation from another transaction';
    end if;
    return jsonb_build_object('state','RESERVED','operationId',v_parent.operation_id,'requestDigest',v_digest);
  end if;
  if p_effective_start<=public.sch_service_date(statement_timestamp()) then
    raise exception using errcode='23514',message='new recurring plan must start on a future zoo-local Monday';
  end if;
  select current_revision into v_revision from public.static_weekly_schedule_control where singleton for update;
  if v_revision is distinct from p_expected_revision then
    raise exception using errcode='40001',message='recurring confirmation authority revision changed';
  end if;
  insert into public.static_weekly_recurring_confirmations(manager_id,confirmation_key,
    request_json,request_digest,effective_start,expected_revision,preview_digest,full_nine_source_id)
  values(p_manager_id,p_confirmation_key,v_request,v_digest,p_effective_start,p_expected_revision,
    p_preview_digest,p_full_nine_source_id) returning * into v_parent;
  return jsonb_build_object('state','RESERVED','operationId',v_parent.operation_id,'requestDigest',v_digest);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v13_read_recurring_confirmation(p_manager_id uuid, p_confirmation_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_parent public.static_weekly_recurring_confirmations%rowtype;v_receipt jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);
  if p_confirmation_key is null then raise exception using errcode='22023',message='exact recurring confirmation key required';end if;

  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key;
  if not found then return jsonb_build_object('state','NOT_FOUND','confirmationKey',p_confirmation_key);end if;
  select receipt_json into v_receipt from public.static_weekly_recurring_confirmation_receipts
    where operation_id=v_parent.operation_id;
  if v_receipt is null then
    raise exception using errcode='23514',message='recurring confirmation has not committed a complete receipt';
  end if;
  return jsonb_build_object('state','ACCEPTED','operationId',v_parent.operation_id,'receipt',v_receipt);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v14_admit_recurring_source(p_manager_id uuid, p_confirmation_key uuid, p_canonical_source jsonb, p_source_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_parent public.static_weekly_recurring_confirmations%rowtype;
  v_binding public.static_weekly_recurring_source_bindings%rowtype;
  v_digest text;v_identity text;v_source_id uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);

  select * into v_parent from public.static_weekly_recurring_confirmations
    where manager_id=p_manager_id and confirmation_key=p_confirmation_key for update;
  if not found or v_parent.owner_xid<>pg_current_xact_id()
    or exists(select 1 from public.static_weekly_recurring_confirmation_receipts where operation_id=v_parent.operation_id) then
    raise exception using errcode='42501',message='recurring source requires this transaction''s uncompleted named-manager reservation';
  end if;
  if p_canonical_source is null or jsonb_typeof(p_canonical_source) is distinct from 'object'
    or jsonb_typeof(p_canonical_source->'version') is distinct from 'object'
    or p_canonical_source ? 'versions'
    or p_canonical_source->'exceptions' is distinct from '[]'::jsonb
    or p_canonical_source#>'{version,namedAbsentSlotIds}' is distinct from '[]'::jsonb
    or p_canonical_source->>'serviceDate' is distinct from v_parent.effective_start::text
    or p_canonical_source#>>'{version,effectiveStart}' is distinct from v_parent.effective_start::text
    or p_canonical_source#>'{version,effectiveEnd}' is distinct from 'null'::jsonb
    or p_source_digest is null or p_source_digest!~'^[0-9a-f]{64}$' then
    raise exception using errcode='23514',message='recurring source must match the exact future exception-free candidate';
  end if;
  perform public.static_weekly_v3_source_identity(p_canonical_source);
  v_digest:=public.static_weekly_digest_jsonb(p_canonical_source);
  if p_source_digest<>v_digest then
    raise exception using errcode='23514',message='recurring source digest does not match actual inserted bytes';
  end if;
  select * into v_binding from public.static_weekly_recurring_source_bindings where operation_id=v_parent.operation_id;
  if found then
    if v_binding.owner_xid<>pg_current_xact_id() or v_binding.source_digest<>v_digest
      or not exists(select 1 from public.static_weekly_authority_source_documents
        where source_id=v_binding.source_id and source_digest=v_digest and canonical_source=p_canonical_source) then
      raise exception using errcode='23505',message='recurring parent already binds different source bytes';
    end if;
    return jsonb_build_object('source_id',v_binding.source_id,'source_digest',v_digest,'operation_id',v_parent.operation_id);
  end if;
  v_identity:=public.static_weekly_digest_text('static-weekly.recurring-source.v1:'||p_manager_id||':'||p_confirmation_key||':'||v_digest);
  -- Stable RFC-variant UUID identity from parent semantic identity + actual
  -- bytes. Rollback/retry does not pick a different registered source UUID.
  v_source_id:=(substr(v_identity,1,8)||'-'||substr(v_identity,9,4)||'-5'||substr(v_identity,14,3)||'-a'||substr(v_identity,18,3)||'-'||substr(v_identity,21,12))::uuid;
  insert into public.static_weekly_authority_source_documents(source_id,canonical_source,source_digest,configured_by)
    values(v_source_id,p_canonical_source,v_digest,'recurring-confirmation:'||v_parent.operation_id);
  insert into public.static_weekly_recurring_source_bindings(source_id,operation_id,source_digest)
    values(v_source_id,v_parent.operation_id,v_digest);
  return jsonb_build_object('source_id',v_source_id,'source_digest',v_digest,'operation_id',v_parent.operation_id);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v15_advance_recurring_generation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_table_name='employees' then
    if tg_op='UPDATE' and new.active is not distinct from old.active
      and new.display_name is not distinct from old.display_name
      and new.employee_code is not distinct from old.employee_code then return null;end if;
    if tg_op='INSERT' and new.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=new.id) then return null;end if;
    if tg_op='DELETE' and old.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=old.id) then return null;end if;
    if tg_op='UPDATE' and new.employee_code!~'^EMP[0-9]+$' and old.employee_code!~'^EMP[0-9]+$' and not exists(select 1 from public.weekly_roster_slot_incumbencies i where i.person_id=new.id) then return null;end if;
  elsif tg_table_name='static_weekly_authority_source_documents' then
    -- Registration is immutable evidence, not schedule activation. Retirement
    -- or corruption/change of a selected source does invalidate preview basis.
    if tg_op='INSERT' then return null;end if;
    if tg_op='UPDATE' and new.active is not distinct from old.active
      and new.retired_at is not distinct from old.retired_at
      and new.canonical_source is not distinct from old.canonical_source
      and new.source_digest is not distinct from old.source_digest then return null;end if;
  elsif tg_op='UPDATE' and to_jsonb(new)=to_jsonb(old) then return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  update public.static_weekly_recurring_generation set generation=generation+1,
    changed_at=statement_timestamp() where singleton;
  if not found then raise exception 'recurring generation singleton is missing';end if;

  perform public.static_weekly_v21_track_dependency_change(tg_table_name,tg_op,
   case when tg_op='INSERT' then null else to_jsonb(old) end,
   case when tg_op='DELETE' then null else to_jsonb(new) end);

  return null;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v15_read_recurring_generation()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_generation bigint;
begin
  perform public.static_weekly_v3_assert_control_plane();
  select generation into strict v_generation from public.static_weekly_recurring_generation where singleton;
  return v_generation;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v17_recurring_dependency_snapshot(p_source_id uuid, p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_source public.static_weekly_authority_source_documents%rowtype;
  v_slots jsonb;v_roster jsonb;v_body jsonb;
begin
  if p_source_id is null or p_week_start is null or not isfinite(p_week_start)
    or extract(isodow from p_week_start)<>1 then
    raise exception using errcode='22023',message='recurring dependency snapshot requires one source and Monday';
  end if;
  select * into v_source from public.static_weekly_authority_source_documents where source_id=p_source_id;
  if not found then raise exception using errcode='23514',message='recurring dependency source is unknown';end if;
  if jsonb_typeof(v_source.canonical_source->'slots') is distinct from 'array'
    or jsonb_array_length(v_source.canonical_source->'slots')=0
    or v_source.source_digest<>public.static_weekly_digest_jsonb(v_source.canonical_source) then
    raise exception using errcode='23514',message='recurring dependency source bytes are not intact';
  end if;
  if exists(select 1 from jsonb_array_elements(v_source.canonical_source->'slots') s
      where s->>'id' is null or not pg_input_is_valid(s->>'id','uuid')
        or (s ? 'contractorCapacity' and jsonb_typeof(s->'contractorCapacity') is distinct from 'boolean'))
    or (select count(*)<>count(distinct s->>'id') from jsonb_array_elements(v_source.canonical_source->'slots') s) then
    raise exception using errcode='23514',message='recurring dependency source requires exact unique registered positions';
  end if;
  if (select count(*)<>count(distinct (s->>'id')::uuid) from jsonb_array_elements(v_source.canonical_source->'slots') s)
    or exists(select 1 from jsonb_array_elements(v_source.canonical_source->'slots') s
    left join public.weekly_roster_slots r on r.slot_id=(s->>'id')::uuid where r.slot_id is null) then
    raise exception using errcode='23514',message='recurring dependency source requires exact unique registered positions';
  end if;
  select jsonb_agg(jsonb_build_object('slotId',r.slot_id,'slotCode',r.slot_code,
    'slotLabel',r.slot_label,'contractorCapacity',coalesce(s->'contractorCapacity','false'::jsonb)) order by r.slot_id)
    into v_slots from jsonb_array_elements(v_source.canonical_source->'slots') s
    join public.weekly_roster_slots r on r.slot_id=(s->>'id')::uuid;
  if exists(
    select s->>'slotId',p_week_start+offset_day
    from jsonb_array_elements(v_slots) s cross join generate_series(0,6) offset_day
    join public.v_weekly_roster_slot_incumbency_ranges i on i.slot_id=(s->>'slotId')::uuid
      and i.effective_start<=p_week_start+offset_day
      and (i.effective_end is null or p_week_start+offset_day<i.effective_end)
    group by s->>'slotId',p_week_start+offset_day having count(*)>1
  ) then raise exception using errcode='23514',message='recurring dependency position has ambiguous dated incumbency';end if;
  select jsonb_agg(jsonb_build_object('slotId',s->'slotId','serviceDate',(p_week_start+offset_day)::text,
      'incumbencyId',i.incumbency_id,'personId',i.person_id,'incumbentName',i.person_name_snapshot,
      'employeeExists',e.id is not null,'employeeActive',e.active,
      'employeeName',e.display_name,'employeeCode',e.employee_code,
      'staffingPersonId',staffing.employee_id,'staffingState',staffing.staffing_state)
    order by s->>'slotId',offset_day) into v_roster
  from jsonb_array_elements(v_slots) s cross join generate_series(0,6) offset_day
  left join public.v_weekly_roster_slot_incumbency_ranges i on i.slot_id=(s->>'slotId')::uuid
    and i.effective_start<=p_week_start+offset_day
    and (i.effective_end is null or p_week_start+offset_day<i.effective_end)
  left join public.employees e on e.id=i.person_id
  left join lateral (select r.employee_id,r.staffing_state
    from public.weekly_roster_slot_staffing_states r where r.slot_id=(s->>'slotId')::uuid
      and r.effective_start<=p_week_start+offset_day
    order by r.effective_start desc,r.authority_revision desc limit 1) staffing on true;
  v_body:=jsonb_build_object('schema','static-weekly.recurring-dependency-snapshot.v1',
    'sourceId',v_source.source_id,'sourceDigest',v_source.source_digest,
    'sourceActive',v_source.active,'sourceRetiredAt',to_char(v_source.retired_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'weekStart',p_week_start,'weekEnd',p_week_start+6,'slots',v_slots,'roster',v_roster);
  return jsonb_build_object('snapshot',v_body,'digest',public.static_weekly_digest_jsonb(v_body));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v18_bind_recurring_publication(p_manager_id uuid, p_confirmation_key uuid, p_publication_id uuid, p_expected_generation bigint, p_decision jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_parent public.static_weekly_recurring_confirmations%rowtype;
 v_source public.static_weekly_recurring_source_bindings%rowtype;
 v_publication public.weekly_schedule_publications%rowtype;
 v_version public.weekly_schedule_versions%rowtype;
 v_existing public.static_weekly_recurring_publication_bindings%rowtype;
 v_dependencies jsonb;v_generation bigint;v_predecessor uuid;v_digest text;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  perform public.static_weekly_v3_manager_actor(p_manager_id);

 select * into v_parent from public.static_weekly_recurring_confirmations
  where manager_id=p_manager_id and confirmation_key=p_confirmation_key;
 if not found or v_parent.owner_xid<>pg_current_xact_id()
  or exists(select 1 from public.static_weekly_recurring_confirmation_receipts where operation_id=v_parent.operation_id) then
  raise exception using errcode='42501',message='publication binding requires this transaction''s pending recurring parent';end if;
 select * into v_source from public.static_weekly_recurring_source_bindings where operation_id=v_parent.operation_id;
 select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id;
 select * into v_version from public.weekly_schedule_versions where version_id=v_publication.version_id;
 if v_source.source_id is null or v_source.owner_xid<>pg_current_xact_id()
  or v_publication.publication_id is null or v_publication.actor_manager_id is distinct from p_manager_id
  or v_publication.idempotency_key is distinct from 'recurring:'||p_manager_id||':'||p_confirmation_key||':publish'
  or v_publication.effective_start is distinct from v_parent.effective_start
  or v_publication.effective_start<=public.sch_service_date(statement_timestamp())
  or v_version.authority_source_id is distinct from v_source.source_id
  or public.static_weekly_effective_version(v_parent.effective_start) is distinct from v_version.version_id then
  raise exception using errcode='23514',message='recurring publication binding must name its exact current parent-bound child';end if;
 select generation into strict v_generation from public.static_weekly_recurring_generation where singleton;
 if p_expected_generation is null or p_expected_generation<>v_generation then
  raise exception using errcode='40001',message='recurring dependency generation changed before publication binding';end if;
 perform public.static_weekly_assert_exact_object(p_decision,
  array['schema','implementationDigest','effectiveDate','timezone','compilerVersion','candidateSourceDigest',
    'recurringAvailabilityDigest','geographyDigest','assignments','gaps','fixedLunch','metrics','changes'],
  array['schema','implementationDigest','effectiveDate','timezone','compilerVersion','candidateSourceDigest',
    'recurringAvailabilityDigest','geographyDigest','assignments','gaps','fixedLunch','metrics','changes','shiftEnd'],
  'recurring displayed decision');
 if p_decision->>'schema' is distinct from 'memphis-zoo.recurring-manager-decision.v1'
  or p_decision->>'effectiveDate' is distinct from v_parent.effective_start::text
  or p_decision->>'timezone' is distinct from 'America/Chicago'
  or p_decision->>'candidateSourceDigest' is distinct from v_source.source_digest
  or p_decision->>'implementationDigest'!~'^[0-9a-f]{64}$'
  or p_decision->>'compilerVersion' is distinct from v_version.draft_document#>>'{authority,optimizerResult,compilerVersion}'
  or p_decision->'metrics' is distinct from v_version.draft_document#>'{authority,optimizerResult,metrics}'
  or jsonb_typeof(p_decision->'assignments') is distinct from 'array'
  or jsonb_typeof(p_decision->'fixedLunch') is distinct from 'object'
  or jsonb_typeof(p_decision->'gaps') is distinct from 'object'
  or jsonb_typeof(p_decision->'changes') is distinct from 'array'
  or not (p_decision ? 'shiftEnd') then
  raise exception using errcode='23514',message='recurring displayed decision does not match its attested publication';end if;
 -- Compare every canonical assignment byte by identity, independent of SQL
 -- collation and Node's stable sort. No browser-supplied subset is accepted.
 if jsonb_array_length(p_decision->'assignments')=0
  or (select count(*)<>count(distinct a->>'planWorkId') from jsonb_array_elements(p_decision->'assignments') a)
  or exists(with displayed as (
    select a->>'planWorkId' id,public.static_weekly_v18_canonical_display_assignment(a) body
    from jsonb_array_elements(p_decision->'assignments') a
   ),attested as (
    select a->>'planWorkId' id,a body from jsonb_array_elements(v_version.draft_document#>'{authority,optimizerResult,assignments}') a
   ) select 1 from displayed d full join attested a using(id) where d.id is null or a.id is null or d.body is distinct from a.body) then
  raise exception using errcode='23514',message='recurring displayed assignments differ from the complete attested publication';end if;
 v_dependencies:=public.static_weekly_v17_recurring_dependency_snapshot(v_source.source_id,v_parent.effective_start);
 if v_dependencies#>'{snapshot,sourceActive}' is distinct from 'true'::jsonb
  or v_dependencies#>>'{snapshot,sourceDigest}' is distinct from v_source.source_digest then
  raise exception using errcode='23514',message='recurring publication source is no longer active and intact';end if;
 v_digest:=public.static_weekly_digest_jsonb(p_decision);
 select publication_id into v_predecessor from public.weekly_schedule_publications where version_id=v_publication.prior_version_id;
 select * into v_existing from public.static_weekly_recurring_publication_bindings where operation_id=v_parent.operation_id;
 if found then
  if v_existing.publication_id is distinct from p_publication_id or v_existing.owner_xid<>pg_current_xact_id()
   or v_existing.decision_json is distinct from p_decision or v_existing.decision_digest<>v_digest
   or v_existing.recurring_generation<>v_generation or v_existing.dependency_snapshot is distinct from v_dependencies->'snapshot'
   or v_existing.dependency_digest is distinct from v_dependencies->>'digest' then
   raise exception using errcode='23505',message='recurring parent already binds different publication dependencies';end if;
 else
  insert into public.static_weekly_recurring_publication_bindings(publication_id,operation_id,source_id,source_digest,
   effective_start,recurring_generation,predecessor_publication_id,implementation_digest,decision_json,decision_digest,
   dependency_snapshot,dependency_digest)
  values(p_publication_id,v_parent.operation_id,v_source.source_id,v_source.source_digest,v_parent.effective_start,
   v_generation,v_predecessor,p_decision->>'implementationDigest',p_decision,v_digest,v_dependencies->'snapshot',v_dependencies->>'digest');
 end if;
 return jsonb_build_object('state','BOUND_PENDING_FINALIZATION','publicationId',p_publication_id,
  'operationId',v_parent.operation_id,'recurringGeneration',v_generation,'dependencyDigest',v_dependencies->>'digest',
  'decisionDigest',v_digest,'predecessorPublicationId',v_predecessor,'accepted',false,'affectedPhonesUpdated',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_ack_terminal_target(p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_revision bigint, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_terminal_intents%rowtype;a public.static_weekly_recurring_terminal_receipts%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 select * into t from public.static_weekly_recurring_terminal_intents where intent_id=p_intent;
 if not found or t.device_id is distinct from p_device or t.credential_id is distinct from p_credential
  or t.employee_id is distinct from p_employee or t.assignment_epoch is distinct from p_epoch
  or t.authority_revision is distinct from p_revision or t.target_digest is distinct from p_rendered_digest
  or p_applied_at is null or not isfinite(p_applied_at) or p_applied_at<t.created_at
  or p_applied_at>statement_timestamp()+interval '5 minutes' then
  raise exception using errcode='23514',message='terminal receipt must match exact principal target revision digest and time';end if;
 select * into a from public.static_weekly_recurring_terminal_receipts where intent_id=p_intent;
 if found then
  if a.rendered_digest is distinct from p_rendered_digest or a.applied_at is distinct from p_applied_at then
   raise exception using errcode='23505',message='terminal target already has a different receipt';end if;
 else
  insert into public.static_weekly_recurring_terminal_receipts(intent_id,rendered_digest,applied_at)
  values(p_intent,p_rendered_digest,p_applied_at) returning * into a;
 end if;
 -- An old exact receipt is retained history only. Selection always consults
 -- the latest winner/range, so this cannot acknowledge a later invalidation.
 return jsonb_build_object('intentId',a.intent_id,'receiptId',a.receipt_id,'applicationStatus','DEVICE_REPORTED_BLOCKED',
  'replacementCoverageReady',false,'receivedAt',a.received_at);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_invalidate_recurring_range(p_manager_id uuid, p_operation_id uuid, p_publication_id uuid, p_start date, p_end date, p_reason text, p_dependency_digest text, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb;v_request jsonb;v_prior public.static_weekly_recurring_invalidations%rowtype;
 v_binding public.static_weekly_recurring_publication_bindings%rowtype;v_revision bigint;v_id uuid:=gen_random_uuid();
 v_weekday date;v_count int:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 v_request:=jsonb_build_object('managerId',p_manager_id,'operationId',p_operation_id,'publicationId',p_publication_id,
  'start',p_start,'end',p_end,'reason',p_reason,'dependencyDigest',p_dependency_digest,'expectedRevision',p_expected_revision);
 select * into v_prior from public.static_weekly_recurring_invalidations where operation_id=p_operation_id;
 if found then
  if v_prior.request_json is distinct from v_request then raise exception using errcode='23505',message='recurring invalidation operation already binds a different request';end if;
  return jsonb_build_object('invalidationId',v_prior.invalidation_id,'authorityRevision',v_prior.authority_revision,'state','BLOCKED_RECURRING_AUTHORITY','replayed',true);
 end if;
 select * into v_binding from public.static_weekly_recurring_publication_bindings where publication_id=p_publication_id;
 if p_operation_id is null or v_binding.publication_id is null or p_start is null or not isfinite(p_start)
  or p_start<=public.sch_service_date(statement_timestamp())
  or p_start<v_binding.effective_start or (p_end is not null and (not isfinite(p_end) or p_end<=p_start))
  or p_reason is null or p_reason not in ('ROSTER_DEPENDENCY_CHANGED','SOURCE_RETIRED','RESTRICTION_DEPENDENCY_CHANGED')
  or p_dependency_digest is null or p_dependency_digest!~'^[0-9a-f]{64}$'
  or not exists(select 1 from public.v_weekly_schedule_effective_ranges r join public.weekly_schedule_publications p using(version_id)
   where p.publication_id=p_publication_id and r.effective_start<=p_start
    and (r.effective_end is null or (p_start<r.effective_end and p_end is not null and p_end<=r.effective_end))) then
  raise exception using errcode='23514',message='recurring invalidation requires the exact latest winner and an affected future range';end if;
 v_revision:=public.static_weekly_advance_authority(p_expected_revision,'invalidate_recurring',p_manager_id,
  v_actor->>'manager_name',p_operation_id,public.static_weekly_digest_jsonb(v_request));
 insert into public.static_weekly_recurring_invalidations(invalidation_id,operation_id,publication_id,effective_start,effective_end,
  authority_revision,reason_code,dependency_digest,actor_manager_id,request_json,request_digest)
 values(v_id,p_operation_id,p_publication_id,p_start,p_end,v_revision,p_reason,p_dependency_digest,p_manager_id,v_request,public.static_weekly_digest_jsonb(v_request));
 insert into public.static_weekly_recurring_invalidated_principals(invalidation_id,employee_id)
 select distinct v_id,(r->>'personId')::uuid from jsonb_array_elements(v_binding.dependency_snapshot->'roster') r
 join public.employees e on e.id=(r->>'personId')::uuid where r->>'personId' is not null;
 -- All known materialized weeks, not just the first seven days. The persistent
 -- range plus principals also covers dates/phones not materialized yet.
 for v_weekday in select distinct x.week_start+n from public.weekly_schedule_compiled_projections x
  cross join generate_series(0,6) n where x.publication_id=p_publication_id
   and x.week_start+n>=p_start and (p_end is null or x.week_start+n<p_end) order by 1 loop
  v_count:=v_count+public.static_weekly_v19_reconcile_terminal_date(v_weekday);
 end loop;
 return jsonb_build_object('invalidationId',v_id,'authorityRevision',v_revision,
  'state','BLOCKED_RECURRING_AUTHORITY','targetsCreated',v_count,'affectedPhonesUpdated',false,'replayed',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_read_terminal_target(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r public.static_weekly_recurring_invalidations%rowtype;t public.static_weekly_recurring_terminal_intents%rowtype;
 ack public.static_weekly_recurring_terminal_receipts%rowtype;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'terminal read requires one finite service date';end if;
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 r:=public.static_weekly_v19_current_terminal_range(p_date);if r.invalidation_id is null then return null;end if;
 select * into t from public.static_weekly_recurring_terminal_intents where invalidation_id=r.invalidation_id
  and service_date=p_date and employee_id=p_employee and device_id=p_device and credential_id=p_credential and assignment_epoch=p_epoch;
 if not found then return jsonb_build_object('targetType','BLOCKED_RECURRING_AUTHORITY','authorityRevision',r.authority_revision,
  'publicationId',r.publication_id,'invalidationId',r.invalidation_id,'applicationStatus','PENDING_TARGET_RECONCILIATION');end if;
 select * into ack from public.static_weekly_recurring_terminal_receipts where intent_id=t.intent_id;
 return jsonb_build_object('intentId',t.intent_id,'target',t.target_json,'targetDigest',t.target_digest,
  'applicationStatus',case when ack.intent_id is null then 'PENDING' else 'DEVICE_REPORTED_BLOCKED' end,
  'appliedAt',ack.applied_at,'receivedAt',ack.received_at,'replacementCoverageReady',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v19_reconcile_terminal_date(p_service_date date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_range public.static_weekly_recurring_invalidations%rowtype;person record;device record;
 v_target jsonb;v_intent uuid;v_count int:=0;v_has_device boolean;
begin
 if p_service_date is null or not isfinite(p_service_date) then raise exception 'terminal target requires one finite service date';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 v_range:=public.static_weekly_v19_current_terminal_range(p_service_date);
 if v_range.invalidation_id is null then return 0;end if;
 -- Capture currently incumbent people too: filling a position or assigning a
 -- first phone must not make an invalid recurring pattern look usable.
 insert into public.static_weekly_recurring_invalidated_principals(invalidation_id,employee_id)
 select distinct v_range.invalidation_id,r.person_id from public.static_weekly_recurring_publication_bindings b
 cross join lateral jsonb_array_elements(b.dependency_snapshot->'slots') s
 join public.v_weekly_roster_slot_incumbency_ranges r on r.slot_id=(s->>'slotId')::uuid
  and r.effective_start<=p_service_date and (r.effective_end is null or p_service_date<r.effective_end)
 join public.employees e on e.id=r.person_id where b.publication_id=v_range.publication_id
 on conflict do nothing;
 for person in select employee_id from public.static_weekly_recurring_invalidated_principals
  where invalidation_id=v_range.invalidation_id order by employee_id loop
  v_has_device:=false;
  for device in select d.id,c.credential_id,d.assignment_epoch from public.devices d
   join public.device_auth_credentials c on c.device_id=d.id and c.confirmed_at is not null
    and c.revoked_at is null and c.expires_at>statement_timestamp()
   where d.active=true and d.assigned_employee_id=person.employee_id order by d.id,c.credential_id loop
   v_has_device:=true;
   v_target:=jsonb_build_object('schema','static-weekly.recurring-terminal-target.v1',
    'targetType','BLOCKED_RECURRING_AUTHORITY','invalidationId',v_range.invalidation_id,
    'operationId',v_range.operation_id,'publicationId',v_range.publication_id,'serviceDate',p_service_date,
    'authorityRevision',v_range.authority_revision,'reasonCode',v_range.reason_code,
    'employeeId',person.employee_id,'deviceId',device.id,'credentialId',device.credential_id,'assignmentEpoch',device.assignment_epoch);
   insert into public.static_weekly_recurring_terminal_intents(invalidation_id,service_date,employee_id,
    device_id,credential_id,assignment_epoch,authority_revision,target_json,target_digest)
   values(v_range.invalidation_id,p_service_date,person.employee_id,device.id,device.credential_id,device.assignment_epoch,
    v_range.authority_revision,v_target,public.static_weekly_digest_jsonb(v_target)) on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end loop;
  if not v_has_device then
   v_target:=jsonb_build_object('schema','static-weekly.recurring-terminal-target.v1',
    'targetType','BLOCKED_RECURRING_AUTHORITY','invalidationId',v_range.invalidation_id,
    'operationId',v_range.operation_id,'publicationId',v_range.publication_id,'serviceDate',p_service_date,
    'authorityRevision',v_range.authority_revision,'reasonCode',v_range.reason_code,
    'employeeId',person.employee_id,'deviceId',null,'credentialId',null,'assignmentEpoch',null);
   insert into public.static_weekly_recurring_terminal_intents(invalidation_id,service_date,employee_id,
    authority_revision,target_json,target_digest)
   values(v_range.invalidation_id,p_service_date,person.employee_id,v_range.authority_revision,
    v_target,public.static_weekly_digest_jsonb(v_target)) on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end if;
 end loop;
 return v_count;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v20_read_recurring_preview_basis(p_manager uuid, p_week date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_winner public.weekly_schedule_publications%rowtype;v_pattern record;v_invalidations jsonb;
 v_revision bigint;v_context jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager);
 if p_week is null or not isfinite(p_week) or extract(isodow from p_week)<>1
  or p_week<=public.sch_service_date(statement_timestamp()) then
  raise exception using errcode='22023',message='recurring repair preview requires one future Monday';end if;
 select * into v_winner from public.weekly_schedule_publications
  where version_id=public.static_weekly_effective_version(p_week);
 if not found then raise exception using errcode='23514',message='recurring preview has no effective publication';end if;
 select jsonb_agg(jsonb_build_object('invalidationId',i.invalidation_id,'authorityRevision',i.authority_revision,
  'effectiveStart',i.effective_start,'effectiveEnd',i.effective_end,'reasonCode',i.reason_code)
  order by i.authority_revision,i.invalidation_id) into v_invalidations
 from public.static_weekly_recurring_invalidations i where i.publication_id=v_winner.publication_id
  and i.effective_start<=p_week+6 and (i.effective_end is null or p_week<i.effective_end);
 if v_invalidations is null then return public.static_weekly_v3_read_publication_source(v_winner.publication_id,p_week);end if;
 select p.publication_id,p.version_id,v.authority_source_id,s.source_digest,v.draft_document into v_pattern
 from public.weekly_schedule_publications p join public.weekly_schedule_versions v using(version_id)
 join public.static_weekly_authority_source_documents s on s.source_id=v.authority_source_id
 where p.authority_revision<v_winner.authority_revision and p.effective_start<=p_week
  and s.active=true and s.retired_at is null and s.source_digest=public.static_weekly_digest_jsonb(s.canonical_source)
  and not exists(select 1 from public.static_weekly_recurring_invalidations i where i.publication_id=p.publication_id
   and i.effective_start<=p_week+6 and (i.effective_end is null or p_week<i.effective_end))
 order by p.effective_start desc,p.authority_revision desc limit 1;
 if not found then raise exception using errcode='23514',message='no preceding valid registered source pattern is available for recurring repair';end if;
 select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
 v_context:=jsonb_build_object('schema','static-weekly.recurring-repair-basis.v1',
  'state','REPLACING_INVALID_FUTURE','effectivePublicationId',v_winner.publication_id,
  'patternPublicationId',v_pattern.publication_id,'patternSourceId',v_pattern.authority_source_id,
  'patternSourceDigest',v_pattern.source_digest,'effectiveStart',p_week,'authorityRevision',v_revision,
  'invalidations',v_invalidations,'managerConfirmationRequired',true,'published',false);
 return jsonb_build_object('source_id',v_pattern.authority_source_id,
  'compiler_input',public.static_weekly_v4_hydrate_compiler_source(v_pattern.draft_document#>'{authority,compilerInput}',p_week),
  'exceptions','[]'::jsonb,'publication_id',v_pattern.publication_id,'version_id',v_pattern.version_id,
  'authority_revision',v_revision,'repair_context',v_context,'repair_context_digest',public.static_weekly_digest_jsonb(v_context));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v21_first_changed_dependency_date(p_publication uuid, p_week date)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b public.static_weekly_recurring_publication_bindings%rowtype;v_current jsonb;v_date date;
begin
 select * into strict b from public.static_weekly_recurring_publication_bindings where publication_id=p_publication;
 v_current:=public.static_weekly_v17_recurring_dependency_snapshot(b.source_id,p_week)->'snapshot';
 if (v_current-array['weekStart','weekEnd','roster']) is distinct from
  (b.dependency_snapshot-array['weekStart','weekEnd','roster']) then return p_week;end if;
 select min((actual->>'serviceDate')::date) into v_date from jsonb_array_elements(v_current->'roster') actual
 where not exists(select 1 from jsonb_array_elements(b.dependency_snapshot->'roster') expected
  where expected->>'slotId'=actual->>'slotId'
   and extract(isodow from (expected->>'serviceDate')::date)=extract(isodow from (actual->>'serviceDate')::date)
   and (actual-'serviceDate')=(expected-'serviceDate'));
 return v_date;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v21_reconcile_dependency_changes(p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_ids uuid[];v_binding record;v_week date;v_date date;v_first date;v_revision bigint;
 v_source public.static_weekly_authority_source_documents%rowtype;v_result jsonb;v_checked jsonb:='[]';
 v_effects jsonb:='[]';v_dependency jsonb;v_existing public.static_weekly_recurring_invalidations%rowtype;
 v_day date;v_state jsonb;v_count int;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 select array_agg(c.change_id order by c.generation,c.change_id) into v_ids
 from public.static_weekly_recurring_dependency_changes c where c.owner_xid=pg_current_xact_id()
  and not exists(select 1 from public.static_weekly_recurring_dependency_checks done where done.change_id=c.change_id);
 if cardinality(v_ids)>0 then
  for v_binding in select b.*,r.effective_end from public.static_weekly_recurring_publication_bindings b
   join public.weekly_schedule_publications p using(publication_id)
   join public.v_weekly_schedule_effective_ranges r using(version_id)
   where r.effective_start>public.sch_service_date(statement_timestamp())
   order by r.effective_start,b.publication_id loop
   v_first:=null;
   for v_week in select distinct week_start from (
    select v_binding.effective_start week_start
    union all
    select date_trunc('week',field.value::date::timestamp)::date
    from public.static_weekly_recurring_dependency_changes c
    cross join lateral (values(c.before_json),(c.after_json)) body(value)
    cross join lateral jsonb_each_text(body.value) field
    where c.change_id=any(v_ids) and field.key in ('effective_start','effective_end','closed_at_effective_date')
     and field.value is not null and pg_input_is_valid(field.value,'date')
     and isfinite(field.value::date)
   ) weeks where week_start>=v_binding.effective_start
    and (v_binding.effective_end is null or week_start<v_binding.effective_end) order by week_start loop
    v_date:=public.static_weekly_v21_first_changed_dependency_date(v_binding.publication_id,v_week);
    if v_date is not null and (v_binding.effective_end is null or v_date<v_binding.effective_end) then
     v_first:=least(v_first,v_date);end if;
   end loop;
   v_checked:=v_checked||jsonb_build_array(jsonb_build_object('publicationId',v_binding.publication_id,'firstChangedDate',v_first));
   if v_first is null then continue;end if;
   select * into v_existing from public.static_weekly_recurring_invalidations i where i.publication_id=v_binding.publication_id
    and i.effective_start<=v_first and (i.effective_end is null or (v_binding.effective_end is not null and i.effective_end>=v_binding.effective_end))
    order by i.authority_revision desc limit 1;
   if found then
    -- An already terminal winner stays terminal; new/current principals still
    -- acquire their exact pending targets. Do not fabricate another revision.
    for v_day in select distinct x.week_start+n from public.weekly_schedule_compiled_projections x
     cross join generate_series(0,6) n where x.publication_id=v_binding.publication_id
      and x.week_start+n>=v_existing.effective_start
      and (v_existing.effective_end is null or x.week_start+n<v_existing.effective_end) order by 1 loop
     perform public.static_weekly_v19_reconcile_terminal_date(v_day);
    end loop;
    v_effects:=v_effects||jsonb_build_array(jsonb_build_object('invalidationId',v_existing.invalidation_id,
     'publicationId',v_binding.publication_id,'authorityRevision',v_existing.authority_revision,'state','BLOCKED_RECURRING_AUTHORITY','existing',true));
   else
    select * into strict v_source from public.static_weekly_authority_source_documents where source_id=v_binding.source_id;
    select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
    v_week:=date_trunc('week',v_first::timestamp)::date;
    v_dependency:=public.static_weekly_v17_recurring_dependency_snapshot(v_binding.source_id,v_week);
    v_state:=public.static_weekly_v19_invalidate_recurring_range(p_manager_id,gen_random_uuid(),v_binding.publication_id,
     v_first,v_binding.effective_end,case when not v_source.active or v_source.retired_at is not null then 'SOURCE_RETIRED' else 'ROSTER_DEPENDENCY_CHANGED' end,
     v_dependency->>'digest',v_revision);
    v_effects:=v_effects||jsonb_build_array(v_state||jsonb_build_object('publicationId',v_binding.publication_id));
   end if;
  end loop;
  select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
  v_result:=jsonb_build_object('schema','static-weekly.recurring-dependency-reconciliation.v1',
   'changeIds',to_jsonb(v_ids),'processedByManagerId',p_manager_id,'authorityRevision',v_revision,
   'checkedPublications',v_checked,'invalidations',v_effects,'affectedPhonesUpdated',false);
  insert into public.static_weekly_recurring_dependency_checks(change_id,processed_by_manager_id,result_json,result_digest)
   select id,p_manager_id,v_result,public.static_weekly_digest_jsonb(v_result) from unnest(v_ids) id;
 end if;
 -- Return current future blocked state separately from any historical accepted
 -- mutation response, including an exact retry with no new dependency changes.
 select coalesce(jsonb_agg(jsonb_build_object('publicationId',p.publication_id,'invalidationId',i.invalidation_id,
  'effectiveStart',i.effective_start,'effectiveEnd',i.effective_end,'authorityRevision',i.authority_revision,
  'state','BLOCKED_RECURRING_AUTHORITY') order by r.effective_start,i.authority_revision),'[]'::jsonb) into v_state
 from public.v_weekly_schedule_effective_ranges r join public.weekly_schedule_publications p using(version_id)
 join public.static_weekly_recurring_invalidations i on i.publication_id=p.publication_id
 where r.effective_start>public.sch_service_date(statement_timestamp());
 select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
 return jsonb_build_object('processedChangeCount',coalesce(cardinality(v_ids),0),'authorityRevision',v_revision,
  'invalidations',v_effects,'blockedPublications',v_state,'affectedPhonesUpdated',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v21_track_dependency_change(p_table text, p_operation text, p_before jsonb, p_after jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_keys text[];v_before jsonb;v_after jsonb;
begin
 -- Publishing a separately validated version changes generation but is not
 -- a staffing edit. Registration and semantic no-ops are filtered by v15.
 if p_table='weekly_schedule_publications' then return;end if;
 if not exists(select 1 from public.static_weekly_recurring_publication_bindings b
  join public.weekly_schedule_publications p using(publication_id)
  join public.v_weekly_schedule_effective_ranges r using(version_id)
  where r.effective_start>public.sch_service_date(statement_timestamp())) then return;end if;
 v_keys:=case p_table
  when 'employees' then array['id','employee_code','display_name','active']
  when 'weekly_roster_slots' then array['slot_id','slot_code','slot_label']
  when 'weekly_roster_slot_incumbencies' then array['incumbency_id','slot_id','person_id','person_name_snapshot','effective_start','effective_end']
  when 'weekly_roster_slot_incumbency_closures' then array['incumbency_closure_id','closed_incumbency_id','replacement_incumbency_id','closed_at_effective_date']
  when 'weekly_roster_slot_staffing_states' then array['staffing_state_id','slot_id','employee_id','staffing_state','effective_start']
  when 'static_weekly_authority_source_documents' then array['source_id','active','retired_at','source_digest'] end;
 if v_keys is null or p_operation not in ('INSERT','UPDATE','DELETE') then raise exception 'unknown recurring dependency change';end if;
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into v_before from jsonb_each(coalesce(p_before,'{}'::jsonb)) where key=any(v_keys);
 select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) into v_after from jsonb_each(coalesce(p_after,'{}'::jsonb)) where key=any(v_keys);
 if p_table='static_weekly_authority_source_documents' then
  -- Record exact content identity without copying the large private source.
  v_before:=v_before||jsonb_build_object('canonical_source_digest',public.static_weekly_digest_jsonb(p_before->'canonical_source'));
  v_after:=v_after||jsonb_build_object('canonical_source_digest',public.static_weekly_digest_jsonb(p_after->'canonical_source'));
 end if;
 if v_before=v_after then return;end if;
 insert into public.static_weekly_recurring_dependency_changes(generation,origin_table,origin_operation,origin_session_user,before_json,after_json)
 select generation,p_table,p_operation,session_user,v_before,v_after from public.static_weekly_recurring_generation where singleton;
 if not found then raise exception 'recurring dependency generation unavailable';end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_ack_recurring_application_target(p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_revision bigint, p_target_digest text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_application_intents%rowtype;r public.static_weekly_recurring_application_receipts%rowtype;
begin
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='recurring schedule requires an active employee principal';end if;
 select * into t from public.static_weekly_recurring_application_intents where intent_id=p_intent for share;
 if not found or t.device_id is distinct from p_device or t.credential_id is distinct from p_credential
  or t.employee_id is distinct from p_employee or t.assignment_epoch is distinct from p_epoch
  or t.authority_revision is distinct from p_revision or t.target_digest is distinct from p_target_digest
  or t.view_digest is distinct from p_rendered_digest or p_applied_at is null or not isfinite(p_applied_at)
  or p_applied_at<t.created_at or p_applied_at>clock_timestamp()+interval '5 minutes' then
  raise exception using errcode='23514',message='recurring receipt requires exact principal target rendered-view revision and time';end if;
 select * into r from public.static_weekly_recurring_application_receipts where intent_id=p_intent;
 if found then
  if r.rendered_digest is distinct from p_rendered_digest or r.applied_at is distinct from p_applied_at then
   raise exception using errcode='23505',message='recurring target already has a different receipt';end if;
 else
  insert into public.static_weekly_recurring_application_receipts(intent_id,rendered_digest,applied_at)
   values(p_intent,p_rendered_digest,p_applied_at) returning * into r;
 end if;
 -- This is an immutable historical receipt. The merged reader, not this
 -- response, decides whether it still applies to the CURRENT desired state.
 return jsonb_build_object('intentId',p_intent,'receiptId',r.receipt_id,'applicationStatus','DEVICE_REPORTED_APPLIED',
  'currentAuthorityNotInferred',true,'appliedAt',r.applied_at,'receivedAt',r.received_at);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_read_recurring_application_target(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_application_intents%rowtype;receipt public.static_weekly_recurring_application_receipts%rowtype;a record;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'recurring application read requires finite date';end if;
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='recurring schedule requires an active employee principal';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status='blocked_recurring_authority' then return public.static_weekly_v19_read_terminal_target(p_date,p_device,p_credential,p_employee,p_epoch);end if;
 select * into t from public.static_weekly_recurring_application_intents i
  where i.service_date=p_date and i.device_id=p_device and i.credential_id=p_credential
   and i.employee_id=p_employee and i.assignment_epoch=p_epoch
  order by i.authority_revision desc,i.created_at desc,i.intent_id desc limit 1;
 if not found then
  if exists(select 1 from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id) then
   return jsonb_build_object('applicationStatus','PENDING_TARGET_RECONCILIATION','affectedPhonesUpdated',false);end if;
  return null;
 end if;
 if a.projection_status is distinct from 'current' or t.publication_id is distinct from a.publication_id
  or t.projection_id is distinct from a.projection_id or t.authority_revision is distinct from a.projection_authority_revision then
  return jsonb_build_object('applicationStatus','PENDING_TARGET_RECONCILIATION','affectedPhonesUpdated',false);end if;
 select * into receipt from public.static_weekly_recurring_application_receipts where intent_id=t.intent_id;
 return jsonb_build_object('intentId',t.intent_id,'target',t.target_json,'targetDigest',t.target_digest,
  'view',t.view_json,'viewJsonText',t.view_json::text,'viewDigest',t.view_digest,
  'applicationStatus',case when receipt.intent_id is null then 'PENDING' else 'DEVICE_REPORTED_APPLIED' end,
  'receiptId',receipt.receipt_id,'appliedAt',receipt.applied_at,'receivedAt',receipt.received_at);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_reconcile_recurring_application_date(p_date date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;b public.static_weekly_recurring_publication_bindings%rowtype;
 p public.static_weekly_recurring_confirmations%rowtype;l public.weekly_schedule_lunch_documents%rowtype;
person record;device record;v_view jsonb;v_target jsonb;v_view_digest text;v_intent uuid;v_count int:=0;v_devices int;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'recurring application reconciliation requires one finite date';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status='blocked_recurring_authority' then return public.static_weekly_v19_reconcile_terminal_date(p_date);end if;
 if a.projection_status is distinct from 'current' or a.projection_id is null then raise exception 'recurring schedule projection is unavailable';end if;
 select * into b from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id;
 if not found then return 0;end if; -- old release-registered workflow is not relabeled recurring acceptance
 select * into strict p from public.static_weekly_recurring_confirmations where operation_id=b.operation_id;
 if not exists(select 1 from public.static_weekly_recurring_confirmation_receipts r where r.operation_id=b.operation_id)
  and (b.owner_xid<>pg_current_xact_id() or p.owner_xid<>pg_current_xact_id()) then
  raise exception 'unaccepted recurring parent cannot create phone targets';end if;
 select * into l from public.weekly_schedule_lunch_documents where projection_id=a.projection_id;
 if not found then raise exception 'exact recurring lunch companion is unavailable';end if;
 for person in with people as (
  select (r->>'personId')::uuid employee_id from jsonb_array_elements(b.dependency_snapshot->'roster') r
   where r->>'personId' is not null and extract(isodow from (r->>'serviceDate')::date)=extract(isodow from p_date)
  union
  select (r->>'personId')::uuid from public.static_weekly_recurring_publication_bindings prior
   cross join lateral jsonb_array_elements(prior.dependency_snapshot->'roster') r
   where prior.publication_id=b.predecessor_publication_id and r->>'personId' is not null
    and extract(isodow from (r->>'serviceDate')::date)=extract(isodow from p_date)
  union
  select x.owner_person_id_snapshot from public.weekly_schedule_occurrences x
   join public.weekly_schedule_compiled_projections projection using(projection_id)
   where projection.publication_id in (a.publication_id,b.predecessor_publication_id) and x.service_date=p_date
    and x.owner_person_id_snapshot is not null
  union
  select (r->>'normal_owner_person_id')::uuid from public.weekly_schedule_lunch_documents lunch
   join public.weekly_schedule_compiled_projections projection using(projection_id)
   cross join lateral jsonb_array_elements(lunch.document_json->'responsibilities') r
   where projection.publication_id in (a.publication_id,b.predecessor_publication_id)
    and r->>'service_date'=p_date::text and r->>'normal_owner_person_id' is not null
  union
  select (r->>'coverer_person_id')::uuid from public.weekly_schedule_lunch_documents lunch
   join public.weekly_schedule_compiled_projections projection using(projection_id)
   cross join lateral jsonb_array_elements(lunch.document_json->'responsibilities') r
   where projection.publication_id in (a.publication_id,b.predecessor_publication_id)
    and r->>'service_date'=p_date::text and r->>'coverer_person_id' is not null
 ) select distinct people.employee_id from people join public.employees e on e.id=people.employee_id order by people.employee_id loop
  v_view:=public.static_weekly_v22_recurring_render_view(a.projection_id,p_date,person.employee_id);
  v_view_digest:=public.static_weekly_digest_jsonb(v_view);v_devices:=0;
  -- Rotation/reconnect must not silently create a different view at the same
  -- authority identity, nor make ON CONFLICT hide changed display bytes.
  if exists(select 1 from public.static_weekly_recurring_application_intents i
   where i.publication_id=a.publication_id and i.projection_id=a.projection_id
    and i.service_date=p_date and i.employee_id=person.employee_id
    and i.authority_revision=a.projection_authority_revision
    and (i.view_json is distinct from v_view or i.view_digest is distinct from v_view_digest
      or i.lunch_document_identity is distinct from l.document_identity)) then
   raise exception using errcode='23514',message='recurring render changed without a new exact authority identity';end if;
  for device in select d.id,c.credential_id,d.assignment_epoch from public.devices d
   join public.device_auth_credentials c on c.device_id=d.id and c.confirmed_at is not null
    and c.revoked_at is null and c.expires_at>statement_timestamp()
   where d.active=true and d.assigned_employee_id=person.employee_id
   order by d.id,c.credential_id loop
   v_devices:=v_devices+1;
   v_target:=jsonb_build_object('schema','static-weekly.recurring-application-target.v1','targetType','SCHEDULE',
    'operationId',b.operation_id,'publicationId',a.publication_id,'projectionId',a.projection_id,'serviceDate',p_date,
    'authorityRevision',a.projection_authority_revision,'lunchDocumentIdentity',l.document_identity,
    'employeeId',person.employee_id,'deviceId',device.id,'credentialId',device.credential_id,
    'assignmentEpoch',device.assignment_epoch,'viewDigest',v_view_digest);
   insert into public.static_weekly_recurring_application_intents(operation_id,publication_id,projection_id,service_date,
    employee_id,device_id,credential_id,assignment_epoch,authority_revision,lunch_document_identity,view_json,view_digest,target_json,target_digest)
   values(b.operation_id,a.publication_id,a.projection_id,p_date,person.employee_id,device.id,device.credential_id,
    device.assignment_epoch,a.projection_authority_revision,l.document_identity,v_view,v_view_digest,v_target,public.static_weekly_digest_jsonb(v_target))
   on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end loop;
  if v_devices=0 then
   v_target:=jsonb_build_object('schema','static-weekly.recurring-application-target.v1','targetType','SCHEDULE',
    'operationId',b.operation_id,'publicationId',a.publication_id,'projectionId',a.projection_id,'serviceDate',p_date,
    'authorityRevision',a.projection_authority_revision,'lunchDocumentIdentity',l.document_identity,
    'employeeId',person.employee_id,'deviceId',null,'credentialId',null,'assignmentEpoch',null,'viewDigest',v_view_digest);
   insert into public.static_weekly_recurring_application_intents(operation_id,publication_id,projection_id,service_date,
    employee_id,authority_revision,lunch_document_identity,view_json,view_digest,target_json,target_digest)
   values(b.operation_id,a.publication_id,a.projection_id,p_date,person.employee_id,a.projection_authority_revision,
    l.document_identity,v_view,v_view_digest,v_target,public.static_weekly_digest_jsonb(v_target))
   on conflict do nothing returning intent_id into v_intent;
   if found then v_count:=v_count+1;end if;
  end if;
 end loop;
 return v_count;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v22_recurring_render_view(p_projection uuid, p_date date, p_employee uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;d jsonb;
begin
 if p_date is null or not isfinite(p_date) or p_projection is null or p_employee is null then raise exception 'exact recurring render principal date and projection required';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status is distinct from 'current' or a.projection_id is distinct from p_projection then
  raise exception using errcode='23514',message='recurring view requires the exact current usable projection';end if;
 d:=public.static_weekly_v5_read_employee_day(p_date,p_employee,(p_date::timestamp+interval '12 hours') at time zone 'America/Chicago');
 if d->>'projection_status' is distinct from 'current' or d->>'projection_id' is distinct from p_projection::text
  or d->>'employee_id' is distinct from p_employee::text or d->>'service_date' is distinct from p_date::text
  or jsonb_typeof(d->'all_items') is distinct from 'array' then
  raise exception using errcode='23514',message='recurring full-day render source is unavailable';end if;
 return jsonb_build_object('schema','static-weekly.recurring-render-view.v1','service_date',p_date,
  'employee_id',p_employee,'employee_name',d->'employee_name','publication_id',a.publication_id,
  'projection_id',p_projection,'projection_status','current','full_day',true,
  'shift',d->'shift','raw_items',d->'all_items');
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v23_finalize_recurring_confirmation(p_manager uuid, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p public.static_weekly_recurring_confirmations%rowtype;b public.static_weekly_recurring_publication_bindings%rowtype;
 r public.static_weekly_recurring_confirmation_receipts%rowtype;l public.weekly_schedule_lunch_documents%rowtype;
 a record;day_authority record;v_revision bigint;v_generation bigint;v_day date;v_manifest jsonb;v_receipt jsonb;v_count integer;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v3_manager_actor(p_manager);
 select * into p from public.static_weekly_recurring_confirmations where manager_id=p_manager and confirmation_key=p_key for update;
 if not found then raise exception 'recurring finalizer requires exact named-manager parent';end if;
 select * into r from public.static_weekly_recurring_confirmation_receipts where operation_id=p.operation_id;
 if found then return r.receipt_json;end if; -- immutable history before current staleness
 if p.owner_xid<>pg_current_xact_id() or p.effective_start<=public.sch_service_date(statement_timestamp()) then
  raise exception 'recurring finalizer requires this transaction and future effective Monday';end if;
 select * into b from public.static_weekly_recurring_publication_bindings where operation_id=p.operation_id;
 select generation into strict v_generation from public.static_weekly_recurring_generation where singleton;
 select current_revision into strict v_revision from public.static_weekly_schedule_control where singleton;
 if b.operation_id is null or b.owner_xid<>pg_current_xact_id() or b.recurring_generation<>v_generation
  or b.decision_digest<>public.static_weekly_digest_jsonb(b.decision_json)
  or b.dependency_digest<>public.static_weekly_digest_jsonb(b.dependency_snapshot)
  or public.static_weekly_v21_first_changed_dependency_date(b.publication_id,p.effective_start) is not null then
  raise exception using errcode='40001',message='recurring finalization dependency or decision changed';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p.effective_start);
 if a.projection_status is distinct from 'current' or a.publication_id is distinct from b.publication_id
  or a.projection_id is null or a.projection_authority_revision is distinct from v_revision then
  raise exception 'recurring finalization requires exact current projection and revision';end if;
 if not exists(select 1 from public.weekly_schedule_command_receipts c
  join public.weekly_schedule_publications publication on publication.publication_id=b.publication_id
  where c.actor_manager_id=p_manager and c.command_type='materialize_projection'
   and c.idempotency_key='recurring:'||p_manager||':'||p_key||':projection:'||p.effective_start
   and c.response_json#>>'{data,projection_id}'=a.projection_id::text
   and (c.response_json->>'revision')::bigint=v_revision
   and c.expected_revision=publication.authority_revision
   and c.response_digest=c.response_json->>'output_digest'
   and c.response_digest=public.static_weekly_digest_jsonb(c.response_json-'output_digest')) then
  raise exception 'recurring finalization requires its exact projection child receipt';end if;
 select * into l from public.weekly_schedule_lunch_documents where projection_id=a.projection_id;
 if not found or l.accepted_by_manager_id is distinct from p_manager then
  raise exception 'recurring finalization requires its exact named-manager lunch companion';end if;
 -- The complete initial week is materialized atomically. The ongoing bounded
 -- reconciliation path must separately populate future materialized weeks.
 for v_day in select p.effective_start+offset_day from generate_series(0,6) offset_day loop
  select * into day_authority from public.static_weekly_v6_schedule_authority_state(v_day);
  if day_authority.projection_status is distinct from 'current' or day_authority.publication_id is distinct from b.publication_id
   or day_authority.projection_id is distinct from a.projection_id or day_authority.projection_authority_revision is distinct from v_revision then
   raise exception 'recurring finalization week contains a different or blocked authority';end if;
  perform public.static_weekly_v22_reconcile_recurring_application_date(v_day);
 end loop;
 select jsonb_agg(jsonb_build_object('intentId',i.intent_id,'serviceDate',i.service_date,
  'employeeId',i.employee_id,'deviceId',i.device_id,'credentialId',i.credential_id,'assignmentEpoch',i.assignment_epoch,
  'targetDigest',i.target_digest,'viewDigest',i.view_digest) order by i.service_date,i.employee_id,i.device_id nulls first,i.credential_id nulls first,i.intent_id),
  count(distinct i.service_date)::int into v_manifest,v_count
 from public.static_weekly_recurring_application_intents i
 where i.operation_id=p.operation_id and i.publication_id=b.publication_id and i.projection_id=a.projection_id
  and i.authority_revision=v_revision and i.service_date between p.effective_start and p.effective_start+6;
 if v_manifest is null or v_count<>7 then raise exception 'recurring finalization requires complete durable initial-week phone targets';end if;
 insert into public.static_weekly_recurring_acceptance_proofs(operation_id,publication_id,projection_id,accepted_revision,
  decision_digest,dependency_digest,target_manifest,target_manifest_digest)
 values(p.operation_id,b.publication_id,a.projection_id,v_revision,b.decision_digest,b.dependency_digest,v_manifest,public.static_weekly_digest_jsonb(v_manifest));
 v_receipt:=jsonb_build_object('schema','static-weekly.recurring-confirmation-receipt.v1',
  'operationId',p.operation_id,'managerId',p.manager_id,'confirmationKey',p.confirmation_key,'requestDigest',p.request_digest,
  'previewDigest',p.preview_digest,'effectiveStart',p.effective_start,'sourceId',b.source_id,'sourceDigest',b.source_digest,
  'publicationId',b.publication_id,'projectionId',a.projection_id,'authorityRevision',v_revision,'lunchDocumentIdentity',l.document_identity,
  'accepted',true,'phoneDeliveryState','PENDING','affectedPhonesUpdated',false);
 insert into public.static_weekly_recurring_confirmation_receipts(operation_id,source_id,source_digest,publication_id,
  projection_id,accepted_revision,lunch_document_identity,receipt_json,receipt_digest)
 values(p.operation_id,b.source_id,b.source_digest,b.publication_id,a.projection_id,v_revision,l.document_identity,v_receipt,
  public.static_weekly_digest_jsonb(v_receipt));
 return v_receipt;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v24_ack_device_schedule_delivery(p_intent uuid, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint, p_target_type text, p_revision bigint, p_target_digest text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare t public.static_weekly_recurring_application_intents%rowtype;
 terminal public.static_weekly_recurring_terminal_intents%rowtype;dated record;v_result jsonb;
begin
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='schedule delivery requires an active employee principal';end if;
 if p_target_type='BLOCKED_RECURRING_AUTHORITY' then
  select * into terminal from public.static_weekly_recurring_terminal_intents where intent_id=p_intent;
  if not found or p_target_digest is distinct from terminal.target_digest
   or p_rendered_digest is distinct from p_target_digest then
   raise exception using errcode='23514',message='terminal delivery receipt requires exact target bytes';end if;
  v_result:=public.static_weekly_v19_ack_terminal_target(p_intent,p_device,p_credential,p_employee,p_epoch,
   p_revision,p_rendered_digest,p_applied_at);
 elsif p_target_type='SCHEDULE' then
  v_result:=public.static_weekly_v22_ack_recurring_application_target(p_intent,p_device,p_credential,p_employee,p_epoch,
   p_revision,p_target_digest,p_rendered_digest,p_applied_at);
  select * into strict t from public.static_weekly_recurring_application_intents where intent_id=p_intent;
  -- A dated absence/cancellation may use the same current recurring winner.
  -- Preserve its existing manager delivery receipt only for the EXACT same
  -- principal, date, revision, projection and lunch just applied. Caller
  -- supplies no dated operation/intent identity. Old/different targets remain
  -- history; no fabricated ACK on enqueue, provider acceptance or new device.
  for dated in select i.* from public.static_weekly_schedule_application_intents i
   join public.static_weekly_staffing_commands c on c.operation_id=i.operation_id and c.state='ACCEPTED'
   where i.service_date=t.service_date and i.employee_id=t.employee_id and i.device_id=t.device_id
    and i.credential_id=t.credential_id and i.assignment_epoch=t.assignment_epoch
    and i.authority_revision=t.authority_revision and i.publication_id=t.publication_id
    and i.projection_id=t.projection_id and i.lunch_document_identity=t.lunch_document_identity
    and not exists(select 1 from public.static_weekly_schedule_application_receipts r where r.intent_id=i.intent_id)
   order by i.intent_id loop
   perform public.static_weekly_v10_ack_device_schedule_application(dated.intent_id,p_device,p_credential,p_employee,p_epoch,
    p_revision,t.projection_id,t.lunch_document_identity,p_rendered_digest,p_applied_at);
  end loop;
 else raise exception using errcode='22023',message='exact typed schedule delivery receipt required';end if;
 return jsonb_build_object('schema','static-weekly.device-schedule-delivery-receipt.v1','receipt',v_result,
  'currentAuthorityNotInferred',true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v24_read_device_schedule_delivery(p_date date, p_device uuid, p_credential uuid, p_employee uuid, p_epoch bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a record;v_delivery jsonb;v_dated jsonb;
begin
 if p_date is null or not isfinite(p_date) then raise exception 'schedule delivery requires one finite service date';end if;
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 perform public.static_weekly_v19_assert_terminal_principal(p_device,p_credential,p_employee,p_epoch);
 if not exists(select 1 from public.employees where id=p_employee and active=true) then
  raise exception using errcode='42501',message='schedule delivery requires an active employee principal';end if;
 select * into a from public.static_weekly_v6_schedule_authority_state(p_date);
 if a.projection_status='blocked_recurring_authority' then
  -- Terminal wins before any older dated or recurring schedule is considered.
  v_delivery:=public.static_weekly_v19_read_terminal_target(p_date,p_device,p_credential,p_employee,p_epoch);
  if v_delivery->>'intentId' is null then
   perform public.static_weekly_v19_reconcile_terminal_date(p_date);
   v_delivery:=public.static_weekly_v19_read_terminal_target(p_date,p_device,p_credential,p_employee,p_epoch);
  end if;
  return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','RECURRING_TERMINAL',
   'delivery',v_delivery,'datedApplication',null,'affectedPhonesUpdated',false);
 end if;
 if exists(select 1 from public.static_weekly_recurring_publication_bindings where publication_id=a.publication_id) then
  if a.projection_status is distinct from 'current' then
   return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','UNAVAILABLE',
    'projectionStatus',a.projection_status,'delivery',null,'datedApplication',null,'affectedPhonesUpdated',false);
  end if;
  v_delivery:=public.static_weekly_v22_read_recurring_application_target(p_date,p_device,p_credential,p_employee,p_epoch);
  if v_delivery->>'intentId' is null then
   -- Reconcile only a missing current identity. Existing immutable views do
   -- not need all-person reconstruction on every connected phone poll.
   perform public.static_weekly_v22_reconcile_recurring_application_date(p_date);
   v_delivery:=public.static_weekly_v22_read_recurring_application_target(p_date,p_device,p_credential,p_employee,p_epoch);
  end if;
  return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','RECURRING_SCHEDULE',
   'delivery',v_delivery,'datedApplication',null,'affectedPhonesUpdated',false);
 end if;
 -- Existing release-registered/dated workflow stays separate. Never use an
 -- old dated target with a different exact current publication/projection.
 v_dated:=public.static_weekly_v10_read_device_schedule_application(p_date,p_device,p_credential,p_employee,p_epoch);
 if a.projection_status is distinct from 'current'
  or v_dated->>'publication_id' is distinct from a.publication_id::text
  or v_dated->>'projection_id' is distinct from a.projection_id::text
  or v_dated->>'authority_revision' is distinct from a.projection_authority_revision::text then v_dated:=null;end if;
 return jsonb_build_object('schema','static-weekly.device-schedule-delivery.v1','mode','LEGACY_REGISTERED',
  'delivery',null,'datedApplication',v_dated,'affectedPhonesUpdated',false);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v27_read_home_time_facts(p_date date, p_employee uuid, p_publication uuid, p_projection uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare rec jsonb:=public.custodial_dated_record(p_date);roster jsonb;working boolean;
begin
 if p_date is null or p_employee is null or p_publication is null or p_projection is null then return null;end if;
 if rec is null or rec->>'projectionStatus'<>'current' or rec->>'publicationId'<>p_publication::text or rec->>'projectionId'<>p_projection::text then return null;end if;
 select r into roster from jsonb_array_elements(public.custodial_dated_rows('roster',p_date)) r where r->>'employee_id'=p_employee::text;
 if roster is null then return null;end if;working:=roster->>'active'='true';
 return jsonb_build_object('contract_version','employee-home-time-facts.v1','service_date',p_date,'employee_id',p_employee,
  'employee_name',roster->>'employee_name','projection_status','current','projection_id',p_projection,'publication_id',p_publication,
  'candidate_revision',rec->>'phonePdfRevision','source','static_weekly_projection','reason',null,
  'schedule_status',case when working then 'scheduled' else 'off' end,
  'shift',case when working then jsonb_build_object('active',true,'start',roster->>'shift_start','end',roster->>'shift_end',
   'shift_start',roster->>'shift_start','shift_end',roster->>'shift_end','lunch_start',roster->>'lunch_start','lunch_end',roster->>'lunch_end') else jsonb_build_object('active',false) end,
  'lunch',case when working then jsonb_build_object('start',roster->>'lunch_start','end',roster->>'lunch_end') else null end);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v2_create_draft(p_effective_start date, p_objective_version text, p_objective jsonb, p_input_provenance jsonb, p_document jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_command uuid:=gen_random_uuid(); v_version uuid; v_content_digest text; v_revision bigint; v_response jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'create_draft');
  v_request:=jsonb_build_object('operation','create_draft','effective_start',p_effective_start,'objective_version',p_objective_version,'objective_digest',public.static_weekly_digest_jsonb(p_objective),'input_provenance_digest',public.static_weekly_digest_jsonb(p_input_provenance),'document_identity',p_document#>>'{validation,database_document_identity}','expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_actor_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if p_effective_start is null or btrim(coalesce(p_objective_version,''))='' then raise exception using errcode='23514',message='complete draft command identity is required'; end if;
  perform public.static_weekly_assert_document_attested(p_document,p_effective_start,true);
  perform public.static_weekly_assert_exact_object(p_input_provenance,array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],array['adapter_schema','compiler_version','input_digest','baseline_input_digest','authority_digest','replay_digest'],'draft input provenance');
  if jsonb_typeof(p_objective) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_input_provenance) k(key) where jsonb_typeof(p_input_provenance->k.key) is distinct from 'string') or p_objective is distinct from p_document#>'{authority,optimizerResult,objective}' or p_objective_version is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'adapter_schema' is distinct from p_document#>>'{adapter,schema}' or p_input_provenance->>'compiler_version' is distinct from p_document#>>'{validation,compiler_version}' or p_input_provenance->>'input_digest' is distinct from p_document#>>'{validation,input_digest}' or p_input_provenance->>'baseline_input_digest' is distinct from p_document#>>'{authority,baselineInputDigest}' or p_input_provenance->>'authority_digest' is distinct from p_document#>>'{validation,authority_digest}' or p_input_provenance->>'replay_digest' is distinct from p_document#>>'{validation,replay_digest}' then raise exception using errcode='23514',message='draft command may use only attested adapter-derived objective and provenance'; end if;
  begin v_version:=(p_document#>>'{authority,compilerInput,version,id}')::uuid; exception when others then raise exception using errcode='23514',message='compiler weekly version identity must be a canonical UUID'; end;
  v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('objective_version',p_objective_version,'objective_digest',public.static_weekly_digest_jsonb(p_objective),'input_provenance_digest',public.static_weekly_digest_jsonb(p_input_provenance),'document_identity',p_document#>>'{validation,database_document_identity}'));
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'create_draft',p_actor_manager_id,p_actor_manager_name,v_command,v_content_digest);
  insert into public.weekly_schedule_versions(version_id,lifecycle_state,effective_start,objective_version,objective_json,input_provenance_json,draft_document,content_digest,created_by_manager_id,created_by_manager_name_snapshot) values(v_version,'draft',p_effective_start,p_objective_version,p_objective,p_input_provenance,p_document,v_content_digest,p_actor_manager_id,p_actor_manager_name);
  perform public.static_weekly_materialize_document(v_version,p_document,v_content_digest,p_actor_manager_id,p_actor_manager_name);
  v_response:=public.static_weekly_response_json('create_draft',v_revision,v_content_digest,v_request_digest,jsonb_build_object('version_id',v_version,'draft_revision',1,'effective_start',p_effective_start));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest) values(v_command,p_actor_manager_id,p_actor_manager_name,'create_draft',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest); return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v2_materialize_projection(p_publication_id uuid, p_service_date date, p_exception_set_digest text, p_compiler_version text, p_objective jsonb, p_metrics jsonb, p_replay_digest text, p_assignments jsonb, p_expected_revision bigint, p_actor_manager_id uuid, p_actor_manager_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_request jsonb; v_request_digest text; v_prior public.weekly_schedule_command_receipts%rowtype; v_publication public.weekly_schedule_publications%rowtype; v_effective_start date; v_effective_end date; v_exception_set jsonb; v_exception_digest text; v_command uuid:=gen_random_uuid(); v_projection uuid:=gen_random_uuid(); v_revision bigint; v_content_digest text; v_response jsonb; v_item jsonb; v_assignment public.weekly_schedule_slot_assignments%rowtype; v_owner public.v_weekly_roster_slot_incumbency_ranges%rowtype; v_occurrence uuid; v_work jsonb;
begin
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_actor_manager_id,p_actor_manager_name,p_idempotency_key,'materialize_projection'); v_request:=jsonb_build_object('operation','materialize_projection','publication_id',p_publication_id,'service_date',p_service_date,'exception_set_digest',p_exception_set_digest,'compiler_version',p_compiler_version,'objective',p_objective,'metrics',p_metrics,'replay_digest',p_replay_digest,'projection_envelope',p_assignments,'expected_revision',p_expected_revision,'actor_manager_id',p_actor_manager_id,'actor_manager_name',p_actor_manager_name); v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
