 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_start date; v_document jsonb; v_vacant jsonb:='[]'::jsonb; v_row record; v_person uuid; v_name text; v_date date; v_matches integer; v_is_vacant boolean;
begin
  select effective_start,draft_document into v_start,v_document from public.weekly_schedule_versions where version_id=p_version_id for share;
  if v_start is null then raise exception using errcode='23514',message='draft version does not exist'; end if;
  v_vacant:=coalesce(v_document#>'{authority,compilerInput,version,vacancyCapableSlotIds}','[]'::jsonb);
  if jsonb_typeof(v_vacant) is distinct from 'array' then raise exception using errcode='23514',message='draft vacancy authority must be an array'; end if;
  for v_row in select * from public.weekly_schedule_slot_availability where version_id=p_version_id order by day_of_week,slot_id loop
    v_date:=v_start+mod(v_row.day_of_week-extract(dow from v_start)::integer+7,7);
    select exists(select 1 from jsonb_array_elements_text(v_vacant) vacancy(slot_id) where vacancy.slot_id=v_row.slot_id::text) into v_is_vacant;
    select count(*) into v_matches from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
    if exists(select 1 from jsonb_array_elements(v_document#>'{authority,compilerInput,slots}') slot
      where slot->>'id'=v_row.slot_id::text and slot->>'kind'='CONTRACTOR_CAPACITY' and public.static_weekly_capacity_registered(slot)) then
      if v_matches<>0 or v_row.availability_state<>'unavailable'
        or v_row.incumbent_person_id_snapshot is not null or v_row.incumbent_name_snapshot is not null
        or v_is_vacant then
        raise exception using errcode='23514',message='recurring nonemployee capacity must remain unavailable with no person/vacancy';
      end if;
      continue;
    end if;
    if coalesce((v_document#>'{authority,compilerInput,version,vacantSlotIds}') ? v_row.slot_id::text,false) and v_matches<>0 then
      raise exception using errcode='23514',message='declared whole-week vacancy cannot hide an incumbent';
    end if;
    v_is_vacant:=v_is_vacant and v_matches=0;
    if v_is_vacant then
      if v_row.availability_state<>'vacant_unfilled' or v_matches<>0
        or v_row.incumbent_person_id_snapshot is not null or v_row.incumbent_name_snapshot is not null then
        raise exception using errcode='23514',message='vacant draft slot must retain its shift and lunch with zero incumbent identity';
      end if;
    else
      if v_row.availability_state='vacant_unfilled' or v_matches<>1 then
        raise exception using errcode='23514',message='non-vacant draft roster slot must resolve exactly one closure-aware incumbent at each service date';
      end if;
      select person_id,person_name_snapshot into v_person,v_name from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
      if v_row.incumbent_person_id_snapshot is distinct from v_person or v_row.incumbent_name_snapshot is distinct from v_name then
        raise exception using errcode='23514',message='draft roster incumbency snapshot is stale or incomplete at publication service date';
      end if;
    end if;
  end loop;
  for v_row in select * from public.weekly_schedule_slot_assignments where version_id=p_version_id order by day_of_week,assignment_id loop
    v_date:=v_start+mod(v_row.day_of_week-extract(dow from v_start)::integer+7,7);
    if nullif(v_row.payload_json#>>'{authority_facts,baseline_owner_slot_id}','') is not null then
      select exists(select 1 from jsonb_array_elements_text(v_vacant) vacancy(slot_id) where vacancy.slot_id=v_row.payload_json#>>'{authority_facts,baseline_owner_slot_id}') into v_is_vacant;
      select count(*) into v_matches from public.v_weekly_roster_slot_incumbency_ranges
        where slot_id=(v_row.payload_json#>>'{authority_facts,baseline_owner_slot_id}')::uuid
          and effective_start<=v_date and (effective_end is null or v_date<effective_end);
      if v_matches>1 or (v_matches=0 and not v_is_vacant) then
        raise exception using errcode='23514',message='baseline work requires a dated incumbent or registered vacancy capability';
      end if;
      v_is_vacant:=v_is_vacant and v_matches=0;
      if v_is_vacant and (v_row.status<>'open' or v_row.owner_slot_id is not null or v_row.owner_person_id_snapshot is not null
        or nullif(v_row.payload_json#>>'{authority_facts,baseline_owner_person_id}','') is not null) then
        raise exception using errcode='23514',message='vacant recurring work must remain OPEN with no invented owner or original actor';
      end if;
    end if;
    if v_row.owner_slot_id is not null then
      v_date:=v_start+mod(v_row.day_of_week-extract(dow from v_start)::integer+7,7);
      select count(*) into v_matches from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.owner_slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
      if v_matches<>1 then raise exception using errcode='23514',message='draft assignment owner must resolve exactly one closure-aware incumbent at each service date'; end if;
      select person_id,person_name_snapshot into v_person,v_name from public.v_weekly_roster_slot_incumbency_ranges where slot_id=v_row.owner_slot_id and effective_start<=v_date and (effective_end is null or v_date<effective_end);
      if v_row.owner_person_id_snapshot is distinct from v_person or v_row.owner_name_snapshot is distinct from v_name then raise exception using errcode='23514',message='draft recurring owner snapshot is stale or incomplete at publication service date'; end if;
    end if;
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_authority_source(p_source_id uuid, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_source jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  if p_source_id is null or p_service_date is null then
    raise exception using errcode='22023',message='scheduler source read requires one immutable source and service date';
  end if;
  select canonical_source into v_source
  from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active=true and retired_at is null
  for share;
  if not found then
    raise exception using errcode='23514',message='scheduler source is not an active release-registered source of record';
  end if;
  return jsonb_build_object(
    'source_id',p_source_id::text,
    'compiler_input',public.static_weekly_v4_hydrate_compiler_source(v_source,p_service_date),
    'exceptions','[]'::jsonb
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_manager_snapshot(p_week_start date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_snapshot jsonb;
  v_source jsonb;
  v_roster jsonb; v_terminal jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_snapshot:=public.static_weekly_v3_read_manager_snapshot_staffing_base(p_week_start);

  select jsonb_agg(jsonb_build_object('invalidationId',r.invalidation_id,'publicationId',r.publication_id,
    'authorityRevision',r.authority_revision,'effectiveStart',r.effective_start,'effectiveEnd',r.effective_end,
    'state','BLOCKED_RECURRING_AUTHORITY') order by r.authority_revision,r.invalidation_id) into v_terminal
  from (select distinct i.invalidation_id,i.publication_id,i.authority_revision,i.effective_start,i.effective_end
    from generate_series(0,6) offset_day
    cross join lateral public.static_weekly_v19_current_terminal_range(p_week_start+offset_day) i
    where i.invalidation_id is not null) r;
  if v_terminal is not null then
    return v_snapshot||jsonb_build_object('projection_status','blocked_recurring_authority',
      'latest_projection',null,'assignments','[]'::jsonb,'recurring_invalidations',v_terminal,
      'recurring_repair_required',true);
  end if;


  -- A draft or publication already binds its own immutable compiler input.
  if jsonb_typeof(v_snapshot->'display_version')='object' then
    return v_snapshot;
  end if;

  begin
    select s.canonical_source into strict v_source
    from public.static_weekly_authority_source_documents s
    where s.active=true;
  exception
    when no_data_found then
      raise exception using errcode='23514',message='initial manager snapshot requires one active registered recurring source';
    when too_many_rows then
      raise exception using errcode='23514',message='initial manager snapshot requires exactly one active registered recurring source';
  end;

  if jsonb_typeof(v_source->'slots')<>'array' then
    raise exception using errcode='23514',message='active registered recurring source has no canonical slot array';
  end if;

  select coalesce(jsonb_agg(
    item||jsonb_build_object(
      'contractor_capacity',coalesce((
        select lower(slot->>'contractorCapacity')='true'
        from jsonb_array_elements(v_source->'slots') slot
        where slot->>'id'=item->>'slot_id'
        limit 1
      ),false)
    ) order by item->>'slot_label',item->>'slot_id'
  ),'[]'::jsonb) into v_roster
  from jsonb_array_elements(coalesce(v_snapshot->'roster','[]'::jsonb)) item;

  return jsonb_set(v_snapshot,'{roster}',v_roster,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_read_publication_source(p_publication_id uuid, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_document jsonb; v_version uuid; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); perform public.static_weekly_v20_assert_usable_recurring_week(p_publication_id,p_service_date);
  select v.draft_document,p.version_id,v.authority_source_id into v_document,v_version,v_source
  from public.weekly_schedule_publications p
  join public.weekly_schedule_versions v on v.version_id=p.version_id
  where p.publication_id=p_publication_id;
  if not found or v_source is null or public.static_weekly_effective_version(p_service_date) is distinct from v_version then
    raise exception using errcode='23514',message='control plane source must name the effective immutable publication and registered source';
  end if;
  return jsonb_build_object(
    'source_id',v_source::text,
    'compiler_input',public.static_weekly_v4_hydrate_compiler_source(v_document#>'{authority,compilerInput}',p_service_date),
    'exceptions',public.static_weekly_compiler_exception_set(p_publication_id,p_service_date),
    'publication_id',p_publication_id::text,
    'version_id',v_version::text,
    'authority_revision',(select current_revision from public.static_weekly_schedule_control where singleton)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_update_draft(p_version_id uuid, p_document jsonb, p_objective jsonb, p_input_provenance jsonb, p_expected_draft_revision bigint, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_document jsonb; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.static_weekly_v14_assert_recurring_source_use((select authority_source_id from public.weekly_schedule_versions where version_id=p_version_id),p_manager_id,null,p_idempotency_key,'update'); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); select authority_source_id into v_source from public.weekly_schedule_versions where version_id=p_version_id and lifecycle_state='draft' for share; perform public.static_weekly_v3_assert_registered_source(v_source,p_document#>'{authority,compilerInput}');
  perform public.static_weekly_assert_compiler_authority(p_document->'authority',p_document->'receipt',(select effective_start from public.weekly_schedule_versions where version_id=p_version_id),true);
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v6_issue_document_attestation(p_document),true);
  return public.static_weekly_v2_update_draft(p_version_id,v_document,p_objective,p_input_provenance,p_expected_draft_revision,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_assert_projection_envelope_single_location_bas(p_envelope jsonb, p_publication_id uuid, p_week_start date, p_exception_set jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_authority jsonb:=p_envelope->'authority'; v_base jsonb; v_compiler_exceptions jsonb; v_publication public.weekly_schedule_publications%rowtype;
begin
  perform public.static_weekly_assert_exact_object(p_envelope,array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],array['adapter','service_date','week_start','week_end','authority','receipt','authority_digest','replay_digest','compiler_version','objective','metrics','applied_exceptions','assignments','database_projection_identity'],'projection envelope');
  perform public.static_weekly_assert_exact_object(p_envelope->'adapter',array['schema','version'],array['schema','version'],'projection envelope adapter');
  if jsonb_typeof(p_exception_set) is distinct from 'array' or jsonb_typeof(p_envelope->'service_date') is distinct from 'string'
    or jsonb_typeof(p_envelope->'week_start') is distinct from 'string' or jsonb_typeof(p_envelope->'week_end') is distinct from 'string'
    or jsonb_typeof(p_envelope->'authority_digest') is distinct from 'string' or jsonb_typeof(p_envelope->'replay_digest') is distinct from 'string'
    or jsonb_typeof(p_envelope->'compiler_version') is distinct from 'string' or jsonb_typeof(p_envelope->'objective') is distinct from 'object'
    or jsonb_typeof(p_envelope->'metrics') is distinct from 'object' or jsonb_typeof(p_envelope->'applied_exceptions') is distinct from 'array'
    or jsonb_typeof(p_envelope->'assignments') is distinct from 'array' or jsonb_typeof(p_envelope->'database_projection_identity') is distinct from 'string' then
    raise exception using errcode='23514',message='projection envelope requires complete typed authority, receipt, identity, and assignment fields';
  end if;
  if jsonb_array_length(p_envelope->'assignments')=0 then raise exception using errcode='23514',message='projection assignments may not be empty'; end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x) where jsonb_typeof(a.x) is distinct from 'object' or not (a.x ?& array['plan_work_id','work_id','day_of_week','service_date','status','work_snapshot','explanation'])) then
    raise exception using errcode='23514',message='projection assignments require every identity, status, snapshot, and explanation key';
  end if;
  if exists(select 1 from jsonb_array_elements(p_envelope->'assignments') as a(x)
      where jsonb_typeof(a.x->'plan_work_id') is distinct from 'string' or nullif(btrim(a.x->>'plan_work_id'),'') is null
        or jsonb_typeof(a.x->'work_id') is distinct from 'string' or nullif(btrim(a.x->>'work_id'),'') is null
        or jsonb_typeof(a.x->'day_of_week') is distinct from 'number' or (a.x->>'day_of_week') !~ '^[0-6]$'
        or jsonb_typeof(a.x->'service_date') is distinct from 'string' or nullif(btrim(a.x->>'service_date'),'') is null
        or (a.x->>'service_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not pg_input_is_valid(a.x->>'service_date','date')
        or case when jsonb_typeof(a.x->'service_date')='string' and (a.x->>'service_date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' and pg_input_is_valid(a.x->>'service_date','date') then (a.x->>'service_date')::date::text is distinct from a.x->>'service_date' or (a.x->>'service_date')::date<p_week_start or (a.x->>'service_date')::date>p_week_start+6 else false end
        or jsonb_typeof(a.x->'explanation') is distinct from 'object'
        or jsonb_typeof(a.x->'status') is distinct from 'string' or upper(a.x->>'status') not in ('ASSIGNED','OPEN','REVIEW')) then
    raise exception using errcode='23514',message='projection assignments require complete canonical seven-day identity, status, and explanation facts';
  end if;
  if (select count(*) from jsonb_array_elements(p_envelope->'assignments'))<>(select count(distinct x->>'plan_work_id') from jsonb_array_elements(p_envelope->'assignments') as a(x)) then
    raise exception using errcode='23514',message='projection assignments may not contain duplicate work identities';
  end if;
  select * into v_publication from public.weekly_schedule_publications where publication_id=p_publication_id;
  if not found then raise exception using errcode='23514',message='projection publication is unknown'; end if;
  select draft_document#>'{authority,compilerInput}' into v_base from public.weekly_schedule_versions where version_id=v_publication.version_id;
  v_compiler_exceptions:=public.static_weekly_compiler_exception_set(p_publication_id,p_week_start);
  perform public.static_weekly_assert_compiler_authority(v_authority,p_envelope->'receipt',p_week_start,false);
  if p_envelope #>> '{adapter,schema}' is distinct from p_envelope#>>'{receipt,schema}' or p_envelope #>> '{adapter,version}' is distinct from p_envelope#>>'{receipt,adapterVersion}' or p_envelope->>'service_date' is distinct from p_week_start::text or p_envelope->>'week_start' is distinct from p_week_start::text or p_envelope->>'week_end' is distinct from (p_week_start+6)::text
    or p_envelope->>'authority_digest' is distinct from public.static_weekly_digest_jsonb(v_authority) or p_envelope->>'replay_digest' is distinct from p_envelope #>>'{receipt,compiler,replayDigest}'
    or p_envelope->>'compiler_version' is distinct from v_authority #>>'{optimizerResult,compilerVersion}' or p_envelope->'objective' is distinct from v_authority #> '{optimizerResult,objective}' or p_envelope->'metrics' is distinct from v_authority #> '{optimizerResult,metrics}'
    or p_envelope->>'database_projection_identity' is distinct from public.static_weekly_digest_jsonb(p_envelope-'database_projection_identity')
    or public.static_weekly_v4_recurring_source_identity(v_authority->'compilerInput') is distinct from public.static_weekly_v4_recurring_source_identity(v_base) then
    raise exception using errcode='23514',message='projection must bind the stable registered source, complete dated receipt, objective, metrics, replay, and full weekly envelope';
  end if;
  if v_authority->'appliedExceptions' is distinct from p_exception_set or p_envelope->'applied_exceptions' is distinct from p_exception_set then
    raise exception using errcode='23514',message='overlay compiler input and applied exceptions must bind the complete accepted seven-day exception set';
  end if;
  if v_authority #> '{overlayCompilerInput,exceptions}' is distinct from v_compiler_exceptions then
    raise exception using errcode='23514',message='overlay compiler input must carry every semantic accepted exception fact for the same seven-day horizon';
  end if;
  if exists(with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')), projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o full join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where o.x is null or p.x is null or p.x->>'service_date' is distinct from o.x->>'serviceDate' or p.x->>'work_id' is distinct from o.x->>'workId' or p.x->>'day_of_week' is distinct from o.x->>'dayOfWeek' or upper(p.x->>'status') is distinct from upper(o.x->>'status')
      or (o.x->>'status'='ASSIGNED' and (p.x->>'owner_slot_id' is distinct from o.x->>'slotId' or p.x->>'owner_person_id' is distinct from o.x->>'personId'))
      or (o.x->>'status' in ('OPEN','REVIEW') and (p.x->>'owner_slot_id' is not null or p.x->>'owner_person_id' is not null))) then
    raise exception using errcode='23514',message='complete weekly projection assignments must exactly bind the canonical optimizer';
  end if;
  if exists(with optimizer as(select value x from jsonb_array_elements(v_authority #> '{optimizerResult,assignments}')), projected as(select value x from jsonb_array_elements(p_envelope->'assignments'))
    select 1 from optimizer o join projected p on p.x->>'plan_work_id'=o.x->>'planWorkId'
    where jsonb_typeof(p.x->'work_snapshot') is distinct from 'object'
      or not (p.x->'work_snapshot' ?& array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])
      or exists(select 1 from jsonb_object_keys(p.x->'work_snapshot') as k(key) where not (k.key=any(array['workId','dayOfWeek','originSlotId','locationId','locationCodeSnapshot','locationNameSnapshot','window','serviceEffortMinutes','serviceEffortProvenance','priority','priorityProvenance','required','coveragePolicy','bestEffortCoverage','coveragePolicyOrder','coveragePolicyProvenance','requiredQualifications','qualificationProvenance','restrictions','restrictionProvenance','restrictedSlotIds','manualLock','manualLockSlotId','overlayWork'])))
      or jsonb_typeof(p.x#>'{work_snapshot,workId}') is distinct from 'string' or jsonb_typeof(p.x#>'{work_snapshot,dayOfWeek}') is distinct from 'number' or jsonb_typeof(p.x#>'{work_snapshot,originSlotId}') not in ('string','null')
      or p.x#>>'{work_snapshot,workId}' is distinct from o.x->>'workId' or p.x#>>'{work_snapshot,dayOfWeek}' is distinct from o.x->>'dayOfWeek' or p.x#>>'{work_snapshot,window,start}' is distinct from o.x#>>'{window,start}' or p.x#>>'{work_snapshot,window,end}' is distinct from o.x#>>'{window,end}' or p.x#>>'{work_snapshot,serviceEffortMinutes}' is distinct from o.x->>'serviceEffortMinutes'
      or jsonb_typeof(p.x#>'{work_snapshot,locationId}') is distinct from 'string' or p.x#>>'{work_snapshot,locationId}' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      or jsonb_typeof(p.x#>'{work_snapshot,locationCodeSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationCodeSnapshot}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,locationNameSnapshot}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,locationNameSnapshot}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,window}') is distinct from 'object' or jsonb_typeof(p.x#>'{work_snapshot,window,start}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,start}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,window,end}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,window,end}'),'') is null
      or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortMinutes}') is distinct from 'number' or jsonb_typeof(p.x#>'{work_snapshot,serviceEffortProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,serviceEffortProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,priority}') is distinct from 'number'
      or jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}') not in ('string','null') or (jsonb_typeof(p.x#>'{work_snapshot,priorityProvenance}')='string' and nullif(btrim(p.x#>>'{work_snapshot,priorityProvenance}'),'') is null)
      or jsonb_typeof(p.x#>'{work_snapshot,required}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicy}') not in ('string','null') or jsonb_typeof(p.x#>'{work_snapshot,bestEffortCoverage}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyOrder}') not in ('number','null') or jsonb_typeof(p.x#>'{work_snapshot,coveragePolicyProvenance}') not in ('string','null')
      or jsonb_typeof(p.x#>'{work_snapshot,requiredQualifications}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,qualificationProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,qualificationProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,restrictions}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,restrictionProvenance}') is distinct from 'string' or nullif(btrim(p.x#>>'{work_snapshot,restrictionProvenance}'),'') is null or jsonb_typeof(p.x#>'{work_snapshot,restrictedSlotIds}') is distinct from 'array' or jsonb_typeof(p.x#>'{work_snapshot,manualLock}') is distinct from 'boolean' or jsonb_typeof(p.x#>'{work_snapshot,manualLockSlotId}') not in ('string','null') or jsonb_typeof(p.x#>'{work_snapshot,overlayWork}') is distinct from 'boolean'
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}') as q(value) where jsonb_typeof(q.value) is distinct from 'string' or nullif(btrim(q.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or exists(select 1 from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}') as r(value) where jsonb_typeof(r.value) is distinct from 'string' or nullif(btrim(r.value#>>'{}'),'') is null)
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,requiredQualifications}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictions}'))
      or (select count(*) from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))<>(select count(distinct value#>>'{}') from jsonb_array_elements(p.x#>'{work_snapshot,restrictedSlotIds}'))
  ) then raise exception using errcode='23514',message='projection work snapshots must be complete semantic authority facts bound to the canonical optimizer'; end if;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_hydrate_compiler_source(p_source jsonb, p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_slots jsonb:='[]'::jsonb;
  v_slot jsonb;
  v_ranges jsonb;
  v_hydrated jsonb;
  v_source_version jsonb;
  v_version jsonb;
  v_declared_vacant jsonb:='[]'::jsonb;
  v_active_vacant jsonb:='[]'::jsonb;
  v_availability jsonb:='[]'::jsonb;
  v_item jsonb;
  v_date date;
  v_week_start date;
  v_state text;
  v_slot_id text;
  v_is_declared_vacant boolean;
  v_is_active_vacant boolean;
begin
  if p_service_date is null or jsonb_typeof(p_source) is distinct from 'object' or jsonb_typeof(p_source->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='dated scheduler source requires one service date and stable slot array';
  end if;
  v_week_start:=p_service_date-(extract(isodow from p_service_date)::integer-1);
  if jsonb_typeof(p_source->'version')='object' then v_source_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then v_source_version:=(p_source->'versions')->0;
  else raise exception using errcode='23514',message='dated scheduler source must carry exactly one recurring version'; end if;
  if jsonb_typeof(coalesce(v_source_version->'vacancyCapableSlotIds','[]'::jsonb)) is distinct from 'array'
    or jsonb_typeof(coalesce(v_source_version->'vacantSlotIds','[]'::jsonb)) is distinct from 'array' then
    raise exception using errcode='23514',message='vacancy-capable and active-vacancy stable-slot authority must be arrays';
  end if;
  v_declared_vacant:=coalesce(v_source_version->'vacancyCapableSlotIds','[]'::jsonb);

  for v_slot in select value from jsonb_array_elements(p_source->'slots') loop
    if jsonb_typeof(v_slot->'id') is distinct from 'string' or v_slot->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      raise exception using errcode='23514',message='registered scheduler source contains a non-UUID stable roster slot identity';
    end if;
    v_slot_id:=v_slot->>'id';
    if v_slot->>'kind'='CONTRACTOR_CAPACITY' then
      perform public.static_weekly_capacity_assert_shape(v_slot);
      if not public.static_weekly_capacity_registered(v_slot)
        or exists(select 1 from public.weekly_roster_slot_incumbencies where slot_id=v_slot_id::uuid)
        or v_declared_vacant ? v_slot_id then
        raise exception using errcode='23514',message='nonemployee source capacity must match immutable registration and cannot hide an incumbent/vacancy';
      end if;
      v_slots:=v_slots||jsonb_build_array(v_slot);continue;
    end if;
    select coalesce(jsonb_agg(jsonb_build_object(
      'personId',r.person_id::text,'displayName',r.person_name_snapshot,
      'effectiveStart',r.effective_start::text,
      'effectiveEnd',case when r.effective_end is null then null else r.effective_end::text end
    ) order by r.effective_start,r.incumbency_id),'[]'::jsonb) into v_ranges
    from public.v_weekly_roster_slot_incumbency_ranges r
    where r.slot_id=v_slot_id::uuid and r.effective_start<=v_week_start+6
      and (r.effective_end is null or r.effective_end>v_week_start);
    select exists(select 1 from jsonb_array_elements_text(v_declared_vacant) vacancy(slot_id) where vacancy.slot_id=v_slot_id)
      into v_is_declared_vacant;
    if jsonb_array_length(v_ranges)=0 then
      if not v_is_declared_vacant then
        raise exception using errcode='23514',message='every non-vacant projected stable roster slot requires closure-aware incumbent history for the requested horizon';
      end if;
      v_active_vacant:=v_active_vacant||jsonb_build_array(v_slot_id);
    end if;
    v_slot:=jsonb_set(v_slot,'{incumbencies}',v_ranges,true);
    v_slots:=v_slots||jsonb_build_array(v_slot);
  end loop;

  v_hydrated:=jsonb_set(p_source,'{slots}',v_slots,true);
  if jsonb_typeof(v_hydrated->'version')='object' then v_version:=v_hydrated->'version';
  else v_version:=(v_hydrated->'versions')->0; end if;
  v_version:=jsonb_set(v_version,'{vacantSlotIds}',v_active_vacant,true);
  for v_item in select value from jsonb_array_elements(coalesce(v_version->'slotAvailability','[]'::jsonb)) loop
    v_slot_id:=v_item->>'slotId';
    if exists(select 1 from jsonb_array_elements(v_slots) slot where slot->>'id'=v_slot_id and slot->>'kind'='CONTRACTOR_CAPACITY') then
      if v_item->>'status' is distinct from 'unavailable' then
        raise exception using errcode='23514',message='registered contractor capacity cannot be activated by a recurring source';
      end if;
      v_availability:=v_availability||jsonb_build_array(v_item);continue;
    end if;
    v_date:=v_week_start+mod((v_item->>'dayOfWeek')::integer-extract(dow from v_week_start)::integer+7,7);
    select not exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges r
      where r.slot_id=v_slot_id::uuid and r.effective_start<=v_date
        and (r.effective_end is null or v_date<r.effective_end)) into v_is_active_vacant;
    if v_is_active_vacant and not (v_declared_vacant ? v_slot_id) then
      raise exception using errcode='23514',message='dated vacancy requires registered stable-slot capability';
    end if;
    if v_is_active_vacant then
      v_item:=jsonb_set(v_item,'{status}',to_jsonb('vacant_unfilled'::text),true);
    else
      select s.staffing_state into v_state from public.weekly_roster_slot_staffing_states s
      where s.slot_id=v_slot_id::uuid and s.effective_start<=v_date
      order by s.effective_start desc,s.authority_revision desc limit 1;
      if v_state='vacant_unfilled' then
        raise exception using errcode='23514',message='vacant staffing state conflicts with an effective incumbent';
      end if;
      if v_state is not null then v_item:=jsonb_set(v_item,'{status}',to_jsonb(v_state),true);
      elsif v_item->>'status'='vacant_unfilled' then v_item:=jsonb_set(v_item,'{status}',to_jsonb('working'::text),true); end if;
    end if;
    v_availability:=v_availability||jsonb_build_array(v_item);
  end loop;
  v_version:=jsonb_set(v_version,'{slotAvailability}',v_availability,true);
  if jsonb_typeof(v_hydrated->'version')='object' then v_hydrated:=jsonb_set(v_hydrated,'{version}',v_version,true);
  else v_hydrated:=jsonb_set(v_hydrated,'{versions}',jsonb_build_array(v_version),true); end if;
  return jsonb_set(v_hydrated,'{serviceDate}',to_jsonb(p_service_date::text),true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_projection_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare v_identity jsonb; v_version jsonb; v_slots jsonb; v_availability jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object' then
    raise exception using errcode='23514',message='projection source must be one compiler input object';
  end if;
  if jsonb_typeof(p_source->'version')='object' then
    v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array' and jsonb_array_length(p_source->'versions')=1 then
    v_version:=(p_source->'versions')->0;
  else
    raise exception using errcode='23514',message='projection source must carry exactly one recurring version';
  end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd'-'namedAbsentSlotIds'-'vacantSlotIds';
  if jsonb_typeof(v_version->'slotAvailability') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must retain recurring slot availability templates';
  end if;
  select coalesce(jsonb_agg(item-'status' order by ordinal),'[]'::jsonb) into v_availability
  from jsonb_array_elements(v_version->'slotAvailability') with ordinality as a(item,ordinal);
  v_version:=jsonb_set(v_version,'{slotAvailability}',v_availability,true);
  v_identity:=p_source-'serviceDate'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='projection source must carry stable roster slots';
  end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb) into v_slots
  from jsonb_array_elements(v_identity->'slots') with ordinality as s(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_read_employee_day_dated_base(p_service_date date, p_employee_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_result jsonb;
  v_field text;
  v_items jsonb;
  v_lunch_items jsonb;
  v_current_lunch jsonb;
begin
  v_result:=public.static_weekly_v5_read_employee_day_single_location_base(p_service_date,p_employee_id,p_now);
  foreach v_field in array array['items','all_items','current_items'] loop
    select coalesce(jsonb_agg(
      case when o.occurrence_id is null then item.value
      else item.value||jsonb_build_object(
        'service_mode',i.service_mode,
        'included_locations',i.location_names,
        'included_location_ids',i.location_ids,
        'included_location_snapshots',i.location_snapshots,
        'is_public_restroom',case when i.service_mode='scan_tracked' then i.has_public_restroom else false end
      ) end
      order by item.ordinality
    ),'[]'::jsonb) into v_items
    from jsonb_array_elements(coalesce(v_result->v_field,'[]'::jsonb)) with ordinality item(value,ordinality)
    left join public.weekly_schedule_occurrences o on o.occurrence_id::text=item.value->>'occurrence_id'
    left join lateral (
      select
        coalesce(o.authority_facts_json#>>'{work_snapshot,serviceMode}','scan_tracked') as service_mode,
        coalesce(jsonb_agg(location.value order by location.ordinality) filter(where location.value is not null),'[]'::jsonb) as location_snapshots,
        coalesce(jsonb_agg(to_jsonb(location.value->>'locationId') order by location.ordinality) filter(where location.value is not null),'[]'::jsonb) as location_ids,
        coalesce(jsonb_agg(to_jsonb(location.value->>'locationNameSnapshot') order by location.ordinality) filter(where location.value is not null),'[]'::jsonb) as location_names,
        coalesce(bool_or(lower(location.value->>'locationNameSnapshot') like '%restroom%'
          or lower(location.value->>'locationNameSnapshot') like '%bathroom%') filter(where location.value is not null),false) as has_public_restroom
      from jsonb_array_elements(
        case when jsonb_typeof(o.authority_facts_json#>'{work_snapshot,includedLocations}')='array'
          then o.authority_facts_json#>'{work_snapshot,includedLocations}' else '[]'::jsonb end
      ) with ordinality location(value,ordinality)
    ) i on true;
    v_result:=jsonb_set(v_result,array[v_field],v_items,true);
  end loop;
  if v_result->>'governed'='true' and v_result->>'projection_status'='current' then
    -- Same accepted reader drives employee display and operational reminder ownership.
    select coalesce(jsonb_agg(jsonb_build_object(
      'id',l.responsibility_id||':'||l.normal_occurrence_id::text,
      'occurrence_id',l.normal_occurrence_id::text,'normal_occurrence_id',l.normal_occurrence_id::text,
      'projection_id',l.projection_id::text,'service_date',p_service_date::text,
      'loan_id',l.loan_id,'responsibility_id',l.responsibility_id,
      'normal_owner_person_id',l.normal_owner_id::text,'coverer_person_id',l.coverer_id::text,
      'location_group_id',l.location_group_id::text,'group_code',l.group_code,'group_name',l.group_name,
      'location_group_code',l.group_code,'location_group_name',l.group_name,'location_name',l.group_name,
      'included_locations',to_jsonb(l.included_locations),'included_location_ids',to_jsonb(l.included_location_ids),
      'included_location_snapshots',l.included_snapshots,'service_mode',l.service_mode,
      'coverage_start',to_char(l.coverage_start,'HH24:MI:SS'),'coverage_end',to_char(l.coverage_end,'HH24:MI:SS'),
      'start_time',to_char(l.coverage_start,'HH24:MI:SS'),'end_time',to_char(l.coverage_end,'HH24:MI:SS'),
      'coverage_purpose','lunch_coverage','purpose','lunch_coverage','section_title','Lunch coverage',
      'source_type','static_weekly_lunch_coverage','owner_type','EMPLOYEE','status','ASSIGNED',
      'load_points',0,'notes','Temporary responsibility; existing check deadlines unchanged.',
      'check_deadline_policy','inherit_existing_90_minute_deadline','creates_deep_clean',false,
      'is_public_restroom',l.service_mode='scan_tracked' and public.sch_is_public_restroom_group(l.location_group_id)
    ) order by l.coverage_start,l.loan_id,l.responsibility_id,l.normal_occurrence_id),'[]') into v_lunch_items
    from public.static_weekly_v8_read_lunch_segments(p_service_date) l where l.coverer_id=p_employee_id;
    select coalesce(jsonb_agg(item order by ordinal),'[]') into v_current_lunch
    from jsonb_array_elements(v_lunch_items) with ordinality rows(item,ordinal)
    where (p_now at time zone 'America/Chicago')::date=p_service_date
      and (item->>'coverage_start')::time<=(p_now at time zone 'America/Chicago')::time
      and (p_now at time zone 'America/Chicago')::time<(item->>'coverage_end')::time;
    v_result:=jsonb_set(v_result,'{all_items}',coalesce(v_result->'all_items','[]')||v_lunch_items);
    v_result:=jsonb_set(v_result,'{current_items}',coalesce(v_result->'current_items','[]')||v_current_lunch);
    v_result:=jsonb_set(v_result,'{items}',coalesce(v_result->'items','[]')||v_current_lunch);
    v_result:=v_result||jsonb_build_object('lunch_coverage_status','PERSISTED',
      'lunch_coverage_contract','static-weekly-lunch-consumers.v1',
      'assignment_count',jsonb_array_length(v_result->'all_items'));
  else
    v_result:=v_result||jsonb_build_object('lunch_coverage_status','UNAVAILABLE');
  end if;
  return jsonb_set(v_result,'{contract_version}',to_jsonb('static-weekly-employee-day.v3'::text),true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v5_registered_source_identity(p_source jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_identity jsonb;
  v_version jsonb;
  v_slots jsonb;
  v_availability jsonb;
begin
  if jsonb_typeof(p_source) is distinct from 'object'
    or coalesce(p_source->'exceptions','[]'::jsonb)<>'[]'::jsonb then
    raise exception using errcode='23514',message='registered scheduler source must be one exception-free recurring compiler input';
  end if;
  if jsonb_typeof(p_source->'version')='object' then
    v_version:=p_source->'version';
  elsif jsonb_typeof(p_source->'versions')='array'
    and jsonb_array_length(p_source->'versions')=1 then
    v_version:=(p_source->'versions')->0;
  else
    raise exception using errcode='23514',message='registered scheduler source must carry exactly one recurring version';
  end if;
  v_version:=v_version-'id'-'publicationId'-'status'-'effectiveStart'-'effectiveEnd'-'vacantSlotIds';
  if jsonb_typeof(v_version->'slotAvailability') is distinct from 'array' then
    raise exception using errcode='23514',message='registered scheduler source must retain recurring slot availability templates';
  end if;
  select coalesce(jsonb_agg(item-'status' order by ordinal),'[]'::jsonb)
    into v_availability
  from jsonb_array_elements(v_version->'slotAvailability')
       with ordinality as availability(item,ordinal);
  v_version:=jsonb_set(v_version,'{slotAvailability}',v_availability,true);
  v_identity:=p_source-'serviceDate'-'exceptions'-'version'-'versions';
  if jsonb_typeof(v_identity->'slots') is distinct from 'array' then
    raise exception using errcode='23514',message='registered scheduler source must carry stable roster slots';
  end if;
  select coalesce(jsonb_agg(slot-'incumbencies' order by ordinal),'[]'::jsonb)
    into v_slots
  from jsonb_array_elements(v_identity->'slots')
       with ordinality as roster(slot,ordinal);
  v_identity:=jsonb_set(v_identity,'{slots}',v_slots,true);
  return jsonb_set(v_identity,'{version}',v_version,true);
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v6_schedule_authority_state_dated_base(p_service_date date)
 RETURNS TABLE(service_date date, governed boolean, authority_source text, projection_status text, version_id uuid, publication_id uuid, projection_id uuid, projection_authority_revision bigint, staffing_authority_revision bigint, week_start date)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_version_id uuid;
  v_publication_id uuid;
  v_projection_id uuid;
  v_projection_revision bigint;
  v_staffing_revision bigint;
  v_week_start date;
  v_status text;
begin
  if p_service_date is null then
    raise exception using errcode = '22023', message = 'service_date is required';
  end if;

  v_version_id := public.static_weekly_effective_version(p_service_date);
  if v_version_id is null then
    return query select p_service_date, false, 'legacy_daily_schedule'::text,
      'legacy_ungoverned'::text, null::uuid, null::uuid, null::uuid,
      null::bigint, null::bigint, null::date;
    return;
  end if;

  v_week_start := p_service_date - (extract(isodow from p_service_date)::integer - 1);
  select p.publication_id
    into v_publication_id
  from public.weekly_schedule_publications p
  where p.version_id = v_version_id
  order by p.authority_revision desc, p.published_at desc, p.publication_id desc
  limit 1;

  if v_publication_id is null then
    return query select p_service_date, true, 'static_weekly_projection'::text,
      'missing_publication'::text, v_version_id, null::uuid, null::uuid,
      null::bigint, null::bigint, v_week_start;
    return;
  end if;


  if exists(select 1 from public.static_weekly_recurring_invalidations i
    where i.publication_id=v_publication_id and i.effective_start<=p_service_date
      and (i.effective_end is null or p_service_date<i.effective_end)) then
    return query select p_service_date,true,'static_weekly_projection'::text,
      'blocked_recurring_authority'::text,v_version_id,v_publication_id,null::uuid,
      (select max(i.authority_revision) from public.static_weekly_recurring_invalidations i
        where i.publication_id=v_publication_id and i.effective_start<=p_service_date
          and (i.effective_end is null or p_service_date<i.effective_end)),
      null::bigint,v_week_start;
    return;
  end if;
  select projection.projection_id, (receipt.response_json->>'revision')::bigint
    into v_projection_id, v_projection_revision
  from public.weekly_schedule_compiled_projections projection
  join public.weekly_schedule_command_receipts receipt
    on receipt.command_type = 'materialize_projection'
   and receipt.response_json#>>'{data,projection_id}' = projection.projection_id::text
  where projection.publication_id = v_publication_id
    and projection.week_start = v_week_start
    and projection.exception_set_digest = public.static_weekly_digest_jsonb(
      public.static_weekly_accepted_exception_set(v_publication_id, v_week_start)
    )
  order by (receipt.response_json->>'revision')::bigint desc,
           receipt.command_id desc,
           projection.compiled_at desc,
           projection.projection_id desc
  limit 1;

  select max(staffing.authority_revision)
    into v_staffing_revision
  from public.weekly_roster_slot_staffing_states staffing
  where staffing.effective_start <= v_week_start + 6;

  if v_projection_id is null or v_projection_revision is null then
    v_status := 'missing_projection';
  elsif v_staffing_revision is not null and v_projection_revision <= v_staffing_revision then
    v_status := 'stale_staffing_change';
  else
    v_status := 'current';
  end if;

  return query select p_service_date, true, 'static_weekly_projection'::text,
    v_status, v_version_id, v_publication_id, v_projection_id,
    v_projection_revision, v_staffing_revision, v_week_start;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v7_create_vacant_roster_slot(p_slot_id uuid, p_slot_label text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb; v_prior public.weekly_schedule_command_receipts%rowtype;
  v_label text:=regexp_replace(btrim(coalesce(p_slot_label,'')),'\s+',' ','g');
  v_code text; v_request jsonb; v_request_digest text; v_content_digest text;
  v_command uuid:=gen_random_uuid(); v_revision bigint; v_response jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'create_vacant_slot');
  if p_slot_id is null or length(v_label) not between 2 and 200 then raise exception using errcode='22023',message='vacant roster position requires a stable UUID and label'; end if;
  v_code:='STATIC_'||upper(replace(p_slot_id::text,'-',''));
  v_request:=jsonb_build_object('operation','create_vacant_slot','slot_id',p_slot_id,'slot_code',v_code,'slot_label',v_label,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  if exists(select 1 from public.weekly_roster_slots where slot_id=p_slot_id or slot_code=v_code) then raise exception using errcode='23505',message='stable roster position already exists'; end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'create_vacant_slot',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slots(slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(p_slot_id,v_code,v_label,p_manager_id,v_actor->>'manager_name',v_content_digest);
  v_response:=public.static_weekly_response_json('create_vacant_slot',v_revision,v_content_digest,v_request_digest,jsonb_build_object('slot_id',p_slot_id,'slot_code',v_code,'slot_label',v_label,'vacant',true));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','create_vacant_slot',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v7_fill_vacant_roster_slot(p_slot_id uuid, p_new_employee_name text, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb; v_prior public.weekly_schedule_command_receipts%rowtype; v_slot public.weekly_roster_slots%rowtype;
  v_name text:=regexp_replace(btrim(coalesce(p_new_employee_name,'')),'\s+',' ','g');
  v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid();
  v_revision bigint; v_response jsonb; v_created jsonb; v_employee_id uuid; v_incumbency uuid:=gen_random_uuid();
  v_current_week date:=public.sch_service_date(statement_timestamp())-(extract(isodow from public.sch_service_date(statement_timestamp()))::integer-1);
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'fill_vacant_slot');
  if p_slot_id is null or length(v_name) not between 2 and 160 or p_effective_start is null
    or extract(isodow from p_effective_start)::integer<>1
    or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='filling a vacancy requires a stable slot, fresh employee name, Monday effective date, and bounded reason';
  end if;
  v_request:=jsonb_build_object('operation','fill_vacant_slot','slot_id',p_slot_id,'new_employee_name',v_name,'effective_start',p_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; return v_prior.response_json; end if;
  -- A receipt is permanent semantic evidence. Time-dependent new-operation
  -- eligibility must never hide a successful response after its week ends.
  if p_effective_start<v_current_week then
    raise exception using errcode='23514',message='a new vacancy fill cannot start before the current week';
  end if;
  select * into v_slot from public.weekly_roster_slots where slot_id=p_slot_id for share;
  if not found then raise exception using errcode='P0002',message='vacant stable roster position was not found'; end if;
  -- A vacated position is reusable; reject any overlapping or future incumbent.
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where slot_id=p_slot_id and (effective_end is null or p_effective_start<effective_end))
    or (exists(select 1 from public.weekly_roster_slot_incumbencies where slot_id=p_slot_id)
      and not exists(select 1 from public.weekly_roster_slot_staffing_states s
        where s.slot_id=p_slot_id and s.effective_start<=p_effective_start
          and s.staffing_state='vacant_unfilled' and s.employee_id is null
          and not exists(select 1 from public.weekly_roster_slot_staffing_states later
            where later.slot_id=p_slot_id and later.effective_start<=p_effective_start
              and (later.effective_start,later.authority_revision)>(s.effective_start,s.authority_revision)))) then
    raise exception using errcode='23514',message='only a never-filled or explicitly vacated stable position with no current or future incumbent can be filled';
  end if;
  v_created:=public.static_weekly_v5_create_replacement_employee(v_name,p_manager_id);
  v_employee_id:=(v_created#>>'{employee,id}')::uuid;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'fill_vacant_slot',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_incumbencies(incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(v_incumbency,p_slot_id,v_employee_id,v_name,p_effective_start,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_employee_id,'working',p_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_response:=public.static_weekly_response_json('fill_vacant_slot',v_revision,v_content_digest,v_request_digest,jsonb_build_object(
    'slot_id',p_slot_id,'slot_label',v_slot.slot_label,'new_employee_id',v_employee_id,'new_employee_name',v_name,
    'new_employee_code',v_created#>>'{employee,employee_code}','effective_start',p_effective_start,'phone_assignment',null
  ));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','fill_vacant_slot',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_read_completed_vacancy(p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 v_mutation public.weekly_schedule_command_receipts%rowtype;
 v_receipt public.weekly_schedule_command_receipts%rowtype;
 v_projection public.weekly_schedule_compiled_projections%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_date date;v_week date;v_projection_snapshot jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.custodial_assert_manager(p_manager_id);
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_manager_id is null or nullif(btrim(p_idempotency_key),'') is null then
  raise exception using errcode='22023',message='completed vacancy lookup requires exact manager and command identity';
 end if;
 select * into v_mutation from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key and command_type='vacate_roster_slot';
 if not found then return null; end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_mutation.command_id,'vacate_roster_slot');
 if v_mutation.response_json#>>'{data,completion_mode}'='mutation_only'
   and (v_mutation.response_json->'data') ? 'original_publication_id'
   and v_mutation.response_json#>'{data,original_publication_id}'='null'::jsonb then
  return v_mutation.response_json;
 end if;
 if v_mutation.response_json#>>'{data,completion_mode}' is distinct from 'projection_required'
   or nullif(v_mutation.response_json#>>'{data,original_publication_id}','') is null then
  raise exception using errcode='23514',message='completed vacancy original completion binding is missing or inconsistent';
 end if;
 select * into v_receipt from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key='projection-'||encode(extensions.digest(convert_to(p_idempotency_key,'UTF8'),'sha256'),'hex');
 if not found then
  raise exception using errcode='23514',message='completed vacancy required projection receipt is missing';
 end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_receipt.command_id,'materialize_projection');
 v_date:=(v_mutation.request_canonical_json->>'effective_start')::date;
 v_week:=v_date-(extract(isodow from v_date)::integer-1);
 if v_receipt.command_type is distinct from 'materialize_projection'
  or v_receipt.expected_revision is distinct from (v_mutation.response_json->>'revision')::bigint
  or (v_receipt.response_json->>'revision')::bigint is distinct from v_receipt.expected_revision+1
  or v_receipt.request_canonical_json->>'service_date' is distinct from v_week::text
  or v_receipt.request_canonical_json->>'publication_id' is distinct from v_mutation.response_json#>>'{data,original_publication_id}' then
  raise exception using errcode='23514',message='completed vacancy projection receipt does not bind the exact mutation';
 end if;
 select * into v_projection from public.weekly_schedule_compiled_projections
  where projection_id=(v_receipt.response_json#>>'{data,projection_id}')::uuid;
 if not found or v_projection.week_start is distinct from v_week
  or v_projection.publication_id::text is distinct from v_receipt.request_canonical_json->>'publication_id'
  or v_projection.authority_digest is distinct from v_receipt.request_canonical_json#>>'{projection_envelope,authority_digest}'
  or v_projection.replay_digest is distinct from v_receipt.request_canonical_json->>'replay_digest' then
  raise exception using errcode='23514',message='completed vacancy immutable projection binding is missing or inconsistent';
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents where projection_id=v_projection.projection_id;
 if not found or v_lunch.accepted_by_manager_id is distinct from p_manager_id
  or v_lunch.document_identity is distinct from v_lunch.document_json->>'document_identity'
  or v_lunch.document_json->>'base_authority_digest' is distinct from v_projection.authority_digest
  or v_lunch.document_json->>'base_replay_digest' is distinct from v_projection.replay_digest then
  raise exception using errcode='23514',message='completed vacancy accepted lunch binding is missing or inconsistent';
 end if;
 perform public.static_weekly_v8_assert_lunch_document(v_projection.projection_id,v_lunch.document_json);
 -- Match the immutable projection descriptor in the manager snapshot used by
 -- the first success. Do not read today's mutable latest-projection selector.
 v_projection_snapshot:=jsonb_build_object(
  'projection_id',v_projection.projection_id::text,'publication_id',v_projection.publication_id::text,
  'version_id',v_projection.version_id::text,'week_start',v_projection.week_start::text,'week_end',v_projection.week_end::text,
  'compiler_version',v_projection.compiler_version,'metrics',v_projection.metrics_json,
  'replay_digest',v_projection.replay_digest,'compiled_at',v_projection.compiled_at,
  'assignments',v_projection.projection_envelope->'assignments');
 return v_receipt.response_json||jsonb_build_object('data',
  (v_mutation.response_json->'data')||(v_receipt.response_json->'data')||
  jsonb_build_object('current_projection',v_projection_snapshot,'mutation',v_mutation.response_json->'data'));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_restore_existing_employee(p_source_id uuid, p_slot_id uuid, p_employee_id uuid, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb;
  v_prior public.weekly_schedule_command_receipts%rowtype;
  v_slot public.weekly_roster_slots%rowtype;
  v_employee public.employees%rowtype;
  v_source public.static_weekly_authority_source_documents%rowtype;
  v_source_slot jsonb;
  v_source_matches integer;
  v_prior_incumbency_count integer;
  v_request jsonb;
  v_request_digest text;
  v_content_digest text;
  v_command uuid:=gen_random_uuid();
  v_incumbency uuid:=gen_random_uuid();
  v_revision bigint;
  v_response jsonb;
  v_status jsonb; v_completion jsonb;
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(
    p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'restore_existing_employee'
  );
  if p_source_id is null or p_slot_id is null or p_employee_id is null or p_effective_start is null

     or nullif(btrim(coalesce(p_reason,'')),'') is null
     or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='existing-employee restoration requires a release-registered source, stable slot, existing employee, non-past effective date, and bounded reason';
  end if;
  v_request:=jsonb_build_object(
    'operation','restore_existing_employee','source_id',p_source_id,'slot_id',p_slot_id,'employee_id',p_employee_id,
    'effective_start',p_effective_start,'reason',p_reason,
    'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id
  );
  v_request_digest:=public.static_weekly_digest_jsonb(v_request);
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts
    where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then
    if v_prior.request_digest<>v_request_digest then
      raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs';
    end if;
    perform public.static_weekly_v8_assert_vacancy_receipt(v_prior.command_id,'restore_existing_employee');
    return v_prior.response_json;
  end if;
  if p_effective_start<public.sch_service_date(statement_timestamp()) then raise exception 'new restoration cannot be backdated'; end if;
  v_completion:=public.static_weekly_v9_roster_completion_context(p_source_id,p_slot_id,p_effective_start,false);
  select * into v_slot from public.weekly_roster_slots where slot_id=p_slot_id for share;
  if not found then raise exception using errcode='P0002',message='stable roster position was not found'; end if;
  select * into v_employee from public.employees where id=p_employee_id for update;
  if not found or v_employee.employee_code!~'^EMP[0-9]+$' then
    raise exception using errcode='23514',message='restoration requires the exact existing custodial employee identity';
  end if;
  if not exists(select 1 from public.msg_users where employee_id=p_employee_id) then
    raise exception using errcode='23514',message='existing employee Messenger identity is missing; restoration will not fabricate a replacement principal';
  end if;
  select * into v_source from public.static_weekly_authority_source_documents
    where source_id=p_source_id and active=true and retired_at is null;
  if not found then
    raise exception using errcode='P0002',message='restoration requires the exact active release-registered recurring source';
  end if;
  select value into v_source_slot from jsonb_array_elements(coalesce(v_source.canonical_source->'slots','[]'::jsonb)) slot(value)
    where value->>'id'=p_slot_id::text;
  if v_source_slot is null then
    raise exception using errcode='23514',message='registered source does not contain the requested stable position';
  end if;
  select count(*) into v_source_matches
  from jsonb_array_elements(coalesce(v_source_slot->'incumbencies','[]'::jsonb)) incumbent(value)
  where value->>'personId'=p_employee_id::text
    and value->>'effectiveStart'=p_effective_start::text
    and (nullif(value->>'effectiveEnd','') is null or p_effective_start<(value->>'effectiveEnd')::date);
  if v_source_matches<>1 then
    raise exception using errcode='23514',message='registered source must bind this exact existing employee to this exact stable position and effective date';
  end if;
  select count(*) into v_prior_incumbency_count
  from public.weekly_roster_slot_incumbencies where slot_id=p_slot_id and person_id=p_employee_id;
  if exists(
    select 1 from public.v_weekly_roster_slot_incumbency_ranges r
    where r.slot_id=p_slot_id
      and (r.effective_start>=p_effective_start
        or (r.effective_start<p_effective_start and (r.effective_end is null or p_effective_start<r.effective_end)))
  ) then
    raise exception using errcode='23514',message='restoration target position already has current or future incumbency authority';
  end if;
  if exists(
    select 1 from public.v_weekly_roster_slot_incumbency_ranges r
    where r.person_id=p_employee_id and r.slot_id<>p_slot_id
      and (r.effective_start>=p_effective_start
        or (r.effective_start<p_effective_start and (r.effective_end is null or p_effective_start<r.effective_end)))
  ) then
    raise exception using errcode='23514',message='existing employee already has current or future authority in another stable position';
  end if;
  perform public.static_weekly_v4_assert_employee_turnover_ready(p_employee_id);
  if exists(
    select 1 from public.weekly_roster_slot_staffing_states
    where slot_id=p_slot_id and effective_start=p_effective_start and staffing_state='working'
  ) then
    raise exception using errcode='23505',message='stable position already has working staffing authority on restoration date';
  end if;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(
    p_expected_revision,'restore_existing_employee',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest
  );
  insert into public.weekly_roster_slot_incumbencies(
    incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,
    created_by_manager_id,created_by_manager_name_snapshot,content_digest
  ) values(
    v_incumbency,p_slot_id,p_employee_id,v_employee.display_name,p_effective_start,
    p_manager_id,v_actor->>'manager_name',v_content_digest
  );
  insert into public.weekly_roster_slot_staffing_states(
    slot_id,employee_id,staffing_state,effective_start,authority_revision,
    actor_manager_id,actor_manager_name_snapshot,reason,content_digest
  ) values(
    p_slot_id,p_employee_id,'working',p_effective_start,v_revision,
    p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest
  );
  v_status:=public.custodial_set_employee_active(p_employee_id,true,p_manager_id,p_reason,false);
  v_response:=public.static_weekly_response_json(
    'restore_existing_employee',v_revision,v_content_digest,v_request_digest,
    jsonb_build_object(
      'slot_id',p_slot_id,'slot_label',v_slot.slot_label,
      'employee_id',p_employee_id,'employee_name',v_employee.display_name,
      'source_id',p_source_id,'source_digest',v_source.source_digest,
      'effective_start',p_effective_start,'prior_scheduler_incumbency_count',v_prior_incumbency_count,
      'restored_incumbency_id',v_incumbency,'employee_status',v_status,
      'phone_assignment',null,'history_preserved',true
    )||v_completion
  );
  insert into public.weekly_schedule_command_receipts(
    command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,
    expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest
  ) values(
    v_command,p_manager_id,v_actor->>'manager_name','restore_existing_employee',p_idempotency_key,
    p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest
  );
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_vacate_roster_slot(p_source_id uuid, p_slot_id uuid, p_employee_id uuid, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_actor jsonb;v_prior public.weekly_schedule_command_receipts%rowtype;
  v_source public.static_weekly_authority_source_documents%rowtype;
  v_incumbent public.v_weekly_roster_slot_incumbency_ranges%rowtype;
  v_employee public.employees%rowtype;v_slot jsonb;v_request jsonb;v_request_digest text;
  v_content_digest text;v_revision bigint;v_command uuid:=gen_random_uuid();v_response jsonb;v_status jsonb;
  v_original_publication uuid;
begin
  perform public.static_weekly_v3_assert_control_plane();
  perform public.custodial_assert_manager(p_manager_id);
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,
    v_actor->>'manager_name',p_idempotency_key,'vacate_roster_slot');
  if p_source_id is null or p_slot_id is null or p_employee_id is null or p_effective_start is null
    or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500
    or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='vacancy requires source, position, exact former employee, effective date and bounded reason';
  end if;
  v_request:=jsonb_build_object('operation','vacate_roster_slot','source_id',p_source_id,'slot_id',p_slot_id,
    'employee_id',p_employee_id,'effective_start',p_effective_start,'reason',p_reason,
    'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request);
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts
    where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then
    if v_prior.request_digest<>v_request_digest then
      raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs';
    end if;
    perform public.static_weekly_v8_assert_vacancy_receipt(v_prior.command_id,'vacate_roster_slot');
    return v_prior.response_json;
  end if;
  -- Immediate turnover only. Do not deactivate someone today for a future vacancy.
  if p_effective_start<>public.sch_service_date(statement_timestamp()) then
    raise exception using errcode='23514',message='vacancy effective date must be the current service date; past or future turnover is not supported';
  end if;
  select * into v_source from public.static_weekly_authority_source_documents
    where source_id=p_source_id and active and retired_at is null for share;
  if not found then raise exception using errcode='23514',message='vacancy requires an active registered source'; end if;
  select value into v_slot from jsonb_array_elements(v_source.canonical_source->'slots')
    where value->>'id'=p_slot_id::text;
  if v_slot is null
    or not coalesce((v_source.canonical_source#>'{version,vacancyCapableSlotIds}') ? p_slot_id::text,false)
     then
    raise exception using errcode='23514',message='registered source must declare this stable position vacancy-capable';
  end if;
  select * into v_incumbent from public.v_weekly_roster_slot_incumbency_ranges
    where slot_id=p_slot_id and effective_start<p_effective_start
      and (effective_end is null or p_effective_start<effective_end);
  if not found or v_incumbent.person_id<>p_employee_id then
    raise exception using errcode='23514',message='vacancy requires the exact effective predecessor incumbent';
  end if;
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where slot_id=p_slot_id and effective_start>=p_effective_start) then
    raise exception using errcode='23514',message='future incumbency already occupies this position';
  end if;
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where person_id=p_employee_id and slot_id<>p_slot_id
        and (effective_end is null or p_effective_start<effective_end)) then
    raise exception using errcode='23514',message='former employee also has another current or future position';
  end if;
  select * into v_employee from public.employees where id=p_employee_id for update;
  if not found then raise exception using errcode='23514',message='predecessor employee identity is missing'; end if;

  -- Bind the original completion shape under the same authority lock and
  -- effective-week selector as the manager snapshot. Absence of a later
  -- projection receipt must never be interpreted as an unpublished action.
  select publication_id into v_original_publication from public.weekly_schedule_publications
    where version_id=public.static_weekly_effective_version(
      p_effective_start-(extract(isodow from p_effective_start)::integer-1));
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'vacate_roster_slot',
    p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(
    slot_id,employee_id,staffing_state,effective_start,authority_revision,
    actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,null,'vacant_unfilled',p_effective_start,v_revision,
    p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  insert into public.weekly_roster_slot_incumbency_closures(
    closed_incumbency_id,replacement_incumbency_id,closed_at_effective_date,authority_revision,
    actor_manager_id,actor_manager_name_snapshot,content_digest)
  values(v_incumbent.incumbency_id,null,p_effective_start,v_revision,
    p_manager_id,v_actor->>'manager_name',v_content_digest);
  v_status:=public.custodial_v12_inactivate_preserving_work(p_employee_id,p_slot_id,p_manager_id,p_reason,v_revision,v_command,p_effective_start);
  v_response:=public.static_weekly_response_json('vacate_roster_slot',v_revision,v_content_digest,
    v_request_digest,jsonb_build_object('slot_id',p_slot_id,'former_employee_id',p_employee_id,
      'replacement_employee_id',null,'effective_start',p_effective_start,'source_id',p_source_id,
      'source_digest',v_source.source_digest,'employee_status',v_status,'history_preserved',true,
      'completion_mode',case when v_original_publication is null then 'mutation_only' else 'projection_required' end,
      'original_publication_id',v_original_publication));
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,
    actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,
    request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','vacate_roster_slot',p_idempotency_key,
    p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_assert_shift_end_derivation(p_authority jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 source jsonb:=p_authority->'compilerInput';
 effective jsonb:=jsonb_set(p_authority->'overlayCompilerInput','{exceptions}','[]'::jsonb);
 policy jsonb:=source#>'{version,shiftEndContinuityPolicy}';
 receipt jsonb:=p_authority->'shiftEndDerivation';
 roster jsonb; boundaries jsonb; chain jsonb; parent jsonb; segment jsonb; work jsonb;
 person jsonb; owner jsonb; physical jsonb; key text; previous_end text; final_end text;
 day integer; matches integer; total numeric; seen text[]:='{}'; parent_seen text[]:='{}';
 minute_samples integer:=0; location_samples integer:=0; location_count integer; span integer;
 named jsonb; named_parent jsonb; named_chain jsonb; named_from jsonb; named_to jsonb; named_to_availability jsonb;
 named_parent_id text; named_key text; named_seen text[]:='{}';
begin
 perform public.static_weekly_assert_exact_object(policy,
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest'],
  array['schema','algorithm','normalPhaseStart','weights','provenance','policyDigest','namedHandoffs'],'shift-end source policy');
 if policy ? 'namedHandoffs' then
  if jsonb_typeof(policy->'namedHandoffs') is distinct from 'array' then
   raise exception using errcode='23514',message='shift-end named handoffs must be one array';
  end if;
  if jsonb_array_length(policy->'namedHandoffs')>14 then
   raise exception using errcode='23514',message='shift-end named handoffs exceed the source bound';
  end if;
 end if;
 perform public.static_weekly_assert_exact_object(receipt,
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],
  array['schema','algorithm','templateDigest','policyDigest','datedRosterDigest','derivedBaselineDigest','staffedDepartureByDay','parentChains','outputWorkDigest','continuity'],'shift-end derivation receipt');
 if policy->>'schema' is distinct from 'memphis-zoo.shift-end-continuity-policy.v1'
  or policy->>'algorithm' is distinct from 'dated-real-staff-directed-proximity-weighted-v1'
  or policy->>'normalPhaseStart' is distinct from '09:45'
  or coalesce(policy->>'provenance','') !~ '^owner-configuration-sha256:[a-f0-9]{64}$'
  or policy->>'policyDigest' is distinct from public.static_weekly_digest_jsonb(policy-'policyDigest')
  or receipt->>'schema' is distinct from 'memphis-zoo.shift-end-derivation.v1'
  or receipt->>'algorithm' is distinct from policy->>'algorithm'
  or receipt->>'policyDigest' is distinct from policy->>'policyDigest'
  or receipt->>'templateDigest' is distinct from public.static_weekly_digest_jsonb(source)
  or receipt->>'derivedBaselineDigest' is distinct from public.static_weekly_digest_jsonb(effective)
  or receipt->>'derivedBaselineDigest' is distinct from p_authority->>'derivedBaselineDigest'
  or source->'exceptions' is distinct from '[]'::jsonb
  or source#>'{version,shiftEndDerivationApplied}' is not null
  or effective#>>'{version,shiftEndDerivationApplied}' is distinct from policy->>'policyDigest'
  or source-'version' is distinct from effective-'version'
  or (source->'version')-'assignments' is distinct from (effective->'version')-'assignments'-'shiftEndDerivationApplied'
  or jsonb_typeof(policy->'weights') is distinct from 'object'
  or jsonb_typeof(source#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(effective#>'{version,assignments}') is distinct from 'array'
  or jsonb_typeof(receipt->'parentChains') is distinct from 'array'
  or jsonb_array_length(source#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(effective#>'{version,assignments}') not between 1 and 1024
  or jsonb_array_length(receipt->'parentChains')<>jsonb_array_length(source#>'{version,assignments}')
  or receipt->>'outputWorkDigest' is distinct from public.static_weekly_digest_jsonb(effective#>'{version,assignments}') then
  raise exception using errcode='23514',message='shift-end source, policy, derived baseline and receipt identities must be exact';
 end if;
 if exists(select 1 from jsonb_each(policy->'weights') w where jsonb_typeof(w.value)<>'number'
  or (w.value#>>'{}')::numeric<=0 or (w.value#>>'{}')::numeric>1000
  or (w.value#>>'{}')::numeric*2<>trunc((w.value#>>'{}')::numeric*2)) then
  raise exception using errcode='23514',message='shift-end weights require exact positive bounded half units';
 end if;
 -- Derive this roster from immutable availability plus dated incumbent ranges,
 -- never from exception-mutated projectionAvailability or a caller roster blob.
 with facts as (
  select a, s, (source->>'serviceDate')::date+
   mod((a->>'dayOfWeek')::int-extract(dow from (source->>'serviceDate')::date)::int+7,7) d
  from jsonb_array_elements(source#>'{version,slotAvailability}') a
  join jsonb_array_elements(source->'slots') s on s->>'id'=a->>'slotId'
  where coalesce(s->'contractorCapacity','false'::jsonb)='false'::jsonb
 ), dated as (
  select *, (select count(*) from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date)) n,
   (select i from jsonb_array_elements(s->'incumbencies') i
   where (i->>'effectiveStart')::date<=d and (i->>'effectiveEnd' is null or d<(i->>'effectiveEnd')::date) limit 1) incumbent
  from facts
 ) select coalesce(jsonb_agg(jsonb_build_object('serviceDate',d::text,'dayOfWeek',a->'dayOfWeek',
   'slotId',a->'slotId','personId',incumbent->'personId','vacant',n=0,'status',a->'status',
   'shift',a->'shift','lunch',a->'lunch') order by (a->>'dayOfWeek')::int,a->>'slotId'),'[]'::jsonb),
  count(*) filter(where n>1 or (n=0 and not coalesce((source#>'{version,vacancyCapableSlotIds}') ? (a->>'slotId'),false))
   or (n=0) is distinct from (a->>'status'='vacant_unfilled')
   or a->>'status' not in ('working','vacant_unfilled','departed_named_absent'))
 into roster,matches from dated;
 if matches<>0 or jsonb_array_length(roster)=0
  or (select count(*) from jsonb_array_elements(roster))<>(select count(distinct (r->>'dayOfWeek',r->>'slotId')) from jsonb_array_elements(roster) r)
  or receipt->>'datedRosterDigest' is distinct from public.static_weekly_digest_jsonb(roster) then
  raise exception using errcode='23514',message='shift-end receipt must bind one exact dated real roster';
 end if;
 select jsonb_object_agg(d::text,closing) into boundaries from (
  select (r->>'dayOfWeek')::int d,max(r#>>'{shift,end}') closing from jsonb_array_elements(roster) r
  where r->'vacant'='false'::jsonb and r->>'status'='working' group by 1
 ) endings;
 if boundaries is null or (select count(*) from jsonb_object_keys(boundaries))<>7
  or boundaries is distinct from receipt->'staffedDepartureByDay' then
  raise exception using errcode='23514',message='shift-end boundary requires real working incumbent on every day';
 end if;
 for chain in select value from jsonb_array_elements(receipt->'parentChains') loop
  perform public.static_weekly_assert_exact_object(chain,
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],
   array['dayOfWeek','parentWorkId','physicalIdentityDigest','workloadBefore','workloadAfter','segments'],'shift-end parent chain');
  day:=(chain->>'dayOfWeek')::int; key:=day::text||':'||(chain->>'parentWorkId');
  select count(*) into matches from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  if matches<>1 or key=any(parent_seen) then raise exception 'shift-end parent must exist exactly once'; end if;
  parent_seen:=array_append(parent_seen,key);
  select w into parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=day::text and w->>'workId'=chain->>'parentWorkId';
  select jsonb_object_agg(k,coalesce(parent->k,'null'::jsonb)) into physical from unnest(array[
   'locationId','locationCodeSnapshot','locationNameSnapshot','includedLocations','serviceMode','requiredQualifications',
   'restrictedSlotIds','restrictions','qualificationProvenance','restrictionProvenance']) k;
  if chain->>'physicalIdentityDigest' is distinct from public.static_weekly_digest_jsonb(physical)
   or chain->'workloadBefore' is distinct from parent->'serviceEffortMinutes'
   or chain->'workloadAfter' is distinct from parent->'serviceEffortMinutes'
   or jsonb_typeof(chain->'segments') is distinct from 'array' or jsonb_array_length(chain->'segments')<1
   or position(':handoff:' in parent->>'workId')>0 or position(':open:' in parent->>'workId')>0 then
   raise exception 'shift-end chain must retain exact immutable parent identity and workload';
  end if;
  previous_end:=parent#>>'{window,start}';final_end:=boundaries->>day::text;total:=0;
  if previous_end='09:45' then
   select r into owner from jsonb_array_elements(roster) r where r->>'slotId'=parent->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
   if not found or parent#>>'{window,end}' is distinct from owner#>>'{shift,end}'
    or parent->'originSlotId' is distinct from parent->'ownerSlotId'
    or not ((policy->'weights') ? (parent->>'locationCodeSnapshot')) then
    raise exception 'immutable normal parent must retain full owning position shift and weight'; end if;
  end if;
  for segment in select value from jsonb_array_elements(chain->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],
    array['workId','ownerSlotId','window','serviceEffortMinutes','kind'],'shift-end segment');
   key:=day::text||':'||(segment->>'workId');
   select count(*) into matches from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   if matches<>1 or key=any(seen) then raise exception 'derived segment must occur exactly once'; end if;
   seen:=array_append(seen,key);
   select w into work from jsonb_array_elements(effective#>'{version,assignments}') w
    where w->>'dayOfWeek'=day::text and w->>'workId'=segment->>'workId';
   perform public.static_weekly_v3_assert_window(segment->'window','shift-end segment');
   if segment#>>'{window,start}' is distinct from previous_end
    or segment->'window' is distinct from work->'window'
    or segment->'ownerSlotId' is distinct from work->'ownerSlotId'
    or segment->'serviceEffortMinutes' is distinct from work->'serviceEffortMinutes'
    or jsonb_typeof(segment->'serviceEffortMinutes') is distinct from 'number'
    or (segment->>'serviceEffortMinutes')::numeric<=0
    or (segment->>'serviceEffortMinutes')::numeric<>trunc((segment->>'serviceEffortMinutes')::numeric)
    or (work-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
       is distinct from (parent-'workId'-'ownerSlotId'-'originSlotId'-'window'-'serviceEffortMinutes'-'serviceEffortProvenance')
    or work->'ownerSlotId' is distinct from work->'originSlotId'
    or work->>'serviceEffortProvenance' is distinct from ((parent->>'serviceEffortProvenance')||
       case when jsonb_array_length(chain->'segments')>1 then ';shift-split-preserves-budget' else '' end) then
    raise exception 'derived segment changed immutable work, exact workload or contiguous window';
   end if;
   previous_end:=segment#>>'{window,end}';total:=total+(segment->>'serviceEffortMinutes')::numeric;
   if parent#>>'{window,start}'<>'09:45' then
    if work is distinct from parent or segment->>'kind' is distinct from 'baseline' then raise exception 'non-closing work must be unchanged'; end if;
   else
    select r into person from jsonb_array_elements(roster) r where r->>'slotId'=work->>'ownerSlotId' and r->>'dayOfWeek'=day::text;
    select a into owner from jsonb_array_elements(source#>'{version,slotAvailability}') a where a->>'slotId'=work->>'ownerSlotId' and a->>'dayOfWeek'=day::text;
    if person is null or owner is null or work#>>'{window,start}'<person#>>'{shift,start}'
     or previous_end>person#>>'{shift,end}' or previous_end>final_end
     or (work->'restrictedSlotIds') ? (work->>'ownerSlotId')
     or not ((owner->'qualifications') @> (work->'requiredQualifications'))
     or exists(select 1 from jsonb_array_elements(work->'includedLocations') loc where (owner->'restrictions') ? (loc->>'locationId')) then
     raise exception 'derived normal responsibility has off-duty or ineligible position'; end if;
    if segment->>'kind'='baseline' then
     if work->'workId' is distinct from parent->'workId' or work->'ownerSlotId' is distinct from parent->'ownerSlotId' then raise exception 'baseline segment identity changed'; end if;
    elsif segment->>'kind' in ('open','handoff') then
     if work->>'workId' is distinct from (parent->>'workId')||':'||(segment->>'kind')||':'||(work#>>'{window,start}')||':'||(work->>'ownerSlotId')
      or (segment->>'kind'='open') is distinct from (person->'vacant'='true'::jsonb)
      or (segment->>'kind'='handoff' and (person->>'status'<>'working' or person->>'personId' is null))
      or (person#>>'{lunch,start}'<=work#>>'{window,start}' and work#>>'{window,start}'<person#>>'{lunch,end}') then
      raise exception 'physical handoff or explicit OPEN segment identity invalid'; end if;
    else raise exception 'unknown derived segment kind'; end if;
   end if;
  end loop;
  if total<>(parent->>'serviceEffortMinutes')::numeric
   or (parent#>>'{window,start}'='09:45' and previous_end is distinct from final_end) then
   raise exception 'parent chain must conserve workload and reach final staffed boundary'; end if;
 end loop;
 if cardinality(seen)<>jsonb_array_length(effective#>'{version,assignments}') then raise exception 'unaccounted derived work'; end if;

 -- A policy string alone never authorizes a new recipient. Every named
 -- handoff must occur exactly once in the already-validated immutable
 -- parent chain, at the departing source worker's actual shift end, with a
 -- real eligible/on-duty recipient and all required directed edges. The
 -- accepted six-key historical policy follows this block without change.
 for named in select value from jsonb_array_elements(coalesce(policy->'namedHandoffs','[]'::jsonb)) loop
  perform public.static_weekly_assert_exact_object(named,
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],
   array['dayOfWeek','locationCode','at','fromSlotId','toSlotId','source'],'shift-end named handoff');
  if (jsonb_typeof(named->'dayOfWeek')='number'
    and named->>'dayOfWeek' ~ '^[0-6]$'
    and jsonb_typeof(named->'locationCode')='string'
    and (policy->'weights') ? (named->>'locationCode')
    and jsonb_typeof(named->'at')='string'
    and named->>'at' ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    and jsonb_typeof(named->'fromSlotId')='string'
    and named->>'fromSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and jsonb_typeof(named->'toSlotId')='string'
    and named->>'toSlotId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    and named->>'fromSlotId'<>named->>'toSlotId'
    and jsonb_typeof(named->'source')='string'
    and length(named->>'source') between 10 and 300) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff typed source identity invalid';
  end if;
  named_key:=(named->>'dayOfWeek')||':'||(named->>'locationCode')||':'||(named->>'at');
  if named_key=any(named_seen) then
   raise exception using errcode='23514',message='shift-end named handoff duplicated';
  end if;
  named_seen:=array_append(named_seen,named_key);
  select count(*),max(w->>'workId') into matches,named_parent_id
   from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek'
    and w->>'locationCodeSnapshot'=named->>'locationCode'
    and w#>>'{window,start}'='09:45';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named parent source is not unique';
  end if;
  select w into named_parent from jsonb_array_elements(source#>'{version,assignments}') w
   where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'workId'=named_parent_id;
  select c into named_chain from jsonb_array_elements(receipt->'parentChains') c
   where c->>'dayOfWeek'=named->>'dayOfWeek' and c->>'parentWorkId'=named_parent_id;
  if named_chain is null then
   raise exception using errcode='23514',message='shift-end named parent chain absent';
  end if;
  select count(*) into matches
   from jsonb_array_elements(named_chain->'segments') with ordinality as s(segment,ordinal)
   where s.ordinal>1 and s.segment->>'kind'='handoff'
    and s.segment#>>'{window,start}'=named->>'at'
    and s.segment->>'ownerSlotId'=named->>'toSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))->>'ownerSlotId'=named->>'fromSlotId'
    and (named_chain->'segments'->(s.ordinal::integer-2))#>>'{window,end}'=named->>'at';
  if matches<>1 then
   raise exception using errcode='23514',message='shift-end named handoff does not match exactly one derived segment';
  end if;
  select r into named_from from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'fromSlotId';
  select r into named_to from jsonb_array_elements(roster) r
   where r->>'dayOfWeek'=named->>'dayOfWeek' and r->>'slotId'=named->>'toSlotId';
  select a into named_to_availability from jsonb_array_elements(source#>'{version,slotAvailability}') a
   where a->>'dayOfWeek'=named->>'dayOfWeek' and a->>'slotId'=named->>'toSlotId';
  if (named_from->>'status'='working' and named_from->>'personId' is not null
    and named_from#>>'{shift,end}'=named->>'at'
    and named_to->>'status'='working' and named_to->>'personId' is not null
    and named_to#>>'{shift,start}'<=named->>'at'
    and named->>'at'<named_to#>>'{shift,end}'
    and not (named_to#>>'{lunch,start}'<=named->>'at' and named->>'at'<named_to#>>'{lunch,end}')
    and (named_to_availability->'qualifications') @> (named_parent->'requiredQualifications')
    and not ((named_parent->'restrictedSlotIds') ? (named->>'toSlotId'))
    and not exists(select 1 from jsonb_array_elements(case
      when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
      else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) target
      where (named_to_availability->'restrictions') ? (target->>'locationId'))
  ) is distinct from true then
   raise exception using errcode='23514',message='shift-end named handoff source or recipient is not current and eligible';
  end if;
  -- The JS source-derived selector requires a verified directed edge from
  -- at least one exact current-source target-position anchor to every member.
  -- Normal owned members take precedence; only a position owning no normal
  -- row may use its explicit accepted route anchor.
  with anchors as (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
    cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0
      then w->'includedLocations' else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
    where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
     and w#>>'{window,start}'='09:45'
   union all
   select named_to_availability->>'acceptedRouteAnchorLocationId'
    where not exists(select 1 from jsonb_array_elements(source#>'{version,assignments}') w
      where w->>'dayOfWeek'=named->>'dayOfWeek' and w->>'ownerSlotId'=named->>'toSlotId'
       and w#>>'{window,start}'='09:45')
  ), targets as (
   select l->>'locationId' id from jsonb_array_elements(case
     when jsonb_array_length(named_parent->'includedLocations')>0 then named_parent->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',named_parent->'locationId')) end) l
  )
  select count(*) into matches from targets target where not exists(
   select 1 from anchors anchor where anchor.id is not null and
    (anchor.id=target.id or exists(select 1 from jsonb_array_elements(source->'proximity') edge
      where edge->>'fromLocationId'=anchor.id and edge->>'toLocationId'=target.id
       and edge->'verified'='true'::jsonb and jsonb_typeof(edge->'minutes')='number'
       and (edge->>'minutes')::numeric>=0 and (edge->>'minutes')::numeric=trunc((edge->>'minutes')::numeric)
       and nullif(edge->>'provenance','') is not null)));
  if matches<>0 then
   raise exception using errcode='23514',message='shift-end named handoff lacks verified directed source proximity';
  end if;
 end loop;
 -- OPEN may retain a stable baseline position, never a fictitious execution
 -- owner/person. Existing optimizer/document validators retain their checks.
 if exists(select 1 from jsonb_array_elements(p_authority#>'{optimizerResult,assignments}') a
  where a->>'status' in ('OPEN','REVIEW') and (a->>'slotId' is not null or a->>'personId' is not null)) then
  raise exception 'OPEN derived work may not invent execution identity'; end if;
 for day in 0..6 loop
  select count(*),count(distinct id) into matches,location_count from (
   select l->>'locationId' id from jsonb_array_elements(source#>'{version,assignments}') w
   cross join lateral jsonb_array_elements(case when jsonb_array_length(w->'includedLocations')>0 then w->'includedLocations'
     else jsonb_build_array(jsonb_build_object('locationId',w->'locationId')) end) l
   where w->>'dayOfWeek'=day::text and w#>>'{window,start}'='09:45'
  ) locations;
  if matches<>location_count then raise exception 'immutable normal template contains duplicate physical ownership'; end if;
  span:=(extract(epoch from (boundaries->>day::text)::time)/60)::int-585;
  if span<=0 then raise exception 'invalid staffed operating span'; end if;
  minute_samples:=minute_samples+span;location_samples:=location_samples+span*location_count;
 end loop;
 if receipt->'continuity' is distinct from jsonb_build_object('minuteSamples',minute_samples,'locationMinuteChecks',location_samples,
  'coverageGaps',0,'duplicateLocations',0,'staffedDepartureByDay',boundaries,
  'scope','dated real-staff handoffs and explicit vacancy OPEN responsibility until final staffed departure; lunch overlay checked separately') then
  raise exception 'shift-end continuity counters must be independently recomputed'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_fill_vacant_roster_slot(p_source_id uuid, p_slot_id uuid, p_new_employee_name text, p_effective_start date, p_reason text, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_completion jsonb; v_actor jsonb; v_prior public.weekly_schedule_command_receipts%rowtype; v_slot public.weekly_roster_slots%rowtype;
  v_name text:=regexp_replace(btrim(coalesce(p_new_employee_name,'')),'\s+',' ','g');
  v_request jsonb; v_request_digest text; v_content_digest text; v_command uuid:=gen_random_uuid();
  v_revision bigint; v_response jsonb; v_created jsonb; v_employee_id uuid; v_incumbency uuid:=gen_random_uuid();
  v_current_week date:=public.sch_service_date(statement_timestamp())-(extract(isodow from public.sch_service_date(statement_timestamp()))::integer-1);
begin
  perform public.static_weekly_v3_assert_control_plane(); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  perform public.static_weekly_assert_command_identity(p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key,'fill_vacant_slot');
  if p_source_id is null or p_slot_id is null or length(v_name) not between 2 and 160 or p_effective_start is null
    or extract(isodow from p_effective_start)::integer<>1
    or nullif(btrim(coalesce(p_reason,'')),'') is null or char_length(p_reason)>500 or p_reason~'[\x00-\x1f\x7f]' then
    raise exception using errcode='23514',message='filling a vacancy requires a stable slot, fresh employee name, Monday effective date, and bounded reason';
  end if;
  v_request:=jsonb_build_object('operation','fill_vacant_slot','source_id',p_source_id,'slot_id',p_slot_id,'new_employee_name',v_name,'effective_start',p_effective_start,'reason',p_reason,'expected_revision',p_expected_revision,'actor_manager_id',p_manager_id);
  v_request_digest:=public.static_weekly_digest_jsonb(v_request); perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
  select * into v_prior from public.weekly_schedule_command_receipts where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key;
  if found then if v_prior.request_digest<>v_request_digest then raise exception using errcode='23505',message='idempotency key was already used for different semantic inputs'; end if; perform public.static_weekly_v8_assert_vacancy_receipt(v_prior.command_id,'fill_vacant_slot'); return v_prior.response_json; end if;
  -- A receipt is permanent semantic evidence. Time-dependent new-operation
  -- eligibility must never hide a successful response after its week ends.
  if p_effective_start<v_current_week then
    raise exception using errcode='23514',message='a new vacancy fill cannot start before the current week';
  end if;
  select * into v_slot from public.weekly_roster_slots where slot_id=p_slot_id for share;
  if not found then raise exception using errcode='P0002',message='vacant stable roster position was not found'; end if;
  -- A vacated position is reusable; reject any overlapping or future incumbent.
  if exists(select 1 from public.v_weekly_roster_slot_incumbency_ranges
      where slot_id=p_slot_id and (effective_end is null or p_effective_start<effective_end))
    or (exists(select 1 from public.weekly_roster_slot_incumbencies where slot_id=p_slot_id)
      and not exists(select 1 from public.weekly_roster_slot_staffing_states s
        where s.slot_id=p_slot_id and s.effective_start<=p_effective_start
          and s.staffing_state='vacant_unfilled' and s.employee_id is null
          and not exists(select 1 from public.weekly_roster_slot_staffing_states later
            where later.slot_id=p_slot_id and later.effective_start<=p_effective_start
              and (later.effective_start,later.authority_revision)>(s.effective_start,s.authority_revision)))) then
    raise exception using errcode='23514',message='only a never-filled or explicitly vacated stable position with no current or future incumbent can be filled';
  end if;
  v_completion:=public.static_weekly_v9_roster_completion_context(p_source_id,p_slot_id,p_effective_start,true);
  v_created:=public.static_weekly_v5_create_replacement_employee(v_name,p_manager_id);
  v_employee_id:=(v_created#>>'{employee,id}')::uuid;
  v_content_digest:=public.static_weekly_digest_jsonb(v_request-'expected_revision'-'actor_manager_id'-'operation');
  v_revision:=public.static_weekly_advance_authority(p_expected_revision,'fill_vacant_slot',p_manager_id,v_actor->>'manager_name',v_command,v_content_digest);
  insert into public.weekly_roster_slot_incumbencies(incumbency_id,slot_id,person_id,person_name_snapshot,effective_start,created_by_manager_id,created_by_manager_name_snapshot,content_digest)
  values(v_incumbency,p_slot_id,v_employee_id,v_name,p_effective_start,p_manager_id,v_actor->>'manager_name',v_content_digest);
  insert into public.weekly_roster_slot_staffing_states(slot_id,employee_id,staffing_state,effective_start,authority_revision,actor_manager_id,actor_manager_name_snapshot,reason,content_digest)
  values(p_slot_id,v_employee_id,'working',p_effective_start,v_revision,p_manager_id,v_actor->>'manager_name',p_reason,v_content_digest);
  v_response:=public.static_weekly_response_json('fill_vacant_slot',v_revision,v_content_digest,v_request_digest,jsonb_build_object(
    'slot_id',p_slot_id,'slot_label',v_slot.slot_label,'new_employee_id',v_employee_id,'new_employee_name',v_name,
    'new_employee_code',v_created#>>'{employee,employee_code}','effective_start',p_effective_start,'phone_assignment',null
  )||v_completion);
  insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
  values(v_command,p_manager_id,v_actor->>'manager_name','fill_vacant_slot',p_idempotency_key,p_expected_revision,v_request_digest,v_request,v_response,v_response->>'output_digest',v_content_digest);
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_read_completed_roster_change(p_manager_id uuid, p_idempotency_key text, p_operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 v_mutation public.weekly_schedule_command_receipts%rowtype;
 v_receipt public.weekly_schedule_command_receipts%rowtype;
 v_projection public.weekly_schedule_compiled_projections%rowtype;
 v_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_date date;v_week date;v_projection_snapshot jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.custodial_assert_manager(p_manager_id);
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_operation is null or p_operation not in ('vacate_roster_slot','fill_vacant_slot','restore_existing_employee') or p_manager_id is null or nullif(btrim(p_idempotency_key),'') is null then
  raise exception using errcode='22023',message='completed vacancy lookup requires exact manager and command identity';
 end if;
 select * into v_mutation from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key=p_idempotency_key and command_type=p_operation;
 if not found then return null; end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_mutation.command_id,p_operation);
 if v_mutation.response_json#>>'{data,completion_mode}'='mutation_only'
   and (v_mutation.response_json->'data') ? 'original_publication_id'
   and v_mutation.response_json#>'{data,original_publication_id}'='null'::jsonb then
  return v_mutation.response_json;
 end if;
 if v_mutation.response_json#>>'{data,completion_mode}' is distinct from 'projection_required'
   or nullif(v_mutation.response_json#>>'{data,original_publication_id}','') is null then
  raise exception using errcode='23514',message='completed vacancy original completion binding is missing or inconsistent';
 end if;
 select * into v_receipt from public.weekly_schedule_command_receipts
  where actor_manager_id=p_manager_id and idempotency_key='projection-'||encode(extensions.digest(convert_to(p_idempotency_key,'UTF8'),'sha256'),'hex');
 if not found then
  raise exception using errcode='23514',message='completed vacancy required projection receipt is missing';
 end if;
 perform public.static_weekly_v8_assert_vacancy_receipt(v_receipt.command_id,'materialize_projection');
 v_date:=(v_mutation.request_canonical_json->>'effective_start')::date;
 v_week:=v_date-(extract(isodow from v_date)::integer-1);
 if v_receipt.command_type is distinct from 'materialize_projection'
  or v_receipt.expected_revision is distinct from (v_mutation.response_json->>'revision')::bigint
  or (v_receipt.response_json->>'revision')::bigint is distinct from v_receipt.expected_revision+1
  or v_receipt.request_canonical_json->>'service_date' is distinct from v_week::text
  or v_receipt.request_canonical_json->>'publication_id' is distinct from v_mutation.response_json#>>'{data,original_publication_id}' then
  raise exception using errcode='23514',message='completed vacancy projection receipt does not bind the exact mutation';
 end if;
 select * into v_projection from public.weekly_schedule_compiled_projections
  where projection_id=(v_receipt.response_json#>>'{data,projection_id}')::uuid;
 if not found or v_projection.week_start is distinct from v_week
  or v_projection.publication_id::text is distinct from v_receipt.request_canonical_json->>'publication_id'
  or v_projection.authority_digest is distinct from v_receipt.request_canonical_json#>>'{projection_envelope,authority_digest}'
  or v_projection.replay_digest is distinct from v_receipt.request_canonical_json->>'replay_digest' then
  raise exception using errcode='23514',message='completed vacancy immutable projection binding is missing or inconsistent';
 end if;
 select * into v_lunch from public.weekly_schedule_lunch_documents where projection_id=v_projection.projection_id;
 if not found or v_lunch.accepted_by_manager_id is distinct from p_manager_id
  or v_lunch.document_identity is distinct from v_lunch.document_json->>'document_identity'
  or v_lunch.document_json->>'base_authority_digest' is distinct from v_projection.authority_digest
  or v_lunch.document_json->>'base_replay_digest' is distinct from v_projection.replay_digest then
  raise exception using errcode='23514',message='completed vacancy accepted lunch binding is missing or inconsistent';
 end if;
 perform public.static_weekly_v8_assert_lunch_document(v_projection.projection_id,v_lunch.document_json);
 -- Match the immutable projection descriptor in the manager snapshot used by
 -- the first success. Do not read today's mutable latest-projection selector.
 v_projection_snapshot:=jsonb_build_object(
  'projection_id',v_projection.projection_id::text,'publication_id',v_projection.publication_id::text,
  'version_id',v_projection.version_id::text,'week_start',v_projection.week_start::text,'week_end',v_projection.week_end::text,
  'compiler_version',v_projection.compiler_version,'metrics',v_projection.metrics_json,
  'replay_digest',v_projection.replay_digest,'compiled_at',v_projection.compiled_at,
  'assignments',v_projection.projection_envelope->'assignments');
 return v_receipt.response_json||jsonb_build_object('data',
  (v_mutation.response_json->'data')||(v_receipt.response_json->'data')||
  jsonb_build_object('current_projection',v_projection_snapshot,'mutation',v_mutation.response_json->'data'));
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v9_roster_completion_context(p_source_id uuid, p_slot_id uuid, p_effective_start date, p_require_vacancy boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare source public.static_weekly_authority_source_documents%rowtype;
 publication uuid; publication_source uuid; matches integer;
begin
 perform public.static_weekly_v3_assert_control_plane();
 if p_source_id is null or p_slot_id is null or p_effective_start is null or p_require_vacancy is null then
  raise exception 'roster completion requires exact source, position and date'; end if;
 select * into source from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active and retired_at is null for share;
 if not found then raise exception 'roster completion requires active registered source'; end if;
 select count(*) into matches from jsonb_array_elements(source.canonical_source->'slots') s
  where s->>'id'=p_slot_id::text and coalesce(s->'contractorCapacity','false'::jsonb)='false'::jsonb;
 if matches<>1 or (p_require_vacancy and not coalesce((source.canonical_source#>'{version,vacancyCapableSlotIds}') ? p_slot_id::text,false)) then
  raise exception 'registered source must bind the exact vacancy-capable stable employee position'; end if;
 select p.publication_id,v.authority_source_id into publication,publication_source
  from public.weekly_schedule_publications p join public.weekly_schedule_versions v on v.version_id=p.version_id
  where p.version_id=public.static_weekly_effective_version(p_effective_start-(extract(isodow from p_effective_start)::int-1));
 if publication is not null and publication_source is distinct from p_source_id then
  raise exception 'roster source does not own the effective published baseline'; end if;
 return jsonb_build_object('source_id',p_source_id,'source_digest',source.source_digest,
  'completion_mode',case when publication is null then 'mutation_only' else 'projection_required' end,
  'original_publication_id',publication);
end $function$

CREATE OR REPLACE FUNCTION public.sch_apply_default_coverage_purpose()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_group_code text;
  v_employee_name text;
  v_template_purpose text;
begin
  select lg.group_code into v_group_code
  from public.location_groups lg
  where lg.id = new.location_group_id;

  if new.assigned_employee_id is not null then
    select e.display_name into v_employee_name
    from public.employees e
    where e.id = new.assigned_employee_id;
  end if;

  select ct.coverage_purpose into v_template_purpose
  from public.coverage_templates ct
  where ct.location_group_id = new.location_group_id
    and ct.day_of_week = extract(dow from new.service_date)::integer
    and ct.segment_number = new.segment_number
  limit 1;

  if new.coverage_purpose is null or new.coverage_purpose = 'area_owner' then
    new.coverage_purpose := coalesce(
      v_template_purpose,
      case
        when v_group_code in ('ELEPHANT_TRUNK_GIFT_SHOP','ELEPHANT_TRUNK_RESTROOMS','BAMBOO_GIFT_SHOP','NORTH_WEST_PASSAGE_GIFT_SHOP') then 'reminder'
        when v_employee_name = 'Michael McWright' then 'late_coverage'
        when new.coverage_start < time '09:45' then 'deep_clean'
        else coalesce(new.coverage_purpose, 'area_owner')
      end
    );
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_clear_scan_alerts_after_scan_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.location_code is not null then
    perform public.sch_clear_scan_alerts_for_location(new.location_code, 'new_scan_event');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_daily_absence_override_regenerate_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_start date;
  v_end date;
begin
  if tg_op = 'DELETE' then
    v_start := old.absence_date;
    v_end := old.absence_date;
  elsif tg_op = 'INSERT' then
    v_start := new.absence_date;
    v_end := new.absence_date;
  else
    v_start := least(coalesce(old.absence_date, new.absence_date), coalesce(new.absence_date, old.absence_date));
    v_end := greatest(coalesce(old.absence_date, new.absence_date), coalesce(new.absence_date, old.absence_date));
  end if;

  if current_setting('memphis.skip_absence_regen', true) = 'on' then
    return coalesce(new, old);
  end if;

  perform public.sch_regenerate_existing_schedules_for_absence_range(v_start, v_end);
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_ensure_schedule_window(p_start_date date DEFAULT sch_service_date(now()), p_days integer DEFAULT 14, p_reason text DEFAULT 'scheduled_rolling_window_readiness'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_start date := coalesce(p_start_date,public.sch_service_date(now()));
  v_days integer := greatest(1,least(coalesce(p_days,14),31));
  v_offset integer;
  v_date date;
  v_result jsonb;
  v_audit jsonb;
  v_authority record;
  v_results jsonb := '[]'::jsonb;
  v_ready integer := 0;
  v_failed integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('schedule-window:'||v_start::text||':'||v_days::text,0));

  for v_offset in 0..(v_days-1) loop
    v_date := v_start+v_offset;
    begin
      select * into strict v_authority
      from public.static_weekly_v6_schedule_authority_state(v_date);

      if v_authority.governed then
        if v_authority.projection_status='current' then
          v_ready := v_ready+1;
          v_results := v_results||jsonb_build_array(jsonb_build_object(
            'service_date',v_date,
            'ok',true,
            'authority_source',v_authority.authority_source,
            'projection_status',v_authority.projection_status,
            'publication_id',v_authority.publication_id,
            'projection_id',v_authority.projection_id,
            'legacy_mutation_skipped',true
          ));
        else
          v_failed := v_failed+1;
          v_results := v_results||jsonb_build_array(jsonb_build_object(
            'service_date',v_date,
            'ok',false,
            'authority_source',v_authority.authority_source,
            'projection_status',v_authority.projection_status,
            'error','static_weekly_projection_not_current',
            'legacy_mutation_skipped',true
          ));
        end if;
        continue;
      end if;

      v_result := public.sch_ensure_daily_schedule(
        v_date,
        coalesce(nullif(btrim(p_reason),''),'scheduled_rolling_window_readiness')
      );
      v_audit := public.sch_audit_schedule_day(v_date);
      if coalesce((v_audit->>'ok')::boolean,false) then
        v_ready := v_ready+1;
        v_results := v_results||jsonb_build_array(jsonb_build_object(
          'service_date',v_date,'ok',true,'authority_source','legacy_daily_schedule',
          'result',v_result,'audit',v_audit
        ));
      else
        v_failed := v_failed+1;
        v_results := v_results||jsonb_build_array(jsonb_build_object(
          'service_date',v_date,'ok',false,'authority_source','legacy_daily_schedule',
          'error','schedule_audit_failed','result',v_result,'audit',v_audit
        ));
      end if;
    exception when others then
      v_failed := v_failed+1;
      v_results := v_results||jsonb_build_array(jsonb_build_object(
        'service_date',v_date,'ok',false,'error',sqlerrm
      ));
    end;
  end loop;

  insert into public.schedule_automation_runs(
    automation_key,service_date,status,result_json,created_at,updated_at
  ) values (
    'rolling_schedule_window_ready',v_start,
    case when v_failed=0 then 'completed' else 'failed' end,
    jsonb_build_object(
      'start_date',v_start,'days',v_days,'reason',p_reason,
      'ready_days',v_ready,'failed_days',v_failed,'results',v_results
    ),now(),now()
  ) on conflict(automation_key,service_date) do update set
    status=excluded.status,result_json=excluded.result_json,updated_at=now();

  return jsonb_build_object(
    'ok',v_failed=0,'start_date',v_start,'days',v_days,
    'ready_days',v_ready,'failed_days',v_failed,'results',v_results
  );
end
$function$

CREATE OR REPLACE FUNCTION public.sch_guard_operational_coverage_template()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_group_code text;
begin
  select group_code into v_group_code
  from public.location_groups
  where id = new.location_group_id;

  if v_group_code like '%GIFT_SHOP' then
    if new.day_of_week = 1
       and coalesce(new.coverage_purpose, '') = 'reminder'
       and new.coverage_start >= time '08:00'
       and new.coverage_start <= time '08:30'
       and new.coverage_end <= time '09:45' then
      return new;
    end if;

    new.active := false;
    new.assigned_employee_id := null;
    new.owner_type := 'OPEN';
    new.notes := trim(concat_ws(' | ', nullif(new.notes, ''), 'Disabled by operational guard: gift shops are Monday morning reminder-only side work, not scan-system/lunch/after-9:45 work.'));
    return new;
  end if;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.sch_guard_operational_daily_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_group_code text;
  v_day integer;
  v_employee_name text;
begin
  select group_code into v_group_code
  from public.location_groups
  where id = new.location_group_id;

  if v_group_code is null then
    raise exception 'Unknown location_group_id %', new.location_group_id;
  end if;

  v_day := extract(dow from new.service_date)::integer;

  if v_group_code like '%GIFT_SHOP' and not (
    v_day = 1
    and coalesce(new.coverage_purpose, '') = 'reminder'
    and new.coverage_start >= time '08:00'
    and new.coverage_start <= time '08:30'
    and new.coverage_end <= time '09:45'
  ) then
    select display_name into v_employee_name
    from public.employees
    where id = new.assigned_employee_id;

    raise exception 'Gift shop guard: blocked assignment for employee "%" (id %) to "%" on service_date %. Gift shops are Monday morning reminder-only side work; this assignment does not meet the reminder-only criteria.',
      coalesce(v_employee_name, 'UNKNOWN'), coalesce(new.assigned_employee_id::text, 'NULL'), v_group_code, new.service_date;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sch_guard_restricted_coverage_template()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.assigned_employee_id is null then
