CREATE OR REPLACE FUNCTION public.static_weekly_sch022_projection_work(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare assignments jsonb;work jsonb;
begin
 assignments:=p_payload#>'{envelope,assignments}';
 if jsonb_typeof(assignments)<>'array' or jsonb_array_length(assignments)>10000 then
  raise exception using errcode='23514',message='SCH022 staged projection assignments unavailable';end if;
 if exists(select 1 from jsonb_array_elements(assignments) item
  where jsonb_typeof(item->'work_snapshot')<>'object') then
  raise exception using errcode='23514',message='SCH022 staged projection work identity unavailable';end if;
 select coalesce(jsonb_agg(public.static_weekly_sch022_normalize_work(
  nullif(item#>>'{work_snapshot,locationId}','')::uuid,item#>>'{work_snapshot,locationCodeSnapshot}',
  coalesce(item#>'{work_snapshot,includedLocations}','[]'::jsonb)) order by item->>'work_id'),'[]'::jsonb)
 into work from jsonb_array_elements(assignments) item;
 return work;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_staffing_accept_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare current_witness jsonb;prior public.static_weekly_sch022_staffing_witnesses%rowtype;
begin
 if old.state='PREPARED' and new.state='ACCEPTED' then
  current_witness:=public.static_weekly_sch022_staged_witness(new.operation_id);
  select * into prior from public.static_weekly_sch022_staffing_witnesses where operation_id=new.operation_id;
  if found then
   if prior.witness_digest is distinct from current_witness->>'digest'
    or prior.target_week_count is distinct from (current_witness->>'target_week_count')::integer
    or prior.manager_id is distinct from new.confirmed_by_manager_id
    or prior.preview_digest is distinct from new.preview_digest then
    raise exception using errcode='40001',message='SCH022 staffing confirmation requires a current exact catalog preview';end if;
  elsif (current_witness->>'target_week_count')::integer>0 then
   raise exception using errcode='23514',message='SCH022 target-bearing staffing confirmation has no prepared catalog witness';
  end if;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_stage_staffing_command(p_operation_id uuid, p_candidates jsonb, p_preview_digest text, p_input_digest text, p_publication_vector jsonb, p_manager_id uuid, p_witness_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare before_state text;staged jsonb;current_witness jsonb;prior public.static_weekly_sch022_staffing_witnesses%rowtype;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 if p_witness_digest is null or p_witness_digest!~'^[0-9a-f]{64}$' then
  raise exception using errcode='22023',message='SCH022 exact staffing preview witness required';end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select state into before_state from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 staged:=public.static_weekly_v10_stage_staffing_command(p_operation_id,p_candidates,p_preview_digest,
  p_input_digest,p_publication_vector,p_manager_id);
 current_witness:=public.static_weekly_sch022_staged_witness(p_operation_id);
 if current_witness->>'digest' is distinct from p_witness_digest then
  raise exception using errcode='40001',message='SCH022 staffing catalog changed since manager preview';end if;
 select * into prior from public.static_weekly_sch022_staffing_witnesses where operation_id=p_operation_id;
 if found then
  if prior.manager_id is distinct from p_manager_id or prior.witness_digest is distinct from p_witness_digest
   or prior.preview_digest is distinct from p_preview_digest then
   raise exception using errcode='23505',message='SCH022 staffing witness replay identity changed';end if;
 elsif before_state='PREPARING' then
  insert into public.static_weekly_sch022_staffing_witnesses(operation_id,manager_id,witness_digest,target_week_count,preview_digest)
  values(p_operation_id,p_manager_id,p_witness_digest,(current_witness->>'target_week_count')::integer,p_preview_digest);
 elsif (current_witness->>'target_week_count')::integer>0 then
  raise exception using errcode='23514',message='SCH022 protected target-bearing staffing preview has no original witness';
 end if;
 return staged;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_sch022_work_witness(p_service_date date, p_work jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare g public.location_groups%rowtype;w jsonb;included jsonb;id_text text;
 target boolean:=false; unbound_target boolean:=false; member_ids uuid[];retained_ids uuid[];
 included_ids uuid[]:=array[]::uuid[];row_ids uuid[];row_target boolean;
 source_rows jsonb;v_head jsonb;result text;
begin
 if p_service_date is null or jsonb_typeof(p_work) is distinct from 'array'
  or jsonb_array_length(p_work)>10000 then
  raise exception using errcode='22023',message='SCH022 requires bounded typed work and an exact service date';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 lock table public.location_groups,public.location_group_memberships,public.locations,
  public.custodial_place_source_versions in share mode;
 select * into g from public.location_groups where group_code='SPLASH_PAD_RESTROOMS' for share;
 select coalesce(array_agg(distinct m.location_id order by m.location_id) filter(where m.active=true),array[]::uuid[]),
  coalesce(array_agg(distinct m.location_id order by m.location_id),array[]::uuid[])
 into member_ids,retained_ids from public.location_group_memberships m where m.location_group_id=g.id;
 for w in select value from jsonb_array_elements(p_work) loop
  if jsonb_typeof(w) is distinct from 'object'
   or (select array_agg(key order by key) from jsonb_object_keys(w) key)
      is distinct from array['includedLocationIds','locationCode','locationId']::text[]
   or jsonb_typeof(w->'locationCode') is distinct from 'string'
   or jsonb_typeof(w->'includedLocationIds') is distinct from 'array'
   or jsonb_array_length(w->'includedLocationIds')>256 then
   raise exception using errcode='22023',message='SCH022 typed work identity is invalid';
  end if;
  included:=w->'includedLocationIds';row_ids:=array[]::uuid[];
  if jsonb_typeof(w->'locationId') not in ('string','null') then
   raise exception using errcode='22023',message='SCH022 typed work location identity is invalid';
  end if;
  if w->>'locationId' is not null then
   begin row_ids:=array_append(row_ids,(w->>'locationId')::uuid);
   exception when invalid_text_representation then
    raise exception using errcode='22023',message='SCH022 typed work location UUID is invalid';end;
  end if;
  for id_text in select value from jsonb_array_elements_text(included) value loop
   begin row_ids:=array_append(row_ids,id_text::uuid);
   exception when invalid_text_representation then
    raise exception using errcode='22023',message='SCH022 included location UUID is invalid';end;
  end loop;
  row_target:=w->>'locationCode'='SPLASH_PAD_RESTROOMS' or (g.id is not null and
   exists(select 1 from unnest(row_ids) member(member_id)
    where member.member_id=g.id or member.member_id=any(retained_ids)));
  if row_target then
   target:=true;included_ids:=included_ids||row_ids;
   if not exists(select 1 from unnest(row_ids) member(member_id)
    where member.member_id=any(member_ids)) then unbound_target:=true;end if;
  end if;
 end loop;
 if not target then return public.static_weekly_digest_jsonb(jsonb_build_object('sch022','NO_TARGET_V1'));end if;
 if g.id is null or g.active is not true then
  raise exception using errcode='23514',message='Splash Pad Restrooms duty requires the exact active custodial group';
 end if;
 if p_service_date<date '2027-05-31' then
  raise exception using errcode='23514',message='Splash Pad Restrooms coverage is inactive before Memorial Day 2027';
 end if;
 if cardinality(member_ids)=0 or unbound_target or exists(select 1 from unnest(included_ids) member(member_id)
  where member.member_id<>g.id and member.member_id<>all(member_ids)) then
  raise exception using errcode='23514',message='Splash Pad Restrooms duty must bind current exact group members';
 end if;
 if exists(select 1 from unnest(member_ids) member(member_id) left join public.locations l on l.id=member.member_id
  where l.id is null or l.active is not true) then
  raise exception using errcode='23514',message='Splash Pad Restrooms has an inactive or unbound physical member';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'source',public.place_source_row('physical_location',l.id),
  'source_updated_at',l.updated_at,
  'place_head',(select jsonb_build_object('revision',v.revision,'effective_at',v.effective_at,'source_row_sha256',v.source_row_sha256)
   from public.custodial_place_source_versions v where v.legacy_kind='physical_location' and v.legacy_id=l.id
   order by v.revision desc limit 1)) order by l.id),'[]'::jsonb)
 into source_rows from public.locations l where l.id=any(member_ids);
 select jsonb_build_object('revision',v.revision,'effective_at',v.effective_at,'source_row_sha256',v.source_row_sha256)
 into v_head from public.custodial_place_source_versions v
 where v.legacy_kind='location_group' and v.legacy_id=g.id order by v.revision desc limit 1;
 result:=public.static_weekly_digest_jsonb(jsonb_build_object('sch022','TARGET_V1','group_id',g.id,
  'group_source',public.place_source_row('location_group',g.id),'group_place_head',v_head,
  'membership_revisions',(select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'location_id',m.location_id,
   'active',m.active,'updated_at',m.updated_at) order by m.id),'[]'::jsonb)
   from public.location_group_memberships m where m.location_group_id=g.id),
  'members',source_rows,'start',date '2027-05-31'));
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_ack_device_schedule_application(p_intent_id uuid, p_device_id uuid, p_credential_id uuid, p_employee_id uuid, p_assignment_epoch bigint, p_authority_revision bigint, p_projection_id uuid, p_lunch_document_identity text, p_rendered_digest text, p_applied_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare target public.static_weekly_schedule_application_intents%rowtype;prior public.static_weekly_schedule_application_receipts%rowtype;v_receipt uuid:=gen_random_uuid();
begin
 if p_rendered_digest is null or p_rendered_digest!~'^[0-9a-f]{64}$' or p_applied_at is null
  or p_applied_at>statement_timestamp()+interval '5 minutes' then
  raise exception using errcode='22023',message='invalid schedule application receipt';end if;
 select * into target from public.static_weekly_schedule_application_intents where intent_id=p_intent_id for share;
 if not found or target.device_id is distinct from p_device_id or target.credential_id is distinct from p_credential_id
  or target.employee_id is distinct from p_employee_id or target.assignment_epoch is distinct from p_assignment_epoch
  or target.authority_revision is distinct from p_authority_revision or target.projection_id is distinct from p_projection_id
  or target.lunch_document_identity is distinct from p_lunch_document_identity or p_applied_at<target.created_at then
  raise exception using errcode='23514',message='schedule application receipt does not match its complete target';end if;
 if not exists(select 1 from public.devices d where d.id=p_device_id and d.active=true
   and d.assigned_employee_id=p_employee_id and d.assignment_epoch=p_assignment_epoch)
  or not exists(select 1 from public.device_auth_credentials c where c.credential_id=p_credential_id
   and c.device_id=p_device_id and c.confirmed_at is not null and c.revoked_at is null
   and c.expires_at>statement_timestamp()) then
  raise exception using errcode='42501',message='current schedule application principal is required';end if;
 select * into prior from public.static_weekly_schedule_application_receipts where intent_id=p_intent_id;
 if found then
  if prior.employee_id is distinct from p_employee_id or prior.device_id is distinct from p_device_id
   or prior.credential_id is distinct from p_credential_id or prior.assignment_epoch is distinct from p_assignment_epoch
   or prior.authority_revision is distinct from p_authority_revision or prior.projection_id is distinct from p_projection_id
   or prior.lunch_document_identity is distinct from p_lunch_document_identity
   or prior.rendered_digest is distinct from p_rendered_digest or prior.applied_at is distinct from p_applied_at then
   raise exception using errcode='23505',message='schedule application intent already has a different receipt';end if;
  return jsonb_build_object('intent_id',prior.intent_id,'receipt_id',prior.receipt_id,
   'application_status','DEVICE_REPORTED_APPLIED','received_at',prior.received_at,'replayed',true);
 end if;
 insert into public.static_weekly_schedule_application_receipts(receipt_id,intent_id,employee_id,device_id,
  credential_id,assignment_epoch,authority_revision,projection_id,lunch_document_identity,rendered_digest,applied_at)
 values(v_receipt,p_intent_id,p_employee_id,p_device_id,p_credential_id,p_assignment_epoch,p_authority_revision,
  p_projection_id,p_lunch_document_identity,p_rendered_digest,p_applied_at);
 return jsonb_build_object('intent_id',p_intent_id,'receipt_id',v_receipt,
  'application_status','DEVICE_REPORTED_APPLIED','received_at',statement_timestamp(),'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_begin_staffing_command(p_semantic_body jsonb, p_client_prepare_key uuid, p_expected_revision bigint, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb; prior public.static_weekly_staffing_commands%rowtype;
 v_operation uuid:=gen_random_uuid();v_command_kind text;v_employee uuid;v_start_date date;v_end_date date;
 v_absence_kind text;v_target_absence uuid;v_current_revision bigint;v_receipt jsonb;v_semantic_digest text;
begin
 perform public.static_weekly_v3_assert_control_plane();
 actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 if jsonb_typeof(p_semantic_body) is distinct from 'object'
  or (select array_agg(key order by key) from jsonb_object_keys(p_semantic_body) key)
   is distinct from array['absenceKind','commandKind','employeeId','endDate','startDate','targetAbsenceId']::text[]
  or p_client_prepare_key is null or p_expected_revision is null or p_expected_revision<0 then
  raise exception using errcode='22023',message='invalid canonical staffing command';
 end if;
 v_semantic_digest:=public.static_weekly_digest_jsonb(p_semantic_body);
 v_command_kind:=p_semantic_body->>'commandKind';
 v_employee:=(p_semantic_body->>'employeeId')::uuid;
 v_start_date:=(p_semantic_body->>'startDate')::date;
 v_end_date:=(p_semantic_body->>'endDate')::date;
 v_absence_kind:=nullif(p_semantic_body->>'absenceKind','');
 v_target_absence:=nullif(p_semantic_body->>'targetAbsenceId','')::uuid;
 if v_start_date>v_end_date or v_end_date-v_start_date>=366
  or (v_command_kind='absence' and (v_absence_kind not in ('daily_absence','pto','unavailable') or v_target_absence is not null))
  or (v_command_kind='cancel_absence' and (v_absence_kind is not null or v_target_absence is null))
  or v_command_kind not in ('absence','cancel_absence') then
  raise exception using errcode='22023',message='invalid staffing command semantics';
 end if;
 select * into prior from public.static_weekly_staffing_commands
  where prepared_by_manager_id=p_manager_id and client_prepare_key=p_client_prepare_key for share;
 if found then
  if prior.semantic_digest is distinct from v_semantic_digest or prior.semantic_body is distinct from p_semantic_body
   or prior.expected_revision is distinct from p_expected_revision then
   raise exception using errcode='23505',message='staffing prepare key was used for different semantics';
  end if;
  return jsonb_build_object('operation_id',prior.operation_id,'state',prior.state,
   'semantic_digest',prior.semantic_digest,'expected_revision',prior.expected_revision,'replayed',true);
 end if;
 if v_command_kind='cancel_absence' and v_start_date<public.sch_service_date(statement_timestamp()) then
  raise exception using errcode='23514',message='staffing cancellation cannot rewrite an elapsed service date';end if;
 select control.current_revision into v_current_revision from public.static_weekly_schedule_control control where control.singleton for share;
 if v_current_revision is distinct from p_expected_revision then
  raise exception using errcode='40001',message='staffing command expected revision is stale';
 end if;
 if not exists(select 1 from public.employees where id=v_employee and active=true) then
  raise exception using errcode='23514',message='staffing command employee is not currently active';
 end if;
 if v_command_kind='cancel_absence' and not exists(
  select 1 from public.static_weekly_staffing_absences a where a.absence_id=v_target_absence
   and a.employee_id=v_employee and v_start_date between a.start_date and a.end_date and v_end_date=a.end_date
   and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id)
 ) then raise exception using errcode='23514',message='cancellation must target the exact uncancelled remaining absence window'; end if;
 perform set_config('app.static_weekly_staffing_write','on',true);
 insert into public.static_weekly_staffing_commands(operation_id,command_kind,employee_id,start_date,end_date,
  absence_kind,target_absence_id,semantic_body,semantic_digest,client_prepare_key,expected_revision,prepared_by_manager_id)
 values(v_operation,v_command_kind,v_employee,v_start_date,v_end_date,v_absence_kind,v_target_absence,p_semantic_body,
  v_semantic_digest,p_client_prepare_key,p_expected_revision,p_manager_id);
 v_receipt:=jsonb_build_object('operation_id',v_operation,'event','PREPARING','manager_id',p_manager_id,
  'semantic_digest',v_semantic_digest,'expected_revision',p_expected_revision,'recorded_at',statement_timestamp());
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest)
 values(v_operation,'PREPARING',p_manager_id,v_semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
 return jsonb_build_object('operation_id',v_operation,'state','PREPARING','semantic_digest',v_semantic_digest,
  'expected_revision',p_expected_revision,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_cancel_staffing_preparation(p_operation_id uuid, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;command public.static_weekly_staffing_commands%rowtype;v_event text;v_receipt jsonb;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 if not found then raise exception using errcode='P0002',message='staffing command is unavailable';end if;
 if command.state='ACCEPTED' then
  return jsonb_build_object('operation_id',command.operation_id,'state','ACCEPTED',
   'accepted_revision',command.accepted_revision,'accepted_receipt',command.accepted_receipt,'cancelled',false);
 end if;
 if command.state in ('CANCELLED','CANCELLED_BY_SUCCESSOR','REJECTED') then
  return jsonb_build_object('operation_id',command.operation_id,'state',command.state,'cancelled',command.state<>'REJECTED','replayed',true);
 end if;
 if command.state not in ('PREPARING','PREPARED') then
  raise exception using errcode='55000',message='staffing command cannot be cancelled from its current state';end if;
 v_event:=case when command.prepared_by_manager_id=p_manager_id then 'CANCELLED' else 'CANCELLED_BY_SUCCESSOR' end;
 perform set_config('app.static_weekly_staffing_write','on',true);
 update public.static_weekly_staffing_commands set state=v_event where operation_id=command.operation_id;
 v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event',v_event,'manager_id',p_manager_id,
  'original_preparer_manager_id',command.prepared_by_manager_id,'semantic_digest',command.semantic_digest,
  'recorded_at',statement_timestamp());
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest) values(command.operation_id,v_event,p_manager_id,
  command.semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
 return jsonb_build_object('operation_id',command.operation_id,'state',v_event,'cancelled',true,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_staffing_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if tg_op='DELETE' then raise exception 'staffing commands are durable and cannot be deleted'; end if;
 if current_setting('app.static_weekly_staffing_write',true) is distinct from 'on' then
  raise exception 'staffing command transitions require the typed authority RPC';
 end if;
 if (to_jsonb(new)-array['state','preview_digest','input_digest','candidate_set_digest','candidate_row_count',
  'candidate_bytes','publication_vector','candidate_summary','accepted_revision','accepted_receipt',
  'prepared_at','accepted_at','confirmation_key','confirmed_by_manager_id','authority_command_id']) is distinct from
  (to_jsonb(old)-array['state','preview_digest','input_digest','candidate_set_digest','candidate_row_count',
  'candidate_bytes','publication_vector','candidate_summary','accepted_revision','accepted_receipt',
  'prepared_at','accepted_at','confirmation_key','confirmed_by_manager_id','authority_command_id']) then
  raise exception 'immutable staffing command identity changed'; end if;
 if not ((old.state='PREPARING' and new.state in ('PREPARED','CANCELLED','CANCELLED_BY_SUCCESSOR','REJECTED'))
  or (old.state='PREPARED' and new.state in ('ACCEPTED','CANCELLED','CANCELLED_BY_SUCCESSOR','REJECTED')))
  then raise exception 'invalid staffing command state transition'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v10_stage_staffing_command(p_operation_id uuid, p_candidates jsonb, p_preview_digest text, p_input_digest text, p_publication_vector jsonb, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;command public.static_weekly_staffing_commands%rowtype;
 v_candidate_set_digest text;v_candidate_rows integer;v_candidate_bytes bigint;v_week_count integer;
 v_projection_weeks integer;v_lunch_weeks integer;v_summary jsonb;v_receipt jsonb;v_current_revision bigint;
begin
 perform public.static_weekly_v3_assert_control_plane();
 actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 if not found then raise exception using errcode='P0002',message='staffing command is unavailable';end if;
 if command.prepared_by_manager_id is distinct from p_manager_id then
  raise exception using errcode='42501',message='only the authenticated original preparer may stage this command';end if;
 if p_preview_digest is null or p_preview_digest!~'^[0-9a-f]{64}$'
  or p_input_digest is null or p_input_digest!~'^[0-9a-f]{64}$'
  or jsonb_typeof(p_publication_vector) is distinct from 'object'
  or jsonb_typeof(p_candidates) is distinct from 'array' then
  raise exception using errcode='22023',message='invalid staffing candidate envelope';end if;
 v_candidate_set_digest:=public.static_weekly_digest_jsonb(p_candidates);
 if command.state='PREPARED' then
  if command.candidate_set_digest is distinct from v_candidate_set_digest
   or command.preview_digest is distinct from p_preview_digest
   or command.input_digest is distinct from p_input_digest
   or command.publication_vector is distinct from p_publication_vector then
   raise exception using errcode='23505',message='prepared staffing operation was replayed with different candidates';end if;
  return jsonb_build_object('operation_id',command.operation_id,'state',command.state,
   'candidate_set_digest',command.candidate_set_digest,'candidate_row_count',command.candidate_row_count,
   'candidate_bytes',command.candidate_bytes,'candidate_summary',command.candidate_summary,'replayed',true);
 end if;
 if command.state<>'PREPARING' then raise exception using errcode='55000',message='staffing command cannot be staged from its current state';end if;
 select control.current_revision into v_current_revision from public.static_weekly_schedule_control control where control.singleton for share;
 if v_current_revision is distinct from command.expected_revision then
  raise exception using errcode='40001',message='staffing command expected revision became stale during preparation';end if;
 if not exists(select 1 from public.employees where id=command.employee_id and active=true) then
  raise exception using errcode='23514',message='staffing command employee is no longer active';end if;
 if command.command_kind='cancel_absence' and command.start_date<public.sch_service_date(statement_timestamp()) then
  raise exception using errcode='23514',message='staffing cancellation cannot rewrite an elapsed service date during preparation';end if;
 if command.command_kind='cancel_absence' and not exists(
  select 1 from public.static_weekly_staffing_absences a where a.absence_id=command.target_absence_id
   and a.employee_id=command.employee_id and command.start_date between a.start_date and a.end_date
   and command.end_date=a.end_date
   and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id)
 ) then raise exception using errcode='23514',message='staffing cancellation remaining window changed during preparation';end if;
 if jsonb_array_length(p_candidates)>100000 then raise exception using errcode='54000',message='staffing candidate row limit exceeded';end if;
 if exists(select 1 from jsonb_array_elements(p_candidates) item where jsonb_typeof(item)<>'object'
   or (select array_agg(key order by key) from jsonb_object_keys(item) key)
      is distinct from array['candidateKey','candidateKind','payload','serviceDate']::text[]
   or jsonb_typeof(item->'candidateKind') is distinct from 'string'
   or item->>'candidateKind' not in ('projection','lunch','schedule_refresh')
   or jsonb_typeof(item->'candidateKey') is distinct from 'string'
   or length(btrim(item->>'candidateKey')) not between 1 and 300
   or item->>'candidateKey' is distinct from btrim(item->>'candidateKey')
   or jsonb_typeof(item->'serviceDate') is distinct from 'string'
   or item->>'serviceDate'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   or jsonb_typeof(item->'payload') is distinct from 'object'
   or case when item->>'candidateKind' in ('projection','lunch')
      then (item->>'serviceDate')::date not between date_trunc('week',command.start_date::timestamp)::date
        and date_trunc('week',command.end_date::timestamp)::date
      else (item->>'serviceDate')::date not between command.start_date and command.end_date end) then
  raise exception using errcode='22023',message='invalid staffing candidate row';end if;
 if p_candidates is distinct from (select coalesce(jsonb_agg(item order by (item->>'serviceDate') collate "C",
   (item->>'candidateKind') collate "C",(item->>'candidateKey') collate "C"),'[]'::jsonb) from jsonb_array_elements(p_candidates) item) then
  raise exception using errcode='22023',message='staffing candidates are not in deterministic order';end if;
 if exists(select 1 from jsonb_array_elements(p_candidates) item
  group by item->>'candidateKind',item->>'candidateKey' having count(*)<>1) then
  raise exception using errcode='23505',message='duplicate staffing candidate identity';end if;
 select count(*) into v_week_count from generate_series(
  date_trunc('week',command.start_date::timestamp)::date,
  date_trunc('week',command.end_date::timestamp)::date,'7 days'::interval);
 select count(distinct (item->>'serviceDate')::date) filter(where item->>'candidateKind'='projection'),
  count(distinct (item->>'serviceDate')::date) filter(where item->>'candidateKind'='lunch')
 into v_projection_weeks,v_lunch_weeks from jsonb_array_elements(p_candidates) item
 where extract(isodow from (item->>'serviceDate')::date)=1;
 if v_projection_weeks is distinct from v_week_count or v_lunch_weeks is distinct from v_week_count
  or exists(select 1 from generate_series(date_trunc('week',command.start_date::timestamp)::date,
    date_trunc('week',command.end_date::timestamp)::date,'7 days'::interval) week_start
   where not exists(select 1 from jsonb_array_elements(p_candidates) item
    where item->>'candidateKind'='projection' and (item->>'serviceDate')::date=week_start::date)
    or not exists(select 1 from jsonb_array_elements(p_candidates) item
    where item->>'candidateKind'='lunch' and (item->>'serviceDate')::date=week_start::date)) then
  raise exception using errcode='23514',message='staffing projection or lunch candidate weeks are incomplete';end if;
 select count(*),coalesce(sum(octet_length(item::text)),0) into v_candidate_rows,v_candidate_bytes
  from jsonb_array_elements(p_candidates) item;
 if v_candidate_bytes>16777216 then raise exception using errcode='54000',message='staffing candidate byte limit exceeded';end if;
 v_summary:=jsonb_build_object('weeks',v_week_count,
  'projections',(select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='projection'),
  'lunches',(select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='lunch'),
  'scheduleRefreshes',(select count(*) from jsonb_array_elements(p_candidates) item where item->>'candidateKind'='schedule_refresh'));
 insert into public.static_weekly_staffing_staged_candidates(operation_id,candidate_kind,candidate_key,service_date,
  payload_json,payload_digest,canonical_bytes)
 select command.operation_id,item->>'candidateKind',item->>'candidateKey',(item->>'serviceDate')::date,item->'payload',
  public.static_weekly_digest_jsonb(item->'payload'),octet_length(item::text)
 from jsonb_array_elements(p_candidates) item;
 perform set_config('app.static_weekly_staffing_write','on',true);
 update public.static_weekly_staffing_commands set state='PREPARED',preview_digest=p_preview_digest,
  input_digest=p_input_digest,candidate_set_digest=v_candidate_set_digest,candidate_row_count=v_candidate_rows,
  candidate_bytes=v_candidate_bytes,publication_vector=p_publication_vector,candidate_summary=v_summary,
  prepared_at=statement_timestamp() where operation_id=command.operation_id;
 v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event','PREPARED','manager_id',p_manager_id,
  'semantic_digest',command.semantic_digest,'candidate_set_digest',v_candidate_set_digest,
  'candidate_row_count',v_candidate_rows,'candidate_bytes',v_candidate_bytes,'recorded_at',statement_timestamp());
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest) values(command.operation_id,'PREPARED',p_manager_id,
  command.semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
 return jsonb_build_object('operation_id',command.operation_id,'state','PREPARED',
  'candidate_set_digest',v_candidate_set_digest,'candidate_row_count',v_candidate_rows,
  'candidate_bytes',v_candidate_bytes,'candidate_summary',v_summary,'replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v11_accept_staffing_command(p_operation_id uuid, p_preview_digest text, p_confirmation_key uuid, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare actor jsonb;command public.static_weekly_staffing_commands%rowtype;target_absence public.static_weekly_staffing_absences%rowtype;
 v_candidates jsonb;v_count integer;v_bytes bigint;v_current_revision bigint;v_revision bigint;
 v_content_digest text;v_projection_candidate record;v_lunch jsonb;v_payload jsonb;v_projection_response jsonb;
 v_projection uuid;v_existing public.weekly_schedule_compiled_projections%rowtype;v_existing_lunch public.weekly_schedule_lunch_documents%rowtype;
 v_signed_envelope jsonb;v_request jsonb;v_request_digest text;v_projection_content_digest text;v_projection_receipt jsonb;
 v_projection_map jsonb:='{}'::jsonb;v_refresh record;v_mapping jsonb;v_intent_count integer:=0;
 v_missing_device jsonb:='[]'::jsonb;v_prior_refresh jsonb:='[]'::jsonb;v_receipt jsonb;v_receipt_digest text;v_reused boolean;v_command_id uuid;
begin
 perform public.static_weekly_v3_assert_control_plane();actor:=public.static_weekly_v3_manager_actor(p_manager_id);
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into command from public.static_weekly_staffing_commands where operation_id=p_operation_id for update;
 if not found then raise exception using errcode='P0002',message='staffing command is unavailable';end if;
 if command.state='ACCEPTED' then
  if command.prepared_by_manager_id is distinct from p_manager_id
   or command.confirmation_key is distinct from p_confirmation_key
   or command.preview_digest is distinct from p_preview_digest then
   raise exception using errcode='23505',message='accepted staffing command was replayed with different confirmation identity';end if;
  return command.accepted_receipt||jsonb_build_object('replayed',true);
 end if;
 if command.state<>'PREPARED' then raise exception using errcode='55000',message='staffing command is not prepared for acceptance';end if;
 if command.prepared_by_manager_id is distinct from p_manager_id then
  raise exception using errcode='42501',message='only the authenticated original preparer may confirm this command';end if;
 if p_confirmation_key is null or p_preview_digest is null or p_preview_digest!~'^[0-9a-f]{64}$'
  or command.preview_digest is distinct from p_preview_digest then
  raise exception using errcode='22023',message='exact staffing preview and confirmation key are required';end if;
 if command.command_kind='cancel_absence' and command.start_date<public.sch_service_date(statement_timestamp()) then
  perform set_config('app.static_weekly_staffing_write','on',true);
  update public.static_weekly_staffing_commands set state='REJECTED' where operation_id=command.operation_id;
  v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event','REJECTED',
   'reason','ELAPSED_CANCELLATION','manager_id',p_manager_id,'semantic_digest',command.semantic_digest,
   'preview_digest',command.preview_digest,'recorded_at',statement_timestamp());
  insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
   semantic_digest,receipt_json,receipt_digest) values(command.operation_id,'REJECTED',p_manager_id,
   command.semantic_digest,v_receipt,public.static_weekly_digest_jsonb(v_receipt));
  return jsonb_build_object('operation_id',command.operation_id,'state','REJECTED',
   'reason','ELAPSED_CANCELLATION','replayed',false);
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('candidateKey',candidate_key,'candidateKind',candidate_kind,
  'payload',payload_json,'serviceDate',service_date::text)
  order by service_date,candidate_kind collate "C",candidate_key collate "C"),'[]'::jsonb),
  count(*),coalesce(sum(canonical_bytes),0) into v_candidates,v_count,v_bytes
 from public.static_weekly_staffing_staged_candidates where operation_id=command.operation_id;
 if public.static_weekly_digest_jsonb(v_candidates) is distinct from command.candidate_set_digest
  or v_count is distinct from command.candidate_row_count or v_bytes is distinct from command.candidate_bytes
  or v_count>100000 or v_bytes>16777216 then
  raise exception using errcode='23514',message='prepared staffing candidate set no longer matches its complete digest';end if;
 select current_revision into v_current_revision from public.static_weekly_schedule_control where singleton for update;
 if v_current_revision is distinct from command.expected_revision then
  raise exception using errcode='40001',message='staffing confirmation expected revision is stale';end if;
 if not exists(select 1 from public.employees where id=command.employee_id and active=true) then
  raise exception using errcode='23514',message='staffing command employee is no longer active';end if;
 if command.command_kind='cancel_absence' then
  select * into target_absence from public.static_weekly_staffing_absences a
   where a.absence_id=command.target_absence_id and a.employee_id=command.employee_id
    and command.start_date between a.start_date and a.end_date and command.end_date=a.end_date
    and not exists(select 1 from public.static_weekly_staffing_absence_cancellations c where c.absence_id=a.absence_id)
   for share;
  if not found then raise exception using errcode='23514',message='staffing cancellation must target the exact uncancelled remaining absence window';end if;
 end if;
 if jsonb_typeof(command.publication_vector) is distinct from 'object'
  or (select array_agg(key order by key) from jsonb_object_keys(command.publication_vector) key)
    is distinct from array['expectedRevision','weeks']::text[]
  or (command.publication_vector->>'expectedRevision')::bigint<>command.expected_revision
  or jsonb_typeof(command.publication_vector->'weeks') is distinct from 'array' then
  raise exception using errcode='23514',message='prepared staffing publication vector is invalid';end if;
 if exists(select 1 from jsonb_array_elements(command.publication_vector->'weeks') week
  where jsonb_typeof(week)<>'object'
   or (select array_agg(key order by key) from jsonb_object_keys(week) key)
      is distinct from array['authorityRevision','publicationId','versionId','weekStart']::text[]
   or (week->>'authorityRevision')::bigint<>command.expected_revision
   or not exists(select 1 from public.weekly_schedule_publications p
    where p.publication_id=(week->>'publicationId')::uuid and p.version_id=(week->>'versionId')::uuid
     and public.static_weekly_effective_version((week->>'weekStart')::date)=p.version_id)) then
  raise exception using errcode='23514',message='prepared staffing publication vector became stale';end if;
 if (select count(*) from jsonb_array_elements(command.publication_vector->'weeks'))<>
    (select count(*) from public.static_weekly_staffing_staged_candidates
      where operation_id=command.operation_id and candidate_kind='projection') then
  raise exception using errcode='23514',message='prepared staffing projection vector is incomplete';end if;

 v_prior_refresh:=public.static_weekly_v11_read_current_refresh_targets(
  command.start_date,command.end_date,p_manager_id);

 v_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object('operation_id',command.operation_id,
  'semantic_digest',command.semantic_digest,'preview_digest',command.preview_digest,
  'input_digest',command.input_digest,'candidate_set_digest',command.candidate_set_digest,
  'publication_vector',command.publication_vector));
 v_revision:=public.static_weekly_advance_authority(command.expected_revision,'apply_staffing_command',
  p_manager_id,actor->>'manager_name',command.operation_id,v_content_digest);
 if command.command_kind='absence' then
  insert into public.static_weekly_staffing_absences(absence_id,employee_id,absence_kind,start_date,end_date,
   accepted_operation_id,accepted_revision,accepted_by_manager_id)
  values(command.operation_id,command.employee_id,command.absence_kind,command.start_date,command.end_date,
   command.operation_id,v_revision,p_manager_id);
 else
  insert into public.static_weekly_staffing_absence_cancellations(absence_id,accepted_operation_id,
   remaining_start_date,remaining_end_date,accepted_revision,accepted_by_manager_id)
  values(command.target_absence_id,command.operation_id,command.start_date,command.end_date,v_revision,p_manager_id);
 end if;
 perform set_config('app.static_weekly_staffing_batch_operation',command.operation_id::text,true);

 for v_projection_candidate in select service_date,payload_json from public.static_weekly_staffing_staged_candidates
  where operation_id=command.operation_id and candidate_kind='projection' order by service_date,candidate_key loop
  v_payload:=v_projection_candidate.payload_json;
  if (select array_agg(key order by key) from jsonb_object_keys(v_payload) key) is distinct from
   array['actorManagerId','actorManagerName','compilerVersion','envelope','exceptionSetDigest','expectedRevision',
    'idempotencyKey','metrics','objective','publicationId','replayDigest','serviceDate']::text[]
   or (v_payload->>'serviceDate')::date is distinct from v_projection_candidate.service_date
   or (v_payload->>'expectedRevision')::bigint is distinct from command.expected_revision
   or v_payload->>'actorManagerId' is distinct from p_manager_id::text
   or v_payload->>'idempotencyKey' is distinct from 'staffing:'||command.operation_id::text||':'||v_projection_candidate.service_date::text
   or not exists(select 1 from jsonb_array_elements(command.publication_vector->'weeks') week
    where week->>'weekStart'=v_projection_candidate.service_date::text
     and week->>'publicationId'=v_payload->>'publicationId'
     and week->>'versionId'=v_payload#>>'{envelope,authority,compilerInput,version,id}') then
   raise exception using errcode='23514',message='staged staffing projection identity is invalid';end if;
  if v_payload->>'exceptionSetDigest' is distinct from public.static_weekly_digest_jsonb(
    public.static_weekly_accepted_exception_set((v_payload->>'publicationId')::uuid,v_projection_candidate.service_date))
   or v_payload->>'compilerVersion' is distinct from v_payload#>>'{envelope,compiler_version}'
   or v_payload->'objective' is distinct from v_payload#>'{envelope,objective}'
   or v_payload->'metrics' is distinct from v_payload#>'{envelope,metrics}'
   or v_payload->>'replayDigest' is distinct from v_payload#>>'{envelope,replay_digest}' then
   raise exception using errcode='23514',message='staged staffing projection compiler identity no longer matches accepted exception authority',
    detail=jsonb_build_object('staged_exception_digest',v_payload->>'exceptionSetDigest',
     'database_exception_digest',public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(
      (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date)),
     'staged_exceptions',v_payload#>'{envelope,applied_exceptions}',
     'database_exceptions',public.static_weekly_accepted_exception_set(
      (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date))::text;end if;
  v_signed_envelope:=jsonb_set(v_payload->'envelope','{attestation}',
   public.static_weekly_v3_issue_attestation('dated_projection',
    public.static_weekly_projection_attestation_payload(v_payload->'envelope')),true);
  select * into v_existing from public.weekly_schedule_compiled_projections p
   where p.publication_id=(v_payload->>'publicationId')::uuid
    and p.week_start=v_projection_candidate.service_date
    and p.exception_set_digest=public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(
     (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date))
    and p.compiler_version=v_payload->>'compilerVersion'
    and p.authority_digest=v_signed_envelope->>'authority_digest'
   order by p.compiled_at desc,p.projection_id desc limit 1;
  v_reused:=found;
  if v_reused then
   if (v_existing.projection_envelope-array['attestation','receipt','database_projection_identity']) is distinct from
      (v_signed_envelope-array['attestation','receipt','database_projection_identity']) then
    raise exception using errcode='23514',message='historical projection identity conflicts with the exact staged candidate';end if;
   v_projection:=v_existing.projection_id;
   v_command_id:=gen_random_uuid();
   v_request:=jsonb_build_object('operation','materialize_projection','publication_id',(v_payload->>'publicationId')::uuid,
    'service_date',v_projection_candidate.service_date,'exception_set_digest',v_existing.exception_set_digest,
    'compiler_version',v_existing.compiler_version,'objective',v_existing.objective_json,'metrics',v_existing.metrics_json,
    'replay_digest',v_existing.replay_digest,'projection_envelope',v_existing.projection_envelope,
    'expected_revision',command.expected_revision,'actor_manager_id',p_manager_id,'actor_manager_name',actor->>'manager_name');
   v_request_digest:=public.static_weekly_digest_jsonb(v_request);
   v_projection_content_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
    'publication_id',v_existing.publication_id,'week_start',v_existing.week_start,
    'exception_set_digest',v_existing.exception_set_digest,'compiler_version',v_existing.compiler_version,
    'objective',v_existing.objective_json,'metrics',v_existing.metrics_json,'replay_digest',v_existing.replay_digest,
    'projection_envelope_identity',v_existing.projection_envelope->>'database_projection_identity',
    'attestation',v_existing.projection_envelope->'attestation'));
   v_projection_receipt:=public.static_weekly_response_json('materialize_projection',v_revision,
    v_projection_content_digest,v_request_digest,jsonb_build_object('projection_id',v_projection,
     'publication_id',v_existing.publication_id,'week_start',v_existing.week_start,
     'week_end',v_existing.week_end,'replay_digest',v_existing.replay_digest));
   insert into public.weekly_schedule_command_receipts(command_id,actor_manager_id,actor_manager_name_snapshot,
    command_type,idempotency_key,expected_revision,request_digest,request_canonical_json,response_json,response_digest,content_digest)
   values(v_command_id,p_manager_id,actor->>'manager_name','materialize_projection',v_payload->>'idempotencyKey',
    command.expected_revision,v_request_digest,v_request,v_projection_receipt,v_projection_receipt->>'output_digest',v_projection_content_digest);
  else
   v_projection_response:=public.static_weekly_v3_materialize_projection(
    (v_payload->>'publicationId')::uuid,v_projection_candidate.service_date,v_payload->>'exceptionSetDigest',
    v_payload->>'compilerVersion',v_payload->'objective',v_payload->'metrics',v_payload->>'replayDigest',
    v_payload->'envelope',command.expected_revision,p_manager_id,v_payload->>'idempotencyKey');
   v_projection:=(v_projection_response#>>'{data,projection_id}')::uuid;
  end if;
  select payload_json into strict v_lunch from public.static_weekly_staffing_staged_candidates
   where operation_id=command.operation_id and candidate_kind='lunch'
    and service_date=v_projection_candidate.service_date;
  perform public.static_weekly_v8_materialize_lunch_document(v_projection,v_lunch,p_manager_id);
  select * into strict v_existing_lunch from public.weekly_schedule_lunch_documents where projection_id=v_projection;
  v_projection_map:=v_projection_map||jsonb_build_object(v_projection_candidate.service_date::text,
   jsonb_build_object('projection_id',v_projection,'publication_id',(v_payload->>'publicationId')::uuid,
    'projection_identity',v_payload#>>'{envelope,database_projection_identity}',
    'lunch_document_identity',v_existing_lunch.document_identity,'reused',v_reused));
 end loop;

 if exists(
 with projection as (select service_date week_start,payload_json from public.static_weekly_staffing_staged_candidates
    where operation_id=command.operation_id and candidate_kind='projection'),
  lunch as (select payload_json from public.static_weekly_staffing_staged_candidates
    where operation_id=command.operation_id and candidate_kind='lunch'),
  expected as (
   select distinct assignment->>'service_date' service_date,assignment->>'owner_person_id' employee_id
   from projection cross join lateral jsonb_array_elements(payload_json#>'{envelope,assignments}') assignment
   where lower(assignment->>'status')='assigned' and assignment->>'service_date' between command.start_date::text and command.end_date::text
   union select responsibility->>'service_date',responsibility->>'normal_owner_person_id'
    from lunch cross join lateral jsonb_array_elements(coalesce(payload_json->'responsibilities','[]'::jsonb)) responsibility
    where responsibility->>'service_date' between command.start_date::text and command.end_date::text
     and responsibility->>'normal_owner_person_id' is not null
   union select responsibility->>'service_date',responsibility->>'coverer_person_id'
    from lunch cross join lateral jsonb_array_elements(coalesce(payload_json->'responsibilities','[]'::jsonb)) responsibility
    where responsibility->>'service_date' between command.start_date::text and command.end_date::text
     and responsibility->>'coverer_person_id' is not null
   union select item->>'serviceDate',item->>'employeeId' from jsonb_array_elements(v_prior_refresh) item
   union select (day::date)::text,command.employee_id::text from generate_series(command.start_date,command.end_date,interval '1 day') day
  ),actual as (select service_date::text,payload_json->>'employeeId' employee_id
   from public.static_weekly_staffing_staged_candidates where operation_id=command.operation_id and candidate_kind='schedule_refresh')
  (select * from expected except select * from actual) union all (select * from actual except select * from expected)
 ) then raise exception using errcode='23514',message='affected employee schedule refresh set is incomplete or excessive';end if;

 for v_refresh in select service_date,payload_json from public.static_weekly_staffing_staged_candidates
  where operation_id=command.operation_id and candidate_kind='schedule_refresh' order by service_date,candidate_key loop
  v_mapping:=v_projection_map->(v_refresh.payload_json->>'weekStart');
  if (select array_agg(key order by key) from jsonb_object_keys(v_refresh.payload_json) key) is distinct from
   array['employeeId','lunchDocumentIdentity','projectionIdentity','publicationId','weekStart']::text[]
   or v_mapping is null or v_refresh.payload_json->>'publicationId' is distinct from v_mapping->>'publication_id'
   or v_refresh.payload_json->>'projectionIdentity' is distinct from v_mapping->>'projection_identity'
   or v_refresh.payload_json->>'lunchDocumentIdentity' is distinct from v_mapping->>'lunch_document_identity'
   or v_refresh.service_date not between command.start_date and command.end_date then
   raise exception using errcode='23514',message='schedule refresh is not bound to the exact accepted projection and lunch';end if;
  insert into public.static_weekly_schedule_application_intents(operation_id,service_date,employee_id,
   device_id,credential_id,assignment_epoch,authority_revision,publication_id,projection_id,lunch_document_identity)
  select command.operation_id,v_refresh.service_date,(v_refresh.payload_json->>'employeeId')::uuid,
   d.id,c.credential_id,d.assignment_epoch,v_revision,(v_mapping->>'publication_id')::uuid,
   (v_mapping->>'projection_id')::uuid,v_mapping->>'lunch_document_identity'
  from public.devices d join public.device_auth_credentials c on c.device_id=d.id
   and c.confirmed_at is not null and c.revoked_at is null and c.expires_at>statement_timestamp()
  where d.active=true and d.assigned_employee_id=(v_refresh.payload_json->>'employeeId')::uuid;
  get diagnostics v_count=row_count;v_intent_count:=v_intent_count+v_count;
  if v_count=0 then v_missing_device:=v_missing_device||jsonb_build_array(jsonb_build_object(
   'service_date',v_refresh.service_date,'employee_id',v_refresh.payload_json->>'employeeId','status','NO_CURRENT_DEVICE'));end if;
 end loop;

 v_receipt:=jsonb_build_object('operation_id',command.operation_id,'event','ACCEPTED',
  'manager_id',p_manager_id,'original_preparer_manager_id',command.prepared_by_manager_id,
  'semantic_digest',command.semantic_digest,'preview_digest',command.preview_digest,
  'candidate_set_digest',command.candidate_set_digest,'authority_revision',v_revision,
  'projections',v_projection_map,'device_intent_count',v_intent_count,
  'missing_device_targets',v_missing_device,'recorded_at',statement_timestamp());
 v_receipt_digest:=public.static_weekly_digest_jsonb(v_receipt);
 perform set_config('app.static_weekly_staffing_write','on',true);
 update public.static_weekly_staffing_commands set state='ACCEPTED',confirmation_key=p_confirmation_key,
  confirmed_by_manager_id=p_manager_id,authority_command_id=command.operation_id,accepted_revision=v_revision,
  accepted_receipt=v_receipt,accepted_at=statement_timestamp() where operation_id=command.operation_id;
 insert into public.static_weekly_staffing_command_receipts(operation_id,event_kind,actor_manager_id,
  semantic_digest,receipt_json,receipt_digest) values(command.operation_id,'ACCEPTED',p_manager_id,
  command.semantic_digest,v_receipt,v_receipt_digest);
 return v_receipt||jsonb_build_object('replayed',false);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v11_staged_projection_digest_matches(p_operation_id uuid, p_content_digest text, p_manager_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare candidate record;signed_envelope jsonb;expected_digest text;matches integer:=0;
begin
 for candidate in select payload_json from public.static_weekly_staffing_staged_candidates
  where operation_id=p_operation_id and candidate_kind='projection' loop
  if candidate.payload_json->>'actorManagerId' is distinct from p_manager_id::text then continue;end if;
  signed_envelope:=jsonb_set(candidate.payload_json->'envelope','{attestation}',
   public.static_weekly_v3_issue_attestation('dated_projection',
    public.static_weekly_projection_attestation_payload(candidate.payload_json->'envelope')),true);
  expected_digest:=public.static_weekly_digest_jsonb(jsonb_build_object(
   'publication_id',(candidate.payload_json->>'publicationId')::uuid,
   'week_start',(candidate.payload_json->>'serviceDate')::date,
   'exception_set_digest',public.static_weekly_digest_jsonb(public.static_weekly_accepted_exception_set(
    (candidate.payload_json->>'publicationId')::uuid,(candidate.payload_json->>'serviceDate')::date)),
   'compiler_version',candidate.payload_json->>'compilerVersion','objective',candidate.payload_json->'objective',
   'metrics',candidate.payload_json->'metrics','replay_digest',candidate.payload_json->>'replayDigest',
   'projection_envelope_identity',signed_envelope->>'database_projection_identity',
   'attestation',signed_envelope->'attestation'));
  if expected_digest=p_content_digest then matches:=matches+1;end if;
 end loop;
 return matches=1;
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v3_create_draft(p_effective_start date, p_objective_version text, p_objective jsonb, p_input_provenance jsonb, p_document jsonb, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text, p_source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor jsonb; v_document jsonb; v_response jsonb; v_version uuid; v_source uuid;
begin
  perform public.static_weekly_v3_assert_control_plane(); perform public.static_weekly_capacity_source_assert_use(p_source_id,p_manager_id,p_idempotency_key,'draft');
 perform public.place_operational_assert_source_use(p_source_id,p_manager_id,p_idempotency_key,'draft');
  perform public.static_weekly_v14_assert_recurring_source_use(p_source_id,p_manager_id,p_effective_start,p_idempotency_key,'draft'); v_actor:=public.static_weekly_v3_manager_actor(p_manager_id); perform public.static_weekly_v3_assert_registered_source(p_source_id,p_document#>'{authority,compilerInput}');
  perform public.static_weekly_assert_compiler_authority(p_document->'authority',p_document->'receipt',p_effective_start,true);
  v_document:=jsonb_set(p_document,'{attestation}',public.static_weekly_v6_issue_document_attestation(p_document),true);
  v_response:=public.static_weekly_v2_create_draft(p_effective_start,p_objective_version,p_objective,p_input_provenance,v_document,p_expected_revision,p_manager_id,v_actor->>'manager_name',p_idempotency_key);
  v_version:=(v_response#>>'{data,version_id}')::uuid; perform set_config('app.static_weekly_source_bind','on',true); update public.weekly_schedule_versions set authority_source_id=p_source_id where version_id=v_version and authority_source_id is null;
  select authority_source_id into v_source from public.weekly_schedule_versions where version_id=v_version for share;
  if v_source is distinct from p_source_id then raise exception using errcode='23514',message='draft did not retain one immutable authority source identity'; end if;
  return v_response;
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v4_begin_day_changes(p_service_date date, p_week_start date, p_base_version_id uuid, p_publication_id uuid, p_operations jsonb, p_expected_revision bigint, p_manager_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_actor jsonb; v_child public.weekly_schedule_command_receipts%rowtype;
  v_projection public.weekly_schedule_command_receipts%rowtype; v_projection_row public.weekly_schedule_compiled_projections%rowtype;
  v_operation jsonb; v_expected jsonb; v_mutations jsonb:='[]'::jsonb; v_snapshot jsonb;
  v_child_count integer:=0; v_requested_count integer; v_index integer; v_key text; v_expected_command text;
begin
  perform public.static_weekly_v3_assert_control_plane();
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  if p_service_date is null or p_week_start is null or extract(isodow from p_week_start)<>1
     or p_service_date<p_week_start or p_service_date>p_week_start+6
     or p_base_version_id is null or p_publication_id is null or p_expected_revision is null or p_expected_revision<0
     or nullif(btrim(coalesce(p_idempotency_key,'')),'') is null or length(btrim(p_idempotency_key))>200
     or p_operations is null or jsonb_typeof(p_operations)<>'array' or jsonb_array_length(p_operations) not between 1 and 25 then
    raise exception using errcode='22023',message='complete bounded day-change batch identity is required';
  end if;
  p_idempotency_key:=btrim(p_idempotency_key);
  v_requested_count:=jsonb_array_length(p_operations);

  -- The same transaction lock used by every child and projection writer makes
  -- recognition, continuation, and independent-session races one serial order.
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));

  select * into v_projection from public.weekly_schedule_command_receipts r
  where r.actor_manager_id=p_manager_id
    and r.idempotency_key=public.static_weekly_v4_day_change_projection_key(p_idempotency_key);

  -- Index 25 is inspected as a sentinel beyond the maximum accepted batch so
  -- a previously longer chain can never be mistaken for a 25-item replay.
  for v_index in 0..25 loop
    v_key:=public.static_weekly_v4_day_change_child_key(p_idempotency_key,v_index);
    select * into v_child from public.weekly_schedule_command_receipts r
    where r.actor_manager_id=p_manager_id and r.idempotency_key=v_key;
    if found then
      if v_index<>v_child_count then
        raise exception using errcode='23505',message='idempotency key is bound to an incomplete day-change receipt chain';
      end if;
      v_child_count:=v_child_count+1;
    end if;
  end loop;

  if v_child_count=0 and v_projection.command_id is null then
    return jsonb_build_object('replayed',false);
  end if;
  if v_child_count<>v_requested_count or v_projection.command_id is null then
    raise exception using errcode='23505',message='idempotency key is bound to a different complete day-change batch';
  end if;

  for v_index in 0..v_requested_count-1 loop
    v_operation:=p_operations->v_index;
    select * into strict v_child from public.weekly_schedule_command_receipts r
    where r.actor_manager_id=p_manager_id
      and r.idempotency_key=public.static_weekly_v4_day_change_child_key(p_idempotency_key,v_index);
    if jsonb_typeof(v_operation)<>'object' or v_operation->>'operation' not in ('exception','cover_all') then
      raise exception using errcode='22023',message='day-change operations must use the normalized control-plane contract';
    end if;
    v_expected_command:=case when v_operation->>'operation'='exception' and v_operation->>'exceptionType'='reverse' then 'reverse_exception' else 'apply_exception' end;
    if v_operation->>'operation'='exception' then
      v_expected:=jsonb_build_object(
        'operation','apply_exception','exception_type',v_operation->>'exceptionType','service_date',p_service_date,
        'starts_at',case when v_operation->>'startsAt' is null then null else (v_operation->>'startsAt')::time end,
        'ends_at',case when v_operation->>'endsAt' is null then null else (v_operation->>'endsAt')::time end,
        'base_version_id',p_base_version_id,'publication_id',p_publication_id,'reason',v_operation->>'reason',
        'payload',v_operation->'payload','expected_revision',p_expected_revision+v_index,
        'actor_manager_id',p_manager_id,
        'reverses_exception_id',case when v_operation->>'reversesExceptionId' is null then null else (v_operation->>'reversesExceptionId')::uuid end
      );
      if (v_child.request_canonical_json-'actor_manager_name') is distinct from v_expected then
        raise exception using errcode='23505',message='idempotency key was already used for different ordered day-change inputs';
      end if;
    else
      v_expected:=jsonb_build_object(
        'operation','apply_exception','exception_type','cover_all','service_date',p_service_date,
        'starts_at',null,'ends_at',null,'base_version_id',p_base_version_id,'publication_id',p_publication_id,
        'reason',v_operation->>'reason','expected_revision',p_expected_revision+v_index,
        'actor_manager_id',p_manager_id,'reverses_exception_id',null
      );
      if (v_child.request_canonical_json-'actor_manager_name'-'payload') is distinct from v_expected
         or jsonb_typeof(v_child.request_canonical_json->'payload')<>'object'
         or (select count(*) from jsonb_object_keys(v_child.request_canonical_json->'payload'))<>1
         or jsonb_typeof(v_child.request_canonical_json#>'{payload,availability}')<>'object'
         or v_child.request_canonical_json#>>'{payload,availability,slotId}' is distinct from v_operation->>'slotId'
         or v_child.request_canonical_json#>'{payload,availability,breakChoice}' is distinct from v_operation->'breakChoice'
         or (v_operation->'shift'<>'null'::jsonb and v_child.request_canonical_json#>'{payload,availability,shift}' is distinct from v_operation->'shift') then
        raise exception using errcode='23505',message='idempotency key was already used for different ordered day-change inputs';
      end if;
    end if;
    if v_child.command_type<>v_expected_command or v_child.expected_revision<>p_expected_revision+v_index
       or v_child.request_digest<>public.static_weekly_digest_jsonb(v_child.request_canonical_json)
       or v_child.response_json->>'request_digest'<>v_child.request_digest
       or v_child.response_json->>'content_digest'<>v_child.content_digest
       or v_child.response_json->>'operation'<>v_expected_command
       or (v_child.response_json->>'revision')::bigint<>p_expected_revision+v_index+1
       or v_child.response_json#>>'{data,sequence}'<>(p_expected_revision+v_index+1)::text
       or v_child.response_json#>>'{data,service_date}'<>p_service_date::text
       or v_child.response_json->>'output_digest'<>public.static_weekly_digest_jsonb(v_child.response_json-'output_digest')
       or v_child.response_digest<>v_child.response_json->>'output_digest'
       or not exists(
         select 1 from public.weekly_schedule_authority_revisions a
         where a.command_id=v_child.command_id and a.authority_revision=p_expected_revision+v_index+1
           and a.operation=v_expected_command and a.actor_manager_id=p_manager_id and a.content_digest=v_child.content_digest
       ) then
      raise exception using errcode='23505',message='idempotency key is bound to an invalid day-change receipt chain';
    end if;
    v_mutations:=v_mutations||jsonb_build_array(v_child.response_json->'data');
  end loop;

  if v_projection.command_type<>'materialize_projection'
     or v_projection.expected_revision<>p_expected_revision+v_requested_count
     or v_projection.request_canonical_json->>'operation'<>'materialize_projection'
     or v_projection.request_canonical_json->>'publication_id'<>p_publication_id::text
     or v_projection.request_canonical_json->>'service_date'<>p_week_start::text
     or v_projection.request_canonical_json->>'actor_manager_id'<>p_manager_id::text
     or (v_projection.request_canonical_json->>'expected_revision')::bigint<>p_expected_revision+v_requested_count
     or v_projection.request_digest<>public.static_weekly_digest_jsonb(v_projection.request_canonical_json)
     or v_projection.response_json->>'request_digest'<>v_projection.request_digest
     or v_projection.response_json->>'content_digest'<>v_projection.content_digest
     or v_projection.response_json->>'operation'<>'materialize_projection'
     or (v_projection.response_json->>'revision')::bigint<>p_expected_revision+v_requested_count+1
     or v_projection.response_json->>'output_digest'<>public.static_weekly_digest_jsonb(v_projection.response_json-'output_digest')
     or v_projection.response_digest<>v_projection.response_json->>'output_digest'
     or not exists(
       select 1 from public.weekly_schedule_authority_revisions a
       where a.command_id=v_projection.command_id and a.authority_revision=p_expected_revision+v_requested_count+1
         and a.operation='materialize_projection' and a.actor_manager_id=p_manager_id and a.content_digest=v_projection.content_digest
     ) then
    raise exception using errcode='23505',message='idempotency key is bound to an invalid final projection receipt';
  end if;

  begin
    select * into strict v_projection_row from public.weekly_schedule_compiled_projections p
    where p.projection_id=(v_projection.response_json#>>'{data,projection_id}')::uuid;
  exception when no_data_found or too_many_rows then
    raise exception using errcode='23505',message='idempotency key is bound to a missing immutable projection';
  end;
  if v_projection_row.publication_id<>p_publication_id or v_projection_row.version_id<>p_base_version_id
     or v_projection_row.week_start<>p_week_start or v_projection_row.compiled_by_manager_id<>p_manager_id
     or v_projection_row.replay_digest<>v_projection.response_json#>>'{data,replay_digest}' then
    raise exception using errcode='23505',message='idempotency key is bound to a different immutable projection';
  end if;
  v_snapshot:=public.static_weekly_v4_projection_snapshot(v_projection_row.projection_id);
  if v_snapshot is null then
    raise exception using errcode='23505',message='idempotency key is bound to a missing immutable projection';
  end if;
  return jsonb_build_object(
    'replayed',true,
    'response',v_projection.response_json||jsonb_build_object(
      'operation','apply_day_changes',
      'data',(v_projection.response_json->'data')||jsonb_build_object('current_projection',v_snapshot,'mutations',v_mutations)
    )
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v6_initialize_registered_roster(p_source_id uuid, p_manager_id uuid, p_configured_by text DEFAULT 'production-manager'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_source jsonb;
  v_slots jsonb;
  v_slot jsonb;
  v_incumbencies jsonb;
  v_incumbent jsonb;
  v_actor jsonb;
  v_slot_id uuid;
  v_person_id uuid;
  v_effective_start date;
  v_effective_end date;
  v_slot_code text;
  v_expected_slots integer:=0;
  v_expected_incumbencies integer:=0;
  v_existing_slots integer:=0;
  v_existing_incumbencies integer:=0;
  v_mismatch boolean:=false;
begin
  perform public.static_weekly_v3_assert_release_operator();
  perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-initial-roster',0));
  v_actor:=public.static_weekly_v3_manager_actor(p_manager_id);
  if p_source_id is null or nullif(btrim(coalesce(p_configured_by,'')),'') is null or length(p_configured_by)>200 then
    raise exception using errcode='22023',message='registered roster bootstrap requires a source, named manager, and bounded release owner';
  end if;

  select canonical_source into v_source
  from public.static_weekly_authority_source_documents
  where source_id=p_source_id and active=true and retired_at is null
  for share;
  if not found then
    raise exception using errcode='23514',message='registered roster bootstrap requires one active immutable authority source';
  end if;
  v_slots:=v_source->'slots';
  if jsonb_typeof(v_slots) is distinct from 'array' or jsonb_array_length(v_slots)=0 or jsonb_array_length(v_slots)>256 then
    raise exception using errcode='23514',message='registered roster bootstrap source must contain a bounded nonempty stable-slot set';
  end if;

  -- Validate the complete registered source before deciding between initial
  -- insertion and the exact idempotent replay path.
  for v_slot in select value from jsonb_array_elements(v_slots) loop
    perform public.static_weekly_v3_assert_uuid(v_slot->'id','registered roster slot id');
    perform public.static_weekly_v3_assert_text(v_slot->'label','registered roster slot label',200);
    v_incumbencies:=v_slot->'incumbencies';
    if v_slot->>'kind'='CONTRACTOR_CAPACITY' then perform public.static_weekly_capacity_assert_shape(v_slot); end if;
    if jsonb_typeof(v_incumbencies) is distinct from 'array'
      or (jsonb_array_length(v_incumbencies)=0 and v_slot->>'kind' is distinct from 'CONTRACTOR_CAPACITY')
      or jsonb_array_length(v_incumbencies)>64 then
      raise exception using errcode='23514',message='each registered roster slot requires bounded immutable incumbency history';
    end if;
    v_expected_slots:=v_expected_slots+1;
    for v_incumbent in select value from jsonb_array_elements(v_incumbencies) loop
      perform public.static_weekly_v3_assert_uuid(v_incumbent->'personId','registered roster incumbent person id');
      perform public.static_weekly_v3_assert_text(v_incumbent->'displayName','registered roster incumbent name',200);
      perform public.static_weekly_v3_assert_text(v_incumbent->'effectiveStart','registered roster effective start',10);
      if (v_incumbent->>'effectiveStart') !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception using errcode='23514',message='registered roster effective start must be YYYY-MM-DD';
      end if;
      v_effective_start:=(v_incumbent->>'effectiveStart')::date;
      v_effective_end:=null;
      if nullif(v_incumbent->>'effectiveEnd','') is not null then
        if (v_incumbent->>'effectiveEnd') !~ '^\d{4}-\d{2}-\d{2}$' then
          raise exception using errcode='23514',message='registered roster effective end must be YYYY-MM-DD or null';
        end if;
        v_effective_end:=(v_incumbent->>'effectiveEnd')::date;
        if v_effective_end<=v_effective_start then
          raise exception using errcode='23514',message='registered roster incumbency end must follow its start';
        end if;
      end if;
      v_expected_incumbencies:=v_expected_incumbencies+1;
    end loop;
  end loop;
  if v_expected_slots<>(select count(distinct value->>'id') from jsonb_array_elements(v_slots)) then
    raise exception using errcode='23514',message='registered roster source contains duplicate stable-slot identities';
  end if;

  select count(*) into v_existing_slots from public.weekly_roster_slots;
  select count(*) into v_existing_incumbencies from public.weekly_roster_slot_incumbencies;
  if v_existing_slots<>0 or v_existing_incumbencies<>0 then
    if v_existing_slots<>v_expected_slots or v_existing_incumbencies<>v_expected_incumbencies then
      raise exception using errcode='23514',message='registered roster bootstrap refuses partial or unrelated existing roster state';
    end if;
    for v_slot in select value from jsonb_array_elements(v_slots) loop
      v_slot_id:=(v_slot->>'id')::uuid;
      v_slot_code:='STATIC_'||upper(replace(v_slot_id::text,'-',''));
      if not exists(
        select 1 from public.weekly_roster_slots s
        where s.slot_id=v_slot_id and s.slot_code=v_slot_code and s.slot_label=v_slot->>'label'
      ) then v_mismatch:=true; exit; end if;
      if v_slot->>'kind'='CONTRACTOR_CAPACITY' and not public.static_weekly_capacity_registered(v_slot) then v_mismatch:=true; exit; end if;
      for v_incumbent in select value from jsonb_array_elements(v_slot->'incumbencies') loop
        v_person_id:=(v_incumbent->>'personId')::uuid;
        v_effective_start:=(v_incumbent->>'effectiveStart')::date;
        v_effective_end:=nullif(v_incumbent->>'effectiveEnd','')::date;
        if not exists(
          select 1 from public.weekly_roster_slot_incumbencies i
          where i.slot_id=v_slot_id and i.person_id=v_person_id
            and i.person_name_snapshot=v_incumbent->>'displayName'
            and i.effective_start=v_effective_start
            and i.effective_end is not distinct from v_effective_end
        ) then v_mismatch:=true; exit; end if;
      end loop;
      exit when v_mismatch;
    end loop;
    if v_mismatch then
      raise exception using errcode='23514',message='registered roster bootstrap refuses roster state that differs from the immutable source';
    end if;
    return jsonb_build_object(
      'source_id',p_source_id::text,
      'source_digest',public.static_weekly_digest_jsonb(v_source),
      'slot_count',v_expected_slots,
      'incumbency_count',v_expected_incumbencies,
      'already_initialized',true
    );
  end if;

  for v_slot in select value from jsonb_array_elements(v_slots) loop
    v_slot_id:=(v_slot->>'id')::uuid;
    v_slot_code:='STATIC_'||upper(replace(v_slot_id::text,'-',''));
    insert into public.weekly_roster_slots(
      slot_id,slot_code,slot_label,created_by_manager_id,created_by_manager_name_snapshot,content_digest
    ) values(
      v_slot_id,v_slot_code,v_slot->>'label',p_manager_id,v_actor->>'manager_name',
      public.static_weekly_digest_jsonb(jsonb_build_object(
        'source_id',p_source_id::text,'slot_id',v_slot_id::text,'slot_code',v_slot_code,'slot_label',v_slot->>'label'
      ))
    );
    if v_slot->>'kind'='CONTRACTOR_CAPACITY' then
      insert into public.static_weekly_contractor_capacity_registrations(
       capacity_slot_id,capacity_code,source_id,source_digest,slot_snapshot,slot_digest,registered_by_manager_id,manager_name_snapshot)
      values(v_slot_id,v_slot->>'label',p_source_id,public.static_weekly_digest_jsonb(v_source),v_slot,
       public.static_weekly_digest_jsonb(v_slot),p_manager_id,v_actor->>'manager_name');
    end if;
    for v_incumbent in select value from jsonb_array_elements(v_slot->'incumbencies') loop
      v_person_id:=(v_incumbent->>'personId')::uuid;
      v_effective_start:=(v_incumbent->>'effectiveStart')::date;
      v_effective_end:=nullif(v_incumbent->>'effectiveEnd','')::date;
      insert into public.weekly_roster_slot_incumbencies(
        slot_id,person_id,person_name_snapshot,effective_start,effective_end,
        created_by_manager_id,created_by_manager_name_snapshot,content_digest
      ) values(
        v_slot_id,v_person_id,v_incumbent->>'displayName',v_effective_start,v_effective_end,
        p_manager_id,v_actor->>'manager_name',
        public.static_weekly_digest_jsonb(jsonb_build_object(
          'source_id',p_source_id::text,'slot_id',v_slot_id::text,'person_id',v_person_id::text,
          'person_name_snapshot',v_incumbent->>'displayName','effective_start',v_effective_start::text,
          'effective_end',case when v_effective_end is null then null else to_jsonb(v_effective_end::text) end
        ))
      );
    end loop;
  end loop;

  return jsonb_build_object(
    'source_id',p_source_id::text,
    'source_digest',public.static_weekly_digest_jsonb(v_source),
    'slot_count',v_expected_slots,
    'incumbency_count',v_expected_incumbencies,
    'already_initialized',false,
    'configured_by',left(p_configured_by,200),
    'manager_id',p_manager_id::text,
    'manager_name',v_actor->>'manager_name'
  );
end
$function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_assert_lunch_document(p_projection_id uuid, p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 projection public.weekly_schedule_compiled_projections%rowtype;
 loan jsonb;responsibility jsonb;segment jsonb;intent jsonb;availability jsonb;helper jsonb;
 base_work jsonb;expected jsonb;actual jsonb;helper_id text;identity_key text;
 start_time time;end_time time;
 projection_availability jsonb;projection_assignments jsonb;projection_work jsonb;
begin
 perform public.static_weekly_assert_exact_object(p_document,
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],
  array['schema','persistence_authority','verification_status','week_start','base_authority_digest','base_replay_digest','source_input_digest','candidate_digest','loans','responsibilities','notification_intents','semantic_snapshot','document_identity'],'lunch document');
 select * into projection from public.weekly_schedule_compiled_projections where projection_id=p_projection_id;
 if not found then raise exception 'lunch projection is missing'; end if;

 projection_availability:=projection.projection_envelope#>'{authority,projectionAvailability}';
 projection_assignments:=projection.projection_envelope->'assignments';
 projection_work:=projection.projection_envelope#>'{authority,overlayCompilerInput,version,assignments}';

 if p_document->>'schema' is distinct from 'memphis-zoo.static-weekly-lunch-authority-document.v1'
  or p_document->>'persistence_authority' is distinct from 'NOT_PERSISTED'
  or p_document->>'verification_status' is distinct from 'VERIFIED'
  or p_document->>'week_start' is distinct from projection.week_start::text
  or p_document->>'base_authority_digest' is distinct from projection.authority_digest
  or p_document->>'base_replay_digest' is distinct from projection.replay_digest
  or p_document->>'source_input_digest' is distinct from projection.projection_envelope#>>'{authority,inputDigest}'
  or coalesce(p_document->>'candidate_digest','') !~ '^[0-9a-f]{64}$'
  or p_document->>'document_identity' is distinct from public.static_weekly_digest_jsonb(p_document-'document_identity') then
  raise exception 'lunch document is not bound to the exact verified projection';
 end if;
 foreach identity_key in array array['loans','responsibilities','notification_intents'] loop
  if jsonb_typeof(p_document->identity_key) is distinct from 'array'
   or jsonb_array_length(p_document->identity_key)>4096 then raise exception 'lunch document array invalid'; end if;
 end loop;
 expected:=jsonb_build_object('schema','memphis-zoo.static-weekly-lunch-semantic-snapshot.v1',
  'loans_digest',public.static_weekly_digest_jsonb(p_document->'loans'),
  'responsibilities_digest',public.static_weekly_digest_jsonb(p_document->'responsibilities'),
  'notification_intents_digest',public.static_weekly_digest_jsonb(p_document->'notification_intents'));
 if p_document->'semantic_snapshot' is distinct from expected then raise exception 'lunch semantic snapshot mismatch'; end if;
 if (select count(*)<>count(distinct value->>'loan_id') from jsonb_array_elements(p_document->'loans'))
 or (select count(*)<>count(distinct value->>'responsibility_id') from jsonb_array_elements(p_document->'responsibilities'))
 or (select count(*)<>count(distinct value->>'notification_key') from jsonb_array_elements(p_document->'notification_intents')) then
  raise exception 'duplicate or missing lunch record identity'; end if;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'serviceDate',value->>'slotId') order by value->>'serviceDate',value->>'slotId'),'[]')
 into expected from jsonb_array_elements(projection_availability)
 where value->>'status'='working' and (nullif(value->>'incumbentPersonId','') is not null or value->>'ownerKind'='CONTRACTOR_CAPACITY')
  and (value->>'ownerKind'='CONTRACTOR_CAPACITY' and value->>'breakChoice'='NONE' and value->'lunch'='null'::jsonb) is not true;
 select coalesce(jsonb_agg(jsonb_build_array(value->>'service_date',value->>'normal_owner_slot_id') order by value->>'service_date',value->>'normal_owner_slot_id'),'[]')
 into actual from jsonb_array_elements(p_document->'loans');
 if actual is distinct from expected then raise exception 'lunch coverage omits or duplicates a working owner'; end if;
 for loan in select value from jsonb_array_elements(p_document->'loans') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,loan,'normal_owner');
  perform public.static_weekly_assert_exact_object(loan,
   case when loan ? 'normal_owner_capacity_id' then array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_capacity_id','coverage_start','coverage_end','status','helper_slot_ids']
    else array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end','status','helper_slot_ids'] end,
   array['loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverage_start','coverage_end','status','reason','helper_slot_ids','fallback','total_distance_minutes'],'lunch loan');
  if not (loan ?& array['reason','fallback','total_distance_minutes']) then raise exception 'lunch explanatory fields are missing'; end if;
  if coalesce(loan->>'loan_id','') !~ '^[0-9a-f]{64}$' then raise exception 'invalid lunch loan identity'; end if;
  select value into availability from jsonb_array_elements(projection_availability)
   where value->>'slotId'=loan->>'normal_owner_slot_id' and value->>'serviceDate'=loan->>'service_date';
  if not found or availability->>'incumbentPersonId' is distinct from loan->>'normal_owner_person_id'
   or loan->'day_of_week' is distinct from availability->'dayOfWeek'
   or loan->>'coverage_start' is distinct from availability#>>'{lunch,start}'
   or loan->>'coverage_end' is distinct from availability#>>'{lunch,end}' then raise exception 'lunch owner or scheduled hour mismatch'; end if;
  perform public.static_weekly_v3_assert_window(jsonb_build_object('start',loan->'coverage_start','end',loan->'coverage_end'),'lunch');
  start_time:=(loan->>'coverage_start')::time;end_time:=(loan->>'coverage_end')::time;
  if end_time-start_time<>interval '1 hour' then raise exception 'lunch must last exactly one hour'; end if;
  perform public.static_weekly_v3_assert_string_array(loan->'helper_slot_ids','lunch helpers');
  if ((loan->>'status'='NO_AREAS' and jsonb_array_length(loan->'helper_slot_ids')=0 and loan->'fallback'='null'::jsonb)
    or (loan->>'status'='PLANNED' and ((jsonb_array_length(loan->'helper_slot_ids')=2 and loan->'fallback'='null'::jsonb)
      or (jsonb_array_length(loan->'helper_slot_ids')=1 and loan->>'fallback'='only_one_eligible_custodian')))) is not true then
   raise exception 'lunch helper cardinality or fallback invalid'; end if;
  for helper_id in select jsonb_array_elements_text(loan->'helper_slot_ids') loop
   select value into helper from jsonb_array_elements(projection_availability)
    where value->>'slotId'=helper_id and value->>'serviceDate'=loan->>'service_date';
   if not found or helper->>'status' is distinct from 'working' or helper_id=loan->>'normal_owner_slot_id'
    or (nullif(helper->>'incumbentPersonId','') is null and helper->>'ownerKind' is distinct from 'CONTRACTOR_CAPACITY')
    or ((helper#>>'{lunch,start}' is null or helper#>>'{lunch,end}' is null)
      and (helper->>'ownerKind'='CONTRACTOR_CAPACITY' and helper->>'breakChoice'='NONE' and helper->'lunch'='null'::jsonb) is not true) or (helper#>>'{shift,start}')::time>start_time
    or (helper#>>'{shift,end}')::time<end_time
    or ((helper#>>'{lunch,start}')::time<end_time and start_time<(helper#>>'{lunch,end}')::time) then
    raise exception 'lunch helper is not available for the full scheduled hour'; end if;
   if not exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r
     where r->>'loan_id'=loan->>'loan_id' and r->>'coverer_slot_id'=helper_id) then
    raise exception 'lunch helper has no assigned responsibility'; end if;
  end loop;
 end loop;
 for responsibility in select value from jsonb_array_elements(p_document->'responsibilities') loop
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'normal_owner');
  perform public.static_weekly_capacity_assert_lunch_party(p_projection_id,responsibility,'coverer');
  perform public.static_weekly_assert_exact_object(responsibility,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','coverer_slot_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments']
    ||case when responsibility ? 'normal_owner_capacity_id' then array['normal_owner_capacity_id'] else array['normal_owner_person_id'] end
    ||case when responsibility ? 'coverer_capacity_id' then array['coverer_capacity_id'] else array['coverer_person_id'] end,
   array['responsibility_id','loan_id','service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','normal_owner_capacity_id','coverer_slot_id','coverer_person_id','coverer_capacity_id','coverage_purpose','coverage_start','coverage_end','check_deadline_policy','creates_deep_clean','proximity_evidence','segments'],'lunch responsibility');
  select value into loan from jsonb_array_elements(p_document->'loans') where value->>'loan_id'=responsibility->>'loan_id';
  if not found or loan->>'status'<>'PLANNED' then raise exception 'lunch responsibility has no planned loan'; end if;
  foreach identity_key in array array['service_date','day_of_week','normal_owner_slot_id','normal_owner_person_id','coverage_start','coverage_end'] loop
   if responsibility->identity_key is distinct from loan->identity_key then raise exception 'lunch responsibility scope mismatch'; end if;
  end loop;
  select value into helper from jsonb_array_elements(projection_availability)
   where value->>'slotId'=responsibility->>'coverer_slot_id' and value->>'serviceDate'=responsibility->>'service_date';
  if not found or helper->>'incumbentPersonId' is distinct from responsibility->>'coverer_person_id'
   or not (loan->'helper_slot_ids' ? (responsibility->>'coverer_slot_id'))
   or coalesce(responsibility->>'responsibility_id','') !~ '^[0-9a-f]{64}$'
   or responsibility->>'coverage_purpose' is distinct from 'lunch_coverage'
   or responsibility->>'check_deadline_policy' is distinct from 'inherit_existing_90_minute_deadline'
   or responsibility->'creates_deep_clean' is distinct from 'false'::jsonb
   or jsonb_typeof(responsibility->'segments') is distinct from 'array'
   or jsonb_array_length(responsibility->'segments')=0 then raise exception 'lunch responsibility policy or recipient mismatch'; end if;
  for segment in select value from jsonb_array_elements(responsibility->'segments') loop
   perform public.static_weekly_assert_exact_object(segment,
    array['planWorkId','workId','serviceMode','window','includedLocations'],array['planWorkId','workId','serviceMode','window','includedLocations'],'lunch segment');
   select value into base_work from jsonb_array_elements(projection_assignments)
    where value->>'plan_work_id'=segment->>'planWorkId' and value->>'service_date'=responsibility->>'service_date';
   if not found or base_work->>'status' is distinct from 'assigned'
    or base_work->>'owner_slot_id' is distinct from responsibility->>'normal_owner_slot_id'
    or base_work->>'owner_person_id' is distinct from responsibility->>'normal_owner_person_id'
    or base_work->>'work_id' is distinct from segment->>'workId'
    or base_work#>'{work_snapshot,includedLocations}' is distinct from segment->'includedLocations'
    or base_work#>>'{work_snapshot,serviceMode}' is distinct from segment->>'serviceMode'
    or segment->>'serviceMode'='reminder_only' then raise exception 'borrowed area differs from original assignment'; end if;
   if not ((helper->'qualifications') @> (base_work#>'{work_snapshot,requiredQualifications}'))
    or (base_work#>'{work_snapshot,restrictedSlotIds}') ? (responsibility->>'coverer_slot_id')
    or exists(select 1 from jsonb_array_elements(segment->'includedLocations') location
      where helper->'restrictions' ? (location->>'locationId')) then
    raise exception 'lunch helper is restricted or unqualified for a borrowed area'; end if;
   perform public.static_weekly_v3_assert_window(segment->'window','borrowed area');
   if (segment#>>'{window,start}')::time<>greatest((base_work#>>'{work_snapshot,window,start}')::time,(loan->>'coverage_start')::time)
    or (segment#>>'{window,end}')::time<>least((base_work#>>'{work_snapshot,window,end}')::time,(loan->>'coverage_end')::time) then
    raise exception 'borrowed-area window must be the exact normal-duty and lunch intersection'; end if;
  end loop;
 end loop;
 -- Account for every normal flexible duty that intersects each scheduled lunch.
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',a->>'plan_work_id')
  order by l->>'loan_id',a->>'plan_work_id'),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l
 join jsonb_array_elements(projection_assignments) a
  on a->>'service_date'=l->>'service_date' and a->>'owner_slot_id'=l->>'normal_owner_slot_id'
 join jsonb_array_elements(projection_work) w
  on w->>'workId'=a->>'work_id' and w->>'dayOfWeek'=a->>'day_of_week'
 where a->>'status'='assigned' and w->>'schedulingMode'='flexible_coverage_ownership'
  and w->>'serviceMode'<>'reminder_only'
  and (a#>>'{work_snapshot,window,start}')::time<(l->>'coverage_end')::time
  and (l->>'coverage_start')::time<(a#>>'{work_snapshot,window,end}')::time;
 select coalesce(jsonb_agg(jsonb_build_array(r->>'loan_id',s->>'planWorkId')
  order by r->>'loan_id',s->>'planWorkId'),'[]') into actual
 from jsonb_array_elements(p_document->'responsibilities') r cross join lateral jsonb_array_elements(r->'segments') s;
 if actual is distinct from expected then raise exception 'lunch responsibility must cover every eligible original area exactly once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s group by r->>'loan_id',s->>'planWorkId' having count(*)>1) then
  raise exception 'borrowed work assigned more than once'; end if;
 if exists(select 1 from jsonb_array_elements(p_document->'responsibilities') r,
  jsonb_array_elements(r->'segments') s,jsonb_array_elements(s->'includedLocations') location
  group by r->>'loan_id',location->>'locationId' having count(distinct r->>'coverer_slot_id')>1) then
  raise exception 'paired or grouped locations split between lunch helpers'; end if;
 for intent in select value from jsonb_array_elements(p_document->'notification_intents') loop
  perform public.static_weekly_assert_exact_object(intent,
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],
   array['notification_key','loan_id','service_date','event','scheduled_time','coverer_slot_id','delivery_state'],'lunch notification intent');
  if coalesce(intent->>'notification_key','') !~ '^[0-9a-f]{64}$'
   or intent->>'delivery_state' is distinct from 'NOT_ENQUEUED' then raise exception 'invalid lunch notification intent'; end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_array(l->>'loan_id',l->>'service_date',h,e,
  case e when 'start' then l->>'coverage_start' else l->>'coverage_end' end) order by l->>'loan_id',h,e),'[]') into expected
 from jsonb_array_elements(p_document->'loans') l cross join lateral jsonb_array_elements_text(l->'helper_slot_ids') h
 cross join unnest(array['start','end']) e
 where exists(select 1 from jsonb_array_elements(projection_availability) a
  where a->>'slotId'=h and a->>'serviceDate'=l->>'service_date' and nullif(a->>'incumbentPersonId','') is not null);
 select coalesce(jsonb_agg(jsonb_build_array(n->>'loan_id',n->>'service_date',n->>'coverer_slot_id',n->>'event',n->>'scheduled_time')
  order by n->>'loan_id',n->>'coverer_slot_id',n->>'event'),'[]') into actual
 from jsonb_array_elements(p_document->'notification_intents') n;
 if actual is distinct from expected then raise exception 'lunch start/end intents must exactly cover every helper'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_materialize_lunch_document(p_projection_id uuid, p_document jsonb, p_manager_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare projection public.weekly_schedule_compiled_projections%rowtype;
 existing public.weekly_schedule_lunch_documents%rowtype;current_authority record;inserted integer;
begin
 perform public.static_weekly_v3_assert_control_plane();
 perform public.static_weekly_v3_manager_actor(p_manager_id);
 perform public.custodial_begin_application_mutation();
 perform pg_advisory_xact_lock(hashtextextended('memphis-static-weekly-authority',0));
 select * into projection from public.weekly_schedule_compiled_projections where projection_id=p_projection_id;
 if not found then raise exception 'lunch projection does not exist'; end if;
 select * into current_authority from public.static_weekly_v6_schedule_authority_state(projection.week_start);
 if current_authority.projection_status is distinct from 'current'
  or current_authority.projection_id is distinct from p_projection_id then raise exception 'lunch projection is not current'; end if;
 perform public.static_weekly_v8_assert_lunch_document(p_projection_id,p_document);
 insert into public.weekly_schedule_lunch_documents(projection_id,document_identity,document_json,accepted_by_manager_id)
 values(p_projection_id,p_document->>'document_identity',p_document,p_manager_id) on conflict(projection_id) do nothing;
 get diagnostics inserted=row_count;
 select * into strict existing from public.weekly_schedule_lunch_documents where projection_id=p_projection_id;
 if existing.document_json is distinct from p_document then raise exception 'immutable lunch publication conflicts with existing authority'; end if;
 return jsonb_build_object('ok',true,'persistence_status','PERSISTED','projection_id',p_projection_id,
  'document_identity',existing.document_identity,'replayed',inserted=0);
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_v8_read_lunch_document(p_service_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare current_authority record;stored public.weekly_schedule_lunch_documents%rowtype;
begin
 select * into current_authority from public.static_weekly_v6_schedule_authority_state(p_service_date);
 if current_authority.projection_status is distinct from 'current' then
  return jsonb_build_object('persistence_status','UNAVAILABLE','projection_status',current_authority.projection_status); end if;
 select * into stored from public.weekly_schedule_lunch_documents where projection_id=current_authority.projection_id;
 if not found then return jsonb_build_object('persistence_status','MISSING','projection_id',current_authority.projection_id); end if;
 if stored.document_identity is distinct from stored.document_json->>'document_identity' then
  raise exception 'saved lunch document identity mismatch'; end if;
 perform public.static_weekly_v8_assert_lunch_document(stored.projection_id,stored.document_json);
 return jsonb_build_object('persistence_status','PERSISTED','projection_id',stored.projection_id,
  'document_identity',stored.document_identity,'service_date',p_service_date,
  'loans',coalesce((select jsonb_agg(value) from jsonb_array_elements(stored.document_json->'loans') where value->>'service_date'=p_service_date::text),'[]'::jsonb),
  'responsibilities',coalesce((select jsonb_agg(value) from jsonb_array_elements(stored.document_json->'responsibilities') where value->>'service_date'=p_service_date::text),'[]'::jsonb));
end $function$

CREATE OR REPLACE FUNCTION public.static_weekly_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='weekly versions are immutable'; end if;
  if tg_op='INSERT' then
    if new.lifecycle_state='published' and current_setting('app.static_weekly_publish_write',true) is distinct from 'on' then raise exception using errcode='23514',message='published versions require v2 publication'; end if;
    return new;
  end if;
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_publish_write',true)='on' and new.lifecycle_state='published' and new.revision=old.revision then return new; end if;
  -- v3 binds a just-created v2 draft to a registered immutable source inside
  -- the same SECURITY DEFINER transaction. No other field/revision may move.
  if old.lifecycle_state='draft' and current_setting('app.static_weekly_source_bind',true)='on' and old.authority_source_id is null and new.authority_source_id is not null and (to_jsonb(new)-'authority_source_id')=(to_jsonb(old)-'authority_source_id') then return new; end if;
  if old.lifecycle_state<>'draft' or current_setting('app.static_weekly_draft_write',true) is distinct from 'on' or new.lifecycle_state<>'draft' or new.revision<>old.revision+1 then raise exception using errcode='23514',message='draft versions require a revision-checked v2 command'; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.tool_commit_cleaning_workflow_authoritative(p_client_session_id text, p_client_completion_id text, p_device_id text, p_location_code text, p_client_started_at text, p_client_ended_at text, p_response_json jsonb, p_scan_evidence jsonb, p_correlation_id text, p_context_id text, p_submission_proof text, p_authenticated_credential_id text, p_native_finish_scan_entry_id text, p_native_completion_attestation_version text, p_native_completion_attestation text, p_native_route_proof_secret text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_completion_id uuid; v_context_id uuid; v_finish_scan_entry_id uuid; v_result jsonb; v_started_at timestamptz; v_completed_at timestamptz;
  v_native_completed_at timestamptz; v_attestation_sha256 text;
begin
  if jsonb_typeof(p_response_json)='object' and not (p_response_json ? 'work_result') then
    if not public.custodial_oc24_legacy_replay_allowed(p_context_id,p_client_session_id,p_client_completion_id,
      p_device_id,p_location_code,p_client_started_at,p_client_ended_at,p_response_json,p_scan_evidence,p_correlation_id) then
      raise exception using errcode='22023',message='explicit work_result required; no exact accepted legacy completion';
    end if;
  else
    perform public.custodial_oc24_assert_completion_selection(p_response_json);
  end if;
  begin
    v_completion_id:=lower(btrim(coalesce(p_client_completion_id,'')))::uuid;
  exception when others then
    raise exception using errcode='22023',message='p_client_completion_id must be a UUID';
  end;
  perform public.custodial_require_native_route_proof_secret(p_native_route_proof_secret);
  if btrim(coalesce(p_native_completion_attestation_version,''))<>'custodial-native-completion.v2'
     or lower(btrim(coalesce(p_native_completion_attestation,''))) !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='42501',message='a verified native completion attestation is required';
  end if;
  begin
    v_context_id:=lower(btrim(p_context_id))::uuid;
    v_finish_scan_entry_id:=lower(btrim(p_native_finish_scan_entry_id))::uuid;
    v_native_completed_at:=btrim(p_client_ended_at)::timestamptz;
  exception when others then
    raise exception using errcode='22023',message='native completion evidence is malformed';
  end;
  if not isfinite(v_native_completed_at) then
    raise exception using errcode='22023',message='native completion evidence is malformed';
  end if;
  if jsonb_typeof(p_scan_evidence)<>'array'
     or (select count(*) from jsonb_array_elements(p_scan_evidence) e where e->>'event_type'='scan_finish')<>1
     or not exists(
       select 1 from jsonb_array_elements(p_scan_evidence) e
       where e->>'event_type'='scan_finish'
         and lower(e->>'client_event_id')=v_finish_scan_entry_id::text
         and e->>'result'='ok'
         and e->>'scanned_at'=public.custodial_canonical_utc_millis(v_native_completed_at)
         and e->'payload_json'->>'entry_source'='native-nfc'
     ) then
    raise exception using errcode='42501',message='the signed physical NFC finish scan is required';
  end if;
  if exists (
    select 1 from public.custodial_offline_actor_contexts c
    where c.context_id=v_context_id and c.native_scan_entry_id=v_finish_scan_entry_id
  ) then
    raise exception using errcode='42501',message='native finish scan must differ from the start scan';
  end if;
  v_attestation_sha256:=encode(extensions.digest(convert_to(lower(btrim(p_native_completion_attestation)),'UTF8'),'sha256'),'hex');
  if exists(
    select 1 from public.custodial_offline_actor_contexts c where c.context_id=v_context_id
      and (c.native_start_attestation_version is distinct from 'custodial-native-start.v1'
        or c.native_scan_entry_id is null
        or (c.native_completion_attestation_version is not null and
          (c.native_completion_attestation_version<>p_native_completion_attestation_version
            or c.native_completion_attestation_sha256<>v_attestation_sha256
            or c.native_completed_at<>v_native_completed_at
            or c.native_finish_scan_entry_id<>v_finish_scan_entry_id)))
  ) then
    raise exception using errcode='23505',message='native completion attestation does not match the frozen occurrence';
  end if;
  v_result:=public.custodial_commit_offline_occurrence(
    p_client_session_id,v_completion_id::text,p_device_id,p_location_code,p_client_started_at,p_client_ended_at,
    p_response_json,p_scan_evidence,p_correlation_id,p_context_id,p_submission_proof,p_authenticated_credential_id,p_backend_execution_secret
  );
  if v_result->>'status'='closed' then
    update public.custodial_offline_actor_contexts
       set native_completion_attestation_version=p_native_completion_attestation_version,
           native_completion_attestation_sha256=v_attestation_sha256,
           native_completed_at=v_native_completed_at,
           native_finish_scan_entry_id=v_finish_scan_entry_id
     where context_id=v_context_id and native_completion_attestation_version is null;
    if not found and not exists(
      select 1 from public.custodial_offline_actor_contexts c
      where c.context_id=v_context_id
        and c.native_completion_attestation_version=p_native_completion_attestation_version
        and c.native_completion_attestation_sha256=v_attestation_sha256
        and c.native_completed_at=v_native_completed_at
        and c.native_finish_scan_entry_id=v_finish_scan_entry_id
    ) then
      raise exception using errcode='23505',message='native completion attestation does not match the frozen occurrence';
    end if;
  end if;
  begin
    v_started_at:=nullif(v_result->>'started_at','')::timestamptz;
    v_completed_at:=nullif(coalesce(v_result->>'completed_at',v_result->>'ended_at'),'')::timestamptz;
  exception when others then
    return v_result||jsonb_build_object('native_completion_attested',v_result->>'status'='closed');
  end;
  return v_result || jsonb_strip_nulls(jsonb_build_object(
    'started_at',public.custodial_canonical_utc_millis(v_started_at),
    'ended_at',public.custodial_canonical_utc_millis(v_completed_at),
    'completed_at',public.custodial_canonical_utc_millis(v_completed_at),
    'native_completion_attested',v_result->>'status'='closed',
    'native_finish_scan_entry_id',case when v_result->>'status'='closed' then v_finish_scan_entry_id end
  ));
end
$function$

CREATE OR REPLACE FUNCTION public.tool_complete_session_authoritative(p_session_uuid text, p_response_json jsonb, p_device_id text, p_client_completion_id text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_session record;
  v_context public.custodial_offline_actor_contexts%rowtype;
  v_existing public.custodial_offline_reconciliation_records%rowtype;
  v_proof text := encode(extensions.gen_random_bytes(32), 'hex');
  v_occurrence_fingerprint text;
  v_assignment_change_id uuid;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select s.*, d.device_id as canonical_device_id, l.location_code, c.credential_id
    into v_session from public.sessions s join public.devices d on d.id=s.device_id join public.locations l on l.id=s.location_id
    join public.device_auth_credentials c on c.credential_id=nullif(lower(btrim(p_authenticated_credential_id)),'')::uuid and c.device_id=s.device_id
   where s.session_uuid=p_session_uuid or s.client_session_id=p_session_uuid
   order by case when s.session_uuid=p_session_uuid then 0 else 1 end limit 1 for update of s;
  if v_session.id is null or upper(btrim(coalesce(p_device_id,'')))<>upper(v_session.canonical_device_id) then
    raise exception using errcode='42501', message='legacy completion is not bound to an authenticated server session';
  end if;
  -- A legacy caller never receives the one-time proof.  Its exact retry is
  -- therefore resolved from the immutable reconciliation record, while any
  -- altered completion id or response is fenced as an identity conflict.
  select * into v_existing from public.custodial_offline_reconciliation_records
    where client_session_id=v_session.client_session_id or client_completion_id=btrim(p_client_completion_id)
    order by case when client_completion_id=btrim(p_client_completion_id) then 0 else 1 end
    limit 1 for update;
  if v_existing.reconciliation_id is not null then
    if v_existing.client_session_id=v_session.client_session_id
       and v_existing.client_completion_id=btrim(p_client_completion_id)
       and v_existing.payload_json=jsonb_build_object('response_json',coalesce(p_response_json,'{}'::jsonb),'scan_evidence','[]'::jsonb) then
      insert into public.custodial_offline_reconciliation_audits(reconciliation_id,event_type,evidence_json)
      values(v_existing.reconciliation_id,'replayed',jsonb_build_object('exact_legacy_adapter_replay',true));
      return v_existing.result_json || jsonb_build_object('reconciliation_id',v_existing.reconciliation_id,'replayed',true);
    end if;
    return public.custodial_quarantine_offline_submission(
      v_session.client_session_id,p_client_completion_id,v_existing.context_id,
      encode(extensions.digest(convert_to(v_session.client_session_id||':'||coalesce(p_client_completion_id,'')||':legacy-conflict','UTF8'),'sha256'),'hex'),
      jsonb_build_object('response_json',coalesce(p_response_json,'{}'::jsonb),'scan_evidence','[]'::jsonb),
      'legacy_adapter_payload_fingerprint_conflict','{}'::jsonb,p_backend_execution_secret);
  end if;
  select * into v_context from public.custodial_offline_actor_contexts where client_session_id=v_session.client_session_id for update;
  if v_context.context_id is null then
    select assignment_change_id into v_assignment_change_id from public.custodial_employee_device_assignment_history
      where device_id=v_session.device_id and new_employee_id=v_session.employee_id order by changed_at desc limit 1;
    if v_assignment_change_id is null then raise exception using errcode='42501', message='legacy completion has no authoritative assignment epoch'; end if;
    v_occurrence_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object('legacy_server_session_id',v_session.id::text,'employee_id',v_session.employee_id::text,'device_id',v_session.device_id::text,'location_id',v_session.location_id::text,'started_at',v_session.started_at,'client_session_id',v_session.client_session_id)::text,'UTF8'),'sha256'),'hex');
    insert into public.custodial_offline_actor_contexts(client_session_id,device_id,employee_id,credential_id,assignment_epoch,assignment_change_id,location_id,canonical_location_code,location_aliases,started_at,occurrence_fingerprint,expires_at)
    select v_session.client_session_id,v_session.device_id,v_session.employee_id,v_session.credential_id,d.assignment_epoch,v_assignment_change_id,v_session.location_id,v_session.location_code,jsonb_build_array(v_session.location_code),v_session.started_at,v_occurrence_fingerprint,now()+interval '7 days'
      from public.devices d where d.id=v_session.device_id
    returning * into v_context;
    insert into public.custodial_offline_submission_proofs(context_id,proof_digest) values(v_context.context_id,encode(extensions.digest(convert_to(v_proof,'UTF8'),'sha256'),'hex'));
  else
    raise exception using errcode='0A000', message='legacy completion must use the existing canonical occurrence adapter';
  end if;
  return public.custodial_commit_offline_occurrence(v_context.client_session_id,p_client_completion_id,v_session.canonical_device_id,v_session.location_code,
    v_context.started_at::text,coalesce(v_session.ended_at,now())::text,coalesce(p_response_json,'{}'::jsonb),'[]'::jsonb,
    'legacy-completion:'||p_client_completion_id,v_context.context_id::text,v_proof,v_context.credential_id::text,p_backend_execution_secret);
end
$function$

CREATE OR REPLACE FUNCTION public.tool_get_offline_scan_authority_snapshot(p_device_id text, p_authenticated_credential_id text, p_backend_execution_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_device record; v_credential public.device_auth_credentials%rowtype;
  v_generated_at timestamptz := date_trunc('milliseconds',clock_timestamp()); v_expires_at timestamptz;
  v_locations jsonb; v_snapshot_id text;
begin
  perform public.custodial_require_backend_execution_secret(p_backend_execution_secret);
  select d.id,d.device_id,d.assigned_employee_id,d.assignment_epoch,e.display_name employee_name,e.active employee_active
    into v_device from public.devices d join public.employees e on e.id=d.assigned_employee_id
   where upper(btrim(d.device_id))=upper(btrim(coalesce(p_device_id,''))) and d.active=true;
  begin
    select * into v_credential from public.device_auth_credentials
     where credential_id=nullif(lower(btrim(coalesce(p_authenticated_credential_id,''))),'')::uuid for share;
  exception when others then
    raise exception using errcode='42501',message='an active authenticated employee-device credential is required';
  end;
  if v_device.id is null or v_device.assigned_employee_id is null or v_device.employee_active is not true
     or v_credential.credential_id is null or v_credential.device_id<>v_device.id or v_credential.confirmed_at is null
     or v_credential.revoked_at is not null or v_credential.expires_at<=v_generated_at then
    raise exception using errcode='42501',message='an active authenticated employee-device assignment is required';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('location_code',l.location_code,'location_name',public.place_operational_location_name(l.id,v_generated_at),
    'location_type',l.location_type,'form_type',coalesce(l.form_type,l.location_type)) order by l.location_code),'[]'::jsonb)
    into v_locations from public.locations l where l.active=true;
  v_expires_at:=date_trunc('milliseconds',least(v_generated_at+interval '24 hours',v_credential.expires_at));
  v_snapshot_id:=encode(extensions.digest(convert_to(jsonb_build_object('contract_version','scan.v4.snapshot-bound-authority',
    'device_id',v_device.device_id,'employee_id',v_device.assigned_employee_id::text,'assignment_epoch',v_device.assignment_epoch,
    'credential_id',v_credential.credential_id::text,'generated_at',public.custodial_canonical_utc_millis(v_generated_at),'expires_at',public.custodial_canonical_utc_millis(v_expires_at),'locations',v_locations)::text,'UTF8'),'sha256'),'hex');
  insert into public.custodial_offline_scan_authority_snapshots(snapshot_id,device_id,employee_id,assignment_epoch,credential_id,generated_at,expires_at,locations_json)
  values(v_snapshot_id,v_device.id,v_device.assigned_employee_id,v_device.assignment_epoch,v_credential.credential_id,v_generated_at,v_expires_at,v_locations)
  on conflict(snapshot_id) do nothing;
  return jsonb_build_object('schema_version','offline-scan-snapshot.v2','contract_version','scan.v4.snapshot-bound-authority',
    'snapshot_id',v_snapshot_id,'canonical_device_id',v_device.device_id,'employee_id',v_device.assigned_employee_id,
    'employee_name',v_device.employee_name,'assignment_epoch',v_device.assignment_epoch,'credential_id',v_credential.credential_id,
    'generated_at',public.custodial_canonical_utc_millis(v_generated_at),'expires_at',public.custodial_canonical_utc_millis(v_expires_at),'locations',v_locations);
end $function$

